package com.cluehelper.guide;

import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.util.Text;

/** Client thread only. The events that end an act, each kept with the tick it was last seen. */
@Singleton
public class ActWatcher
{
	static final int NEVER = Integer.MIN_VALUE;
	private static final String WITHDRAW_LINE = "You withdraw your items from the STASH unit.";
	private static final String DEPOSIT_LINE = "You deposit your items into the STASH unit.";
	private static final String URI = "Uri";
	/** Uri and the double agents appear beside the player who called them. */
	private static final int SPAWN_TILES = 5;
	private static final Set<String> CHALLENGE_ITEMS = Set.of("challenge scroll", "puzzle box", "light box");

	private final Client client;
	private final PlayerModel player;
	private int withdrawTick = NEVER;
	private int depositTick = NEVER;
	private int uriTick = NEVER;
	private int challengeTick = NEVER;
	private int enemyTick = NEVER;
	private NPC enemy;
	private boolean inventoryChanged = true;
	private boolean challengeCarried;

	@Inject
	ActWatcher(Client client, PlayerModel player)
	{
		this.client = client;
		this.player = player;
	}

	public void onChatMessage(ChatMessage message)
	{
		if (message.getType() != ChatMessageType.GAMEMESSAGE && message.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String text = Text.removeTags(message.getMessage());
		if (WITHDRAW_LINE.equals(text))
		{
			withdrawTick = client.getTickCount();
		}
		else if (DEPOSIT_LINE.equals(text))
		{
			depositTick = client.getTickCount();
		}
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			inventoryChanged = true;
		}
	}

	/** Call once per tick with the step being guided. */
	void onGameTick(Step step)
	{
		int tick = client.getTickCount();
		if (inventoryChanged)
		{
			inventoryChanged = false;
			boolean carried = carriesChallengeItem();
			if (carried && !challengeCarried)
			{
				challengeTick = tick;
			}
			challengeCarried = carried;
		}
		Player local = client.getLocalPlayer();
		WorldPoint at = local == null ? null : local.getWorldLocation();
		if (at == null || client.getTopLevelWorldView() == null)
		{
			return;
		}
		Set<Integer> enemies = enemyIds(step);
		NPC near = null;
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			boolean beside = npc.getWorldLocation().distanceTo2D(at) <= SPAWN_TILES;
			if (beside && URI.equals(npc.getName()))
			{
				uriTick = tick;
			}
			if (beside && enemies.contains(npc.getId()) && !npc.isDead())
			{
				near = npc;
			}
		}
		enemy = near;
		if (near != null)
		{
			enemyTick = tick;
		}
	}

	/** Items came out of a STASH unit since {@code since} and none went back in after. */
	boolean holdsStashItems(int since)
	{
		return withdrawTick >= since && withdrawTick > depositTick;
	}

	/** Only the ends this watcher sees as events; the guide checks the others against what the player carries. */
	boolean isDone(SubStep.Done done, int since)
	{
		switch (done)
		{
			case STASH_WITHDRAWN:
				return withdrawTick >= since;
			case STASH_DEPOSITED:
				return depositTick >= since;
			case URI_HERE:
				return uriTick >= since;
			case CHALLENGE_ITEM:
				return challengeTick >= since || challengeCarried;
			case STEP_CHANGES:
			case EQUIPPED:
			case ITEM_CARRIED:
			case ITEM_GONE:
			case WAY_IN_WORN:
			case GEAR_WORN:
			case SLOTS_EMPTY:
			case ITEM_HELD:
				return false;
			default:
				throw new IllegalArgumentException("unhandled act end " + done);
		}
	}

	/** The double agent, wizard or guard attacking now; null when none is near. */
	NPC getEnemy()
	{
		return enemy;
	}

	boolean foughtSince(int tick)
	{
		return enemyTick >= tick && enemy == null;
	}

	private static Set<Integer> enemyIds(Step step)
	{
		StepIndex.Entry data = step == null ? null : step.getData();
		if (data == null)
		{
			return Set.of();
		}
		Set<Integer> ids = new HashSet<>();
		data.getCombat().forEach(combat -> ids.addAll(combat.getNpcs()));
		return ids;
	}

	private boolean carriesChallengeItem()
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		return snapshot != null && snapshot.getInventory().keySet().stream()
			.anyMatch(id -> CHALLENGE_ITEMS.contains(client.getItemDefinition(id).getName().toLowerCase()));
	}
}

package com.cluehelper.guide;

import com.cluehelper.step.ClueTypes;
import com.cluehelper.step.EmptySlots;
import com.cluehelper.step.SpadeNeed;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * What to do once at the step, per type: the sub-steps after the travel. Texts name what core doesn't show in the same
 * words (the emotes in order, the hand-in) and point to core for the rest; highlights stay core's.
 */
final class Acts
{
	private static final String STAY_EQUIPPED = "Stay equipped until Uri is done";
	private static final String TALK_OPTION = "Talk-to";
	private static final Set<String> TYPES_WITH_OWN_ACT = Set.of(ClueTypes.EMOTE, ClueTypes.MUSIC, ClueTypes.HOT_COLD, ClueTypes.SKILL);

	private Acts()
	{
	}

	/**
	 * Gear the act wants worn (Robin's +180 ranged attack) goes on first; a step of several places wears it per stage.
	 *
	 * @param takeFromStash the step's items are in its STASH unit and not on the player
	 */
	static List<SubStep> of(Step step, boolean takeFromStash)
	{
		List<String> worn = !step.getStages().isEmpty() ? List.of() : step.getData().getWornNeeds();
		List<SubStep> acts = actsOf(step, takeFromStash);
		if (worn.isEmpty())
		{
			return acts;
		}
		List<SubStep> equipped = new ArrayList<>(SubSteps.equip(worn));
		equipped.addAll(acts);
		return List.copyOf(equipped);
	}

	/** The step's one act: its marker's act, a key search, or what its type does. */
	static SubStep act(Step step)
	{
		if (step.getWaypointAct() != null)
		{
			return SubStep.builder().kind(SubStep.Kind.ACT).text(step.getWaypointAct())
				.waypoint(step.isActAnywhere() ? null : step.getTargets().get(0))
				.actItems(step.getActItems()).build();
		}
		if (needsItemFromNpc(step))
		{
			String what = hasAny(step.getObjectNames()) ? "the " + step.getObjectNames().get(0).toLowerCase() : "it";
			return SubStep.builder().kind(SubStep.Kind.ACT).text("Search " + what + " with the key")
				.detail("The key comes from " + step.getNpcs().get(0)).build();
		}
		SubStep.SubStepBuilder act = SubStep.builder().kind(SubStep.Kind.ACT).text(actText(step));
		String npc = talkedTo(step);
		return npc == null ? act.build() : act.option(TALK_OPTION).npcNames(Set.of(MenuLabels.normalise(npc))).build();
	}

	/** The NPC the step's own act talks to; null for a step whose act is something else. */
	private static String talkedTo(Step step)
	{
		boolean ownAct = TYPES_WITH_OWN_ACT.contains(step.getType());
		return !ownAct && !isDig(step) && hasAny(step.getNpcs()) ? step.getNpcs().get(0) : null;
	}

	/**
	 * In core's cryptics naming both an NPC and an object, the NPC holds the key the object needs, except Juna's "speak to
	 * the guardian".
	 */
	private static boolean needsItemFromNpc(Step step)
	{
		boolean talk = step.getText() != null && step.getText().toLowerCase().contains("speak");
		return ClueTypes.CRYPTIC.equals(step.getType()) && !talk && hasAny(step.getNpcs())
			&& (hasAny(step.getObjectNames()) || hasAny(step.getObjectIds()));
	}

	private static boolean hasAny(List<?> list)
	{
		return list != null && !list.isEmpty();
	}

	private static String actText(Step step)
	{
		String type = step.getType() == null ? "" : step.getType();
		switch (type)
		{
			case ClueTypes.EMOTE:
				return "Perform the emote";
			case ClueTypes.MUSIC:
				return "Talk to Cecilia";
			case ClueTypes.HOT_COLD:
				return "Feel the device, then dig";
			case ClueTypes.SKILL:
				return "Do the challenge";
			default:
				break;
		}
		if (isDig(step))
		{
			return "Dig";
		}
		if (hasAny(step.getNpcs()))
		{
			return "Talk to " + step.getNpcs().get(0);
		}
		if (hasAny(step.getObjectNames()))
		{
			return "Search the " + step.getObjectNames().get(0).toLowerCase();
		}
		if (hasAny(step.getObjectIds()))
		{
			return "Search it";
		}
		return "Do the clue step";
	}

	private static List<SubStep> actsOf(Step step, boolean takeFromStash)
	{
		SubStep main = act(step);
		if (step.getWaypointAct() != null)
		{
			return List.of(main);
		}
		String type = step.getType() == null ? "" : step.getType();
		switch (type)
		{
			case ClueTypes.EMOTE:
				return emote(step, takeFromStash);
			case ClueTypes.MUSIC:
				return List.of(music(step));
			case ClueTypes.FALO:
				return List.of(act("Talk to Falo the Bard", "With the item the Clue Scroll plugin lists"));
			case ClueTypes.SKILL:
				return List.of(handIn(step));
			default:
				break;
		}
		StepIndex.Entry data = step.getData();
		StepIndex.Target kill = data == null ? null : data.getTargets().stream()
			.filter(target -> target.getKind() == StepIndex.Target.Kind.KILL).findFirst().orElse(null);
		if (kill != null)
		{
			return List.of(act(kill.getText() != null ? kill.getText() : "Kill the monster", area(data)));
		}
		if (isDig(step))
		{
			return List.of(main.toBuilder().text("Dig").detail(withFloor(step, note(step))).fights(fightsFor(step)).again("Dig again").build());
		}
		if (data != null && data.getChallenge() != null && step.getNpcs() != null && !step.getNpcs().isEmpty())
		{
			return talkThenChallenge(step, data.getChallenge());
		}
		return List.of(main.toBuilder().detail(withFloor(step, main.getDetail())).build());
	}

	private static List<SubStep> emote(Step step, boolean takeFromStash)
	{
		List<SubStep> acts = new ArrayList<>();
		WorldPoint stash = takeFromStash ? SubSteps.stashTile(step) : null;
		boolean items = step.getRequirements() != null && !step.getRequirements().getItems().isEmpty();
		acts.addAll(items ? SubSteps.remove(EmptySlots.of(step.getRequirements().getItems())) : List.of());
		acts.addAll(takeFromStash ? fromStash(step) : items ? List.of(equip()) : List.of());
		WorldPoint spot = step.getTargets().isEmpty() ? null : step.getTargets().get(0);
		if (stash != null && spot != null)
		{
			acts.add(SubStep.builder().kind(SubStep.Kind.WALK_TO_CLUE).text("Walk to the clue")
				.goal(spot).radius(SubSteps.ARRIVE_TILES).build());
		}
		String emotes = step.getEmotes().isEmpty() ? "the emote" : String.join(", then ", step.getEmotes());
		acts.add(SubStep.builder().kind(SubStep.Kind.ACT).text("Perform " + emotes).detail(items ? STAY_EQUIPPED : null)
			.done(SubStep.Done.URI_HERE).fights(fightsFor(step)).again("Perform " + emotes + " again").tab(StepGuide.Tab.EMOTES).build());
		acts.add(SubStep.builder().kind(SubStep.Kind.ACT).text("Talk to Uri").detail(items ? "Stay equipped" : null).build());
		return List.copyOf(acts);
	}

	/** Take the items out of the STASH unit and put them on. */
	static List<SubStep> fromStash(Step step)
	{
		SubStep take = SubStep.builder().kind(SubStep.Kind.ACT).text("Search the STASH unit: take the items")
			.detail("Then equip them").done(SubStep.Done.STASH_WITHDRAWN).build();
		boolean items = step.getRequirements() != null && !step.getRequirements().getItems().isEmpty();
		return items ? List.of(take, equip()) : List.of(take);
	}

	private static SubStep equip()
	{
		return SubStep.builder().kind(SubStep.Kind.ACT).text("Equip the items").detail("The Clue Scroll plugin lists them")
			.done(SubStep.Done.EQUIPPED).tab(StepGuide.Tab.INVENTORY).build();
	}

	private static SubStep music(Step step)
	{
		StepIndex.Music music = step.getData().getMusic();
		String track = music != null && music.getTrack() != null ? music.getTrack() : step.getText();
		String unlock = music == null || music.getUnlock() == null ? null : "Unlocked: " + music.getUnlock();
		return act("Talk to Cecilia, then play " + track, unlock == null ? "Music tab" : "Music tab. " + unlock).toBuilder()
			.tab(StepGuide.Tab.MUSIC).build();
	}

	private static SubStep handIn(Step step)
	{
		boolean charlie = "beginner".equals(step.getTier());
		return act(charlie ? "Give Charlie the item" : "Talk to Sherlock", charlie ? "He wants what the clue names" : "Task done: hand it in");
	}

	private static List<SubStep> talkThenChallenge(Step step, StepIndex.Challenge challenge)
	{
		String npc = step.getNpcs().get(0);
		SubStep talk = SubStep.builder().kind(SubStep.Kind.ACT).text("Talk to " + npc).detail(withFloor(step, null))
			.done(SubStep.Done.CHALLENGE_ITEM).build();
		if (challenge.getBox() != null)
		{
			String box = challenge.getBox().toLowerCase().contains("light") ? "light box" : "puzzle box";
			return List.of(talk, act("Open the " + box + ", then talk to " + npc + " again", null).toBuilder().actItemNamed(box).build());
		}
		return List.of(talk, act("Talk to " + npc + " again: answer the challenge", null));
	}

	private static SubStep act(String text, String detail)
	{
		return SubStep.builder().kind(SubStep.Kind.ACT).text(text).detail(detail).build();
	}

	private static boolean isDig(Step step)
	{
		return step.getRequirements() != null && step.getRequirements().getSpade() != SpadeNeed.NONE;
	}

	private static boolean fightsFor(Step step)
	{
		return !step.getData().getCombat().isEmpty();
	}

	private static String note(Step step)
	{
		return step.getData().getNote();
	}

	private static String area(StepIndex.Entry data)
	{
		return data.getArea() == null ? null : data.getArea().getText();
	}

	/**
	 * Core's tile can be on another floor than the NPC (Donovan upstairs, the cache's tile on floor 1): hand data says
	 * so, else the cache's plane does.
	 */
	private static String withFloor(Step step, String detail)
	{
		String floor = step.getData().getFloor();
		if (floor == null && !step.getTargets().isEmpty())
		{
			int corePlane = step.getTargets().get(0).getPlane();
			for (WorldPoint other : step.getOtherTiles())
			{
				if (other.getPlane() > corePlane && other.distanceTo2D(step.getTargets().get(0)) <= SubSteps.AREA_ARRIVE_TILES)
				{
					floor = other.getPlane() == 1 ? "Upstairs: first floor" : "Upstairs: floor " + other.getPlane();
				}
			}
		}
		if (floor == null)
		{
			return detail;
		}
		return detail == null ? floor : floor + ". " + detail;
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.Book;

/** Client thread only. A refused book change leaves the book as it was; the next tick shows whether it changed. */
final class ChangeRefusal
{
	private static final int CHECK_TICKS = 2;

	private String candidate;
	private Book book;
	private int checkTick;

	/** A MESBOX line during the change: the change is suspect until its check tick. */
	void suspect(String change, Book book, int tick)
	{
		candidate = change;
		this.book = book;
		checkTick = tick + CHECK_TICKS;
	}

	/** The change the game refused, once its check tick has come and the book is not the one it changes to; null otherwise. */
	String refused(int tick, int spellbookVarbit)
	{
		if (candidate == null || tick < checkTick)
		{
			return null;
		}
		String refused = spellbookVarbit != book.ordinal() ? candidate : null;
		candidate = null;
		return refused;
	}

	void clear()
	{
		candidate = null;
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.PositionRules;
import com.cluehelper.step.StepRequirements;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Client thread only. After an emote step whose items came out of its STASH unit, they go back before moving on; the
 * reminder outlives the step and ends on the deposit line, or 15 tiles away once the player has been back by the unit
 * (the Agility Pyramid's emote is done on top, its unit stands at the foot).
 */
@Singleton
final class DepositReminder
{
	private static final int DEPOSIT_TILES = 15;

	private final ActWatcher actWatcher;
	private Pending pending;
	private boolean beenNear;

	@Inject
	DepositReminder(ActWatcher actWatcher)
	{
		this.actWatcher = actWatcher;
	}

	/** The unit to put the items back into; null when nothing is owed. */
	WorldPoint getAt()
	{
		return pending == null ? null : pending.getAt();
	}

	int getStashId()
	{
		return pending == null ? StepRequirements.NO_STASH : pending.getStashId();
	}

	void start(WorldPoint at, int stashId, List<String> items, int tick)
	{
		pending = new Pending(at, tick, stashId, items);
		beenNear = false;
	}

	void onGameTick(WorldPoint tile)
	{
		if (pending == null || tile == null)
		{
			return;
		}
		boolean deposited = actWatcher.isDone(SubStep.Done.STASH_DEPOSITED, pending.getSince());
		boolean near = PositionRules.near(tile, pending.getAt(), DEPOSIT_TILES);
		beenNear |= near;
		if (deposited || beenNear && !near)
		{
			pending = null;
		}
	}

	/** The walk back to the unit and the deposit, before {@code base}, while the items are owed. */
	List<SubStep> before(List<SubStep> base, WorldPoint tile)
	{
		if (pending == null || tile == null)
		{
			return base;
		}
		List<SubStep> all = new ArrayList<>();
		all.add(SubStep.builder().kind(SubStep.Kind.WALK).text("Walk to the STASH unit").waypoint(pending.getAt()).goal(pending.getAt())
			.radius(SubSteps.ARRIVE_TILES).done(SubStep.Done.STASH_DEPOSITED).build());
		all.add(SubStep.builder().kind(SubStep.Kind.ACT).text("Search the STASH unit: put back the " + String.join(" and ", pending.getItems()))
			.detail("Before moving on").done(SubStep.Done.STASH_DEPOSITED).build());
		all.addAll(base);
		return List.copyOf(all);
	}

	void clear()
	{
		pending = null;
		beenNear = false;
	}

	@Value
	private static class Pending
	{
		WorldPoint at;
		int since;
		int stashId;
		/** The STASH items the player still carries, to put back. */
		List<String> items;
	}
}

package com.cluehelper.guide;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
public class FairyDials
{
	private static final int COUNT = 3;
	private static final int LETTERS_PER_DIAL = 4;
	private static final String LETTERS = "ABCDIJKLPQRS";
	private static final int[] VARBITS = {VarbitID.FAIRYRING_1, VarbitID.FAIRYRING_2, VarbitID.FAIRYRING_3};
	/**
	 * A dial's four letter widgets share one box on its hub and the game turns each letter's model into place, so a
	 * mushroom is found from the hub by its clockwise turns to the front: front, right, top, left.
	 */
	private static final Point[] MUSHROOM_OFFSETS = {new Point(0, 48), new Point(49, -1), new Point(0, -49), new Point(-49, -1)};
	/** The front mushroom only shows through a hole in the plank. */
	private static final int[] MUSHROOM_RADII = {21, 31, 31, 31};

	private final Client client;

	@Inject
	FairyDials(Client client)
	{
		this.client = client;
	}

	public List<Shape> shapes(String code)
	{
		List<Shape> out = new ArrayList<>();
		String letters = letters(code);
		for (int dial = 0; letters != null && dial < COUNT; dial++)
		{
			char letter = letters.charAt(dial);
			Widget hub = client.getWidget(InterfaceID.Fairyrings.A + LETTERS.indexOf(letter));
			if (Widgets.visible(hub))
			{
				out.add(mushroom(hub.getBounds(), turnsToFront(dial, letter)));
			}
		}
		return out;
	}

	boolean isDialled(String code)
	{
		String letters = letters(code);
		for (int dial = 0; letters != null && dial < COUNT; dial++)
		{
			if (turnsToFront(dial, letters.charAt(dial)) != 0)
			{
				return false;
			}
		}
		return letters != null;
	}

	static String letters(String code)
	{
		String letters = code == null ? "" : code.replaceAll("[^A-Za-z]", "").toUpperCase();
		if (letters.length() != COUNT)
		{
			return null;
		}
		for (int dial = 0; dial < COUNT; dial++)
		{
			if (varbitWithLetterAtFront(dial, letters.charAt(dial)) < 0)
			{
				return null;
			}
		}
		return letters;
	}

	/** The travel log lists every code alphabetically, starting at AIP. */
	static int logIndex(String letters)
	{
		int index = 0;
		for (int dial = 0; dial < COUNT; dial++)
		{
			index = index * LETTERS_PER_DIAL + LETTERS.indexOf(letters.charAt(dial)) - dial * LETTERS_PER_DIAL;
		}
		return index;
	}

	/**
	 * Each dial's varbit counts its letters in the order they reach the front turning clockwise: A, D, C, B (I, L, K, J;
	 * P, S, R, Q). -1 when the letter isn't on that dial.
	 */
	private static int varbitWithLetterAtFront(int dial, char letter)
	{
		int onDial = LETTERS.indexOf(letter) - dial * LETTERS_PER_DIAL;
		return onDial < 0 || onDial >= LETTERS_PER_DIAL ? -1 : (LETTERS_PER_DIAL - onDial) % LETTERS_PER_DIAL;
	}

	private int turnsToFront(int dial, char letter)
	{
		return Math.floorMod(varbitWithLetterAtFront(dial, letter) - client.getVarbitValue(VARBITS[dial]), LETTERS_PER_DIAL);
	}

	private static Shape mushroom(Rectangle hub, int turnsToFront)
	{
		Point offset = MUSHROOM_OFFSETS[turnsToFront];
		int radius = MUSHROOM_RADII[turnsToFront];
		return new Ellipse2D.Double(hub.getCenterX() + offset.x - radius, hub.getCenterY() + offset.y - radius, 2 * radius, 2 * radius);
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.GearPicker;
import com.cluehelper.route.GearRequirement;
import com.cluehelper.route.RequiredItems;
import com.cluehelper.route.StepNeeds;
import com.cluehelper.step.EmptySlots;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.plugins.cluescrolls.clues.item.AllRequirementsCollection;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/** Acts that put gear on or take it off: what to change now, from what is carried and worn, and when it is done. */
@Singleton
final class GearActs
{
	private static final String EQUIP_TEXT = "Equip:";

	private final Client client;
	private final PlayerModel player;
	private final StepNeeds stepNeeds;

	@Inject
	GearActs(Client client, PlayerModel player, StepNeeds stepNeeds)
	{
		this.client = client;
		this.player = player;
		this.stepNeeds = stepNeeds;
	}

	/** A gear act as the pieces to put on or take off now; any other sub-step, or one there is no step for, as it is. */
	SubStep refresh(SubStep act, Step step)
	{
		switch (act.getDone())
		{
			case WAY_IN_WORN:
				return step == null ? act : equipWhatIsCarried(act, step);
			case GEAR_WORN:
				return step == null ? act : equipGear(act, step);
			case SLOTS_EMPTY:
				return removeGear(act);
			default:
				return act;
		}
	}

	/** For an act done by {@link SubStep.Done#EQUIPPED}, {@code WAY_IN_WORN}, {@code GEAR_WORN} or {@code SLOTS_EMPTY}. */
	boolean isDone(SubStep act, Step step)
	{
		switch (act.getDone())
		{
			case EQUIPPED:
				return wearsStepItems(step);
			case WAY_IN_WORN:
				return wearsWayInGear(step);
			case GEAR_WORN:
				return step != null && wearsGear(act, step);
			case SLOTS_EMPTY:
				return act.getEmptied().stream().allMatch(requirement -> requirement.fulfilledBy(wornBySlot()));
			default:
				throw new IllegalArgumentException("not a gear act: " + act.getDone());
		}
	}

	/**
	 * The way in's gear as carried: one item that covers every requirement (the Medallion of the Deep) when the player
	 * has it, else per requirement the item they carry.
	 */
	private SubStep equipWhatIsCarried(SubStep act, Step step)
	{
		List<StepIndex.Requires> worn = step.getData().getRequires().stream().filter(StepIndex.Requires::isWear)
			.collect(Collectors.toList());
		Set<Integer> carried = player.carriedIds();
		Integer coversAll = worn.get(0).getIds().stream().filter(carried::contains)
			.filter(id -> worn.stream().allMatch(need -> need.getIds().contains(id))).findFirst().orElse(null);
		List<Integer> chosen = coversAll != null ? List.of(coversAll) : worn.stream()
			.map(need -> need.getIds().stream().filter(carried::contains).findFirst().orElse(need.getIds().get(0)))
			.distinct().collect(Collectors.toList());
		return equipping(act, chosen);
	}

	/** The gear a part's act wants, from what is carried: the fewest pieces to put on, listed by name. */
	private SubStep equipGear(SubStep act, Step step)
	{
		Set<Integer> worn = player.wornIds();
		Set<Integer> inventory = player.inventoryIds();
		List<Integer> chosen = wornNeeds(act, step).stream().flatMap(need -> toEquip(need.getRequirement(), worn, inventory).stream())
			.distinct().collect(Collectors.toList());
		return chosen.isEmpty() ? act : equipping(act, chosen);
	}

	/** The worn items an act wants off, refreshed as each comes off. */
	private SubStep removeGear(SubStep act)
	{
		Item[] worn = wornBySlot();
		Set<Integer> off = Arrays.stream(EquipmentInventorySlot.values())
			.filter(slot -> slot.getSlotIdx() < worn.length && worn[slot.getSlotIdx()].getId() != -1)
			.filter(slot -> act.getEmptied().stream().anyMatch(requirement -> !EmptySlots.allows(requirement, slot,
				worn[slot.getSlotIdx()].getId())))
			.map(slot -> worn[slot.getSlotIdx()].getId())
			.collect(Collectors.toUnmodifiableSet());
		return act.toBuilder().actItems(off).build();
	}

	private SubStep equipping(SubStep act, List<Integer> itemIds)
	{
		List<String> names = itemIds.stream().map(id -> client.getItemDefinition(id).getName()).collect(Collectors.toList());
		return act.toBuilder().text(EQUIP_TEXT).items(names).actItems(Set.copyOf(itemIds)).build();
	}

	private boolean wearsStepItems(Step step)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		return step != null && step.getRequirements() != null && snapshot != null
			&& step.getRequirements().itemsFulfilledBy(PlayerSnapshot.items(snapshot.getWorn()));
	}

	private boolean wearsWayInGear(Step step)
	{
		if (step == null)
		{
			return true;
		}
		Set<Integer> on = player.wornIds();
		return step.getData().getRequires().stream().filter(StepIndex.Requires::isWear)
			.allMatch(need -> need.getIds().stream().anyMatch(on::contains));
	}

	private boolean wearsGear(SubStep act, Step step)
	{
		Set<Integer> worn = player.wornIds();
		return wornNeeds(act, step).stream().allMatch(need -> need.getRequirement() instanceof GearRequirement
			? ((GearRequirement) need.getRequirement()).isWorn(worn) : need.getRequirement().fulfilledBy(PlayerSnapshot.oneOfEach(worn)));
	}

	private List<RequiredItems.Need> wornNeeds(SubStep act, Step step)
	{
		return stepNeeds.of(step).getNeeds().stream().filter(need -> act.getWornNeeds().contains(need.getName()))
			.collect(Collectors.toList());
	}

	private static List<Integer> toEquip(ItemRequirement requirement, Set<Integer> worn, Set<Integer> inventory)
	{
		if (requirement instanceof GearRequirement)
		{
			return ((GearRequirement) requirement).choose(worn, inventory, Set.of()).map(GearPicker.Choice::getEquip).orElse(List.of());
		}
		if (requirement.fulfilledBy(PlayerSnapshot.oneOfEach(worn)))
		{
			return List.of();
		}
		List<Integer> fitting = inventory.stream().filter(requirement::fulfilledBy).sorted().collect(Collectors.toList());
		boolean outfit = requirement instanceof AllRequirementsCollection;
		return outfit || fitting.isEmpty() ? fitting : List.of(fitting.get(0));
	}

	private Item[] wornBySlot()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		return worn == null ? new Item[0] : worn.getItems();
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.ItemUse;
import java.util.List;
import java.util.Set;
import lombok.Builder;
import lombok.Value;

/** What the overlays mark for the current sub-step, as one value: {@link #NONE} marks nothing. */
@Value
@Builder(toBuilder = true)
class Highlights
{
	static final Highlights NONE = Highlights.builder().build();

	/** Carried or worn items to outline. */
	@Builder.Default
	Set<Integer> items = Set.of();
	/** Outlined items whose left click does what the step needs. */
	@Builder.Default
	Set<Integer> fillItems = Set.of();
	/** Bank items to outline; the huntsman's kit stands for an item only it holds. */
	@Builder.Default
	Set<Integer> bankItems = Set.of();
	@Builder.Default
	int spellWidget = -1;
	/** A scroll book entry, or {@link ScrollBook#NO_WIDGET}. */
	@Builder.Default
	int menuWidget = ScrollBook.NO_WIDGET;
	@Builder.Default
	StepGuide.Tab tab = StepGuide.Tab.NONE;
	@Builder.Default
	MenuTarget menuTarget = MenuTarget.NONE;
	/** The current sub-step's own object or NPC with its option ("Search for traps"), for colouring its menu line. */
	@Builder.Default
	MenuTarget optionTarget = MenuTarget.NONE;
	/** The teleport's held items, for the fill once their left click is learned. */
	@Builder.Default
	List<ItemUse> heldUses = List.of();
	/** The menu label a one-click teleport goes to; null for none. */
	String oneClickLabel;
	/** An outlined object is filled when its left click is this option (a STASH unit's "Search"); null for teleports. */
	String objectOption;
}

package com.cluehelper.guide;

import com.cluehelper.player.Container;
import com.cluehelper.player.ItemUse;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;

/**
 * What a left click on an item, object or NPC does, Menu Entry Swapper's swaps included. Learned from the hover menu's
 * top entry once the mouse has been over it; before that, read from Menu Entry Swapper's config, else the first action.
 * Client thread only.
 */
@Singleton
public final class LeftClicks
{
	private static final String ITEM = "item:";
	private static final String WORN = "worn:";
	private static final String WORN_ID = "wornid:";
	private static final int SLOT_ITEM_CHILD = 1;
	private static final String OBJECT = "object:";
	private static final String NPC = "npc:";
	private static final String BANK = "bank:";
	private static final String WITHDRAW_OPTION = "Withdraw";
	private static final Set<MenuAction> NPC_OPTIONS = EnumSet.of(MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION,
		MenuAction.NPC_THIRD_OPTION, MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION);
	private static final Set<MenuAction> OBJECT_OPTIONS = EnumSet.of(MenuAction.GAME_OBJECT_FIRST_OPTION,
		MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION, MenuAction.GAME_OBJECT_FOURTH_OPTION,
		MenuAction.GAME_OBJECT_FIFTH_OPTION);
	private static final Set<String> WEAR_OPTIONS = Set.of("Wear", "Wield", "Equip", "Hold");
	private static final String USE_OPTION = "Use";
	private static final String REMOVE_OPTION = "Remove";

	private final Client client;
	private final SwapperClicks swapperClicks;
	private final Map<String, String> learned = new HashMap<>();

	@Inject
	LeftClicks(Client client, SwapperClicks swapperClicks)
	{
		this.client = client;
		this.swapperClicks = swapperClicks;
	}

	/** @return whether the left click learned is new */
	boolean learn(MenuEntry hoverMenuTop)
	{
		String key = key(hoverMenuTop);
		String option = hoverMenuTop.getOption();
		return key != null && option != null && !option.equals(learned.put(key, option));
	}

	String swappedOrLearned(ItemUse use)
	{
		return use.getContainer() == Container.WORN ? worn(use.getItemId()) : carried(use.getItemId());
	}

	/** Before a hover, a carried item no swap applies to left-clicks its first inventory action. */
	String item(ItemUse use)
	{
		return use.getContainer() == Container.WORN ? worn(use.getItemId()) : item(use.getItemId());
	}

	String item(int itemId)
	{
		String known = carried(itemId);
		return known != null ? known : firstAction(client.getItemDefinition(itemId).getInventoryActions());
	}

	boolean wears(int itemId)
	{
		String click = item(itemId);
		return click != null && WEAR_OPTIONS.contains(click);
	}

	/** A worn item's left click takes it off, as it does unless a swap or the item itself says otherwise. */
	boolean removes(int wornItemId)
	{
		String click = worn(wornItemId);
		return click == null || REMOVE_OPTION.equalsIgnoreCase(MenuLabels.normalise(click));
	}

	/** A task's item does the act on a left click when it is put on or used on another (a tinderbox, a herb). */
	boolean wearsOrUses(int itemId)
	{
		String click = item(itemId);
		return click != null && (WEAR_OPTIONS.contains(click) || USE_OPTION.equals(click));
	}

	/** A bank item's left click withdraws it, whatever the quantity, unless the bank hands out notes. */
	public boolean withdraws(int bankItemId)
	{
		String known = learned.get(BANK + bankItemId);
		boolean withdrawClick = known == null || known.startsWith(WITHDRAW_OPTION);
		return withdrawClick && client.getVarbitValue(VarbitID.BANK_WITHDRAWNOTES) == 0;
	}

	String object(TileObject object)
	{
		String known = learned.get(OBJECT + object.getId());
		if (known != null)
		{
			return known;
		}
		ObjectComposition definition = client.getObjectDefinition(object.getId());
		String swapped = swapperClicks.object(definition);
		return swapped != null ? swapped : defaultClick(definition);
	}

	public boolean isLeftClick(TileObject object, String option)
	{
		String click = object(object);
		return click != null && click.equalsIgnoreCase(option);
	}

	/** Learned from the hover menu, else the NPC's first option. */
	String npc(NPC npc)
	{
		String known = learned.get(NPC + npc.getId());
		if (known != null)
		{
			return known;
		}
		NPCComposition definition = npc.getTransformedComposition();
		return definition == null ? null : firstAction(definition.getActions());
	}

	private String carried(int itemId)
	{
		String known = learned.get(ITEM + itemId);
		return known != null ? known : swapperClicks.item(itemId);
	}

	/**
	 * Worn items' options carry only the item name as the target, and a left click Menu Entry Swapper put on top (the Max
	 * cape's "Home") carries neither, so the slot's item id is the fallback key.
	 */
	private String worn(int itemId)
	{
		String byName = learned.get(WORN + MenuLabels.normalise(client.getItemDefinition(itemId).getName()));
		String known = byName != null ? byName : learned.get(WORN_ID + itemId);
		return known != null ? known : swapperClicks.worn(itemId);
	}

	/** The house settings put the jewellery box's and nexus' left-click destination on their varbit-picked form. */
	private static String defaultClick(ObjectComposition object)
	{
		ObjectComposition shown = object.getImpostorIds() != null ? object.getImpostor() : object;
		return shown == null ? null : firstAction(shown.getActions());
	}

	private static String firstAction(String[] actions)
	{
		if (actions == null)
		{
			return null;
		}
		for (String action : actions)
		{
			if (action != null)
			{
				return action;
			}
		}
		return null;
	}

	private static String key(MenuEntry entry)
	{
		Widget widget = entry.getWidget();
		int group = widget == null ? -1 : WidgetUtil.componentToInterface(widget.getId());
		if (group == InterfaceID.INVENTORY && entry.getItemId() > 0)
		{
			return ITEM + entry.getItemId();
		}
		if (group == InterfaceID.BANKMAIN && entry.getItemId() > 0)
		{
			return BANK + entry.getItemId();
		}
		if (group == InterfaceID.WORNITEMS && entry.getTarget() != null && !entry.getTarget().isEmpty())
		{
			return WORN + MenuLabels.normalise(entry.getTarget());
		}
		if (group == InterfaceID.WORNITEMS)
		{
			int slotItem = slotItem(widget);
			return slotItem > 0 ? WORN_ID + slotItem : null;
		}
		if (NPC_OPTIONS.contains(entry.getType()) && entry.getNpc() != null)
		{
			return NPC + entry.getNpc().getId();
		}
		return OBJECT_OPTIONS.contains(entry.getType()) ? OBJECT + entry.getIdentifier() : null;
	}

	private static int slotItem(Widget slot)
	{
		if (slot.getItemId() > 0)
		{
			return slot.getItemId();
		}
		Widget item = slot.getChild(SLOT_ITEM_CHILD);
		return item == null ? -1 : item.getItemId();
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.Book;
import com.cluehelper.player.Container;
import com.cluehelper.player.HouseState;
import com.cluehelper.player.ItemUse;
import com.cluehelper.route.Exit;
import com.cluehelper.route.Leg;
import com.cluehelper.route.Route;
import com.cluehelper.step.Stage;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import com.cluehelper.step.TargetKind;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.Category;
import com.cluehelper.transport.SpellbookChange;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/** The sub-step for each kind of route leg: what it says, where it leads and where it lands. */
final class LegSteps
{
	/** A feel's information depends on its exact tile, so the walk ends on the marker. */
	private static final int PROBE_ARRIVE_TILES = 0;
	private static final String FAIRY_RING_PREFIX = "Fairy ring";
	private static final String TALK_TO = "Talk to";
	private static final String NPC_MENU = "npc ";
	private static final Map<Category, String> RIDE_PLACES = Map.of(Category.BOAT, "the boat", Category.CANOE,
		"the canoe station", Category.MINECART, "the minecart", Category.LEVER, "the lever", Category.BALLOON,
		"the balloon basket", Category.MUSHTREE, "the mushtree", Category.WILDERNESS_OBELISK, "the obelisk");
	private static final Pattern LIST_HOTKEY = Pattern.compile("^([0-9A-Z])[.:] ");
	private static final Pattern CLICK_NOTE = Pattern.compile(" \\((left|right)-click\\)$");
	private static final Map<String, String> CHANGE_WARNINGS = Map.of(
		"Ancient Pyramid altar", "Drains your Prayer, and the way in crosses desert heat",
		"Astral altar", "Aggressive suqahs nearby",
		"Tyss", "Right-click Tyss: Spellbook");

	private LegSteps()
	{
	}

	static SubStep walkToStage(Leg leg, Stage stage)
	{
		int radius = stage.getRadius() > 0 ? stage.getRadius() : SubSteps.ARRIVE_TILES;
		if (!stage.isOurMarker())
		{
			return SubStep.builder().kind(SubStep.Kind.WALK_TO_CLUE).text("Walk to the clue")
				.goal(leg.getTo()).radius(radius).build();
		}
		String text = !stage.getNpcIds().isEmpty() ? "Walk to the outlined NPC"
			: !stage.getObjectIds().isEmpty() ? "Walk to the outlined object" : "Walk to the marker";
		return SubStep.builder().kind(SubStep.Kind.WALK).text(text).waypoint(leg.getTo()).goal(leg.getTo()).radius(radius)
			.npcIds(stage.getNpcIds()).objectIds(stage.getObjectIds()).option(stage.getOption()).spans(stage.getSpans()).build();
	}

	/** Core's *clue* tag items are named too, and outlined in the bank like ours, so the spade is easy to find. */
	static SubStep withdraw(Route route, IntFunction<String> itemNames)
	{
		if (route.getWithdraw().isEmpty())
		{
			return SubStep.builder().kind(SubStep.Kind.WITHDRAW).text("Close the bank").build();
		}
		List<String> items = route.getWithdraw().stream().map(use -> itemLine(use, itemNames)).collect(Collectors.toList());
		String text = route.isDepositFirst() ? "Deposit to free slots, then withdraw:" : "Withdraw from the bank:";
		return SubStep.builder().kind(SubStep.Kind.WITHDRAW).text(text).items(List.copyOf(items))
			.bankItems(route.getWithdraw().stream().map(ItemUse::getItemId).collect(Collectors.toUnmodifiableSet())).build();
	}

	static SubStep walk(Leg leg, Leg next, Step step, boolean takeFromStash)
	{
		WorldPoint stash = takeFromStash ? SubSteps.stashTile(step) : null;
		if (stash != null && step.getTargets().contains(leg.getTo()))
		{
			return stashWalk(stash);
		}
		if (step.getWaypointAct() != null && step.getTargets().contains(leg.getTo()))
		{
			return SubStep.builder().kind(SubStep.Kind.WALK).text("Walk to the marker")
				.waypoint(leg.getTo()).goal(leg.getTo()).radius(step.isActAnywhere() ? SubSteps.ARRIVE_TILES : PROBE_ARRIVE_TILES).build();
		}
		if (step.getTargets().contains(leg.getTo()))
		{
			int radius = step.getKind() == TargetKind.AREA ? SubSteps.AREA_ARRIVE_TILES : SubSteps.ARRIVE_TILES;
			return SubStep.builder().kind(SubStep.Kind.WALK_TO_CLUE).text("Walk to the clue")
				.goal(leg.getTo()).radius(radius).build();
		}
		return SubStep.builder().kind(SubStep.Kind.WALK).text("Walk to " + walkGoal(next))
			.waypoint(leg.getTo()).goal(leg.getTo()).radius(SubSteps.ARRIVE_TILES).build();
	}

	static SubStep stashWalk(WorldPoint stash)
	{
		return SubStep.builder().kind(SubStep.Kind.WALK).text("Walk to the STASH unit").waypoint(stash).goal(stash).radius(SubSteps.ARRIVE_TILES).build();
	}

	static SubStep enter(StepIndex.Entry data)
	{
		StepIndex.WayIn way = data.getEntry();
		String needs = data.getRequires().stream().map(StepIndex.Requires::getName).collect(Collectors.joining(", "));
		String option = way.getOption() == null || way.getOption().isEmpty() ? null : way.getOption();
		String detail = option == null ? needs : needs.isEmpty() ? option : option + "; needs " + needs;
		return SubStep.builder().kind(SubStep.Kind.ENTER).text("Go in: " + way.getText()).detail(detail.isEmpty() ? null : detail)
			.waypoint(way.getTile()).wayIn(way).build();
	}

	static SubStep exit(Leg leg, Exit exit)
	{
		return SubStep.builder().kind(SubStep.Kind.EXIT).text(exitText(exit))
			.waypoint(exit.getOrigin()).goal(leg.getTo()).radius(SubSteps.LANDING_TILES).exit(exit).build();
	}

	/** The Swap's book is its spell's, not the leg's: after the cast the player is back on Lunar. */
	static SubStep swap(Leg leg)
	{
		Book book = leg.getRow().getRequirements().getBook();
		return SubStep.builder().kind(SubStep.Kind.SPELLBOOK_SWAP).text("Spellbook Swap to " + book.label())
			.detail("Right-click Spellbook Swap, then pick the book").book(book).change(leg.getChange()).build();
	}

	static SubStep teleport(Leg leg, HouseState house)
	{
		CatalogRow row = leg.getRow();
		WorldPoint standsAt = row.isLocated() && !row.isInHouse() ? leg.getFrom() : null;
		return SubStep.builder().kind(SubStep.Kind.TELEPORT).text(withKey(teleportText(row), hotkey(row, house))).detail(teleportDetail(row))
			.waypoint(standsAt).goal(leg.getTo()).radius(SubSteps.LANDING_TILES).row(row).build();
	}

	static SubStep fairyRing(Leg leg)
	{
		CatalogRow landing = leg.getLanding();
		String place = landing.getName();
		int colon = place.indexOf(": ");
		String where = place.startsWith(FAIRY_RING_PREFIX) && colon >= 0 ? place.substring(colon + 2) : place;
		boolean coded = landing.getCode() != null && landing.getCode().length() == 3;
		return SubStep.builder().kind(SubStep.Kind.FAIRY_RING)
			.text(coded ? "Fairy ring " + MenuLines.menuColoured(landing.getCode()) : "Fairy ring to " + where)
			.waypoint(leg.getFrom()).goal(leg.getTo()).radius(SubSteps.LANDING_TILES).row(landing).build();
	}

	static SubStep change(Leg leg)
	{
		SpellbookChange change = leg.getChange();
		String book = leg.getBookAfter().label();
		if (change.isAnywhere())
		{
			return SubStep.builder().kind(SubStep.Kind.CHANGE_BOOK).text(capeName(change) + ": Spellbook → " + book)
				.detail(change.getName().contains("(worn)") ? "Right-click the worn cape in the equipment tab" : "Right-click the cape: Spellbook")
				.book(leg.getBookAfter()).change(change).build();
		}
		return SubStep.builder().kind(SubStep.Kind.CHANGE_BOOK).text(change.getName() + " → " + book)
			.detail(warning(change)).waypoint(change.getTile()).book(leg.getBookAfter()).change(change).build();
	}

	/**
	 * The hotkey in the menu line's colour: the list label's own ("diary cape: B. Hatius Cosaintus"), else put before
	 * the destination as a list label shows it ("Jewellery box: 7. Burthorpe").
	 */
	static String withKey(String text, char key)
	{
		if (key == 0)
		{
			return text;
		}
		String coloured = Matcher.quoteReplacement(MenuLines.keyText(key));
		String inLabel = text.replaceFirst("(?<=: )" + Pattern.quote(String.valueOf(key)) + "(?=[.:] )", coloured);
		int colon = text.lastIndexOf(": ");
		return !inLabel.equals(text) || colon < 0 ? inLabel : text.substring(0, colon + 2) + MenuLines.keyText(key) + ". "
			+ text.substring(colon + 2);
	}

	/** A required item's use carries the whole banked stack, so the amount still to take comes with the name. */
	private static String itemLine(ItemUse use, IntFunction<String> itemNames)
	{
		String storage = use.getContainer() == Container.GROUP_STORAGE ? " (group storage)" : "";
		return itemNames.apply(use.getItemId()) + storage;
	}

	private static String exitText(Exit exit)
	{
		String target = exit.getTarget().isEmpty() ? "exit" : exit.getTarget().toLowerCase();
		String option = exit.getOption().replace('-', ' ');
		if (option.equals(TALK_TO) && !exit.getTarget().isEmpty())
		{
			return TALK_TO + " " + exit.getTarget();
		}
		return option.isEmpty() ? "Take the " + target : option + (option.equals("Travel") ? " with the " : " the ") + target;
	}

	private static String walkGoal(Leg next)
	{
		if (next == null)
		{
			return "the marker";
		}
		switch (next.getKind())
		{
			case FAIRY_RING:
				return "the fairy ring";
			case SPELLBOOK_CHANGE:
				return place(next.getChange());
			case BANK:
				return "the bank";
			case TELEPORT:
				return located(next.getRow());
			default:
				return "the marker";
		}
	}

	private static String located(CatalogRow row)
	{
		if (row.getCategory() == Category.SPIRIT_TREE && !row.isInHouse())
		{
			return "the spirit tree";
		}
		if (row.getMenu() != null && row.getMenu().startsWith(NPC_MENU))
		{
			return "the outlined NPC";
		}
		return row.getCategory() == Category.QUETZAL ? "Renu" : RIDE_PLACES.getOrDefault(row.getCategory(), "the marker");
	}

	private static String teleportText(CatalogRow row)
	{
		String name = row.getName();
		if (row.isLocated() || row.isQuetzalMap())
		{
			return houseText(row);
		}
		switch (row.getCategory())
		{
			case SPELL:
			case HOME:
				return "Cast " + name;
			case MINIGAME:
				return "Minigame teleport: " + row.minigameName();
			case TABLET:
				return "Break the " + name;
			case SCROLL:
				return name.contains(":") ? "Use " + name : "Read the " + name + " scroll";
			default:
				return "Use " + name;
		}
	}

	private static String teleportDetail(CatalogRow row)
	{
		if (row.isInHouse())
		{
			return null;
		}
		if (row.getCategory() == Category.SPIRIT_TREE)
		{
			return "Travel";
		}
		if (row.getCategory() == Category.QUETZAL)
		{
			return "Renu: Travel, then pick it on the map";
		}
		if (row.isQuetzalMap())
		{
			return "Signal, then pick it on the map";
		}
		switch (row.getCategory())
		{
			case SPELL:
			case HOME:
				return "Magic tab";
			case MINIGAME:
				return "Magic tab: Minigame Teleport";
			default:
				return null;
		}
	}

	private static char hotkey(CatalogRow row, HouseState house)
	{
		String menu = row.getMenu();
		if (menu != null && menu.startsWith("nexus "))
		{
			int struct = Integer.parseInt(menu.split(" ")[1]);
			Integer line = house.getNexusLines().get(struct);
			return line == null || line < 1 || line > MenuLines.HOTKEYS.length() ? 0 : MenuLines.HOTKEYS.charAt(line - 1);
		}
		if (menu != null && menu.startsWith("box "))
		{
			int line = Integer.parseInt(menu.substring("box ".length()));
			return line < MenuLines.HOTKEYS.length() ? MenuLines.HOTKEYS.charAt(line) : 0;
		}
		String label = menu != null && menu.startsWith("list ") ? menu.substring("list ".length())
			: menu != null && menu.contains(RowTargets.MENU_STEP) ? menu.substring(menu.lastIndexOf(RowTargets.MENU_STEP) + RowTargets.MENU_STEP.length())
			: row.getName().substring(row.getName().lastIndexOf(": ") + 2);
		Matcher key = LIST_HOTKEY.matcher(label);
		return key.find() ? key.group(1).charAt(0) : 0;
	}

	private static String houseText(CatalogRow row)
	{
		String name = CLICK_NOTE.matcher(row.getName()).replaceFirst("");
		int colon = name.indexOf(": ");
		if (row.getCategory() == Category.PORTAL)
		{
			return "Enter the " + name.substring(colon + 2) + " portal";
		}
		return colon < 0 ? "Use the " + name.toLowerCase() : name;
	}

	private static String capeName(SpellbookChange change)
	{
		String name = change.getName();
		int colon = name.indexOf(':');
		return (colon < 0 ? name : name.substring(0, colon)).replace(" (worn)", "");
	}

	private static String place(SpellbookChange change)
	{
		String name = change.getName();
		int colon = name.indexOf(':');
		String where = colon < 0 ? name : name.substring(0, colon);
		return where.startsWith("Tyss") ? "Tyss" : "the " + where;
	}

	private static String warning(SpellbookChange change)
	{
		return CHANGE_WARNINGS.entrySet().stream().filter(e -> change.getName().startsWith(e.getKey()))
			.map(Map.Entry::getValue).findFirst().orElse(null);
	}
}

package com.cluehelper.guide;

import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Text matching is only for lines no script argument identifies: the nexus and the jewellery box are matched by struct
 * id and index instead, because better-teleport-menu rewrites their text.
 */
public final class MenuLabels
{
	private static final Set<String> TELEPORT_LIST_OPENERS = Set.of("rub", "open", "teleport", "teleports", "teleport menu", "operate",
		"travel", "tree", "activate", "configure", "ring configure", "perks", "spellbook", "commune");
	/** Catalog (Shortest Path) labels that the worn Max cape's options name differently. */
	private static final Map<String, String> GAME_NAMES = Map.of(
		"feldip hills", "carnivorous chinchompas",
		"tele to poh", "home");
	private static final Pattern APOSTROPHE = Pattern.compile("['’]");
	private static final Pattern HOTKEY_LABEL = Pattern.compile("^([0-9A-Z])[.:] ");
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	private static final Pattern KEY_BRACKET = Pattern.compile("^\\[[^]]*]\\s*");
	private static final Pattern KEY_PREFIX = Pattern.compile("^[0-9A-Z]\\s*[.:]\\s+");
	private static final Pattern ALIAS = Pattern.compile("\\s*\\([^)]*\\)\\s*$");
	private static final Pattern NOT_WORD = Pattern.compile("[^a-z0-9]+");
	private static final int SHORTEST_PARTIAL = 4;
	private static final String TELEPORT_SUFFIX = " teleport";
	private static final String RING_PREFIX = "ring ";

	private MenuLabels()
	{
	}

	public static String normalise(String text)
	{
		if (text == null)
		{
			return "";
		}
		String plain = TAGS.matcher(text).replaceAll("").trim();
		plain = KEY_BRACKET.matcher(plain).replaceFirst("");
		plain = KEY_PREFIX.matcher(plain).replaceFirst("");
		plain = ALIAS.matcher(plain).replaceFirst("");
		plain = APOSTROPHE.matcher(plain).replaceAll("");
		return NOT_WORD.matcher(plain.toLowerCase(Locale.ROOT)).replaceAll(" ").trim();
	}

	public static boolean matches(String line, String label)
	{
		return same(line, label) || same(withoutRegionPrefix(line), label);
	}

	/** Diary Masters lines name the region first: "7: Karamja: Kaleb Paramaya (retired)". */
	private static String withoutRegionPrefix(String line)
	{
		int lastColon = line == null ? -1 : line.lastIndexOf(':');
		return lastColon > 0 ? line.substring(lastColon + 1) : null;
	}

	/** A prefix matches plurals ("Black chinchompas"), never a name inside another: "Ardougne" isn't "West Ardougne". */
	private static boolean same(String line, String label)
	{
		String a = normalise(line);
		String b = normalise(label);
		if (a.isEmpty() || b.isEmpty())
		{
			return false;
		}
		String gameName = GAME_NAMES.get(b);
		if (gameName != null && a.equals(gameName))
		{
			return true;
		}
		if (a.equals(b) || namesPlaceOf(a, b))
		{
			return true;
		}
		return Math.min(a.length(), b.length()) >= SHORTEST_PARTIAL && (a.startsWith(b) || b.startsWith(a))
			|| startsWithWord(a, b) || startsWithWord(b, a);
	}

	/** A short name that is the label's first word: the ring of the elements' "Air" for the game's "Air Altar". */
	private static boolean startsWithWord(String label, String word)
	{
		return label.startsWith(word + " ");
	}

	/** Item options like the Ardougne cloak's "Monastery Teleport" for the catalog's "Kandarin Monastery". */
	private static boolean namesPlaceOf(String option, String label)
	{
		if (!option.endsWith(TELEPORT_SUFFIX) || option.length() == TELEPORT_SUFFIX.length())
		{
			return false;
		}
		List<String> words = List.of(label.split(" "));
		return words.containsAll(List.of(option.substring(0, option.length() - TELEPORT_SUFFIX.length()).split(" ")));
	}

	/**
	 * The diary cape's sub-menu and list name a line differently ("Morytania: Le-sabrè") but keep the hotkey order, so a
	 * label's hotkey ("C. Le-sabrè") gives its line, or -1.
	 */
	static int hotkeyIndex(String label)
	{
		Matcher key = label == null ? null : HOTKEY_LABEL.matcher(label.trim());
		return key != null && key.find() ? MenuLines.HOTKEYS.indexOf(key.group(1).charAt(0)) : -1;
	}

	static boolean isOpener(String option)
	{
		return TELEPORT_LIST_OPENERS.contains(normalise(option));
	}

	/** Rings also offer Zanaris as an option of its own: "Zanaris", or "Ring-Zanaris" on the house's spiritual fairy tree. */
	static boolean isRingDestination(String option, String code)
	{
		String plain = normalise(option);
		String place = code.toLowerCase(Locale.ROOT);
		return isLastDestination(option, code) || plain.equals(place) || plain.equals(RING_PREFIX + place);
	}

	static boolean isLastDestination(String option, String code)
	{
		String plain = TAGS.matcher(option == null ? "" : option).replaceAll("").toUpperCase(Locale.ROOT).replace(" ", "");
		return plain.contains("LAST-DESTINATION") && plain.contains("(" + code.replace("-", "") + ")");
	}
}

package com.cluehelper.guide;

import java.awt.Color;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.function.BiConsumer;
import java.util.function.Predicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Teleport interfaces are read from their scripts' arguments, before better-teleport-menu rewrites them. Lines and menu
 * options are only recoloured, never rewritten or hidden. Client thread only.
 */
@Singleton
public class MenuLines
{
	private static final int LIST_TITLE = 219;
	private static final int LIST_TITLE_ALT = 9142;
	private static final int LIST_LINE = 218;
	private static final int LIST_LINE_ALT = 9143;
	private static final int NEXUS_LINE = 2675;
	private static final int BOX_LINE = 1688;
	static final String HOTKEYS = "123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
	private static final int LIST_GROUP = 187;
	private static final Pattern MINIGAME_PLACE_NUMBER = Pattern.compile("^\\d+\\. ");
	/** A minigame card's text is its name, a break, then its places. */
	private static final String LINE_BREAK = "<br>";
	private static final int NEXUS_GROUP = 17;
	private static final int BOX_GROUP = 590;
	private static final int LOG_FIRST_CODE = 12;
	/** Each code in the travel log is followed by its favourite star. */
	private static final int LOG_COMPONENTS_PER_CODE = 2;
	private static final String MAP_TELEPORT = "Teleport";
	private static final String MAP_REGION = "Select";
	/** Same cyan as {@code Markers.COLOUR}, the colour of every Clue Helper highlight. */
	private static final int TEXT_COLOUR = 0x40D0FF;

	/** A hotkey as the info box names it: upper case, in the colour of the menu line it presses. */
	static String keyText(char key)
	{
		return menuColoured(String.valueOf(Character.toUpperCase(key)));
	}

	/** What to press or dial, in the colour of the menu lines; the info box closes the colour. */
	static String menuColoured(String text)
	{
		return String.format("<col=%06x>%s</col>", TEXT_COLOUR, text);
	}

	private final Client client;
	private final QuetzalIcons quetzalIcons;
	private final FairyDials fairyDials;
	private final Map<String, int[]> listLines = new HashMap<>();
	private String listTitle;
	private final List<int[]> rawListLines = new ArrayList<>();
	private boolean listFresh;
	private final Map<Integer, int[]> nexusLines = new HashMap<>();
	private final Map<Integer, int[]> boxLines = new HashMap<>();
	private final Map<Widget, Integer> originalTextColours = new IdentityHashMap<>();

	@Inject
	MenuLines(Client client, QuetzalIcons quetzalIcons, FairyDials fairyDials)
	{
		this.client = client;
		this.quetzalIcons = quetzalIcons;
		this.fairyDials = fairyDials;
	}

	/** Call from a handler at priority 2, ahead of better-teleport-menu's at 1. */
	public void onScriptPreFired(ScriptPreFired event)
	{
		switch (event.getScriptId())
		{
			case LIST_TITLE:
			case LIST_TITLE_ALT:
				listLines.clear();
				rawListLines.clear();
				listTitle = objectTail();
				break;
			case LIST_LINE:
			case LIST_LINE_ALT:
			{
				int[] ints = intTail(6);
				String label = objectTail();
				if (ints != null && label != null)
				{
					listLines.put(MenuLabels.normalise(label), new int[]{ints[0], ints[3], ints[3]});
					rawListLines.add(new int[]{ints[0], ints[3]});
					listFresh = true;
				}
				break;
			}
			case NEXUS_LINE:
			{
				int[] ints = intTail(8);
				if (ints != null)
				{
					nexusLines.put(ints[3], new int[]{ints[7], ints[0]});
				}
				break;
			}
			case BOX_LINE:
			{
				int[] ints = intTail(7);
				if (ints != null)
				{
					boxLines.put(ints[6], new int[]{ints[0], ints[4]});
				}
				break;
			}
			default:
				break;
		}
	}

	/**
	 * Once per list, a tick after its lines are drawn. Hands over the widget texts rather than the script's labels: only
	 * they carry the grey of a planted spirit tree that can't be used.
	 */
	public void takeFreshList(BiConsumer<String, List<String>> reader)
	{
		if (!listFresh)
		{
			return;
		}
		listFresh = false;
		List<String> texts = new ArrayList<>();
		for (int[] at : rawListLines)
		{
			Widget line = child(at);
			if (line != null && line.getText() != null)
			{
				texts.add(line.getText());
			}
		}
		reader.accept(listTitle, texts);
	}

	public void onWidgetClosed(WidgetClosed event)
	{
		originalTextColours.keySet().removeIf(line -> line.getId() >>> 16 == event.getGroupId());
		if (event.getGroupId() == LIST_GROUP)
		{
			listLines.clear();
		}
		else if (event.getGroupId() == NEXUS_GROUP)
		{
			nexusLines.clear();
		}
		else if (event.getGroupId() == BOX_GROUP)
		{
			boxLines.clear();
		}
	}

	/** Whether any of the target's lines is on screen, coloured or outlined: the menu is open at the teleport's line. */
	public boolean showing(MenuTarget target)
	{
		return !lineWidgets(target).isEmpty();
	}

	/** Only the target's lines without text (map icons, region shields, travel log codes); text lines are coloured. */
	public List<Rectangle> lines(MenuTarget target)
	{
		List<Rectangle> out = new ArrayList<>();
		for (Widget widget : lineWidgets(target))
		{
			Rectangle shown = Widgets.hasTextInside(widget) ? null : Widgets.clipped(widget);
			if (shown != null && !shown.isEmpty())
			{
				out.add(shown);
			}
		}
		return out;
	}

	/**
	 * Call every client tick: it also puts back the colour of lines no longer wanted.
	 *
	 * @param entryWidget a scroll book entry whose name and charges are coloured too, or -1
	 */
	public void colourLines(MenuTarget target, int entryWidget, boolean enabled)
	{
		Set<Widget> wanted = Collections.newSetFromMap(new IdentityHashMap<>());
		if (enabled)
		{
			lineWidgets(target).stream().flatMap(line -> Widgets.descendants(line).stream()).filter(Widgets::hasText).forEach(wanted::add);
			if (entryWidget != ScrollBook.NO_WIDGET)
			{
				for (int text : ScrollBook.texts(entryWidget))
				{
					Widget line = client.getWidget(text);
					if (Widgets.visible(line) && Widgets.hasText(line))
					{
						wanted.add(line);
					}
				}
			}
		}
		for (Iterator<Map.Entry<Widget, Integer>> it = originalTextColours.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Widget, Integer> line = it.next();
			if (!wanted.contains(line.getKey()))
			{
				line.getKey().setTextColor(line.getValue());
				it.remove();
			}
		}
		for (Widget line : wanted)
		{
			originalTextColours.putIfAbsent(line, line.getTextColor());
			if (line.getTextColor() != TEXT_COLOUR)
			{
				line.setTextColor(TEXT_COLOUR);
			}
		}
	}

	/** Call on {@code MenuOpened}. */
	public void colourMenu(MenuTarget target, boolean enabled)
	{
		if (!enabled || target == null || target == MenuTarget.NONE)
		{
			return;
		}
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		for (int row : pickRows(entries, target))
		{
			colour(entries[row]);
		}
		String destination = target.destination();
		for (MenuEntry entry : entries)
		{
			Menu sub = entry.getSubMenu();
			if (sub == null || destination == null || !isOptionOnTarget(entry, target))
			{
				continue;
			}
			MenuEntry[] options = sub.getMenuEntries();
			boolean named = false;
			for (MenuEntry option : options)
			{
				if (MenuLabels.matches(option.getOption(), destination))
				{
					colour(option);
					named = true;
				}
			}
			int line = MenuLabels.hotkeyIndex(destination);
			if (!named && line >= 0 && line < options.length)
			{
				colour(options[options.length - 1 - line]);
			}
		}
	}

	private static void colour(MenuEntry entry)
	{
		entry.setOption(ColorUtil.wrapWithColorTag(Text.removeTags(entry.getOption()), new Color(TEXT_COLOUR)));
	}

	private List<Widget> lineWidgets(MenuTarget target)
	{
		Found found = new Found();
		find(target, found);
		return found.widgets;
	}

	/** The key the charter's destination list gives the target's port, or 0 while the list isn't open. */
	public char charterKey(MenuTarget target)
	{
		String destination = target == null ? null : target.destination();
		Widget[] rows = dynamicChildren(InterfaceID.CharteringMenuSide.LIST_CONTENT);
		for (int i = 0; destination != null && i + 1 < rows.length; i++)
		{
			String text = rows[i + 1] == null ? null : Text.removeTags(rows[i + 1].getText()).trim();
			if (Widgets.visible(rows[i]) && namesPort(rows[i], destination) && text != null && !text.isEmpty())
			{
				return text.charAt(0);
			}
		}
		return 0;
	}

	/** The charter map's marker and the destination list's line both carry the port's name as their action. */
	private boolean charter(String destination, Found out)
	{
		boolean found = false;
		for (Widget marker : dynamicChildren(InterfaceID.SailingMenu.CONTENT))
		{
			if (Widgets.visible(marker) && namesPort(marker, destination))
			{
				out.add(marker);
				found = true;
			}
		}
		Widget[] rows = dynamicChildren(InterfaceID.CharteringMenuSide.LIST_CONTENT);
		for (int i = 0; i + 1 < rows.length; i++)
		{
			if (Widgets.visible(rows[i]) && namesPort(rows[i], destination))
			{
				out.add(rows[i + 1]);
				found = true;
			}
		}
		return found;
	}

	private Widget[] dynamicChildren(int component)
	{
		Widget parent = client.getWidget(component);
		Widget[] children = parent == null || parent.isHidden() ? null : parent.getDynamicChildren();
		return children == null ? new Widget[0] : children;
	}

	private static boolean namesPort(Widget widget, String label)
	{
		for (String action : widget.getActions() == null ? new String[0] : widget.getActions())
		{
			if (action != null && MenuLabels.matches(action, label))
			{
				return true;
			}
		}
		return false;
	}

	private void find(MenuTarget target, Found out)
	{
		if (target == null || target == MenuTarget.NONE)
		{
			return;
		}
		switch (target.getLine())
		{
			case NEXUS:
				nexus(target, out);
				break;
			case BOX:
				out.add(child(boxLines.get(target.getLineId())));
				break;
			case FAIRY_CODE:
				fairyCode(target.getLineKey(), out);
				break;
			case MINIGAME:
				minigame(target.getLineName(), out);
				break;
			case QUETZAL:
				quetzal(target.getLineId(), out);
				break;
			default:
				labelled(target, out);
				break;
		}
		for (MenuTarget alternative : target.getAlternatives())
		{
			find(alternative, out);
		}
	}

	private int[] pickRows(MenuEntry[] entries, MenuTarget target)
	{
		String destination = target.destination();
		int pick = find(entries, target, entry -> isExactly(entry, destination));
		if (pick < 0)
		{
			pick = find(entries, target, entry -> isDestination(entry, target, destination));
		}
		if (pick < 0)
		{
			pick = find(entries, target, entry -> leadsToDestination(entry, target, destination));
		}
		if (pick < 0)
		{
			pick = find(entries, target, entry -> MenuLabels.isOpener(entry.getOption()));
		}
		return pick < 0 ? new int[0] : new int[]{pick};
	}

	private void nexus(MenuTarget target, Found out)
	{
		int[] at = nexusLines.get(target.getLineId());
		Widget line = child(at);
		if (Widgets.visible(line))
		{
			out.add(labelOf(line));
			return;
		}
		Widget map = client.getWidget(InterfaceID.TelenexusTeleport.FRAME);
		Widget[] icons = map == null || map.isHidden() ? null : map.getDynamicChildren();
		if (icons == null)
		{
			return;
		}
		Widget region = null;
		for (Widget icon : icons)
		{
			if (!Widgets.visible(icon) || icon.getActions() == null)
			{
				continue;
			}
			if (Widgets.hasAction(icon, MAP_TELEPORT) && MenuLabels.matches(icon.getName(), target.getLineName()))
			{
				out.add(icon);
				return;
			}
			if (Widgets.hasAction(icon, MAP_REGION) && MenuLabels.matches(icon.getName(), target.getLineKey()))
			{
				region = icon;
			}
		}
		out.add(region);
	}

	private void fairyCode(String code, Found out)
	{
		String letters = FairyDials.letters(code);
		if (letters == null)
		{
			return;
		}
		int logComponent = LOG_FIRST_CODE + LOG_COMPONENTS_PER_CODE * FairyDials.logIndex(letters);
		out.add(client.getWidget(InterfaceID.FairyringsLog.UNIVERSE | logComponent));
		if (fairyDials.isDialled(letters))
		{
			out.add(client.getWidget(InterfaceID.Fairyrings.CONFIRM));
		}
	}

	private void minigame(String name, Found out)
	{
		if (Widgets.visible(client.getWidget(InterfaceID.Minigames.MINIGAMES)))
		{
			minigameCard(name, out);
			return;
		}
		if (minigamePlace(name, out))
		{
			return;
		}
		Widget current = client.getWidget(InterfaceID.Grouping.CURRENTGAME);
		if (!Widgets.visible(current))
		{
			return;
		}
		if (MenuLabels.matches(current.getText(), name))
		{
			out.add(client.getWidget(InterfaceID.Grouping.TELEPORT));
			return;
		}
		Widget contents = client.getWidget(InterfaceID.Grouping.DROPDOWN_CONTENTS);
		Widget[] lines = Widgets.visible(contents) ? contents.getDynamicChildren() : null;
		if (lines != null)
		{
			for (Widget line : lines)
			{
				if (Widgets.visible(line) && MenuLabels.matches(line.getText(), name))
				{
					out.add(line);
					return;
				}
			}
		}
		out.add(client.getWidget(InterfaceID.Grouping.DROPDOWN_TOP));
	}

	/**
	 * The Minigame Teleport spell opens a grid of cards, one per minigame, each with the game's name and its places;
	 * the card whose name is the row's game is outlined. A row like "Rat Pits: 4. Port Sarim" names the game first.
	 */
	private void minigameCard(String name, Found out)
	{
		String game = name.split(": ")[0];
		for (int card = InterfaceID.Minigames.MINIGAME_21; card <= InterfaceID.Minigames.MINIGAME_1; card++)
		{
			Widget widget = client.getWidget(card);
			if (Widgets.visible(widget) && hasTextMatching(widget, game))
			{
				out.add(widget);
				return;
			}
		}
	}

	/** A game with several places asks which one next, e.g. "Port Sarim (wily cats)" for "Rat Pits: 4. Port Sarim". */
	private boolean minigamePlace(String name, Found out)
	{
		String[] parts = name.split(": ", 2);
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		Widget[] lines = parts.length < 2 || !Widgets.visible(options) ? null : options.getDynamicChildren();
		if (lines == null)
		{
			return false;
		}
		String place = MenuLabels.normalise(MINIGAME_PLACE_NUMBER.matcher(parts[1]).replaceFirst(""));
		for (Widget line : lines)
		{
			if (Widgets.visible(line) && MenuLabels.normalise(line.getText()).startsWith(place))
			{
				out.add(line);
				return true;
			}
		}
		return false;
	}

	private static boolean hasTextMatching(Widget widget, String label)
	{
		for (Widget part : Widgets.descendants(widget))
		{
			String text = part.getText();
			if (text != null && MenuLabels.matches(text.split(LINE_BREAK, 2)[0], label))
			{
				return true;
			}
		}
		return false;
	}

	private void quetzal(int quetzalTableId, Found out)
	{
		int[] at = quetzalIcons.position(quetzalTableId);
		if (at == null)
		{
			return;
		}
		Widget icons = client.getWidget(InterfaceID.QuetzalMenu.ICONS);
		if (!Widgets.visible(icons))
		{
			icons = client.getWidget(InterfaceID.QuetzalwhistleMenu.ICONS);
		}
		if (!Widgets.visible(icons))
		{
			return;
		}
		out.add(QuetzalIcons.nearest(icons.getDynamicChildren(), at));
	}

	private void labelled(MenuTarget target, Found out)
	{
		String destination = target.destination();
		if (destination == null || charter(destination, out))
		{
			return;
		}
		for (Map.Entry<String, int[]> line : listLines.entrySet())
		{
			if (MenuLabels.matches(line.getKey(), destination))
			{
				Widget listLine = child(line.getValue());
				out.add(Widgets.visible(listLine) ? listLine : drawnOverList(line.getValue(), destination));
				return;
			}
		}
		int index = MenuLabels.hotkeyIndex(destination);
		for (int[] line : listLines.values())
		{
			if (index >= 0 && line[2] == index)
			{
				out.add(child(line));
				return;
			}
		}
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		Widget[] lines = options == null || options.isHidden() ? null : options.getDynamicChildren();
		if (lines == null)
		{
			return;
		}
		List<String> labels = new ArrayList<>(target.getPath());
		for (int i = labels.size() - 1; i >= 0; i--)
		{
			for (Widget option : lines)
			{
				if (Widgets.visible(option) && MenuLabels.matches(option.getText(), labels.get(i)))
				{
					out.add(option);
					return;
				}
			}
		}
	}

	/**
	 * Another plugin's map drawn over the hidden list (spirit-tree-map): its button for the destination, a widget in the
	 * list's interface named after it, with an action.
	 */
	private Widget drawnOverList(int[] listLine, String destination)
	{
		for (Widget widget : Widgets.descendants(client.getWidget(listLine[0] >>> 16, 0)))
		{
			if (Widgets.visible(widget) && widget.getActions() != null && MenuLabels.matches(widget.getName(), destination))
			{
				return widget;
			}
		}
		return null;
	}

	/** An option named exactly so wins over one that only starts the same: a ladder's "Climb-up" over its "Climb". */
	private static boolean isExactly(MenuEntry entry, String destination)
	{
		return destination != null && entry.getOption() != null
			&& MenuLabels.normalise(entry.getOption()).equals(MenuLabels.normalise(destination));
	}

	private boolean isDestination(MenuEntry entry, MenuTarget target, String destination)
	{
		if (target.getLine() == MenuTarget.Line.FAIRY_CODE && target.getLineKey() != null)
		{
			return MenuLabels.isRingDestination(entry.getOption(), target.getLineKey());
		}
		return destination != null && MenuLabels.matches(entry.getOption(), destination);
	}

	private static boolean leadsToDestination(MenuEntry entry, MenuTarget target, String destination)
	{
		List<String> path = target.getPath();
		for (int i = 0; i < path.size() - 1; i++)
		{
			if (MenuLabels.matches(entry.getOption(), path.get(i)))
			{
				return true;
			}
		}
		Menu sub = entry.getSubMenu();
		if (sub == null || destination == null)
		{
			return false;
		}
		for (MenuEntry option : sub.getMenuEntries())
		{
			if (MenuLabels.matches(option.getOption(), destination))
			{
				return true;
			}
		}
		return false;
	}

	private int find(MenuEntry[] entries, MenuTarget target, Predicate<MenuEntry> wanted)
	{
		for (int i = entries.length - 1; i >= 0; i--)
		{
			if (isOptionOnTarget(entries[i], target) && wanted.test(entries[i]))
			{
				return i;
			}
		}
		return -1;
	}

	private static boolean isOptionOnTarget(MenuEntry entry, MenuTarget target)
	{
		if (target.getItemIds().contains(entry.getItemId()))
		{
			return true;
		}
		Widget widget = entry.getWidget();
		if (widget != null && (target.getItemIds().contains(widget.getItemId()) || target.getWidgetIds().contains(widget.getId())))
		{
			return true;
		}
		if (entry.getItemId() <= 0 && target.getItemNames().contains(MenuLabels.normalise(entry.getTarget())))
		{
			return true;
		}
		MenuAction type = entry.getType();
		boolean objectOption = type == MenuAction.GAME_OBJECT_FIRST_OPTION || type == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| type == MenuAction.GAME_OBJECT_THIRD_OPTION || type == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| type == MenuAction.GAME_OBJECT_FIFTH_OPTION;
		if (objectOption && target.getObjectIds().contains(entry.getIdentifier()))
		{
			return true;
		}
		NPC npc = entry.getNpc();
		return npc != null && (target.getNpcIds().contains(npc.getId())
			|| npc.getTransformedComposition() != null && target.getNpcIds().contains(npc.getTransformedComposition().getId())
			|| npc.getName() != null && target.getNpcNames().contains(MenuLabels.normalise(npc.getName())));
	}

	private Widget child(int[] at)
	{
		if (at == null)
		{
			return null;
		}
		Widget parent = client.getWidget(at[0]);
		return parent == null ? null : parent.getChild(at[1]);
	}

	/** The target's lines. */
	private static final class Found
	{
		final List<Widget> widgets = new ArrayList<>();

		void add(Widget widget)
		{
			if (Widgets.visible(widget))
			{
				widgets.add(widget);
			}
		}
	}

	/** A nexus row ({@code ROWS1}) has no text; its label sits at the same height in the {@code TEXT1} layer. */
	private Widget labelOf(Widget row)
	{
		if (Widgets.hasText(row))
		{
			return row;
		}
		Widget text = client.getWidget(InterfaceID.TelenexusTeleport.TEXT1);
		Widget[] labels = text == null ? null : text.getDynamicChildren();
		int top = row.getRelativeY();
		int bottom = top + row.getHeight();
		for (Widget label : labels == null ? new Widget[0] : labels)
		{
			int middle = label == null ? -1 : label.getRelativeY() + label.getHeight() / 2;
			if (label != null && Widgets.hasText(label) && middle >= top && middle < bottom)
			{
				return label;
			}
		}
		return row;
	}

	private int[] intTail(int count)
	{
		int size = client.getIntStackSize();
		if (size < count)
		{
			return null;
		}
		int[] tail = new int[count];
		System.arraycopy(client.getIntStack(), size - count, tail, 0, count);
		return tail;
	}

	private String objectTail()
	{
		int size = client.getObjectStackSize();
		Object last = size < 1 ? null : client.getObjectStack()[size - 1];
		return last instanceof String ? (String) last : null;
	}
}

package com.cluehelper.guide;

import java.util.List;
import java.util.Set;
import lombok.Builder;
import lombok.Value;

@Value
@Builder(toBuilder = true)
public class MenuTarget
{
	public static final MenuTarget NONE = MenuTarget.builder().build();

	public enum Line
	{
		LABEL,
		NEXUS,
		BOX,
		FAIRY_CODE,
		MINIGAME,
		QUETZAL
	}

	@Builder.Default
	Set<Integer> itemIds = Set.of();
	/** A worn item's options carry no item id, only its name as the target. */
	@Builder.Default
	Set<String> itemNames = Set.of();
	@Builder.Default
	Set<Integer> objectIds = Set.of();
	@Builder.Default
	Set<Integer> npcIds = Set.of();
	/** NPCs by name as {@link MenuLabels#normalise} gives it: the step's own NPC, whose ids core knows and we don't. */
	@Builder.Default
	Set<String> npcNames = Set.of();
	/** Interface components whose options count, by widget id (a scroll book's entry). */
	@Builder.Default
	Set<Integer> widgetIds = Set.of();
	@Builder.Default
	List<String> path = List.of();
	@Builder.Default
	Line line = Line.LABEL;
	/** Set by the line factories below: a struct id, a box line index or a Quetzal table id. */
	int lineId;
	/** Set by the line factories below: a map region shield or a fairy ring code. */
	String lineKey;
	/** Set by the line factories below: the cache's name of a nexus destination, or a minigame. */
	String lineName;
	/** The same landing through another house menu (the jewellery box for the glory), so its lines are coloured too. */
	@Builder.Default
	List<MenuTarget> alternatives = List.of();

	/** A nexus line: its struct id, the map region shield, and the cache's name of the destination. */
	public static MenuTarget nexus(int structId, String region, String placeName)
	{
		return builder().line(Line.NEXUS).lineId(structId).lineKey(region).lineName(placeName).build();
	}

	/** A jewellery box line by its index. */
	public static MenuTarget box(int lineIndex)
	{
		return builder().line(Line.BOX).lineId(lineIndex).build();
	}

	/** The fairy ring dials on a code. */
	public static MenuTarget fairyCode(String code)
	{
		return builder().line(Line.FAIRY_CODE).lineKey(code).build();
	}

	/** A minigame's card by its name. */
	public static MenuTarget minigame(String name)
	{
		return builder().line(Line.MINIGAME).lineName(name).build();
	}

	/** A quetzal map site by its Quetzal table id. */
	public static MenuTarget quetzal(int tableId)
	{
		return builder().line(Line.QUETZAL).lineId(tableId).build();
	}

	public boolean isEmpty()
	{
		return itemIds.isEmpty() && objectIds.isEmpty() && npcIds.isEmpty() && path.isEmpty() && line == Line.LABEL;
	}

	public String destination()
	{
		return path.isEmpty() ? null : path.get(path.size() - 1);
	}
}

package com.cluehelper.guide;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Client thread only. An obelisk takes two clicks: Set Destination and its list line, then Teleport to Destination.
 * The list was open on the target's line: its closing means the destination is set.
 */
@Singleton
final class ObeliskDestination
{
	private boolean listSeen;
	private String setFor;

	@Inject
	ObeliskDestination()
	{
	}

	/**
	 * Call every tick. {@code watching} while the step's menu target is the obelisk's list line; {@code showing} while
	 * that list is open on it.
	 *
	 * @return whether the destination was just set for {@code rowName}
	 */
	boolean onGameTick(boolean watching, boolean showing, String rowName)
	{
		if (!watching)
		{
			listSeen = false;
			return false;
		}
		if (showing)
		{
			listSeen = true;
			return false;
		}
		if (!listSeen)
		{
			return false;
		}
		listSeen = false;
		setFor = rowName;
		return true;
	}

	boolean isSetFor(String rowName)
	{
		return rowName.equals(setFor);
	}

	void clear()
	{
		listSeen = false;
		setFor = null;
	}
}

package com.cluehelper.guide;

import java.util.Set;

final class OneClick
{
	/** Left clicks of teleport items that don't teleport. */
	private static final Set<String> NOT_TELEPORTS = Set.of("wield", "wear", "equip", "remove", "use", "drop", "examine", "check",
		"inspect", "read");

	private OneClick()
	{
	}

	static boolean teleportsTo(String option, String destination)
	{
		return option != null && destination != null && !MenuLabels.isOpener(option) && MenuLabels.matches(option, destination);
	}

	/**
	 * An item with one destination names no option in its row ("Skull sceptre" left-clicks "Invoke" or "Teleport"), so
	 * any left click that is an action of its own is its teleport: with one destination there is no list to open.
	 */
	static boolean isOwnTeleport(String option)
	{
		return option != null && !NOT_TELEPORTS.contains(MenuLabels.normalise(option));
	}
}

package com.cluehelper.guide;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.widgets.Widget;

@Singleton
public class QuetzalIcons
{
	private static final int MOST_PIXELS_OFF = 24;

	private final Client client;
	private Map<Integer, int[]> positions;

	@Inject
	QuetzalIcons(Client client)
	{
		this.client = client;
	}

	/** The first call reads the cache, so it must be on the client thread. */
	public int[] position(int quetzalTableId)
	{
		if (positions == null)
		{
			positions = read();
		}
		return positions.get(quetzalTableId);
	}

	private Map<Integer, int[]> read()
	{
		Map<Integer, int[]> out = new HashMap<>();
		List<Integer> rows = client.getDBTableRows(DBTableID.Quetzal.ID);
		for (int row : rows == null ? List.<Integer>of() : rows)
		{
			Object[] id = client.getDBTableField(row, DBTableID.Quetzal.COL_ID, 0);
			Object[] x = client.getDBTableField(row, DBTableID.Quetzal.COL_IF_X_POS, 0);
			Object[] y = client.getDBTableField(row, DBTableID.Quetzal.COL_IF_Y_POS, 0);
			if (isInt(id) && isInt(x) && isInt(y))
			{
				out.put((Integer) id[0], new int[]{(Integer) x[0], (Integer) y[0]});
			}
		}
		return out;
	}

	static Widget nearest(Widget[] icons, int[] at)
	{
		Widget best = null;
		int bestOff = MOST_PIXELS_OFF + 1;
		for (Widget icon : icons == null ? new Widget[0] : icons)
		{
			if (icon == null || icon.isHidden())
			{
				continue;
			}
			int x = icon.getOriginalX();
			int y = icon.getOriginalY();
			int off = Math.min(off(x, y, at), off(x + icon.getWidth() / 2, y + icon.getHeight() / 2, at));
			if (off < bestOff)
			{
				best = icon;
				bestOff = off;
			}
		}
		return best;
	}

	private static int off(int x, int y, int[] at)
	{
		return Math.max(Math.abs(x - at[0]), Math.abs(y - at[1]));
	}

	private static boolean isInt(Object[] field)
	{
		return field != null && field.length > 0 && field[0] instanceof Integer;
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.Book;
import com.cluehelper.player.HouseState;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.player.PositionRules;
import com.cluehelper.player.RuneModel;
import com.cluehelper.player.Spell;
import com.cluehelper.transport.AvailabilityEngine;
import com.cluehelper.transport.AvailabilityService;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.Category;
import com.cluehelper.transport.HouseNeed;
import com.cluehelper.transport.RowAvailability;
import com.cluehelper.transport.SpellbookChange;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;

/** What to click for a catalog row: its object or NPC and menu path, its held items, or its spell's button. Client thread only. */
@Slf4j
@Singleton
final class RowTargets
{
	static final String SIGNAL_OPTION = "Signal";

	private static final String TRAVEL_OPTION = "Travel";
	private static final String TREE_OPTION = "Tree";
	private static final String SPELLBOOK_OPTION = "Spellbook";
	/** Between a menu cell's option and the list line it opens. */
	static final String MENU_STEP = " > ";
	private static final int PARAM_SPELL_WIDGET = 596;
	/** Catalog landings spread 0–2 tiles, so another menu's line within this lands at the same place. */
	private static final int SAME_LANDING_TILES = 3;
	/** The patch objects are multilocs on their transmit varbits; the grown tree is the form they show. */
	private static final Set<Integer> PLANTED_SPIRIT_TREES = Set.of(ObjectID.FARMING_SPIRIT_TREE_PATCH_1,
		ObjectID.FARMING_SPIRIT_TREE_PATCH_2, ObjectID.FARMING_SPIRIT_TREE_PATCH_3, ObjectID.FARMING_SPIRIT_TREE_PATCH_4,
		ObjectID.FARMING_SPIRIT_TREE_PATCH_5, ObjectID.SPIRIT_TREE_FULLYGROWN);
	/** Minigame Teleport is a spell on every book, so it is cast rather than picked from the Grouping tab. */
	private static final Map<Book, Integer> MINIGAME_SPELLS = Map.of(
		Book.STANDARD, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_STANDARD,
		Book.ANCIENT, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ANCIENT,
		Book.LUNAR, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_LUNAR,
		Book.ARCEUUS, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ARCEUUS);

	private final Client client;
	private final PlayerModel player;
	private final AvailabilityService availability;
	private final Map<String, Integer> spellWidgets = new HashMap<>();

	@Inject
	RowTargets(Client client, PlayerModel player, AvailabilityService availability)
	{
		this.client = client;
		this.player = player;
		this.availability = availability;
	}

	/** The row's object or NPC, with the menu its catalog line names. */
	MenuTarget located(CatalogRow row)
	{
		MenuTarget.MenuTargetBuilder target = MenuTarget.builder().objectIds(objectsOf(row));
		String menu = row.getMenu();
		if (menu == null)
		{
			return target.build();
		}
		String[] parts = menu.split(" ", 2);
		boolean outside = !row.isInHouse();
		switch (parts[0])
		{
			case "quetzal":
				return MenuTarget.quetzal(row.quetzalTableId()).toBuilder().objectIds(objectsOf(row))
					.npcIds(Set.of(NpcID.QUETZAL_CHILD_GREEN)).path(List.of(TRAVEL_OPTION)).build();
			case "list":
				return target.path(listPath(row, outside, parts[1])).build();
			case "nexus":
			{
				String[] nexus = parts[1].split(" ", 2);
				return MenuTarget.nexus(Integer.parseInt(nexus[0]), nexus[1], row.nexusPlace()).toBuilder()
					.objectIds(objectsOf(row)).build();
			}
			case "box":
				return MenuTarget.box(Integer.parseInt(parts[1])).toBuilder().objectIds(objectsOf(row)).build();
			case "npc":
				return MenuTarget.builder().npcIds(Set.of(row.getObjectId())).path(List.of(parts[1].split(MENU_STEP))).build();
			default:
				return target.path(List.of(parts[1].split(MENU_STEP))).build();
		}
	}

	/** The teleport's object, with the house furniture that lands at the same place as alternatives. */
	MenuTarget locatedTeleport(SubStep teleport)
	{
		return located(teleport.getRow()).toBuilder().alternatives(sameLanding(teleport)).build();
	}

	/** The held items with the teleport's option, or Signal for a quetzal; house furniture landing there as alternatives. */
	MenuTarget heldTeleport(SubStep teleport, Set<Integer> held)
	{
		CatalogRow row = teleport.getRow();
		MenuTarget.MenuTargetBuilder target = row.isQuetzalMap()
			? MenuTarget.quetzal(row.quetzalTableId()).toBuilder().path(List.of(SIGNAL_OPTION))
			: MenuTarget.builder().path(optionPath(row));
		return withItems(target, held).alternatives(sameLanding(teleport)).build();
	}

	MenuTarget heldBookChange(Set<Integer> held, Book book)
	{
		return withItems(MenuTarget.builder(), held).path(List.of(SPELLBOOK_OPTION, book.label())).build();
	}

	MenuTarget houseBookChange(SpellbookChange change, Book book)
	{
		return MenuTarget.builder().objectIds(Set.of(change.getObjectId())).path(List.of(SPELLBOOK_OPTION, book.label())).build();
	}

	MenuTarget plantedTree(Set<Integer> treeIds, String line)
	{
		return MenuTarget.builder().objectIds(treeIds).path(List.of(TRAVEL_OPTION, TREE_OPTION, line)).build();
	}

	MenuTarget items(Set<Integer> itemIds, String option)
	{
		return withItems(MenuTarget.builder(), itemIds).path(List.of(option)).build();
	}

	/** The options after the row name's item: "Ardougne cloak: Kandarin Monastery" is Kandarin Monastery. */
	List<String> optionPath(CatalogRow row)
	{
		String[] parts = row.getName().split(": ");
		return parts.length < 2 ? List.of() : List.of(parts).subList(1, parts.length);
	}

	boolean hasOneDestination(SubStep current)
	{
		return current != null && current.getKind() == SubStep.Kind.TELEPORT && current.getRow() != null
			&& optionPath(current.getRow()).isEmpty();
	}

	/** The row's carried items; runes are left out, as the spell widget covers those. */
	List<ItemUse> heldUses(CatalogRow row)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		RuneModel runes = player.getRuneModel();
		if (snapshot == null || runes == null)
		{
			return List.of();
		}
		RowAvailability judged = new AvailabilityEngine(runes, id -> "").judge(row, snapshot, AvailabilityService.nowMinutes());
		return judged.getWitness().stream()
			.filter(use -> use.getContainer().isCarried())
			.filter(use -> !runes.isRune(use.getItemId()))
			.collect(Collectors.toUnmodifiableList());
	}

	List<ItemUse> heldUses(SpellbookChange change)
	{
		return heldUses(CatalogRow.builder().name(change.getName()).requirements(change.getRequirements()).build());
	}

	/** -1 when none is known. */
	int spellWidget(CatalogRow row)
	{
		RuneModel runes = player.getRuneModel();
		if (runes == null)
		{
			return -1;
		}
		return spellWidgets.computeIfAbsent(row.getName(), name ->
		{
			String spellName = spellName(name);
			Book book = row.getRequirements().getBook();
			for (Spell spell : runes.getSpells())
			{
				if (spell.getName().equalsIgnoreCase(spellName) && (book == null || spell.getBook() == book))
				{
					int widget = client.getItemDefinition(spell.getObj()).getIntValue(PARAM_SPELL_WIDGET);
					return widget > 0 ? widget : -1;
				}
			}
			log.debug("no spell widget for {}", name);
			return -1;
		});
	}

	int minigameSpellWidget(Book book)
	{
		return MINIGAME_SPELLS.getOrDefault(book, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_STANDARD);
	}

	private MenuTarget.MenuTargetBuilder withItems(MenuTarget.MenuTargetBuilder target, Set<Integer> itemIds)
	{
		Set<String> names = itemIds.stream().map(id -> MenuLabels.normalise(client.getItemDefinition(id).getName()))
			.collect(Collectors.toUnmodifiableSet());
		return target.itemIds(itemIds).itemNames(names);
	}

	private List<MenuTarget> sameLanding(SubStep current)
	{
		WorldPoint landing = current.getGoal();
		PlayerSnapshot snapshot = player.getSnapshot();
		if (landing == null || snapshot == null)
		{
			return List.of();
		}
		List<MenuTarget> same = new ArrayList<>();
		for (RowAvailability judged : availability.getCarried().available())
		{
			CatalogRow row = judged.getRow();
			boolean house = row.isInHouse() && row.getMenu() != null;
			if (house && row != current.getRow() && row.getDestination() != null
				&& PositionRules.near(row.getDestination(), landing, SAME_LANDING_TILES))
			{
				same.add(located(row));
			}
		}
		return List.copyOf(same);
	}

	/** On the house's spiritual fairy tree "Ring-configure" opens a list too, so the Tree option is named. */
	private static List<String> listPath(CatalogRow row, boolean outside, String line)
	{
		if (outside)
		{
			return List.of(TRAVEL_OPTION, line);
		}
		return row.getCategory() == Category.SPIRIT_TREE ? List.of(TREE_OPTION, line) : List.of(line);
	}

	private static Set<Integer> objectsOf(CatalogRow row)
	{
		HouseNeed need = row.isInHouse() ? row.getRequirements().getHouse() : null;
		if (need != null)
		{
			return Set.copyOf(need.getKind() == HouseNeed.Kind.NEXUS ? HouseState.NEXUS_OBJECTS : need.getIds());
		}
		if (row.getObjectId() == ObjectID.SPIRIT_TREE_FULLYGROWN)
		{
			return PLANTED_SPIRIT_TREES;
		}
		return row.getObjectId() < 0 ? Set.of() : Set.of(row.getObjectId());
	}

	private static String spellName(String rowName)
	{
		String name = rowName;
		int colon = name.indexOf(':');
		if (colon >= 0)
		{
			name = name.substring(0, colon);
		}
		int bracket = name.indexOf(" (");
		return bracket >= 0 ? name.substring(0, bracket) : name;
	}
}

