	private void onPlan(Plan plan)
	{
		PlanStart start = routes.getStart();
		Step step = routes.travelStep();
		boolean noWalk = start != null && start.getKind() == PlanStart.Kind.TELEPORT_ONLY;
		boolean partWay = start != null && step != null && step.getData().getEntry() != null
			&& step.getData().getEntry().isPartWay(start.getTile());
		SubStep goIn = noWalk || partWay ? SubSteps.goingIn(step, start.getTile()) : null;
		boolean inside = noWalk && goIn == null && isInsideWayIn(step, start.getTile());
		if (goIn != null || inside)
		{
			// On a way in with no walk nodes (the Agility Pyramid's course and top): keep going, never teleport out
			if (route != null || routeStep == null || !routeStep.getKey().equals(step.getKey()) || steps.isEmpty())
			{
				route = null;
				routeStep = step;
				steps = inWayIn(step, goIn);
				index = 0;
				updateHighlights();
				refreshObjects();
				notifyListeners();
			}
			return;
		}
		Route committed = routes.getCommitted();
		if (isTravelling())
		{
			waiting = new Waiting(committed, player.getPosition().getTile());
			return;
		}
		follow(committed);
	}

	/** Call from a PostMenuSort handler that runs after Menu Entry Swapper's. */
	public void onPostMenuSort()
	{
		if (client.isMenuOpen() || client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length > 0 && leftClicks.learn(entries[entries.length - 1]))
		{
			highlights = stepHighlights.withItemFill(highlights, getCurrent(), routeStep);
			scene = scene.toBuilder().fillObjects(stepHighlights.fillObjects(scene.getObjects(), highlights))
				.fillNpcs(stepHighlights.fillNpcs(scene.getNpcs(), scene.getNpcOption())).build();
		}
	}

	/** Call from a GameTick handler that runs after the planner's. */
	public void onGameTick()
	{
		WorldPoint tile = player.getPosition().getTile();
		boolean jumped = PositionRules.teleported(lastTile, tile);
		lastTile = tile;
		jumpedThisSubStep |= jumped;
		if (jumped)
		{
			actReachedStepKey = null;
		}
		// Before the early returns below: a follow on every tick near the step would starve them (a deposit never seen)
		actWatcher.onGameTick(routeStep);
		deposit.onGameTick(tile);
		boolean changed = false;
		if (waiting != null && !isTravelling())
		{
			Waiting next = waiting;
			boolean stale = PositionRules.teleported(next.getFrom(), tile);
			waiting = null;
			if (!stale)
			{
				follow(next.getRoute());
				return;
			}
		}
		if (routeStep != null && !isAtStep() && arrived(routeStep))
		{
			follow(route);
			return;
		}
		changed |= advance(tile);
		changed |= refreshFight();
		changed |= refreshBox();
		changed |= watchDestinationSet();
		changed |= keyFromCharterList();
		changed |= partWayIn(tile);
		changed |= pickUpForAct(tile);
		changed |= refreshGear();
		changed |= showMaking();
		checkRefusal();
		checkTeleportRefusal();
		if (changed)
		{
			updateHighlights();
		}
		refreshObjects();
		highlights = stepHighlights.refreshed(highlights, getCurrent(), routeStep);
		if (changed)
		{
			notifyListeners();
		}
	}

	private void refreshObjects()
	{
		SubStep current = getCurrent();
		boolean bank = isBankStop();
		List<String> option = current == null || current.getOption() == null ? List.of() : List.of(current.getOption());
		MenuTarget target = outlineTarget(current, option);
		boolean ownOption = !option.isEmpty() && highlights.getMenuTarget() == MenuTarget.NONE;
		highlights = highlights.toBuilder().optionTarget(ownOption ? target : MenuTarget.NONE).build();
		if (target.getObjectIds().isEmpty() && target.getNpcIds().isEmpty() && !bank)
		{
			scene = scene.toBuilder().objects(List.of()).npcs(List.of()).fillObjects(List.of()).fillNpcs(List.of()).build();
			return;
		}
		int tick = client.getTickCount();
		boolean nothingYet = scene.isEmpty() && scene.getEmptySearches() < OBJECT_REFRESH_TICKS;
		if (scene.getFoundTick() == ActWatcher.NEVER || nothingYet || tick - scene.getFoundTick() >= OBJECT_REFRESH_TICKS)
		{
			scene = searchScene(current, target, bank, tick);
		}
	}

	/**
	 * What the scene is searched for: the sub-step's own NPCs or objects with its option, the furniture a walk leads to,
	 * the STASH unit the next act searches, else the menu target's objects.
	 */
	private MenuTarget outlineTarget(SubStep current, List<String> option)
	{
		if (current != null && !current.getNpcIds().isEmpty())
		{
			return MenuTarget.builder().npcIds(current.getNpcIds()).path(option).build();
		}
		if (current != null && !current.getObjectIds().isEmpty())
		{
			return MenuTarget.builder().objectIds(current.getObjectIds()).path(option).build();
		}
		if (current != null && !current.getNpcNames().isEmpty())
		{
			return MenuTarget.builder().npcNames(current.getNpcNames()).path(option).build();
		}
		if (isApproach())
		{
			return rowTargets.located(getNext().getRow());
		}
		int stash = stashAhead();
		return stash != StepRequirements.NO_STASH ? MenuTarget.builder().objectIds(Set.of(stash)).build() : highlights.getMenuTarget();
	}

	/** The objects and NPCs found now, with the ones a left click uses filled. */
	private SceneHighlights searchScene(SubStep current, MenuTarget target, boolean bank, int tick)
	{
		List<TileObject> objects = bank ? sceneObjects.banksNear(current.getWaypoint(), BANK_TILES) : sceneObjects.find(target.getObjectIds());
		List<NPC> npcs = bank ? sceneObjects.bankersNear(current.getWaypoint(), BANK_TILES) : npcsFor(target);
		if (!bank)
		{
			colourCrewMenus(target, npcs);
		}
		String npcOption = bank || target.getPath().isEmpty() ? null : target.getPath().get(0);
		return SceneHighlights.builder().foundTick(tick)
			.emptySearches(scene.getFoundTick() == ActWatcher.NEVER ? 0 : scene.getEmptySearches() + 1)
			.objects(objects).npcs(npcs).fillObjects(bank ? List.of() : stepHighlights.fillObjects(objects, highlights))
			.npcOption(npcOption).fillNpcs(stepHighlights.fillNpcs(npcs, npcOption)).build();
	}

	/**
	 * Shortest Path names one NPC per ride (a charter's Trader Crewmember), but a port's crew have several ids: when the
	 * named one isn't there, an NPC of the same name near the boarding tile with the ride's option is it, else any NPC
	 * there with that option (Port Sarim's boat to Port Piscarilius is Cabin Boy Herbert's, not Veos'). Its menu is
	 * coloured too.
	 */
	private List<NPC> npcsFor(MenuTarget target)
	{
		List<NPC> named = sceneObjects.npcs(target.getNpcIds());
		WorldPoint boarding = isApproach() ? getNext().getWaypoint() : getCurrent().getWaypoint();
		if (!named.isEmpty() || target.getNpcIds().isEmpty() || target.getPath().isEmpty() || boarding == null)
		{
			return named;
		}
		String name = client.getNpcDefinition(target.getNpcIds().iterator().next()).getName();
		List<NPC> offering = sceneObjects.npcsNear(boarding, RIDE_NPC_TILES, target.getPath().get(0));
		List<NPC> sameName = offering.stream().filter(npc -> npc.getName() != null && npc.getName().equalsIgnoreCase(name))
			.collect(Collectors.toUnmodifiableList());
		return sameName.isEmpty() ? offering : sameName;
	}

	/** NPCs found by name rather than id stand in for the named one in its menu too: their ids join the target's. */
	private void colourCrewMenus(MenuTarget target, List<NPC> npcs)
	{
		MenuTarget menuTarget = highlights.getMenuTarget();
		Set<Integer> ids = new HashSet<>(target.getNpcIds());
		npcs.forEach(npc -> ids.add(npc.getId()));
		if (ids.size() > target.getNpcIds().size() && menuTarget.getNpcIds().equals(target.getNpcIds()))
		{
			highlights = highlights.toBuilder().menuTarget(menuTarget.toBuilder().npcIds(Set.copyOf(ids)).build()).build();
		}
	}

	private static boolean isInsideWayIn(Step step, WorldPoint at)
	{
		StepIndex.WayIn way = step == null ? null : step.getData().getEntry();
		return way != null && way.isInside(at);
	}

	/** Going in (or already in): the rest of the way, then the clue's own sub-steps. */
	private List<SubStep> inWayIn(Step step, SubStep goIn)
	{
		List<SubStep> rest = new ArrayList<>();
		if (goIn != null)
		{
			rest.add(goIn);
		}
		if (!step.getTargets().isEmpty())
		{
			rest.add(SubStep.builder().kind(SubStep.Kind.WALK_TO_CLUE).text("Walk to the clue").goal(step.getTargets().get(0))
				.radius(SubSteps.ARRIVE_TILES).build());
		}
		rest.addAll(subSteps.acts(step));
		return SubSteps.withWayInEquipped(rest, step.getData());
	}

	/** Part way up a way in (the pyramid's lower levels), the step points on, not back to its ground-floor start. */
	private boolean partWayIn(WorldPoint tile)
	{
		SubStep current = getCurrent();
		boolean onWay = current != null && current.getKind() == SubStep.Kind.ENTER && current.getWayIn().isPartWay(tile);
		pickUpTiles = onWay && current.getWayIn().getPickUp() != null ? groundItemTiles(current.getWayIn().getPickUp().getId()) : List.of();
		if (onWay && current.getWayIn().getPickUp() != null)
		{
			return pickUpOnTheWay(current, current.getWayIn().getPickUp(), tile);
		}
		boolean partWay = onWay && !current.getText().startsWith(KEEP_GOING);
		if (!partWay)
		{
			return false;
		}
		WorldPoint to = current.getWayIn().getTo();
		boolean toNearby = !current.getWayIn().isNoLine() && to != null && tile != null && to.getPlane() == tile.getPlane()
			&& to.distanceTo2D(tile) <= PART_WAY_LINE_TILES;
		return replaceCurrent(current.toBuilder().text(KEEP_GOING + current.getWayIn().getText()).waypoint(toNearby ? to : null).build());
	}

	/** Part way in, the ground items to pick up first (the Mogre Camp's rocks): to the nearest, then on through the way. */
	private boolean pickUpOnTheWay(SubStep current, StepIndex.PickUp pickUp, WorldPoint tile)
	{
		int counted = pickUp.getVarbit() < 0 ? 0 : client.getVarbitValue(pickUp.getVarbit());
		int carried = Math.min(pickUp.getCount(), Math.max(counted, carriedCount(pickUp.getId())));
		boolean done = carried >= pickUp.getCount();
		return replaceCurrent(current.toBuilder()
			.text(done ? KEEP_GOING + pickUp.getThen() : "Pick up " + pickUp.getCount() + " " + pickUp.getName() + " (" + carried + "/" + pickUp.getCount() + ")")
			.detail(null).waypoint(done ? current.getWayIn().getTo() : nearest(tile)).build());
	}

	/** An act's ground item (king worms): outlined where it lies, the nearest as the waypoint. */
	private boolean pickUpForAct(WorldPoint tile)
	{
		SubStep current = getCurrent();
		if (current == null || current.getKind() != SubStep.Kind.ACT || current.getGroundItem() < 0)
		{
			return false;
		}
		pickUpTiles = groundItemTiles(current.getGroundItem());
		return replaceCurrent(current.toBuilder().waypoint(nearest(tile)).build());
	}

	/** The pick-up tile nearest the player; null with no tile or none to pick up. */
	private WorldPoint nearest(WorldPoint tile)
	{
		return tile == null ? null : pickUpTiles.stream().min(Comparator.comparingInt(at -> at.distanceTo2D(tile))).orElse(null);
	}

	private int carriedCount(int itemId)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		return snapshot == null ? 0 : snapshot.count(Container.INVENTORY, itemId);
	}

	/** Client thread. Every loaded tile on the player's floor with that item on the ground. */
	private List<WorldPoint> groundItemTiles(int itemId)
	{
		WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			return List.of();
		}
		List<WorldPoint> found = new ArrayList<>();
		Tile[][] tiles = view.getScene().getTiles()[view.getPlane()];
		for (Tile[] column : tiles)
		{
			for (Tile tile : column)
			{
				List<TileItem> items = tile == null ? null : tile.getGroundItems();
				if (items != null && items.stream().anyMatch(item -> item.getId() == itemId))
				{
					found.add(tile.getWorldLocation());
				}
			}
		}
		return List.copyOf(found);
	}

	public List<WorldPoint> getPickUpTiles()
	{
		return pickUpTiles;
	}

	/** The charter list's key for the port is known only once it is open: the step's text names it from then on. */
	private boolean keyFromCharterList()
	{
		char key = menuLines.charterKey(highlights.getMenuTarget());
		SubStep current = getCurrent();
		if (key == 0 || current == null || current.getText().contains(MenuLines.keyText(key)))
		{
			return false;
		}
		return replaceCurrent(current.toBuilder().text(LegSteps.withKey(current.getText(), key)).build());
	}

	private boolean watchDestinationSet()
	{
		MenuTarget menuTarget = highlights.getMenuTarget();
		List<String> path = menuTarget.getPath();
		SubStep current = getCurrent();
		boolean watching = current != null && current.getRow() != null && path.size() == 2 && SET_DESTINATION.equals(path.get(0));
		return obelisk.onGameTick(watching, watching && menuLines.showing(menuTarget), watching ? current.getRow().getName() : null);
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.HOPPING)
		{
			scene = SceneHighlights.NONE;
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			scene = scene.toBuilder().foundTick(ActWatcher.NEVER).build();
			refreshObjects();
		}
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		SubStep current = getCurrent();
		if (current == null || current.getKind() != SubStep.Kind.TELEPORT || current.getRow() == null)
		{
			return;
		}
		MenuTarget menuTarget = highlights.getMenuTarget();
		boolean onItem = menuTarget.getItemIds().contains(event.getItemId())
			|| menuTarget.getItemNames().contains(MenuLabels.normalise(event.getMenuTarget()));
		boolean onObject = menuTarget.getObjectIds().contains(event.getId());
		if (onItem || onObject)
		{
			teleportRefusal.clicked(client.getTickCount(), player.getPosition().getTile());
		}
	}

	/** MESBOX lines during a book change are the refusal backstop. */
	public void onChatMessage(ChatMessage message)
	{
		SubStep current = getCurrent();
		boolean gameLine = message.getType() == ChatMessageType.GAMEMESSAGE || message.getType() == ChatMessageType.MESBOX;
		if (gameLine && current != null && current.getKind() == SubStep.Kind.TELEPORT && current.getRow() != null)
		{
			teleportRefusal.onGameLine(current.getRow().getName(), client.getTickCount());
		}
		if (message.getType() != ChatMessageType.MESBOX || current == null || current.getChange() == null)
		{
			return;
		}
		String text = Text.removeTags(message.getMessage());
		if (text.contains(CAPE_LIMIT_TEXT))
		{
			routes.onCapeChangesRefused();
			return;
		}
		changeRefusal.suspect(current.getChange().getName(), current.getBook(), client.getTickCount());
	}

	private void checkTeleportRefusal()
	{
		Player local = client.getLocalPlayer();
		SubStep current = getCurrent();
		String currentRow = current == null || current.getRow() == null ? null : current.getRow().getName();
		boolean standingStill = local != null && local.getAnimation() == NO_ANIMATION;
		String refused = teleportRefusal.refused(client.getTickCount(), currentRow, player.getPosition().getTile(), standingStill);
		if (refused != null)
		{
			log.debug("teleport refused: {}", refused);
			routes.onRowRefused(refused);
		}
	}

	private void checkRefusal()
	{
		String refused = changeRefusal.refused(client.getTickCount(), client.getVarbitValue(VarbitID.SPELLBOOK));
		if (refused != null)
		{
			routes.onRowRefused(refused);
		}
	}

	private void follow(Route committed)
	{
		Step step = routes.travelStep();
		WorldPoint tile = player.getPosition().getTile();
		noteDeposit(routeStep, step);
		if (routeStep == null || step == null || !routeStep.getKey().equals(step.getKey()))
		{
			stepSince = client.getTickCount();
		}
		route = committed;
		routeStep = step;
		boolean atStep = step != null && (stillAtAct(step, tile) || arrived(step));
		List<SubStep> base = step == null || committed == null && !atStep ? List.of() : atStep ? actsHere(step, tile)
			: subSteps.of(committed, step);
		steps = deposit.before(base, tile);
		index = 0;
		jumpedThisSubStep = false;
		advance(tile);
		refreshGear();
		showMaking();
		updateHighlights();
		refreshObjects();
		notifyListeners();
	}

	private boolean refreshFight()
	{
		SubStep act = index < steps.size() ? steps.get(index) : null;
		SubStep view = null;
		SubStep again = null;
		if (act != null && act.isFights())
		{
			NPC enemy = actWatcher.getEnemy();
			if (enemy != null)
			{
				boolean emote = act.getDone() == SubStep.Done.URI_HERE;
				view = SubStep.builder().kind(SubStep.Kind.ACT).text("Kill the " + (enemy.getName() == null ? "enemy" : enemy.getName()))
					.detail(emote ? "Stay equipped" : null).build();
				again = act.toBuilder().text(act.getAgain()).build();
			}
			else if (actWatcher.foughtSince(stepSince))
			{
				view = act.toBuilder().text(act.getAgain()).build();
			}
		}
		Fight next = view == null ? null : new Fight(view, again);
		boolean changed = !Objects.equals(next, fight);
		fight = next;
		return changed;
	}

	private void noteDeposit(Step ended, Step next)
	{
		boolean emote = ended != null && ClueTypes.EMOTE.equals(ended.getType()) && ended.getData().getStash() != null;
		boolean takenFromStash = actWatcher.holdsStashItems(stepSince);
		if (!emote || !takenFromStash || next != null && ended.getKey().equals(next.getKey()))
		{
			return;
		}
		StashMemory.State stash = stepNeeds.of(ended).getStash();
		List<String> back = itemsToPutBack(ended);
		if ((stash == StashMemory.State.FILLED || stash == StashMemory.State.EMPTY) && !back.isEmpty())
		{
			int stashId = ended.getRequirements() == null ? StepRequirements.NO_STASH : ended.getRequirements().getStashObjectId();
			deposit.start(ended.getData().getStash().getTile(), stashId, back, client.getTickCount());
		}
	}

	/** The ended emote's items still on the player, by the names of the ones carried; none once all are put back. */
	private List<String> itemsToPutBack(Step ended)
	{
		if (ended.getRequirements() == null)
		{
			return List.of();
		}
		Set<Integer> carried = player.carriedIds();
		List<String> back = new ArrayList<>();
		for (ItemRequirement need : ended.getRequirements().getItems())
		{
			carried.stream().filter(need::fulfilledBy).findFirst().ifPresent(id -> back.add(client.getItemDefinition(id).getName()));
		}
		return List.copyOf(back);
	}

	private boolean advance(WorldPoint tile)
	{
		boolean moved = false;
		while (index < steps.size() && isComplete(steps.get(index), tile))
		{
			index++;
			jumpedThisSubStep = false;
			moved = true;
		}
		SubStep current = index < steps.size() ? steps.get(index) : null;
		if (current != null && current.getKind() == SubStep.Kind.ACT && routeStep != null)
		{
			actReachedStepKey = actKey(routeStep);
		}
		return moved;
	}

	private boolean stillAtAct(Step step, WorldPoint tile)
	{
		return actKey(step).equals(actReachedStepKey) && tile != null
			&& step.getTargets().stream().anyMatch(target -> target.distanceTo2D(tile) <= STAY_AT_ACT_TILES);
	}

	/**
	 * Arrived where the planner can't see it: the step's NPC is in the scene a short walk away (Brimstail inside his
	 * cave, where core's tile is the entrance), or the player is beside a cache tile of the step core doesn't give. A
	 * step of several places or a probe trip never arrives this way: their NPCs and tiles belong to one stage.
	 */
	private boolean arrived(Step step)
	{
		PlanStart start = routes.getStart();
		WalkCosts walk = start == null ? null : start.getWalk();
		boolean parts = step.getStages().stream().allMatch(stage -> stage.getKind() == Stage.Kind.PART);
		if (walk == null || step.getWaypointAct() != null || !parts || ClueTypes.HOT_COLD.equals(step.getType()))
		{
			return false;
		}
		for (WorldPoint other : step.getOtherTiles())
		{
			if (walk.costNear(other) <= ARRIVED_WALK_TILES)
			{
				return true;
			}
		}
		if (step.getNpcs() == null || step.getNpcs().isEmpty() || client.getTopLevelWorldView() == null)
		{
			return false;
		}
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			WorldPoint at = npc.getWorldLocation();
			if (npc.getName() != null && step.getNpcs().contains(npc.getName()) && walk.costNear(at) <= ARRIVED_WALK_TILES)
			{
				return true;
			}
		}
		return false;
	}

	private List<SubStep> actsHere(Step step, WorldPoint tile)
	{
		SubStep stageAct = actHere(step, tile);
		return stageAct.getStage() != null ? SubSteps.stageActs(stageAct.getStage()) : subSteps.acts(step);
	}

	/** At a step of several places, the act of the stage nearest to the player. */
	private static SubStep actHere(Step step, WorldPoint tile)
	{
		Stage nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (Stage stage : step.getStages())
		{
			for (WorldPoint at : stage.getTiles())
			{
				int distance = tile == null || at.getPlane() != tile.getPlane() ? Integer.MAX_VALUE - 1 : at.distanceTo2D(tile);
				if (distance < nearestDistance)
				{
					nearest = stage;
					nearestDistance = distance;
				}
			}
		}
		return nearest == null || nearest.getKind() == Stage.Kind.FINAL ? Acts.act(step) : SubSteps.stageAct(nearest);
	}

	/** Each probe tile of a hot/cold step, and each stage left of a step of several places, is an act of its own. */
	private static String actKey(Step step)
	{
		return step.getKey() + "@" + step.getTargets();
	}

	/** The box shows the acts alone: nothing to travel. */
	public boolean isAtStep()
	{
		return !steps.isEmpty() && steps.stream().allMatch(sub -> sub.getKind() == SubStep.Kind.ACT);
	}

	private void clear()
	{
		route = null;
		routeStep = null;
		stepSince = ActWatcher.NEVER;
		actReachedStepKey = null;
		steps = List.of();
		index = 0;
		jumpedThisSubStep = false;
		lastTile = null;
		waiting = null;
		fight = null;
		boxView = null;
		pickUpTiles = List.of();
		deposit.clear();
		changeRefusal.clear();
		teleportRefusal.clear();
		obelisk.clear();
		highlights = Highlights.NONE;
		scene = SceneHighlights.NONE;
	}

	/** A teleport or book change is animating: its item, spell and tab are already used. */
	public boolean isTravelling()
	{
		SubStep current = getCurrent();
		Player local = client.getLocalPlayer();
		boolean acting = current != null && (current.isTravel() || current.getChange() != null);
		return acting && local != null && local.getAnimation() != NO_ANIMATION;
	}

	/** A walk to NPCs ends once one of them is rendered close by (an elf in Prifddinas), not at the planned tile. */
	private boolean stageNpcNearby(SubStep step, WorldPoint tile)
	{
		return !step.getNpcIds().isEmpty() && tile != null && scene.getNpcs().stream()
			.anyMatch(npc -> npc.getWorldLocation().getPlane() == tile.getPlane()
				&& npc.getWorldLocation().distanceTo2D(tile) <= SubSteps.AREA_ARRIVE_TILES);
	}

	private boolean isComplete(SubStep step, WorldPoint tile)
	{
		switch (step.getKind())
		{
			case WALK:
			case WALK_TO_CLUE:
				return step.getDone() == SubStep.Done.STASH_DEPOSITED && deposit.getAt() == null || PositionRules.near(tile, step.getGoal(), step.getRadius())
					|| step.getSpans().stream().anyMatch(place -> place.spans(tile)) || stageNpcNearby(step, tile);
			case WILDERNESS_EXIT:
				return tile != null && tile.getY() <= step.getGoal().getY();
			case TELEPORT:
			case FAIRY_RING:
			case EXIT:
				// Any floor: Shortest Path puts some landings on the wrong one (the diary cape's Kaleb, Slepe)
				return jumpedThisSubStep && tile != null && tile.distanceTo2D(step.getGoal()) <= step.getRadius();
			case ENTER:
				return step.getWayIn().isInside(tile);
			case SPELLBOOK_SWAP:
			case CHANGE_BOOK:
				return client.getVarbitValue(VarbitID.SPELLBOOK) == step.getBook().ordinal();
			case BANK:
				return bankMemory.isBankOpen();
			case WITHDRAW:
				return !bankMemory.isBankOpen();
			case ACT:
				return isActDone(step);
			default:
				throw new IllegalArgumentException("unhandled sub-step kind " + step.getKind());
		}
	}

	private boolean isActDone(SubStep act)
	{
		switch (act.getDone())
		{
			case EQUIPPED:
			case WAY_IN_WORN:
			case GEAR_WORN:
			case SLOTS_EMPTY:
				return gearActs.isDone(act, routeStep);
			case STASH_DEPOSITED:
				return deposit.getAt() == null || actWatcher.isDone(act.getDone(), stepSince);
			case STASH_WITHDRAWN:
				return actWatcher.isDone(act.getDone(), stepSince) || !subSteps.takeFromStash(routeStep);
			case ITEM_CARRIED:
				return player.carriesItemNamed(act.getCarriedWhenDone());
			case ITEM_GONE:
				return !player.carriesItemNamed(act.getActItemNamed());
			case ITEM_HELD:
				return act.getHeldWhenDone().stream().anyMatch(player.carriedIds()::contains);
			default:
				return actWatcher.isDone(act.getDone(), stepSince);
		}
	}

	/** The scene is searched again for the new sub-step's objects and NPCs. */
	private void updateHighlights()
	{
		scene = SceneHighlights.NONE;
		highlights = stepHighlights.of(getCurrent(), routeStep);
	}

	/** Walking to the STASH unit the next act searches: it is outlined from the walk on, like a bank. */
	private int stashAhead()
	{
		SubStep current = getCurrent();
		SubStep next = getNext();
		return current != null && current.getKind() == SubStep.Kind.WALK && next != null ? stepHighlights.stashOf(next, routeStep) : StepRequirements.NO_STASH;
	}

	private boolean refreshBox()
	{
		SubStep act = index < steps.size() ? steps.get(index) : null;
		boolean talk = act != null && act.getKind() == SubStep.Kind.ACT && act.getActItemNamed() == null && routeStep != null
			&& routeStep.getNpcs() != null && act.getText().startsWith(TALK_TO)
			&& routeStep.getNpcs().contains(act.getText().substring(TALK_TO.length()));
		String box = talk ? carriedBox() : null;
		String npc = box == null ? null : act.getText().substring(TALK_TO.length());
		SubStep view = box == null ? null : act.toBuilder().text("Open the " + box + ", then talk to " + npc + " again")
			.actItemNamed(box).build();
		boolean changed = !Objects.equals(view, boxView);
		boxView = view;
		return changed;
	}

	private String carriedBox()
	{
		for (int id : player.inventoryIds())
		{
			String name = client.getItemDefinition(id).getName().toLowerCase(Locale.ROOT);
			for (String box : BOXES)
			{
				if (name.startsWith(box))
				{
					return box;
				}
			}
		}
		return null;
	}

	/** A gear act listing what to put on or take off now. */
	private boolean refreshGear()
	{
		SubStep current = getCurrent();
		return current != null && replaceCurrent(gearActs.refresh(current, routeStep));
	}

	/** The current sub-step rewritten; the caller's tick updates the highlights once for every change. */
	private boolean replaceCurrent(SubStep listed)
	{
		if (listed.equals(getCurrent()))
		{
			return false;
		}
		List<SubStep> updated = new ArrayList<>(steps);
		updated.set(index, listed);
		steps = List.copyOf(updated);
		return true;
	}

	/** A task act made in steps says the step it is at under the act. */
	private boolean showMaking()
	{
		SubStep current = getCurrent();
		String detail = current != null && current.isTask() ? taskActs.detail(routeStep) : null;
		return detail != null && replaceCurrent(current.toBuilder().detail(detail).build());
	}

	private void notifyListeners()
	{
		listeners.forEach(Runnable::run);
	}

	@Value
	private static class Waiting
	{
		Route route;
		/** Where the player stood when it came: a route from farther away than a step is stale. */
		WorldPoint from;
	}

	/** The fight shown while an enemy attacks, and the act to do again after it. */
	@Value
	private static class Fight
	{
		SubStep view;
		SubStep again;
	}
}

package com.cluehelper.guide;

import com.cluehelper.memory.BankMemory;
import com.cluehelper.player.Container;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.Exit;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import com.cluehelper.step.StepRequirements;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.Category;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.widgets.Widget;

/**
 * What the overlays mark for a sub-step: its items, tab, spell, menu target, and the one-click fill of the items,
 * objects and NPCs whose left click does what the step needs. Client thread only.
 */
@Singleton
final class StepHighlights
{
	private static final String SEARCH_OPTION = "Search";
	private static final String REMOVE_OPTION = "Remove";
	private static final String TELEPORT_TO_DESTINATION = "Teleport to Destination";
	private static final Set<Integer> FAIRY_RING_OBJECTS = Set.of(ObjectID.FAIRYRING_HOMEHUB, ObjectID.FAIRYRING_MINORHUB,
		ObjectID.POH_FAIRY_RING, ObjectID.POH_SPIRIT_RING);

	private final Client client;
	private final PlayerModel player;
	private final BankMemory bankMemory;
	private final LeftClicks leftClicks;
	private final RowTargets rowTargets;
	private final TaskActs taskActs;
	private final DepositReminder deposit;
	private final ObeliskDestination obelisk;

	@Inject
	StepHighlights(Client client, PlayerModel player, BankMemory bankMemory, LeftClicks leftClicks, RowTargets rowTargets,
		TaskActs taskActs, DepositReminder deposit, ObeliskDestination obelisk)
	{
		this.client = client;
		this.player = player;
		this.bankMemory = bankMemory;
		this.leftClicks = leftClicks;
		this.rowTargets = rowTargets;
		this.taskActs = taskActs;
		this.deposit = deposit;
		this.obelisk = obelisk;
	}

	Highlights of(SubStep current, Step step)
	{
		if (current == null)
		{
			return Highlights.NONE;
		}
		Highlights.HighlightsBuilder shown = Highlights.builder().objectOption(current.getOption()).bankItems(current.getBankItems().stream()
			.map(id -> bankMemory.onlyInBankedKit(id) ? ItemID.HUNTSMANS_KIT : id).collect(Collectors.toUnmodifiableSet()));
		switch (current.getKind())
		{
			case ACT:
				return actHighlights(shown, current, step);
			case EXIT:
				Exit exit = current.getExit();
				return shown.menuTarget(withDialogue(wayTarget(exit.getObjectId(), exit.getOption()), wayInOf(step, exit))).build();
			case ENTER:
				return shown.menuTarget(enterTarget(current)).build();
			case SPELLBOOK_SWAP:
				shown.spellWidget(InterfaceID.MagicSpellbook.SPELLBOOK_SWAP).tab(StepGuide.Tab.MAGIC);
				break;
			case TELEPORT:
				teleportHighlights(shown, current);
				break;
			case FAIRY_RING:
				if (current.getRow().getCode() != null)
				{
					shown.menuTarget(MenuTarget.fairyCode(current.getRow().getCode()).toBuilder().objectIds(FAIRY_RING_OBJECTS).build());
				}
				break;
			case CHANGE_BOOK:
				changeBookHighlights(shown, current);
				break;
			default:
				break;
		}
		return withOneClick(shown.build(), current);
	}

	/** The items that change as they are carried or put on, refreshed every tick. */
	Highlights refreshed(Highlights shown, SubStep current, Step step)
	{
		return withNamedItems(taskActs.withItems(withEquipItems(shown, current, step), current, step), current);
	}

	/** An act's items are filled by what it asks for (equip on a left click, its own items), not by a teleport's left click. */
	Highlights withItemFill(Highlights shown, SubStep current, Step step)
	{
		if (current != null && current.getKind() == SubStep.Kind.ACT)
		{
			return withEquipItems(shown, current, step);
		}
		return shown.toBuilder().fillItems(oneClickItems(shown, current, shown.getOneClickLabel())).build();
	}

	/** The STASH unit the act searches, or {@link StepRequirements#NO_STASH}. */
	int stashOf(SubStep act, Step step)
	{
		if (act.getDone() == SubStep.Done.STASH_DEPOSITED)
		{
			return deposit.getStashId();
		}
		boolean taking = act.getDone() == SubStep.Done.STASH_WITHDRAWN && step != null && step.getRequirements() != null;
		return taking ? step.getRequirements().getStashObjectId() : StepRequirements.NO_STASH;
	}

	List<TileObject> fillObjects(List<TileObject> objects, Highlights shown)
	{
		String objectOption = shown.getObjectOption();
		if (objectOption != null)
		{
			return objects.stream().filter(object -> leftClicks.isLeftClick(object, objectOption))
				.collect(Collectors.toUnmodifiableList());
		}
		MenuTarget menuTarget = shown.getMenuTarget();
		boolean ring = menuTarget.getLine() == MenuTarget.Line.FAIRY_CODE && menuTarget.getLineKey() != null;
		String firstClick = menuTarget.getPath().isEmpty() ? null : menuTarget.getPath().get(0);
		String label = shown.getOneClickLabel();
		boolean houseList = menuTarget.getLine() == MenuTarget.Line.NEXUS || menuTarget.getLine() == MenuTarget.Line.BOX;
		return objects.stream()
			.filter(object -> ring ? ringGoesTo(leftClicks.object(object), menuTarget.getLineKey())
				: oneClickTo(leftClicks.object(object), label, firstClick)
				|| houseList && MenuLabels.isOpener(leftClicks.object(object)))
			.collect(Collectors.toUnmodifiableList());
	}

	/** Each worn item's "Remove", coloured in its menu; worn options name the item but carry no id. */
	private MenuTarget removeTarget(Set<Integer> worn)
	{
		Set<String> names = worn.stream().map(id -> MenuLabels.normalise(client.getItemDefinition(id).getName()))
			.collect(Collectors.toUnmodifiableSet());
		return MenuTarget.builder().itemIds(worn).itemNames(names).path(List.of(REMOVE_OPTION)).build();
	}

	/** The act's items whose left click does the act: put on, taken off (a Max cape left-clicking "Home" isn't), else all. */
	private Set<Integer> actItemFill(SubStep act)
	{
		switch (act.getDone())
		{
			case WAY_IN_WORN:
			case GEAR_WORN:
				return act.getActItems().stream().filter(leftClicks::wears).collect(Collectors.toUnmodifiableSet());
			case SLOTS_EMPTY:
				return act.getActItems().stream().filter(leftClicks::removes).collect(Collectors.toUnmodifiableSet());
			default:
				return act.getActItems();
		}
	}

	List<NPC> fillNpcs(List<NPC> npcs, String npcOption)
	{
		return npcOption == null ? List.of()
			: npcs.stream().filter(npc -> npcOption.equalsIgnoreCase(leftClicks.npc(npc))).collect(Collectors.toUnmodifiableList());
	}

	/** An act's own items, its STASH unit, the gear to put on, or a planted tree's line; else only its one-click fill. */
	private Highlights actHighlights(Highlights.HighlightsBuilder shown, SubStep current, Step step)
	{
		shown.tab(current.getTab());
		int stash = stashOf(current, step);
		if (stash != StepRequirements.NO_STASH)
		{
			return shown.menuTarget(MenuTarget.builder().objectIds(Set.of(stash)).build()).objectOption(SEARCH_OPTION).build();
		}
		if (current.getDone() == SubStep.Done.EQUIPPED)
		{
			return withEquipItems(shown.build(), current, step);
		}
		if (!current.getActItems().isEmpty())
		{
			boolean takesOff = current.getDone() == SubStep.Done.SLOTS_EMPTY;
			shown.items(current.getActItems()).fillItems(actItemFill(current))
				.tab(takesOff ? StepGuide.Tab.EQUIPMENT : StepGuide.Tab.INVENTORY);
			return (takesOff ? shown.menuTarget(removeTarget(current.getActItems())) : shown).build();
		}
		String planted = taskActs.plantedTreeLine(current, step);
		if (planted != null)
		{
			shown.menuTarget(rowTargets.plantedTree(current.getObjectIds(), planted));
		}
		return withOneClick(shown.build(), current);
	}

	/** The way in's object with its option and dialogue; once its items are picked up, the object they are used on. */
	private static MenuTarget enterTarget(SubStep current)
	{
		StepIndex.PickUp pickUp = current.getWayIn().getPickUp();
		boolean pickedUp = pickUp != null && current.getText().startsWith(StepGuide.KEEP_GOING);
		return pickedUp ? MenuTarget.builder().objectIds(Set.copyOf(pickUp.getObjects())).path(List.of(pickUp.getOption())).build()
			: withDialogue(wayTarget(current.getWayIn().getObject(), current.getWayIn().getOption()), current.getWayIn());
	}

	/** The step's hand-written way in that this exit row is, or null. */
	private static StepIndex.WayIn wayInOf(Step step, Exit exit)
	{
		StepIndex.WayIn way = step == null ? null : step.getData().getEntry();
		return way != null && exit.getOrigin().equals(way.getTile()) && exit.getDestination().equals(way.getTo()) ? way : null;
	}

	/** A conversation's chat options follow its option, so each menu's pick is coloured in turn. */
	private static MenuTarget withDialogue(MenuTarget target, StepIndex.WayIn way)
	{
		if (way == null || way.getDialogue().isEmpty())
		{
			return target;
		}
		List<String> path = new ArrayList<>(target.getPath());
		path.addAll(way.getDialogue());
		return target.toBuilder().path(List.copyOf(path)).build();
	}

	/** Shortest Path names objects and NPCs alike by id, so the id is looked for as both. */
	private static MenuTarget wayTarget(int id, String option)
	{
		Set<Integer> ids = id < 0 ? Set.of() : Set.of(id);
		return MenuTarget.builder().objectIds(ids).npcIds(ids).path(option == null || option.isEmpty() ? List.of() : List.of(option)).build();
	}

	/** A spell, the Minigame Teleport spell, house furniture or a spirit tree, a named item, or the held item with its menu. */
	private void teleportHighlights(Highlights.HighlightsBuilder shown, SubStep current)
	{
		CatalogRow row = current.getRow();
		if (isSpell(row))
		{
			shown.spellWidget(rowTargets.spellWidget(row)).tab(StepGuide.Tab.MAGIC);
		}
		else if (row.getCategory() == Category.MINIGAME)
		{
			shown.spellWidget(rowTargets.minigameSpellWidget(player.currentBook())).tab(StepGuide.Tab.MAGIC)
				.menuTarget(MenuTarget.minigame(row.minigameName()));
		}
		else if (row.isLocated())
		{
			MenuTarget target = rowTargets.locatedTeleport(current);
			boolean set = obelisk.isSetFor(row.getName());
			shown.menuTarget(set ? target.toBuilder().path(List.of(TELEPORT_TO_DESTINATION)).build() : target);
		}
		else if (current.getActItemNamed() != null)
		{
			shown.tab(StepGuide.Tab.INVENTORY);
		}
		else
		{
			Set<Integer> held = withHeld(shown, rowTargets.heldUses(row));
			shown.menuWidget(ScrollBook.entry(row.getName())).menuTarget(rowTargets.heldTeleport(current, held));
		}
	}

	/** An item that changes the book anywhere (a cape), or house furniture that does. */
	private void changeBookHighlights(Highlights.HighlightsBuilder shown, SubStep current)
	{
		if (current.getChange().isAnywhere())
		{
			Set<Integer> held = withHeld(shown, rowTargets.heldUses(current.getChange()));
			shown.menuTarget(rowTargets.heldBookChange(held, current.getBook()));
		}
		else if (current.getChange().isInHouse())
		{
			shown.menuTarget(rowTargets.houseBookChange(current.getChange(), current.getBook()));
		}
	}

	private static boolean isSpell(CatalogRow row)
	{
		return row.getCategory() == Category.SPELL || row.getCategory() == Category.HOME;
	}

	/**
	 * The held items go on {@code shown}, outlined in the tab they are in.
	 *
	 * @return the items' ids
	 */
	private static Set<Integer> withHeld(Highlights.HighlightsBuilder shown, List<ItemUse> held)
	{
		Set<Integer> items = held.stream().map(ItemUse::getItemId).collect(Collectors.toUnmodifiableSet());
		boolean worn = !held.isEmpty() && held.stream().allMatch(use -> use.getContainer() == Container.WORN);
		shown.heldUses(held).items(items)
			.tab(held.isEmpty() ? StepGuide.Tab.NONE : worn ? StepGuide.Tab.EQUIPMENT : StepGuide.Tab.INVENTORY);
		return items;
	}

	/** The one-click fill: the items whose left click goes where the menu target does. */
	private Highlights withOneClick(Highlights built, SubStep current)
	{
		String label = directLabel(built.getMenuTarget(), current);
		return built.toBuilder().oneClickLabel(label).fillItems(oneClickItems(built, current, label)).build();
	}

	/** None for a quetzal: its option only opens the map. */
	private String directLabel(MenuTarget menuTarget, SubStep current)
	{
		if (menuTarget.getLine() == MenuTarget.Line.QUETZAL)
		{
			return null;
		}
		if (menuTarget.destination() != null)
		{
			return menuTarget.destination();
		}
		List<String> path = current.getRow() == null ? List.of() : rowTargets.optionPath(current.getRow());
		return path.isEmpty() ? null : path.get(path.size() - 1);
	}

	private Set<Integer> oneClickItems(Highlights shown, SubStep current, String label)
	{
		boolean signals = shown.getMenuTarget().getLine() == MenuTarget.Line.QUETZAL;
		boolean oneDestination = label == null && rowTargets.hasOneDestination(current);
		return shown.getHeldUses().stream()
			.filter(use -> signals ? RowTargets.SIGNAL_OPTION.equalsIgnoreCase(leftClicks.item(use))
				: oneDestination ? OneClick.isOwnTeleport(leftClicks.item(use)) : OneClick.teleportsTo(leftClicks.swappedOrLearned(use), label))
			.map(ItemUse::getItemId)
			.collect(Collectors.toUnmodifiableSet());
	}

	/** The carried items the emote step wants on, refreshed every tick as they are put on. */
	private Highlights withEquipItems(Highlights shown, SubStep current, Step step)
	{
		if (current == null || current.getKind() != SubStep.Kind.ACT || current.getDone() != SubStep.Done.EQUIPPED
			|| step == null || step.getRequirements() == null)
		{
			return shown;
		}
		Set<Integer> wanted = player.inventoryIds().stream()
			.filter(id -> step.getRequirements().getItems().stream().anyMatch(need -> need.fulfilledBy(id)))
			.collect(Collectors.toUnmodifiableSet());
		return shown.toBuilder().items(wanted)
			.fillItems(wanted.stream().filter(leftClicks::wears).collect(Collectors.toUnmodifiableSet())).build();
	}

	/** The carried item the act names, refreshed every tick as it arrives (the puzzle box, after the talk). */
	private Highlights withNamedItems(Highlights shown, SubStep current)
	{
		boolean clicksItem = current != null && (current.getKind() == SubStep.Kind.ACT || current.getKind() == SubStep.Kind.TELEPORT);
		if (!clicksItem || current.getActItemNamed() == null)
		{
			return shown;
		}
		Set<Integer> named = player.inventoryIds().stream()
			.filter(id -> client.getItemDefinition(id).getName().toLowerCase().startsWith(current.getActItemNamed()))
			.collect(Collectors.toUnmodifiableSet());
		String option = current.getActOption();
		Highlights.HighlightsBuilder next = shown.toBuilder().items(named)
			.fillItems(option == null ? named : named.stream().filter(id -> option.equalsIgnoreCase(leftClicks.item(id))).collect(Collectors.toUnmodifiableSet()))
			.tab(named.isEmpty() ? shown.getTab() : StepGuide.Tab.INVENTORY);
		return option == null ? next.build() : takeOutFromBook(next, named, current, option);
	}

	/** The book's entry for the scroll, outlined once the book is open, and its Remove option coloured. */
	private Highlights takeOutFromBook(Highlights.HighlightsBuilder shown, Set<Integer> items, SubStep current, String option)
	{
		boolean fromBook = current.getDone() == SubStep.Done.ITEM_CARRIED && current.getRow() != null;
		Widget book = fromBook ? client.getWidget(InterfaceID.Bookofscrolls.CONTENTS) : null;
		boolean bookOpen = book != null && !book.isHidden();
		return shown.menuWidget(fromBook ? ScrollBook.entry(current.getRow().getName()) : ScrollBook.NO_WIDGET)
			.menuTarget(bookOpen
				? MenuTarget.builder().widgetIds(ScrollBook.widgets(current.getRow().getName())).path(List.of(ScrollBook.REMOVE_OPTION)).build()
				: rowTargets.items(items, option))
			.build();
	}

	private static boolean oneClickTo(String leftClick, String label, String firstClick)
	{
		return OneClick.teleportsTo(leftClick, label) || firstClick != null && MenuLabels.matches(leftClick, firstClick);
	}

	/** Menu Entry Swapper's "Last-destination" carries no code, so the remembered last ring stands in for it. */
	private boolean ringGoesTo(String leftClick, String code)
	{
		if (MenuLabels.isRingDestination(leftClick, code))
		{
			return true;
		}
		PlayerSnapshot snapshot = player.getSnapshot();
		String last = snapshot == null ? null : snapshot.getLastFairyRing();
		return leftClick != null && !leftClick.contains("(") && MenuLabels.isLastDestination(leftClick + " (" + last + ")", code);
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.Book;
import com.cluehelper.route.Exit;
import com.cluehelper.step.Stage;
import com.cluehelper.step.StepIndex;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.SpellbookChange;
import java.util.List;
import java.util.Set;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

@Value
@Builder(toBuilder = true)
public class SubStep
{
	/** What ends an act; any other sub-step ends by its kind's own check. */
	public enum Done
	{
		/** The step changes or a new plan comes: the last act of a step, or a stage's. */
		STEP_CHANGES,
		STASH_WITHDRAWN,
		STASH_DEPOSITED,
		/** Core's item requirements are met by what is worn. */
		EQUIPPED,
		URI_HERE,
		/** A challenge scroll, puzzle box or light box arrives in the inventory. */
		CHALLENGE_ITEM,
		/** An item named {@code carriedWhenDone} is in the inventory (a scroll taken out of its book). */
		ITEM_CARRIED,
		/** No item named {@code actItemNamed} is in the inventory any more (a book deposited). */
		ITEM_GONE,
		/** The way in's worn requirements (diving gear) are all worn. */
		WAY_IN_WORN,
		/** The needs named in {@code wornNeeds} are met by worn items alone. */
		GEAR_WORN,
		/** Core's {@code emptied} slot requirements are met by what is worn. */
		SLOTS_EMPTY,
		/** One of {@code heldWhenDone} is carried or worn. */
		ITEM_HELD
	}

	public enum Kind
	{
		WALK,
		/** Out of a scene with no walk node, by a staircase, ladder or cave exit. */
		EXIT,
		/** Into the step's own area by hand data's way in: a guild door, a boat, a dungeon ladder. */
		ENTER,
		/** Core's own markers guide this walk. */
		WALK_TO_CLUE,
		WILDERNESS_EXIT,
		TELEPORT,
		SPELLBOOK_SWAP,
		FAIRY_RING,
		CHANGE_BOOK,
		BANK,
		WITHDRAW,
		/** Talk, search, dig or emote. */
		ACT
	}

	Kind kind;
	String text;
	String detail;
	/** Null on core's target and for travel that lands far away. */
	WorldPoint waypoint;
	/** Null when the sub-step completes some other way than arriving within {@link #radius}. */
	WorldPoint goal;
	int radius;
	Book book;
	/** The teleport to highlight, or a fairy ring's landing. */
	CatalogRow row;
	SpellbookChange change;
	Exit exit;
	StepIndex.WayIn wayIn;
	/** An act that ends one stage of several; null for the step's own act. */
	Stage stage;
	/** The option that does the act on its objects or NPCs, coloured in their menu and filled on a left click; or null. */
	String option;
	/** Objects to outline and walk up to, from the stage: an anvil. */
	@Builder.Default
	Set<Integer> objectIds = Set.of();
	/** NPCs to outline and walk up to, from the stage: the Grand Exchange clerks. */
	@Builder.Default
	Set<Integer> npcIds = Set.of();
	/** The step's own NPC by name, whose option is coloured only: core outlines it. */
	@Builder.Default
	Set<String> npcNames = Set.of();
	@Builder.Default
	Done done = Done.STEP_CHANGES;
	/** An enemy may attack during this act (a dig, an emote): while one is near, the guide says to fight it. */
	boolean fights;
	/** The act's text once a fight is over: "Dig again". */
	String again;
	@Builder.Default
	Set<Integer> bankItems = Set.of();
	/** Shown one per line under the text: the items to withdraw. */
	@Builder.Default
	List<String> items = List.of();
	/** An act's item, used by its left click: the strange device for a feel. */
	@Builder.Default
	Set<Integer> actItems = Set.of();
	/** A carried item to click, by the start of its name (puzzle boxes come in a form per tier); null for none. */
	String actItemNamed;
	/** The option the act takes on its item: filled when that is the item's left click, coloured in its menu. */
	String actOption;
	/** For {@link Done#GEAR_WORN}: the step's needs to wear, by name. */
	@Builder.Default
	List<String> wornNeeds = List.of();
	/** For {@link Done#SLOTS_EMPTY}: core's empty-slot requirements. */
	@Builder.Default
	List<ItemRequirement> emptied = List.of();
	/** For {@link Done#ITEM_HELD}: any of these. */
	@Builder.Default
	Set<Integer> heldWhenDone = Set.of();
	/** For a walk to or an act at a place that spans an area: anywhere in one is there, and it is outlined. */
	@Builder.Default
	List<StepIndex.Place> spans = List.of();
	/** A ground item to pick up, outlined where it lies, the nearest as the waypoint; -1 for none. */
	@Builder.Default
	int groundItem = -1;
	/** For {@link Done#ITEM_CARRIED}: the start of the item's name, lower case. */
	String carriedWhenDone;
	/** The side tab the act is done in: Emotes for an emote, Music for a track. */
	@Builder.Default
	StepGuide.Tab tab = StepGuide.Tab.NONE;

	/** Gear put on or taken off, or something fetched before the act: done where the player stands, no line to the place. */
	public boolean isPreparation()
	{
		return done == Done.GEAR_WORN || done == Done.WAY_IN_WORN || done == Done.SLOTS_EMPTY || done == Done.ITEM_HELD;
	}

	public boolean isTravel()
	{
		return kind == Kind.TELEPORT || kind == Kind.FAIRY_RING;
	}

	/** An act that is a skill challenge's task, at its place or anywhere. */
	public boolean isTask()
	{
		return kind == Kind.ACT && stage != null && stage.getKind() == Stage.Kind.TASK;
	}
}

package com.cluehelper.guide;

import com.cluehelper.memory.BankMemory;
import com.cluehelper.memory.StashMemory;
import com.cluehelper.player.HouseState;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.Exit;
import com.cluehelper.player.PositionRules;
import com.cluehelper.route.Leg;
import com.cluehelper.route.PlanStart;
import com.cluehelper.route.RequiredItems;
import com.cluehelper.route.Route;
import com.cluehelper.route.RoutePlanner;
import com.cluehelper.route.StepNeeds;
import com.cluehelper.step.EmptySlots;
import com.cluehelper.step.Stage;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Function;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

@Singleton
public final class SubSteps
{
	public static final int ARRIVE_TILES = 3;
	/** The Agility Pyramid's course spans its foot; a cave's way in is a tile. */
	private static final int ON_WAY_IN_TILES = 40;
	/** The walk from a landing to the place, a way in (a cave entrance) included. */
	private static final Set<SubStep.Kind> WALKS_IN = EnumSet.of(SubStep.Kind.WALK, SubStep.Kind.EXIT, SubStep.Kind.ENTER,
		SubStep.Kind.WALK_TO_CLUE);
	/** Some teleports land anywhere in a small area, beyond the catalog's 0–2 tile spread. */
	static final int LANDING_TILES = 10;
	/** A wandering NPC: being in its area is enough. */
	static final int AREA_ARRIVE_TILES = 15;

	private static final int MAX_STACK = Integer.MAX_VALUE / 2;

	private final Client client;
	private final Supplier<PlayerSnapshot> snapshot;
	private final IntPredicate onlyInBankedKit;
	private final StepNeeds stepNeeds;
	private final Supplier<PlanStart> start;
	private final BooleanSupplier scrollBookOutOfWilderness;

	@Inject
	SubSteps(Client client, PlayerModel player, BankMemory bankMemory, StepNeeds stepNeeds, RoutePlanner routes)
	{
		this(client, player::getSnapshot, bankMemory::onlyInBankedKit, stepNeeds, routes::getStart,
			routes::keepsScrollBookOutOfWilderness);
	}

	/** @param client item names */
	public SubSteps(Client client, Supplier<PlayerSnapshot> snapshot, IntPredicate onlyInBankedKit, StepNeeds stepNeeds,
		Supplier<PlanStart> start, BooleanSupplier scrollBookOutOfWilderness)
	{
		this.client = client;
		this.snapshot = snapshot;
		this.onlyInBankedKit = onlyInBankedKit;
		this.stepNeeds = stepNeeds;
		this.start = start;
		this.scrollBookOutOfWilderness = scrollBookOutOfWilderness;
	}

	/** Client thread only. The route's legs as sub-steps, then the step's own acts. */
	public List<SubStep> of(Route route, Step step)
	{
		boolean takeFromStash = takeFromStash(step);
		List<SubStep> legs = new RouteSteps(route, step, id -> withdrawLine(step, id), house(), takeFromStash).build(this::exitOf);
		List<SubStep> steps = withWanderNote(withGearOnArrival(withWayInEquipped(legs, step.getData())), step.getData());
		boolean wildernessTarget = step.getTargets().stream().anyMatch(tile -> PositionRules.wildernessLevel(tile) > 0);
		return scrollBookOutOfWilderness.getAsBoolean() ? ScrollBook.withBookBanked(steps, carriesScrollBook(), wildernessTarget) : steps;
	}

	/** What to do at the step once there, its STASH items taken out first when they wait there. */
	public List<SubStep> acts(Step step)
	{
		return Acts.of(step, takeFromStash(step));
	}

	/** The step's items wait in its filled STASH unit, and the player has none of them on. */
	public boolean takeFromStash(Step step)
	{
		if (step == null || step.getData().getStash() == null || step.getRequirements() == null)
		{
			return false;
		}
		return stepNeeds.of(step).getStash() == StashMemory.State.FILLED
			&& !step.getRequirements().itemsFulfilledBy(PlayerSnapshot.items(carriedItems()));
	}

	private HouseState house()
	{
		PlayerSnapshot player = snapshot.get();
		return player == null ? HouseState.NONE : player.getHouse();
	}

	private Map<Integer, Integer> carriedItems()
	{
		PlayerSnapshot player = snapshot.get();
		return player == null ? Map.of() : player.carriedItems();
	}

	private boolean carriesScrollBook()
	{
		PlayerSnapshot player = snapshot.get();
		return player != null && player.carriesItemNamed(ScrollBook.BOOK_NAME, id -> client.getItemDefinition(id).getName());
	}

	/** The exit a start leg leaves by, or null for any other walk. */
	private Exit exitOf(Leg leg)
	{
		PlanStart from = start.get();
		if (from == null || from.getKind() != PlanStart.Kind.SCENE || !leg.getFrom().equals(from.getTile()))
		{
			return null;
		}
		return from.getWalk().exitTo(leg.getTo());
	}

	/** "Green dragon leather x2" while more than one is still to take, else the name alone. */
	private String withdrawLine(Step step, int itemId)
	{
		String name = client.getItemDefinition(itemId).getName();
		if (onlyInBankedKit.test(itemId))
		{
			return client.getItemDefinition(ItemID.HUNTSMANS_KIT).getName() + " (" + name + " inside)";
		}
		int more = stillToTake(step, itemId);
		return more > 1 ? name + " x" + more : name;
	}

	/** The fewest of the item that, with what is carried, meet every step need it counts towards. */
	private int stillToTake(Step step, int itemId)
	{
		Map<Integer, Integer> carried = carriedItems();
		int most = 0;
		for (RequiredItems.Need need : stepNeeds.of(step).getNeeds())
		{
			ItemRequirement requirement = need.getRequirement();
			if (requirement.fulfilledBy(itemId) && !requirement.fulfilledBy(withMore(carried, itemId, 0)))
			{
				most = Math.max(most, fewestMeeting(requirement, carried, itemId));
			}
		}
		return most;
	}

	/** Doubles, then halves back: needs run from 1 to thousands (coins). 0 when this item alone can't meet it (an outfit). */
	private static int fewestMeeting(ItemRequirement requirement, Map<Integer, Integer> carried, int itemId)
	{
		int high = 1;
		while (high < MAX_STACK && !requirement.fulfilledBy(withMore(carried, itemId, high)))
		{
			high *= 2;
		}
		if (high >= MAX_STACK)
		{
			return 0;
		}
		int low = high / 2;
		while (low + 1 < high)
		{
			int middle = (low + high) / 2;
			if (requirement.fulfilledBy(withMore(carried, itemId, middle)))
			{
				high = middle;
			}
			else
			{
				low = middle;
			}
		}
		return high;
	}

	private static Item[] withMore(Map<Integer, Integer> carried, int itemId, int more)
	{
		Map<Integer, Integer> items = new HashMap<>(carried);
		items.merge(itemId, more, Integer::sum);
		return PlayerSnapshot.items(items);
	}

	/** The sub-steps of one route, built leg by leg: each stage's walk and act in turn, then the step's own acts. */
	private static final class RouteSteps
	{
		private final List<SubStep> steps = new ArrayList<>();
		private final Route route;
		private final Step step;
		private final IntFunction<String> itemNames;
		private final HouseState house;
		private final boolean takeFromStash;
		/** The STASH unit stands outside the step's way in: its items come before going in. */
		private final boolean stashFirst;

		RouteSteps(Route route, Step step, IntFunction<String> itemNames, HouseState house, boolean takeFromStash)
		{
			this.route = route;
			this.step = step;
			this.itemNames = itemNames;
			this.house = house;
			this.takeFromStash = takeFromStash;
			this.stashFirst = takeFromStash && stashOutsideWayIn(step);
		}

		List<SubStep> build(Function<Leg, Exit> exits)
		{
			if (route.isOpenBankStart() && !route.getWithdraw().isEmpty())
			{
				steps.add(LegSteps.withdraw(route, itemNames));
			}
			List<Stage> stages = step.getStages().stream().filter(stage -> !stage.getTiles().isEmpty()).collect(Collectors.toList());
			List<Leg> legs = route.getLegs();
			int stage = 0;
			for (int i = 0; i < legs.size(); i++)
			{
				Leg leg = legs.get(i);
				Leg next = i + 1 < legs.size() ? legs.get(i + 1) : null;
				Exit exit = leg.getKind() == Leg.Kind.WALK ? exits.apply(leg) : null;
				Stage reached = stage < stages.size() - 1 && stages.get(stage).getTiles().contains(leg.getTo()) ? stages.get(stage) : null;
				if (reached != null && leg.getKind() == Leg.Kind.WALK && exit == null)
				{
					steps.add(LegSteps.walkToStage(leg, reached));
				}
				else
				{
					addLeg(leg, next, exit);
				}
				if (reached != null)
				{
					addStageAct(steps, reached);
					stage++;
				}
			}
			addLastActs(stages);
			addActsDoneAnywhere(steps, step);
			return steps;
		}

		private void addLeg(Leg leg, Leg next, Exit exit)
		{
			switch (leg.getKind())
			{
				case WALK:
					addWalk(leg, next, exit);
					break;
				case WILDERNESS_EXIT:
					steps.add(SubStep.builder().kind(SubStep.Kind.WILDERNESS_EXIT).text("Walk south out of deep Wilderness")
						.detail("Teleports work from there").waypoint(leg.getTo()).goal(leg.getTo()).build());
					break;
				case SWAP_TELEPORT:
					steps.add(LegSteps.swap(leg));
					steps.add(LegSteps.teleport(leg, house));
					break;
				case TELEPORT:
					steps.add(LegSteps.teleport(leg, house));
					break;
				case FAIRY_RING:
					steps.add(LegSteps.fairyRing(leg));
					break;
				case SPELLBOOK_CHANGE:
					steps.add(LegSteps.change(leg));
					break;
				case BANK:
					steps.add(SubStep.builder().kind(SubStep.Kind.BANK).text("Open the bank")
						.detail(route.isPinIncluded() ? "Your PIN comes first" : null).waypoint(leg.getTo()).build());
					steps.add(LegSteps.withdraw(route, itemNames));
					break;
				default:
					throw new IllegalArgumentException("unhandled leg kind " + leg.getKind());
			}
		}

		/** A walk into the step's area goes in by its way in, with the STASH items first when the unit stands outside. */
		private void addWalk(Leg leg, Leg next, Exit exit)
		{
			boolean wayIn = exit != null && isWayIn(exit, step);
			if ((exit == null || wayIn) && entersStepArea(leg, step))
			{
				if (stashFirst)
				{
					steps.add(LegSteps.stashWalk(stashTile(step)));
					steps.addAll(Acts.fromStash(step));
				}
				steps.add(LegSteps.enter(step.getData()));
			}
			if (exit != null || wayIn || !boardedThere(next))
			{
				steps.add(exit != null && !wayIn ? LegSteps.exit(leg, exit) : LegSteps.walk(leg, next, step, takeFromStash && !stashFirst));
			}
		}

		/** The last stage's act, or the step's own acts once every stage is done. */
		private void addLastActs(List<Stage> stages)
		{
			Stage last = stages.isEmpty() ? null : stages.get(stages.size() - 1);
			if (last != null && last.getKind() != Stage.Kind.FINAL)
			{
				addStageAct(steps, last);
			}
			else
			{
				steps.addAll(Acts.of(step, takeFromStash && !stashFirst));
			}
		}
	}

	/** After the last bank stop, which may be what brings the task's items. */
	private static void addActsDoneAnywhere(List<SubStep> steps, Step step)
	{
		int at = 0;
		for (int i = 0; i < steps.size(); i++)
		{
			if (steps.get(i).getKind() == SubStep.Kind.WITHDRAW)
			{
				at = i + 1;
			}
		}
		for (Stage stage : step.getStages())
		{
			if (stage.getTiles().isEmpty())
			{
				steps.add(at++, stageAct(stage));
			}
		}
	}

	/** Ends when the stage is dropped from the step, which brings a new plan. */
	static SubStep stageAct(Stage stage)
	{
		return SubStep.builder().kind(SubStep.Kind.ACT).text(stage.getAct()).detail(stage.getDetail()).stage(stage)
			.npcIds(stage.getNpcIds()).objectIds(stage.getObjectIds()).option(stage.getOption()).spans(stage.getSpans()).build();
	}

	/** The step's way in, when the player is on it: near its start, any floor, and not yet inside. */
	public static SubStep goingIn(Step step, WorldPoint at)
	{
		StepIndex.WayIn way = step == null ? null : step.getData().getEntry();
		boolean byStart = way != null && at != null && way.getTile() != null && at.distanceTo2D(way.getTile()) <= ON_WAY_IN_TILES;
		boolean onIt = way != null && (byStart || way.isPartWay(at)) && !way.isInside(at);
		return onIt ? LegSteps.enter(step.getData()) : null;
	}

	/**
	 * A fairy ring, ride or spirit tree used where it stands: its own sub-step leads the line there and colours its menu
	 * from the start, so no "Walk to" comes before it.
	 */
	private static boolean boardedThere(Leg next)
	{
		return next != null && (next.getKind() == Leg.Kind.FAIRY_RING
			|| next.getKind() == Leg.Kind.TELEPORT && next.getRow() != null && next.getRow().isLocated() && !next.getRow().isInHouse());
	}

	/** The STASH unit stands outside the step's way in (the Agility Pyramid's, at its foot): its items come first. */
	private static boolean stashOutsideWayIn(Step step)
	{
		WorldPoint stash = stashTile(step);
		StepIndex.WayIn way = step.getData().getEntry();
		return stash != null && way != null && !way.isInside(stash);
	}

	/** An exit leg that is the step's own hand-written way in, named by its text instead of "Take the exit". */
	private static boolean isWayIn(Exit exit, Step step)
	{
		StepIndex.WayIn way = step.getData().getEntry();
		return way != null && exit.getOrigin().equals(way.getTile()) && exit.getDestination().equals(way.getTo());
	}

	static WorldPoint stashTile(Step step)
	{
		return step.getData().getStash() == null ? null : step.getData().getStash().getTile();
	}

	/** The last walk to the step starts outside its hand-written way in. */
	private static boolean entersStepArea(Leg leg, Step step)
	{
		StepIndex.WayIn way = step.getData().getEntry();
		return way != null && step.getTargets().contains(leg.getTo()) && !way.isInside(leg.getFrom());
	}

	/** Before going in, the gear the way in needs worn is put on. */
	private static void addStageAct(List<SubStep> steps, Stage stage)
	{
		steps.addAll(stageActs(stage));
	}

	/** Gear the act wants worn goes on just before, so each part of a three-step can wear its own. */
	static List<SubStep> stageActs(Stage stage)
	{
		List<SubStep> acts = new ArrayList<>(remove(stage.getEmptied()));
		stage.getBefore().forEach(before -> acts.add(SubStep.builder().kind(SubStep.Kind.ACT).text(before.getText())
			.npcIds(Set.copyOf(before.getNpcs())).option(before.getOption()).groundItem(before.getGroundItem())
			.heldWhenDone(Set.copyOf(before.getHeld())).done(SubStep.Done.ITEM_HELD).build()));
		acts.addAll(stage.getWorn().isEmpty() ? List.of() : equip(stage.getWorn()));
		acts.add(stageAct(stage));
		return List.copyOf(acts);
	}

	/** Take off what core's empty-slot requirements forbid; none when there are none. */
	static List<SubStep> remove(List<ItemRequirement> emptied)
	{
		return emptied.isEmpty() ? List.of() : List.of(SubStep.builder().kind(SubStep.Kind.ACT)
			.text("Take off your " + EmptySlots.slotNames(emptied)).emptied(emptied).done(SubStep.Done.SLOTS_EMPTY)
			.tab(StepGuide.Tab.EQUIPMENT).build());
	}

	/** Put on the needs named, done once worn items alone meet them. */
	static List<SubStep> equip(List<String> wornNeeds)
	{
		return List.of(SubStep.builder().kind(SubStep.Kind.ACT).text("Equip the " + String.join(" and ", wornNeeds))
			.wornNeeds(wornNeeds).done(SubStep.Done.GEAR_WORN).tab(StepGuide.Tab.INVENTORY).build());
	}

	/** A wide wanderer is looked for rather than walked to: where it wanders goes under the walk. */
	private static List<SubStep> withWanderNote(List<SubStep> steps, StepIndex.Entry data)
	{
		StepIndex.Wander wander = data == null ? null : data.getWander();
		if (wander == null || wander.getText() == null)
		{
			return steps;
		}
		return steps.stream().map(sub -> sub.getKind() == SubStep.Kind.WALK_TO_CLUE ? sub.toBuilder().detail(wander.getText()).build() : sub)
			.collect(Collectors.toUnmodifiableList());
	}

	/**
	 * The act's gear goes on as soon as the route lands, before walking or going in: a course fails without its Graceful,
	 * Ape Atoll's monkeys and a dust devil's cave hurt without theirs.
	 */
	private static List<SubStep> withGearOnArrival(List<SubStep> steps)
	{
		int equip = IntStream.range(0, steps.size()).filter(i -> steps.get(i).getDone() == SubStep.Done.GEAR_WORN).findFirst().orElse(-1);
		if (equip < 0)
		{
			return steps;
		}
		int landed = equip;
		while (landed > 0 && WALKS_IN.contains(steps.get(landed - 1).getKind()))
		{
			landed--;
		}
		List<SubStep> out = new ArrayList<>(steps);
		out.add(landed, out.remove(equip));
		return List.copyOf(out);
	}

	static List<SubStep> withWayInEquipped(List<SubStep> steps, StepIndex.Entry data)
	{
		List<StepIndex.Requires> worn = data == null ? List.of()
			: data.getRequires().stream().filter(StepIndex.Requires::isWear).collect(Collectors.toList());
		if (worn.isEmpty())
		{
			return steps;
		}
		SubStep equip = SubStep.builder().kind(SubStep.Kind.ACT)
			.text("Equip the " + worn.stream().map(StepIndex.Requires::getName).collect(Collectors.joining(" and ")))
			.actItems(worn.stream().flatMap(need -> need.getIds().stream()).collect(Collectors.toUnmodifiableSet()))
			.done(SubStep.Done.WAY_IN_WORN).tab(StepGuide.Tab.INVENTORY).build();
		List<SubStep> out = new ArrayList<>();
		for (SubStep sub : steps)
		{
			if (sub.getKind() == SubStep.Kind.ENTER)
			{
				out.add(equip);
			}
			out.add(sub);
		}
		return List.copyOf(out);
	}
}

package com.cluehelper.guide;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EntityOps;
import net.runelite.api.ItemComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Reads Menu Entry Swapper's config (never writes it) so the one-click fill shows before anything is hovered. Its
 * format: {@code object_<id>} holds the op index (0-4) or a sub-op packed as {@code ((sub + 1) << 8) | op};
 * {@code item_<id>} holds the op index, -1 for Use, or an option's hash; {@code wornitem_<id>} holds the menu identifier
 * or the option's hash. A hash naming a sub-menu line is left to hover learning. Client thread only.
 */
@Singleton
public class SwapperClicks
{
	private static final String GROUP = "menuentryswapper";
	private static final String PLUGIN_KEY = "menuentryswapperplugin";
	private static final String LEFT_CLICK_KEY = "leftClickCustomization";
	private static final String USE = "Use";
	private static final int SUB_OP_SHIFT = 8;
	private static final int OP_MASK = 0xFF;
	private static final int MAX_OP_INDEX = 4;
	private static final int FIRST_WORN_OPTION_ID = 2;
	private static final int FIRST_WORN_OPTION_PARAM = 451;
	private static final int LAST_WORN_OPTION_ID = 9;

	private final Client client;
	private final ConfigManager configManager;

	@Inject
	SwapperClicks(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	String object(ObjectComposition object)
	{
		ObjectComposition shown = object.getImpostorIds() != null && object.getImpostor() != null ? object.getImpostor() : object;
		Integer value = swap("object_" + shown.getId());
		if (value == null || value < 0)
		{
			return null;
		}
		String[] actions = shown.getActions();
		if (value <= MAX_OP_INDEX)
		{
			return actions != null && value < actions.length ? actions[value] : null;
		}
		EntityOps ops = shown.getOps();
		EntityOps subs = ops == null ? null : ops.getSubOps(value & OP_MASK);
		int sub = (value >> SUB_OP_SHIFT) - 1;
		return subs == null || sub < 0 || sub >= subs.getNumOps() ? null : subs.getOp(sub);
	}

	String item(int itemId)
	{
		Integer value = swap("item_" + ItemVariationMapping.map(itemId));
		if (value == null)
		{
			return null;
		}
		if (value == -1)
		{
			return USE;
		}
		String[] actions = client.getItemDefinition(itemId).getInventoryActions();
		if (actions == null)
		{
			return null;
		}
		if (value >= 0 && value < actions.length)
		{
			return actions[value];
		}
		for (String action : actions)
		{
			if (action != null && action.hashCode() == value)
			{
				return action;
			}
		}
		return null;
	}

	String worn(int itemId)
	{
		Integer value = swap("wornitem_" + ItemVariationMapping.map(itemId));
		if (value == null)
		{
			return null;
		}
		ItemComposition item = client.getItemDefinition(itemId);
		for (int id = FIRST_WORN_OPTION_ID; id <= LAST_WORN_OPTION_ID; id++)
		{
			String option = item.getStringValue(FIRST_WORN_OPTION_PARAM + id - FIRST_WORN_OPTION_ID);
			if (option != null && !option.isEmpty() && (value == id || value == option.hashCode()))
			{
				return option;
			}
		}
		return null;
	}

	private Integer swap(String key)
	{
		if ("false".equals(configManager.getConfiguration("runelite", PLUGIN_KEY))
			|| "false".equals(configManager.getConfiguration(GROUP, LEFT_CLICK_KEY)))
		{
			return null;
		}
		String value = configManager.getConfiguration(GROUP, key);
		if (value == null || value.isEmpty())
		{
			return null;
		}
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.cluehelper.guide;

import com.cluehelper.memory.BankMemory;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.RequiredItems;
import com.cluehelper.route.StepNeeds;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * A skill challenge's task act: the items it is done with, the making step reached, the spell cast on an item and the
 * interface option it picks. Client thread only.
 */
@Singleton
final class TaskActs
{
	private final Client client;
	private final PlayerModel player;
	private final BankMemory bankMemory;
	private final StepNeeds stepNeeds;
	private final LeftClicks leftClicks;

	@Inject
	TaskActs(Client client, PlayerModel player, BankMemory bankMemory, StepNeeds stepNeeds, LeftClicks leftClicks)
	{
		this.client = client;
		this.player = player;
		this.bankMemory = bankMemory;
		this.stepNeeds = stepNeeds;
		this.leftClicks = leftClicks;
	}

	/** The items the task needs that the player carries, outlined (used on each other, not clicked once). */
	Highlights withItems(Highlights shown, SubStep current, Step step)
	{
		if (current == null || !current.isTask() || step == null || step.getRequirements() == null)
		{
			return shown;
		}
		Set<Integer> carried = player.carriedIds();
		if (neededFromCarriedKit(step) != null)
		{
			return shown.toBuilder().items(Set.of(ItemID.HUNTSMANS_KIT)).tab(StepGuide.Tab.INVENTORY).build();
		}
		StepIndex.Cast cast = step.getData().getCast();
		if (cast != null && cast.getOn().stream().anyMatch(carried::contains))
		{
			return withCast(shown, cast, carried);
		}
		if (current.getStage().getOption() != null && makingNow(step, carried) == null)
		{
			return shown;
		}
		StepIndex.Making making = makingNow(step, carried);
		Set<Integer> items = making != null
			? carried.stream().filter(id -> making.getItems().stream().anyMatch(group -> group.contains(id))).collect(Collectors.toUnmodifiableSet())
			: carried.stream().filter(id -> step.getRequirements().getItems().stream().anyMatch(need -> need.fulfilledBy(id)))
			.collect(Collectors.toUnmodifiableSet());
		return shown.toBuilder().items(items).fillItems(items.stream().filter(leftClicks::wearsOrUses).collect(Collectors.toUnmodifiableSet()))
			.tab(items.isEmpty() ? shown.getTab() : StepGuide.Tab.INVENTORY).build();
	}

	/** The book to switch to first, else the making step reached; null when the task needs neither. */
	String detail(Step step)
	{
		String book = step == null ? null : step.getData().getBook();
		if (book != null && !book.equals(player.currentBook().name()))
		{
			return "Switch to the " + book.toLowerCase(Locale.ROOT) + " spellbook first";
		}
		String inKit = neededFromCarriedKit(step);
		if (inKit != null)
		{
			return "Take the " + inKit + " out of the huntsman's kit";
		}
		StepIndex.Making making = makingNow(step, player.carriedIds());
		return making == null ? null : making.getText();
	}

	/**
	 * At a spirit tree for the planted-tree task: the player's first planted tree, as its line in the tree's list, reached
	 * by Travel or, on the house's spiritual fairy tree, by Tree.
	 */
	String plantedTreeLine(SubStep current, Step step)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		if (!current.isTask() || step == null || !step.getData().isToPlantedTree() || snapshot == null)
		{
			return null;
		}
		return snapshot.getPlantedTrees().stream().sorted().findFirst().orElse(null);
	}

	/** An interface option the task picks and its confirm button, outlined while the interface is open. */
	List<Widget> choice(SubStep current, Step step)
	{
		Widget product = makeOption(step);
		if (product != null)
		{
			return List.of(product);
		}
		StepIndex.Choose choose = current != null && current.isTask() && step != null ? step.getData().getChoose() : null;
		Widget root = choose == null ? null : client.getWidget(choose.getRoot());
		if (root == null || root.isHidden())
		{
			return List.of();
		}
		Widget option = withText(root, choose.getText());
		List<Widget> widgets = new ArrayList<>();
		if (option != null)
		{
			widgets.add(option.getParent() != null ? option.getParent() : option);
		}
		Widget confirm = client.getWidget(choose.getConfirm());
		if (confirm != null && !confirm.isHidden())
		{
			widgets.add(confirm);
		}
		return List.copyOf(widgets);
	}

	/** The making step's product in the "How many do you wish to make?" box: its option, A to R. */
	private Widget makeOption(Step step)
	{
		Widget box = client.getWidget(InterfaceID.Skillmulti.UNIVERSE);
		StepIndex.Making making = box == null || box.isHidden() || step == null ? null : makingNow(step, player.carriedIds());
		if (making == null || making.getMake() < 0)
		{
			return null;
		}
		for (int id = InterfaceID.Skillmulti.A; id <= InterfaceID.Skillmulti.R; id++)
		{
			Widget option = client.getWidget(id);
			if (option != null && !option.isHidden()
				&& Widgets.descendants(option).stream().anyMatch(shown -> shown.getItemId() == making.getMake()))
			{
				return option;
			}
		}
		return null;
	}

	private static Widget withText(Widget parent, String text)
	{
		if (parent.getText() != null && Text.removeTags(parent.getText()).equalsIgnoreCase(text))
		{
			return parent;
		}
		for (Widget[] children : new Widget[][]{parent.getStaticChildren(), parent.getDynamicChildren(), parent.getNestedChildren()})
		{
			for (Widget child : children == null ? new Widget[0] : children)
			{
				Widget found = child.isHidden() ? null : withText(child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	/** The name of a step item only the carried huntsman's kit holds, or null. */
	private String neededFromCarriedKit(Step step)
	{
		Set<Integer> carried = player.carriedIds();
		BankMemory.Seen kit = carried.contains(ItemID.HUNTSMANS_KIT) ? bankMemory.getKit() : null;
		if (kit == null || step == null)
		{
			return null;
		}
		Item[] held = PlayerSnapshot.oneOfEach(carried);
		for (RequiredItems.Need need : stepNeeds.of(step).getNeeds())
		{
			if (!need.getRequirement().fulfilledBy(held))
			{
				Integer stored = kit.items.keySet().stream().filter(need.getRequirement()::fulfilledBy).findFirst().orElse(null);
				if (stored != null)
				{
					return client.getItemDefinition(stored).getName().toLowerCase(Locale.ROOT);
				}
			}
		}
		return null;
	}

	/** The spell's button until it is picked (the last of its buttons shown), then the items it is cast on. */
	private Highlights withCast(Highlights shown, StepIndex.Cast cast, Set<Integer> carried)
	{
		boolean picked = client.isWidgetSelected();
		Set<Integer> items = picked ? carried.stream().filter(cast.getOn()::contains).collect(Collectors.toUnmodifiableSet()) : Set.of();
		int spellWidget = picked ? -1 : cast.getWidgets().stream().filter(this::widgetShown).reduce((first, last) -> last)
			.orElse(cast.getWidgets().isEmpty() ? -1 : cast.getWidgets().get(0));
		return shown.toBuilder().items(items).fillItems(items).spellWidget(spellWidget)
			.tab(picked ? StepGuide.Tab.INVENTORY : StepGuide.Tab.MAGIC).build();
	}

	private boolean widgetShown(int widgetId)
	{
		Widget widget = client.getWidget(widgetId);
		return widget != null && !widget.isHidden();
	}

	/** The furthest making step whose worked-on item is carried; null before any is, or for a task made of nothing. */
	private static StepIndex.Making makingNow(Step step, Set<Integer> carried)
	{
		List<StepIndex.Making> making = step == null ? List.of() : step.getData().getMaking();
		StepIndex.Making now = null;
		for (StepIndex.Making part : making)
		{
			if (!part.getItems().isEmpty() && part.getItems().get(0).stream().anyMatch(carried::contains))
			{
				now = part;
			}
		}
		return now;
	}
}

package com.cluehelper.guide;

import com.cluehelper.player.PositionRules;
import net.runelite.api.coords.WorldPoint;

/** Client thread only. A game message right after a teleport click, with no animation, means the game refused it. */
final class TeleportRefusal
{
	/** A teleport animates on its click's tick or within two: three ticks without one means it was refused. */
	private static final int CHECK_TICKS = 3;

	private int clickTick = ActWatcher.NEVER;
	private WorldPoint clickTile;
	private String row;
	private int checkTick = ActWatcher.NEVER;

	void clicked(int tick, WorldPoint tile)
	{
		clickTick = tick;
		clickTile = tile;
	}

	/** A game line within a tick of the click: the row is suspect until its check tick. */
	void onGameLine(String rowName, int tick)
	{
		if (clickTick != ActWatcher.NEVER && tick - clickTick <= 1)
		{
			row = rowName;
			checkTick = tick + CHECK_TICKS;
		}
	}

	/**
	 * The row the game refused, once its check tick has come while the step is still its teleport and the player stands
	 * by the click's tile without animating; null otherwise.
	 */
	String refused(int tick, String currentRow, WorldPoint tile, boolean standingStill)
	{
		if (row == null || tick < checkTick)
		{
			return null;
		}
		boolean sameStep = row.equals(currentRow);
		boolean stayed = tile != null && clickTile != null && !PositionRules.teleported(clickTile, tile);
		String refused = sameStep && stayed && standingStill ? row : null;
		row = null;
		clickTick = ActWatcher.NEVER;
		return refused;
	}

	void clear()
	{
		row = null;
		clickTick = ActWatcher.NEVER;
	}
}

package com.cluehelper.guide;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/** Questions about a widget and the widgets under it. */
public final class Widgets
{
	private Widgets()
	{
	}

	/** The widget and everything under it, depth first. */
	public static List<Widget> descendants(Widget widget)
	{
		List<Widget> out = new ArrayList<>();
		if (widget == null)
		{
			return out;
		}
		out.add(widget);
		for (Widget[] children : new Widget[][]{widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			for (int i = 0; children != null && i < children.length; i++)
			{
				out.addAll(descendants(children[i]));
			}
		}
		return out;
	}

	/** Not hidden, and with a width on screen. */
	static boolean visible(Widget widget)
	{
		return widget != null && !widget.isHidden() && widget.getBounds() != null && widget.getBounds().width > 0;
	}

	static boolean hasText(Widget widget)
	{
		return widget.getText() != null && !Text.removeTags(widget.getText()).isBlank();
	}

	/** A nexus row is a container whose text sits in its children: the text is recoloured, so no box is drawn. */
	static boolean hasTextInside(Widget widget)
	{
		return descendants(widget).stream().anyMatch(Widgets::hasText);
	}

	static boolean hasAction(Widget widget, String action)
	{
		for (String a : widget.getActions())
		{
			if (action.equalsIgnoreCase(a))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Rows scrolled out of view keep {@code hidden = false} and their bounds, and the list's layer is as tall as all its
	 * rows, so only clipping to every ancestor leaves the visible part.
	 */
	static Rectangle clipped(Widget widget)
	{
		return widget.getBounds().intersection(insideParents(widget));
	}

	private static Rectangle insideParents(Widget widget)
	{
		Rectangle area = new Rectangle(Integer.MIN_VALUE / 2, Integer.MIN_VALUE / 2, Integer.MAX_VALUE, Integer.MAX_VALUE);
		for (Widget parent = widget.getParent(); parent != null && !area.isEmpty(); parent = parent.getParent())
		{
			Rectangle outer = parent.getBounds();
			if (outer != null && outer.width > 0)
			{
				area = area.intersection(outer);
			}
		}
		return area;
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;

/** Core's bands, measured exact for both tiers: Chebyshev distance to the spot's centre. */
public enum Band
{
	SHAKING("visibly shaking", 3, 4),
	INCREDIBLY_HOT("incredibly hot", 29, 29),
	VERY_HOT("very hot", 69, 69),
	HOT("hot", 99, 99),
	WARM("warm", 149, 149),
	COLD("cold", 199, 199),
	VERY_COLD("very cold", 499, 499),
	ICE_COLD("ice cold", Integer.MAX_VALUE, Integer.MAX_VALUE);

	private final String text;
	private final int beginnerMax;
	private final int masterMax;

	Band(String text, int beginnerMax, int masterMax)
	{
		this.text = text;
		this.beginnerMax = beginnerMax;
		this.masterMax = masterMax;
	}

	public String getText()
	{
		return text;
	}

	public static Band of(int distance, HotColdTier tier)
	{
		for (Band band : values())
		{
			if (distance <= (tier == HotColdTier.BEGINNER ? band.beginnerMax : band.masterMax))
			{
				return band;
			}
		}
		return ICE_COLD;
	}

	/** Tiles from the centre within which a dig finds the casket or the master's enemy. */
	public static int digRadius(HotColdTier tier)
	{
		return tier == HotColdTier.BEGINNER ? SHAKING.beginnerMax : SHAKING.masterMax;
	}

	/** Null unless the clause is exactly one band's text. */
	static Band fromClause(String clause)
	{
		for (Band band : values())
		{
			if (band.text.equals(clause))
			{
				return band;
			}
		}
		return null;
	}
}

package com.cluehelper.hotcold;

/** "Than last time": the exact Chebyshev distance against the step's previous reading (exact in 93 of 93 recorded readings). */
public enum Comparison
{
	WARMER("warmer"),
	SAME("same"),
	COLDER("colder");

	private final String text;

	Comparison(String text)
	{
		this.text = text;
	}

	public String getText()
	{
		return text;
	}

	public static Comparison of(int distance, int previousDistance)
	{
		return distance < previousDistance ? WARMER : distance == previousDistance ? SAME : COLDER;
	}
}

package com.cluehelper.hotcold;

import lombok.Value;

/** The strange device's game messages, verbatim as recorded in play. */
@Value
public class DeviceLine
{
	public enum Kind
	{
		READING,
		/** Upstairs and in other places the device refuses; the game's anchor stays on the last real reading. */
		NOT_HERE,
		/** After every master reading, in the same tick. */
		HURT,
		/** A feel with no hot/cold step. */
		INACTIVE,
		/** The dig that gives the casket. */
		FOUND
	}

	private static final String READING_START = "The device is ";
	private static final String SHAKING_START = "visibly shaking";
	private static final String NOT_HERE_TEXT = "The strange device doesn't seem to work here.";
	private static final String HURT_TEXT = "The power of the strange device hurts you in the process.";
	private static final String INACTIVE_TEXT = "The strange device is inactive.";
	private static final String FOUND_TEXT = "The strange device cools as you find your treasure.";
	private static final String WARMER_TEXT = "warmer than last time";
	private static final String SAME_TEXT = "the same temperature as last time";
	private static final String COLDER_TEXT = "colder than last time";

	Kind kind;
	Band band;
	/** Null on a step's first reading and on the shaking line. */
	Comparison comparison;

	/** @param text the message without tags; null when it isn't one of the device's lines */
	public static DeviceLine parse(String text)
	{
		if (text == null)
		{
			return null;
		}
		switch (text)
		{
			case NOT_HERE_TEXT:
				return new DeviceLine(Kind.NOT_HERE, null, null);
			case HURT_TEXT:
				return new DeviceLine(Kind.HURT, null, null);
			case INACTIVE_TEXT:
				return new DeviceLine(Kind.INACTIVE, null, null);
			case FOUND_TEXT:
				return new DeviceLine(Kind.FOUND, null, null);
			default:
				return reading(text);
		}
	}

	private static DeviceLine reading(String text)
	{
		if (!text.startsWith(READING_START))
		{
			return null;
		}
		String rest = text.substring(READING_START.length());
		if (rest.startsWith(SHAKING_START))
		{
			return new DeviceLine(Kind.READING, Band.SHAKING, null);
		}
		int end = rest.indexOf(',');
		Band band = Band.fromClause(end < 0 ? stripPeriod(rest) : rest.substring(0, end));
		if (band == null)
		{
			return null;
		}
		return new DeviceLine(Kind.READING, band, comparison(rest));
	}

	private static Comparison comparison(String rest)
	{
		if (rest.contains(WARMER_TEXT))
		{
			return Comparison.WARMER;
		}
		if (rest.contains(SAME_TEXT))
		{
			return Comparison.SAME;
		}
		return rest.contains(COLDER_TEXT) ? Comparison.COLDER : null;
	}

	private static String stripPeriod(String clause)
	{
		return clause.endsWith(".") ? clause.substring(0, clause.length() - 1) : clause;
	}
}

package com.cluehelper.hotcold;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Our own record of each hot/cold step's readings, the anchor the game compares against: it keeps it across logout,
 * hop, teleport and bank, which core doesn't. Stored as JSON per RuneScape profile, so its fields are its format.
 */
public final class FeelLogs
{
	/** A beginner and a master step held at once, each possibly with a League Tutor twin. */
	private static final int MOST_STEPS = 4;

	private Map<String, List<Reading>> steps = new LinkedHashMap<>();

	public List<Reading> get(String stepKey)
	{
		List<Reading> readings = steps == null ? null : steps.get(stepKey);
		return readings == null ? List.of() : List.copyOf(readings);
	}

	/** A reading without a comparison is a step's first, so it starts the step's log afresh. */
	public FeelLogs with(String stepKey, Reading reading)
	{
		FeelLogs next = copy();
		List<Reading> readings = reading.getComparison() == null && reading.getBand() != Band.SHAKING
			? new ArrayList<>() : new ArrayList<>(next.steps.getOrDefault(stepKey, List.of()));
		readings.add(reading);
		next.steps.remove(stepKey);
		next.steps.put(stepKey, readings);
		Iterator<String> oldest = next.steps.keySet().iterator();
		while (next.steps.size() > MOST_STEPS)
		{
			oldest.next();
			oldest.remove();
		}
		return next;
	}

	/**
	 * A solved step's readings say nothing about the next spot, but the game still compares the next clue's first
	 * reading of the tier with the last one, so that one stays as the anchor.
	 */
	public FeelLogs solved(String stepKey)
	{
		FeelLogs next = copy();
		List<Reading> readings = next.steps.remove(stepKey);
		if (readings != null && !readings.isEmpty())
		{
			next.steps.put(stepKey, new ArrayList<>(List.of(readings.get(readings.size() - 1).asAnchor())));
		}
		return next;
	}

	/** Readings of the step, anchors left out. */
	public static int feels(List<Reading> readings)
	{
		return (int) readings.stream().filter(reading -> !reading.isAnchor()).count();
	}

	/** The most recent step of the tier with a log, or null. */
	public String latestKey(String tierPrefix)
	{
		String latest = null;
		if (steps != null)
		{
			for (String key : steps.keySet())
			{
				if (key.startsWith(tierPrefix))
				{
					latest = key;
				}
			}
		}
		return latest;
	}

	private FeelLogs copy()
	{
		FeelLogs next = new FeelLogs();
		if (steps != null)
		{
			steps.forEach((key, readings) -> next.steps.put(key, new ArrayList<>(readings)));
		}
		return next;
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import java.util.List;
import java.util.Map;
import lombok.AccessLevel;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
@Builder(toBuilder = true, access = AccessLevel.PACKAGE)
public class HotColdPlan
{
	public enum Action
	{
		FEEL,
		/** The last reading shook: any shaking tile is a dig tile. */
		DIG_HERE,
		/** One spot is left, and one dig covers every tile of it the grid keeps. */
		DIG_SPOT,
		/** Spots are left but no probe tells them apart. */
		NONE
	}

	String stepKey;
	HotColdTier tier;
	Action action;
	/** The probe tile or the dig tile; null for {@link Action#NONE}. */
	WorldPoint tile;
	/** Set for {@link Action#FEEL}. */
	ProbePlanner.Choice choice;
	/** Kept spot names to their share, largest first. */
	Map<String, Double> kept;
	boolean exact;
	int readings;
	int probes;
	int landings;
	long nanos;
	long landingNanos;
	/** Every probe the choice weighed, for replays. */
	@Builder.Default
	List<Probe> considered = List.of();

	/** The next feel, at the probe the choice picked. */
	static HotColdPlan feel(HotColdPlanBuilder base, ProbePlanner.Choice choice)
	{
		return base.action(Action.FEEL).tile(choice.getProbe().getTile()).choice(choice).build();
	}

	static HotColdPlan digHere(HotColdPlanBuilder base, WorldPoint tile)
	{
		return base.action(Action.DIG_HERE).tile(tile).build();
	}

	static HotColdPlan digSpot(HotColdPlanBuilder base, WorldPoint tile)
	{
		return base.action(Action.DIG_SPOT).tile(tile).build();
	}

	static HotColdPlan none(HotColdPlanBuilder base)
	{
		return base.action(Action.NONE).build();
	}

	public boolean isDig()
	{
		return action == Action.DIG_HERE || action == Action.DIG_SPOT;
	}

	public List<ProbePlanner.Branch> branches()
	{
		return choice == null ? List.of() : choice.getBranches();
	}
}

