import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdLocation;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdSolver;
import net.runelite.client.util.Text;

/**
 * Client thread, except the plans, which run on their own {@link PlannerRunner} so they never supersede a route plan.
 * Reads core's hot/cold solver only at GameTick priority -1, and only ever copies its set.
 */
@Slf4j
@Singleton
public class HotColdService
{
	static final String KEY = "hotColdLogs";
	private static final int NO_CHECK = -1;
	/** Ranking-only ticks on a feel in the Wilderness while the Wilderness is avoided. */
	static final int WILDERNESS_PENALTY_TICKS = 20;
	/** Local probes: every second tile out to this, then every fourth out to {@link #LOCAL_FAR}. */
	private static final int LOCAL_NEAR = 8;
	private static final int LOCAL_FAR = 32;
	/** Above this the overworld ends; the device is unmeasured underground. */
	private static final int OVERWORLD_MAX_Y = 4500;
	private static final int NEAR_PROBE_TILES = 3;
	/** A feel this close to where "feel where you stand" was planned tells about the same. */
	private static final int HERE_DRIFT_TILES = 2;

	private final Client client;
	private final ClueLink clueLink;
	private final PlayerModel player;
	private final RoutePlanner routes;
	private final ProbeTarget probeTarget;
	private final StepData stepData;
	private final StepNeeds stepNeeds;
	private final AvailabilityService availability;
	private final ClueHelperConfig config;
	private final PlannerRunner runner;
	private final MemorySlot<FeelLogs> logs;
	private final List<Consumer<String>> traceListeners = new CopyOnWriteArrayList<>();
	private final List<Consumer<Planned>> planListeners = new CopyOnWriteArrayList<>();
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	private Runnable unregisterStep;
	private List<Spot> beginnerSpots;
	private List<Spot> masterSpots;
	private List<WorldPoint> landingTiles;
	private boolean planPending;
	private WorldPoint lastTile;
	@Getter
	private volatile HotColdPlan plan;
	private volatile Set<String> coreSpots = Set.of();
	private volatile boolean coreReset;

	/** A plan with what it was planned from, for replays. */
	@lombok.Value
	public static class Planned
	{
		ProbeJob job;
		HotColdPlan plan;
	}

	@Inject
	HotColdService(Client client, ClueLink clueLink, PlayerModel player, RoutePlanner routes, ProbeTarget probeTarget,
		StepData stepData, StepNeeds stepNeeds, AvailabilityService availability, ClueHelperConfig config, MemoryStore memory,
		ScheduledExecutorService executor, ClientThread clientThread)
	{
		this.stepNeeds = stepNeeds;
		this.availability = availability;
		this.client = client;
		this.clueLink = clueLink;
		this.player = player;
		this.routes = routes;
		this.probeTarget = probeTarget;
		this.stepData = stepData;
		this.config = config;
		this.runner = new PlannerRunner(executor, clientThread);
		this.logs = memory.slot(KEY, FeelLogs.class, FeelLogs::new);
	}

	public void start()
	{
		probeTarget.setEnabled(config.hotColdPlanner());
		unregisterStep = clueLink.addListener(this::onStepChange);
		planPending = true;
	}

	public void stop()
	{
		if (unregisterStep != null)
		{
			unregisterStep.run();
		}
		runner.cancelAll();
		probeTarget.clear();
		plan = null;
	}

	/** Runs on the client thread after each plan. */
	public Runnable addListener(Runnable listener)
	{
		listeners.add(listener);
		return () -> listeners.remove(listener);
	}

	/** Dev trace lines. */
	public Runnable addTraceListener(Consumer<String> listener)
	{
		traceListeners.add(listener);
		return () -> traceListeners.remove(listener);
	}

	public Runnable addPlanListener(Consumer<Planned> listener)
	{
		planListeners.add(listener);
		return () -> planListeners.remove(listener);
	}

	public void onConfigChanged()
	{
		probeTarget.setEnabled(config.hotColdPlanner());
		if (!config.hotColdPlanner())
		{
			runner.cancelAll();
			probeTarget.clear();
			plan = null;
		}
		planPending = true;
	}

	/** Call after a profile change: each profile has its own logs. */
	public void onProfileChanged()
	{
		probeTarget.clear();
		plan = null;
		planPending = true;
	}

	/** 3544 is set earlier in the same tick as the line, so any priority reads it. */
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		DeviceLine line = DeviceLine.parse(Text.removeTags(event.getMessage()));
		if (line == null)
		{
			return;
		}
		String key = logKey();
		if (key == null)
		{
			return;
		}
		if (line.getKind() == DeviceLine.Kind.FOUND)
		{
			logs.set(logs.get().solved(key));
			probeTarget.clear();
			plan = null;
			trace("found: log of " + key + " cleared, last reading kept as the anchor");
			return;
		}
		if (line.getKind() != DeviceLine.Kind.READING)
		{
			return;
		}
		Reading reading = reading(line);
		FeelLogs updated = logs.get().with(key, reading);
		logs.set(updated);
		planPending = true;
		trace("reading " + key + " " + reading.getX() + "," + reading.getY() + "," + reading.getPlane() + " " + line.getBand().getText()
			+ (line.getComparison() == null ? "" : ", " + line.getComparison().getText()) + " (log " + updated.get(key).size() + ")");
	}

	/** Call from a GameTick handler at priority -1, after the route planner's. */
	public void onGameTick()
	{
		Step step = clueLink.getCurrentStep();
		if (!isHotCold(step) || !config.hotColdPlanner())
		{
			return;
		}
		readCore();
		WorldPoint tile = player.getPosition().getTile();
		boolean jumped = PositionRules.teleported(lastTile, tile);
		lastTile = tile;
		HotColdPlan current = plan;
		boolean stale = current == null || !current.getStepKey().equals(step.getKey());
		if (jumped && current != null && current.getTile() != null
			&& (tile.getPlane() != current.getTile().getPlane() || tile.distanceTo2D(current.getTile()) > NEAR_PROBE_TILES))
		{
			planPending = true;
		}
		if (walkedOffHere(current, tile) && !runner.isWorking())
		{
			planPending = true;
		}
		if ((planPending || stale && !runner.isWorking()) && ownsDevice(step))
		{
			submit(step);
		}
	}

	private static boolean walkedOffHere(HotColdPlan current, WorldPoint tile)
	{
		boolean here = current != null && current.getChoice() != null && current.getChoice().getProbe().getKind() == Probe.Kind.HERE;
		return here && tile != null && (tile.getPlane() != current.getTile().getPlane() || tile.distanceTo2D(current.getTile()) > HERE_DRIFT_TILES);
	}

	private void onStepChange(StepChange change, Step step)
	{
		if (change == StepChange.CLEARED || change == StepChange.NEW)
		{
			forgetIfDug(plan);
			probeTarget.clear();
			plan = null;
		}
		if (change == StepChange.NEW && isHotCold(step))
		{
			planPending = true;
			if (config.hotColdPlanner() && ownsDevice(step))
			{
				probeTarget.choosing(step.getKey());
			}
		}
		if (change == StepChange.UPDATED && isHotCold(step))
		{
			listeners.forEach(Runnable::run);
		}
	}

	/**
	 * A beginner dig gives the next clue without the "cools" line, so a step that ends on its dig tile is taken as
	 * solved; otherwise the next clue of the tier would start from this one's readings. Banking the clue there is the
	 * case this misjudges.
	 */
	private void forgetIfDug(HotColdPlan last)
	{
		WorldPoint tile = player.getPosition().getTile();
		boolean dig = last != null && last.isDig();
		if (dig && tile != null && tile.getPlane() == last.getTile().getPlane()
			&& tile.distanceTo2D(last.getTile()) <= Band.digRadius(last.getTier()))
		{
			logs.set(logs.get().solved(last.getStepKey()));
			trace("dug at " + tile + ": log of " + last.getStepKey() + " cleared, last reading kept as the anchor");
		}
	}

	private void readCore()
	{
		ClueScroll clue = clueLink.coreClue();
		HotColdSolver solver = clue instanceof HotColdClue ? ((HotColdClue) clue).getHotColdSolver() : null;
		if (solver == null)
		{
			coreSpots = Set.of();
			coreReset = true;
			return;
		}
		Set<String> names = new HashSet<>();
		for (HotColdLocation location : new HashSet<>(solver.getPossibleLocations()))
		{
			names.add(location.name());
		}
		coreSpots = Set.copyOf(names);
		coreReset = solver.getLastWorldPoint() == null;
	}

	private void submit(Step step)
	{
		WalkData.Loaded walk = routes.getWalk();
		Step landings = walk == null ? null : landingStep(step, walk.getTable());
		PlanInput landingSearch = landings == null ? null : routes.inputFor(landings, stepNeeds.of(landings));
		if (landingSearch == null)
		{
			return;
		}
		planPending = false;
		HotColdTier tier = HotColdTier.of(step.getTier());
		boolean carried = carries(tier);
		ProbeJob job = ProbeJob.builder()
			.stepKey(step.getKey())
			.tier(tier)
			.spots(spots(tier))
			.readings(logs.get().get(step.getKey()))
			.here(carried && player.getPosition().getKind() == Position.Kind.WORLD ? player.getPosition().getTile() : null)
			.local(carried ? localProbes(walk) : List.of())
			.landingSearch(landingSearch)
			.costs(ProbePlanner.Costs.builder()
				.wildernessPenaltyTicks(landingSearch.getSettings().isAvoidWilderness() ? WILDERNESS_PENALTY_TICKS : 0).build())
			.avoidWilderness(landingSearch.getSettings().isAvoidWilderness())
			.build();
		trace("plan " + step.getKey() + " from " + job.getReadings().size() + " readings");
		runner.submit(job::run, result -> onPlanned(job, result));
	}

	private void onPlanned(ProbeJob job, HotColdPlan planned)
	{
		Step step = clueLink.getCurrentStep();
		if (step == null || !planned.getStepKey().equals(step.getKey()))
		{
			return;
		}
		plan = planned;
		probeTarget.set(target(planned));
		trace(describe(planned) + coreComparison(planned));
		planListeners.forEach(listener -> listener.accept(new Planned(job, planned)));
		listeners.forEach(Runnable::run);
	}

	private static ProbeTarget.Target target(HotColdPlan planned)
	{
		switch (planned.getAction())
		{
			case FEEL:
				boolean here = planned.getChoice().getProbe().getKind() == Probe.Kind.HERE;
				return new ProbeTarget.Target(planned.getStepKey(), planned.getTile(), here ? "Feel the device where you stand"
					: "Feel the device here", false, here);
			case DIG_HERE:
			case DIG_SPOT:
				return new ProbeTarget.Target(planned.getStepKey(), planned.getTile(), "Dig here", true, false);
			case NONE:
				return null;
			default:
				throw new IllegalArgumentException("unhandled action " + planned.getAction());
		}
	}

	/** The PROBES search's targets: every overworld walk node, each a landing or a walk away from one. */
	private Step landingStep(Step step, WalkTable table)
	{
		if (landingTiles == null)
		{
			List<WorldPoint> tiles = new ArrayList<>();
			for (int node = 0; node < table.nodeCount(); node++)
			{
				WorldPoint tile = table.tile(node);
				if (tile != null && tile.getPlane() == 0 && tile.getY() < OVERWORLD_MAX_Y)
				{
					tiles.add(tile);
				}
			}
			landingTiles = List.copyOf(tiles);
		}
		return step.toBuilder().kind(TargetKind.PROBES).targets(landingTiles)
			.requirements(step.getRequirements().plus(HotColdTier.of(step.getTier()).getDevice())).build();
	}

	private List<Probe> localProbes(WalkData.Loaded walk)
	{
		PlanStart start = routes.getStart();
		WorldPoint here = player.getPosition().getTile();
		if (start == null || start.getKind() != PlanStart.Kind.SCENE || start.getWalk() == null || here == null)
		{
			return List.of();
		}
		WalkCosts fromHere = start.getWalk();
		List<Probe> probes = new ArrayList<>();
		for (int dx = -LOCAL_FAR; dx <= LOCAL_FAR; dx++)
		{
			for (int dy = -LOCAL_FAR; dy <= LOCAL_FAR; dy++)
			{
				int reach = Math.max(Math.abs(dx), Math.abs(dy));
				int stride = reach <= LOCAL_NEAR ? 2 : 4;
				if (reach == 0 || dx % stride != 0 || dy % stride != 0)
				{
					continue;
				}
				WorldPoint tile = new WorldPoint(here.getX() + dx, here.getY() + dy, here.getPlane());
				int cost = fromHere.cost(tile);
				if (cost != WalkCosts.UNREACHED)
				{
					int ticks = (cost + 1) / 2;
					probes.add(new Probe(tile, Probe.Kind.LOCAL, ticks, ticks, OriginClass.of(tile, walk.getNoTeleport()).isWilderness()));
				}
			}
		}
		return probes;
	}

	private List<Spot> spots(HotColdTier tier)
	{
		if (beginnerSpots == null)
		{
			beginnerSpots = Spots.of(stepData.index(), HotColdTier.BEGINNER);
			masterSpots = Spots.of(stepData.index(), HotColdTier.MASTER);
		}
		return tier == HotColdTier.BEGINNER ? beginnerSpots : masterSpots;
	}

	/**
	 * The current hot/cold step's, or, while core has no clue (banked, not read), the newest log of the carried device's
	 * tier: the device works without the clue.
	 */
	private String logKey()
	{
		Step step = clueLink.getCurrentStep();
		if (isHotCold(step))
		{
			return step.getKey();
		}
		boolean beginner = carries(HotColdTier.BEGINNER);
		boolean master = carries(HotColdTier.MASTER);
		if (beginner == master)
		{
			return master ? logs.get().latestKey(StepKey.HOT_COLD_PREFIX) : null;
		}
		HotColdTier tier = beginner ? HotColdTier.BEGINNER : HotColdTier.MASTER;
		String latest = logs.get().latestKey(StepKey.hotColdPrefix(tier));
		return latest != null ? latest : StepKey.hotCold(tier, tier.getDeviceNpc());
	}

	private Reading reading(DeviceLine line)
	{
		int coord = client.getVarpValue(VarPlayerID.TRAIL_HOTCOLD_LAST_CHECK_COORD);
		if (coord == NO_CHECK)
		{
			WorldPoint tile = player.getPosition().getTile();
			return new Reading(tile.getX(), tile.getY(), tile.getPlane(), line.getBand(), line.getComparison());
		}
		return new Reading(coord >> 14 & 0x3FFF, coord & 0x3FFF, coord >> 28 & 3, line.getBand(), line.getComparison());
	}

	/** Carried, or in the remembered bank: the probe routes then start with a bank stop for it. */
	private boolean ownsDevice(Step step)
	{
		HotColdTier tier = HotColdTier.of(step.getTier());
		if (carries(tier))
		{
			return true;
		}
		PlayerSnapshot banked = availability.getBankedSnapshot();
		return banked != null && banked.getBank().containsKey(tier.getDeviceItemId());
	}

	private boolean carries(HotColdTier tier)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		return snapshot != null && snapshot.getInventory().containsKey(tier.getDeviceItemId());
	}

	private static boolean isHotCold(Step step)
	{
		return step != null && ClueTypes.HOT_COLD.equals(step.getType());
	}

	/** Dev only: starts the current hot/cold step's log again, its last reading kept as the anchor. */
	public String restartLog()
	{
		Step step = clueLink.getCurrentStep();
		if (!isHotCold(step))
		{
			return "No hot/cold step";
		}
		logs.set(logs.get().solved(step.getKey()));
		planPending = true;
		return "Feel log of " + step.getKey() + " restarted";
	}

	/** Dev only. */
	public List<String> describeLog()
	{
		Step step = clueLink.getCurrentStep();
		if (!isHotCold(step))
		{
			return List.of("No hot/cold step");
		}
		List<String> lines = new ArrayList<>();
		List<Reading> readings = logs.get().get(step.getKey());
		lines.add(step.getKey() + ": " + readings.size() + " readings");
		readings.forEach(reading -> lines.add("  " + reading));
		HotColdPlan current = plan;
		lines.add(current == null ? "no plan" : describe(current));
		return lines;
	}

	public Set<String> getCoreSpots()
	{
		return coreSpots;
	}

	public boolean isCoreReset()
	{
		return coreReset;
	}

	public int hitpoints()
	{
		return client.getBoostedSkillLevel(Skill.HITPOINTS);
	}

	public List<Spot> spotsOf(HotColdTier tier)
	{
		return spots(tier);
	}

	/** For the verdict "did the grid keep a spot core dropped". */
	private String coreComparison(HotColdPlan planned)
	{
		Set<String> core = coreSpots;
		List<String> dropped = new ArrayList<>();
		for (String spot : planned.getKept().keySet())
		{
			if (!core.contains(spot))
			{
				dropped.add(spot);
			}
		}
		return "; core " + core.size() + (coreReset ? " (reset)" : "") + (dropped.isEmpty() ? "" : ", core dropped " + dropped);
	}

	private static String describe(HotColdPlan planned)
	{
		StringBuilder line = new StringBuilder(planned.getAction().name()).append(' ').append(planned.getTile())
			.append(" kept ").append(planned.getKept().size()).append(planned.isExact() ? "" : " (closest fits)")
			.append(" from ").append(planned.getReadings()).append(" readings");
		if (planned.getChoice() != null)
		{
			ProbePlanner.Choice choice = planned.getChoice();
			line.append(" probe ").append(choice.getProbe().getKind()).append(' ').append(choice.getProbe().getTicks()).append('t')
				.append(String.format(" %.2f bits cost %d", choice.getBits(), choice.getCostTicks()))
				.append(" branches ").append(choice.getBranches().size());
		}
		return line.append(" probes ").append(planned.getProbes()).append(" landings ").append(planned.getLandings())
			.append(" in ").append(planned.getNanos() / 1_000_000).append(" ms (landings ").append(planned.getLandingNanos() / 1_000_000)
			.append(" ms)").toString();
	}

	private void trace(String line)
	{
		log.debug("hot/cold {}", line);
		traceListeners.forEach(listener -> listener.accept(line));
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * The box's hot/cold lines. The branch preview names only core's candidates, grouped by the reading each would give
 * at the probe: never a candidate list of our own.
 */
@Value
public class HotColdView
{
	private static final int MOST_BRANCHES = 3;
	private static final int NAMED_SPOTS = 2;
	/** The most a master feel dealt in 13 recorded feels. */
	private static final int MOST_FEEL_DAMAGE = 8;
	private static final int NAMED_AREAS = 2;

	String title;
	/** "Next feel" and the branch lines. */
	List<String> lines;
	List<String> warnings;

	@Value
	public static class Inputs
	{
		HotColdPlan plan;
		/** A copy of core's remaining spots. */
		Set<String> coreSpots;
		boolean coreReset;
		List<Spot> spots;
		HotColdTier tier;
		int hitpoints;
	}

	public static HotColdView of(Inputs in)
	{
		HotColdPlan plan = in.getPlan();
		if (plan == null)
		{
			return null;
		}
		Map<String, Spot> spots = in.getSpots().stream().collect(Collectors.toMap(Spot::getName, spot -> spot));
		List<String> lines = new ArrayList<>();
		List<String> warnings = new ArrayList<>();
		int kept = plan.getKept().size();
		String title;
		switch (plan.getAction())
		{
			case DIG_HERE:
				title = "The device shook: dig on that tile";
				break;
			case DIG_SPOT:
				title = "Only " + name(spots, plan.getKept().keySet().iterator().next()) + " fits";
				break;
			case NONE:
				title = kept + " spots fit, and no feel tells them apart";
				break;
			case FEEL:
				title = plan.getReadings() == 0 ? "No feels yet: " + kept + " spots" : kept + " spots fit your " + plan.getReadings() + feels(plan.getReadings());
				Probe probe = plan.getChoice().getProbe();
				lines.add(probe.getKind() == Probe.Kind.HERE ? "Feel where you stand:" : "Next feel:");
				lines.addAll(branchLines(plan, in.getCoreSpots(), spots));
				break;
			default:
				throw new IllegalArgumentException("unhandled action " + plan.getAction());
		}
		if (in.getTier() == HotColdTier.MASTER && plan.getAction() == HotColdPlan.Action.FEEL && in.getHitpoints() <= MOST_FEEL_DAMAGE)
		{
			warnings.add("HP " + in.getHitpoints() + ": the next feel can kill you (master feels deal 4–8)");
		}
		if (!plan.isExact())
		{
			warnings.add("No spot fits every feel; these fit the most");
		}
		if (in.isCoreReset() && plan.getReadings() > 0)
		{
			warnings.add("The Clue Scroll plugin's list was reset; Clue Helper still counts your " + plan.getReadings() + feels(plan.getReadings()));
		}
		else if (!in.getCoreSpots().isEmpty() && !in.getCoreSpots().containsAll(plan.getKept().keySet()))
		{
			warnings.add("Core's list may have dropped the spot. Re-read the clue and feel again");
		}
		borderNote(plan, spots).ifPresent(warnings::add);
		return new HotColdView(title, List.copyOf(lines), List.copyOf(warnings));
	}

	private static Optional<String> borderNote(HotColdPlan plan, Map<String, Spot> spots)
	{
		boolean digging = plan.isDig();
		if (!digging || plan.getKept().isEmpty())
		{
			return Optional.empty();
		}
		Spot spot = spots.get(plan.getKept().keySet().iterator().next());
		return spot != null && spot.isBorder()
			? Optional.of("Dig on the single-combat side to face one Brassican Mage")
			: Optional.empty();
	}

	/** Each core candidate goes to the reading it most likely gives; hotter readings first. */
	private static List<String> branchLines(HotColdPlan plan, Set<String> coreSpots, Map<String, Spot> spots)
	{
		List<ProbePlanner.Branch> branches = plan.branches();
		Map<ProbePlanner.Branch, List<String>> grouped = new LinkedHashMap<>();
		for (String name : plan.getKept().keySet())
		{
			if (!coreSpots.isEmpty() && !coreSpots.contains(name))
			{
				continue;
			}
			branches.stream()
				.filter(branch -> branch.getSpots().containsKey(name))
				.max(Comparator.comparingDouble(branch -> branch.getProbability() * branch.getSpots().get(name)))
				.ifPresent(branch -> grouped.computeIfAbsent(branch, b -> new ArrayList<>()).add(name));
		}
		List<ProbePlanner.Branch> order = new ArrayList<>(grouped.keySet());
		order.sort(Comparator.comparing((ProbePlanner.Branch b) -> b.getBand().ordinal())
			.thenComparing(b -> b.getComparison() == null ? -1 : b.getComparison().ordinal()));
		List<String> lines = new ArrayList<>();
		int others = 0;
		for (int i = 0; i < order.size(); i++)
		{
			ProbePlanner.Branch branch = order.get(i);
			if (i >= MOST_BRANCHES && order.size() > MOST_BRANCHES + 1)
			{
				others += grouped.get(branch).size();
				continue;
			}
			lines.add("If " + label(branch, order) + ": " + group(grouped.get(branch), spots));
		}
		if (others > 0)
		{
			lines.add("Else: " + others + " other" + (others == 1 ? "" : "s"));
		}
		return lines;
	}

	/** The comparison is named only where two shown branches share a band. */
	private static String label(ProbePlanner.Branch branch, List<ProbePlanner.Branch> shown)
	{
		long sameBand = shown.stream().filter(other -> other.getBand() == branch.getBand()).count();
		return sameBand > 1 ? branch.label() : branch.getBand().getText();
	}

	private static String group(List<String> names, Map<String, Spot> spots)
	{
		if (names.size() <= NAMED_SPOTS)
		{
			return names.stream().map(name -> name(spots, name)).collect(Collectors.joining("; "));
		}
		Map<String, Integer> areas = new TreeMap<>();
		for (String name : names)
		{
			Spot spot = spots.get(name);
			areas.merge(spot == null ? "?" : spot.getArea(), 1, Integer::sum);
		}
		String byArea = areas.entrySet().stream()
			.sorted((a, b) -> b.getValue() - a.getValue())
			.limit(NAMED_AREAS)
			.map(e -> e.getKey() + " " + e.getValue())
			.collect(Collectors.joining(", "));
		return names.size() + " spots (" + byArea + (areas.size() > NAMED_AREAS ? ", …" : "") + ")";
	}

	private static String name(Map<String, Spot> spots, String name)
	{
		Spot spot = spots.get(name);
		return spot == null ? name : spot.getDescription();
	}

	private static String feels(int readings)
	{
		return readings == 1 ? " feel" : " feels";
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Every tile within each spot's radius of its centre, kept while it explains the step's readings exactly: the band from
 * the Chebyshev distance, and each comparison against the previous reading of the log. When no tile explains them all,
 * the tiles with the fewest misses are kept instead, so the grid never empties.
 */
public final class Hypotheses
{
	/** 133 of 140 cache centres equal core's, so a spot's prior sits mostly on its centre. */
	private static final double CENTRE_SHARE = 0.5;

	private final List<Spot> spots;
	private final int[] x;
	private final int[] y;
	private final int[] spot;
	private final double[] weight;
	private final int misses;

	private Hypotheses(List<Spot> spots, int[] x, int[] y, int[] spot, double[] weight, int misses)
	{
		this.spots = spots;
		this.x = x;
		this.y = y;
		this.spot = spot;
		this.weight = weight;
		this.misses = misses;
	}

	public static Hypotheses filter(List<Spot> spots, HotColdTier tier, List<Reading> readings)
	{
		List<List<WorldPoint>> tiles = new ArrayList<>();
		for (Reading reading : readings)
		{
			tiles.add(reading.tiles());
		}
		List<int[]> kept = new ArrayList<>();
		int fewest = Integer.MAX_VALUE;
		for (int s = 0; s < spots.size(); s++)
		{
			Spot candidate = spots.get(s);
			int r = candidate.getRadius();
			for (int dx = -r; dx <= r; dx++)
			{
				for (int dy = -r; dy <= r; dy++)
				{
					int hx = candidate.getX() + dx;
					int hy = candidate.getY() + dy;
					int missed = misses(hx, hy, readings, tiles, tier, fewest);
					if (missed < fewest)
					{
						fewest = missed;
						kept.clear();
					}
					if (missed == fewest)
					{
						kept.add(new int[]{hx, hy, s, dx == 0 && dy == 0 ? 1 : 0});
					}
				}
			}
		}
		int n = kept.size();
		int[] x = new int[n];
		int[] y = new int[n];
		int[] spot = new int[n];
		double[] weight = new double[n];
		for (int i = 0; i < n; i++)
		{
			int[] h = kept.get(i);
			x[i] = h[0];
			y[i] = h[1];
			spot[i] = h[2];
			weight[i] = priorWeight(spots.get(h[2]), h[3] == 1);
		}
		return new Hypotheses(spots, x, y, spot, weight, fewest == Integer.MAX_VALUE ? 0 : fewest);
	}

	/** Counting stops past {@code enough}: such a tile is dropped anyway. */
	private static int misses(int hx, int hy, List<Reading> readings, List<List<WorldPoint>> tiles, HotColdTier tier, int enough)
	{
		int missed = 0;
		for (int i = 0; i < readings.size() && missed <= enough; i++)
		{
			Reading reading = readings.get(i);
			if (!reading.isAnchor() && !fitsBand(hx, hy, reading.getBand(), tiles.get(i), tier))
			{
				missed++;
			}
			if (i > 0 && reading.getComparison() != null && !fitsComparison(hx, hy, reading.getComparison(), tiles.get(i), tiles.get(i - 1)))
			{
				missed++;
			}
		}
		return missed;
	}

	private static boolean fitsBand(int hx, int hy, Band band, List<WorldPoint> at, HotColdTier tier)
	{
		for (WorldPoint tile : at)
		{
			if (Band.of(distance(tile, hx, hy), tier) == band)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean fitsComparison(int hx, int hy, Comparison comparison, List<WorldPoint> at, List<WorldPoint> before)
	{
		for (WorldPoint tile : at)
		{
			for (WorldPoint previous : before)
			{
				if (Comparison.of(distance(tile, hx, hy), distance(previous, hx, hy)) == comparison)
				{
					return true;
				}
			}
		}
		return false;
	}

	static int distance(WorldPoint tile, int hx, int hy)
	{
		return Math.max(Math.abs(tile.getX() - hx), Math.abs(tile.getY() - hy));
	}

	private static double priorWeight(Spot spot, boolean centre)
	{
		int side = 2 * spot.getRadius() + 1;
		return centre ? CENTRE_SHARE : (1 - CENTRE_SHARE) / (side * side - 1);
	}

	public boolean isExact()
	{
		return misses == 0;
	}

	/** Each kept spot's share of the posterior, largest first. */
	public Map<String, Double> spotShares()
	{
		double[] mass = new double[spots.size()];
		double total = 0;
		for (int i = 0; i < x.length; i++)
		{
			mass[spot[i]] += weight[i];
			total += weight[i];
		}
		List<Integer> order = new ArrayList<>();
		for (int s = 0; s < mass.length; s++)
		{
			if (mass[s] > 0)
			{
				order.add(s);
			}
		}
		order.sort((a, b) -> Double.compare(mass[b], mass[a]));
		Map<String, Double> shares = new LinkedHashMap<>();
		for (int s : order)
		{
			shares.put(spots.get(s).getName(), mass[s] / total);
		}
		return shares;
	}

	public List<Spot> keptSpots()
	{
		List<Spot> kept = new ArrayList<>();
		for (String name : spotShares().keySet())
		{
			kept.add(spot(name));
		}
		return kept;
	}

	public Spot spot(String name)
	{
		for (Spot candidate : spots)
		{
			if (candidate.getName().equals(name))
			{
				return candidate;
			}
		}
		return null;
	}

	/** The tile nearest, by Chebyshev, to the farthest kept tile of the spot: a dig there covers them all if any tile does. */
	public WorldPoint digTile(String spotName)
	{
		int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
		for (int i = 0; i < x.length; i++)
		{
			if (spots.get(spot[i]).getName().equals(spotName))
			{
				minX = Math.min(minX, x[i]);
				minY = Math.min(minY, y[i]);
				maxX = Math.max(maxX, x[i]);
				maxY = Math.max(maxY, y[i]);
			}
		}
		return minX == Integer.MAX_VALUE ? null : new WorldPoint((minX + maxX) / 2, (minY + maxY) / 2, 0);
	}

	/** Up to {@code perSpot} kept tiles of each spot, the centre first, weighted to keep each spot's share. */
	public Samples sample(int perSpot)
	{
		List<Integer> spotIndex = new ArrayList<>();
		List<String> names = new ArrayList<>();
		List<int[]> picked = new ArrayList<>();
		List<Double> weights = new ArrayList<>();
		double total = 0;
		for (double w : weight)
		{
			total += w;
		}
		for (int s = 0; s < spots.size(); s++)
		{
			List<Integer> mine = new ArrayList<>();
			double mass = 0;
			for (int i = 0; i < x.length; i++)
			{
				if (spot[i] == s)
				{
					mine.add(i);
					mass += weight[i];
				}
			}
			if (mine.isEmpty())
			{
				continue;
			}
			int compact = names.size();
			names.add(spots.get(s).getName());
			spotIndex.add(s);
			List<Integer> chosen = spread(mine, perSpot, spots.get(s));
			double chosenMass = 0;
			for (int i : chosen)
			{
				chosenMass += weight[i];
			}
			for (int i : chosen)
			{
				picked.add(new int[]{x[i], y[i], compact});
				weights.add(weight[i] / chosenMass * mass / total);
			}
		}
		int n = picked.size();
		int[] sx = new int[n];
		int[] sy = new int[n];
		int[] ss = new int[n];
		double[] sw = new double[n];
		for (int i = 0; i < n; i++)
		{
			sx[i] = picked.get(i)[0];
			sy[i] = picked.get(i)[1];
			ss[i] = picked.get(i)[2];
			sw[i] = weights.get(i);
		}
		return new Samples(List.copyOf(names), sx, sy, ss, sw);
	}

	private List<Integer> spread(List<Integer> mine, int perSpot, Spot owner)
	{
		if (mine.size() <= perSpot)
		{
			return mine;
		}
		List<Integer> chosen = new ArrayList<>();
		for (int i : mine)
		{
			if (x[i] == owner.getX() && y[i] == owner.getY())
			{
				chosen.add(i);
			}
		}
		int wanted = perSpot - chosen.size();
		for (int k = 0; k < wanted; k++)
		{
			int i = mine.get((int) ((long) k * mine.size() / wanted));
			if (!chosen.contains(i))
			{
				chosen.add(i);
			}
		}
		return chosen;
	}

	/** Sampled hypotheses with weights summing to 1; spots are indexed into {@link #names}. */
	public static final class Samples
	{
		final List<String> names;
		final int[] x;
		final int[] y;
		final int[] spot;
		final double[] weight;

		Samples(List<String> names, int[] x, int[] y, int[] spot, double[] weight)
		{
			this.names = names;
			this.x = x;
			this.y = y;
			this.spot = spot;
			this.weight = weight;
		}

		public int spotCount()
		{
			return names.size();
		}
	}
}

package com.cluehelper.hotcold;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** A tile to feel on, and what getting there costs. */
@Value
public class Probe
{
	public enum Kind
	{
		/** Where the player stands. */
		HERE,
		/** A tile in the loaded scene, walked to. */
		LOCAL,
		/** A walk-table node, by the route planner's Best rule. */
		LANDING
	}

	WorldPoint tile;
	Kind kind;
	/** The route's shown ticks. */
	int ticks;
	/** The route's ranking ticks: its ticks plus penalties such as a Magic cape use. */
	int rankTicks;
	boolean wilderness;
}

package com.cluehelper.hotcold;

import com.cluehelper.route.OriginClass;
import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanInput;
import com.cluehelper.route.Planner;
import com.cluehelper.step.HotColdTier;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** One plan after a feel: filter the grid, gather probes, choose. Snapshot data only, so it runs on the executor. */
@Value
@Builder
public class ProbeJob
{
	/** Kept tiles per spot that the scoring sees; a radius of at most 3 gives up to 49. */
	private static final int SAMPLES_PER_SPOT = 9;

	String stepKey;
	HotColdTier tier;
	List<Spot> spots;
	List<Reading> readings;
	WorldPoint here;
	/** Scene tiles near the player with their walk in ticks. */
	List<Probe> local;
	/** A PROBES search over every landing tile; null when the route planner isn't ready. */
	PlanInput landingSearch;
	ProbePlanner.Costs costs;
	boolean avoidWilderness;

	public HotColdPlan run()
	{
		long started = System.nanoTime();
		List<Probe> probes = new ArrayList<>();
		if (here != null)
		{
			probes.add(new Probe(here, Probe.Kind.HERE, 0, 0, wilderness(here)));
		}
		for (Probe tile : local)
		{
			if (!avoidWilderness || !tile.isWilderness())
			{
				probes.add(tile);
			}
		}
		boolean needsProbes = readings.isEmpty() || readings.get(readings.size() - 1).getBand() != Band.SHAKING;
		int landings = needsProbes ? addLandings(probes) : 0;
		long landingNanos = System.nanoTime() - started;
		return decide(stepKey, spots, tier, readings, probes, costs).toBuilder()
			.landings(landings).landingNanos(landingNanos).considered(List.copyOf(probes)).nanos(System.nanoTime() - started).build();
	}

	/** The rules after the probes are in, shared with the simulator. */
	public static HotColdPlan decide(String stepKey, List<Spot> spots, HotColdTier tier, List<Reading> readings, List<Probe> probes,
		ProbePlanner.Costs costs)
	{
		Hypotheses grid = Hypotheses.filter(spots, tier, readings);
		HotColdPlan.HotColdPlanBuilder plan = HotColdPlan.builder().stepKey(stepKey).tier(tier).kept(grid.spotShares())
			.exact(grid.isExact()).readings(FeelLogs.feels(readings)).probes(probes.size());
		Reading last = readings.isEmpty() ? null : readings.get(readings.size() - 1);
		if (last != null && last.getBand() == Band.SHAKING)
		{
			return HotColdPlan.digHere(plan, new WorldPoint(last.getX(), last.getY(), last.getPlane()));
		}
		List<Spot> kept = grid.keptSpots();
		if (kept.size() == 1)
		{
			return HotColdPlan.digSpot(plan, grid.digTile(kept.get(0).getName()));
		}
		ProbePlanner.Choice choice = ProbePlanner.choose(grid.sample(SAMPLES_PER_SPOT), tier, last, probes, costs);
		if (choice == null)
		{
			return HotColdPlan.none(plan);
		}
		return HotColdPlan.feel(plan, choice);
	}

	private int addLandings(List<Probe> probes)
	{
		if (landingSearch == null)
		{
			return 0;
		}
		Plan landings = Planner.plan(landingSearch);
		Map<WorldPoint, Integer> ranks = landings.getProbeRanks();
		landings.getProbeTicks().forEach((tile, ticks) ->
			probes.add(new Probe(tile, Probe.Kind.LANDING, ticks, ranks.getOrDefault(tile, ticks), wilderness(tile))));
		return landings.getProbeTicks().size();
	}

	private boolean wilderness(WorldPoint tile)
	{
		return landingSearch != null && OriginClass.of(tile, landingSearch.getNoTeleport()).isWilderness();
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Picks the probe with the most information per tick: the mutual information between the next reading and the spot,
 * over the sampled hypotheses, divided by the probe's cost. Predicts readings with the same rules {@link Hypotheses}
 * filters by, so a probe it values can't leave the grid as it was. Pure.
 */
public final class ProbePlanner
{
	/** A feel doesn't stop movement; the click and the chat line take about a tick. */
	public static final int FEEL_TICKS = 1;
	/** Below this a probe can't tell any two spots apart. */
	private static final double MIN_BITS = 1e-6;
	private static final int COMPARISONS = Comparison.values().length + 1;
	private static final int OUTCOMES = Band.values().length * COMPARISONS;
	private static final double LOG2 = Math.log(2);
	/** With this few spots left the next feel can end the solve, so the trip from the probe to the dig counts too. */
	private static final int ONWARD_SPOTS = 3;

	private ProbePlanner()
	{
	}

	@Value
	@Builder
	public static class Costs
	{
		int wildernessPenaltyTicks;
	}

	@Value
	public static class Branch
	{
		Band band;
		/** Null when the reading would have no comparison. */
		Comparison comparison;
		double probability;
		/** Spot name to its share within this branch, largest first. */
		Map<String, Double> spots;

		public String label()
		{
			return comparison == null ? band.getText() : band.getText() + ", " + comparison.getText();
		}
	}

	@Value
	public static class Choice
	{
		Probe probe;
		double bits;
		int costTicks;
		/** Most likely first. */
		List<Branch> branches;
	}

	/**
	 * @param previous the log's last reading, or null; the next reading is compared against it
	 * @return null when no probe tells the spots apart
	 */
	public static Choice choose(Hypotheses.Samples samples, HotColdTier tier, Reading previous, List<Probe> probes, Costs costs)
	{
		WorldPoint before = previous == null ? null : previous.tiles().get(0);
		double prior = entropy(spotMasses(samples));
		double[] table = new double[OUTCOMES * samples.spotCount()];
		int[] touched = new int[samples.x.length];
		double[] outcomeMass = new double[OUTCOMES];
		int[] digTicks = samples.spotCount() <= ONWARD_SPOTS ? digTicks(samples, probes) : null;
		Probe best = null;
		double bestScore = 0;
		double bestBits = 0;
		int bestCost = 0;
		for (Probe probe : probes)
		{
			double bits = prior - conditionalEntropy(table, touched, outcomeMass, samples, tier, before, probe.getTile());
			if (bits < MIN_BITS)
			{
				continue;
			}
			int cost = cost(probe, costs) + (digTicks == null ? 0 : onward(samples, digTicks, probe.getTile()));
			double score = bits / cost;
			if (best == null || score > bestScore || score == bestScore && cost < bestCost)
			{
				best = probe;
				bestScore = score;
				bestBits = bits;
				bestCost = cost;
			}
		}
		if (best == null)
		{
			return null;
		}
		return new Choice(best, bestBits, bestCost, branches(samples, tier, before, best.getTile()));
	}

	static int cost(Probe probe, Costs costs)
	{
		return probe.getRankTicks() + FEEL_TICKS + (probe.isWilderness() ? costs.getWildernessPenaltyTicks() : 0);
	}

	/**
	 * Each spot's dig as if reached from here: the cheapest probe near it plus the walk, which teleports make about the
	 * same from anywhere.
	 */
	private static int[] digTicks(Hypotheses.Samples samples, List<Probe> probes)
	{
		int spots = samples.spotCount();
		int[] ticks = new int[spots];
		for (int s = 0; s < spots; s++)
		{
			WorldPoint centre = centre(samples, s);
			int best = Integer.MAX_VALUE;
			for (Probe probe : probes)
			{
				best = Math.min(best, probe.getRankTicks() + walkTicks(probe.getTile(), centre.getX(), centre.getY()));
			}
			ticks[s] = best;
		}
		return ticks;
	}

	/** The expected trip from the probe to the dig: a walk when it's near, else as from here. */
	private static int onward(Hypotheses.Samples samples, int[] digTicks, WorldPoint at)
	{
		double ticks = 0;
		for (int i = 0; i < samples.x.length; i++)
		{
			ticks += samples.weight[i] * Math.min(walkTicks(at, samples.x[i], samples.y[i]), digTicks[samples.spot[i]]);
		}
		return (int) Math.round(ticks);
	}

	private static int walkTicks(WorldPoint from, int x, int y)
	{
		return (Hypotheses.distance(from, x, y) + 1) / 2;
	}

	private static WorldPoint centre(Hypotheses.Samples samples, int spot)
	{
		double x = 0, y = 0, mass = 0;
		for (int i = 0; i < samples.x.length; i++)
		{
			if (samples.spot[i] == spot)
			{
				x += samples.weight[i] * samples.x[i];
				y += samples.weight[i] * samples.y[i];
				mass += samples.weight[i];
			}
		}
		return new WorldPoint((int) Math.round(x / mass), (int) Math.round(y / mass), 0);
	}

	/** {@code table} must be all zeros, and is again on return; {@code touched} holds at least one slot per sample. */
	private static double conditionalEntropy(double[] table, int[] touched, double[] outcomeMass, Hypotheses.Samples samples,
		HotColdTier tier, WorldPoint before, WorldPoint at)
	{
		int spots = samples.spotCount();
		int n = 0;
		for (int i = 0; i < samples.x.length; i++)
		{
			int cell = outcome(samples.x[i], samples.y[i], tier, before, at) * spots + samples.spot[i];
			if (table[cell] == 0)
			{
				touched[n++] = cell;
			}
			table[cell] += samples.weight[i];
		}
		double spread = 0;
		for (int t = 0; t < n; t++)
		{
			int cell = touched[t];
			double m = table[cell];
			spread += m * Math.log(m);
			outcomeMass[cell / spots] += m;
			table[cell] = 0;
		}
		double sum = -spread;
		for (int o = 0; o < OUTCOMES; o++)
		{
			if (outcomeMass[o] > 0)
			{
				sum += outcomeMass[o] * Math.log(outcomeMass[o]);
				outcomeMass[o] = 0;
			}
		}
		return sum / LOG2;
	}

	static int outcome(int hx, int hy, HotColdTier tier, WorldPoint before, WorldPoint at)
	{
		int distance = Hypotheses.distance(at, hx, hy);
		Band band = Band.of(distance, tier);
		if (before == null || band == Band.SHAKING)
		{
			return band.ordinal() * COMPARISONS;
		}
		return band.ordinal() * COMPARISONS + 1 + Comparison.of(distance, Hypotheses.distance(before, hx, hy)).ordinal();
	}

	private static List<Branch> branches(Hypotheses.Samples samples, HotColdTier tier, WorldPoint before, WorldPoint at)
	{
		int spots = samples.spotCount();
		double[] table = new double[OUTCOMES * spots];
		for (int i = 0; i < samples.x.length; i++)
		{
			table[outcome(samples.x[i], samples.y[i], tier, before, at) * spots + samples.spot[i]] += samples.weight[i];
		}
		List<Branch> branches = new ArrayList<>();
		for (int o = 0; o < OUTCOMES; o++)
		{
			double total = 0;
			for (int s = 0; s < spots; s++)
			{
				total += table[o * spots + s];
			}
			if (total <= 0)
			{
				continue;
			}
			List<Integer> order = new ArrayList<>();
			for (int s = 0; s < spots; s++)
			{
				if (table[o * spots + s] > 0)
				{
					order.add(s);
				}
			}
			int row = o;
			order.sort((a, b) -> Double.compare(table[row * spots + b], table[row * spots + a]));
			Map<String, Double> shares = new LinkedHashMap<>();
			for (int s : order)
			{
				shares.put(samples.names.get(s), table[o * spots + s] / total);
			}
			int c = o % COMPARISONS;
			branches.add(new Branch(Band.values()[o / COMPARISONS], c == 0 ? null : Comparison.values()[c - 1], total, shares));
		}
		branches.sort((a, b) -> Double.compare(b.getProbability(), a.getProbability()));
		return branches;
	}

	private static double[] spotMasses(Hypotheses.Samples samples)
	{
		double[] mass = new double[samples.spotCount()];
		for (int i = 0; i < samples.x.length; i++)
		{
			mass[samples.spot[i]] += samples.weight[i];
		}
		return mass;
	}

	private static double entropy(double[] masses)
	{
		double h = 0;
		for (double m : masses)
		{
			if (m > 0)
			{
				h -= m * Math.log(m);
			}
		}
		return h / LOG2;
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.ClueTypes;
import com.cluehelper.step.HotColdTier;
import com.cluehelper.step.SpadeNeed;
import com.cluehelper.step.Step;
import com.cluehelper.step.TargetKind;
import java.util.List;
import java.util.Set;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * The hot/cold planner's chosen tile, which the route planner and the guide travel to instead of core's spots. Kept
 * apart from the planner so neither of them depends on it. Any thread.
 */
@Singleton
public class ProbeTarget
{
	@Value
	public static class Target
	{
		String stepKey;
		/** Null while the first plan is still being made. */
		WorldPoint tile;
		String act;
		boolean dig;
		/** Feel where you stand: the tile is where the plan was made, not a place to walk to. */
		boolean here;
	}

	private volatile Target target;
	private volatile boolean enabled;

	/** With the planner off a hot/cold step stays core's, which has no route. */
	public void setEnabled(boolean planner)
	{
		enabled = planner;
	}

	public void set(Target chosen)
	{
		target = chosen;
	}

	public void clear()
	{
		target = null;
	}

	/** Until the first plan arrives the step has no target, rather than core's NPC the player needn't visit. */
	public void choosing(String stepKey)
	{
		target = new Target(stepKey, null, null, false, false);
	}

	/**
	 * The step to route and guide: a hot/cold step goes to the chosen tile, or, before a choice, to the nearest of
	 * core's tiles (the NPC who gives the device, before the first feel). Any other step is returned as it is.
	 */
	public Step travelStep(Step step)
	{
		if (step == null || !enabled || !ClueTypes.HOT_COLD.equals(step.getType()) || step.getKind() != TargetKind.PROBES)
		{
			return step;
		}
		Target chosen = target;
		if (chosen == null || !chosen.getStepKey().equals(step.getKey()))
		{
			return step.toBuilder().kind(TargetKind.ANY_OF).build();
		}
		if (chosen.getTile() == null)
		{
			return step.toBuilder().kind(TargetKind.ANY_OF).targets(List.of()).build();
		}
		HotColdTier tier = HotColdTier.of(step.getTier());
		return step.toBuilder()
			.kind(TargetKind.ANY_OF)
			.targets(List.of(chosen.getTile()))
			.requirements(step.getRequirements().plus(tier.getDevice()))
			.waypointAct(chosen.getAct())
			.actItems(chosen.isDig() ? Set.of() : Set.of(tier.getDeviceItemId()))
			.actAnywhere(chosen.isHere())
			.build();
	}
}

package com.cluehelper.hotcold;

import java.util.List;
import lombok.AllArgsConstructor;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.ToString;
import net.runelite.api.coords.WorldPoint;

/** Stored as JSON in the feel log, so its fields are its format. */
@Getter
@EqualsAndHashCode
@ToString
@AllArgsConstructor
@NoArgsConstructor
public final class Reading
{
	private int x;
	private int y;
	private int plane;
	/** Null on an anchor: a finished step's last reading, kept only for the next step's first comparison. */
	private Band band;
	/** Null on a step's first reading and on the shaking line. */
	private Comparison comparison;

	public Reading asAnchor()
	{
		return new Reading(x, y, plane, null, null);
	}

	public boolean isAnchor()
	{
		return band == null;
	}

	/**
	 * Core compares Prifddinas through its overworld mirror; whether the device does is unmeasured, so a reading there
	 * fits a spot from either tile.
	 */
	public List<WorldPoint> tiles()
	{
		WorldPoint tile = new WorldPoint(x, y, plane);
		WorldPoint mirror = WorldPoint.getMirrorPoint(tile, true);
		return mirror.equals(tile) ? List.of(tile) : List.of(tile, mirror);
	}
}

