package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import com.cluehelper.step.StepIndex;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.Enemy;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdLocation;

/** Core's spots, read from its enum, never from its solver. */
public final class Spots
{
	private static final int MIN_RADIUS = 1;

	private Spots()
	{
	}

	public static List<Spot> of(StepIndex index, HotColdTier tier)
	{
		Map<String, StepIndex.Spot> cache = index.getHotColdSpots();
		List<Spot> spots = new ArrayList<>();
		for (HotColdLocation location : HotColdLocation.values())
		{
			if (tierOf(location) == tier)
			{
				spots.add(spot(location, tier, cache.get(location.name())));
			}
		}
		return List.copyOf(spots);
	}

	private static HotColdTier tierOf(HotColdLocation location)
	{
		return location.isBeginnerClue() ? HotColdTier.BEGINNER : HotColdTier.MASTER;
	}

	private static Spot spot(HotColdLocation location, HotColdTier tier, StepIndex.Spot cached)
	{
		WorldPoint core = location.getWorldPoint();
		int[] tile = cached == null ? null : cached.getTile();
		int x = tile == null ? core.getX() : tile[0];
		int y = tile == null ? core.getY() : tile[1];
		int radius = Math.max(MIN_RADIUS, Math.max(Math.abs(core.getX() - x), Math.abs(core.getY() - y)));
		String description = location.getArea();
		if (description.endsWith("."))
		{
			description = description.substring(0, description.length() - 1);
		}
		return new Spot(location.name(), tier, x, y, radius, description,
			location.getHotColdArea().getName(), location.getEnemy() == Enemy.BRASSICAN_OR_WIZARDS);
	}
}

package com.cluehelper.link;

import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.step.Stages;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepResolver;
import com.cluehelper.transport.AvailabilityService;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.ClueScrollService;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;

/**
 * Core is read once per tick, at GameTick priority -1, after core's own handlers have updated it. Its active state
 * comes from {@code isPluginActive} and {@link PluginChanged}, never from {@code isPluginEnabled} or the config key,
 * which both flip before core actually stops or starts.
 */
@Slf4j
@Singleton
public class ClueLink
{
	private static final int NO_CLUE_PARAM = -1;

	private final PluginManager pluginManager;
	private final ClueScrollService service;
	private final Client client;
	private final StepResolver resolver;
	private final AvailabilityService availability;
	private final LinkState state = new LinkState();
	private final List<StepListener> listeners = new CopyOnWriteArrayList<>();
	private final Set<String> loggedFailures = ConcurrentHashMap.newKeySet();

	private volatile ClueScrollPlugin core;
	private volatile Step current;
	private volatile boolean inventoryChanged;
	private boolean inventoryHoldsClue;

	@Inject
	ClueLink(PluginManager pluginManager, ClueScrollService service, Client client, StepResolver resolver,
		AvailabilityService availability)
	{
		this.availability = availability;
		this.pluginManager = pluginManager;
		this.service = service;
		this.client = client;
		this.resolver = resolver;
	}

	/** Swing thread. Core's instance exists even while it is off. */
	public void start()
	{
		core = findCore();
		current = null;
		inventoryChanged = true;
		state.start(isCoreActive());
	}

	public void stop()
	{
		core = null;
		current = null;
		state.start(false);
	}

	public boolean isActive()
	{
		return state.isActive();
	}

	public boolean needsRead()
	{
		return state.needsRead();
	}

	public boolean hasStep()
	{
		return state.hasStep();
	}

	/** Null when core has no clue. */
	public Step getCurrentStep()
	{
		return current;
	}

	/** Null if the client has no Clue Scroll plugin. */
	public ClueScrollPlugin getCore()
	{
		return core;
	}

	public ClueScroll coreClue()
	{
		return service.getClue();
	}

	public Runnable addListener(StepListener listener)
	{
		listeners.add(listener);
		return () -> listeners.remove(listener);
	}

	/**
	 * Swing thread, so it only sets the flag.
	 *
	 * @return whether the active flag changed
	 */
	public boolean onPluginChanged(PluginChanged event)
	{
		Plugin c = core;
		return c != null && event.getPlugin() == c && state.onPluginChanged(event.isLoaded());
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			inventoryChanged = true;
		}
	}

	/**
	 * Call from a GameTick handler at priority -1.
	 *
	 * @return whether anything the box shows changed: active, needs-read or has-step
	 */
	public boolean onGameTick()
	{
		boolean wasActive = state.isActive();
		boolean neededRead = state.needsRead();
		boolean hadStep = state.hasStep();

		boolean active = isCoreActive();
		ClueScroll clue = active ? service.getClue() : null;
		Step step = clue == null ? null : Stages.adjusted(resolve(clue), this::owns, playerTile());
		StepChange change = state.tick(active, step == null ? null : step.getKey(),
			step == null ? null : List.of(step.getTargets(), step.getStages()), clue == null && carriesClue());
		if (change != StepChange.UNCHANGED)
		{
			current = step;
			for (StepListener listener : listeners)
			{
				listener.onStepChange(change, step);
			}
		}
		return wasActive != state.isActive() || neededRead != state.needsRead() || hadStep != state.hasStep();
	}

	private Step resolve(ClueScroll clue)
	{
		try
		{
			return resolver.resolve(clue, core);
		}
		catch (RuntimeException e)
		{
			if (loggedFailures.add(clue.getClass().getName()))
			{
				log.warn("Could not read the Clue Scroll plugin's {}", clue.getClass().getSimpleName(), e);
			}
			return StepResolver.unreadable(clue);
		}
	}

	private WorldPoint playerTile()
	{
		Player local = client.getLocalPlayer();
		return local == null ? null : local.getWorldLocation();
	}

	private boolean owns(int itemId)
	{
		PlayerSnapshot banked = availability.getBankedSnapshot();
		return holds(InventoryID.INV, itemId) || holds(InventoryID.WORN, itemId)
			|| banked != null && (banked.getBank().containsKey(itemId) || banked.getGroupStorage().containsKey(itemId));
	}

	private boolean holds(int containerId, int itemId)
	{
		ItemContainer items = client.getItemContainer(containerId);
		return items != null && items.contains(itemId);
	}

	/** Client thread only. Whether the inventory holds a clue item, read or not. */
	public boolean carriesClue()
	{
		if (inventoryChanged)
		{
			inventoryChanged = false;
			inventoryHoldsClue = inventoryHoldsClue();
		}
		return inventoryHoldsClue;
	}

	/** A clue item has item param 623, except the shared beginner and master clues, which have none. */
	private boolean inventoryHoldsClue()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return false;
		}
		for (Item item : inventory.getItems())
		{
			int id = item.getId();
			if (id == ItemID.TRAIL_CLUE_BEGINNER || id == ItemID.TRAIL_CLUE_MASTER
				|| id > 0 && client.getItemDefinition(id).getIntValue(ParamID.CLUE_SCROLL) != NO_CLUE_PARAM)
			{
				return true;
			}
		}
		return false;
	}

	private ClueScrollPlugin findCore()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof ClueScrollPlugin)
			{
				return (ClueScrollPlugin) plugin;
			}
		}
		return null;
	}

	private boolean isCoreActive()
	{
		Plugin c = core;
		return c != null && pluginManager.isPluginActive(c);
	}
}

package com.cluehelper.link;

import java.util.Objects;

/**
 * ClueLink's rules without the client, so recorded logs replay through them. A new step is told by its key, never by
 * object identity: core hands out the same static entry again for re-reads and later trails.
 */
final class LinkState
{
	private volatile boolean active;
	private volatile boolean needsRead;
	private volatile boolean hasStep;
	private String lastKey;
	private Object lastTargets;

	void start(boolean coreActive)
	{
		hasStep = false;
		needsRead = false;
		lastKey = null;
		lastTargets = null;
		setActive(coreActive);
	}

	/** Swing thread. @return whether the active flag changed */
	boolean onPluginChanged(boolean loaded)
	{
		return setActive(loaded);
	}

	StepChange tick(boolean coreActive, String key, Object targets, boolean inventoryHoldsClue)
	{
		setActive(coreActive);
		String seen = coreActive ? key : null;
		needsRead = coreActive && seen == null && inventoryHoldsClue;
		StepChange change = observe(seen, targets);
		lastKey = seen;
		lastTargets = seen == null ? null : targets;
		hasStep = seen != null;
		return change;
	}

	boolean isActive()
	{
		return active;
	}

	boolean needsRead()
	{
		return needsRead;
	}

	boolean hasStep()
	{
		return hasStep;
	}

	private StepChange observe(String key, Object targets)
	{
		if (key == null)
		{
			return hasStep ? StepChange.CLEARED : StepChange.UNCHANGED;
		}
		if (!hasStep || !key.equals(lastKey))
		{
			return StepChange.NEW;
		}
		return Objects.equals(targets, lastTargets) ? StepChange.UNCHANGED : StepChange.UPDATED;
	}

	private boolean setActive(boolean nowActive)
	{
		boolean changed = active != nowActive;
		active = nowActive;
		return changed;
	}
}

package com.cluehelper.link;

public enum StepChange
{
	NEW,
	/** Same key, no gap, different targets: three-step progress or hot/cold narrowing. */
	UPDATED,
	CLEARED,
	UNCHANGED
}

package com.cluehelper.link;

import com.cluehelper.step.Step;

/** Called on the client thread. */
public interface StepListener
{
	/** @param step the current step, or null after {@link StepChange#CLEARED} */
	void onStepChange(StepChange change, Step step);
}

package com.cluehelper.memory;

import com.cluehelper.player.AccountType;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * The bank, group storage and huntsman's kit as last seen. Client thread, except the getters. Saved to the profile only
 * when the bank closes, the kit is seen outside the bank, and at logout: each save costs about 1 ms on the client thread
 * and a bank visit fires one event per withdraw.
 */
@Slf4j
@Singleton
public class BankMemory
{
	private static final String BANK_KEY = "bank";
	private static final String GROUP_STORAGE_KEY = "groupStorage";
	private static final String PIN_KEY = "bankPin";
	private static final String KIT_KEY = "huntsmansKit";
	private static final int NO_PLACEHOLDER = -1;
	private static final int NO_NOTE = -1;
	private static final String DEPOSIT = "Deposit";

	private final Client client;
	private final MemorySlot<Seen> storedBank;
	private final MemorySlot<Seen> storedGroup;
	private final MemorySlot<Pin> pin;
	private final MemorySlot<Seen> storedKit;
	private final Map<Integer, Boolean> placeholders = new HashMap<>();
	private final LateDeposits lateDeposits = new LateDeposits();

	private volatile Seen liveBank;
	private volatile Seen liveGroup;
	private volatile Seen liveKit;
	private boolean unsaved;
	/** The PIN is asked once per login: a bank or PIN screen seen since then means it's done. */
	private volatile boolean pinDoneThisSession;
	private volatile long version;
	/** Tracked from the bank's own load and close events: the bank widget can outlive a closed bank. */
	private volatile boolean bankOpen;

	@Inject
	BankMemory(Client client, MemoryStore memory)
	{
		this.client = client;
		this.storedBank = memory.slot(BANK_KEY, Seen.class, Seen::new);
		this.storedGroup = memory.slot(GROUP_STORAGE_KEY, Seen.class, Seen::new);
		this.pin = memory.slot(PIN_KEY, Pin.class, Pin::new);
		this.storedKit = memory.slot(KIT_KEY, Seen.class, Seen::new);
	}

	/** Null when this profile has never opened it. Any thread. */
	public Seen getBank()
	{
		Seen live = liveBank;
		return live != null ? live : seenOrNull(storedBank.get());
	}

	/** Null when never seen or not a group account. Any thread. */
	public Seen getGroupStorage()
	{
		Seen live = liveGroup;
		return live != null ? live : seenOrNull(storedGroup.get());
	}

	/** The huntsman's kit's traps and tools, as last sent when it was opened; null when never. Any thread. */
	public Seen getKit()
	{
		Seen live = liveKit;
		return live != null ? live : seenOrNull(storedKit.get());
	}

	/**
	 * These items plus the huntsman's kit's contents when the kit is among them: a carried kit's traps count as carried, a
	 * banked kit's as banked.
	 */
	public Map<Integer, Integer> withKit(Map<Integer, Integer> items)
	{
		Seen kit = items.containsKey(ItemID.HUNTSMANS_KIT) ? getKit() : null;
		if (kit == null)
		{
			return items;
		}
		Map<Integer, Integer> all = new HashMap<>(items);
		kit.items.forEach((id, quantity) -> all.merge(id, quantity, Integer::sum));
		return all;
	}

	/** Whether the item is only in the huntsman's kit, not loose in the bank: the kit is withdrawn for it. */
	public boolean onlyInBankedKit(int itemId)
	{
		Seen bank = getBank();
		Seen kit = getKit();
		return bank != null && kit != null && bank.items.containsKey(ItemID.HUNTSMANS_KIT) && !bank.items.containsKey(itemId)
			&& kit.items.containsKey(itemId);
	}

	public boolean isPinPending()
	{
		return pin.get().seen && !pinDoneThisSession;
	}

	/** Changes whenever the remembered contents or the PIN state change, so a plan can tell it is stale. */
	public long getVersion()
	{
		return version;
	}

	public boolean isBankOpen()
	{
		return bankOpen;
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			lateDeposits.onCarried(carried(), client.getTickCount());
		}
		else if (event.getContainerId() == InventoryID.BANK)
		{
			lateDeposits.onBankSeen(client.getTickCount());
			liveBank = seen(event.getItemContainer());
			pinDoneThisSession = true;
			unsaved = true;
			version++;
		}
		else if (event.getContainerId() == InventoryID.INV_GROUP_TEMP && AccountType.of(client.getVarbitValue(VarbitID.IRONMAN)).isGroup()
			&& client.getVarbitValue(VarbitID.GIM_SHARED_BANK_HASEDITED) != 1)
		{
			liveGroup = seen(event.getItemContainer());
			unsaved = true;
			version++;
		}
		else if (event.getContainerId() == InventoryID.HUNTSMANS_KIT)
		{
			liveKit = seen(event.getItemContainer());
			unsaved = true;
			version++;
			if (!bankOpen)
			{
				save();
			}
		}
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKPIN_KEYPAD && !pin.get().seen)
		{
			Pin seen = new Pin();
			seen.seen = true;
			pin.set(seen);
			version++;
		}
		else if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
			lateDeposits.onCarried(carried(), client.getTickCount());
		}
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (bankOpen && option != null && option.regionMatches(true, 0, DEPOSIT, 0, DEPOSIT.length()))
		{
			lateDeposits.onDepositClicked(client.getTickCount());
		}
	}

	/** Call before the planner's tick, so the plan never sees an unconfirmed deposit as missing. */
	public void onGameTick()
	{
		Map<Integer, Integer> deposited = lateDeposits.onTick();
		Seen bank = getBank();
		if (deposited.isEmpty() || bank == null)
		{
			return;
		}
		Seen updated = new Seen();
		updated.seenAt = bank.seenAt;
		updated.items = new HashMap<>(bank.items);
		deposited.forEach((id, quantity) -> updated.items.merge(id, quantity, Integer::sum));
		liveBank = updated;
		unsaved = true;
		version++;
		if (!bankOpen)
		{
			save();
		}
		log.debug("deposits without a bank update: {}", deposited);
	}

	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = false;
			save();
		}
		else if (event.getGroupId() == InterfaceID.BANKPIN_KEYPAD)
		{
			pinDoneThisSession = true;
			version++;
		}
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			save();
			bankOpen = false;
			pinDoneThisSession = false;
			version++;
		}
	}

	/** On {@code RuneScapeProfileChanged}, after the store reloads: the live copies belonged to the old profile. */
	public void onProfileChanged()
	{
		liveBank = null;
		liveGroup = null;
		liveKit = null;
		unsaved = false;
		version++;
	}

	private void save()
	{
		if (!unsaved)
		{
			return;
		}
		unsaved = false;
		long started = System.nanoTime();
		if (liveBank != null)
		{
			storedBank.set(liveBank);
		}
		if (liveGroup != null)
		{
			storedGroup.set(liveGroup);
		}
		if (liveKit != null)
		{
			storedKit.set(liveKit);
		}
		log.debug("bank memory saved in {} ms", (System.nanoTime() - started) / 1e6);
	}

	/** Placeholders arrive as quantity 1 under a placeholder id, so they are told apart by definition. */
	private Seen seen(ItemContainer container)
	{
		Seen seen = new Seen();
		seen.seenAt = System.currentTimeMillis();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && item.getQuantity() > 0 && !isPlaceholder(item.getId()))
				{
					seen.items.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return seen;
	}

	/** Notes count as the items they stand for, as a deposit puts them in the bank. */
	private Map<Integer, Integer> carried()
	{
		Map<Integer, Integer> carried = new HashMap<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container == null)
			{
				continue;
			}
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && item.getQuantity() > 0)
				{
					carried.merge(unnoted(item.getId()), item.getQuantity(), Integer::sum);
				}
			}
		}
		return carried;
	}

	private int unnoted(int id)
	{
		ItemComposition item = client.getItemDefinition(id);
		return item.getNote() != NO_NOTE ? item.getLinkedNoteId() : id;
	}

	private boolean isPlaceholder(int id)
	{
		return placeholders.computeIfAbsent(id, i -> client.getItemDefinition(i).getPlaceholderTemplateId() != NO_PLACEHOLDER);
	}

	private static Seen seenOrNull(Seen stored)
	{
		return stored == null || stored.seenAt == 0 ? null : stored;
	}

	public static final class Seen
	{
		/** Epoch millis; 0 when never seen. */
		public long seenAt;
		public Map<Integer, Integer> items = new HashMap<>();
	}

	static final class Pin
	{
		boolean seen;
	}
}

package com.cluehelper.memory;

import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PositionRules;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

/**
 * Client thread. Turning the dials without travelling doesn't change a ring's Last-destination, so the code is the
 * dials as they stood at the confirm, kept once the player lands. A "Last-destination (XYZ)" menu entry corrects it.
 */
@Singleton
public class FairyRingMemory
{
	static final String KEY = "fairyRing";
	/** Each dial's letters by its varbit value, which follows the turning order. */
	private static final String[] LEFT_DIAL = {"A", "D", "C", "B"};
	private static final String[] MIDDLE_DIAL = {"I", "L", "K", "J"};
	private static final String[] RIGHT_DIAL = {"P", "S", "R", "Q"};
	private static final Pattern LAST_DESTINATION = Pattern.compile("last-destination \\(([A-Z]{3})\\)", Pattern.CASE_INSENSITIVE);
	/** A ring teleport lands about 7 ticks after the confirm, arrival lock included. */
	private static final int LANDING_WITHIN_TICKS = 12;

	private final Client client;
	private final PlayerModel player;
	private final MemorySlot<Last> remembered;
	private final List<Consumer<String>> listeners = new CopyOnWriteArrayList<>();
	private String pending;
	private int pendingTick;
	private WorldPoint pendingFrom;
	private String published;

	@Inject
	FairyRingMemory(Client client, MemoryStore memory, PlayerModel player)
	{
		this.client = client;
		this.player = player;
		this.remembered = memory.slot(KEY, Last.class, Last::new);
	}

	public Runnable addListener(Consumer<String> devTraceLines)
	{
		listeners.add(devTraceLines);
		return () -> listeners.remove(devTraceLines);
	}

	/** Call on start and after a profile change. */
	public void publish()
	{
		String code = remembered.get().code;
		if (code != null && !code.equals(published))
		{
			published = code;
			player.setLastFairyRing(code);
			tell("last destination " + code);
		}
	}

	/** At the confirm the dials show where the ring sends the player, also after picking a travel-log line. */
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		Matcher last = LAST_DESTINATION.matcher(Text.removeTags(event.getMenuOption()));
		if (last.find())
		{
			arm(last.group(1).toUpperCase());
		}
		else if (event.getParam1() == InterfaceID.Fairyrings.CONFIRM)
		{
			arm(dials());
		}
	}

	/** A "Last-destination (XYZ)" entry is the game's own word, so it wins over what travel taught. */
	public void onMenuEntries(MenuEntry[] entries)
	{
		for (MenuEntry entry : entries)
		{
			Matcher last = LAST_DESTINATION.matcher(Text.removeTags(entry.getOption() == null ? "" : entry.getOption()));
			if (last.find())
			{
				remember(last.group(1).toUpperCase(), "menu");
				return;
			}
		}
	}

	/** A confirmed teleport counts once the player has jumped; one the game refused never does. */
	public void onGameTick()
	{
		if (pending == null)
		{
			return;
		}
		WorldPoint at = position();
		boolean jumped = PositionRules.teleported(pendingFrom, at);
		if (jumped)
		{
			remember(pending, "travel");
		}
		if (jumped || client.getTickCount() - pendingTick > LANDING_WITHIN_TICKS)
		{
			pending = null;
		}
	}

	String dials()
	{
		return LEFT_DIAL[client.getVarbitValue(VarbitID.FAIRYRING_1) & 3] + MIDDLE_DIAL[client.getVarbitValue(VarbitID.FAIRYRING_2) & 3]
			+ RIGHT_DIAL[client.getVarbitValue(VarbitID.FAIRYRING_3) & 3];
	}

	private void arm(String code)
	{
		pending = code;
		pendingTick = client.getTickCount();
		pendingFrom = position();
		tell("travelling to " + code + " (dials " + dials() + ")");
	}

	private void remember(String code, String source)
	{
		if (!code.equals(remembered.get().code))
		{
			Last next = new Last();
			next.code = code;
			next.seenAt = System.currentTimeMillis();
			remembered.set(next);
			tell(code + " (" + source + ")");
		}
		publish();
	}

	private WorldPoint position()
	{
		Player local = client.getLocalPlayer();
		return local == null ? null : WorldPoint.fromLocalInstance(client, local.getLocalLocation());
	}

	private void tell(String line)
	{
		listeners.forEach(listener -> listener.accept(line));
	}

	static final class Last
	{
		String code;
		long seenAt;
	}
}

package com.cluehelper.memory;

import com.cluehelper.player.PlayerModel;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;

/**
 * Client thread. Patches the Time Tracking plugin remembers for this account, as core stores them: "region.varbit" to
 * "value:seconds" in its group. A grown Farming Guild redwood is a place for Sherlock's redwood task.
 */
@Singleton
public class GrownPatches
{
	private static final String FARMING_GUILD_REDWOOD = "Farming Guild redwood";
	private static final String TIME_TRACKING = "timetracking";
	private static final String REDWOOD_KEY = "4922." + VarbitID.FARMING_TRANSMIT_I;
	private static final int HARVESTABLE = 18;
	private static final int CHECK_HEALTH = 37;
	private static final int REGROWN_FIRST = 41;
	private static final int REGROWN_LAST = 55;

	private final ConfigManager configManager;
	private final PlayerModel player;

	@Inject
	GrownPatches(ConfigManager configManager, PlayerModel player)
	{
		this.configManager = configManager;
		this.player = player;
	}

	/** Call on start, after a profile change and when Time Tracking writes one of its patches. */
	public void publish()
	{
		player.setGrownPatches(isGrownRedwood(storedValue(REDWOOD_KEY)) ? Set.of(FARMING_GUILD_REDWOOD) : Set.of());
	}

	public boolean isOurs(ConfigChanged event)
	{
		return TIME_TRACKING.equals(event.getGroup()) && REDWOOD_KEY.equals(event.getKey());
	}

	/** Core's redwood patch values: chopping, or grown with its health check due first. */
	private static boolean isGrownRedwood(int value)
	{
		return value == HARVESTABLE || value == CHECK_HEALTH || value >= REGROWN_FIRST && value <= REGROWN_LAST;
	}

	/** -1 when Time Tracking has never seen the patch. */
	private int storedValue(String key)
	{
		String stored = configManager.getRSProfileConfiguration(TIME_TRACKING, key);
		String value = stored == null ? "" : stored.split(":", 2)[0];
		return value.matches("\\d+") ? Integer.parseInt(value) : -1;
	}
}

package com.cluehelper.memory;

import java.util.HashMap;
import java.util.Map;

/**
 * Items that left the inventory or equipment right after a Deposit click, held until the bank's own update confirms
 * them. Walking off on the next tick closes the bank before that update arrives, so ticks without one mean the items
 * went in anyway.
 */
final class LateDeposits
{
	/** The server carries out a click on the next tick, and the walk-off can close the bank on that same tick. */
	static final int DEPOSIT_TICKS = 2;
	/**
	 * The bank's update comes in the same server cycle as the inventory's, before the next game tick; BankMemory runs
	 * before the planner on that tick, so the plan never sees the item missing.
	 */
	private static final int CONFIRM_TICKS = 1;
	private static final int NEVER = Integer.MIN_VALUE;

	private Map<Integer, Integer> carried = Map.of();
	private final Map<Integer, Integer> pending = new HashMap<>();
	private int clickTick = NEVER;
	private int bankSeenTick = NEVER;
	private int ticksWaited;

	void onDepositClicked(int tick)
	{
		clickTick = tick;
	}

	/** @param now the inventory and equipment together, unnoted, after any change to either */
	void onCarried(Map<Integer, Integer> now, int tick)
	{
		boolean bankAlreadySeen = tick == bankSeenTick;
		if (clickTick != NEVER && tick - clickTick <= DEPOSIT_TICKS && !bankAlreadySeen)
		{
			carried.forEach((id, before) -> {
				int gone = before - now.getOrDefault(id, 0);
				if (gone > 0)
				{
					pending.merge(id, gone, Integer::sum);
				}
			});
		}
		carried = Map.copyOf(now);
	}

	/** The bank's own update holds whatever was deposited this tick, whichever of the two updates came first. */
	void onBankSeen(int tick)
	{
		bankSeenTick = tick;
		pending.clear();
		ticksWaited = 0;
	}

	/** Each game tick: the deposits no bank update confirmed in time, returned once; empty otherwise. */
	Map<Integer, Integer> onTick()
	{
		if (pending.isEmpty() || ++ticksWaited < CONFIRM_TICKS)
		{
			return Map.of();
		}
		Map<Integer, Integer> unconfirmed = Map.copyOf(pending);
		pending.clear();
		ticksWaited = 0;
		return unconfirmed;
	}
}

package com.cluehelper.memory;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.Objects;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/** Safe to use from any thread. */
@Slf4j
public final class MemorySlot<T>
{
	private final String key;
	private final Class<T> type;
	private final Supplier<T> fresh;
	private final ProfileConfig profile;
	private final Gson gson;

	private boolean loaded;
	private String loadedProfile;
	private T value;

	MemorySlot(String key, Class<T> type, Supplier<T> fresh, ProfileConfig profile, Gson gson)
	{
		this.key = key;
		this.type = type;
		this.fresh = fresh;
		this.profile = profile;
		this.gson = gson;
	}

	public synchronized T get()
	{
		String currentProfile = profile.profileKey();
		if (!loaded || !Objects.equals(currentProfile, loadedProfile))
		{
			value = read(currentProfile);
			loadedProfile = currentProfile;
			loaded = true;
		}
		return value;
	}

	/** Without a profile the value is kept in memory only, and dropped when a profile loads. */
	public synchronized void set(T newValue)
	{
		String currentProfile = profile.profileKey();
		value = newValue;
		loadedProfile = currentProfile;
		loaded = true;
		if (currentProfile == null)
		{
			log.debug("{} kept in memory only: no RuneScape profile yet", key);
			return;
		}
		profile.set(key, gson.toJson(newValue));
	}

	public synchronized void clear()
	{
		forget();
		if (profile.profileKey() != null)
		{
			profile.unset(key);
		}
	}

	synchronized void forget()
	{
		loaded = false;
		loadedProfile = null;
		value = null;
	}

	private T read(String currentProfile)
	{
		if (currentProfile == null)
		{
			return fresh.get();
		}
		String json = profile.get(key);
		if (json == null)
		{
			return fresh.get();
		}
		try
		{
			T parsed = gson.fromJson(json, type);
			return parsed == null ? fresh.get() : parsed;
		}
		catch (JsonParseException e)
		{
			log.warn("unreadable {} in this profile, starting fresh", key, e);
			return fresh.get();
		}
	}
}

package com.cluehelper.memory;

import com.google.gson.Gson;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Nothing is read or written until the client has a RuneScape profile, which needs a login; before that every slot
 * holds its fresh value in memory only.
 */
@Singleton
public class MemoryStore
{
	private final ProfileConfig profile;
	private final Gson gson;
	private final List<MemorySlot<?>> slots = new CopyOnWriteArrayList<>();

	@Inject
	MemoryStore(ConfigManager configManager, Gson gson)
	{
		this(new RuneLiteProfileConfig(configManager), gson);
	}

	MemoryStore(ProfileConfig profile, Gson gson)
	{
		this.profile = profile;
		this.gson = gson;
	}

	/**
	 * Create each slot once and keep it: the store holds on to every slot it makes.
	 *
	 * @param fresh the value of a profile that has none stored, or whose stored JSON is unreadable
	 */
	public <T> MemorySlot<T> slot(String key, Class<T> type, Supplier<T> fresh)
	{
		MemorySlot<T> slot = new MemorySlot<>(key, type, fresh, profile, gson);
		slots.add(slot);
		return slot;
	}

	public boolean hasProfile()
	{
		return profile.profileKey() != null;
	}

	/** Call on {@code RuneScapeProfileChanged}. */
	public void reload()
	{
		for (MemorySlot<?> slot : slots)
		{
			slot.forget();
		}
	}
}

