import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.HashTable;
import net.runelite.api.Player;
import net.runelite.api.WidgetNode;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.util.Text;

/**
 * Client thread. Learned as Shortest Path does: the spirit tree menu greys a planted tree that can't be used, and
 * inside a patch's region its {@code FARMING_TRANSMIT_*} varbit reads {@link #GROWN} for a grown tree.
 */
@Singleton
public class SpiritTreeMemory
{
	static final String KEY = "spiritTrees";
	private static final String MENU_TITLE = "Spirit Tree Locations";
	/** As core's farming tracker reads the varbit: 8-19 is growing, 21 and up diseased or dead. */
	private static final int GROWN = 20;
	private static final String GREYED = "5f5f5f";

	/** Patch name → {region, transmit varbit}; the varbit describes the patch only inside its region. */
	private static final Map<String, int[]> PATCHES = Map.of(
		"Port Sarim", new int[]{12082, VarbitID.FARMING_TRANSMIT_A},
		"Etceteria", new int[]{10300, VarbitID.FARMING_TRANSMIT_B},
		"Brimhaven", new int[]{11058, VarbitID.FARMING_TRANSMIT_B},
		"Hosidius", new int[]{6711, VarbitID.FARMING_TRANSMIT_F},
		"Farming Guild", new int[]{4922, VarbitID.FARMING_TRANSMIT_A});

	private final Client client;
	private final PlayerModel player;
	private final MemorySlot<Patches> remembered;
	private final List<Consumer<String>> listeners = new CopyOnWriteArrayList<>();
	private Set<String> published;
	private int lastRegion = -1;
	private int lastRegionTick = -1;

	@Inject
	SpiritTreeMemory(Client client, MemoryStore memory, PlayerModel player)
	{
		this.client = client;
		this.player = player;
		this.remembered = memory.slot(KEY, Patches.class, Patches::new);
	}

	public Set<String> grown()
	{
		return remembered.get().patches.entrySet().stream().filter(e -> e.getValue().value == GROWN)
			.map(Map.Entry::getKey).collect(Collectors.toUnmodifiableSet());
	}

	public Runnable addListener(Consumer<String> devTraceLines)
	{
		listeners.add(devTraceLines);
		return () -> listeners.remove(devTraceLines);
	}

	/** Call on start and after a profile change. */
	public void publish()
	{
		Set<String> now = grown();
		if (!now.equals(published))
		{
			published = now;
			player.setPlantedTrees(now);
			tell("grown " + now);
		}
	}

	/** Patches the menu doesn't list keep what was known: the menu only speaks for its own lines. */
	public void onListMenu(String title, List<String> rawLines)
	{
		if (!MENU_TITLE.equalsIgnoreCase(Text.removeTags(title == null ? "" : title).trim()))
		{
			return;
		}
		tell("menu " + rawLines);
		for (String raw : rawLines)
		{
			String name = placeOf(raw);
			if (PATCHES.containsKey(name))
			{
				observe(name, raw.toLowerCase().contains(GREYED) ? 0 : GROWN, "menu");
			}
		}
		publish();
	}

	/**
	 * The transmit varbit counts only once the region has held for two ticks (it is refilled after a region change) and
	 * while no modal interface is open (varbits aren't sent then).
	 */
	public void onGameTick()
	{
		Player local = client.getLocalPlayer();
		WorldPoint at = local == null ? null : WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		int region = at == null ? -1 : at.getRegionID();
		int tick = client.getTickCount();
		int settledRegion = region != -1 && region == lastRegion && tick == lastRegionTick + 1 ? region : -1;
		lastRegion = region;
		lastRegionTick = tick;
		if (settledRegion == -1 || modalOpen())
		{
			return;
		}
		for (Map.Entry<String, int[]> patch : PATCHES.entrySet())
		{
			if (patch.getValue()[0] == settledRegion)
			{
				observe(patch.getKey(), client.getVarbitValue(patch.getValue()[1]), "region");
				publish();
			}
		}
	}

	/** "<col=735a28>7</col>: Port Sarim" → "Port Sarim". */
	private static String placeOf(String raw)
	{
		String text = Text.removeTags(raw).trim();
		int colon = text.lastIndexOf(": ");
		return colon < 0 ? text : text.substring(colon + 2).trim();
	}

	private void observe(String patch, int value, String source)
	{
		Seen old = remembered.get().patches.get(patch);
		if (old != null && old.value == value)
		{
			return;
		}
		Patches next = new Patches();
		next.patches.putAll(remembered.get().patches);
		Seen seen = new Seen();
		seen.value = value;
		seen.seenAt = System.currentTimeMillis();
		next.patches.put(patch, seen);
		remembered.set(next);
		tell(patch + " = " + value + " (" + source + ")");
	}

	private boolean modalOpen()
	{
		HashTable<WidgetNode> table = client.getComponentTable();
		if (table == null)
		{
			return false;
		}
		for (WidgetNode node : table)
		{
			if (node.getModalMode() != WidgetModalMode.NON_MODAL)
			{
				return true;
			}
		}
		return false;
	}

	private void tell(String line)
	{
		listeners.forEach(listener -> listener.accept(line));
	}

	static final class Patches
	{
		Map<String, Seen> patches = new HashMap<>();
	}

	static final class Seen
	{
		/** The patch varbit's value; from the menu, {@link SpiritTreeMemory#GROWN} or 0. */
		int value;
		long seenAt;
	}
}

package com.cluehelper.memory;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ObjectComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.plugins.cluescrolls.clues.emote.STASHUnit;
import net.runelite.client.util.Text;

/**
 * Client thread. Filled state has no var: the Clue Scroll plugin's tick (script 1479) is built state too and stays 1
 * for an emptied unit. So a built unit counts as filled, as that tick suggests, until one of the two Search chat lines
 * says otherwise.
 */
@Singleton
public class StashMemory
{
	public enum State
	{
		/** The step has no STASH unit; never a unit's own state. */
		NONE,
		NOT_BUILT, FILLED, EMPTY
	}

	static final String KEY = "stash";
	private static final String WITHDRAWN = "You withdraw your items from the STASH unit.";
	private static final String DEPOSITED = "You deposit your items into the STASH unit.";
	/** A Search line lands 0–3 ticks after the click, or 8 when the first Search of a session asks for the PIN. */
	private static final int SEARCH_LINE_TICKS = 8;
	private static final String SEARCH = "Search";
	private static final int CORE_STASH_SCRIPT = 1479;
	private static final int BUILT = 1;
	private static final int NOT_SEEN = -1;
	private static final Set<Integer> UNIT_OBJECTS = Arrays.stream(STASHUnit.values()).map(STASHUnit::getObjectId)
		.collect(Collectors.toUnmodifiableSet());

	private final Client client;
	private final MemorySlot<Units> remembered;
	private final Map<Integer, Integer> builtVarbits = new HashMap<>();
	private int lastSearchObject = NOT_SEEN;
	private int lastSearchTick;

	@Inject
	StashMemory(Client client, MemoryStore memory)
	{
		this.client = client;
		this.remembered = memory.slot(KEY, Units.class, Units::new);
	}

	public State state(int objectId)
	{
		if (!isBuilt(objectId))
		{
			return State.NOT_BUILT;
		}
		Seen seen = remembered.get().units.get(objectId);
		return seen == null || seen.filled ? State.FILLED : State.EMPTY;
	}

	/**
	 * Client thread, outside any script: scripts don't nest, and a call from a chat command's handler trips the
	 * client's assertion.
	 */
	public int coreCheck(int objectId)
	{
		client.runScript(CORE_STASH_SCRIPT, objectId, 0, 0, 0);
		return client.getIntStack()[0];
	}

	public static Set<Integer> unitObjects()
	{
		return UNIT_OBJECTS;
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (SEARCH.equals(Text.removeTags(event.getMenuOption())) && UNIT_OBJECTS.contains(event.getId()))
		{
			lastSearchObject = event.getId();
			lastSearchTick = client.getTickCount();
		}
	}

	public void onChatMessage(ChatMessage message)
	{
		if (message.getType() != ChatMessageType.GAMEMESSAGE || lastSearchObject == NOT_SEEN
			|| client.getTickCount() - lastSearchTick > SEARCH_LINE_TICKS)
		{
			return;
		}
		String text = Text.removeTags(message.getMessage());
		if (WITHDRAWN.equals(text) || DEPOSITED.equals(text))
		{
			remember(lastSearchObject, DEPOSITED.equals(text));
			lastSearchObject = NOT_SEEN;
		}
	}

	private void remember(int objectId, boolean filled)
	{
		Units units = new Units();
		units.units.putAll(remembered.get().units);
		Seen seen = new Seen();
		seen.filled = filled;
		seen.seenAt = System.currentTimeMillis();
		units.units.put(objectId, seen);
		remembered.set(units);
	}

	/** The unit object is a multiloc on its own {@code HH_CONSTRUCTED_*} varbit, readable at login. */
	public boolean isBuilt(int objectId)
	{
		int varbit = builtVarbits.computeIfAbsent(objectId, id ->
		{
			ObjectComposition unit = client.getObjectDefinition(id);
			return unit == null ? -1 : unit.getVarbitId();
		});
		return varbit == -1 || client.getVarbitValue(varbit) == BUILT;
	}

	static final class Units
	{
		Map<Integer, Seen> units = new HashMap<>();
	}

	static final class Seen
	{
		boolean filled;
		long seenAt;
	}
}

package com.cluehelper.memory;

import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PositionRules;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.util.Text;

/**
 * Client thread. The game has no var for the Xeric's Honour unlock, and the talisman's menu shows the Honour line the
 * same whether it is unlocked or not. So it is learned from the chat line when an ancient tablet unlocks it, or, for
 * an account that unlocked it before, from a teleport that lands there: Mount Quidamortem can be walked to, but no
 * other teleport lands on that spot.
 */
@Singleton
public class XericsHonourMemory
{
	static final String KEY = "xericsHonour";
	/** The catalog's {@code UNLOCK_XERICS_HONOUR} token. */
	private static final String UNLOCK = "XERICS_HONOUR";
	/** The landing of the talisman's and the mounted talisman's Honour teleports in items.tsv and poh.tsv. */
	static final WorldPoint LANDING = new WorldPoint(1254, 3560, 0);
	private static final String TABLET_USED = "As the talisman and tablet are held together, a surge of power connects the two.";
	/** The real landing is 3 tiles north of the catalog's (1254 3563); a little more allows for a spread. */
	private static final int LANDING_TILES = 5;

	private final Client client;
	private final PlayerModel player;
	private final MemorySlot<Seen> remembered;
	private WorldPoint lastTile;

	@Inject
	XericsHonourMemory(Client client, MemoryStore memory, PlayerModel player)
	{
		this.client = client;
		this.player = player;
		this.remembered = memory.slot(KEY, Seen.class, Seen::new);
	}

	/** Call on start and after a profile change. */
	public void publish()
	{
		player.setUnlocks(isUnlocked() ? Set.of(UNLOCK) : Set.of());
	}

	/** Call before the player model's GameTick handler, so its snapshot has a fresh unlock. */
	public void onGameTick()
	{
		Player local = client.getLocalPlayer();
		WorldPoint tile = local == null ? null : WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		if (PositionRules.teleported(lastTile, tile) && tile.distanceTo(LANDING) <= LANDING_TILES)
		{
			learn();
		}
		lastTile = tile;
	}

	public void onChatMessage(ChatMessage message)
	{
		if (message.getType() == ChatMessageType.GAMEMESSAGE && Text.removeTags(message.getMessage()).startsWith(TABLET_USED))
		{
			learn();
		}
	}

	/** Logging in, possibly on another account, is no teleport. */
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			lastTile = null;
		}
	}

	private boolean isUnlocked()
	{
		return remembered.get().learnedAt > 0;
	}

	private void learn()
	{
		if (isUnlocked())
		{
			return;
		}
		Seen seen = new Seen();
		seen.learnedAt = System.currentTimeMillis();
		remembered.set(seen);
		publish();
	}

	static final class Seen
	{
		/** Epoch millis when the unlock was first seen; 0 when never. */
		long learnedAt;
	}
}

