}

package com.cluehelper.player;

import net.runelite.api.coords.WorldPoint;

public final class PositionRules
{
	/** Must match the POH node of Shortest Path's walk table. */
	public static final WorldPoint POH_NODE = new WorldPoint(1858, 7051, 0);

	private static final int POH_MIN_X = 1856;
	/** Template region 8302 (x 2048–2111) holds houses too, beyond Shortest Path's box. */
	private static final int POH_MAX_X = 2111;
	private static final int POH_MIN_Y = 7040;
	private static final int POH_MAX_Y = 7111;

	private static final int WILDERNESS_MIN_X = 2944;
	private static final int WILDERNESS_MAX_X_SURFACE = 3391;
	private static final int WILDERNESS_MAX_X_UNDERGROUND = 3461;
	private static final int SURFACE_MIN_Y = 3525;
	private static final int SURFACE_MAX_Y = 3972;
	private static final int SURFACE_LEVEL_BASE_Y = 3520;
	private static final int UNDERGROUND_MIN_Y = 9918;
	private static final int UNDERGROUND_MAX_Y = 10375;
	private static final int UNDERGROUND_LEVEL_BASE_Y = 9912;
	private static final int TILES_PER_LEVEL = 8;
	/** Inside the surface area but not Wilderness: Ferox Enclave and the south edge (Shortest Path's boxes: x, y, width, height). */
	private static final int[][] NOT_WILDERNESS = {{3123, 3622, 2, 10}, {3125, 3617, 16, 23}, {3138, 3636, 18, 10},
		{3141, 3625, 14, 11}, {3141, 3619, 7, 6}, {2997, 3525, 34, 9}, {3005, 3534, 21, 10}, {3000, 3534, 5, 5},
		{3031, 3525, 2, 2}};

	private PositionRules()
	{
	}

	/** Farther than running moves in a tick: a teleport, a ladder, a boat. */
	private static final int JUMP_TILES = 4;

	/** Whether getting from {@code from} to {@code to} within a tick took a teleport, a ladder or a boat; false while either is unknown. */
	public static boolean teleported(WorldPoint from, WorldPoint to)
	{
		return from != null && to != null && (from.getPlane() != to.getPlane() || from.distanceTo2D(to) > JUMP_TILES);
	}

	/** On the same floor and within {@code radius}; false while either is unknown. */
	public static boolean near(WorldPoint tile, WorldPoint goal, int radius)
	{
		return tile != null && goal != null && tile.getPlane() == goal.getPlane() && tile.distanceTo2D(goal) <= radius;
	}

	/**
	 * @param boatTile the boat entity's tile through {@code fromLocalInstance}; never the player's raw
	 *     location, which on a boat is the deck's own frozen coordinates
	 */
	public static Position onBoat(WorldPoint boatTile)
	{
		return boatTile == null ? Position.NONE : new Position(boatTile, Position.Kind.BOAT, boatTile);
	}

	/**
	 * @param mappedTile the player's local location through {@code fromLocalInstance}, which also maps
	 *     instances to their template
	 */
	public static Position onFoot(WorldPoint mappedTile, boolean topLevelInstance)
	{
		if (mappedTile == null)
		{
			return Position.NONE;
		}
		if (isInPoh(mappedTile))
		{
			return new Position(POH_NODE, Position.Kind.POH, mappedTile);
		}
		return new Position(mappedTile, topLevelInstance ? Position.Kind.INSTANCE : Position.Kind.WORLD, mappedTile);
	}

	/** x/y only: the POH template comes back on plane 2 from every floor. */
	public static boolean isInPoh(WorldPoint tile)
	{
		return tile.getX() >= POH_MIN_X && tile.getX() <= POH_MAX_X && tile.getY() >= POH_MIN_Y && tile.getY() <= POH_MAX_Y;
	}

	/** Must match the areas of Shortest Path's {@code WildernessChecker}. */
	public static int wildernessLevel(WorldPoint tile)
	{
		if (tile == null || tile.getX() < WILDERNESS_MIN_X)
		{
			return 0;
		}
		int x = tile.getX();
		int y = tile.getY();
		if (isSafeInsideSurfaceArea(x, y))
		{
			return 0;
		}
		if (y >= SURFACE_MIN_Y && y <= SURFACE_MAX_Y && x <= WILDERNESS_MAX_X_SURFACE)
		{
			return (y - SURFACE_LEVEL_BASE_Y) / TILES_PER_LEVEL + 1;
		}
		if (y >= UNDERGROUND_MIN_Y && y <= UNDERGROUND_MAX_Y && x <= WILDERNESS_MAX_X_UNDERGROUND)
		{
			return (y - UNDERGROUND_LEVEL_BASE_Y) / TILES_PER_LEVEL + 1;
		}
		return 0;
	}

	private static boolean isSafeInsideSurfaceArea(int x, int y)
	{
		for (int[] box : NOT_WILDERNESS)
		{
			if (x >= box[0] && x < box[0] + box[2] && y >= box[1] && y < box[1] + box[3])
			{
				return true;
			}
		}
		return false;
	}
}

package com.cluehelper.player;

import java.util.Map;
import java.util.TreeMap;

/** Client thread only. */
public final class RebuildStats
{
	private static final double NANOS_PER_MS = 1_000_000.0;
	private static final double TICKS_PER_MINUTE = 100.0;

	private final Map<String, Integer> byReason = new TreeMap<>();
	private final Map<String, Long> readNanos = new TreeMap<>();
	private int rebuilds;
	private long totalNanos;
	private long maxNanos;
	private int firstTick = -1;
	private int lastTick;

	void record(String reason, long nanos, int tick)
	{
		byReason.merge(reason, 1, Integer::sum);
		rebuilds++;
		totalNanos += nanos;
		maxNanos = Math.max(maxNanos, nanos);
		if (firstTick < 0)
		{
			firstTick = tick;
		}
		lastTick = tick;
	}

	void recordRead(String what, long nanos)
	{
		readNanos.put(what, nanos);
	}

	public String summary()
	{
		int ticks = Math.max(1, lastTick - firstTick);
		return String.format("%d rebuilds over %d ticks (%.1f/min), mean %.3f ms, max %.3f ms; by reason %s; reads %s",
			rebuilds, ticks, rebuilds * TICKS_PER_MINUTE / ticks, rebuilds == 0 ? 0 : totalNanos / NANOS_PER_MS / rebuilds,
			maxNanos / NANOS_PER_MS, byReason, readsInMs());
	}

	private Map<String, String> readsInMs()
	{
		Map<String, String> ms = new TreeMap<>();
		readNanos.forEach((what, nanos) -> ms.put(what, String.format("%.2f ms", nanos / NANOS_PER_MS)));
		return ms;
	}
}

package com.cluehelper.player;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import lombok.Value;
import net.runelite.api.EnumID;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;

/**
 * Everything except the tomes comes from the cache, so a game update that adds a staff or a rune carries
 * over by itself. The spellbook widget is never read: it is stale while the magic tab is hidden.
 */
public final class RuneModel
{
	private static final int PARAM_RUNE_1 = 365;
	private static final int PARAM_RUNE_COUNT_1 = 366;
	private static final int PARAM_RUNE_2 = 367;
	private static final int PARAM_RUNE_COUNT_2 = 368;
	private static final int PARAM_RUNE_3 = 369;
	private static final int PARAM_RUNE_COUNT_3 = 370;
	private static final int[][] RUNE_PARAMS = {
		{PARAM_RUNE_1, PARAM_RUNE_COUNT_1}, {PARAM_RUNE_2, PARAM_RUNE_COUNT_2}, {PARAM_RUNE_3, PARAM_RUNE_COUNT_3}};
	private static final int PARAM_NAME = 601;
	private static final int PARAM_MEMBERS = 603;
	private static final int PARAM_LEVEL = 604;
	private static final int PARAM_QUEST = 1189;
	private static final int ABSENT = -1;

	/** {element rune, enum of its staves (OBJ → BOOLEAN), enum of the pouch types that hold it}. */
	private static final int[][] ELEMENTS = {
		{ItemID.AIRRUNE, 988, 983},
		{ItemID.WATERRUNE, 989, 987},
		{ItemID.EARTHRUNE, 996, 993},
		{ItemID.FIRERUNE, 997, 994},
	};
	/** Not in the cache as data. Only the charged ids: an empty tome supplies nothing. */
	private static final int[][] TOMES = {
		{ItemID.TOME_OF_FIRE, ItemID.FIRERUNE},
		{ItemID.TOME_OF_WATER, ItemID.WATERRUNE},
		{ItemID.TOME_OF_EARTH, ItemID.EARTHRUNE},
	};

	private final List<Spell> spells;
	private final Map<Integer, Integer> pouchRunes;
	/** The rune itself comes first. */
	private final Map<Integer, List<Integer>> payersByRune;
	private final Map<Integer, Set<Integer>> unlimitingWornItemsByRune;
	private final Map<Integer, String> runeNames;

	private RuneModel(List<Spell> spells, Map<Integer, Integer> pouchRunes, Map<Integer, List<Integer>> payersByRune,
		Map<Integer, Set<Integer>> unlimitingWornItemsByRune, Map<Integer, String> runeNames)
	{
		this.spells = spells;
		this.pouchRunes = pouchRunes;
		this.payersByRune = payersByRune;
		this.unlimitingWornItemsByRune = unlimitingWornItemsByRune;
		this.runeNames = runeNames;
	}

	/** On the client thread when {@code cache} is the client. */
	public static RuneModel load(CacheView cache)
	{
		Map<Integer, Integer> pouchRunes = enumMap(cache, EnumID.RUNEPOUCH_RUNE);
		Map<Integer, Set<Integer>> payerSets = new HashMap<>();
		Map<Integer, String> names = new HashMap<>();
		for (int rune : pouchRunes.values())
		{
			payerSets.computeIfAbsent(rune, r -> new LinkedHashSet<>()).add(rune);
			names.put(rune, cache.itemName(rune));
		}
		Map<Integer, Set<Integer>> unlimited = new HashMap<>();
		for (int[] element : ELEMENTS)
		{
			int rune = element[0];
			unlimited.computeIfAbsent(rune, r -> new TreeSet<>()).addAll(keysOf(cache, element[1]));
			for (int type : keysOf(cache, element[2]))
			{
				Integer combination = pouchRunes.get(type);
				if (combination != null)
				{
					payerSets.computeIfAbsent(rune, r -> new LinkedHashSet<>()).add(combination);
				}
			}
		}
		for (int[] tome : TOMES)
		{
			unlimited.computeIfAbsent(tome[1], r -> new TreeSet<>()).add(tome[0]);
		}
		for (int[] row : cache.multirunes())
		{
			payerSets.computeIfAbsent(row[0], r -> new LinkedHashSet<>(Collections.singleton(row[0]))).add(row[1]);
		}
		Map<Integer, List<Integer>> payers = new HashMap<>();
		payerSets.forEach((rune, set) -> payers.put(rune, List.copyOf(set)));
		Map<Integer, Set<Integer>> unlimitedCopy = new HashMap<>();
		unlimited.forEach((rune, set) -> unlimitedCopy.put(rune, Set.copyOf(set)));
		return new RuneModel(List.copyOf(spells(cache)), Map.copyOf(pouchRunes), Map.copyOf(payers),
			Map.copyOf(unlimitedCopy), Map.copyOf(names));
	}

	public List<Spell> getSpells()
	{
		return spells;
	}

	/** Every item that pays for a rune or stands in for one: runes, combination runes, staves and tomes. */
	public Set<Integer> sourceItemIds()
	{
		Set<Integer> ids = new HashSet<>();
		payersByRune.values().forEach(ids::addAll);
		unlimitingWornItemsByRune.values().forEach(ids::addAll);
		return Set.copyOf(ids);
	}

	/** -1 for an unknown pouch type. */
	public int pouchRune(int pouchType)
	{
		return pouchRunes.getOrDefault(pouchType, -1);
	}

	public boolean isRune(int itemId)
	{
		return payersByRune.containsKey(itemId);
	}

	private String runeName(int rune)
	{
		return runeNames.getOrDefault(rune, "rune " + rune);
	}

	public Supply supply(int rune, int quantity, PlayerSnapshot player)
	{
		for (int source : unlimitingWornItemsByRune.getOrDefault(rune, Collections.emptySet()))
		{
			if (player.count(Container.WORN, source) > 0)
			{
				return new Supply(true, Integer.MAX_VALUE, List.of(new ItemUse(Container.WORN, source, 1)));
			}
		}
		List<ItemUse> used = new ArrayList<>();
		int have = 0;
		for (Container container : new Container[]{Container.INVENTORY, Container.RUNE_POUCH, Container.BANK, Container.GROUP_STORAGE})
		{
			for (int payer : payersByRune.getOrDefault(rune, List.of(rune)))
			{
				int count = player.count(container, payer);
				if (count > 0 && have < quantity)
				{
					used.add(new ItemUse(container, payer, Math.min(count, quantity - have)));
				}
				have += count;
			}
		}
		return new Supply(have >= quantity, have, have >= quantity ? List.copyOf(used) : List.of());
	}

	/** Ignores which book is active: that is the planner's business. */
	public List<String> whyNotCastable(Spell spell, PlayerSnapshot player)
	{
		List<String> whyNot = new ArrayList<>();
		if (player.boosted(Skill.MAGIC) < spell.getLevel())
		{
			whyNot.add("needs " + spell.getLevel() + " Magic");
		}
		if (spell.isMembers() && !player.isMembersWorld())
		{
			whyNot.add("members world only");
		}
		if (spell.getQuest() != null && !player.finished(spell.getQuest()))
		{
			whyNot.add(player.isQuestsRead() ? spell.getQuest().getName() + " not finished" : "quests not read yet");
		}
		for (Spell.RuneCost cost : spell.getRunes())
		{
			Supply supply = supply(cost.getRune(), cost.getQuantity(), player);
			if (!supply.isEnough())
			{
				whyNot.add(shortfall(cost.getRune(), cost.getQuantity(), supply.getHave()));
			}
		}
		return whyNot;
	}

	public String shortfall(int rune, int quantity, int have)
	{
		return "needs " + quantity + " " + runeName(rune).toLowerCase() + (quantity == 1 ? "" : "s") + " (has " + have + ")";
	}

	@Value
	public static class Supply
	{
		boolean enough;
		/** {@link Integer#MAX_VALUE} for a staff or tome. */
		int have;
		/** Empty unless enough. */
		List<ItemUse> witness;
	}

	private static List<Spell> spells(CacheView cache)
	{
		Map<Integer, Quest> questsById = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			questsById.put(quest.getId(), quest);
		}
		List<Spell> spells = new ArrayList<>();
		int[] books = cache.enumKeys(EnumID.SPELLBOOKS);
		int[] bookEnums = cache.enumIntValues(EnumID.SPELLBOOKS);
		for (int b = 0; b < books.length; b++)
		{
			Book book = Book.of(books[b]);
			if (book == null)
			{
				continue;
			}
			for (int obj : cache.enumIntValues(bookEnums[b]))
			{
				spells.add(spell(cache, book, obj, questsById));
			}
		}
		return spells;
	}

	private static Spell spell(CacheView cache, Book book, int obj, Map<Integer, Quest> questsById)
	{
		List<Spell.RuneCost> runes = new ArrayList<>();
		for (int[] param : RUNE_PARAMS)
		{
			int rune = cache.itemIntParam(obj, param[0], ABSENT);
			if (rune > 0)
			{
				runes.add(new Spell.RuneCost(rune, cache.itemIntParam(obj, param[1], 0)));
			}
		}
		String name = cache.itemStringParam(obj, PARAM_NAME);
		return new Spell(book, name == null ? "spell " + obj : name, obj,
			Math.max(0, cache.itemIntParam(obj, PARAM_LEVEL, 0)), cache.itemIntParam(obj, PARAM_MEMBERS, 0) == 1,
			questsById.get(cache.itemIntParam(obj, PARAM_QUEST, ABSENT)), List.copyOf(runes));
	}

	private static Map<Integer, Integer> enumMap(CacheView cache, int enumId)
	{
		int[] keys = cache.enumKeys(enumId);
		int[] values = cache.enumIntValues(enumId);
		Map<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < keys.length; i++)
		{
			map.put(keys[i], values[i]);
		}
		return map;
	}

	private static List<Integer> keysOf(CacheView cache, int enumId)
	{
		List<Integer> keys = new ArrayList<>();
		for (int key : cache.enumKeys(enumId))
		{
			keys.add(key);
		}
		return keys;
	}
}

