	int objectId;
}

package com.cluehelper.route;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

/**
 * Lays a walk on the tiles the game itself walks, keeping its length. The player clicks a tile and the game searches
 * a 128 by 128 window round them breadth first, trying neighbours in {@link Directions} order, and walks the path
 * back from the clicked tile along each tile's first finder. Many walks are equally short; this one is the game's.
 * Each stretch on foot is split into clicks a minimap click can reach, and each click's own path replaces the walk up
 * to it when it is exactly as long. A step no click walks (through a door, onto a ladder) stays as it was.
 * Adapted from Shortest Path's InGameWalkRewriter.
 */
final class GameWalk
{
	/** About a minimap click's reach. */
	private static final int CLICK_TILES = 15;
	/** The corners the game keeps for one click's walk; past them the player stops short. */
	private static final int MAX_CHECKPOINTS = 25;
	private static final int WINDOW = 128;
	private static final int HALF_WINDOW = WINDOW / 2;
	private static final int UNVISITED = -1;
	private static final int NO_STEP = Integer.MIN_VALUE;

	private final int[] distance = new int[WINDOW * WINDOW];
	private final int[] parent = new int[WINDOW * WINDOW];
	private final int[] queue = new int[WINDOW * WINDOW];

	List<WorldPoint> along(Ground ground, int[] path)
	{
		int[] walked = path.clone();
		int current = 0;
		while (current < path.length - 1)
		{
			int click = farthestClick(ground, path, current);
			if (click == current)
			{
				current++;
				continue;
			}
			int originX = WalkSearch.x(path[current]) - HALF_WINDOW;
			int originY = WalkSearch.y(path[current]) - HALF_WINDOW;
			int plane = WalkSearch.plane(path[current]);
			int at = local(originX, originY, path[click]);
			for (int i = click; i > current; i--, at = parent[at])
			{
				walked[i] = WalkTable.pack(originX + at % WINDOW, originY + at / WINDOW, plane);
			}
			current = click;
		}
		List<WorldPoint> tiles = new ArrayList<>(walked.length);
		for (int tile : walked)
		{
			tiles.add(WalkTable.unpack(tile));
		}
		return tiles;
	}

	/** The farthest tile on foot within reach whose clicked walk is as long as the path's, or {@code current} if none. */
	private int farthestClick(Ground ground, int[] path, int current)
	{
		int last = current;
		while (last + 1 < path.length && isStep(path[last], path[last + 1]) && withinReach(path[current], path[last + 1]))
		{
			last++;
		}
		if (last == current)
		{
			return current;
		}
		int originX = WalkSearch.x(path[current]) - HALF_WINDOW;
		int originY = WalkSearch.y(path[current]) - HALF_WINDOW;
		search(ground, originX, originY, WalkSearch.plane(path[current]), last - current);
		for (int i = last; i > current; i--)
		{
			int at = local(originX, originY, path[i]);
			if (distance[at] == i - current && fitsCheckpoints(at, i - current))
			{
				return i;
			}
		}
		return current;
	}

	/** The game's walking search from the window's centre, as deep as {@code depth}; doors stay shut as the game has them. */
	private void search(Ground ground, int originX, int originY, int plane, int depth)
	{
		Arrays.fill(distance, UNVISITED);
		int start = HALF_WINDOW * WINDOW + HALF_WINDOW;
		distance[start] = 0;
		parent[start] = start;
		int head = 0;
		int tail = 0;
		queue[tail++] = start;
		while (head < tail)
		{
			int at = queue[head++];
			if (distance[at] >= depth)
			{
				break;
			}
			int x = at % WINDOW;
			int y = at / WINDOW;
			for (int d = 0; d < Directions.COUNT; d++)
			{
				int nx = x + Directions.DX[d];
				int ny = y + Directions.DY[d];
				int next = ny * WINDOW + nx;
				if (nx < 0 || ny < 0 || nx >= WINDOW || ny >= WINDOW || distance[next] != UNVISITED
					|| !ground.canMove(originX + x, originY + y, plane, d) || ground.stepCost(originX + x, originY + y, plane, d) != 1)
				{
					continue;
				}
				distance[next] = distance[at] + 1;
				parent[next] = at;
				queue[tail++] = next;
			}
		}
	}

	private boolean fitsCheckpoints(int at, int steps)
	{
		int turns = 0;
		int previous = NO_STEP;
		for (int i = 0; i < steps; i++, at = parent[at])
		{
			int step = at - parent[at];
			turns += previous != NO_STEP && step != previous ? 1 : 0;
			previous = step;
		}
		return turns + 1 <= MAX_CHECKPOINTS;
	}

	private static boolean isStep(int from, int to)
	{
		return WalkSearch.plane(from) == WalkSearch.plane(to)
			&& Math.max(Math.abs(WalkSearch.x(from) - WalkSearch.x(to)), Math.abs(WalkSearch.y(from) - WalkSearch.y(to))) == 1;
	}

	private static boolean withinReach(int from, int to)
	{
		int dx = WalkSearch.x(to) - WalkSearch.x(from);
		int dy = WalkSearch.y(to) - WalkSearch.y(from);
		return dx * dx + dy * dy <= CLICK_TILES * CLICK_TILES;
	}

	private static int local(int originX, int originY, int tile)
	{
		return (WalkSearch.y(tile) - originY) * WINDOW + WalkSearch.x(tile) - originX;
	}
}

package com.cluehelper.route;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.EquipmentInventorySlot;

/**
 * Worn gear adding up to a bonus total, from what the player wears, carries and has stored: as few items out of the
 * bank as can do it, then as few to put on. One item per slot; a two-handed weapon leaves the shield slot empty.
 */
public final class GearPicker
{
	private static final int WEAPON = EquipmentInventorySlot.WEAPON.getSlotIdx();
	private static final int SHIELD = EquipmentInventorySlot.SHIELD.getSlotIdx();

	@Value
	public static class Piece
	{
		int itemId;
		int slot;
		boolean twoHanded;
		int value;
	}

	@Value
	public static class Choice
	{
		/** Not yet worn, the withdrawn ones included. */
		List<Integer> equip;
		List<Integer> withdraw;
	}

	@Value
	private static class Upgrade
	{
		Piece piece;
		int gain;
	}

	private GearPicker()
	{
	}

	/** Empty when nothing owned adds up to {@code atLeast}. */
	public static Optional<Choice> pick(Collection<Piece> pieces, Set<Integer> worn, Set<Integer> inventory, Set<Integer> stored,
		int atLeast)
	{
		Choice best = null;
		for (boolean twoHanded : new boolean[]{false, true})
		{
			Choice choice = pick(pieces, twoHanded, worn, inventory, stored, atLeast);
			if (choice != null && (best == null || cheaper(choice, best)))
			{
				best = choice;
			}
		}
		return Optional.ofNullable(best);
	}

	private static Choice pick(Collection<Piece> pieces, boolean twoHanded, Set<Integer> worn, Set<Integer> inventory,
		Set<Integer> stored, int atLeast)
	{
		Map<Integer, Piece> current = bestPerSlot(pieces, twoHanded, worn);
		Map<Integer, Piece> carried = bestPerSlot(pieces, twoHanded, union(worn, inventory));
		Map<Integer, Piece> storedBest = bestPerSlot(pieces, twoHanded, stored);
		int need = atLeast - current.values().stream().mapToInt(Piece::getValue).sum();
		List<Upgrade> fromCarried = upgrades(carried, current, Map.of());
		List<Upgrade> fromStorage = upgrades(storedBest, current, carried);
		for (int withdrawn = 0; withdrawn <= fromStorage.size(); withdrawn++)
		{
			List<Upgrade> taken = fromStorage.subList(0, withdrawn);
			Set<Integer> takenSlots = new HashSet<>();
			int left = need;
			for (Upgrade upgrade : taken)
			{
				takenSlots.add(upgrade.piece.slot);
				left -= upgrade.piece.value - value(current.get(upgrade.piece.slot));
			}
			List<Integer> equip = new ArrayList<>();
			taken.forEach(upgrade -> equip.add(upgrade.piece.itemId));
			for (Upgrade upgrade : fromCarried)
			{
				if (left <= 0)
				{
					break;
				}
				if (!takenSlots.contains(upgrade.piece.slot))
				{
					equip.add(upgrade.piece.itemId);
					left -= upgrade.gain;
				}
			}
			if (left <= 0)
			{
				List<Integer> withdraw = taken.stream().map(upgrade -> upgrade.piece.itemId).collect(Collectors.toUnmodifiableList());
				return new Choice(List.copyOf(equip), withdraw);
			}
		}
		return null;
	}

	/** Per slot, how much {@code better} adds over the larger of what is worn and {@code beaten}; best first. */
	private static List<Upgrade> upgrades(Map<Integer, Piece> better, Map<Integer, Piece> current, Map<Integer, Piece> beaten)
	{
		List<Upgrade> upgrades = new ArrayList<>();
		better.forEach((slot, piece) ->
		{
			int gain = piece.value - Math.max(value(current.get(slot)), value(beaten.get(slot)));
			if (gain > 0)
			{
				upgrades.add(new Upgrade(piece, gain));
			}
		});
		upgrades.sort(Comparator.comparingInt(Upgrade::getGain).reversed());
		return upgrades;
	}

	private static Map<Integer, Piece> bestPerSlot(Collection<Piece> pieces, boolean twoHanded, Set<Integer> owned)
	{
		Map<Integer, Piece> best = new HashMap<>();
		for (Piece piece : pieces)
		{
			if (owned.contains(piece.itemId) && fits(piece, twoHanded))
			{
				best.merge(piece.slot, piece, (a, b) -> b.value > a.value ? b : a);
			}
		}
		return best;
	}

	private static boolean fits(Piece piece, boolean twoHanded)
	{
		if (piece.slot == SHIELD)
		{
			return !twoHanded;
		}
		return piece.slot != WEAPON || piece.twoHanded == twoHanded;
	}

	private static boolean cheaper(Choice a, Choice b)
	{
		if (a.withdraw.size() != b.withdraw.size())
		{
			return a.withdraw.size() < b.withdraw.size();
		}
		return a.equip.size() < b.equip.size();
	}

	private static int value(Piece piece)
	{
		return piece == null ? 0 : piece.value;
	}

	private static Set<Integer> union(Set<Integer> a, Set<Integer> b)
	{
		Set<Integer> all = new HashSet<>(a);
		all.addAll(b);
		return all;
	}
}

package com.cluehelper.route;

import com.cluehelper.step.GearBonus;
import java.util.Collection;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/** Client thread only: item stats and names. What each owned item adds to a gear bonus, cached by item. */
@Singleton
public class GearPieces
{
	private static final int AMMO = EquipmentInventorySlot.AMMO.getSlotIdx();

	private final Client client;
	private final ItemManager itemManager;
	private final Map<GearBonus, Map<Integer, Optional<GearPicker.Piece>>> cache = new EnumMap<>(GearBonus.class);

	@Inject
	GearPieces(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	public Map<Integer, GearPicker.Piece> of(GearBonus bonus, Collection<Integer> itemIds)
	{
		Map<Integer, Optional<GearPicker.Piece>> known = cache.computeIfAbsent(bonus, k -> new HashMap<>());
		Map<Integer, GearPicker.Piece> pieces = new HashMap<>();
		for (int itemId : itemIds)
		{
			known.computeIfAbsent(itemId, id -> piece(bonus, id)).ifPresent(piece -> pieces.put(itemId, piece));
		}
		return Map.copyOf(pieces);
	}

	private Optional<GearPicker.Piece> piece(GearBonus bonus, int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		ItemEquipmentStats equipment = stats == null || !stats.isEquipable() ? null : stats.getEquipment();
		if (equipment == null)
		{
			return Optional.empty();
		}
		int value = value(bonus, equipment, itemId);
		return value > 0 ? Optional.of(new GearPicker.Piece(itemId, equipment.getSlot(), equipment.isTwoHanded(), value))
			: Optional.empty();
	}

	private int value(GearBonus bonus, ItemEquipmentStats equipment, int itemId)
	{
		switch (bonus)
		{
			case MELEE_STRENGTH:
				return equipment.getStr();
			case MAGIC_ATTACK:
				return equipment.getAmagic();
			case RANGED_ATTACK:
				return equipment.getArange();
			case GUTHIX_ITEMS:
				return isGuthix(name(itemId)) ? 1 : 0;
			case ZAMORAK_ITEMS:
				return isZamorak(name(itemId)) ? 1 : 0;
			case ANY_EQUIPMENT:
				return equipment.getSlot() != AMMO ? 1 : 0;
			default:
				throw new IllegalArgumentException("unhandled gear bonus " + bonus);
		}
	}

	private String name(int itemId)
	{
		return client.getItemDefinition(itemId).getName().toLowerCase(Locale.ROOT);
	}

	/** Assumed from item names: Guthix's own gear, all Void Knight equipment and the Book of balance. */
	private static boolean isGuthix(String name)
	{
		return name.contains("guthix") || name.startsWith("void ") || name.startsWith("elite void") || name.equals("book of balance");
	}

	/** Assumed from item names: Zamorak's own gear (Zamorakian spear and hasta too) and the Unholy book. */
	private static boolean isZamorak(String name)
	{
		return name.contains("zamorak") || name.equals("unholy book");
	}
}

package com.cluehelper.route;

import java.util.Arrays;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/** Worn gear adding up to a bonus total, as a need: any owned piece that adds to it counts as one of its items. */
@Value
public class GearRequirement implements ItemRequirement
{
	String name;
	int atLeast;
	/** By item id: the owned items that add to the total. */
	Map<Integer, GearPicker.Piece> pieces;

	@Override
	public boolean fulfilledBy(int itemId)
	{
		return pieces.containsKey(itemId);
	}

	@Override
	public boolean fulfilledBy(Item[] items)
	{
		Set<Integer> ids = Arrays.stream(items).map(Item::getId).collect(Collectors.toSet());
		return choose(Set.of(), ids, Set.of()).isPresent();
	}

	@Override
	public String getCollectiveName(Client client)
	{
		return name;
	}

	public Optional<GearPicker.Choice> choose(Set<Integer> worn, Set<Integer> inventory, Set<Integer> stored)
	{
		return GearPicker.pick(pieces.values(), worn, inventory, stored, atLeast);
	}

	public boolean isWorn(Set<Integer> worn)
	{
		return choose(worn, Set.of(), Set.of()).map(choice -> choice.getEquip().isEmpty()).orElse(false);
	}
}

package com.cluehelper.route;

import java.util.Arrays;
import java.util.function.IntPredicate;

/**
 * Where a walk can step: the loaded scene as the client has it, its closed doors opened at a cost, and Shortest Path's
 * world map past the scene's edge. The open walk rows (stairs, ladders, shortcuts) join tiles apart. In an instance,
 * whose tiles are on no map, only its scene. Any thread once built.
 */
public final class Ground
{
	private static final int[] NO_ROWS = new int[0];
	private static final int WORLD_TILE_LIMIT = 150_000;

	private final WorldMap map;
	private final LoadedScene scene;
	private final WalkTable table;
	private final IntPredicate rowOpen;

	private Ground(WorldMap map, LoadedScene scene, WalkTable table, IntPredicate rowOpen)
	{
		this.map = map;
		this.scene = scene;
		this.table = table;
		this.rowOpen = rowOpen;
	}

	/** {@code scene}: the loaded scene with its doors open, or null; {@code rowOpen}: by row of {@code table}. */
	public static Ground world(WorldMap map, LoadedScene scene, WalkTable table, IntPredicate rowOpen)
	{
		return new Ground(map, scene, table, rowOpen);
	}

	/** An instance's scene, or the loaded scene alone for a quick walk inside it. */
	public static Ground sceneOnly(LoadedScene scene)
	{
		return new Ground(null, scene, null, row -> false);
	}

	LoadedScene getScene()
	{
		return scene;
	}

	/** Past this many tiles reached, a search gives up on its goal. */
	int tileLimit()
	{
		return map != null ? WORLD_TILE_LIMIT : scene.getFlags().length * scene.getSizeX() * scene.getSizeY();
	}

	boolean canMove(int x, int y, int plane, int direction)
	{
		int nx = x + Directions.DX[direction];
		int ny = y + Directions.DY[direction];
		if (inScene(x, y, plane) && inScene(nx, ny, plane))
		{
			return scene.canMove(x - scene.getBaseX(), y - scene.getBaseY(), plane, direction);
		}
		return map != null && map.canMove(x, y, plane, direction);
	}

	/** One tile, or more through a closed door the scene shows. */
	int stepCost(int x, int y, int plane, int direction)
	{
		boolean inside = inScene(x, y, plane) && inScene(x + Directions.DX[direction], y + Directions.DY[direction], plane);
		return inside ? scene.stepCost(plane, x - scene.getBaseX(), y - scene.getBaseY(), direction) : 1;
	}

	/** An object stands on the tile: stairs, a ladder, a crate. */
	boolean isBlocked(int x, int y, int plane)
	{
		if (inScene(x, y, plane))
		{
			return scene.isBlocked(x - scene.getBaseX(), y - scene.getBaseY(), plane);
		}
		return map == null || map.isBlocked(x, y, plane);
	}

	/** A wall or door stands between straight neighbours; an object on the far tile is no wall. */
	boolean isWallBetween(int x, int y, int plane, int dx, int dy)
	{
		if (inScene(x, y, plane) && inScene(x + dx, y + dy, plane))
		{
			return scene.isWallBetween(x - scene.getBaseX(), y - scene.getBaseY(), plane, dx, dy);
		}
		return map == null || map.isWallBetween(x, y, plane, dx, dy);
	}

	/** The open rows that start on the packed tile. */
	int[] openRowsFrom(int tile)
	{
		if (table == null)
		{
			return NO_ROWS;
		}
		int[] rows = table.rowsFrom(tile);
		return rows.length == 0 ? NO_ROWS : Arrays.stream(rows).filter(rowOpen).toArray();
	}

	int rowDestination(int row)
	{
		return table.rowDestTile(row);
	}

	boolean isExitRow(int row)
	{
		return table.isExitRow(row);
	}

	Exit exit(int row)
	{
		return table.exit(table.rowOrigin(row), table.rowDest(row));
	}

	int rowCost(int row)
	{
		return table.rowCost(row);
	}

	private boolean inScene(int x, int y, int plane)
	{
		return scene != null && scene.contains(x, y, plane);
	}
}

package com.cluehelper.route;

import com.cluehelper.SpellbookChanges;
import com.cluehelper.player.Book;
import com.cluehelper.transport.RowAvailability;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * Label-setting Dijkstra over states (leg, node, banked b, change category c, book k, has-transport t).
 * <p>
 * Banked and change category are state dimensions so that the goal's states hold each feature set's best route at
 * once, and Best, Direct and Same book never mix feature sets. Spellbook Swap is fused into the spell edge it
 * enables. A pending revert is a book of its own that turns into Lunar on its free cast, or once its window passes.
 */
final class LabelSearch
{
	static final int NONE = 0;
	static final int CHANGED = 1;
	static final int WALKED = 2;
	static final int CATEGORIES = 3;
	private static final int BOOKS = 7;
	private static final int FIRST_PENDING = 4;
	private static final int LUNAR = Book.LUNAR.ordinal();
	private static final int MAX_LABELS = 4;
	private static final int STATES_PER_NODE = 2 * CATEGORIES * BOOKS * 2;
	private static final int SAME_BOOK_SLACK_HALF_TICKS = 120;
	private static final int SURFACE_WILDERNESS_MAX_Y = 3972;
	private static final int[] NOTHING = new int[0];
	private static final int CANNOT_CAST = -1;

	private final PlanContext ctx;
	private final List<int[]> legTargets;
	private final boolean probes;
	private final int areaHalfTicks;
	private final int nodes;
	private final int revertHalfTicks;
	private final Set<String> excluded;
	/** Only routes whose first transport has this key, a way into the house aside; null for any. */
	private final String onlyFirst;
	private final boolean requireTransport;
	private final boolean wantSameBook;
	private final int rankLimit;
	private final Label[] slots;
	private final LowerBound[] bounds;
	private final boolean[][] targets;
	private final PriorityQueue<Label> queue = new PriorityQueue<>((a, b) -> a.f != b.f ? a.f - b.f : a.half - b.half);

	final Label[][] goals = new Label[2][CATEGORIES];
	final Map<Integer, Label[][]> probeBest = new HashMap<>();
	int labels;

	/** @param excluded first-transport keys to leave out; {@link Route#WALK} leaves out routes with no transport */
	LabelSearch(PlanContext ctx, List<int[]> legTargets, boolean probes, int areaHalfTicks, Set<String> excluded, int rankLimit)
	{
		this(ctx, legTargets, probes, areaHalfTicks, excluded, null, rankLimit);
	}

	/** The routes that start with transport {@code onlyFirst} ({@link Route#WALK} for none), up to {@code rankLimit}. */
	LabelSearch(PlanContext ctx, List<int[]> legTargets, int areaHalfTicks, String onlyFirst, int rankLimit)
	{
		this(ctx, legTargets, false, areaHalfTicks, Set.of(), onlyFirst, rankLimit);
	}

	private LabelSearch(PlanContext ctx, List<int[]> legTargets, boolean probes, int areaHalfTicks, Set<String> excluded,
		String onlyFirst, int rankLimit)
	{
		this.rankLimit = rankLimit;
		this.ctx = ctx;
		this.legTargets = legTargets;
		this.probes = probes;
		this.areaHalfTicks = areaHalfTicks;
		this.excluded = excluded;
		this.onlyFirst = onlyFirst;
		this.requireTransport = excluded.contains(Route.WALK) || onlyFirst != null && !Route.WALK.equals(onlyFirst);
		this.wantSameBook = excluded.isEmpty() && onlyFirst == null;
		this.nodes = ctx.nodeCount();
		this.revertHalfTicks = ctx.startPending ? 2 * ctx.in.getRevertTicksLeft() : -1;
		this.slots = new Label[legTargets.size() * nodes * STATES_PER_NODE * MAX_LABELS];
		this.bounds = new LowerBound[legTargets.size()];
		this.targets = new boolean[legTargets.size()][nodes];
		for (int leg = 0; leg < bounds.length; leg++)
		{
			bounds[leg] = probes ? null : ctx.lowerBound(legTargets.get(leg));
			for (int target : legTargets.get(leg))
			{
				targets[leg][target] = true;
			}
		}
	}

	void run()
	{
		offer(null, startNode(), startBankState(), NONE, startBook(), 0, 0, 0, 0, null, null, null, new int[0]);
		while (!queue.isEmpty())
		{
			Label label = queue.poll();
			if (label.dead)
			{
				continue;
			}
			if (!probes && (label.f > rankLimit || pastEverythingUseful(label.f)))
			{
				break;
			}
			if (!probes && label.c != NONE && pastPlain(label.f))
			{
				continue;
			}
			if (label.node == ctx.goal)
			{
				if (goals[label.b][label.c] == null)
				{
					goals[label.b][label.c] = label;
				}
				continue;
			}
			expand(label);
		}
	}

	/**
	 * A route needing the margin must beat the best plain route, so nothing past it matters; while that route uses a
	 * change, Same book is still worth a slack past it.
	 */
	private boolean pastEverythingUseful(int f)
	{
		Label plain = bestPlainGoal();
		if (plain == null)
		{
			return false;
		}
		if (goals[0][NONE] != null || !wantSameBook)
		{
			return f > plain.rank;
		}
		return f > plain.rank + Math.max(plain.rank, SAME_BOOK_SLACK_HALF_TICKS);
	}

	/** Past the best plain route only Same book can still be found, so changed labels are dropped there. */
	private boolean pastPlain(int f)
	{
		Label plain = bestPlainGoal();
		return plain != null && f > plain.rank;
	}

	private Label bestPlainGoal()
	{
		Label[] noBankStop = goals[PlanContext.NOT_BANKED];
		return noBankStop[NONE] != null ? noBankStop[NONE] : noBankStop[CHANGED];
	}

	private int startNode()
	{
		PlanStart start = ctx.in.getStart();
		return start.getKind() == PlanStart.Kind.AT_NODE ? start.getNode() : ctx.start;
	}

	private int startBankState()
	{
		return ctx.in.isAtOpenBank() && ctx.options[PlanContext.BANKED] != null ? PlanContext.BANKED : PlanContext.NOT_BANKED;
	}

	private int startBook()
	{
		return ctx.startPending ? pendingIndex(ctx.startBook) : ctx.startBook.ordinal();
	}

	private void expand(Label from)
	{
		int k = effectiveBook(from.k, from.half);
		OriginClass abstractClass = ctx.abstractClass(from.node);
		if (abstractClass != null)
		{
			expandTeleports(from, abstractClass, k);
			expandCape(from, abstractClass, k);
			return;
		}
		if (isTarget(from.leg, from.node))
		{
			arrive(from, k);
		}
		expandWalks(from, k);
		OriginClass origin = ctx.originClass(from.node);
		if (origin.allowsTeleports())
		{
			offer(from, ctx.abstractNode(origin), from.b, from.c, k, from.t, from.leg, 0, 0, null, null, null, from.spent);
		}
		expandExits(from, k);
		if (ctx.houseUsable(from.node, from.t))
		{
			expandLocatedTeleports(from, k);
			expandFairyRing(from, k);
			expandLocatedChanges(from, origin, k);
		}
		expandBank(from, k);
	}

	private void expandLocatedTeleports(Label from, int k)
	{
		List<TransportOptions.Teleport> here = ctx.options[from.b].located.get(from.node);
		if (here == null)
		{
			return;
		}
		for (TransportOptions.Teleport tele : here)
		{
			if (tele.node != from.node && !ctx.forbidden(tele.node) && !excluded.contains(Route.teleportKey(tele.row)))
			{
				transport(from, tele.node, from.c, k, tele.halfTicks, Leg.Kind.TELEPORT, tele, null);
			}
		}
	}

	private void arrive(Label from, int k)
	{
		Book needed = ctx.stageBook(from.node);
		if (ctx.stageNeedsBank(from.node, from.b) || needed != null && bookOf(k) != needed)
		{
			return;
		}
		int[] staged = sortedUnion(from.withdrawn, ctx.stageWithdraw(from.node, from.b));
		if (from.leg + 1 < legTargets.size())
		{
			int half = PlanContext.WITHDRAW_HALF_TICKS * (staged.length - from.withdrawn.length);
			offer(from, from.node, from.b, from.c, k, from.t, from.leg + 1, half, half, null, null, null, from.spent, staged);
			return;
		}
		if (from.b == PlanContext.NOT_BANKED && !ctx.arrivesWithoutBank())
		{
			return;
		}
		int[] withdrawn = from.b == PlanContext.BANKED ? sortedUnion(staged, ctx.requiredWithdraw) : staged;
		int area = areaHalfTicks + PlanContext.WITHDRAW_HALF_TICKS * (withdrawn.length - from.withdrawn.length);
		Book end = endBook(k);
		int strand = ctx.strandHalfTicks(end, from.b, capeUses(from.spent));
		if (probes)
		{
			Label[][] best = probeBest.computeIfAbsent(from.node, n -> new Label[2][CATEGORIES]);
			Label current = best[from.b][from.c];
			if (current == null || current.rank > from.rank + area + strand)
			{
				best[from.b][from.c] = goalLabel(from, end, area, strand, withdrawn);
			}
			return;
		}
		if (!(requireTransport && from.t == 0))
		{
			Label goal = offer(from, ctx.goal, from.b, from.c, 0, 0, from.leg, area, area + strand, null, null, null, from.spent, withdrawn);
			if (goal != null)
			{
				goal.endBook = end;
			}
		}
	}

	private Label goalLabel(Label from, Book end, int area, int strand, int[] withdrawn)
	{
		Label goal = new Label();
		goal.parent = from;
		goal.node = ctx.goal;
		goal.b = from.b;
		goal.c = from.c;
		goal.half = from.half + area;
		goal.rank = from.rank + area + strand;
		goal.spent = from.spent;
		goal.withdrawn = withdrawn;
		goal.endBook = end;
		return goal;
	}

	private void expandWalks(Label from, int k)
	{
		if (from.node == ctx.start)
		{
			expandStartLegs(from, k);
			return;
		}
		if (!ctx.isTableNode(from.node))
		{
			return;
		}
		WalkTable table = ctx.table;
		WalkGates gates = ctx.gates(from.b);
		for (int e = table.entriesFrom(from.node); e < table.entriesEnd(from.node); e++)
		{
			int cost = gates.cost(e);
			int to = table.entryTo(e);
			if (cost == WalkTable.NO_PATH || ctx.forbidden(to))
			{
				continue;
			}
			int[] withdrawn = sortedUnion(from.withdrawn, gates.withdraw(e));
			if (!pointlessAfterBank(from, withdrawn) || ctx.usesBankItems(to))
			{
				int total = cost + PlanContext.WITHDRAW_HALF_TICKS * (withdrawn.length - from.withdrawn.length);
				offer(from, to, from.b, from.c, k, from.t, from.leg, total, total, Leg.Kind.WALK, null, null, from.spent, withdrawn);
			}
		}
	}

	private void expandStartLegs(Label from, int k)
	{
		PlanStart start = ctx.in.getStart();
		if (start.getKind() != PlanStart.Kind.SCENE)
		{
			return;
		}
		WalkCosts walk = start.getWalk();
		WalkTable table = ctx.table;
		for (int node = 0; node < table.nodeCount(); node++)
		{
			int cost = walk.cost(table.placed(node));
			if (cost != WalkCosts.UNREACHED && !ctx.forbidden(node))
			{
				offer(from, node, from.b, from.c, k, from.t, from.leg, cost, cost, Leg.Kind.WALK, null, null, from.spent);
			}
		}
		for (int[] targets : legTargets)
		{
			for (int node : targets)
			{
				int cost = ctx.isTableNode(node) ? WalkCosts.UNREACHED : walk.cost(ctx.tile(node));
				if (cost != WalkCosts.UNREACHED)
				{
					offer(from, node, from.b, from.c, k, from.t, from.leg, cost, cost, Leg.Kind.WALK, null, null, from.spent);
				}
			}
		}
	}

	private void expandExits(Label from, int k)
	{
		WorldPoint tile = ctx.tile(from.node);
		OriginClass origin = ctx.originClass(from.node);
		if (tile == null || !origin.isWilderness() || tile.getY() > SURFACE_WILDERNESS_MAX_Y)
		{
			return;
		}
		exit(from, k, tile, origin, OriginClass.WILD30, OriginClass.EXIT_WILD30_Y);
		exit(from, k, tile, origin, OriginClass.WILD20, OriginClass.EXIT_WILD20_Y);
		exit(from, k, tile, origin, OriginClass.WILD0, OriginClass.EXIT_WILD0_Y);
	}

	private void exit(Label from, int k, WorldPoint tile, OriginClass origin, OriginClass to, int exitY)
	{
		if (to.ordinal() < origin.ordinal() && tile.getY() > exitY)
		{
			int tiles = tile.getY() - exitY;
			offer(from, ctx.abstractNode(to), from.b, from.c, k, from.t, from.leg, tiles, tiles, Leg.Kind.WILDERNESS_EXIT, null, null, from.spent);
		}
	}

	private void expandTeleports(Label from, OriginClass origin, int k)
	{
		TransportOptions options = ctx.options[from.b];
		TransportOptions.Change swap = ctx.in.getSettings().getSpellbookChanges() != SpellbookChanges.OFF ? options.swap : null;
		for (TransportOptions.Teleport tele : options.teleports)
		{
			if (!origin.allows(tele.maxWilderness) || origin == OriginClass.POH && tele.minigame || ctx.forbidden(tele.node)
				|| excluded.contains(Route.teleportKey(tele.row)))
			{
				continue;
			}
			int bookAfter = bookAfterCasting(tele.book, k);
			if (bookAfter != CANNOT_CAST)
			{
				transport(from, tele.node, from.c, bookAfter, tele.halfTicks, Leg.Kind.TELEPORT, tele, null);
			}
			if (swap != null && k == LUNAR && tele.book != null && tele.book != Book.LUNAR)
			{
				transport(from, tele.node, Math.max(from.c, CHANGED), LUNAR, tele.halfTicks + swap.halfTicks, Leg.Kind.SWAP_TELEPORT, tele, swap);
			}
		}
	}

	private static int bookAfterCasting(Book rowBook, int k)
	{
		if (rowBook == null)
		{
			return k;
		}
		if (k < FIRST_PENDING)
		{
			return rowBook.ordinal() == k ? k : CANNOT_CAST;
		}
		return rowBook == pendingBook(k) ? LUNAR : CANNOT_CAST;
	}

	/** The Magic or Max cape changes to any expanded book wherever teleports work, which also ends a pending revert. */
	private void expandCape(Label from, OriginClass origin, int k)
	{
		TransportOptions.Change cape = ctx.options[from.b].cape;
		if (cape == null || !ctx.changesAllowed(origin))
		{
			return;
		}
		for (Book book : ctx.expanded)
		{
			if (k >= FIRST_PENDING || book.ordinal() != k)
			{
				change(from, from.node, Math.max(from.c, CHANGED), book.ordinal(), cape);
			}
		}
	}

	/**
	 * A single altar or Tyss toggles its book, or goes back to Standard when already on it; the occult altar and a
	 * mounted cape go to any expanded book.
	 */
	private void expandLocatedChanges(Label from, OriginClass origin, int k)
	{
		List<TransportOptions.Change> here = ctx.options[from.b].changes.get(from.node);
		if (here == null || !ctx.changesAllowed(origin))
		{
			return;
		}
		Book current = bookOf(k);
		for (TransportOptions.Change change : here)
		{
			Book toggles = change.change.getToggles();
			for (Book next : toggles == null ? ctx.expanded : Set.of(current == toggles ? Book.STANDARD : toggles))
			{
				if (ctx.expanded.contains(next) && (k >= FIRST_PENDING || next != current))
				{
					change(from, from.node, WALKED, next.ordinal(), change);
				}
			}
		}
	}

	private void expandFairyRing(Label from, int k)
	{
		TransportOptions options = ctx.options[from.b];
		TransportOptions.Teleport entry = options.fairyEntries.get(from.node);
		if (entry == null)
		{
			return;
		}
		for (TransportOptions.Teleport landing : options.fairyLandings)
		{
			if (landing.node != from.node && !ctx.forbidden(landing.node) && !excluded.contains(Route.fairyKey(landing.row)))
			{
				int half = Math.max(entry.halfTicks, landing.halfTicks) - (ctx.isLastFairyRing(landing.row) ? 2 * landing.row.getMenuTicks() : 0);
				transport(from, landing.node, from.c, k, half, Leg.Kind.FAIRY_RING, entry, landing);
			}
		}
	}

	/**
	 * The only way into the banked state. Withdrawals are charged on the edges that use them, since the withdraw list
	 * is only known edge by edge.
	 */
	private void expandBank(Label from, int k)
	{
		if (from.b == PlanContext.NOT_BANKED && ctx.options[PlanContext.BANKED] != null && ctx.isUsableBank(from.node))
		{
			int half = ctx.bankStopHalfTicks;
			offer(from, from.node, PlanContext.BANKED, from.c, k, from.t, from.leg, half, half, Leg.Kind.BANK, null, null, from.spent);
			takeGateItems(from, k, half);
		}
	}

	/**
	 * A web's knife or sword, or a stage's gear, is used a few legs after the bank, where a stop that took nothing yet
	 * only walks to bank-item uses; so a second stop takes them at once.
	 */
	private void takeGateItems(Label from, int k, int bankHalfTicks)
	{
		int[] withdrawn = sortedUnion(sortedUnion(from.withdrawn, ctx.gates(PlanContext.BANKED).storedGateItems()), ctx.stageWithdraw());
		if (withdrawn.length > from.withdrawn.length)
		{
			int half = bankHalfTicks + PlanContext.WITHDRAW_HALF_TICKS * (withdrawn.length - from.withdrawn.length);
			offer(from, from.node, PlanContext.BANKED, from.c, k, from.t, from.leg, half, half, Leg.Kind.BANK, null, null, from.spent, withdrawn);
		}
	}

	private void transport(Label from, int node, int c, int k, int half, Leg.Kind kind, TransportOptions.Teleport tele, Object second)
	{
		int t = 1;
		if (onlyFirst != null && from.t == 0)
		{
			String key = kind == Leg.Kind.FAIRY_RING ? Route.fairyKey(((TransportOptions.Teleport) second).row) : Route.teleportKey(tele.row);
			boolean first = key.equals(onlyFirst);
			if (Route.WALK.equals(onlyFirst) || !first && node != ctx.pohNode)
			{
				return;
			}
			t = first ? 1 : 0;
		}
		int[] spent = spend(from.spent, tele.res, tele.amounts, from.b);
		int[] withdrawn = sortedUnion(from.withdrawn, tele.withdraw);
		if (second instanceof TransportOptions.Change)
		{
			TransportOptions.Change swap = (TransportOptions.Change) second;
			spent = spend(spent, swap.res, swap.amounts, from.b);
			withdrawn = sortedUnion(withdrawn, swap.withdraw);
		}
		else if (second instanceof TransportOptions.Teleport)
		{
			TransportOptions.Teleport landing = (TransportOptions.Teleport) second;
			spent = spend(spent, landing.res, landing.amounts, from.b);
			withdrawn = sortedUnion(withdrawn, landing.withdraw);
		}
		if (spent != null && !pointlessAfterBank(from, withdrawn))
		{
			int total = half + PlanContext.WITHDRAW_HALF_TICKS * (withdrawn.length - from.withdrawn.length);
			offer(from, node, from.b, c, k, t, from.leg, total, total, kind, tele, second, spent, withdrawn);
		}
	}

	private void change(Label from, int node, int c, int k, TransportOptions.Change change)
	{
		int[] spent = spend(from.spent, change.res, change.amounts, from.b);
		int[] withdrawn = sortedUnion(from.withdrawn, change.withdraw);
		if (spent != null && !pointlessAfterBank(from, withdrawn))
		{
			int total = change.halfTicks + PlanContext.WITHDRAW_HALF_TICKS * (withdrawn.length - from.withdrawn.length);
			int penalty = change.capeUse ? PlanContext.CAPE_USE_PENALTY_HALF_TICKS : 0;
			offer(from, node, from.b, c, k, from.t, from.leg, total, total + penalty, Leg.Kind.SPELLBOOK_CHANGE,
				change, null, spent, withdrawn);
		}
	}

	/** The same route without the bank stop would be faster. */
	private boolean pointlessAfterBank(Label from, int[] withdrawn)
	{
		return from.b == PlanContext.BANKED && withdrawn.length == 0 && bankStopsArePruned();
	}

	private boolean bankStopsArePruned()
	{
		return ctx.arrivesWithoutBank() && !ctx.in.isAtOpenBank();
	}

	private static int[] sortedUnion(int[] a, int[] b)
	{
		if (b.length == 0)
		{
			return a;
		}
		if (a.length == 0)
		{
			return b;
		}
		int[] out = new int[a.length + b.length];
		int i = 0;
		int j = 0;
		int n = 0;
		while (i < a.length || j < b.length)
		{
			int next = j >= b.length || i < a.length && a[i] <= b[j] ? a[i] : b[j];
			if (i < a.length && a[i] == next)
			{
				i++;
			}
			if (j < b.length && b[j] == next)
			{
				j++;
			}
			out[n++] = next;
		}
		return n == out.length ? out : Arrays.copyOf(out, n);
	}

	/**
	 * Withdrawing later costs the same as now, except after a bank stop that took nothing: that one only walks to
	 * bank-item uses, so it can't stand in for a stop that took something.
	 */
	private boolean dominates(int bankState, int aRank, int aHalf, int[] aSpent, int[] aWithdrawn, int bRank, int bHalf, int[] bSpent,
		int[] bWithdrawn)
	{
		if (bankState == PlanContext.BANKED && aWithdrawn.length == 0 && bWithdrawn.length > 0 && bankStopsArePruned())
		{
			return false;
		}
		int withdrawLater = PlanContext.WITHDRAW_HALF_TICKS * countMissing(aWithdrawn, bWithdrawn);
		return aRank + withdrawLater <= bRank && aHalf + withdrawLater <= bHalf && spendsNoMore(aSpent, bSpent);
	}

	private static int countMissing(int[] sortedHave, int[] sortedWanted)
	{
		int count = 0;
		int i = 0;
		for (int id : sortedWanted)
		{
			while (i < sortedHave.length && sortedHave[i] < id)
			{
				i++;
			}
			if (i >= sortedHave.length || sortedHave[i] != id)
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * Returns null when dominated. A lower change category also dominates a higher one at the same place, book and bank
	 * state: it can do whatever the higher one goes on to do, and never needs the margin.
	 */
	private Label offer(Label from, int node, int b, int c, int k, int t, int leg, int addHalf, int addRank, Leg.Kind kind,
		Object ref, Object ref2, int[] spent)
	{
		return offer(from, node, b, c, k, t, leg, addHalf, addRank, kind, ref, ref2, spent, from == null ? NOTHING : from.withdrawn);
	}

	private Label offer(Label from, int node, int b, int c, int k, int t, int leg, int addHalf, int addRank, Leg.Kind kind,
		Object ref, Object ref2, int[] spent, int[] withdrawn)
	{
		int half = (from == null ? 0 : from.half) + addHalf;
		int rank = (from == null ? 0 : from.rank) + addRank;
		int bound = bounds[leg] == null ? 0 : bounds[leg].of(node);
		if (bound >= LowerBound.UNREACHABLE)
		{
			return null;
		}
		for (int lower = 0; lower < c; lower++)
		{
			if (dominatedAt(stateIndex(leg, node, b, lower, k, t) * MAX_LABELS, b, rank, half, spent, withdrawn))
			{
				return null;
			}
		}
		for (int higher = c + 1; higher < CATEGORIES; higher++)
		{
			killDominated(stateIndex(leg, node, b, higher, k, t) * MAX_LABELS, b, rank, half, spent, withdrawn);
		}
		int base = stateIndex(leg, node, b, c, k, t) * MAX_LABELS;
		int free = -1;
		int worst = -1;
		for (int i = base; i < base + MAX_LABELS; i++)
		{
			Label old = slots[i];
			if (old == null || old.dead)
			{
				free = free < 0 ? i : free;
				continue;
			}
			if (dominates(b, old.rank, old.half, old.spent, old.withdrawn, rank, half, spent, withdrawn))
			{
				return null;
			}
			if (dominates(b, rank, half, spent, withdrawn, old.rank, old.half, old.spent, old.withdrawn))
			{
				old.dead = true;
				slots[i] = null;
				free = free < 0 ? i : free;
			}
			else if (worst < 0 || old.rank > slots[worst].rank)
			{
				worst = i;
			}
		}
		if (free < 0)
		{
			if (slots[worst].rank <= rank)
			{
				return null;
			}
			slots[worst].dead = true;
			free = worst;
		}
		Label label = new Label();
		label.leg = leg;
		label.node = node;
		label.b = b;
		label.c = c;
		label.k = k;
		label.t = t;
		label.half = half;
		label.rank = rank;
		label.f = rank + bound;
		label.spent = spent;
		label.withdrawn = withdrawn;
		label.parent = from;
		label.kind = kind;
		label.ref = ref;
		label.ref2 = ref2;
		label.edgeHalf = addHalf;
		slots[free] = label;
		queue.add(label);
		labels++;
		return label;
	}

	private boolean dominatedAt(int base, int b, int rank, int half, int[] spent, int[] withdrawn)
	{
		for (int i = base; i < base + MAX_LABELS; i++)
		{
			Label old = slots[i];
			if (old != null && !old.dead && dominates(b, old.rank, old.half, old.spent, old.withdrawn, rank, half, spent, withdrawn))
			{
				return true;
			}
		}
		return false;
	}

	private void killDominated(int base, int b, int rank, int half, int[] spent, int[] withdrawn)
	{
		for (int i = base; i < base + MAX_LABELS; i++)
		{
			Label old = slots[i];
			if (old != null && !old.dead && dominates(b, rank, half, spent, withdrawn, old.rank, old.half, old.spent, old.withdrawn))
			{
				old.dead = true;
				slots[i] = null;
			}
		}
	}

	private int stateIndex(int leg, int node, int b, int c, int k, int t)
	{
		return ((((leg * nodes + node) * 2 + b) * CATEGORIES + c) * BOOKS + k) * 2 + t;
	}

	/**
	 * Null when the bank state hasn't enough. A resource the player has plenty of (a stack of 1,000 runes) is never
	 * tracked, so it doesn't split labels.
	 */
	private int[] spend(int[] spent, int[] res, int[] amounts, int b)
	{
		if (spent == null || res.length == 0)
		{
			return spent;
		}
		int[] merged = spent;
		for (int i = 0; i < res.length; i++)
		{
			if (!ctx.resources.tracked(res[i]))
			{
				continue;
			}
			merged = add(merged, res[i], amounts[i]);
			if (count(merged, res[i]) > ctx.resources.available(res[i], b))
			{
				return null;
			}
		}
		return merged;
	}

	/** {@code pairs} is flat (resource, units) pairs, sorted by resource. */
	private static int[] add(int[] pairs, int resource, int units)
	{
		for (int i = 0; i < pairs.length; i += 2)
		{
			if (pairs[i] == resource)
			{
				int[] copy = pairs.clone();
				copy[i + 1] += units;
				return copy;
			}
		}
		int[] copy = new int[pairs.length + 2];
		int at = 0;
		int i = 0;
		while (i < pairs.length && pairs[i] < resource)
		{
			copy[at++] = pairs[i++];
			copy[at++] = pairs[i++];
		}
		copy[at++] = resource;
		copy[at++] = units;
		while (i < pairs.length)
		{
			copy[at++] = pairs[i++];
		}
		return copy;
	}

	static int count(int[] pairs, int resource)
	{
		for (int i = 0; i < pairs.length; i += 2)
		{
			if (pairs[i] == resource)
			{
				return pairs[i + 1];
			}
		}
		return 0;
	}

	private int capeUses(int[] spent)
	{
		return ctx.resources.cape < 0 ? 0 : count(spent, ctx.resources.cape);
	}

	private static boolean spendsNoMore(int[] a, int[] b)
	{
		for (int i = 0; i < a.length; i += 2)
		{
			if (a[i + 1] > count(b, a[i]))
			{
				return false;
			}
		}
		return true;
	}

	private int effectiveBook(int k, int half)
	{
		return k >= FIRST_PENDING && half > revertHalfTicks ? LUNAR : k;
	}

	private static int pendingIndex(Book book)
	{
		return book == Book.ARCEUUS ? FIRST_PENDING + 2 : FIRST_PENDING + book.ordinal();
	}

	private static Book pendingBook(int k)
	{
		return k == FIRST_PENDING + 2 ? Book.ARCEUUS : Book.values()[k - FIRST_PENDING];
	}

	/** A pending swap reverts to Lunar by itself, so a route that leaves it pending ends on Lunar. */
	static Book endBook(int k)
	{
		return k >= FIRST_PENDING ? Book.LUNAR : Book.values()[k];
	}

	static Book bookOf(int k)
	{
		return k >= FIRST_PENDING ? pendingBook(k) : Book.values()[k];
	}

	private boolean isTarget(int leg, int node)
	{
		return targets[leg][node];
	}

	static final class Label
	{
		int leg;
		int node;
		int b;
		int c;
		int k;
		int t;
		int half;
		int rank;
		int f;
		int[] spent;
		/** Sorted; each id is charged its withdraw ticks once. */
		int[] withdrawn = NOTHING;
		Label parent;
		Leg.Kind kind;
		Object ref;
		Object ref2;
		int edgeHalf;
		Book endBook;
		boolean dead;

		RowAvailability.Confidence confidence()
		{
			RowAvailability.Confidence worst = RowAvailability.Confidence.SURE;
			for (Label l = this; l != null; l = l.parent)
			{
				RowAvailability.Confidence c = l.ref instanceof TransportOptions.Teleport ? ((TransportOptions.Teleport) l.ref).confidence
					: l.ref instanceof TransportOptions.Change ? ((TransportOptions.Change) l.ref).confidence : null;
				if (c != null && c.ordinal() > worst.ordinal())
				{
					worst = c;
				}
			}
			return worst;
		}

		List<Label> chain()
		{
			List<Label> chain = new ArrayList<>();
			for (Label l = this; l != null; l = l.parent)
			{
				chain.add(0, l);
			}
			return chain;
		}
	}
}

package com.cluehelper.route;

import com.cluehelper.player.Book;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.SpellbookChange;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
public class Leg
{
	public enum Kind
	{
		WALK,
		WILDERNESS_EXIT,
		TELEPORT,
		SWAP_TELEPORT,
		FAIRY_RING,
		SPELLBOOK_CHANGE,
		BANK
	}

	Kind kind;
	WorldPoint from;
	WorldPoint to;
	int halfTicks;
	/** The teleport's row, or a fairy ring's entry ring; null for walks, exits, spellbook changes and bank stops. */
	CatalogRow row;
	CatalogRow landing;
	SpellbookChange change;
	/** For a pending Spellbook Swap, the temporary book. */
	Book bookAfter;

	private Leg(Kind kind, WorldPoint from, WorldPoint to, int halfTicks, CatalogRow row, CatalogRow landing, SpellbookChange change,
		Book bookAfter)
	{
		this.kind = kind;
		this.from = from;
		this.to = to;
		this.halfTicks = halfTicks;
		this.row = row;
		this.landing = landing;
		this.change = change;
		this.bookAfter = bookAfter;
	}

	public static Leg walk(WorldPoint from, WorldPoint to, int halfTicks, Book book)
	{
		return new Leg(Kind.WALK, from, to, halfTicks, null, null, null, book);
	}

	/** Due south until out of the Wilderness, a tile per half-tick. */
	public static Leg wildernessExit(WorldPoint from, int halfTicks, Book book)
	{
		return new Leg(Kind.WILDERNESS_EXIT, from, new WorldPoint(from.getX(), from.getY() - halfTicks, from.getPlane()), halfTicks, null, null, null, book);
	}

	public static Leg teleport(WorldPoint from, CatalogRow row, int halfTicks, Book book)
	{
		return new Leg(Kind.TELEPORT, from, row.getDestination(), halfTicks, row, null, null, book);
	}

	/** A Spellbook Swap cast, then the teleport it enables. */
	public static Leg swapTeleport(WorldPoint from, CatalogRow row, SpellbookChange swap, int halfTicks, Book book)
	{
		return new Leg(Kind.SWAP_TELEPORT, from, row.getDestination(), halfTicks, row, null, swap, book);
	}

	public static Leg fairyRing(WorldPoint from, CatalogRow entry, CatalogRow landing, int halfTicks, Book book)
	{
		return new Leg(Kind.FAIRY_RING, from, landing.getDestination(), halfTicks, entry, landing, null, book);
	}

	public static Leg spellbookChange(WorldPoint at, SpellbookChange change, int halfTicks, Book bookAfter)
	{
		return new Leg(Kind.SPELLBOOK_CHANGE, at, at, halfTicks, null, null, change, bookAfter);
	}

	public static Leg bank(WorldPoint at, int halfTicks, Book book)
	{
		return new Leg(Kind.BANK, at, at, halfTicks, null, null, null, book);
	}

	public int getTicks()
	{
		return (halfTicks + 1) / 2;
	}

	public boolean isTransport()
	{
		return kind == Kind.TELEPORT || kind == Kind.SWAP_TELEPORT || kind == Kind.FAIRY_RING;
	}

	public String describe()
	{
		switch (kind)
		{
			case WALK:
				return "walk " + getTicks();
			case WILDERNESS_EXIT:
				return "walk south " + getTicks();
			case TELEPORT:
				return row.getName();
			case SWAP_TELEPORT:
				return "Spellbook Swap · " + row.getName();
			case FAIRY_RING:
				return landing.getName();
			case SPELLBOOK_CHANGE:
				return change.getName() + " → " + bookAfter;
			case BANK:
				return "bank";
			default:
				throw new IllegalArgumentException("unhandled leg kind " + kind);
		}
	}
}

package com.cluehelper.route;

import lombok.Value;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/** The loaded scene's collision flags as captured, and the closed doors on it a walk may open at a cost. */
@Value
public class LoadedScene
{
	private static final int FULL = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
	private static final int N = CollisionDataFlag.BLOCK_MOVEMENT_NORTH;
	private static final int E = CollisionDataFlag.BLOCK_MOVEMENT_EAST;
	private static final int S = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
	private static final int W = CollisionDataFlag.BLOCK_MOVEMENT_WEST;
	private static final int NE = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST;
	private static final int NW = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST;
	private static final int SE = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST;
	private static final int SW = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST;
	private static final int BORDER_LOW = 1;
	private static final int BORDER_HIGH = 5;
	/** Opening a door on the way: the click and the stop it costs, in tiles of running. */
	private static final int DOOR_TILES = 3;
	private static final int[] FROM_SIDES = {W, E, S, N, W | S, E | S, W | N, E | N};
	private static final int[] TO_SIDES = {E, W, N, S, E | N, W | N, E | S, W | S};

	int baseX;
	int baseY;
	int sizeX;
	int sizeY;
	/** [plane][x][y]; a null plane has no data. */
	int[][][] flags;
	/** [plane][x][y]: the sides (wall flags) of each tile that a closed door opens through; null when none are known. */
	int[][][] doorSides;

	public LoadedScene(int baseX, int baseY, int sizeX, int sizeY, int[][][] flags)
	{
		this(baseX, baseY, sizeX, sizeY, flags, null);
	}

	public LoadedScene(int baseX, int baseY, int sizeX, int sizeY, int[][][] flags, int[][][] doorSides)
	{
		this.baseX = baseX;
		this.baseY = baseY;
		this.sizeX = sizeX;
		this.sizeY = sizeY;
		this.flags = flags;
		this.doorSides = doorSides;
	}

	/** Client thread only. Null for an instanced scene or one without collision data. */
	public static LoadedScene capture(WorldView view)
	{
		return view == null || view.isInstance() ? null : captureLoaded(view);
	}

	/** Client thread only. In an instance its tiles are the instance's own and match nothing in the walk table. */
	public static LoadedScene captureLoaded(WorldView view)
	{
		CollisionData[] maps = view == null ? null : view.getCollisionMaps();
		if (maps == null)
		{
			return null;
		}
		int[][][] flags = new int[maps.length][][];
		for (int plane = 0; plane < maps.length; plane++)
		{
			if (maps[plane] != null)
			{
				int[][] source = maps[plane].getFlags();
				flags[plane] = new int[source.length][];
				for (int x = 0; x < source.length; x++)
				{
					flags[plane][x] = source[x].clone();
				}
			}
		}
		return new LoadedScene(view.getBaseX(), view.getBaseY(), view.getSizeX(), view.getSizeY(), flags);
	}

	/** The client blocks the scene's first row and last five. */
	public boolean contains(WorldPoint tile)
	{
		return contains(tile.getX(), tile.getY(), tile.getPlane());
	}

	boolean contains(int worldX, int worldY, int plane)
	{
		int x = worldX - baseX;
		int y = worldY - baseY;
		return x >= BORDER_LOW && y >= BORDER_LOW && x < sizeX - BORDER_HIGH && y < sizeY - BORDER_HIGH
			&& plane >= 0 && plane < flags.length && flags[plane] != null;
	}

	/** The game lets a player step from {@code from} to {@code to}, its neighbour; both in the scene. */
	public boolean canStep(WorldPoint from, WorldPoint to)
	{
		int dx = to.getX() - from.getX();
		int dy = to.getY() - from.getY();
		for (int d = 0; d < Directions.DX.length; d++)
		{
			if (Directions.DX[d] == dx && Directions.DY[d] == dy)
			{
				return canMove(from.getX() - baseX, from.getY() - baseY, from.getPlane(), d);
			}
		}
		throw new IllegalArgumentException(to + " is no neighbour of " + from);
	}

	/** Scene coordinates, from here on. The game's movement rule; {@code d} indexes {@link Directions}. */
	boolean canMove(int x, int y, int plane, int d)
	{
		int[][] f = flags[plane];
		switch (d)
		{
			case 0:
				return free(f, x - 1, y, E);
			case 1:
				return free(f, x + 1, y, W);
			case 2:
				return free(f, x, y - 1, N);
			case 3:
				return free(f, x, y + 1, S);
			case 4:
				return free(f, x - 1, y - 1, N | E | NE) && free(f, x - 1, y, E) && free(f, x, y - 1, N);
			case 5:
				return free(f, x + 1, y - 1, N | W | NW) && free(f, x + 1, y, W) && free(f, x, y - 1, N);
			case 6:
				return free(f, x - 1, y + 1, S | E | SE) && free(f, x - 1, y, E) && free(f, x, y + 1, S);
			default:
				return free(f, x + 1, y + 1, S | W | SW) && free(f, x + 1, y, W) && free(f, x, y + 1, S);
		}
	}

	/** Tiles a step from ({@code x}, {@code y}) in direction {@code d} costs: one, plus a door's opening. */
	int stepCost(int plane, int x, int y, int d)
	{
		int[][] sides = doorSides == null ? null : doorSides[plane];
		if (sides == null)
		{
			return 1;
		}
		boolean throughDoor = (sides[x][y] & FROM_SIDES[d]) != 0 || (sides[x + Directions.DX[d]][y + Directions.DY[d]] & TO_SIDES[d]) != 0;
		return throughDoor ? 1 + DOOR_TILES : 1;
	}

	boolean isBlocked(int x, int y, int plane)
	{
		return (flags[plane][x][y] & FULL) != 0;
	}

	/** A wall stands between the tile and its straight neighbour {@code dx}, {@code dy}. */
	boolean isWallBetween(int x, int y, int plane, int dx, int dy)
	{
		int fromWall = dx > 0 ? E : dx < 0 ? W : dy > 0 ? N : S;
		int toWall = dx > 0 ? W : dx < 0 ? E : dy > 0 ? S : N;
		return (flags[plane][x][y] & fromWall) != 0 || (flags[plane][x + dx][y + dy] & toWall) != 0;
	}

	private static boolean free(int[][] f, int x, int y, int sides)
	{
		return x >= 0 && y >= 0 && x < f.length && y < f[x].length && (f[x][y] & (FULL | sides)) == 0;
	}
}

package com.cluehelper.route;

import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

/**
 * A* lower bounds in half-ticks. They must never overestimate and must stay consistent over every edge kind, or the
 * label search stops being exact.
 */
final class LowerBound
{
	static final int UNREACHABLE = Integer.MAX_VALUE / 4;

	private final int[] bound;

	LowerBound(PlanContext ctx, int[] targets)
	{
		int[] walk = walkToTargets(ctx, targets);
		int cheapest = UNREACHABLE;
		for (TransportOptions options : ctx.options)
		{
			if (options == null)
			{
				continue;
			}
			for (TransportOptions.Teleport tele : options.teleports)
			{
				cheapest = Math.min(cheapest, tele.halfTicks + walk[tele.node]);
			}
			for (List<TransportOptions.Teleport> here : options.located.values())
			{
				for (TransportOptions.Teleport tele : here)
				{
					cheapest = Math.min(cheapest, tele.halfTicks + walk[tele.node]);
				}
			}
			int fairy = options.fairyEntries.values().stream().mapToInt(e -> e.halfTicks).min().orElse(UNREACHABLE);
			for (TransportOptions.Teleport landing : options.fairyLandings)
			{
				cheapest = Math.min(cheapest, fairy + walk[landing.node]);
			}
		}
		bound = walk;
		for (int node = 0; node < bound.length; node++)
		{
			bound[node] = Math.min(bound[node], cheapest);
		}
		bound[ctx.start] = 0;
		bound[ctx.goal] = 0;
	}

	int of(int node)
	{
		return bound[node];
	}

	private static int[] walkToTargets(PlanContext ctx, int[] targets)
	{
		WalkTable table = ctx.table;
		int[] walk = new int[ctx.nodeCount()];
		Arrays.fill(walk, UNREACHABLE);
		PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[1] - b[1]);
		for (int target : targets)
		{
			walk[target] = 0;
			queue.add(new int[]{target, 0});
		}
		while (!queue.isEmpty())
		{
			int[] head = queue.poll();
			int node = head[0];
			if (head[1] != walk[node] || !ctx.isTableNode(node))
			{
				continue;
			}
			for (int i = table.reverseFrom(node); i < table.reverseEnd(node); i++)
			{
				int entry = table.reverseEntry(i);
				int from = table.entryFrom(entry);
				int cost = head[1] + table.entryFull(entry);
				if (cost < walk[from])
				{
					walk[from] = cost;
					queue.add(new int[]{from, cost});
				}
			}
		}
		return walk;
	}
}

package com.cluehelper.route;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class NoTeleportAreas
{
	public static final NoTeleportAreas NONE = new NoTeleportAreas(List.of());
	private static final String RESOURCE = "no-teleport.tsv";
	private static final int ANY_PLANE = -1;

	private final List<int[]> boxes;

	private NoTeleportAreas(List<int[]> boxes)
	{
		this.boxes = boxes;
	}

	public static NoTeleportAreas load() throws IOException
	{
		List<int[]> boxes = new ArrayList<>();
		try (InputStream in = NoTeleportAreas.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("missing resource " + RESOURCE);
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			boolean header = true;
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				if (header)
				{
					header = false;
					continue;
				}
				String[] c = line.split("\t");
				boxes.add(new int[]{Integer.parseInt(c[1]), Integer.parseInt(c[2]), Integer.parseInt(c[3]), Integer.parseInt(c[4]),
					Integer.parseInt(c[5])});
			}
		}
		return new NoTeleportAreas(List.copyOf(boxes));
	}

	public boolean contains(WorldPoint tile)
	{
		for (int[] box : boxes)
		{
			if (tile.getX() >= box[0] && tile.getY() >= box[1] && tile.getX() <= box[2] && tile.getY() <= box[3]
				&& (box[4] == ANY_PLANE || box[4] == tile.getPlane()))
			{
				return true;
			}
		}
		return false;
	}
}

package com.cluehelper.route;

import com.cluehelper.player.PositionRules;
import net.runelite.api.coords.WorldPoint;

public enum OriginClass
{
	WILD0(0),
	WILD20(20),
	WILD30(30),
	/** No teleport, and no spellbook change either, since no teleport could follow. */
	WILD_DEEP(Integer.MAX_VALUE),
	/** Grouping (minigame) teleports don't work from inside a house. */
	POH(0),
	NO_TELEPORT(Integer.MAX_VALUE);

	/** Walking due south to this surface y reaches the class. */
	static final int EXIT_WILD30_Y = 3759;
	static final int EXIT_WILD20_Y = 3679;
	/** Minigame rows work only outside the Wilderness, so level 0 needs an exit too. */
	static final int EXIT_WILD0_Y = 3524;

	private final int highestLevel;

	OriginClass(int highestLevel)
	{
		this.highestLevel = highestLevel;
	}

	public static OriginClass of(WorldPoint tile, NoTeleportAreas noTeleport)
	{
		if (PositionRules.isInPoh(tile))
		{
			return POH;
		}
		if (noTeleport.contains(tile))
		{
			return NO_TELEPORT;
		}
		int level = PositionRules.wildernessLevel(tile);
		return level <= 0 ? WILD0 : level <= 20 ? WILD20 : level <= 30 ? WILD30 : WILD_DEEP;
	}

	public boolean allowsTeleports()
	{
		return this != WILD_DEEP && this != NO_TELEPORT;
	}

	public boolean allows(int maxWildernessLevel)
	{
		return allowsTeleports() && highestLevel <= maxWildernessLevel;
	}

	public boolean isWilderness()
	{
		return this == WILD20 || this == WILD30 || this == WILD_DEEP;
	}
}

