import java.util.Set;
import lombok.Builder;
import lombok.Value;

/** Snapshot data only, never the client, so a plan runs on any thread. */
@Value
@Builder(toBuilder = true)
public class PlanInput
{
	public static final int NO_REVERT_WINDOW = -1;

	Step step;
	PlayerSnapshot player;
	/** Null when no bank counts (UIM, useBank off, bank never seen). */
	PlayerSnapshot banked;
	boolean pinPending;
	boolean atOpenBank;
	@Builder.Default
	RequiredItems required = RequiredItems.NONE;
	AvailabilityEngine engine;
	long nowMinutes;
	Catalog catalog;
	WalkTable table;
	@Builder.Default
	NoTeleportAreas noTeleport = NoTeleportAreas.NONE;
	PlanStart start;
	PlannerSettings settings;
	/** Ticks left of a pending Spellbook Swap's free cast. */
	@Builder.Default
	int revertTicksLeft = NO_REVERT_WINDOW;
	/** Row names of spellbook changes and teleports the game refused this session; never offered. */
	@Builder.Default
	Set<String> refusedChanges = Set.of();
	boolean foreignHouseStart;
	/** The followed route's first transport key; null when no route of this step is followed. */
	String followedFirstTransport;
}

package com.cluehelper.route;

import com.cluehelper.player.Charge;
import com.cluehelper.player.Container;
import com.cluehelper.player.PlayerSnapshot;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** What a route spends: items, charges, cooldowns and cape uses, each with the units available before and after a bank stop. */
final class PlanResources
{
	/** Assumed: no route uses one resource more often than this. */
	private static final int MOST_USES_PER_ROUTE = 8;

	private final Map<String, Integer> ids = new LinkedHashMap<>();
	private final List<int[]> available = new ArrayList<>();
	private final List<Integer> mostPerUse = new ArrayList<>();
	int cape = -1;

	int item(int itemId, PlayerSnapshot player, int bankState)
	{
		int have = 0;
		for (Container container : Container.values())
		{
			have += player.count(container, itemId);
		}
		return set("item:" + itemId, bankState, have);
	}

	int charge(int itemId, PlayerSnapshot player, int bankState)
	{
		Charge charge = player.getCharges().get(itemId);
		int perItem = charge == null ? 1 : Math.max(0, charge.getCharges());
		int held = player.carried(itemId) + player.stored(itemId);
		return set("charge:" + itemId, bankState, Math.max(1, held) * perItem);
	}

	int once(String key, int bankState)
	{
		return set(key, bankState, 1);
	}

	int capeUses(int left, int bankState)
	{
		cape = set("cape", bankState, left);
		return cape;
	}

	int available(int resource, int bankState)
	{
		return available.get(resource)[bankState];
	}

	void used(int resource, int units)
	{
		mostPerUse.set(resource, Math.max(mostPerUse.get(resource), units));
	}

	boolean tracked(int resource)
	{
		int most = Math.max(available.get(resource)[0], available.get(resource)[1]);
		return resource == cape || most < MOST_USES_PER_ROUTE * mostPerUse.get(resource);
	}

	String name(int resource)
	{
		return new ArrayList<>(ids.keySet()).get(resource);
	}

	private int set(String key, int bankState, int units)
	{
		Integer id = ids.get(key);
		if (id == null)
		{
			id = ids.size();
			ids.put(key, id);
			available.add(new int[2]);
			mostPerUse.add(0);
		}
		available.get(id)[bankState] = Math.max(available.get(id)[bankState], units);
		return id;
	}
}

package com.cluehelper.route;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class PlanStart
{
	public enum Kind
	{
		SCENE,
		AT_NODE,
		TELEPORT_ONLY
	}

	Kind kind;
	WorldPoint tile;
	/** The walk from the tile; also kept for a teleport-only start, where it reaches no node. */
	WalkCosts walk;
	int node;

	public static PlanStart scene(WorldPoint tile, WalkCosts walk)
	{
		return new PlanStart(Kind.SCENE, tile, walk, WalkTable.NO_NODE);
	}

	public static PlanStart atNode(WalkTable table, int node)
	{
		return new PlanStart(Kind.AT_NODE, table.tile(node), null, node);
	}

	public static PlanStart teleportOnly(WorldPoint tile)
	{
		return teleportOnly(tile, null);
	}

	public static PlanStart teleportOnly(WorldPoint tile, WalkCosts walk)
	{
		return new PlanStart(Kind.TELEPORT_ONLY, tile, walk, WalkTable.NO_NODE);
	}
}

package com.cluehelper.route;

import com.cluehelper.player.PositionRules;
import com.cluehelper.step.ClueTypes;
import com.cluehelper.step.Stage;
import com.cluehelper.step.Step;
import com.cluehelper.step.TargetKind;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.api.coords.WorldPoint;

/** Pure, so it runs on the executor with snapshot data only. */
public final class Planner
{
	/** A route with a bank stop or a walked change must beat its reference by this margin. */
	private static final int MARGIN_MIN_HALF_TICKS = 10;
	private static final int MARGIN_PERCENT = 10;
	private static final int REGION_SIZE = 64;
	private static final int ALTERNATIVE_SLACK_HALF_TICKS = 60;
	/** Catalog landings of one place spread 0–2 tiles. */
	private static final int SAME_LANDING_TILES = 2;
	/** Rejected repeats and round trips count against this too. */
	private static final int MOST_ALTERNATIVE_SEARCHES = 12;

	private Planner()
	{
	}

	public static Plan plan(PlanInput in)
	{
		return plan(in, true);
	}

	/**
	 * Without the alternatives, whose searches take most of a plan's time; the followed route's way is planned again
	 * instead, bounded by the best route plus the commit margin.
	 */
	public static Plan withoutAlternatives(PlanInput in)
	{
		return plan(in, false);
	}

	private static Plan plan(PlanInput in, boolean withAlternatives)
	{
		long started = System.nanoTime();
		Step step = in.getStep();
		if (step != null && step.getData().isHidden())
		{
			return Plan.builder().stepKey(step.getKey()).alternatives(List.of()).candidates(List.of()).probeTicks(Map.of())
				.note("not guided: a Leagues step").build();
		}
		if (step == null || step.getTargets() == null || step.getTargets().isEmpty())
		{
			return Plan.builder().stepKey(step == null ? null : step.getKey()).alternatives(List.of()).candidates(List.of())
				.probeTicks(Map.of()).note(step == null ? "no step" : ClueTypes.HOT_COLD.equals(step.getType())
					? "choosing where to feel" : "no target tile for this step yet").build();
		}
		PlanContext ctx = new PlanContext(in);
		if (ctx.stageVerdicts().stream().anyMatch(verdict -> !verdict.getMissing().isEmpty())
			|| ctx.required.getMissing().stream().anyMatch(RequiredItems.Need::isBlocksRoute))
		{
			return Plan.builder().stepKey(step.getKey()).alternatives(List.of()).candidates(List.of()).probeTicks(Map.of())
				.requirementNotes(requirementNotes(ctx)).build();
		}
		List<List<int[]>> orders = legOrders(ctx, step);
		ctx.freezeNodes();
		long contextNanos = System.nanoTime() - started;
		int area = step.getKind() == TargetKind.AREA ? areaHalfTicks(step) : 0;
		boolean probes = step.getKind() == TargetKind.PROBES;
		Searches searches = new Searches(ctx, area, probes);

		LabelSearch first = searches.bestOrder(orders, Set.of(), Integer.MAX_VALUE);
		Plan.PlanBuilder plan = Plan.builder().stepKey(step.getKey());
		Picks picks = new Picks(ctx, first);
		if (picks.best == null && ctx.avoidsWilderness && !probes)
		{
			Plan throughWilderness = plan(wildernessAllowed(in), withAlternatives);
			if (throughWilderness.getBest() != null)
			{
				return throughWilderness.toBuilder().note("only reachable through the Wilderness")
					.searchNanos(System.nanoTime() - started).labels(searches.labels + throughWilderness.getLabels())
					.searches(searches.count + throughWilderness.getSearches()).build();
			}
		}
		plan.best(picks.best).direct(picks.direct != picks.best ? picks.direct : null)
			.sameBook(picks.best != null && picks.best.isChanged() ? picks.sameBook : null)
			.fasterUnqualified(picks.fasterUnqualified)
			.candidates(picks.candidates);
		Map<WorldPoint, Integer> probeRanks = new LinkedHashMap<>();
		plan.probeTicks(probes ? probeTicks(ctx, first, probeRanks) : Map.of()).probeRanks(probeRanks);
		plan.alternatives(probes || orders.size() > 1 || !withAlternatives ? List.of() : alternatives(in, searches, orders, picks));
		plan.followed(probes || orders.size() > 1 ? null : followed(in, searches, orders, picks));
		plan.note(probes ? null : picks.best == null ? noRouteNote(ctx, orders) : ctx.onlyInWilderness ? "Wilderness target" : null);
		plan.requirementNotes(requirementNotes(ctx));
		return plan.searchNanos(System.nanoTime() - started).contextNanos(contextNanos).labels(searches.labels)
			.searches(searches.count).build();
	}

	/** Avoiding the Wilderness never hides the only way to a step outside it, such as the King Black Dragon's lair. */
	private static PlanInput wildernessAllowed(PlanInput in)
	{
		return in.toBuilder().settings(in.getSettings().toBuilder().avoidWilderness(false).build()).build();
	}

	private static List<List<int[]>> legOrders(PlanContext ctx, Step step)
	{
		if (!step.getStages().isEmpty())
		{
			return stageOrders(ctx, step);
		}
		List<int[]> nodes = step.getTargets().stream().map(tile -> new int[]{ctx.nodeAt(tile)}).collect(Collectors.toList());
		if (step.getKind() != TargetKind.SEQUENCE)
		{
			return List.of(List.of(nodes.stream().mapToInt(n -> n[0]).toArray()));
		}
		if (!ClueTypes.THREE_STEP.equals(step.getType()))
		{
			return List.of(nodes);
		}
		List<List<int[]>> orders = new ArrayList<>();
		permute(nodes, 0, orders);
		return orders;
	}

	/**
	 * One leg per stage, any of its tiles. A stage done anywhere (Sherlock's task with no place) has no leg. Three-step
	 * parts may be visited in any order; every other step's stages keep theirs.
	 */
	private static List<List<int[]>> stageOrders(PlanContext ctx, Step step)
	{
		List<int[]> legs = new ArrayList<>();
		boolean anyOrder = true;
		for (Stage stage : step.getStages())
		{
			anyOrder &= stage.getKind() == Stage.Kind.PART;
			int[] places = stage.getTiles().stream().filter(tile -> isThere(ctx, stage, tile)).mapToInt(ctx::nodeAt).toArray();
			if (places.length > 0)
			{
				legs.add(places);
			}
		}
		if (!anyOrder)
		{
			return List.of(legs);
		}
		List<List<int[]>> orders = new ArrayList<>();
		permute(legs, 0, orders);
		return orders;
	}

	/**
	 * A place that needs a grown patch (a Farming Guild redwood) counts only while the player has it grown, one in the
	 * house (its spirit tree) only while the house has it.
	 */
	private static boolean isThere(PlanContext ctx, Stage stage, WorldPoint tile)
	{
		String patch = stage.getGrownOnly().get(tile);
		boolean inHouse = PositionRules.POH_NODE.equals(tile);
		return (patch == null || ctx.in.getPlayer().getPlantedTrees().contains(patch))
			&& (!inHouse || ctx.in.getPlayer().getHouse().hasAny(stage.getHouseObjects())) && !ctx.lacksItems(tile);
	}

	private static void permute(List<int[]> items, int from, List<List<int[]>> out)
	{
		if (from == items.size())
		{
			out.add(new ArrayList<>(items));
			return;
		}
		for (int i = from; i < items.size(); i++)
		{
			Collections.swap(items, from, i);
			permute(items, from + 1, out);
			Collections.swap(items, from, i);
		}
	}

	/** The expected search: half the area's radius, run at one tile per half-tick. */
	static int areaHalfTicks(Step step)
	{
		List<Integer> regions = step.getRegions();
		if (regions == null || regions.isEmpty())
		{
			return 0;
		}
		int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
		for (int region : regions)
		{
			int x = (region >> 8) * REGION_SIZE;
			int y = (region & 0xFF) * REGION_SIZE;
			minX = Math.min(minX, x);
			minY = Math.min(minY, y);
			maxX = Math.max(maxX, x + REGION_SIZE);
			maxY = Math.max(maxY, y + REGION_SIZE);
		}
		int radius = Math.max(maxX - minX, maxY - minY) / 2;
		return radius / 2;
	}

	private static Route followed(PlanInput in, Searches searches, List<List<int[]>> orders, Picks picks)
	{
		String first = in.getFollowedFirstTransport();
		if (first == null || picks.best == null || first.equals(picks.best.getFirstTransportKey()))
		{
			return null;
		}
		int limit = picks.best.getRankHalfTicks() + 2 * RoutePlanner.COMMIT_MARGIN_TICKS;
		LabelSearch search = searches.firstBy(orders, first, limit);
		return search == null ? null : new Picks(searches.ctx, search).best;
	}

	private static List<Route> alternatives(PlanInput in, Searches searches, List<List<int[]>> orders, Picks picks)
	{
		List<Route> alternatives = new ArrayList<>();
		Set<String> excluded = new HashSet<>();
		Set<String> identities = new HashSet<>();
		List<Route> shown = new ArrayList<>();
		Stream.of(picks.best, picks.direct, picks.sameBook, picks.fasterUnqualified).filter(Objects::nonNull).forEach(route ->
		{
			excluded.add(route.getFirstTransportKey());
			excludeAfterBank(route, excluded);
			identities.add(route.getIdentity());
			shown.add(route);
		});
		if (excluded.isEmpty())
		{
			return alternatives;
		}
		int limit = picks.best == null ? Integer.MAX_VALUE
			: picks.best.getRankHalfTicks() + Math.max(picks.best.getRankHalfTicks(), ALTERNATIVE_SLACK_HALF_TICKS);
		for (int tries = 0; alternatives.size() < in.getSettings().getRouteCount() - 1 && tries < MOST_ALTERNATIVE_SEARCHES; tries++)
		{
			LabelSearch search = searches.bestOrder(orders, Set.copyOf(excluded), limit);
			Route next = new Picks(searches.ctx, search).best;
			if (next == null || !excluded.add(next.getFirstTransportKey()))
			{
				break;
			}
			excludeAfterBank(next, excluded);
			if (!repeats(next, shown) && !loops(next) && identities.add(next.getIdentity()))
			{
				alternatives.add(next);
				shown.add(next);
			}
		}
		return alternatives;
	}

	private static void excludeAfterBank(Route route, Set<String> excluded)
	{
		String afterBank = route.getAfterBankTransportKey();
		if (afterBank != null)
		{
			excluded.add(afterBank);
		}
	}

	/**
	 * Leaving the shown routes' transports out can leave a round trip as the cheapest route with a transport ("walk to
	 * ring BIP, ring to DIP, ring back to BIP, walk 35").
	 */
	private static boolean loops(Route route)
	{
		List<WorldPoint> places = new ArrayList<>();
		for (Leg leg : route.getLegs())
		{
			WorldPoint from = leg.getFrom();
			WorldPoint to = leg.getTo();
			if (from == null || to == null || to.equals(from))
			{
				continue;
			}
			if (places.isEmpty())
			{
				places.add(from);
			}
			List<WorldPoint> before = places.subList(0, places.size() - 1);
			if (before.stream().anyMatch(seen -> seen.getPlane() == to.getPlane() && seen.distanceTo2D(to) <= SAME_LANDING_TILES))
			{
				return true;
			}
			places.add(to);
		}
		return false;
	}

	private static WorldPoint firstLanding(Route route)
	{
		Leg first = route.getFirstTransport();
		return first == null ? null : first.getTo();
	}

	/**
	 * Fishing cape and Max cape to Otto's Grotto are one alternative, while a free home teleport beside a paid spell
	 * stays.
	 */
	private static boolean repeats(Route route, List<Route> shown)
	{
		WorldPoint landing = firstLanding(route);
		return landing != null && shown.stream().anyMatch(other ->
		{
			WorldPoint at = firstLanding(other);
			return at != null && at.getPlane() == landing.getPlane() && at.distanceTo2D(landing) <= SAME_LANDING_TILES
				&& route.getSpent().keySet().containsAll(other.getSpent().keySet());
		});
	}

	/** Fills {@code ranks} with each tile's ranking ticks, rounded up. */
	private static Map<WorldPoint, Integer> probeTicks(PlanContext ctx, LabelSearch search, Map<WorldPoint, Integer> ranks)
	{
		Map<WorldPoint, Integer> ticks = new LinkedHashMap<>();
		search.probeBest.forEach((node, best) ->
		{
			Route[][] routes = new Route[2][LabelSearch.CATEGORIES];
			for (int b = 0; b < 2; b++)
			{
				for (int c = 0; c < LabelSearch.CATEGORIES; c++)
				{
					LabelSearch.Label arrival = best[b][c];
					routes[b][c] = arrival == null ? null : RouteBuilder.build(ctx, arrival, arrival.rank);
				}
			}
			Route pick = new Picks(routes).best;
			if (pick != null)
			{
				ticks.put(ctx.tile(node), pick.getTicks());
				ranks.put(ctx.tile(node), (pick.getRankHalfTicks() + 1) / 2);
			}
		});
		return ticks;
	}

	/** One line per missing item; an item with another way to it lists that way's missing parts after an "or". */
	private static List<String> missingList(List<RequiredItems.Verdict> verdicts)
	{
		List<String> lines = new ArrayList<>();
		for (RequiredItems.Verdict verdict : verdicts)
		{
			for (RequiredItems.Need need : verdict.getMissing())
			{
				if (lines.contains("- " + need.getName()))
				{
					continue;
				}
				lines.add("- " + need.getName());
				List<String> parts = verdict.getMissingParts().getOrDefault(need, List.of());
				if (!parts.isEmpty())
				{
					lines.add("or");
					parts.forEach(part -> lines.add("- " + part));
				}
			}
		}
		if (!lines.isEmpty())
		{
			lines.add(0, "Not found on you or in your bank:");
		}
		return List.copyOf(lines);
	}

	static List<String> requirementNotes(PlanContext ctx)
	{
		RequiredItems required = ctx.in.getRequired();
		List<String> notes = new ArrayList<>();
		List<RequiredItems.Verdict> verdicts = new ArrayList<>(List.of(ctx.required));
		verdicts.addAll(ctx.stageVerdicts());
		notes.addAll(missingList(verdicts));
		if (required.isSpadeAtLeprechaun() && ctx.required.getMissing().stream().anyMatch(need -> need.getName().equalsIgnoreCase("spade")))
		{
			notes.add("Your spade is with a tool leprechaun");
		}
		return notes;
	}

	/** The walk table holds walks up to 200 tiles only, so a target no entry reaches is too far to walk. */
	private static String noRouteNote(PlanContext ctx, List<List<int[]>> orders)
	{
		Step step = ctx.in.getStep();
		if (step.getData().getReach() != null)
		{
			return step.getData().getReach();
		}
		Set<Integer> reachable = new HashSet<>();
		WalkTable table = ctx.table;
		for (int node = 0; node < table.nodeCount(); node++)
		{
			for (int e = table.entriesFrom(node); e < table.entriesEnd(node); e++)
			{
				reachable.add(table.entryTo(e));
			}
		}
		boolean walkTooLong = orders.get(0).stream().flatMapToInt(Arrays::stream).anyMatch(n -> !reachable.contains(n));
		return walkTooLong ? "walk too long" : "no route from what you have";
	}

	private static final class Searches
	{
		final PlanContext ctx;
		final int area;
		final boolean probes;
		int labels;
		int count;

		Searches(PlanContext ctx, int area, boolean probes)
		{
			this.ctx = ctx;
			this.area = area;
			this.probes = probes;
		}

		/**
		 * Each order after the first stops at the best rank so far, which leaves out its slower direct and same-book
		 * routes; so a bounded winner runs once more in full.
		 */
		LabelSearch bestOrder(List<List<int[]>> orders, Set<String> excluded, int rankLimit)
		{
			LabelSearch best = null;
			List<int[]> bestOrder = null;
			int bestRank = Integer.MAX_VALUE;
			boolean bestBounded = false;
			for (List<int[]> order : orders)
			{
				int limit = Math.min(rankLimit, bestRank);
				LabelSearch search = run(order, excluded, limit);
				Route pick = new Picks(ctx, search).best;
				int rank = pick == null ? Integer.MAX_VALUE : pick.getRankHalfTicks();
				if (best == null || rank < bestRank)
				{
					best = search;
					bestOrder = order;
					bestRank = rank;
					bestBounded = limit != rankLimit;
				}
			}
			return bestBounded ? run(bestOrder, excluded, rankLimit) : best;
		}

		/** The best order's search of the routes that start with transport {@code first}; null when none is in the limit. */
		LabelSearch firstBy(List<List<int[]>> orders, String first, int rankLimit)
		{
			LabelSearch best = null;
			int bestRank = Integer.MAX_VALUE;
			for (List<int[]> order : orders)
			{
				LabelSearch search = new LabelSearch(ctx, order, area, first, rankLimit);
				search.run();
				labels += search.labels;
				count++;
				Route pick = new Picks(ctx, search).best;
				if (pick != null && pick.getRankHalfTicks() < bestRank)
				{
					best = search;
					bestRank = pick.getRankHalfTicks();
				}
			}
			return best;
		}

		private LabelSearch run(List<int[]> order, Set<String> excluded, int rankLimit)
		{
			LabelSearch search = new LabelSearch(ctx, order, probes, area, excluded, rankLimit);
			search.run();
			labels += search.labels;
			count++;
			return search;
		}
	}

	static final class Picks
	{
		Route best;
		Route direct;
		Route sameBook;
		Route fasterUnqualified;
		List<Plan.Candidate> candidates = new ArrayList<>();

		Picks(PlanContext ctx, LabelSearch search)
		{
			this(routes(ctx, search));
			for (int b = 0; b < 2; b++)
			{
				for (int c = 0; c < LabelSearch.CATEGORIES; c++)
				{
					LabelSearch.Label goal = search.goals[b][c];
					if (goal != null)
					{
						candidates.add(new Plan.Candidate(category(b, c), RouteBuilder.build(ctx, goal, goal.rank)));
					}
				}
			}
		}

		Picks(Route[][] r)
		{
			Route plain = faster(r[0][LabelSearch.NONE], r[0][LabelSearch.CHANGED]);
			Route bankOnly = faster(r[1][LabelSearch.NONE], r[1][LabelSearch.CHANGED]);
			Route walkedOnly = r[0][LabelSearch.WALKED];
			Route both = r[1][LabelSearch.WALKED];
			Route pickBank = qualifies(bankOnly, plain) ? bankOnly : plain;
			Route pickWalked = qualifies(walkedOnly, plain) ? walkedOnly : plain;
			Route reference = faster(pickBank, pickWalked);
			Route pickBoth = qualifies(both, reference) ? both : reference;
			best = Stream.of(plain, pickBank, pickWalked, pickBoth).filter(Objects::nonNull)
				.min(Comparator.comparingInt(Route::getRankHalfTicks)).orElse(null);
			direct = pickWalked;
			Route sameBookBanked = r[1][LabelSearch.NONE];
			sameBook = qualifies(sameBookBanked, r[0][LabelSearch.NONE]) ? sameBookBanked : r[0][LabelSearch.NONE];
			Route fastest = Stream.of(r[0], r[1]).flatMap(Stream::of).filter(Objects::nonNull)
				.min(Comparator.comparingInt(Route::getRankHalfTicks)).orElse(null);
			fasterUnqualified = fastest != null && best != null && fastest.getRankHalfTicks() < best.getRankHalfTicks() ? fastest : null;
		}

		private static Route[][] routes(PlanContext ctx, LabelSearch search)
		{
			Route[][] routes = new Route[2][LabelSearch.CATEGORIES];
			for (int b = 0; b < 2; b++)
			{
				for (int c = 0; c < LabelSearch.CATEGORIES; c++)
				{
					LabelSearch.Label goal = search.goals[b][c];
					routes[b][c] = goal == null ? null : RouteBuilder.build(ctx, goal, goal.rank);
				}
			}
			return routes;
		}

		private static String category(int b, int c)
		{
			return (b == 1 ? "bank" : "no bank") + ", " + (c == LabelSearch.NONE ? "no change" : c == LabelSearch.CHANGED ? "carried change" : "walked change");
		}

		private static Route faster(Route a, Route b)
		{
			return a == null ? b : b == null ? a : b.getRankHalfTicks() < a.getRankHalfTicks() ? b : a;
		}

		private static boolean qualifies(Route route, Route reference)
		{
			if (route == null)
			{
				return false;
			}
			if (reference == null)
			{
				return true;
			}
			int margin = Math.max(MARGIN_MIN_HALF_TICKS, reference.getRankHalfTicks() * MARGIN_PERCENT / 100);
			return route.getRankHalfTicks() < reference.getRankHalfTicks() - margin;
		}
	}
}

package com.cluehelper.route;

import java.util.concurrent.Executor;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;

/**
 * Runs planner jobs off the client thread and hands only the latest job's result back to it.
 * Each submit supersedes every earlier one: a superseded job is skipped if it hasn't started,
 * and its result is dropped if it has. Nothing is ever interrupted or slept on.
 */
@Slf4j
@Singleton
public class PlannerRunner
{
	private final Executor background;
	private final Executor clientThread;
	private final AtomicLong generation = new AtomicLong();
	private volatile long finishedGeneration;

	@Inject
	public PlannerRunner(ScheduledExecutorService executor, ClientThread clientThread)
	{
		this(executor, clientThread::invoke);
	}

	PlannerRunner(Executor background, Executor clientThread)
	{
		this.background = background;
		this.clientThread = clientThread;
	}

	/**
	 * @param job reads snapshot data only, never the client
	 * @param onResult runs on the client thread, only if no newer job was submitted meanwhile
	 */
	public <T> void submit(Supplier<T> job, Consumer<T> onResult)
	{
		long id = generation.incrementAndGet();
		background.execute(() -> run(id, job, onResult));
	}

	public void cancelAll()
	{
		finishedGeneration = generation.incrementAndGet();
	}

	public boolean isWorking()
	{
		return finishedGeneration != generation.get();
	}

	private <T> void run(long id, Supplier<T> job, Consumer<T> onResult)
	{
		if (isSuperseded(id))
		{
			return;
		}
		T result;
		try
		{
			result = job.get();
		}
		catch (RuntimeException e)
		{
			log.warn("planner job failed", e);
			finishIfLatest(id);
			return;
		}
		if (isSuperseded(id))
		{
			return;
		}
		clientThread.execute(() ->
		{
			if (finishIfLatest(id))
			{
				onResult.accept(result);
			}
		});
	}

	private boolean isSuperseded(long id)
	{
		return id != generation.get();
	}

	private synchronized boolean finishIfLatest(long id)
	{
		if (isSuperseded(id))
		{
			return false;
		}
		finishedGeneration = id;
		return true;
	}
}

package com.cluehelper.route;

import com.cluehelper.AvoidWilderness;
import com.cluehelper.ClueHelperConfig;
import com.cluehelper.SpellbookChanges;
import com.cluehelper.player.AccountType;
import lombok.Builder;
import lombok.Value;

/** Copied on the client thread. */
@Value
@Builder(toBuilder = true)
public class PlannerSettings
{
	@Builder.Default
	int routeCount = 3;
	@Builder.Default
	SpellbookChanges spellbookChanges = SpellbookChanges.ALL;
	boolean avoidWilderness;
	@Builder.Default
	boolean bankEdge = true;
	boolean scrollBookOutOfWilderness;

	public static PlannerSettings from(ClueHelperConfig config, AccountType accountType)
	{
		boolean avoid = config.avoidWilderness() == AvoidWilderness.ALWAYS
			|| config.avoidWilderness() == AvoidWilderness.HARDCORE_ONLY && accountType.isHardcore();
		return PlannerSettings.builder()
			.spellbookChanges(config.spellbookChanges())
			.avoidWilderness(avoid)
			.bankEdge(config.useBank())
			.scrollBookOutOfWilderness(config.scrollBookOutOfWilderness())
			.build();
	}
}

package com.cluehelper.route;

import com.cluehelper.memory.StashMemory;
import com.cluehelper.player.Container;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PlayerSnapshot;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.Item;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/**
 * Each need is core's own {@link ItemRequirement}, tested through {@code fulfilledBy}; only our own
 * {@link AlternativeRequirement} and {@link GearRequirement} are taken apart, for their other ways and gear picks. Built
 * on the client thread; judging is pure.
 */
@Value
@Builder(toBuilder = true)
public class RequiredItems
{
	public static final RequiredItems NONE = RequiredItems.builder().build();

	@Builder.Default
	List<Need> needs = List.of();
	@Builder.Default
	StashMemory.State stash = StashMemory.State.NONE;
	/** The planner doesn't route to the tool leprechaun, it only notes it. */
	boolean spadeAtLeprechaun;

	@Value
	public static class Need
	{
		String name;
		ItemRequirement requirement;
		boolean stepItem;
		/** Core's *clue* bank tag lists it already, so our bank highlights leave it out. */
		boolean inCoreTag;
		/** The step can't be done without it (an emote's items, Charlie's item), so there is no route while it is missing. */
		boolean blocksRoute;
	}

	@Value
	public static class Verdict
	{
		private static final Verdict MET = new Verdict(true, true, List.of(), List.of(), Map.of());

		/** A STASH known to be filled counts as carried. */
		boolean carried;
		/** Met with the bank added. */
		boolean banked;
		List<ItemUse> withdraw;
		List<Need> missing;
		/** For a missing need with another way to it: the parts of that way also missing. */
		Map<Need, List<String>> missingParts;

		private Verdict(boolean carried, boolean banked, List<ItemUse> withdraw, List<Need> missing, Map<Need, List<String>> missingParts)
		{
			this.carried = carried;
			this.banked = banked;
			this.withdraw = withdraw;
			this.missing = missing;
			this.missingParts = missingParts;
		}

		/** Not met even with the bank: these needs are owned nowhere. */
		static Verdict missing(List<Need> missing, Map<Need, List<String>> missingParts)
		{
			return new Verdict(false, false, List.of(), missing, missingParts);
		}

		/** Met once these are withdrawn at a bank stop. */
		static Verdict fromBank(List<ItemUse> withdraw)
		{
			return new Verdict(false, true, withdraw, List.of(), Map.of());
		}

		/** Met only with a bank stop. */
		public boolean isFromBank()
		{
			return !carried && banked;
		}
	}

	public boolean isEmpty()
	{
		return needs.isEmpty();
	}

	Verdict judge(PlayerSnapshot player, PlayerSnapshot banked)
	{
		List<Need> open = needs.stream().filter(need -> !(need.stepItem && stash == StashMemory.State.FILLED)).collect(Collectors.toList());
		if (open.isEmpty())
		{
			return Verdict.MET;
		}
		Map<Integer, Integer> carried = player.carriedItems();
		if (allMet(open, carried))
		{
			return Verdict.MET;
		}
		if (banked == null || !allMet(open, everything(carried, banked)))
		{
			Map<Integer, Integer> all = banked == null ? carried : everything(carried, banked);
			Item[] owned = PlayerSnapshot.items(all);
			List<Need> missing = open.stream().filter(need -> !need.requirement.fulfilledBy(owned)).collect(Collectors.toList());
			Map<Need, List<String>> parts = missing.stream().filter(need -> need.requirement instanceof AlternativeRequirement)
				.collect(Collectors.toMap(need -> need, need -> ((AlternativeRequirement) need.requirement).missingParts(owned)));
			return Verdict.missing(missing, parts);
		}
		return Verdict.fromBank(minimalWithdraw(open, player, carried, banked));
	}

	/**
	 * Drops what isn't needed, trying the gear picker's own picks last so they are the ones kept, and before them the items
	 * meeting the most needs alone: a made item (a net trap, an unfinished potion) is kept over its parts.
	 */
	private static List<ItemUse> minimalWithdraw(List<Need> open, PlayerSnapshot player, Map<Integer, Integer> carried,
		PlayerSnapshot banked)
	{
		List<ItemUse> candidates = new ArrayList<>();
		addCandidates(open, Container.BANK, banked.getBank(), candidates);
		addCandidates(open, Container.GROUP_STORAGE, banked.getGroupStorage(), candidates);
		if (!allMet(open, with(carried, candidates)))
		{
			candidates.clear();
			banked.getBank().forEach((id, qty) -> candidates.add(new ItemUse(Container.BANK, id, qty)));
			banked.getGroupStorage().forEach((id, qty) -> candidates.add(new ItemUse(Container.GROUP_STORAGE, id, qty)));
		}
		Set<Integer> picked = gearPicks(open, player, banked);
		candidates.sort(Comparator.comparing((ItemUse candidate) -> picked.contains(candidate.getItemId()))
			.thenComparingLong(candidate -> needsMetAlone(open, candidate.getItemId())));
		List<ItemUse> kept = new ArrayList<>(candidates);
		for (ItemUse candidate : candidates)
		{
			kept.remove(candidate);
			if (!allMet(open, with(carried, kept)))
			{
				kept.add(candidate);
			}
		}
		return List.copyOf(kept);
	}

	private static long needsMetAlone(List<Need> open, int itemId)
	{
		return open.stream().filter(need -> need.requirement instanceof AlternativeRequirement
			? ((AlternativeRequirement) need.requirement).wholeBy(itemId) : need.requirement.fulfilledBy(itemId)).count();
	}

	private static Set<Integer> gearPicks(List<Need> open, PlayerSnapshot player, PlayerSnapshot banked)
	{
		Set<Integer> stored = banked.storedIds();
		Set<Integer> picked = new HashSet<>();
		for (Need need : open)
		{
			if (need.requirement instanceof GearRequirement)
			{
				((GearRequirement) need.requirement).choose(player.getWorn().keySet(), player.getInventory().keySet(), stored)
					.ifPresent(choice -> picked.addAll(choice.getWithdraw()));
			}
		}
		return picked;
	}

	private static void addCandidates(List<Need> open, Container container, Map<Integer, Integer> stored, List<ItemUse> out)
	{
		stored.entrySet().stream()
			.filter(e -> open.stream().anyMatch(need -> need.requirement.fulfilledBy(e.getKey())))
			.sorted(Map.Entry.comparingByKey())
			.forEach(e -> out.add(new ItemUse(container, e.getKey(), e.getValue())));
	}

	private static boolean allMet(List<Need> open, Map<Integer, Integer> items)
	{
		Item[] array = PlayerSnapshot.items(items);
		return open.stream().allMatch(need -> need.requirement.fulfilledBy(array));
	}

	private static Map<Integer, Integer> everything(Map<Integer, Integer> carried, PlayerSnapshot banked)
	{
		Map<Integer, Integer> items = new LinkedHashMap<>(carried);
		banked.storedItems().forEach((id, qty) -> items.merge(id, qty, Integer::sum));
		return items;
	}

	private static Map<Integer, Integer> with(Map<Integer, Integer> carried, List<ItemUse> withdrawn)
	{
		Map<Integer, Integer> items = new LinkedHashMap<>(carried);
		withdrawn.forEach(use -> items.merge(use.getItemId(), use.getQuantity(), Integer::sum));
		return items;
	}

}

package com.cluehelper.route;

import com.cluehelper.player.Book;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PositionRules;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.RowAvailability;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
@Builder
public class Route
{
	public static final String WALK = "walk";

	List<Leg> legs;
	int halfTicks;
	/** Half-ticks plus the ranking-only consumable, cape-use and stranding penalties. */
	int rankHalfTicks;
	boolean banked;
	/** Spellbook Swap included. */
	boolean changed;
	/** Lunar while a Spellbook Swap is pending. */
	Book startBook;
	Book endBook;
	/** Keyed like {@code item:1712}, {@code cooldown:892}, {@code cape}. */
	Map<String, Integer> spent;
	RowAvailability.Confidence confidence;
	boolean wilderness;
	@Builder.Default
	List<ItemUse> withdraw = List.of();
	/** Core's *clue* bank tag already shows these, so our bank highlights leave them out. */
	@Builder.Default
	Set<Integer> withdrawInCoreTag = Set.of();
	/** The withdraw list needs more slots than are free; the extra click is counted in the ticks. */
	boolean depositFirst;
	boolean pinIncluded;
	/** Banked, but with no bank leg: the route starts with the withdraw list. */
	boolean openBankStart;

	public int getTicks()
	{
		return (halfTicks + 1) / 2;
	}

	public String getIdentity()
	{
		StringBuilder id = new StringBuilder(getFirstTransportKey());
		boolean afterBank = false;
		for (Leg leg : legs)
		{
			if (leg.getKind() == Leg.Kind.BANK)
			{
				id.append(" | bank");
				afterBank = true;
			}
			else if (afterBank && leg.isTransport())
			{
				id.append(" | ").append(transportKey(leg));
				afterBank = false;
			}
		}
		String changes = legs.stream()
			.filter(leg -> leg.getKind() == Leg.Kind.SPELLBOOK_CHANGE || leg.getKind() == Leg.Kind.SWAP_TELEPORT)
			.map(leg -> leg.getKind() == Leg.Kind.SWAP_TELEPORT ? "Spellbook Swap" : leg.getChange().getName() + "→" + leg.getBookAfter())
			.collect(Collectors.joining(", "));
		return changes.isEmpty() ? id.toString() : id + " | " + changes;
	}

	public String getFirstTransportKey()
	{
		Leg first = getFirstTransport();
		return first == null ? WALK : transportKey(first);
	}

	/**
	 * A way into the house followed by the house's own transport counts as that transport, or one house route would
	 * hide all others from the alternatives.
	 */
	public Leg getFirstTransport()
	{
		List<Leg> transports = legs.stream().filter(Leg::isTransport).collect(Collectors.toList());
		if (transports.isEmpty())
		{
			return null;
		}
		Leg first = transports.get(0);
		boolean intoHouse = PositionRules.POH_NODE.equals(first.getTo()) && transports.size() > 1;
		return intoHouse ? transports.get(1) : first;
	}

	/**
	 * Alternatives leave this out too, or every way to reach a bank would come back as an alternative with the same
	 * teleport after it.
	 */
	public String getAfterBankTransportKey()
	{
		boolean afterBank = false;
		for (Leg leg : legs)
		{
			if (leg.getKind() == Leg.Kind.BANK)
			{
				afterBank = true;
			}
			else if (afterBank && leg.isTransport())
			{
				return transportKey(leg);
			}
		}
		return null;
	}

	private static String transportKey(Leg leg)
	{
		return leg.getKind() == Leg.Kind.FAIRY_RING ? fairyKey(leg.getLanding()) : teleportKey(leg.getRow());
	}

	static String teleportKey(CatalogRow row)
	{
		WorldPoint to = row.getDestination();
		return row.getName() + "@" + to.getX() + "," + to.getY() + "," + to.getPlane();
	}

	static String fairyKey(CatalogRow landing)
	{
		return "fairy " + landing.getCode();
	}

	public String describe()
	{
		return legs.stream().map(Leg::describe).collect(Collectors.joining(" → "));
	}
}

package com.cluehelper.route;

import com.cluehelper.player.Book;
import com.cluehelper.player.Container;
import com.cluehelper.player.ItemUse;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/** A searched goal label as the route the guide follows: its legs, withdraw list and what it spends. */
final class RouteBuilder
{
	private RouteBuilder()
	{
	}

	static Route build(PlanContext ctx, LabelSearch.Label goal, int rank)
	{
		List<Leg> legs = new ArrayList<>();
		WorldPoint at = ctx.in.getStart().getTile();
		boolean wilderness = false;
		boolean stageReached = false;
		for (LabelSearch.Label label : goal.chain())
		{
			if (label.kind == null)
			{
				stageReached |= label.parent != null && label.leg != label.parent.leg;
				continue;
			}
			Leg leg = leg(ctx, label, at);
			Leg last = legs.isEmpty() ? null : legs.get(legs.size() - 1);
			boolean merge = leg.getKind() == Leg.Kind.WALK && last != null && last.getKind() == Leg.Kind.WALK
				&& !leavesByExit(ctx, last) && !stageReached;
			stageReached = false;
			if (merge)
			{
				legs.set(legs.size() - 1, Leg.walk(last.getFrom(), leg.getTo(), last.getHalfTicks() + leg.getHalfTicks(), leg.getBookAfter()));
			}
			else
			{
				legs.add(leg);
			}
			at = leg.getTo();
			wilderness |= at != null && OriginClass.of(at, ctx.in.getNoTeleport()).isWilderness();
		}
		Map<String, Integer> spent = new LinkedHashMap<>();
		for (LabelSearch.Label label : goal.chain())
		{
			tally(ctx, label.ref, spent);
			tally(ctx, label.ref2, spent);
		}
		List<ItemUse> withdraw = withdraw(ctx, goal);
		boolean banked = goal.b == PlanContext.BANKED;
		boolean depositFirst = banked && slotsNeeded(ctx, withdraw) > ctx.in.getPlayer().getFreeInventorySlots();
		int extra = depositFirst ? PlanContext.DEPOSIT_FIRST_HALF_TICKS : 0;
		boolean bankLeg = legs.stream().anyMatch(leg -> leg.getKind() == Leg.Kind.BANK);
		return Route.builder()
			.legs(List.copyOf(legs))
			.halfTicks(goal.half + extra)
			.rankHalfTicks(rank + extra)
			.banked(banked)
			.withdraw(withdraw)
			.withdrawInCoreTag(inCoreTag(ctx, goal, withdraw))
			.depositFirst(depositFirst)
			.pinIncluded(bankLeg && ctx.in.isPinPending())
			.openBankStart(banked && !bankLeg)
			.changed(goal.c != LabelSearch.NONE)
			.startBook(ctx.homeBook)
			.endBook(goal.endBook != null ? goal.endBook : LabelSearch.endBook(goal.k))
			.spent(spent)
			.confidence(goal.confidence())
			.wilderness(wilderness)
			.build();
	}

	/** A start leg through an {@link Exit} stays a leg of its own, so the guide can name the exit. */
	private static boolean leavesByExit(PlanContext ctx, Leg leg)
	{
		PlanStart start = ctx.in.getStart();
		return start.getKind() == PlanStart.Kind.SCENE && leg.getFrom() != null && leg.getFrom().equals(start.getTile())
			&& start.getWalk().exitTo(leg.getTo()) != null;
	}

	private static List<ItemUse> withdraw(PlanContext ctx, LabelSearch.Label goal)
	{
		if (goal.b != PlanContext.BANKED)
		{
			return List.of();
		}
		Map<Integer, ItemUse> byItem = new LinkedHashMap<>(routeWithdraw(goal));
		ctx.required.getWithdraw().forEach(use -> byItem.putIfAbsent(use.getItemId(), use));
		for (int gateItem : goal.withdrawn)
		{
			byItem.putIfAbsent(gateItem, new ItemUse(Container.BANK, gateItem, 1));
		}
		return List.copyOf(byItem.values());
	}

	private static Map<Integer, ItemUse> routeWithdraw(LabelSearch.Label goal)
	{
		Map<Integer, ItemUse> byItem = new LinkedHashMap<>();
		for (LabelSearch.Label label : goal.chain())
		{
			for (Object ref : new Object[]{label.ref, label.ref2})
			{
				List<ItemUse> uses = ref instanceof TransportOptions.Teleport ? ((TransportOptions.Teleport) ref).withdrawUses
					: ref instanceof TransportOptions.Change ? ((TransportOptions.Change) ref).withdrawUses : null;
				if (label.b == PlanContext.BANKED && uses != null)
				{
					uses.forEach(use -> byItem.putIfAbsent(use.getItemId(), use));
				}
			}
		}
		return byItem;
	}

	private static Set<Integer> inCoreTag(PlanContext ctx, LabelSearch.Label goal, List<ItemUse> withdraw)
	{
		Set<Integer> routeItems = routeWithdraw(goal).keySet();
		Set<Integer> tagged = new HashSet<>();
		for (ItemUse use : withdraw)
		{
			List<RequiredItems.Need> helped = ctx.in.getRequired().getNeeds().stream()
				.filter(need -> need.getRequirement().fulfilledBy(use.getItemId())).collect(Collectors.toList());
			if (!routeItems.contains(use.getItemId()) && !helped.isEmpty() && helped.stream().allMatch(RequiredItems.Need::isInCoreTag))
			{
				tagged.add(use.getItemId());
			}
		}
		return Set.copyOf(tagged);
	}

	/** A stack of something already in the inventory takes no new slot. */
	private static int slotsNeeded(PlanContext ctx, List<ItemUse> withdraw)
	{
		return (int) withdraw.stream().filter(use -> ctx.in.getPlayer().count(Container.INVENTORY, use.getItemId()) == 0).count();
	}

	/** Every unit a leg uses, tracked by the search or not. */
	private static void tally(PlanContext ctx, Object ref, Map<String, Integer> spent)
	{
		int[] res = ref instanceof TransportOptions.Teleport ? ((TransportOptions.Teleport) ref).res
			: ref instanceof TransportOptions.Change ? ((TransportOptions.Change) ref).res : null;
		int[] amounts = ref instanceof TransportOptions.Teleport ? ((TransportOptions.Teleport) ref).amounts
			: ref instanceof TransportOptions.Change ? ((TransportOptions.Change) ref).amounts : null;
		for (int i = 0; res != null && i < res.length; i++)
		{
			spent.merge(ctx.resources.name(res[i]), amounts[i], Integer::sum);
		}
	}

	private static Leg leg(PlanContext ctx, LabelSearch.Label label, WorldPoint at)
	{
		Book book = LabelSearch.bookOf(label.k);
		switch (label.kind)
		{
			case TELEPORT:
				return Leg.teleport(at, ((TransportOptions.Teleport) label.ref).row, label.edgeHalf, book);
			case SWAP_TELEPORT:
				return Leg.swapTeleport(at, ((TransportOptions.Teleport) label.ref).row, ((TransportOptions.Change) label.ref2).change, label.edgeHalf, book);
			case FAIRY_RING:
				return Leg.fairyRing(at, ((TransportOptions.Teleport) label.ref).row, ((TransportOptions.Teleport) label.ref2).row, label.edgeHalf, book);
			case SPELLBOOK_CHANGE:
				return Leg.spellbookChange(at, ((TransportOptions.Change) label.ref).change, label.edgeHalf, book);
			case BANK:
				return Leg.bank(at, label.edgeHalf, book);
			case WILDERNESS_EXIT:
				return Leg.wildernessExit(at, label.edgeHalf, book);
			case WALK:
				return Leg.walk(at, ctx.tile(label.node), label.edgeHalf, book);
			default:
				throw new IllegalArgumentException("unhandled leg kind " + label.kind);
		}
	}
}

package com.cluehelper.route;

