import com.cluehelper.player.SpellbookState;
import com.cluehelper.poh.HouseOwnership;
import com.cluehelper.poh.PohService;
import com.cluehelper.step.StageTarget;
import com.cluehelper.step.Step;
import com.cluehelper.transport.AvailabilityEngine;
import com.cluehelper.transport.AvailabilityService;
import com.cluehelper.transport.AvailabilitySet;
import com.cluehelper.transport.Catalog;
import com.cluehelper.transport.CatalogData;
import com.cluehelper.transport.Requirements;
import com.cluehelper.transport.VarCheck;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.IntPredicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;

/**
 * Client thread, except the plans themselves, which run on the executor through {@link PlannerRunner}. Re-plans only
 * when a {@link Trigger} input changes, never per tile.
 */
@Slf4j
@Singleton
public class RoutePlanner
{
	static final int COMMIT_MARGIN_TICKS = 5;
	/** A Spellbook Swap's free cast stays pending this long after varbit 3617 turns 1. */
	private static final int SWAP_WINDOW_TICKS = 200;
	private static final int NOT_REFUSED = -1;
	private static final int TARGET_WALK_BUCKET_TILES = 2 * COMMIT_MARGIN_TICKS;
	/** The guide's landing radius: some teleports land anywhere in a small area. */
	private static final int LANDED_TILES = 10;
	private static final int POCKET_TILES = 3;
	private static final int NO_TARGET_NEAR = -1;
	private static final long NO_SCENE = Long.MIN_VALUE;

	private final Client client;
	private final ClueLink clueLink;
	private final PlayerModel player;
	private final AvailabilityService availability;
	private final CatalogData catalogData;
	private final WalkData walkData;
	private final PlannerRunner runner;
	/** The walk from the player's tile, searched apart so it never supersedes a plan. */
	private final PlannerRunner startRunner;
	private final ClueHelperConfig config;
	private final BankMemory bankMemory;
	private final StepNeeds stepNeeds;
	private final PohService poh;
	private final ProbeTarget probeTarget;
	private final StageTarget stageTarget;
	private final SceneDoors doors;
	private final List<Consumer<Plan>> listeners = new CopyOnWriteArrayList<>();
	private final List<BiConsumer<Plan, PlanInput>> inputListeners = new CopyOnWriteArrayList<>();

	private volatile WalkData.Loaded walk;
	private volatile Catalog catalog;
	private long gatesVersion = -1;
	private boolean[] rowOpen;
	private WorldPoint lastTile;
	/** After a teleport the scene loads a tick after the tile moves: a walk over the old scene must be redone. */
	private long lastSceneBase = NO_SCENE;
	@Getter
	private volatile PlanStart start;
	@Getter
	private volatile int nearestNode = WalkTable.NO_NODE;
	@Getter
	private volatile long lastWalkNanos;
	private int targetWalkBucket = NO_TARGET_NEAR;
	private Trigger lastTrigger;
	@Getter
	private volatile Plan plan = Plan.NONE;
	@Getter
	private volatile Route committed;
	private String committedStep;
	private int swapCheckAtCapeRefusal = NOT_REFUSED;
	private final Set<String> refusedChanges = new HashSet<>();

	@Inject
	RoutePlanner(Client client, ClueLink clueLink, PlayerModel player, AvailabilityService availability, CatalogData catalogData,
		WalkData walkData, PlannerRunner runner, ClueHelperConfig config, BankMemory bankMemory, StepNeeds stepNeeds, PohService poh,
		ProbeTarget probeTarget, StageTarget stageTarget, SceneDoors doors, ScheduledExecutorService executor, ClientThread clientThread)
	{
		this.startRunner = new PlannerRunner(executor, clientThread);
		this.stageTarget = stageTarget;
		this.doors = doors;
		this.poh = poh;
		this.probeTarget = probeTarget;
		this.bankMemory = bankMemory;
		this.stepNeeds = stepNeeds;
		this.client = client;
		this.clueLink = clueLink;
		this.player = player;
		this.availability = availability;
		this.catalogData = catalogData;
		this.walkData = walkData;
		this.runner = runner;
		this.config = config;
	}

	/** The guide takes such a scroll out at the bank as the plan does. */
	public boolean keepsScrollBookOutOfWilderness()
	{
		return config.scrollBookOutOfWilderness();
	}

	public void start()
	{
		catalogData.get().thenAccept(loaded -> catalog = loaded);
		walkData.get().thenAccept(loaded ->
		{
			if (loaded != null)
			{
				watchGateVars(loaded.getTable());
				walk = loaded;
			}
		});
	}

	public void stop()
	{
		runner.cancelAll();
		startRunner.cancelAll();
		plan = Plan.NONE;
		committed = null;
		committedStep = null;
		lastTrigger = null;
		lastTile = null;
		start = null;
	}

	/** Listeners run on the client thread with each new plan. */
	public Runnable addListener(Consumer<Plan> listener)
	{
		listeners.add(listener);
		return () -> listeners.remove(listener);
	}

	/** Like {@link #addListener}, with what each plan was planned from: the dev launcher records slow ones. */
	public Runnable addInputListener(BiConsumer<Plan, PlanInput> listener)
	{
		inputListeners.add(listener);
		return () -> inputListeners.remove(listener);
	}

	/** The step to travel to now: the clue's step, with a hot/cold probe as its target and the stages already done dropped. */
	public Step travelStep()
	{
		return stageTarget.travelStep(probeTarget.travelStep(clueLink.getCurrentStep()));
	}

	/** Call after the player model's and availability's GameTick handlers. */
	public void onGameTick()
	{
		refresh();
	}

	/** The start walk from a new tile first, then a plan once any of its inputs changed. */
	private void refresh()
	{
		Step step = travelStep();
		PlayerSnapshot snapshot = player.getSnapshot();
		RuneModel runes = player.getRuneModel();
		WalkData.Loaded data = walk;
		Catalog loadedCatalog = catalog;
		boolean dormant = snapshot != null && snapshot.getDormantReason() != null;
		if (step == null || snapshot == null || runes == null || data == null || loadedCatalog == null || dormant)
		{
			if ((step == null || dormant) && plan != Plan.NONE)
			{
				stop();
				listeners.forEach(listener -> listener.accept(Plan.NONE));
			}
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		forgetCapeRefusalOnceCheckMoved(snapshot);
		snapshot = withRefusals(snapshot);
		updateStart(data, snapshot, runes, step);
		if (start == null)
		{
			return;
		}
		PlannerSettings settings = PlannerSettings.from(config, snapshot.getAccountType());
		AvailabilitySet carried = availability.getCarried();
		PlayerSnapshot banked = availability.getBankedSnapshot();
		RequiredItems required = stepNeeds.of(step);
		boolean atOpenBank = bankMemory.isBankOpen();
		boolean foreignHouse = poh.isInHouse() && poh.getOwnership() == HouseOwnership.Ownership.FOREIGN;
		Trigger trigger = new Trigger(step, snapshot.getVersion(), carried.getSnapshotVersion(), carried.getValidUntilMinute(),
			nearestNode, targetWalkBucket, start.getKind(), snapshot.getSpellbook(), settings, Set.copyOf(refusedChanges),
			bankMemory.getVersion(), atOpenBank, required, foreignHouse);
		if (trigger.equals(lastTrigger))
		{
			return;
		}
		lastTrigger = trigger;
		PlanInput input = input(step, snapshot, runes, data, loadedCatalog, settings, banked, required, atOpenBank, foreignHouse);
		PlanInput followingInput = input.toBuilder().followedFirstTransport(followedFirstTransport(step)).build();
		runner.submit(() -> Planner.withoutAlternatives(followingInput), planned -> onPlanned(planned, followingInput));
	}

	/**
	 * Client thread. What a plan for {@code step} would get now, for searches of other planners; null until the
	 * first plan's inputs are all loaded.
	 */
	public PlanInput inputFor(Step step, RequiredItems required)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		RuneModel runes = player.getRuneModel();
		WalkData.Loaded data = walk;
		Catalog loadedCatalog = catalog;
		if (step == null || snapshot == null || runes == null || data == null || loadedCatalog == null || start == null)
		{
			return null;
		}
		snapshot = withRefusals(snapshot);
		boolean foreignHouse = poh.isInHouse() && poh.getOwnership() == HouseOwnership.Ownership.FOREIGN;
		return input(step, snapshot, runes, data, loadedCatalog, PlannerSettings.from(config, snapshot.getAccountType()),
			availability.getBankedSnapshot(), required, bankMemory.isBankOpen(), foreignHouse);
	}

	/** Loaded walk data; null until it is. */
	public WalkData.Loaded getWalk()
	{
		return walk;
	}

	/** Client thread. The walk rows the player can take now, fixed for a search on another thread. */
	public IntPredicate openRows()
	{
		boolean[] open = rowOpen;
		return row -> open != null && open[row];
	}

	private PlanInput input(Step step, PlayerSnapshot snapshot, RuneModel runes, WalkData.Loaded data, Catalog loadedCatalog,
		PlannerSettings settings, PlayerSnapshot banked, RequiredItems required, boolean atOpenBank, boolean foreignHouse)
	{
		return PlanInput.builder()
			.step(step)
			.player(snapshot)
			.banked(banked == null ? null : withRefusals(banked))
			.pinPending(bankMemory.isPinPending())
			.atOpenBank(atOpenBank)
			.required(required)
			.engine(new AvailabilityEngine(runes, id -> "item " + id))
			.nowMinutes(AvailabilityService.nowMinutes())
			.catalog(loadedCatalog)
			.table(data.getTable())
			.noTeleport(data.getNoTeleport())
			.start(start)
			.settings(settings)
			.revertTicksLeft(revertTicksLeft())
			.refusedChanges(Set.copyOf(refusedChanges))
			.foreignHouseStart(foreignHouse)
			.build();
	}

	/** Client thread. The game refused a cape change for today's limit, whatever SB_SWAP_CHECK says. */
	public void onCapeChangesRefused()
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		Integer used = snapshot == null ? null : snapshot.varbit(VarbitID.SB_SWAP_CHECK);
		swapCheckAtCapeRefusal = used == null ? 0 : used;
		lastTrigger = null;
		log.debug("cape change refused at 4816 = {}", swapCheckAtCapeRefusal);
	}

	/**
	 * Client thread. No var tells of some refusals (the Music cape's "untrimmed cape" rule), so the row isn't offered
	 * again this session.
	 */
	public void onRowRefused(String row)
	{
		if (refusedChanges.add(row))
		{
			lastTrigger = null;
			log.debug("refused this session: {}", row);
		}
	}

	/** The refused cape change counts until SB_SWAP_CHECK moves: the day's limit has reset by then. */
	private void forgetCapeRefusalOnceCheckMoved(PlayerSnapshot snapshot)
	{
		Integer used = snapshot.varbit(VarbitID.SB_SWAP_CHECK);
		if (swapCheckAtCapeRefusal != NOT_REFUSED && used != null && used != swapCheckAtCapeRefusal)
		{
			swapCheckAtCapeRefusal = NOT_REFUSED;
		}
	}

	/** After a cape refusal, no cape uses are left. */
	private PlayerSnapshot withRefusals(PlayerSnapshot snapshot)
	{
		if (swapCheckAtCapeRefusal == NOT_REFUSED)
		{
			return snapshot;
		}
		Map<Integer, Integer> varbits = new HashMap<>(snapshot.getVarbits());
		varbits.put(VarbitID.SB_SWAP_CHECK, SpellbookState.CAPE_CHANGES_PER_DAY);
		SpellbookState book = snapshot.getSpellbook();
		SpellbookState noCapeUses = book == null ? null : new SpellbookState(book.getBook(), book.isPendingRevert(), 0,
			book.isArceuusUnlocked(), book.isAncientAccess(), book.isLunarAccess(), book.isSwapAccess());
		return snapshot.toBuilder().varbits(varbits).spellbook(noCapeUses).build();
	}

	private void updateStart(WalkData.Loaded data, PlayerSnapshot snapshot, RuneModel runes, Step step)
	{
		Position position = player.getPosition();
		WalkTable table = data.getTable();
		if (position.getKind() != Position.Kind.WORLD)
		{
			startRunner.cancelAll();
		}
		if (position.getKind() == Position.Kind.POH && table.node(PositionRules.POH_NODE) != WalkTable.NO_NODE)
		{
			start = PlanStart.atNode(table, table.node(PositionRules.POH_NODE));
			nearestNode = start.getNode();
			lastTile = null;
			return;
		}
		if (position.getKind() != Position.Kind.WORLD)
		{
			start = PlanStart.teleportOnly(position.getTile());
			nearestNode = WalkTable.NO_NODE;
			lastTile = null;
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		long sceneBase = sceneBase(view);
		boolean sceneReloaded = sceneBase != lastSceneBase;
		if (position.getTile().equals(lastTile) && (start != null || startRunner.isWorking()) && !sceneReloaded)
		{
			return;
		}
		lastTile = position.getTile();
		lastSceneBase = sceneBase;
		refreshGates(table, snapshot, runes);
		LoadedScene scene = doors.withDoorsOpen(view, LoadedScene.capture(view), table);
		Ground ground = Ground.world(data.getMap(), scene, table, openRows());
		WorldPoint tile = position.getTile();
		List<WorldPoint> targets = step.getTargets();
		startRunner.submit(() -> timedWalk(ground, tile), walk -> walked(table, tile, targets, walk));
	}

	private WalkCosts timedWalk(Ground ground, WorldPoint tile)
	{
		long started = System.nanoTime();
		WalkCosts walk = WalkCosts.from(ground, tile);
		lastWalkNanos = System.nanoTime() - started;
		return walk;
	}

	/** Client thread: the walk from the player's tile is in, and the plan goes ahead now rather than a tick later. */
	private void walked(WalkTable table, WorldPoint tile, List<WorldPoint> targets, WalkCosts walk)
	{
		if (isMidObstacle(walk) && start != null)
		{
			retryNextTick();
			return;
		}
		int nearestHere = nearest(table, walk);
		int targetWalk = targets.stream().mapToInt(walk::cost).min().orElse(WalkCosts.UNREACHED);
		boolean targetNear = targetWalk != WalkCosts.UNREACHED;
		if (isInPocket(nearestHere, targetNear, tile))
		{
			retryNextTick();
			return;
		}
		nearestNode = nearestHere;
		targetWalkBucket = targetNear ? targetWalk / TARGET_WALK_BUCKET_TILES : NO_TARGET_NEAR;
		start = nearestNode != WalkTable.NO_NODE || targetNear ? PlanStart.scene(tile, walk)
			: PlanStart.teleportOnly(tile, walk);
		refresh();
	}
	private static long sceneBase(WorldView view)
	{
		return view == null ? NO_SCENE : (long) view.getBaseX() << 32 | view.getBaseY() & 0xFFFFFFFFL;
	}

	/** Each new snapshot judges the walk gates and the webs again. */
	private void refreshGates(WalkTable table, PlayerSnapshot snapshot, RuneModel runes)
	{
		if (gatesVersion == snapshot.getVersion())
		{
			return;
		}
		WalkGates gates = new WalkGates(table, snapshot, new AvailabilityEngine(runes, id -> ""), AvailabilityService.nowMinutes());
		rowOpen = gates.rowOpen();
		doors.playerChanged(snapshot);
		gatesVersion = snapshot.getVersion();
	}

	/**
	 * Collision flags still loading after a reload, or the player mid-obstacle on a blocked tile (stepping stones, a
	 * log): the walk reaches only the player's tile.
	 */
	private static boolean isMidObstacle(WalkCosts walk)
	{
		return walk.reachedTiles() <= 1;
	}

	/** Mid-obstacle in a pocket with no node (south of Kaleb's, anim 741), a few tiles from a start that had nodes. */
	private boolean isInPocket(int nearestHere, boolean targetInScene, WorldPoint tile)
	{
		return nearestHere == WalkTable.NO_NODE && !targetInScene && start != null && start.getKind() == PlanStart.Kind.SCENE
			&& start.getTile() != null && start.getTile().distanceTo2D(tile) <= POCKET_TILES;
	}

	/** The last start stands until the next tick looks again. */
	private void retryNextTick()
	{
		lastTile = null;
		lastSceneBase = NO_SCENE;
	}

	private static int nearest(WalkTable table, WalkCosts walk)
	{
		int best = WalkTable.NO_NODE;
		int bestCost = WalkCosts.UNREACHED;
		for (int node = 0; node < table.nodeCount(); node++)
		{
			int cost = walk.cost(table.placed(node));
			if (cost < bestCost)
			{
				best = node;
				bestCost = cost;
			}
		}
		return best;
	}

	private int revertTicksLeft()
	{
		int since = player.getPendingRevertSinceTick();
		return since == PlayerModel.UNKNOWN_TICK ? PlanInput.NO_REVERT_WINDOW
			: Math.max(PlanInput.NO_REVERT_WINDOW, SWAP_WINDOW_TICKS - (client.getTickCount() - since));
	}

	private String followedFirstTransport(Step step)
	{
		return committed != null && step.getKey().equals(committedStep) ? committed.getFirstTransportKey() : null;
	}

	private void onPlanned(Plan planned, PlanInput input)
	{
		plan = planned;
		committed = commit(planned);
		committedStep = planned.getStepKey();
		listeners.forEach(listener -> listener.accept(planned));
		inputListeners.forEach(listener -> listener.accept(planned, input));
	}

	private Route commit(Plan planned)
	{
		Route best = planned.getBest();
		Route current = committed;
		if (best == null || current == null || !Objects.equals(committedStep, planned.getStepKey()))
		{
			return best;
		}
		Route same = offered(planned, current.getIdentity());
		if (same == null || best.getTicks() <= same.getTicks() - COMMIT_MARGIN_TICKS || landsWhereItStarts(same))
		{
			return best;
		}
		return same;
	}

	/**
	 * Right after a teleport the followed route is still offered from the landing, teleporting to where the player
	 * already stands; keeping it would send the guide back to the teleport.
	 */
	private boolean landsWhereItStarts(Route route)
	{
		Leg first = route.getFirstTransport();
		PlanStart from = start;
		return first != null && from != null && from.getTile() != null && first.getTo() != null
			&& first.getTo().getPlane() == from.getTile().getPlane() && first.getTo().distanceTo2D(from.getTile()) <= LANDED_TILES;
	}

	private static Route offered(Plan planned, String identity)
	{
		for (Route route : routesOf(planned))
		{
			if (route != null && route.getIdentity().equals(identity))
			{
				return route;
			}
		}
		return null;
	}

	private static List<Route> routesOf(Plan planned)
	{
		List<Route> routes = new ArrayList<>();
		routes.add(planned.getBest());
		routes.add(planned.getDirect());
		routes.add(planned.getSameBook());
		routes.addAll(planned.getAlternatives());
		routes.add(planned.getFollowed());
		planned.getCandidates().forEach(candidate -> routes.add(candidate.getRoute()));
		return routes;
	}

	private void watchGateVars(WalkTable table)
	{
		Set<Integer> varbits = new HashSet<>();
		Set<Integer> varps = new HashSet<>();
		for (Requirements gate : table.getGates())
		{
			for (VarCheck check : gate.getVars())
			{
				(check.getKind() == VarCheck.Kind.VARBIT ? varbits : varps).add(check.getId());
			}
		}
		player.watch(varbits, varps);
	}

	/** Walking changes it only through the nearest node or the walk to a target in the scene. */
	@Value
	private static class Trigger
	{
		Step step;
		long snapshotVersion;
		long carriedVersion;
		long carriedValidUntil;
		int nearestNode;
		int targetWalkBucket;
		PlanStart.Kind startKind;
		SpellbookState spellbook;
		PlannerSettings settings;
		Set<String> refusedChanges;
		long bankVersion;
		boolean atOpenBank;
		RequiredItems required;
		boolean foreignHouse;
	}
}

package com.cluehelper.route;

import com.cluehelper.player.PlayerSnapshot;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;

/**
 * The walk table, like Shortest Path, takes doors as open: a closed one costs a click, not a detour. A locked door
 * stays shut: one with a lock option, or one the game answered with a "locked" message this session.
 */
@Singleton
public final class SceneDoors
{
	private static final String OPEN = "Open";
	/** A web across a way (the Wilderness lever's room) is slashed through like a door is opened. */
	private static final String SLASH = "Slash";
	private static final Set<String> LOCK_OPTIONS = Set.of("Pick-lock", "Unlock");
	private static final String LOCKED = "locked";
	private static final int NOTHING_OPENED = -1;
	private static final int WEST = 1;
	private static final int NORTH = 2;
	private static final int EAST = 4;
	private static final int SOUTH = 8;
	private static final int OBJECT_TYPE_MASK = 0x1F;
	/** A wall across a tile's diagonal (the Wizards' Tower door) is a game object blocking the whole tile. */
	private static final int DIAGONAL_WALL = 9;
	private static final int ALL_SIDES = CollisionDataFlag.BLOCK_MOVEMENT_WEST | CollisionDataFlag.BLOCK_MOVEMENT_NORTH
		| CollisionDataFlag.BLOCK_MOVEMENT_EAST | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;

	private static final String NONE = "";
	/** Shortest Path's SLASH items (knives, axes, blades), as the catalog generator writes them. */
	private static final Set<Integer> SLASH_ITEMS = slashItems();

	/** The option that opens each object: Open, Slash, or NONE. */
	private final Map<Integer, String> openOptions = new HashMap<>();
	private final Set<Integer> lockedIds = new HashSet<>();
	private int lastOpened = NOTHING_OPENED;
	private volatile boolean canSlash;
	private final Client client;

	@Inject
	public SceneDoors(Client client)
	{
		this.client = client;
	}

	/** From each new snapshot: a web opens only to a player carrying or wielding something that slashes. */
	public void playerChanged(PlayerSnapshot player)
	{
		canSlash = player.carriedIds().stream().anyMatch(SLASH_ITEMS::contains);
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		lastOpened = OPEN.equals(event.getMenuOption()) ? event.getId() : NOTHING_OPENED;
	}

	public void onChatMessage(ChatMessage message)
	{
		boolean game = message.getType() == ChatMessageType.GAMEMESSAGE || message.getType() == ChatMessageType.SPAM;
		if (game && lastOpened != NOTHING_OPENED && message.getMessage().toLowerCase().contains(LOCKED))
		{
			lockedIds.add(lastOpened);
		}
	}

	/**
	 * Client thread only. A copy of {@code scene}, a capture of {@code view}, with the walls of closed doors cleared and
	 * the sides they open through recorded. A door that {@code table} crosses by a row (one that shuts behind the
	 * player, its opening animated) stays shut, so its row's time counts.
	 */
	public LoadedScene withDoorsOpen(WorldView view, LoadedScene scene, WalkTable table)
	{
		if (scene == null)
		{
			return null;
		}
		Tile[][][] tiles = view.getScene().getTiles();
		int[][][] flags = copyOf(scene.getFlags());
		int[][][] doorSides = new int[flags.length][][];
		for (int plane = 0; plane < Math.min(tiles.length, flags.length); plane++)
		{
			if (flags[plane] == null)
			{
				continue;
			}
			doorSides[plane] = new int[flags[plane].length][flags[plane][0].length];
			for (int x = 0; x < tiles[plane].length; x++)
			{
				for (int y = 0; y < tiles[plane][x].length; y++)
				{
					Tile tile = tiles[plane][x][y];
					WallObject wall = tile == null ? null : tile.getWallObject();
					if (wall != null && opens(wall.getId()) && !passedByRow(table, wall.getId(), view, x, y, plane))
					{
						clearWall(flags[plane], doorSides[plane], x, y, wall.getOrientationA());
					}
					if (diagonalDoor(tile) != null)
					{
						clear(flags[plane], x, y, CollisionDataFlag.BLOCK_MOVEMENT_OBJECT);
						doorSides[plane][x][y] |= ALL_SIDES;
					}
				}
			}
		}
		return new LoadedScene(scene.getBaseX(), scene.getBaseY(), scene.getSizeX(), scene.getSizeY(), flags, doorSides);
	}

	private static int[][][] copyOf(int[][][] flags)
	{
		int[][][] copy = new int[flags.length][][];
		for (int plane = 0; plane < flags.length; plane++)
		{
			if (flags[plane] != null)
			{
				copy[plane] = new int[flags[plane].length][];
				for (int x = 0; x < flags[plane].length; x++)
				{
					copy[plane][x] = flags[plane][x].clone();
				}
			}
		}
		return copy;
	}

	/** Client thread only. */
	/** A door or web the path can go through with one click. */
	public boolean opensOnClick(WallObject wall)
	{
		return opens(wall.getId());
	}

	/** Client thread only. The closed door standing across {@code tile}'s diagonal, or null. */
	public GameObject diagonalDoor(Tile tile)
	{
		if (tile == null)
		{
			return null;
		}
		for (GameObject object : tile.getGameObjects())
		{
			if (object != null && (object.getConfig() & OBJECT_TYPE_MASK) == DIAGONAL_WALL && opens(object.getId()))
			{
				return object;
			}
		}
		return null;
	}

	private static boolean passedByRow(WalkTable table, int id, WorldView view, int sceneX, int sceneY, int plane)
	{
		return table != null && table.isRowObjectAt(id, new WorldPoint(view.getBaseX() + sceneX, view.getBaseY() + sceneY, plane));
	}

	private boolean opens(int id)
	{
		String option = openOption(id);
		return !lockedIds.contains(id) && (OPEN.equals(option) || SLASH.equals(option) && canSlash);
	}

	/** Client thread only. The option that opens a door or web, or "" for anything else. */
	public String openOption(int id)
	{
		return openOptions.computeIfAbsent(id, key ->
		{
			ObjectComposition object = client.getObjectDefinition(key);
			if (object != null && object.getImpostorIds() != null)
			{
				object = object.getImpostor();
			}
			String option = NONE;
			for (String action : object == null || object.getActions() == null ? new String[0] : object.getActions())
			{
				if (action != null && LOCK_OPTIONS.contains(action))
				{
					return NONE;
				}
				option = OPEN.equals(action) || SLASH.equals(action) ? action : option;
			}
			return option;
		});
	}

	private static Set<Integer> slashItems()
	{
		try (InputStream in = SceneDoors.class.getResourceAsStream("slash.txt"))
		{
			if (in == null)
			{
				throw new IllegalStateException("slash.txt is missing");
			}
			Set<Integer> ids = new HashSet<>();
			for (String line : new String(in.readAllBytes(), StandardCharsets.UTF_8).split("\\R"))
			{
				if (!line.isBlank() && !line.startsWith("#"))
				{
					ids.add(Integer.parseInt(line.trim()));
				}
			}
			return Set.copyOf(ids);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("can't read slash.txt", e);
		}
	}

	private static void clearWall(int[][] flags, int[][] doorSides, int x, int y, int orientation)
	{
		if ((orientation & WEST) != 0)
		{
			open(flags, doorSides, x, y, CollisionDataFlag.BLOCK_MOVEMENT_WEST);
			open(flags, doorSides, x - 1, y, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		}
		if ((orientation & NORTH) != 0)
		{
			open(flags, doorSides, x, y, CollisionDataFlag.BLOCK_MOVEMENT_NORTH);
			open(flags, doorSides, x, y + 1, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH);
		}
		if ((orientation & EAST) != 0)
		{
			open(flags, doorSides, x, y, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
			open(flags, doorSides, x + 1, y, CollisionDataFlag.BLOCK_MOVEMENT_WEST);
		}
		if ((orientation & SOUTH) != 0)
		{
			open(flags, doorSides, x, y, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH);
			open(flags, doorSides, x, y - 1, CollisionDataFlag.BLOCK_MOVEMENT_NORTH);
		}
	}

	private static void open(int[][] flags, int[][] doorSides, int x, int y, int side)
	{
		clear(flags, x, y, side);
		if (x >= 0 && x < doorSides.length && y >= 0 && y < doorSides[x].length)
		{
			doorSides[x][y] |= side;
		}
	}

	private static void clear(int[][] flags, int x, int y, int flag)
	{
		if (x >= 0 && x < flags.length && y >= 0 && y < flags[x].length)
		{
			flags[x][y] &= ~flag;
		}
	}
}

package com.cluehelper.route;

import com.cluehelper.memory.StashMemory;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.step.ClueTypes;
import com.cluehelper.step.EmptySlots;
import com.cluehelper.step.GearBonus;
import com.cluehelper.step.SpadeNeed;
import com.cluehelper.step.Stage;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import com.cluehelper.step.StepRequirements;
import com.cluehelper.transport.AvailabilityService;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import java.util.function.IntFunction;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirements;

/** Client thread only: reads varbits. */
@Singleton
public class StepNeeds
{
	/** Copy of core's {@code ClueScrollOverlay.HAS_SPADE} (1.13.2). */
	private static final ItemRequirement SPADE = ItemRequirements.any("Spade", ItemRequirements.item(ItemID.SPADE),
		ItemRequirements.item(ItemID.EASTER23_SPADE));
	/** Core's {@code ClueScrollOverlay.HAS_LIGHT} item ids (1.13.2). */
	private static final int[] LIGHT_SOURCES = {594, 33, 32, 4531, 4534, 4524, 4539, 4550, 4702, 9065, 5013, 9804, 9805, 13137,
		13138, 13139, 13140, 20720, 29777, 13280, 13342, 26824, 26826, 26828, 26830, 26832, 26834, 26836, 26838, 26840, 26842,
		26844, 26846, 26848, 30363};
	private static final ItemRequirement LIGHT = light();
	/** Core's *clue* bank tag holds a plain spade for these types, and every emote and skill-challenge item. */
	private static final Set<String> SPADE_IN_CORE_TAG = Set.of(ClueTypes.COORDINATE, ClueTypes.HOT_COLD, ClueTypes.FAIRY_RING,
		ClueTypes.MAP, ClueTypes.BEGINNER_MAP);
	private static final Set<String> ITEMS_IN_CORE_TAG = Set.of(ClueTypes.EMOTE, ClueTypes.SKILL);
	private static final int LIT = 1;

	private final Client client;
	private final IntFunction<StashMemory.State> stashStates;
	private final BiFunction<GearBonus, Collection<Integer>, Map<Integer, GearPicker.Piece>> gearPieces;
	private final Supplier<Set<Integer>> ownedItemIds;
	/** One requirement per hand-data entry, so a re-plan's needs equal the last ones. */
	private final Map<StepIndex.Requires, ItemRequirement> wayInItems = new HashMap<>();
	private final Map<StepIndex.Alternative, ItemRequirement> widened = new HashMap<>();

	@Inject
	StepNeeds(Client client, StashMemory stash, GearPieces gearPieces, AvailabilityService availability, PlayerModel player)
	{
		this(client, stash::state, gearPieces::of, () -> ownedItemIds(player.getSnapshot(), availability.getBankedSnapshot()));
	}

	/**
	 * @param client names, real levels and varbits
	 * @param ownedItemIds what gear is picked from: carried, and stored while banking counts
	 */
	public StepNeeds(Client client, IntFunction<StashMemory.State> stashStates,
		BiFunction<GearBonus, Collection<Integer>, Map<Integer, GearPicker.Piece>> gearPieces, Supplier<Set<Integer>> ownedItemIds)
	{
		this.client = client;
		this.stashStates = stashStates;
		this.gearPieces = gearPieces;
		this.ownedItemIds = ownedItemIds;
	}

	public RequiredItems of(Step step)
	{
		StepRequirements requirements = step.getRequirements();
		if (requirements == null)
		{
			return RequiredItems.NONE;
		}
		List<RequiredItems.Need> needs = new ArrayList<>();
		if (requirements.getSpade() == SpadeNeed.SPADE)
		{
			needs.add(new RequiredItems.Need("spade", SPADE, false, SPADE_IN_CORE_TAG.contains(step.getType()), false));
		}
		if (requirements.needsLight() && !firePitLit(requirements))
		{
			needs.add(new RequiredItems.Need("light source", LIGHT, false, false, false));
		}
		boolean inCoreTag = ITEMS_IN_CORE_TAG.contains(step.getType());
		for (ItemRequirement item : requirements.getItems())
		{
			boolean optional = isOptional(item.getCollectiveName(client), step.getData());
			if (!EmptySlots.metByEmptySlots(item) && !optional)
			{
				ItemRequirement need = withAlternatives(item, step.getData());
				needs.add(new RequiredItems.Need(item.getCollectiveName(client), need, true, inCoreTag && need == item, true));
			}
		}
		for (ItemRequirement item : requirements.getOwnItems())
		{
			needs.add(new RequiredItems.Need(item.getCollectiveName(client), item, false, false, true));
		}
		for (StepIndex.Requires way : taskDone(step) ? List.<StepIndex.Requires>of() : step.getData().getRequires())
		{
			needs.add(new RequiredItems.Need(way.getName(), wayInItems.computeIfAbsent(way, StepNeeds::anyOf), false, false, false));
		}
		Set<Integer> owned = step.getData().getGear().isEmpty() ? Set.of() : ownedItemIds.get();
		for (StepIndex.Gear gear : step.getData().getGear())
		{
			GearRequirement worn = new GearRequirement(gear.getName(), gear.getAtLeast(), gearPieces.apply(gear.getBonus(), owned));
			needs.add(new RequiredItems.Need(gear.getName(), worn, false, false, false));
		}
		return RequiredItems.builder()
			.needs(List.copyOf(needs))
			.stash(stash(requirements))
			.spadeAtLeprechaun(client.getVarbitValue(VarbitID.FARMING_TOOLS_SPADE) > 0)
			.build();
	}

	private boolean isOptional(String name, StepIndex.Entry data)
	{
		List<StepIndex.Level> from = data.getOptionalFrom().get(name);
		return data.getOptional().contains(name)
			|| from != null && from.stream().allMatch(level -> client.getRealSkillLevel(level.getSkill()) >= level.getLevel());
	}

	/** Core's item, or the hand data's other way to the same thing; core's bank tag then lacks the other items. */
	private ItemRequirement withAlternatives(ItemRequirement item, StepIndex.Entry data)
	{
		StepIndex.Alternative other = data == null ? null
			: data.getAlternatives().stream().filter(alternative -> item.fulfilledBy(alternative.getInstead())).findFirst().orElse(null);
		if (other == null)
		{
			return item;
		}
		return widened.computeIfAbsent(other, alternative -> new AlternativeRequirement(item, alternative.getAll().stream()
			.map(this::part).collect(Collectors.toList())));
	}

	/** Any of these ids, named by them: "Grimy cadantine or Cadantine". */
	private AlternativeRequirement.Part part(List<Integer> ids)
	{
		String name = ids.stream().map(id -> client.getItemDefinition(id).getName()).distinct().collect(Collectors.joining(" or "));
		return new AlternativeRequirement.Part(name, ItemRequirements.any(name, ids.stream().map(ItemRequirements::item)
			.toArray(ItemRequirement[]::new)));
	}

	/** A skill challenge whose task core marked done: the way to the task's place (a talisman for its ruins) isn't needed. */
	private static boolean taskDone(Step step)
	{
		return ClueTypes.SKILL.equals(step.getType()) && step.getStages().stream().noneMatch(stage -> stage.getKind() == Stage.Kind.TASK);
	}

	/** Gear is picked from all of these, the bank only while banking counts. */
	public static Set<Integer> ownedItemIds(PlayerSnapshot snapshot, PlayerSnapshot banked)
	{
		Set<Integer> ids = new HashSet<>(snapshot == null ? Set.of() : snapshot.carriedIds());
		if (banked != null)
		{
			ids.addAll(banked.storedIds());
		}
		return ids;
	}

	private boolean firePitLit(StepRequirements requirements)
	{
		return requirements.getFirePitVarbitId() != -1 && client.getVarbitValue(requirements.getFirePitVarbitId()) == LIT;
	}

	private StashMemory.State stash(StepRequirements requirements)
	{
		return requirements.hasStash() ? stashStates.apply(requirements.getStashObjectId()) : StashMemory.State.NONE;
	}

	private static ItemRequirement anyOf(StepIndex.Requires way)
	{
		ItemRequirement[] items = way.getIds().stream().map(ItemRequirements::item).toArray(ItemRequirement[]::new);
		return ItemRequirements.any(way.getName(), items);
	}

	private static ItemRequirement light()
	{
		ItemRequirement[] items = new ItemRequirement[LIGHT_SOURCES.length];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = ItemRequirements.item(LIGHT_SOURCES[i]);
		}
		return ItemRequirements.any("Light source", items);
	}
}

