/** The teleports and spellbook changes available on one side of the bank stop, placed by where each is used from. */
final class TransportOptions
{
	/** A row the scroll book rules keep until a bank stop. */
	private static final int AFTER_BANK_ONLY = -1;
	private static final int SWAP_DURATION_TICKS = 4;
	private static final int SWAP_MENU_TICKS = 1;
	/** The house scene loads about a tick after the transport's own landing. */
	private static final int HOUSE_LOAD_HALF_TICKS = 2;

	static final class Teleport
	{
		CatalogRow row;
		int node;
		int halfTicks;
		Book book;
		int[] res;
		int[] amounts;
		int[] withdraw;
		List<ItemUse> withdrawUses;
		RowAvailability.Confidence confidence;
		boolean minigame;
		int maxWilderness;
	}

	static final class Change
	{
		SpellbookChange change;
		int node = WalkTable.NO_NODE;
		int halfTicks;
		int[] res;
		int[] amounts;
		int[] withdraw;
		List<ItemUse> withdrawUses;
		boolean capeUse;
		RowAvailability.Confidence confidence;
	}

	final List<Teleport> teleports = new ArrayList<>();
	final Map<Integer, Teleport> fairyEntries = new HashMap<>();
	final List<Teleport> fairyLandings = new ArrayList<>();
	/** Transports that start at a node: house furniture, spirit trees, Renu. */
	final Map<Integer, List<Teleport>> located = new HashMap<>();
	final Map<Integer, List<Change>> changes = new HashMap<>();
	Change cape;
	Change swap;

	private final PlanContext ctx;

	TransportOptions(PlanContext ctx, PlayerSnapshot player, int bankState)
	{
		this.ctx = ctx;
		PlayerSnapshot judgedAt = player.toBuilder().wildernessLevel(0).build();
		addTeleports(player, judgedAt, bankState);
		addChanges(player, judgedAt, bankState);
	}

	/** Every available teleport row, placed by where it is used from; of a home or minigame row's variants, the longest. */
	private void addTeleports(PlayerSnapshot player, PlayerSnapshot judgedAt, int bankState)
	{
		boolean carriesBook = player.carried(BookScrolls.BOOK) > 0;
		Map<String, Teleport> longestVariant = new LinkedHashMap<>();
		for (CatalogRow row : ctx.in.getCatalog().getTeleports())
		{
			if (ctx.in.getRefusedChanges().contains(row.getName()))
			{
				continue;
			}
			RowAvailability judged = ctx.in.getEngine().judge(row, judgedAt, ctx.in.getNowMinutes());
			if (!judged.isAvailable())
			{
				continue;
			}
			int bookStop = scrollBookHalfTicks(row, carriesBook, bankState);
			if (bookStop == AFTER_BANK_ONLY)
			{
				continue;
			}
			Teleport tele = teleport(judged, player, bankState);
			tele.halfTicks += bookStop;
			place(row, tele, player, longestVariant);
		}
		teleports.addAll(longestVariant.values());
		keepMostVersatileWithdraws(teleports);
	}

	/**
	 * The master scroll book's own Wilderness teleport reads a scroll taken out at the bank, and any Wilderness teleport
	 * banks a carried book first: the half-ticks that costs, or {@link #AFTER_BANK_ONLY} before the bank stop.
	 */
	private int scrollBookHalfTicks(CatalogRow row, boolean carriesBook, int bankState)
	{
		boolean bookStaysOut = ctx.in.getSettings().isScrollBookOutOfWilderness();
		boolean takenOut = BookScrolls.isTakenOutAtBank(row, bookStaysOut);
		boolean bankedFirst = !takenOut && bookStaysOut && carriesBook && BookScrolls.intoWilderness(row);
		if ((takenOut || bankedFirst) && bankState != PlanContext.BANKED)
		{
			return AFTER_BANK_ONLY;
		}
		return takenOut ? 2 * BookScrolls.TAKE_OUT_TICKS : bankedFirst ? 2 * BookScrolls.DEPOSIT_TICKS : 0;
	}

	/** A fairy ring entry, a transport used where it stands, a fairy ring landing, or a plain teleport by its variant. */
	private void place(CatalogRow row, Teleport tele, PlayerSnapshot player, Map<String, Teleport> longestVariant)
	{
		if (row.getOrigin() != null && row.getCategory() == Category.FAIRY_RING)
		{
			tele.node = ctx.nodeAt(row.getOrigin());
			tele.halfTicks += houseWalkHalfTicks(row.getRequirements(), player);
			fairyEntries.merge(tele.node, tele, (a, b) -> a.halfTicks <= b.halfTicks ? a : b);
		}
		else if (row.getOrigin() != null)
		{
			int from = ctx.nodeAt(row.getOrigin());
			tele.halfTicks += from == ctx.pohNode ? houseWalkHalfTicks(row.getRequirements(), player) : 0;
			located.computeIfAbsent(from, k -> new ArrayList<>()).add(tele);
		}
		else if (row.getCode() != null)
		{
			fairyLandings.add(tele);
		}
		else
		{
			longestVariant.merge(variantKey(row), tele, (a, b) -> a.halfTicks >= b.halfTicks ? a : b);
		}
	}

	/** Every available spellbook change: the Swap, the first cape, and the altars and Tyss where they stand. */
	private void addChanges(PlayerSnapshot player, PlayerSnapshot judgedAt, int bankState)
	{
		for (SpellbookChange change : ctx.in.getCatalog().getSpellbookChanges())
		{
			if (change.isInHouse() && ctx.pohNode == WalkTable.NO_NODE || ctx.in.getRefusedChanges().contains(change.getName()))
			{
				continue;
			}
			CatalogRow asRow = CatalogRow.builder().name(change.getName()).requirements(change.getRequirements()).build();
			RowAvailability judged = ctx.in.getEngine().judge(asRow, judgedAt, ctx.in.getNowMinutes());
			if (!judged.isAvailable())
			{
				continue;
			}
			Change c = change(change, judged, player, bankState);
			if (change.isTemporary())
			{
				swap = c;
			}
			else if (change.isAnywhere())
			{
				cape = cape == null ? c : cape;
			}
			else
			{
				c.node = change.isInHouse() ? ctx.pohNode : ctx.nodeAt(change.getTile());
				c.halfTicks += houseWalkHalfTicks(change.getRequirements(), player);
				changes.computeIfAbsent(c.node, k -> new ArrayList<>()).add(c);
			}
		}
	}

	/** Prefers e.g. the Max cape over a Construction cape that gives the same teleport. */
	private void keepMostVersatileWithdraws(List<Teleport> all)
	{
		Map<String, Teleport> kept = new HashMap<>();
		for (Teleport tele : all)
		{
			if (tele.withdraw.length > 0)
			{
				kept.merge(sameTeleportKey(tele), tele, (a, b) -> ctx.versatility(b.withdraw) > ctx.versatility(a.withdraw) ? b : a);
			}
		}
		all.removeIf(tele -> tele.withdraw.length > 0 && kept.get(sameTeleportKey(tele)) != tele);
	}

	private String sameTeleportKey(Teleport tele)
	{
		return tele.node + "|" + tele.halfTicks + "|" + tele.book;
	}

	/** Home and minigame rows come once per animation override; with several on, the game picks one, so the longest counts. */
	private String variantKey(CatalogRow row)
	{
		return row.getCategory() + "|" + row.getName() + "|" + row.getDestination() + "|" + row.getRequirements().getBook();
	}

	private Teleport teleport(RowAvailability judged, PlayerSnapshot player, int bankState)
	{
		CatalogRow row = judged.getRow();
		Teleport tele = new Teleport();
		tele.row = row;
		tele.node = row.getDestination() == null ? WalkTable.NO_NODE : ctx.nodeAt(row.getDestination());
		tele.halfTicks = 2 * (row.getDuration() + row.getMenuTicks())
			+ (tele.node != WalkTable.NO_NODE && tele.node == ctx.pohNode ? HOUSE_LOAD_HALF_TICKS : 0);
		tele.book = row.getRequirements().getBook();
		tele.confidence = judged.getConfidence();
		tele.minigame = row.getCategory() == Category.MINIGAME;
		tele.maxWilderness = row.getRequirements().getMaxWildernessLevel();
		Spending spending = spending(row.getSpends(), judged.getWitness(), player, bankState);
		tele.res = spending.res;
		tele.amounts = spending.amounts;
		tele.withdrawUses = withdrawUses(judged.getWitness());
		tele.withdraw = ids(tele.withdrawUses);
		return tele;
	}

	private Change change(SpellbookChange change, RowAvailability judged, PlayerSnapshot player, int bankState)
	{
		Change c = new Change();
		c.change = change;
		c.halfTicks = change.isTemporary() ? 2 * (SWAP_DURATION_TICKS + SWAP_MENU_TICKS) : 2 * (change.getDuration() + change.getMenuTicks());
		c.capeUse = change.getSpends().stream().anyMatch(s -> s.getKind() == Spend.Kind.CAPE_USE);
		c.confidence = judged.getConfidence();
		Spending spending = spending(change.getSpends(), judged.getWitness(), player, bankState);
		c.res = spending.res;
		c.amounts = spending.amounts;
		c.withdrawUses = withdrawUses(judged.getWitness());
		c.withdraw = ids(c.withdrawUses);
		return c;
	}

	private static final class Spending
	{
		int[] res;
		int[] amounts;
	}

	private Spending spending(List<Spend> spends, List<ItemUse> witness, PlayerSnapshot player, int bankState)
	{
		Map<Integer, Integer> units = new LinkedHashMap<>();
		for (Spend spend : spends)
		{
			switch (spend.getKind())
			{
				case RUNES:
				case ITEM:
					for (ItemUse use : witness)
					{
						if (use.getContainer() != Container.WORN)
						{
							int r = ctx.resources.item(use.getItemId(), player, bankState);
							units.merge(r, use.getQuantity(), Integer::sum);
						}
					}
					break;
				case CHARGE:
					for (ItemUse use : witness)
					{
						units.merge(ctx.resources.charge(use.getItemId(), player, bankState), 1, Integer::sum);
					}
					break;
				case COOLDOWN:
					units.merge(ctx.resources.once("cooldown:" + spend.getVar(), bankState), 1, Integer::sum);
					break;
				case DAILY:
					units.merge(ctx.resources.once("daily:" + spend.getVar(), bankState), 1, Integer::sum);
					break;
				case CAPE_USE:
					SpellbookState state = player.getSpellbook();
					units.merge(ctx.resources.capeUses(state == null ? 0 : state.getCapeChangesLeft(), bankState), 1, Integer::sum);
					break;
				default:
					throw new IllegalArgumentException("unhandled spend " + spend.getKind());
			}
		}
		units.forEach(ctx.resources::used);
		Spending s = new Spending();
		s.res = units.keySet().stream().mapToInt(Integer::intValue).toArray();
		s.amounts = units.values().stream().mapToInt(Integer::intValue).toArray();
		return s;
	}

	private static int houseWalkHalfTicks(Requirements requirements, PlayerSnapshot player)
	{
		HouseNeed need = requirements.getHouse();
		if (need == null)
		{
			return 0;
		}
		HouseState house = player.getHouse();
		return 2 * house.walkTicks(need.getKind() == HouseNeed.Kind.NEXUS ? HouseState.NEXUS_OBJECTS : need.getIds());
	}

	private static List<ItemUse> withdrawUses(List<ItemUse> witness)
	{
		List<ItemUse> stored = new ArrayList<>();
		for (ItemUse use : witness)
		{
			if (use.getContainer().isStored())
			{
				stored.add(use);
			}
		}
		return List.copyOf(stored);
	}

	private static int[] ids(List<ItemUse> uses)
	{
		return uses.stream().mapToInt(ItemUse::getItemId).distinct().sorted().toArray();
	}
}

package com.cluehelper.route;

import net.runelite.api.coords.WorldPoint;

/**
 * The walk from one tile to every tile near it, as far as a table walk goes: what the planner's start legs and the
 * guide's arrival checks cost. An {@link Exit} (a cave, a dungeon's ladder) ends the walk at its landing, so a route
 * goes on from that landing's node and the guide can name the exit. Costs are tiles, half-ticks when running.
 * Immutable once built; any thread.
 */
public final class WalkCosts
{
	public static final int UNREACHED = WalkSearch.UNREACHED;
	/** As far as a walk of the table, so a start partway along one reaches the node it leads to. */
	private static final int MAX_TILES = 200;
	/** A node stands this close to an exit's landing. */
	private static final int BESIDE_TILES = 2;

	private final Ground ground;
	private final WorldPoint start;
	private final WalkSearch search;

	private WalkCosts(Ground ground, WorldPoint start, WalkSearch search)
	{
		this.ground = ground;
		this.start = start;
		this.search = search;
	}

	public static WalkCosts from(Ground ground, WorldPoint start)
	{
		WalkSearch search = new WalkSearch(ground, MAX_TILES, true);
		search.run(WalkTable.pack(start), (tile, cost) -> UNREACHED);
		return new WalkCosts(ground, start, search);
	}

	public WorldPoint getStart()
	{
		return start;
	}

	/** The loaded scene the walk was searched over, its doors open; null when none was. */
	public LoadedScene getScene()
	{
		return ground.getScene();
	}

	/** The walk to the tile, or to the landing of an exit within 2 tiles of it (the exit's node); else UNREACHED. */
	public int cost(WorldPoint tile)
	{
		if (tile == null)
		{
			return UNREACHED;
		}
		int cost = search.cost(WalkTable.pack(tile));
		if (cost != UNREACHED)
		{
			return cost;
		}
		int landing = exitLandingBy(tile);
		return landing == WalkSearch.NONE ? UNREACHED : search.cost(landing);
	}

	/** The exit a walk to {@code tile} leaves by, when the tile is its landing's node; else null. */
	public Exit exitTo(WorldPoint tile)
	{
		if (tile == null)
		{
			return null;
		}
		int packed = WalkTable.pack(tile);
		if (search.cost(packed) != UNREACHED)
		{
			int via = search.via(packed);
			return via != WalkSearch.NONE && ground.isExitRow(via) ? ground.exit(via) : null;
		}
		int landing = exitLandingBy(tile);
		return landing == WalkSearch.NONE ? null : ground.exit(search.via(landing));
	}

	/**
	 * The walk to a tile by {@code tile}: itself, else a straight neighbour with no wall between (a crate, a fairy
	 * ring), else the nearest within 2 tiles.
	 */
	public int costNear(WorldPoint tile)
	{
		if (cost(tile) != UNREACHED)
		{
			return cost(tile);
		}
		int best = UNREACHED;
		int bestDistance = Integer.MAX_VALUE;
		for (int dx = -BESIDE_TILES; dx <= BESIDE_TILES; dx++)
		{
			for (int dy = -BESIDE_TILES; dy <= BESIDE_TILES; dy++)
			{
				WorldPoint near = tile.dx(dx).dy(dy);
				int c = cost(near);
				int distance = opensOnto(near, tile) ? 0 : Math.max(Math.abs(dx), Math.abs(dy));
				if (c != UNREACHED && (distance < bestDistance || distance == bestDistance && c < best))
				{
					best = c;
					bestDistance = distance;
				}
			}
		}
		return best;
	}

	/**
	 * The cheapest tile on a straight side of the object: the game walks to a side to use it, never a corner. A side
	 * with no wall between it and the object wins: stairs against a bank's outer wall face inwards. Null when none.
	 */
	public WorldPoint cheapestBeside(WorldPoint southWest, int sizeX, int sizeY)
	{
		WorldPoint best = null;
		int bestCost = UNREACHED;
		boolean bestOpen = false;
		for (int x = -1; x <= sizeX; x++)
		{
			for (int y = -1; y <= sizeY; y++)
			{
				boolean outsideX = x == -1 || x == sizeX;
				boolean outsideY = y == -1 || y == sizeY;
				WorldPoint tile = southWest.dx(x).dy(y);
				int c = outsideX != outsideY ? cost(tile) : UNREACHED;
				boolean open = c != UNREACHED
					&& opensOnto(tile, southWest.dx(Math.max(0, Math.min(sizeX - 1, x))).dy(Math.max(0, Math.min(sizeY - 1, y))));
				if (c != UNREACHED && (open && !bestOpen || open == bestOpen && c < bestCost))
				{
					best = tile;
					bestCost = c;
					bestOpen = open;
				}
			}
		}
		return best;
	}

	public int reachedTiles()
	{
		return search.reachedTiles();
	}

	private boolean opensOnto(WorldPoint from, WorldPoint to)
	{
		int dx = to.getX() - from.getX();
		int dy = to.getY() - from.getY();
		return from.getPlane() == to.getPlane() && Math.abs(dx) + Math.abs(dy) == 1
			&& !ground.isWallBetween(from.getX(), from.getY(), from.getPlane(), dx, dy);
	}

	/** The cheapest reached exit landing within 2 tiles of the tile. */
	private int exitLandingBy(WorldPoint tile)
	{
		int best = WalkSearch.NONE;
		int bestCost = UNREACHED;
		for (int landing : search.exitLandings())
		{
			boolean near = WalkSearch.plane(landing) == tile.getPlane()
				&& Math.max(Math.abs(WalkSearch.x(landing) - tile.getX()), Math.abs(WalkSearch.y(landing) - tile.getY())) <= BESIDE_TILES;
			if (near && search.cost(landing) < bestCost)
			{
				best = landing;
				bestCost = search.cost(landing);
			}
		}
		return best;
	}
}

package com.cluehelper.route;

import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class WalkData
{
	@Value
	public static class Loaded
	{
		WalkTable table;
		NoTeleportAreas noTeleport;
		WorldMap map;
	}

	private final CompletableFuture<Loaded> loaded;

	@Inject
	WalkData(ScheduledExecutorService executor)
	{
		loaded = CompletableFuture.supplyAsync(WalkData::loadOrNull, executor);
	}

	public CompletableFuture<Loaded> get()
	{
		return loaded;
	}

	private static Loaded loadOrNull()
	{
		try
		{
			long started = System.nanoTime();
			Loaded data = new Loaded(WalkTable.load(), NoTeleportAreas.load(), WorldMap.load());
			log.debug("walk data: {} nodes, {} entries, {} rows in {} ms", data.getTable().nodeCount(), data.getTable().entryCount(),
				data.getTable().rowCount(), (System.nanoTime() - started) / 1_000_000);
			return data;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("the bundled walk data is unreadable: no routes will be planned", e);
			return null;
		}
	}
}

package com.cluehelper.route;

import com.cluehelper.player.Container;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.transport.AvailabilityEngine;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.Requirements;
import com.cluehelper.transport.RowAvailability;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.IntStream;
import net.runelite.api.gameval.ItemID;

/** An unread var fails its gate, so an unread account walks the always-open way. */
public final class WalkGates
{
	private static final int[] NOTHING = new int[0];
	/** Any tier cuts a web on the first slash; a knife does half the time, other blades at most as often. */
	private static final Set<Integer> WILDERNESS_SWORDS = Set.of(ItemID.WILDERNESS_SWORD_EASY, ItemID.WILDERNESS_SWORD_MEDIUM,
		ItemID.WILDERNESS_SWORD_HARD, ItemID.WILDERNESS_SWORD_ELITE);
	/** Assumed: the knife's 50%, so one slash more on average. */
	private static final int EXPECTED_SLASHES_WITHOUT_SWORD = 2;
	/** Assumed, as Shortest Path's 4-tick web row includes the two steps through. */
	private static final int SLASH_TICKS = 2;
	private static final int RETRY_HALF_TICKS = 2 * SLASH_TICKS * (EXPECTED_SLASHES_WITHOUT_SWORD - 1);

	private final WalkTable table;
	private final boolean[] gatePass;
	private final boolean[] setPass;
	/** Stored items a passing gate takes, such as a banked knife for a web; carried ones are preferred. */
	private final int[][] gateWithdraw;
	private final int[][] setWithdraw;
	private final int[] gateExtra;
	private final int[] setExtra;

	public WalkGates(WalkTable table, PlayerSnapshot player, AvailabilityEngine engine, long nowMinutes)
	{
		this.table = table;
		List<Requirements> gates = table.getGates();
		gatePass = new boolean[gates.size() + 1];
		gateWithdraw = new int[gates.size() + 1][];
		gateExtra = new int[gates.size() + 1];
		gatePass[0] = true;
		gateWithdraw[0] = NOTHING;
		for (int g = 0; g < gates.size(); g++)
		{
			CatalogRow asRow = CatalogRow.builder().name("gate " + (g + 1)).requirements(gates.get(g)).build();
			RowAvailability judged = engine.judge(asRow, player, nowMinutes);
			gatePass[g + 1] = judged.isAvailable();
			gateWithdraw[g + 1] = judged.isAvailable() ? storedIds(judged) : NOTHING;
			if (judged.isAvailable() && isSlash(gates.get(g)))
			{
				slashWith(g + 1, judged, player);
			}
		}
		setPass = new boolean[table.gateSetCount() + 1];
		setWithdraw = new int[table.gateSetCount() + 1][];
		setExtra = new int[table.gateSetCount() + 1];
		setPass[0] = true;
		setWithdraw[0] = NOTHING;
		for (int s = 1; s <= table.gateSetCount(); s++)
		{
			boolean pass = true;
			TreeSet<Integer> withdraw = new TreeSet<>();
			for (int gate : table.gateSet(s))
			{
				pass &= gatePass[gate];
				IntStream.of(gateWithdraw[gate]).forEach(withdraw::add);
				setExtra[s] += gateExtra[gate];
			}
			setPass[s] = pass;
			setWithdraw[s] = pass ? withdraw.stream().mapToInt(Integer::intValue).toArray() : NOTHING;
		}
	}

	/** {@link WalkTable#NO_PATH} when the failed gates block every way. */
	public int cost(int entry)
	{
		int set = table.entryGateSet(entry);
		return setPass[set] ? table.entryFull(entry) + setExtra[set] : table.entryOpen(entry);
	}

	/** Sorted item ids to take from the bank for {@link #cost}'s walk. */
	public int[] withdraw(int entry)
	{
		return setWithdraw[table.entryGateSet(entry)];
	}

	/** Sorted: every stored item some gate takes. */
	public int[] storedGateItems()
	{
		return IntStream.range(1, gateWithdraw.length).flatMap(g -> IntStream.of(gateWithdraw[g])).distinct().sorted().toArray();
	}

	public boolean[] rowOpen()
	{
		boolean[] open = new boolean[table.rowCount()];
		for (int r = 0; r < open.length; r++)
		{
			open[r] = gatePass[table.rowGate(r)];
		}
		return open;
	}

	private static boolean isSlash(Requirements gate)
	{
		return gate.getItems().stream().anyMatch(clause -> clause.getBranches().stream()
			.anyMatch(branch -> branch.getIds().stream().anyMatch(WILDERNESS_SWORDS::contains)));
	}

	/** A carried blade beats fetching the sword, which costs about what the retries do; a stored sword beats any stored blade. */
	private void slashWith(int gate, RowAvailability judged, PlayerSnapshot player)
	{
		boolean bySword = judged.getWitness().stream().anyMatch(use -> WILDERNESS_SWORDS.contains(use.getItemId()));
		if (bySword)
		{
			return;
		}
		int storedSword = gateWithdraw[gate].length == 0 ? -1 : storedSword(player);
		if (storedSword != -1)
		{
			gateWithdraw[gate] = new int[] {storedSword};
			return;
		}
		gateExtra[gate] = RETRY_HALF_TICKS;
	}

	private static int storedSword(PlayerSnapshot player)
	{
		for (int sword : WILDERNESS_SWORDS)
		{
			if (player.stored(sword) > 0)
			{
				return sword;
			}
		}
		return -1;
	}

	private static int[] storedIds(RowAvailability judged)
	{
		return judged.getWitness().stream()
			.filter(use -> use.getContainer().isStored())
			.mapToInt(ItemUse::getItemId).distinct().sorted().toArray();
	}
}

package com.cluehelper.route;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** Where a walk ends: on a tile, or where the game stops to use an object. */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class WalkGoal
{
	WorldPoint southWest;
	int sizeX;
	int sizeY;
	boolean object;

	public static WalkGoal tile(WorldPoint tile)
	{
		return new WalkGoal(tile, 1, 1, false);
	}

	/** The game walks to the first tile it finds on a straight side of the object with no wall between. */
	public static WalkGoal object(WorldPoint southWest, int sizeX, int sizeY)
	{
		return new WalkGoal(southWest, sizeX, sizeY, true);
	}

	/** On a straight side of the object, outside it, with no wall between. */
	boolean isUsedFrom(Ground ground, int x, int y, int plane)
	{
		int west = southWest.getX();
		int south = southWest.getY();
		int east = west + sizeX - 1;
		int north = south + sizeY - 1;
		if (plane != southWest.getPlane())
		{
			return false;
		}
		boolean besideX = x == west - 1 || x == east + 1;
		boolean besideY = y == south - 1 || y == north + 1;
		boolean alongX = x >= west && x <= east;
		boolean alongY = y >= south && y <= north;
		if (besideX == besideY || besideX && !alongY || besideY && !alongX)
		{
			return false;
		}
		int dx = x < west ? 1 : x > east ? -1 : 0;
		int dy = y < south ? 1 : y > north ? -1 : 0;
		return !ground.isWallBetween(x, y, plane, dx, dy);
	}
}

package com.cluehelper.route;

import java.util.Arrays;

/**
 * The cheapest walk from one tile over a {@link Ground}, tile by tile in {@link Directions} order: each step one tile,
 * a closed door a few more, a walk row its own cost. One search per instance; once run, read from any thread.
 */
final class WalkSearch
{
	static final int UNREACHED = Integer.MAX_VALUE;
	static final int NONE = -1;
	private static final int BUCKETS = 1024;

	/** Told of each tile as its cost settles: the cost after which the search may stop, or {@link #UNREACHED}. */
	interface Stop
	{
		int after(int tile, int cost);
	}

	private final Ground ground;
	private final int maxCost;
	private final boolean exitsEnd;
	private final int slotMask;
	private final int slotShift;
	private final int[] keys;
	private final int[] costs;
	private final int[] parents;
	private final int[] vias;
	private final boolean[] used;
	private final IntList exitLandings = new IntList();
	private int reached;
	private int settledBelow;

	/**
	 * @param maxCost no tile past this cost is reached
	 * @param exitsEnd an {@link Exit} row's landing is reached but not walked on from: a route goes on from its node
	 */
	WalkSearch(Ground ground, int maxCost, boolean exitsEnd)
	{
		this.ground = ground;
		this.maxCost = maxCost;
		this.exitsEnd = exitsEnd;
		int slots = Integer.highestOneBit(ground.tileLimit()) << 2;
		slotMask = slots - 1;
		slotShift = Integer.SIZE - Integer.numberOfTrailingZeros(slots);
		keys = new int[slots];
		costs = new int[slots];
		parents = new int[slots];
		vias = new int[slots];
		used = new boolean[slots];
	}

	void run(int start, Stop stop)
	{
		IntList[] buckets = new IntList[BUCKETS];
		for (int i = 0; i < BUCKETS; i++)
		{
			buckets[i] = new IntList();
		}
		improve(start, 0, NONE, NONE);
		buckets[0].add(start);
		int pending = 1;
		int stopAfter = UNREACHED;
		int cost = 0;
		for (; pending > 0 && cost <= stopAfter && reached < ground.tileLimit(); cost++)
		{
			IntList bucket = buckets[cost % BUCKETS];
			for (int i = 0; i < bucket.size; i++)
			{
				int tile = bucket.data[i];
				pending--;
				if (costOf(tile) != cost)
				{
					continue;
				}
				reached++;
				stopAfter = Math.min(stopAfter, stop.after(tile, cost));
				int via = vias[slot(tile)];
				if (via != NONE && ground.isExitRow(via))
				{
					exitLandings.add(tile);
					if (exitsEnd)
					{
						continue;
					}
				}
				pending += expand(buckets, tile, cost);
			}
			bucket.size = 0;
		}
		settledBelow = cost;
	}

	/** The tile's cost once settled, else {@link #UNREACHED}. */
	int cost(int tile)
	{
		int cost = costOf(tile);
		return cost < settledBelow ? cost : UNREACHED;
	}

	/** The tile the walk to {@code tile} came from, or {@link #NONE} at the start. */
	int parent(int tile)
	{
		return parents[slot(tile)];
	}

	/** The row the walk took into {@code tile}, or {@link #NONE} for a step. */
	int via(int tile)
	{
		return vias[slot(tile)];
	}

	int reachedTiles()
	{
		return reached;
	}

	/** The landings of the {@link Exit} rows reached, packed. */
	int[] exitLandings()
	{
		return Arrays.copyOf(exitLandings.data, exitLandings.size);
	}

	/** The walk to {@code end}, packed tiles from the start on. */
	int[] trace(int end)
	{
		IntList back = new IntList();
		for (int tile = end; tile != NONE; tile = parent(tile))
		{
			back.add(tile);
		}
		int[] path = new int[back.size];
		for (int i = 0; i < back.size; i++)
		{
			path[i] = back.data[back.size - 1 - i];
		}
		return path;
	}

	private int expand(IntList[] buckets, int tile, int cost)
	{
		int x = x(tile);
		int y = y(tile);
		int plane = plane(tile);
		int pushed = 0;
		for (int row : ground.openRowsFrom(tile))
		{
			pushed += push(buckets, ground.rowDestination(row), cost + ground.rowCost(row), tile, row);
		}
		for (int d = 0; d < Directions.COUNT; d++)
		{
			int nx = x + Directions.DX[d];
			int ny = y + Directions.DY[d];
			int next = WalkTable.pack(nx, ny, plane);
			if (ground.canMove(x, y, plane, d))
			{
				pushed += push(buckets, next, cost + ground.stepCost(x, y, plane, d), tile, NONE);
			}
			else if (d < Directions.STRAIGHT && ground.isBlocked(nx, ny, plane) && ground.openRowsFrom(next).length > 0)
			{
				pushed += push(buckets, next, cost + 1, tile, NONE);
			}
		}
		return pushed;
	}

	private int push(IntList[] buckets, int tile, int cost, int from, int via)
	{
		if (cost > maxCost || !improve(tile, cost, from, via))
		{
			return 0;
		}
		buckets[cost % BUCKETS].add(tile);
		return 1;
	}

	private int costOf(int tile)
	{
		int h = slot(tile);
		return used[h] ? costs[h] : UNREACHED;
	}

	private boolean improve(int tile, int cost, int from, int via)
	{
		int h = slot(tile);
		if (used[h] && costs[h] <= cost)
		{
			return false;
		}
		used[h] = true;
		keys[h] = tile;
		costs[h] = cost;
		parents[h] = from;
		vias[h] = via;
		return true;
	}

	private int slot(int tile)
	{
		int h = tile * 0x9E3779B1 >>> slotShift;
		while (used[h] && keys[h] != tile)
		{
			h = h + 1 & slotMask;
		}
		return h;
	}

	static int x(int tile)
	{
		return tile & 0x3FFF;
	}

	static int y(int tile)
	{
		return tile >>> 14 & 0x3FFF;
	}

	static int plane(int tile)
	{
		return tile >>> 28;
	}

	private static final class IntList
	{
		int[] data = new int[256];
		int size;

		void add(int value)
		{
			if (size == data.length)
			{
				data = Arrays.copyOf(data, size * 2);
			}
			data[size++] = value;
		}
	}
}

package com.cluehelper.route;

import com.cluehelper.transport.RequirementParser;
import com.cluehelper.transport.Requirements;
import java.io.BufferedReader;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/** Immutable once loaded; any thread. Costs are tiles, which are half-ticks when running. */
public final class WalkTable
{
	public static final int NO_NODE = -1;
	public static final int NO_PATH = -1;
	static final String DIRECTORY = "walk/";

	public static final int KIND_LANDING = 1;
	public static final int KIND_ORIGIN = 1 << 1;
	public static final int KIND_BANK = 1 << 2;
	public static final int KIND_TARGET = 1 << 3;
	private static final int KIND_POH = 1 << 4;
	public static final int KIND_CHANGE = 1 << 5;
	private static final int KIND_ENTRY = 1 << 6;
	/** Where a far walk row lands: only start legs walk from it, nothing walks to it. */
	private static final int KIND_EXIT = 1 << 7;
	private static final Map<String, Integer> KIND_BITS = Map.of("landing", KIND_LANDING, "origin", KIND_ORIGIN,
		"bank", KIND_BANK, "target", KIND_TARGET, "poh", KIND_POH, "change", KIND_CHANGE, "entry", KIND_ENTRY, "exit", KIND_EXIT);

	private WorldPoint[] tiles = new WorldPoint[0];
	private WorldPoint[] placed = new WorldPoint[0];
	private int[] kinds = new int[0];
	private final Map<WorldPoint, Integer> byTile = new HashMap<>();

	private int[] entryStart = {0};
	private int[] entryTo = new int[0];
	private int[] entryFull = new int[0];
	private int[] entryGateSet = new int[0];
	private int[] entryOpen = new int[0];
	private int[] reverseStart = {0};
	private int[] reverseEntry = new int[0];
	private int[] entryFrom = new int[0];
	private int[][] gateSets = new int[0][];
	private List<Requirements> gates = List.of();
	private Map<Integer, List<Bank>> banks = Map.of();

	private int[] rowOrigin = new int[0];
	private int[] rowDest = new int[0];
	private int[] rowCost = new int[0];
	private int[] rowGate = new int[0];
	private static final int[] NO_ROWS = new int[0];
	private Map<Integer, int[]> rowsByOrigin = Map.of();
	private boolean[] rowIsExit = new boolean[0];
	private Map<Long, Exit> exits = Map.of();
	private Map<Long, Exit> rowObjects = Map.of();
	/** Each row object's id by the packed tiles its rows start from. */
	private Map<Integer, Set<Integer>> rowObjectsAt = Map.of();

	private WalkTable()
	{
	}

	public static WalkTable load() throws IOException
	{
		WalkTable table = new WalkTable();
		table.readNodes(lines("nodes.tsv"));
		table.readGates(lines("gates.tsv"));
		table.readTable(new Varints(bytes("table.bin")));
		table.readRows(new Varints(bytes("rows.bin")));
		table.readBanks(lines("banks.tsv"));
		table.exits = rowActions(lines("exits.tsv"));
		table.markExitRows();
		table.rowObjects = rowActions(lines("row-objects.tsv"));
		table.rowObjectsAt = table.rowObjects.values().stream().collect(Collectors.groupingBy(exit -> pack(exit.getOrigin()),
			Collectors.mapping(Exit::getObjectId, Collectors.toUnmodifiableSet())));
		table.indexReverse();
		return table;
	}

	public int nodeCount()
	{
		return tiles.length;
	}

	public WorldPoint tile(int node)
	{
		return tiles[node];
	}

	/** The walkable tile the node snaps to; null when none is within 2 tiles. */
	public WorldPoint placed(int node)
	{
		return placed[node];
	}

	public boolean is(int node, int kind)
	{
		return (kinds[node] & kind) != 0;
	}

	public int node(WorldPoint tile)
	{
		return tile == null ? NO_NODE : byTile.getOrDefault(tile, NO_NODE);
	}

	public int entriesFrom(int node)
	{
		return entryStart[node];
	}

	public int entriesEnd(int node)
	{
		return entryStart[node + 1];
	}

	public int entryTo(int entry)
	{
		return entryTo[entry];
	}

	/** The cost when every gate on the path passes. */
	public int entryFull(int entry)
	{
		return entryFull[entry];
	}

	/** 0 when the path uses no gated row; else an index into {@link #gateSet(int)}. */
	public int entryGateSet(int entry)
	{
		return entryGateSet[entry];
	}

	/** The cost using always-open rows only, or {@link #NO_PATH}; meaningful only for a gated entry. */
	public int entryOpen(int entry)
	{
		return entryOpen[entry];
	}

	public int gateSetCount()
	{
		return gateSets.length;
	}

	/** Gate ids (1-based) used by entries with this gate set (1-based). */
	public int[] gateSet(int set)
	{
		return gateSets[set - 1];
	}

	/** Index = gate id − 1. */
	public List<Requirements> getGates()
	{
		return gates;
	}

	public List<Bank> banks(int node)
	{
		return banks.getOrDefault(node, List.of());
	}

	public int rowCount()
	{
		return rowOrigin.length;
	}

	public WorldPoint rowOrigin(int row)
	{
		return unpack(rowOrigin[row]);
	}

	public WorldPoint rowDest(int row)
	{
		return unpack(rowDest[row]);
	}

	public int rowCost(int row)
	{
		return rowCost[row];
	}

	/** The row is an {@link Exit}: it leaves for a far landing (a cave, a dungeon's ladder). */
	boolean isExitRow(int row)
	{
		return rowIsExit[row];
	}

	/** The rows that start on the packed tile ({@link #pack}). */
	int[] rowsFrom(int tile)
	{
		return rowsByOrigin.getOrDefault(tile, NO_ROWS);
	}

	/** The packed tile the row lands on. */
	int rowDestTile(int row)
	{
		return rowDest[row];
	}

	/** 0 for an always-open row, else a gate id. */
	public int rowGate(int row)
	{
		return rowGate[row];
	}

	/** Null unless the row from {@code origin} to {@code destination} is an {@link Exit}. */
	public Exit exit(WorldPoint origin, WorldPoint destination)
	{
		return exits.get(exitKey(origin, destination));
	}

	/** The object clicked to take the row from {@code origin} to {@code destination} (a ladder, a door), or null. */
	public Exit rowObject(WorldPoint origin, WorldPoint destination)
	{
		return rowObjects.get(exitKey(origin, destination));
	}

	/** A row starts by {@code tile} (on it or next to it) through the object: the same id elsewhere says nothing. */
	public boolean isRowObjectAt(int objectId, WorldPoint tile)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (rowObjectsAt.getOrDefault(pack(tile.dx(dx).dy(dy)), Set.of()).contains(objectId))
				{
					return true;
				}
			}
		}
		return false;
	}

	public int entryCount()
	{
		return entryTo.length;
	}

	/** Entries that walk into {@code node}: {@code reverseEntry(i)} for i in [reverseFrom, reverseEnd). */
	public int reverseFrom(int node)
	{
		return reverseStart[node];
	}

	public int reverseEnd(int node)
	{
		return reverseStart[node + 1];
	}

	public int reverseEntry(int index)
	{
		return reverseEntry[index];
	}

	public int entryFrom(int entry)
	{
		return entryFrom[entry];
	}

	private void indexReverse()
	{
		int nodes = tiles.length;
		entryFrom = new int[entryTo.length];
		reverseStart = new int[nodes + 1];
		for (int node = 0; node < nodes; node++)
		{
			for (int e = entryStart[node]; e < entryStart[node + 1]; e++)
			{
				entryFrom[e] = node;
				reverseStart[entryTo[e] + 1]++;
			}
		}
		for (int node = 0; node < nodes; node++)
		{
			reverseStart[node + 1] += reverseStart[node];
		}
		reverseEntry = new int[entryTo.length];
		int[] fill = Arrays.copyOf(reverseStart, nodes);
		for (int e = 0; e < entryTo.length; e++)
		{
			reverseEntry[fill[entryTo[e]]++] = e;
		}
	}

	private void markExitRows()
	{
		rowIsExit = new boolean[rowOrigin.length];
		for (int row = 0; row < rowOrigin.length; row++)
		{
			rowIsExit[row] = exits.containsKey((long) rowOrigin[row] << 32 | rowDest[row] & 0xFFFFFFFFL);
		}
	}

	private static Map<Long, Exit> rowActions(List<String[]> rows)
	{
		Map<Long, Exit> byRow = new HashMap<>();
		for (String[] c : rows)
		{
			WorldPoint origin = parseTile(c[0]);
			WorldPoint destination = parseTile(c[1]);
			int objectId = c[4].isEmpty() ? -1 : Integer.parseInt(c[4]);
			byRow.putIfAbsent(exitKey(origin, destination), new Exit(origin, destination, c[2], c[3], objectId));
		}
		return byRow;
	}

	private static long exitKey(WorldPoint origin, WorldPoint destination)
	{
		return (long) pack(origin) << 32 | pack(destination) & 0xFFFFFFFFL;
	}

	static int pack(WorldPoint tile)
	{
		return pack(tile.getX(), tile.getY(), tile.getPlane());
	}

	static int pack(int x, int y, int plane)
	{
		return plane << 28 | y << 14 | x;
	}

	private static WorldPoint parseTile(String cell)
	{
		String[] parts = cell.split(" ");
		return new WorldPoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
	}

	static WorldPoint unpack(int packed)
	{
		return new WorldPoint(packed & 0x3FFF, packed >>> 14 & 0x3FFF, packed >>> 28);
	}

	private void readNodes(List<String[]> rows)
	{
		int count = rows.size();
		tiles = new WorldPoint[count];
		placed = new WorldPoint[count];
		kinds = new int[count];
		for (String[] c : rows)
		{
			int id = Integer.parseInt(c[0]);
			tiles[id] = new WorldPoint(Integer.parseInt(c[1]), Integer.parseInt(c[2]), Integer.parseInt(c[3]));
			placed[id] = c[4].isEmpty() ? null : new WorldPoint(Integer.parseInt(c[4]), Integer.parseInt(c[5]), Integer.parseInt(c[6]));
			for (String kind : c[7].split(","))
			{
				kinds[id] |= KIND_BITS.getOrDefault(kind, 0);
			}
			byTile.putIfAbsent(tiles[id], id);
		}
	}

	private void readGates(List<String[]> rows)
	{
		RequirementParser parser = new RequirementParser();
		List<Requirements> parsed = new ArrayList<>();
		for (String[] c : rows)
		{
			Map<String, String> cells = new HashMap<>();
			cells.put(RequirementParser.SKILLS, cell(c, 1));
			cells.put(RequirementParser.QUESTS, cell(c, 2));
			cells.put(RequirementParser.VARBITS, cell(c, 3));
			cells.put(RequirementParser.VARPS, cell(c, 4));
			cells.put(RequirementParser.ITEMS, cell(c, 5));
			parsed.add(parser.parse(cells));
		}
		gates = List.copyOf(parsed);
	}

	private void readBanks(List<String[]> rows)
	{
		RequirementParser parser = new RequirementParser();
		Map<Integer, List<Bank>> byNode = new HashMap<>();
		for (String[] c : rows)
		{
			String[] xyz = c[0].split(" ");
			int node = node(new WorldPoint(Integer.parseInt(xyz[0]), Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2])));
			if (node == NO_NODE)
			{
				throw new IllegalStateException("banks.tsv: no node at " + c[0]);
			}
			Map<String, String> cells = new HashMap<>();
			cells.put(RequirementParser.MEMBERS, cell(c, 3));
			cells.put(RequirementParser.SKILLS, cell(c, 4));
			cells.put(RequirementParser.QUESTS, cell(c, 5));
			cells.put(RequirementParser.VARBITS, cell(c, 6));
			cells.put(RequirementParser.VARPS, cell(c, 7));
			Bank bank = new Bank(c[1], c[2], parser.parse(cells));
			byNode.computeIfAbsent(node, n -> new ArrayList<>()).add(bank);
		}
		banks = byNode;
	}

	private void readTable(Varints in)
	{
		int nodes = in.next();
		if (nodes != tiles.length)
		{
			throw new IllegalStateException("table.bin has " + nodes + " nodes, nodes.tsv " + tiles.length);
		}
		gateSets = new int[in.next()][];
		for (int s = 0; s < gateSets.length; s++)
		{
			gateSets[s] = new int[in.next()];
			for (int g = 0; g < gateSets[s].length; g++)
			{
				gateSets[s][g] = in.next();
			}
		}
		IntBuffer to = new IntBuffer(), full = new IntBuffer(), set = new IntBuffer(), open = new IntBuffer();
		entryStart = new int[nodes + 1];
		for (int node = 0; node < nodes; node++)
		{
			entryStart[node] = to.size;
			int count = in.next();
			int previous = 0;
			for (int i = 0; i < count; i++)
			{
				previous += in.next();
				to.add(previous);
				full.add(in.next());
				int gateSet = in.next();
				set.add(gateSet);
				open.add(gateSet == 0 ? NO_PATH : in.next() - 1);
			}
		}
		entryStart[nodes] = to.size;
		entryTo = to.toArray();
		entryFull = full.toArray();
		entryGateSet = set.toArray();
		entryOpen = open.toArray();
	}

	private void readRows(Varints in)
	{
		int count = in.next();
		rowOrigin = new int[count];
		rowDest = new int[count];
		rowCost = new int[count];
		rowGate = new int[count];
		for (int i = 0; i < count; i++)
		{
			rowOrigin[i] = in.next();
			rowDest[i] = in.next();
			rowCost[i] = in.next();
			rowGate[i] = in.next();
		}
		Map<Integer, List<Integer>> byOrigin = new HashMap<>();
		for (int i = 0; i < count; i++)
		{
			byOrigin.computeIfAbsent(rowOrigin[i], tile -> new ArrayList<>()).add(i);
		}
		rowsByOrigin = byOrigin.entrySet().stream().collect(Collectors.toUnmodifiableMap(Map.Entry::getKey,
			entry -> entry.getValue().stream().mapToInt(Integer::intValue).toArray()));
	}

	private static String cell(String[] cells, int index)
	{
		return index < cells.length ? cells[index] : "";
	}

	private static InputStream open(String name) throws IOException
	{
		InputStream in = WalkTable.class.getResourceAsStream(DIRECTORY + name);
		if (in == null)
		{
			throw new IOException("missing resource " + DIRECTORY + name);
		}
		return in;
	}

	private static List<String[]> lines(String name) throws IOException
	{
		List<String[]> rows = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(open(name), StandardCharsets.UTF_8)))
		{
			boolean header = true;
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				if (header)
				{
					header = false;
					continue;
				}
				rows.add(line.split("\t", -1));
			}
		}
		return rows;
	}

	private static byte[] bytes(String name) throws IOException
	{
		try (InputStream in = open(name))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buffer = new byte[8192];
			int read;
			while ((read = in.read(buffer)) > 0)
			{
				out.write(buffer, 0, read);
			}
			return out.toByteArray();
		}
	}

	private static final class Varints
	{
		private final byte[] data;
		private int at;

		Varints(byte[] data)
		{
			this.data = data;
		}

		int next()
		{
			int value = 0;
			for (int shift = 0; ; shift += 7)
			{
				if (at >= data.length)
				{
					throw new IllegalStateException("walk data ends early");
				}
				int b = data[at++];
				value |= (b & 0x7F) << shift;
				if ((b & 0x80) == 0)
				{
					return value;
				}
			}
		}
	}

	private static final class IntBuffer
	{
		int[] data = new int[1024];
		int size;

		void add(int value)
		{
			if (size == data.length)
			{
				data = Arrays.copyOf(data, size * 2);
			}
			data[size++] = value;
		}

		int[] toArray()
		{
			return Arrays.copyOf(data, size);
		}
	}
}

package com.cluehelper.route;

import java.io.IOException;
import java.io.InputStream;
import java.util.BitSet;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Shortest Path's collision map of the whole game, doors open: four bits per tile, whether its north and east edges
 * can be walked and whether a wall or door stands on them. Immutable once loaded; any thread.
 */
public final class WorldMap
{
	private static final String RESOURCE = WalkTable.DIRECTORY + "collision-map.zip";
	private static final int REGION_BITS = 6;
	private static final int REGION_MASK = (1 << REGION_BITS) - 1;
	private static final int TILES_PER_PLANE = 1 << 2 * REGION_BITS;
	private static final int FLAGS_PER_TILE = 4;
	private static final int OPEN_NORTH = 0;
	private static final int OPEN_EAST = 1;
	private static final int WALL_NORTH = 2;
	private static final int WALL_EAST = 3;
	private static final int MAX_PLANE = 3;
	private static final int MAX_COORDINATE = 1 << 14;

	/** Each region's flag words by region x << 8 | region y; null where the map has none. */
	private final long[][] regions = new long[1 << 16][];

	private WorldMap()
	{
	}

	public static WorldMap load() throws IOException
	{
		WorldMap map = new WorldMap();
		try (InputStream resource = WorldMap.class.getResourceAsStream(RESOURCE))
		{
			if (resource == null)
			{
				throw new IOException("missing resource " + RESOURCE);
			}
			ZipInputStream in = new ZipInputStream(resource);
			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] region = entry.getName().split("_");
				map.regions[Integer.parseInt(region[0]) << 8 | Integer.parseInt(region[1])] = BitSet.valueOf(in.readAllBytes()).toLongArray();
			}
		}
		return map;
	}

	/** Shortest Path's walking rule: a diagonal needs both straight steps beside it; off a blocked tile, any open neighbour. */
	boolean canMove(int x, int y, int plane, int direction)
	{
		int dx = Directions.DX[direction];
		int dy = Directions.DY[direction];
		if (isBlocked(x, y, plane))
		{
			boolean straight = dx == 0 || dy == 0;
			return !isBlocked(x + dx, y + dy, plane)
				&& (straight || !isBlocked(x + dx, y, plane) && !isBlocked(x, y + dy, plane));
		}
		if (dx == 0 || dy == 0)
		{
			return canStep(x, y, plane, dx, dy);
		}
		return canStep(x, y, plane, 0, dy) && canStep(x, y + dy, plane, dx, 0)
			&& canStep(x, y, plane, dx, 0) && canStep(x + dx, y, plane, 0, dy);
	}

	/** No edge of the tile can be walked: an object stands on it. */
	boolean isBlocked(int x, int y, int plane)
	{
		return !canStep(x, y, plane, 0, 1) && !canStep(x, y, plane, 0, -1) && !canStep(x, y, plane, 1, 0)
			&& !canStep(x, y, plane, -1, 0);
	}

	/** A wall or door stands on the edge between straight neighbours; an object blocking a tile is no wall. */
	boolean isWallBetween(int x, int y, int plane, int dx, int dy)
	{
		if (dx > 0 || dy > 0)
		{
			return flag(x, y, plane, dx > 0 ? WALL_EAST : WALL_NORTH);
		}
		return flag(x + dx, y + dy, plane, dx < 0 ? WALL_EAST : WALL_NORTH);
	}

	boolean hasRegion(int x, int y)
	{
		return x >= 0 && y >= 0 && x < MAX_COORDINATE && y < MAX_COORDINATE && regions[region(x, y)] != null;
	}

	private boolean canStep(int x, int y, int plane, int dx, int dy)
	{
		if (dx > 0 || dy > 0)
		{
			return flag(x, y, plane, dx > 0 ? OPEN_EAST : OPEN_NORTH);
		}
		return flag(x + dx, y + dy, plane, dx < 0 ? OPEN_EAST : OPEN_NORTH);
	}

	private boolean flag(int x, int y, int plane, int flag)
	{
		if (plane < 0 || plane > MAX_PLANE || !hasRegion(x, y))
		{
			return false;
		}
		long[] words = regions[region(x, y)];
		int bit = (plane * TILES_PER_PLANE + (y & REGION_MASK) * (REGION_MASK + 1) + (x & REGION_MASK)) * FLAGS_PER_TILE + flag;
		int word = bit >>> 6;
		return word < words.length && (words[word] >>> (bit & 63) & 1L) != 0;
	}

	private static int region(int x, int y)
	{
		return (x >> REGION_BITS) << 8 | y >> REGION_BITS;
	}
}

package com.cluehelper.route;

import java.util.List;
import net.runelite.api.coords.WorldPoint;

/**
 * The walk between two tiles as the player's character takes it: the cheapest way over the {@link Ground}, laid tile
 * by tile as the game's own walking lays it when the player clicks along it. A row (stairs, a ladder) shows as a jump
 * from its origin to its destination. Any thread.
 */
public final class WorldWalk
{
	/** A blocked goal tile (a fairy ring) is used from a tile this close to it. */
	private static final int BESIDE_GOAL_TILES = 2;
	/** Once on a side of the goal with no wall between, a walk this much longer may still reach the goal itself. */
	private static final int BESIDE_GOAL_SLACK = 8;

	/**
	 * To the goal tile, or to beside it; for an object, to the first tile found that uses it, as the game walks. Empty
	 * when the goal is out of reach: a guess past the search would lead the wrong way (through a minigame portal).
	 */
	public List<WorldPoint> path(Ground ground, WorldPoint start, WalkGoal goal)
	{
		WalkSearch search = new WalkSearch(ground, WalkSearch.UNREACHED, false);
		End end = new End(ground, goal);
		search.run(WalkTable.pack(start), end);
		int tile = end.tile(search);
		return tile == WalkSearch.NONE ? List.of() : new GameWalk().along(ground, search.trace(tile));
	}

	/** Where the walk ends: the goal, the first tile found that uses its object, or the best tile beside it. */
	private static final class End implements WalkSearch.Stop
	{
		private final Ground ground;
		private final WalkGoal goal;
		private final WorldPoint goalTile;
		private final int target;
		private int usedFrom = WalkSearch.NONE;

		End(Ground ground, WalkGoal goal)
		{
			this.ground = ground;
			this.goal = goal;
			this.goalTile = goal.getSouthWest();
			this.target = WalkTable.pack(goalTile);
		}

		@Override
		public int after(int tile, int cost)
		{
			if (goal.isObject())
			{
				boolean uses = usedFrom == WalkSearch.NONE
					&& goal.isUsedFrom(ground, WalkSearch.x(tile), WalkSearch.y(tile), WalkSearch.plane(tile));
				usedFrom = uses ? tile : usedFrom;
				return uses ? cost : WalkSearch.UNREACHED;
			}
			if (tile == target)
			{
				return cost;
			}
			return opensOnto(tile) ? cost + BESIDE_GOAL_SLACK : WalkSearch.UNREACHED;
		}

		int tile(WalkSearch search)
		{
			return goal.isObject() ? usedFrom : besideGoal(search);
		}

		/** The goal when reached, else the reached tile beside it with no wall between, else the nearest. */
		private int besideGoal(WalkSearch search)
		{
			if (search.cost(target) != WalkSearch.UNREACHED)
			{
				return target;
			}
			int best = WalkSearch.NONE;
			int bestCost = WalkSearch.UNREACHED;
			int bestDistance = Integer.MAX_VALUE;
			for (int dx = -BESIDE_GOAL_TILES; dx <= BESIDE_GOAL_TILES; dx++)
			{
				for (int dy = -BESIDE_GOAL_TILES; dy <= BESIDE_GOAL_TILES; dy++)
				{
					int tile = WalkTable.pack(goalTile.getX() + dx, goalTile.getY() + dy, goalTile.getPlane());
					int cost = search.cost(tile);
					int distance = opensOnto(tile) ? 0 : Math.max(Math.abs(dx), Math.abs(dy));
					if (cost != WalkSearch.UNREACHED && (distance < bestDistance || distance == bestDistance && cost < bestCost))
					{
						best = tile;
						bestCost = cost;
						bestDistance = distance;
					}
				}
			}
			return best;
		}

		/** A straight neighbour of the goal with no wall between; a tile beside it through a wall is no way to it. */
		private boolean opensOnto(int tile)
		{
			int x = WalkSearch.x(tile);
			int y = WalkSearch.y(tile);
			int dx = x - goalTile.getX();
			int dy = y - goalTile.getY();
			return WalkSearch.plane(tile) == goalTile.getPlane() && Math.abs(dx) + Math.abs(dy) == 1
				&& !ground.isWallBetween(x, y, goalTile.getPlane(), -dx, -dy);
		}
	}
}

package com.cluehelper.step;

public final class CacheRow
{
	private int id;
	private String name;
	private Branch when;

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	/** Null when the step has one row for every branch. */
	public Branch getWhen()
	{
		return when;
	}

	@Override
	public String toString()
	{
		return id + " " + name + (when == null ? "" : " when " + when);
	}

	public static final class Branch
	{
		private int varbit;
		private Integer equals;
		private Integer notEquals;

		public int getVarbit()
		{
			return varbit;
		}

		public boolean holdsFor(int value)
		{
			return equals != null ? value == equals : notEquals == null || value != notEquals;
		}

		@Override
		public String toString()
		{
			return "varbit " + varbit + (equals != null ? " = " + equals : " != " + notEquals);
		}
	}
}

package com.cluehelper.step;

import java.util.Locale;

/**
 * Field names match the "fields" object of the replay fixtures and of {@code ::ch-step}'s fixture
 * lines, so recorded clues replay through the same key rule.
 */
public final class ClueFacts
{
	private static final int NO_ITEM = -1;

	private String type;
	private int itemId = NO_ITEM;
	private String text;
	private int[] tile;
	private int widgetGroupId = -1;
	private String tier;
	private String npc;
	private String challengeType;
	private String rawChallenge;

	private ClueFacts()
	{
	}

	static ClueFacts of(String type)
	{
		ClueFacts facts = new ClueFacts();
		facts.type = type;
		return facts;
	}

	ClueFacts itemId(int itemId)
	{
		this.itemId = itemId;
		return this;
	}

	ClueFacts text(String text)
	{
		this.text = text;
		return this;
	}

	ClueFacts tile(int x, int y, int plane)
	{
		this.tile = new int[]{x, y, plane};
		return this;
	}

	ClueFacts widgetGroupId(int widgetGroupId)
	{
		this.widgetGroupId = widgetGroupId;
		return this;
	}

	ClueFacts tier(String tier)
	{
		this.tier = tier;
		return this;
	}

	ClueFacts npc(String npc)
	{
		this.npc = npc;
		return this;
	}

	ClueFacts challenge(String challengeType, String rawChallenge)
	{
		this.challengeType = challengeType;
		this.rawChallenge = rawChallenge;
		return this;
	}

	public String getType()
	{
		return type;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getText()
	{
		return text;
	}

	public int[] getTile()
	{
		return tile == null ? null : tile.clone();
	}

	public int getWidgetGroupId()
	{
		return widgetGroupId;
	}

	public String getTier()
	{
		return tier;
	}

	public String getNpc()
	{
		return npc;
	}

	public String getChallengeType()
	{
		return challengeType;
	}

	public String getRawChallenge()
	{
		return rawChallenge;
	}

	public static String normalise(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replaceAll("<[^>]*>", " ")
			.replaceAll("\\s+", " ")
			.trim()
			.toLowerCase(Locale.ROOT);
	}
}

