package com.cluehelper.step;

import net.runelite.api.gameval.ItemID;

/**
 * Built from core's public getters only. An item id is the key only when the type has one item per
 * entry. A cache row is never the key: one key can own two rows, and two keys one row.
 */
public final class StepKey
{
	public static final String HOT_COLD_PREFIX = "hotcold:";

	private StepKey()
	{
	}

	/** The keys of one tier's hot/cold steps start with this. */
	public static String hotColdPrefix(HotColdTier tier)
	{
		return HOT_COLD_PREFIX + tier.getTierName() + ":";
	}

	/** @param npc the NPC the clue names, as core gives it or as a key already names him */
	public static String hotCold(HotColdTier tier, String npc)
	{
		return hotColdPrefix(tier) + ClueFacts.normalise(npc);
	}

	public static String of(ClueFacts f)
	{
		String type = f.getType();
		switch (type)
		{
			case ClueTypes.CRYPTIC:
			case ClueTypes.FALO:
			case ClueTypes.THREE_STEP:
			case ClueTypes.FAIRY_RING:
				return type + ":" + ClueFacts.normalise(f.getText());
			case ClueTypes.SKILL:
				return "skill:" + f.getChallengeType() + ":" + ClueFacts.normalise(f.getRawChallenge());
			case ClueTypes.HOT_COLD:
				return hotCold(HotColdTier.of(f.getTier()), f.getNpc());
			case ClueTypes.BEGINNER_MAP:
				return "map:w" + f.getWidgetGroupId();
			case ClueTypes.COORDINATE:
			case ClueTypes.MAP:
				return hasOwnItem(f) ? type + ":" + f.getItemId() : type + ":" + tile(f.getTile());
			case ClueTypes.ANAGRAM:
			case ClueTypes.CIPHER:
			case ClueTypes.EMOTE:
			case ClueTypes.MUSIC:
				return hasOwnItem(f) ? type + ":" + f.getItemId() : type + ":" + ClueFacts.normalise(f.getText());
			default:
				return "unknown:" + type;
		}
	}

	/** Beginner and master clues of every type share one item each, so their item says nothing. */
	private static boolean hasOwnItem(ClueFacts f)
	{
		int item = f.getItemId();
		return item > 0 && item != ItemID.TRAIL_CLUE_BEGINNER && item != ItemID.TRAIL_CLUE_MASTER;
	}

	private static String tile(int[] tile)
	{
		return tile == null ? "?" : tile[0] + "," + tile[1] + "," + tile[2];
	}
}

package com.cluehelper.step;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Item;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/** Core's item requirements are tested only through their own {@code fulfilledBy}, never taken apart. */
public final class StepRequirements
{
	private final SpadeNeed spade;
	private final boolean light;
	private final int firePitVarbitId;
	private final int lightSourceVarbitId;
	private final List<ItemRequirement> items;
	private final List<ItemRequirement> ownItems;
	private final int stashObjectId;

	StepRequirements(SpadeNeed spade, boolean light, int firePitVarbitId, int lightSourceVarbitId, List<ItemRequirement> items,
		int stashObjectId)
	{
		this(spade, light, firePitVarbitId, lightSourceVarbitId, items, List.of(), stashObjectId);
	}

	private StepRequirements(SpadeNeed spade, boolean light, int firePitVarbitId, int lightSourceVarbitId, List<ItemRequirement> items,
		List<ItemRequirement> ownItems, int stashObjectId)
	{
		this.spade = spade;
		this.light = light;
		this.firePitVarbitId = firePitVarbitId;
		this.lightSourceVarbitId = lightSourceVarbitId;
		this.items = List.copyOf(items);
		this.ownItems = List.copyOf(ownItems);
		this.stashObjectId = stashObjectId;
	}

	/** The {@code stashObjectId} of a step without a STASH unit. */
	public static final int NO_STASH = -1;

	public static StepRequirements none()
	{
		return new StepRequirements(SpadeNeed.NONE, false, -1, -1, List.of(), NO_STASH);
	}

	public StepRequirements plus(ItemRequirement item)
	{
		List<ItemRequirement> more = new ArrayList<>(items);
		more.add(item);
		return new StepRequirements(spade, light, firePitVarbitId, lightSourceVarbitId, more, ownItems, stashObjectId);
	}

	/** An item the step's route needs that core's *clue* bank tag doesn't list: Charlie's item. */
	public StepRequirements plusOwn(ItemRequirement item)
	{
		List<ItemRequirement> more = new ArrayList<>(ownItems);
		more.add(item);
		return new StepRequirements(spade, light, firePitVarbitId, lightSourceVarbitId, items, more, stashObjectId);
	}

	public List<ItemRequirement> getOwnItems()
	{
		return ownItems;
	}

	/** The emote step's STASH unit object, or {@link #NO_STASH}. */
	public int getStashObjectId()
	{
		return stashObjectId;
	}

	public boolean hasStash()
	{
		return stashObjectId != NO_STASH;
	}

	public SpadeNeed getSpade()
	{
		return spade;
	}

	public boolean needsLight()
	{
		return light;
	}

	/** The varbit that says the step's fire pit is lit, so no light is needed; -1 for none. */
	public int getFirePitVarbitId()
	{
		return firePitVarbitId;
	}

	/** Core's light-source varbit of a coordinate clue; -1 for none. */
	public int getLightSourceVarbitId()
	{
		return lightSourceVarbitId;
	}

	public List<ItemRequirement> getItems()
	{
		return items;
	}

	public boolean itemsFulfilledBy(Item[] items)
	{
		for (ItemRequirement requirement : this.items)
		{
			if (!requirement.fulfilledBy(items))
			{
				return false;
			}
		}
		return true;
	}

	/** By value: a rewritten step (a probe trip, a stage dropped) is rebuilt every tick and must equal the last one. */
	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof StepRequirements))
		{
			return false;
		}
		StepRequirements that = (StepRequirements) other;
		return spade == that.spade && light == that.light && firePitVarbitId == that.firePitVarbitId
			&& lightSourceVarbitId == that.lightSourceVarbitId && stashObjectId == that.stashObjectId && items.equals(that.items)
			&& ownItems.equals(that.ownItems);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(spade, light, firePitVarbitId, lightSourceVarbitId, stashObjectId, items, ownItems);
	}

	@Override
	public String toString()
	{
		StringBuilder text = new StringBuilder();
		if (spade != SpadeNeed.NONE)
		{
			text.append("spade");
		}
		if (light)
		{
			text.append(text.length() > 0 ? ", " : "").append("light");
			if (firePitVarbitId != -1)
			{
				text.append(" (fire pit ").append(firePitVarbitId).append(')');
			}
		}
		if (lightSourceVarbitId != -1)
		{
			text.append(text.length() > 0 ? ", " : "").append("light varbit ").append(lightSourceVarbitId);
		}
		if (!items.isEmpty())
		{
			text.append(text.length() > 0 ? ", " : "").append(items.size()).append(" item requirement").append(items.size() == 1 ? "" : "s");
		}
		return text.length() == 0 ? "none" : text.toString();
	}
}

package com.cluehelper.step;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.CrypticClue;
import net.runelite.client.plugins.cluescrolls.clues.EmoteClue;
import net.runelite.client.plugins.cluescrolls.clues.HotColdClue;
import net.runelite.client.plugins.cluescrolls.clues.SkillChallengeClue;
import net.runelite.client.plugins.cluescrolls.clues.ThreeStepCrypticClue;
import net.runelite.client.plugins.cluescrolls.clues.emote.STASHUnit;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirements;

@Slf4j
@Singleton
public class StepResolver
{
	private static final String UNKNOWN_TIER = "unknown";
	private static final String THREE_STEP_TIER = "master";


	private final Supplier<StepIndex> index;
	private final Set<String> loggedUnknown = ConcurrentHashMap.newKeySet();
	/** One requirement per key or tool entry, so a re-read step equals the last one. */
	private final Map<Integer, ItemRequirement> keyRequirements = new ConcurrentHashMap<>();

	@Inject
	StepResolver(StepData data)
	{
		this(data::index);
	}

	public StepResolver(Supplier<StepIndex> index)
	{
		this.index = index;
	}

	/** @param plugin core's real instance: several entries throw on null */
	public Step resolve(ClueScroll clue, ClueScrollPlugin plugin)
	{
		ClueFacts facts = CoreClueReader.facts(clue, plugin);
		String key = StepKey.of(facts);
		StepIndex.Entry entry = clue instanceof ThreeStepCrypticClue
			? threeStepEntry((ThreeStepCrypticClue) clue)
			: index.get().entry(key);
		if (entry == null && loggedUnknown.add(key))
		{
			log.info("No step data for {}: using the Clue Scroll plugin's targets only", key);
		}
		String tier = tier(facts, entry);
		List<WorldPoint> targets = targets(clue, plugin, facts, entry);
		List<String> npcs = NpcAliases.withAliases(CoreClueReader.npcs(clue, plugin));
		List<Stage> stages = stages(clue, plugin, entry, targets, npcs);
		return Step.builder()
			.key(key)
			.type(facts.getType())
			.tier(tier)
			.text(CoreClueReader.displayText(clue, facts, plugin))
			.kind(stages.isEmpty() ? kind(clue, entry) : TargetKind.SEQUENCE)
			.targets(stages.isEmpty() ? targets : Stages.tiles(stages))
			.npcs(npcs)
			.regions(CoreClueReader.regions(clue))
			.objectIds(CoreClueReader.objectIds(clue))
			.objectNames(CoreClueReader.objectNames(clue))
			.requirements(requirements(clue))
			.stages(stages)
			.data(entry == null ? StepIndex.Entry.NONE : entry)
			.otherTiles(otherTiles(entry, targets))
			.emotes(CoreClueReader.emotes(clue))
			.build();
	}

	private List<Stage> stages(ClueScroll clue, ClueScrollPlugin plugin, StepIndex.Entry entry, List<WorldPoint> targets,
		List<String> npcs)
	{
		if (clue instanceof ThreeStepCrypticClue)
		{
			return Stages.parts(CoreClueReader.unsolvedParts((ThreeStepCrypticClue) clue), plugin, this::wornFor);
		}
		StepIndex.Target key = entry == null ? null : entry.getTargets().stream()
			.filter(target -> target.getKind() == StepIndex.Target.Kind.KEY && target.getKeyTile() != null).findFirst().orElse(null);
		if (key != null)
		{
			return Stages.killForKey(key, npcs.isEmpty() ? null : npcs.get(0), keyRequirements.computeIfAbsent(key.getKey(),
				ItemRequirements::item), targets);
		}
		if (clue instanceof SkillChallengeClue)
		{
			return Stages.challenge(entry, ((SkillChallengeClue) clue).getRawChallenge(), CoreClueReader.challengeCompleted(clue),
				CoreClueReader.returnItem(clue), targets, EmptySlots.of(CoreClueReader.itemRequirements(clue)));
		}
		return List.of();
	}

	/** Cache tiles the step is also done at, off core's targets: Brimstail inside his cave, Martin Thwait in the den. */
	private static List<WorldPoint> otherTiles(StepIndex.Entry entry, List<WorldPoint> targets)
	{
		if (entry == null)
		{
			return List.of();
		}
		List<WorldPoint> other = new ArrayList<>();
		for (WorldPoint tile : tiles(entry))
		{
			if (!nearAny(tile, targets))
			{
				other.add(tile);
			}
		}
		return List.copyOf(other);
	}

	/** For a clue whose getters threw: only its class, so it still shows as a step. */
	public static Step unreadable(ClueScroll clue)
	{
		String type = clue.getClass().getSimpleName();
		return Step.builder()
			.key("unreadable:" + type)
			.type(type)
			.tier(UNKNOWN_TIER)
			.text("")
			.kind(TargetKind.ANY_OF)
			.targets(List.of())
			.npcs(List.of())
			.regions(List.of())
			.objectIds(List.of())
			.objectNames(List.of())
			.requirements(new StepRequirements(SpadeNeed.NONE, false, -1, -1, List.of(), StepRequirements.NO_STASH))
			.build();
	}

	/**
	 * A three-step's key joins its parts' texts, so the step data can't hold it, but its parts are
	 * master cryptics the data does hold. Null unless the data has every part.
	 */
	private StepIndex.Entry threeStepEntry(ThreeStepCrypticClue clue)
	{
		List<CacheRow> rows = new ArrayList<>();
		List<StepIndex.Entry> unsolved = new ArrayList<>();
		for (Map.Entry<CrypticClue, Boolean> part : List.copyOf(clue.getClueSteps()))
		{
			StepIndex.Entry partEntry = partEntry(part.getKey());
			if (partEntry == null)
			{
				return null;
			}
			rows.addAll(partEntry.getRows());
			if (!part.getValue())
			{
				unsolved.add(partEntry);
			}
		}
		return StepIndex.Entry.ofParts(THREE_STEP_TIER, rows, unsolved);
	}

	private StepIndex.Entry partEntry(CrypticClue part)
	{
		return index.get().entry(StepKey.of(ClueFacts.of(ClueTypes.CRYPTIC).text(part.getText())));
	}

	private List<String> wornFor(CrypticClue part)
	{
		StepIndex.Entry entry = partEntry(part);
		return entry == null ? List.of() : entry.getWornNeeds();
	}

	private static TargetKind kind(ClueScroll clue, StepIndex.Entry entry)
	{
		if (clue instanceof HotColdClue)
		{
			return TargetKind.PROBES;
		}
		if (clue instanceof ThreeStepCrypticClue || clue instanceof SkillChallengeClue)
		{
			return TargetKind.SEQUENCE;
		}
		boolean killArea = entry != null && entry.getArea() != null;
		return CoreClueReader.regions(clue).isEmpty() && !killArea ? TargetKind.ANY_OF : TargetKind.AREA;
	}

	/**
	 * Core adds a Prifddinas mirror twin to coordinate clues, the wrong tile for 2 of the 3 that get
	 * one, so a coordinate clue keeps only the tile the cache names. A step core gives no tile (Falo,
	 * skill challenges) gets the cache's.
	 */
	private static List<WorldPoint> targets(ClueScroll clue, ClueScrollPlugin plugin, ClueFacts facts, StepIndex.Entry entry)
	{
		if (entry != null && entry.getStand() != null)
		{
			return List.of(entry.getStand());
		}
		if (entry != null && entry.getArea() != null && entry.getArea().getTile() != null)
		{
			return List.of(entry.getArea().getTile());
		}
		List<WorldPoint> core = CoreClueReader.locations(clue, plugin);
		List<WorldPoint> cache = entry == null ? List.of() : tiles(entry);
		if (ClueTypes.COORDINATE.equals(facts.getType()) && !cache.isEmpty())
		{
			List<WorldPoint> named = new ArrayList<>();
			for (WorldPoint tile : core)
			{
				if (nearAny(tile, cache))
				{
					named.add(tile);
				}
			}
			if (!named.isEmpty())
			{
				return List.copyOf(named);
			}
			WorldPoint primary = CoreClueReader.primaryLocation(clue, plugin);
			return primary == null ? core : List.of(primary);
		}
		return withWander(core.isEmpty() ? cache : core, entry);
	}

	/** An NPC that wanders far is met wherever the route reaches its range first. */
	private static List<WorldPoint> withWander(List<WorldPoint> targets, StepIndex.Entry entry)
	{
		if (entry == null || entry.getWander() == null)
		{
			return targets;
		}
		List<WorldPoint> all = new ArrayList<>(targets);
		entry.getWander().getTiles().stream().filter(tile -> !all.contains(tile)).forEach(all::add);
		return List.copyOf(all);
	}

	private static boolean nearAny(WorldPoint tile, List<WorldPoint> others)
	{
		for (WorldPoint other : others)
		{
			if (other.getPlane() == tile.getPlane() && Math.max(Math.abs(other.getX() - tile.getX()), Math.abs(other.getY() - tile.getY())) <= 1)
			{
				return true;
			}
		}
		return false;
	}

	private static List<WorldPoint> tiles(StepIndex.Entry entry)
	{
		List<WorldPoint> tiles = new ArrayList<>();
		for (int[] tile : entry.getTiles())
		{
			WorldPoint point = new WorldPoint(tile[0], tile[1], tile[2]);
			if (!tiles.contains(point))
			{
				tiles.add(point);
			}
		}
		return List.copyOf(tiles);
	}

	private static String tier(ClueFacts facts, StepIndex.Entry entry)
	{
		if (entry != null && entry.getTier() != null)
		{
			return entry.getTier();
		}
		return facts.getTier() != null ? facts.getTier() : UNKNOWN_TIER;
	}

	private static StepRequirements requirements(ClueScroll clue)
	{
		SpadeNeed spade = clue.isRequiresSpade() ? SpadeNeed.SPADE : SpadeNeed.NONE;
		STASHUnit stash = clue instanceof EmoteClue ? ((EmoteClue) clue).getStashUnit() : null;
		List<ItemRequirement> items = CoreClueReader.challengeCompleted(clue) ? List.of() : CoreClueReader.itemRequirements(clue);
		StepRequirements requirements = new StepRequirements(spade, clue.isRequiresLight(), clue.getFirePitVarbitId(),
			CoreClueReader.lightSourceVarbitId(clue), items, stash == null ? StepRequirements.NO_STASH : stash.getObjectId());
		ItemRequirement charliesItem = CoreClueReader.returnItem(clue);
		return charliesItem == null ? requirements : requirements.plusOwn(charliesItem);
	}
}

package com.cluehelper.step;

public enum TargetKind
{
	ANY_OF,
	/** An NPC that walks around inside its regions. */
	AREA,
	/** Places visited in turn: three-step parts, a skill challenge and its hand-in. */
	SEQUENCE,
	/** Hot/cold: the spots still possible, narrowed by each probe. */
	PROBES
}

package com.cluehelper.transport;

import com.cluehelper.player.Charge;
import com.cluehelper.player.Container;
import com.cluehelper.player.HouseState;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.player.RuneModel;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;
import java.util.stream.Collectors;
import net.runelite.api.Quest;

/**
 * Pure, so it runs on any thread. Spell rows are never filtered by their book: the planner decides which book a
 * route casts from.
 */
public final class AvailabilityEngine
{
	/** Carried first, so a banked snapshot withdraws only what the player lacks (its bank maps are empty otherwise). */
	private static final List<Container> CARRIED = List.of(Container.INVENTORY, Container.WORN, Container.BANK,
		Container.GROUP_STORAGE);
	/** At a bank a withdrawn item can be worn before the teleport. */
	private static final List<Container> WORN_ONLY = List.of(Container.WORN, Container.BANK, Container.GROUP_STORAGE);
	/** Shortest Path lists every charge of an item as its own alternative: glory(1) to glory(t6) is 12. */
	private static final int MAX_ALTERNATIVES_NAMED = 2;

	private final RuneModel runes;
	private final IntFunction<String> itemNames;

	/** @param itemNames called from any thread */
	public AvailabilityEngine(RuneModel runes, IntFunction<String> itemNames)
	{
		this.runes = runes;
		this.itemNames = itemNames;
	}

	/** Also judges a banked snapshot ({@link PlayerSnapshot#getBank()} filled), whose witnesses name what to withdraw. */
	public AvailabilitySet carried(List<CatalogRow> rows, PlayerSnapshot player, long nowMinutes)
	{
		List<RowAvailability> judged = rows.stream().map(row -> judge(row, player, nowMinutes)).collect(Collectors.toList());
		long validUntil = judged.stream().mapToLong(RowAvailability::getPassesFrom).min().orElse(Long.MAX_VALUE);
		return new AvailabilitySet(player.getVersion(), List.copyOf(judged), validUntil);
	}

	public RowAvailability judge(CatalogRow row, PlayerSnapshot player, long nowMinutes)
	{
		Verdict v = new Verdict();
		Requirements req = row.getRequirements();
		req.getErrors().forEach(error -> v.no("catalog row unreadable: " + error));
		if (req.isMembers() && !player.isMembersWorld())
		{
			v.no("members world only");
		}
		if (player.getWildernessLevel() > req.getMaxWildernessLevel())
		{
			v.no("above Wilderness level " + req.getMaxWildernessLevel());
		}
		req.getLevels().forEach(need -> checkLevel(need, player, v));
		req.getQuests().forEach(quest -> checkQuest(quest, player, v));
		req.getVars().forEach(check -> checkVar(check, player, nowMinutes, v));
		checkHouse(req.getHouse(), player, v);
		req.getPlantedTrees().forEach(patch -> checkPlanted(patch, player, v));
		req.getItems().forEach(clause -> checkClause(clause, req.isSpendsCharges(), player, nowMinutes, v));
		return v.result(row);
	}

	private static void checkLevel(LevelNeed need, PlayerSnapshot player, Verdict v)
	{
		int have = need.have(player);
		if (have < need.getLevel())
		{
			v.no("needs " + need.describe() + " (has " + have + ")");
		}
	}

	private static void checkQuest(Quest quest, PlayerSnapshot player, Verdict v)
	{
		if (!player.isQuestsRead())
		{
			v.unread("quests not read yet");
		}
		else if (!player.finished(quest))
		{
			v.no(quest.getName() + " not finished");
		}
	}

	private static void checkHouse(HouseNeed need, PlayerSnapshot player, Verdict v)
	{
		if (need == null)
		{
			return;
		}
		HouseState house = player.getHouse();
		boolean built = need.getKind() == HouseNeed.Kind.NEXUS ? house.getNexusKeys().contains(need.getIds().get(0))
			: house.hasAny(need.getIds());
		if (!built)
		{
			v.no(need.describe() + " not known in your house");
		}
	}

	/** Unknown counts as unavailable: a tree never seen grown may be dead or not planted. */
	private static void checkPlanted(String patch, PlayerSnapshot player, Verdict v)
	{
		if (!player.getPlantedTrees().contains(patch))
		{
			v.no("spirit tree at " + patch + " not seen grown");
		}
	}

	private static void checkVar(VarCheck check, PlayerSnapshot player, long nowMinutes, Verdict v)
	{
		Integer value = check.getKind() == VarCheck.Kind.VARBIT ? player.varbit(check.getId()) : player.varp(check.getId());
		if (value == null)
		{
			if (player.getUnknownVars() == PlayerSnapshot.UnknownVars.FAIL)
			{
				v.no(check.describe());
			}
			else if (player.getUnknownVars() == PlayerSnapshot.UnknownVars.UNREAD)
			{
				v.unread(check.describe() + ": not read");
			}
			return;
		}
		if (!check.test(value, nowMinutes))
		{
			v.no(check.whyNot(value, nowMinutes));
			v.passesFrom = Math.min(v.passesFrom, check.passesFrom(value));
		}
	}

	private void checkClause(ItemClause clause, boolean spendsCharges, PlayerSnapshot player, long nowMinutes, Verdict v)
	{
		if (clause.getWaivedBy() != null && passes(clause.getWaivedBy(), player, nowMinutes))
		{
			return;
		}
		List<String> shortfalls = new ArrayList<>();
		String unread = null;
		Paid best = null;
		for (ItemClause.Branch branch : clause.getBranches())
		{
			Paid paid = pay(branch, clause.isMustBeWorn(), spendsCharges, player);
			if (paid.witness != null)
			{
				best = best == null || preferred(paid, best, spendsCharges, player) ? paid : best;
				continue;
			}
			if (paid.unread != null)
			{
				unread = paid.unread;
			}
			else
			{
				shortfalls.add(paid.shortfall);
			}
		}
		if (best != null)
		{
			v.witness.addAll(best.witness);
			v.chargesUnknown |= best.chargesUnknown;
		}
		else if (unread != null)
		{
			v.unread(unread);
		}
		else
		{
			v.no(shortfalls.size() <= MAX_ALTERNATIVES_NAMED ? String.join(" or ", shortfalls)
				: shortfalls.get(0) + " or one of " + (shortfalls.size() - 1) + " other variants");
		}
	}

	/** Fewest known charges wins, so partly charged items get used up first; ties keep the catalog's order. */
	private static boolean preferred(Paid a, Paid b, boolean spendsCharges, PlayerSnapshot player)
	{
		int bankA = fromStorage(a.witness);
		int bankB = fromStorage(b.witness);
		if (bankA != bankB)
		{
			return bankA < bankB;
		}
		return spendsCharges && knownCharges(a.witness, player) < knownCharges(b.witness, player);
	}

	private static int fromStorage(List<ItemUse> witness)
	{
		return (int) witness.stream().filter(use -> use.getContainer().isStored()).count();
	}

	/** Unknown counts as more than any known total. */
	private static int knownCharges(List<ItemUse> witness, PlayerSnapshot player)
	{
		int total = 0;
		for (ItemUse use : witness)
		{
			Charge charge = player.getCharges().get(use.getItemId());
			if (charge == null || charge.getCharges() < 0)
			{
				return Integer.MAX_VALUE;
			}
			total += charge.getCharges();
		}
		return total;
	}

	private Paid pay(ItemClause.Branch branch, boolean mustBeWorn, boolean spendsCharges, PlayerSnapshot player)
	{
		if (branch.isUnlock())
		{
			return player.getUnlocks().contains(branch.getUnlock()) ? Paid.with(List.of(), false)
				: Paid.unread("unlock " + branch.getUnlock() + " not seen yet");
		}
		List<Integer> ids = branch.getIds();
		if (ids.size() == 1 && runes.isRune(ids.get(0)) && !mustBeWorn)
		{
			RuneModel.Supply supply = runes.supply(ids.get(0), branch.getQuantity(), player);
			return supply.isEnough() ? Paid.with(supply.getWitness(), false)
				: Paid.missing(runes.shortfall(ids.get(0), branch.getQuantity(), supply.getHave()));
		}
		List<ItemUse> used = new ArrayList<>();
		boolean chargesUnknown = false;
		boolean emptied = false;
		int have = 0;
		for (Container container : mustBeWorn ? WORN_ONLY : CARRIED)
		{
			for (int id : ids)
			{
				int count = CatalogRules.UNCHARGED.contains(id) ? 0 : player.count(container, id);
				if (count == 0 || have >= branch.getQuantity())
				{
					continue;
				}
				Charge charge = player.getCharges().get(id);
				if (spendsCharges && charge != null && charge.getCharges() <= 0)
				{
					emptied = true;
					continue;
				}
				chargesUnknown |= spendsCharges && charge == null;
				int take = Math.min(count, branch.getQuantity() - have);
				used.add(new ItemUse(container, id, take));
				have += take;
			}
		}
		if (have >= branch.getQuantity())
		{
			return Paid.with(used, chargesUnknown);
		}
		String what = itemNames.apply(ids.get(0)) + (ids.size() > 1 ? " (any of " + ids.size() + ")" : "");
		return Paid.missing((mustBeWorn ? "needs to wield " : "needs ")
			+ (branch.getQuantity() > 1 ? branch.getQuantity() + " x " : "") + what + (emptied ? ", no charges left" : ""));
	}

	private static boolean passes(VarCheck check, PlayerSnapshot player, long nowMinutes)
	{
		Integer value = check.getKind() == VarCheck.Kind.VARBIT ? player.varbit(check.getId()) : player.varp(check.getId());
		if (value == null)
		{
			return player.getUnknownVars() == PlayerSnapshot.UnknownVars.PASS;
		}
		return check.test(value, nowMinutes);
	}

	private static final class Paid
	{
		List<ItemUse> witness;
		boolean chargesUnknown;
		String shortfall;
		String unread;

		static Paid with(List<ItemUse> witness, boolean chargesUnknown)
		{
			Paid p = new Paid();
			p.witness = witness;
			p.chargesUnknown = chargesUnknown;
			return p;
		}

		static Paid missing(String shortfall)
		{
			Paid p = new Paid();
			p.shortfall = shortfall;
			return p;
		}

		static Paid unread(String what)
		{
			Paid p = new Paid();
			p.unread = what;
			return p;
		}
	}

	private static final class Verdict
	{
		final List<String> whyNot = new ArrayList<>();
		final List<ItemUse> witness = new ArrayList<>();
		boolean unread;
		boolean chargesUnknown;
		long passesFrom = Long.MAX_VALUE;

		void no(String reason)
		{
			whyNot.add(reason);
		}

		void unread(String reason)
		{
			unread = true;
			whyNot.add(reason);
		}

		RowAvailability result(CatalogRow row)
		{
			boolean available = whyNot.isEmpty();
			RowAvailability.Confidence confidence = unread ? RowAvailability.Confidence.UNREAD
				: available && chargesUnknown ? RowAvailability.Confidence.CHARGES_UNKNOWN : RowAvailability.Confidence.SURE;
			return new RowAvailability(row, available, confidence, available ? List.copyOf(witness) : List.of(),
				List.copyOf(whyNot), passesFrom);
		}
	}
}

package com.cluehelper.transport;

import com.cluehelper.ClueHelperConfig;
import com.cluehelper.memory.BankMemory;
import com.cluehelper.player.Charge;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.player.RuneModel;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;

/** Client thread, except the getters. Also judges again when a cooldown clears, since no var changes then. */
@Singleton
public class AvailabilityService
{
	private static final long MILLIS_PER_MINUTE = 60_000L;

	private final PlayerModel player;
	private final Client client;
	private final BankMemory bankMemory;
	private final ClueHelperConfig config;
	private final Set<Integer> catalogItems = new HashSet<>();
	private final Map<Integer, String> itemNames = new ConcurrentHashMap<>();
	private final List<Consumer<AvailabilitySet>> listeners = new CopyOnWriteArrayList<>();

	private volatile List<CatalogRow> catalog = List.of();
	private volatile AvailabilitySet carried = AvailabilitySet.EMPTY;
	private volatile AvailabilitySet banked = AvailabilitySet.EMPTY;
	private volatile PlayerSnapshot bankedSnapshot;
	private long judgedBankVersion = -1;
	private volatile long lastJudgeNanos;
	private volatile boolean stale = true;
	private Runnable unregister;

	@Inject
	AvailabilityService(PlayerModel player, Client client, BankMemory bankMemory, ClueHelperConfig config)
	{
		this.player = player;
		this.client = client;
		this.bankMemory = bankMemory;
		this.config = config;
	}

	public void start()
	{
		unregister = player.addListener(snapshot -> stale = true);
	}

	public void stop()
	{
		if (unregister != null)
		{
			unregister.run();
			unregister = null;
		}
		carried = AvailabilitySet.EMPTY;
		banked = AvailabilitySet.EMPTY;
		bankedSnapshot = null;
	}

	/** Any thread. The rows' vars are watched from the next tick on. */
	public void setCatalog(List<CatalogRow> rows)
	{
		Set<Integer> varbits = new HashSet<>();
		Set<Integer> varps = new HashSet<>();
		for (CatalogRow row : rows)
		{
			Requirements req = row.getRequirements();
			req.getVars().forEach(check -> (check.getKind() == VarCheck.Kind.VARBIT ? varbits : varps).add(check.getId()));
			req.getItems().stream().filter(clause -> clause.getWaivedBy() != null)
				.forEach(clause -> varbits.add(clause.getWaivedBy().getId()));
		}
		player.watch(varbits, varps);
		catalog = List.copyOf(rows);
		stale = true;
	}

	public List<CatalogRow> getCatalog()
	{
		return catalog;
	}

	/** Call after {@link PlayerModel#onGameTick()} on the same tick. */
	public void onGameTick()
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		RuneModel runes = player.getRuneModel();
		if (snapshot == null || runes == null)
		{
			return;
		}
		long now = nowMinutes();
		boolean bankChanged = bankMemory.getVersion() != judgedBankVersion;
		if (stale || bankChanged || now >= carried.getValidUntilMinute() || now >= banked.getValidUntilMinute())
		{
			stale = false;
			judgedBankVersion = bankMemory.getVersion();
			nameCatalogItems();
			long started = System.nanoTime();
			AvailabilityEngine engine = new AvailabilityEngine(runes, this::itemName);
			carried = engine.carried(catalog, snapshot, now);
			bankedSnapshot = withBank(snapshot);
			banked = bankedSnapshot == null ? AvailabilitySet.EMPTY : engine.carried(catalog, bankedSnapshot, now);
			lastJudgeNanos = System.nanoTime() - started;
			AvailabilitySet judged = carried;
			listeners.forEach(listener -> listener.accept(judged));
		}
	}

	/** Null when no bank counts. */
	/** The bank is part of planning while the setting is on and the account has one. */
	public boolean bankCounts(PlayerSnapshot snapshot)
	{
		return config.useBank() && snapshot.getAccountType().hasBank();
	}

	private PlayerSnapshot withBank(PlayerSnapshot snapshot)
	{
		BankMemory.Seen bank = bankMemory.getBank();
		if (bank == null || !bankCounts(snapshot))
		{
			return null;
		}
		BankMemory.Seen group = bankMemory.getGroupStorage();
		Set<Integer> stored = new HashSet<>(bank.items.keySet());
		if (group != null)
		{
			stored.addAll(group.items.keySet());
		}
		stored.retainAll(catalogItems);
		Map<Integer, Charge> charges = new HashMap<>(player.charges(stored));
		charges.putAll(snapshot.getCharges());
		return snapshot.toBuilder()
			.bank(bankMemory.withKit(bank.items))
			.groupStorage(group == null ? Map.of() : group.items)
			.charges(charges)
			.build();
	}

	/** Listeners run on the client thread, each time the catalog is judged again. */
	public Runnable addListener(Consumer<AvailabilitySet> listener)
	{
		listeners.add(listener);
		return () -> listeners.remove(listener);
	}

	public AvailabilitySet getCarried()
	{
		return carried;
	}

	/** Empty when no bank counts. */
	public AvailabilitySet getBanked()
	{
		return banked;
	}

	/** Null when no bank counts. */
	public PlayerSnapshot getBankedSnapshot()
	{
		return bankedSnapshot;
	}

	public long getLastJudgeNanos()
	{
		return lastJudgeNanos;
	}

	public static long nowMinutes()
	{
		return System.currentTimeMillis() / MILLIS_PER_MINUTE;
	}

	private String itemName(int id)
	{
		return itemNames.getOrDefault(id, "item " + id);
	}

	private void nameCatalogItems()
	{
		for (CatalogRow row : catalog)
		{
			for (ItemClause clause : row.getRequirements().getItems())
			{
				for (ItemClause.Branch branch : clause.getBranches())
				{
					branch.getIds().forEach(id ->
					{
						catalogItems.add(id);
						itemNames.computeIfAbsent(id, i -> client.getItemDefinition(i).getName());
					});
				}
			}
		}
	}
}

package com.cluehelper.transport;

import java.util.List;
import java.util.stream.Collectors;
