package com.cluehelper.transport;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class CatalogData
{
	private final CompletableFuture<Catalog> catalog;

	@Inject
	CatalogData(ScheduledExecutorService executor)
	{
		catalog = CompletableFuture.supplyAsync(CatalogData::loadOrEmpty, executor);
	}

	public CompletableFuture<Catalog> get()
	{
		return catalog;
	}

	private static Catalog loadOrEmpty()
	{
		try
		{
			long started = System.nanoTime();
			Catalog loaded = CatalogLoader.load();
			log.debug("catalog: {} teleports, {} spellbook changes in {} ms", loaded.getTeleports().size(),
				loaded.getSpellbookChanges().size(), (System.nanoTime() - started) / 1_000_000);
			return loaded;
		}
		catch (IllegalStateException e)
		{
			log.warn("the bundled catalog is unreadable: no teleports will be offered", e);
			return Catalog.EMPTY;
		}
	}
}

package com.cluehelper.transport;

import com.cluehelper.player.Book;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;

/**
 * A requirement that doesn't parse stays on its row as an error; a malformed tile or number fails the whole load,
 * which the schema test catches before release.
 */
public final class CatalogLoader
{
	static final List<String> TELEPORT_FILES = List.of("spells.tsv", "home_teleports.tsv", "minigames.tsv", "items.tsv",
		"fairy_rings.tsv", "poh.tsv", "spirit_trees.tsv", "quetzals.tsv", "rides.tsv", "sailing.tsv");
	static final String SPELLBOOK_FILE = "spellbooks.tsv";

	static final String CATEGORY = "Category";
	static final String NAME = "Display info";
	static final String ORIGIN = "Origin";
	static final String DESTINATION = "Destination";
	private static final String CODE = "Code";
	static final String DURATION = "Duration";
	static final String MENU_TICKS = "Menu ticks";
	static final String SPENDS = "Spends";
	private static final String KIND = "Kind";
	static final String WHERE = "Where";
	private static final String FROM = "From";
	private static final String TO = "To";
	static final String MENU = "Menu";
	static final String OBJECT = "menuOption menuTarget objectID";

	private static final String ANY = "any";
	private static final String ANYWHERE = "anywhere";
	private static final String IN_HOUSE = "poh";
	private static final String TEMPORARY = "temporary";
	private static final String TOGGLE = "toggle ";
	private static final Pattern WHERE_REF = Pattern.compile("(object|npc):(\\d+)");

	private CatalogLoader()
	{
	}

	public static Catalog load()
	{
		RequirementParser parser = new RequirementParser();
		List<CatalogRow> teleports = new ArrayList<>();
		for (String file : TELEPORT_FILES)
		{
			for (TsvTable.Line line : read(file))
			{
				teleports.add(at(file, line, () -> teleport(line, parser)));
			}
		}
		List<SpellbookChange> changes = new ArrayList<>();
		for (TsvTable.Line line : read(SPELLBOOK_FILE))
		{
			changes.add(at(SPELLBOOK_FILE, line, () -> spellbookChange(line, parser)));
		}
		return new Catalog(List.copyOf(teleports), List.copyOf(changes));
	}

	static List<TsvTable.Line> read(String file)
	{
		try (InputStream in = CatalogLoader.class.getResourceAsStream(file))
		{
			if (in == null)
			{
				throw new IllegalStateException(file + " is missing");
			}
			return TsvTable.read(in);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("can't read " + file, e);
		}
	}

	private static CatalogRow teleport(TsvTable.Line line, RequirementParser parser)
	{
		String code = line.get(CODE);
		String menu = line.get(MENU);
		return CatalogRow.builder()
			.name(line.get(NAME))
			.category(Category.of(line.get(CATEGORY)))
			.origin(tile(line.get(ORIGIN)))
			.destination(tile(line.get(DESTINATION)))
			.code(code.isEmpty() ? null : code)
			.duration(Integer.parseInt(line.get(DURATION)))
			.menuTicks(Integer.parseInt(line.get(MENU_TICKS)))
			.spends(Spend.parse(line.get(SPENDS)))
			.requirements(CatalogRules.fairyRingStaff(parser.parse(line.getCells())))
			.menu(menu.isEmpty() ? null : menu)
			.objectId(objectId(line.get(OBJECT)))
			.build();
	}

	private static SpellbookChange spellbookChange(TsvTable.Line line, RequirementParser parser)
	{
		String where = line.get(WHERE);
		SpellbookChange.SpellbookChangeBuilder change = SpellbookChange.builder()
			.name(line.get(NAME))
			.temporary(TEMPORARY.equals(line.get(KIND)))
			.inHouse(where.startsWith(IN_HOUSE))
			.from(book(line.get(FROM)))
			.toggles(line.get(TO).startsWith(TOGGLE) ? book(line.get(TO).substring(TOGGLE.length())) : null)
			.duration(Integer.parseInt(line.get(DURATION)))
			.menuTicks(Integer.parseInt(line.get(MENU_TICKS)))
			.spends(Spend.parse(line.get(SPENDS)))
			.requirements(parser.parse(line.getCells()));
		if (!where.equals(ANYWHERE) && !where.startsWith(IN_HOUSE))
		{
			change.tile(tile(where.replaceAll("\\s*[a-z]+:\\d+", "")));
		}
		Matcher ref = WHERE_REF.matcher(where);
		while (ref.find())
		{
			int id = Integer.parseInt(ref.group(2));
			if (ref.group(1).equals("object"))
			{
				change.objectId(id);
			}
			else
			{
				change.npcId(id);
			}
		}
		SpellbookChange built = change.build();
		if (built.isInHouse() && built.getObjectId() != SpellbookChange.NO_ID)
		{
			HouseNeed piece = new HouseNeed(HouseNeed.Kind.FURNITURE, List.of(built.getObjectId()));
			return built.toBuilder().requirements(built.getRequirements().toBuilder().house(piece).build()).build();
		}
		return built;
	}

	/** The last word of "Travel Spirit tree 26261"; -1 for an empty cell. */
	private static int objectId(String cell)
	{
		return cell.isEmpty() ? -1 : Integer.parseInt(cell.substring(cell.lastIndexOf(' ') + 1));
	}

	private static Book book(String cell)
	{
		return cell.isEmpty() || cell.equals(ANY) ? null : Book.valueOf(cell.trim().toUpperCase(Locale.ROOT));
	}

	static WorldPoint tile(String cell)
	{
		if (cell.isEmpty())
		{
			return null;
		}
		String[] xyz = cell.trim().split("\\s+");
		if (xyz.length != 3)
		{
			throw new IllegalArgumentException("not a tile: '" + cell + "'");
		}
		return new WorldPoint(Integer.parseInt(xyz[0]), Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2]));
	}

	private static <T> T at(String file, TsvTable.Line line, Supplier<T> parse)
	{
		try
		{
			return parse.get();
		}
		catch (RuntimeException e)
		{
			throw new IllegalStateException(file + ":" + line.getNumber() + ": " + e.getMessage(), e);
		}
	}
}

package com.cluehelper.transport;

import com.cluehelper.player.PositionRules;
import java.util.List;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Fairy rings come as Shortest Path has them: an entry row (origin, no destination) per ring you can stand at, and a
 * landing row (destination and code, no origin) per code; any entry reaches any landing.
 */
@Value
@Builder
public class CatalogRow
{
	private static final String QUETZAL_MENU = "quetzal ";
	private static final String MINIGAME_SUFFIX = " Minigame Teleport";

	String name;
	Category category;
	/** Null for a teleport and for a fairy-ring landing. */
	WorldPoint origin;
	/** Null for a fairy-ring entry row. */
	WorldPoint destination;
	/** Null except on a fairy-ring landing row. */
	String code;
	int duration;
	int menuTicks;
	@Builder.Default
	List<Spend> spends = List.of();
	Requirements requirements;
	/**
	 * How to find the row's line in the menu it opens: {@code nexus 466 Wilderness} (struct id, map region),
	 * {@code box 10} (script 1688's index), {@code list Xeric's Inferno} (a 187 line), {@code op Karamja} (the
	 * object's own option; {@code op Set Destination > Level 13 Wilderness} picks a 187 line after it),
	 * {@code npc Charter} (the option of the NPC whose id is in objectId); null otherwise.
	 */
	String menu;
	/** -1 when none. */
	@Builder.Default
	int objectId = -1;

	public boolean isInHouse()
	{
		return PositionRules.POH_NODE.equals(origin);
	}

	/** Used where it stands, like house furniture or a spirit tree; fairy rings are entries and landings instead. */
	public boolean isLocated()
	{
		return origin != null && category != Category.FAIRY_RING;
	}

	/** Its menu is the quetzal map: {@code quetzal <table id>}. */
	public boolean isQuetzalMap()
	{
		return menu != null && menu.startsWith(QUETZAL_MENU);
	}

	/** -1 when the row isn't the quetzal map. */
	public int quetzalTableId()
	{
		return isQuetzalMap() ? Integer.parseInt(menu.substring(QUETZAL_MENU.length())) : -1;
	}

	public String minigameName()
	{
		return name.replace(MINIGAME_SUFFIX, "");
	}

	/** The place after the row name's colon, without its bracketed note. */
	public String nexusPlace()
	{
		String place = name.substring(name.indexOf(": ") + 2);
		int bracket = place.indexOf(" (");
		return bracket < 0 ? place : place.substring(0, bracket);
	}
}

package com.cluehelper.transport;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

public final class CatalogRules
{
	/** Never a teleport item: a glory that shows as 1704 has no charges. */
	public static final Set<Integer> UNCHARGED = Set.of(ItemID.AMULET_OF_GLORY, ItemID.TRAIL_AMULET_OF_GLORY,
		ItemID.RING_OF_WEALTH, ItemID.JEWL_NECKLACE_OF_SKILLS, ItemID.JEWL_BRACELET_OF_COMBAT,
		ItemID.XERIC_TALISMAN_EMPTY, ItemID.RING_OF_SHADOWS_UNCHARGED, ItemID.TOME_OF_FIRE_UNCHARGED,
		ItemID.TOME_OF_WATER_UNCHARGED, ItemID.TOME_OF_EARTH_UNCHARGED);

	private static final Set<Integer> FAIRY_RING_STAVES = Set.of(ItemID.DRAMEN_STAFF, ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF);
	private static final VarCheck LUMBRIDGE_ELITE_DONE =
		new VarCheck(VarCheck.Kind.VARBIT, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE, VarCheck.Op.EQUAL, 1);

	private CatalogRules()
	{
	}

	/** A fairy-ring staff clause counts only when wielded, and not at all once the Lumbridge elite diary is done. */
	public static Requirements fairyRingStaff(Requirements requirements)
	{
		List<ItemClause> clauses = new ArrayList<>();
		for (ItemClause clause : requirements.getItems())
		{
			boolean staffClause = clause.getBranches().stream()
				.anyMatch(branch -> branch.getIds().stream().anyMatch(FAIRY_RING_STAVES::contains));
			clauses.add(staffClause ? clause.wornOnly(LUMBRIDGE_ELITE_DONE) : clause);
		}
		return requirements.toBuilder().items(List.copyOf(clauses)).build();
	}
}

