package com.cluehelper.transport;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import lombok.Value;

@Value
public class Spend
{
	public enum Kind
	{
		RUNES, ITEM, CHARGE, COOLDOWN, DAILY, CAPE_USE
	}

	private static final int NO_VAR = -1;
	private static final String NONE = "none";

	Kind kind;
	/** The cooldown varp or the daily counter varbit; {@link #NO_VAR} for the other kinds. */
	int var;

	static List<Spend> parse(String cell)
	{
		List<Spend> spends = new ArrayList<>();
		for (String token : cell.split(";"))
		{
			String trimmed = token.trim();
			if (trimmed.isEmpty() || trimmed.equals(NONE))
			{
				continue;
			}
			String[] parts = trimmed.split(":", 2);
			Kind kind = Kind.valueOf(parts[0].toUpperCase(Locale.ROOT).replace('-', '_'));
			spends.add(new Spend(kind, parts.length == 2 ? Integer.parseInt(parts[1]) : NO_VAR));
		}
		return List.copyOf(spends);
	}
}

package com.cluehelper.transport;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

final class TsvTable
{
	private static final String COMMENT = "#";

	private TsvTable()
	{
	}

	static List<Line> read(InputStream in) throws IOException
	{
		List<Line> lines = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String[] header = null;
			String text;
			int number = 0;
			while ((text = reader.readLine()) != null)
			{
				number++;
				if (text.startsWith(COMMENT) || text.trim().isEmpty())
				{
					continue;
				}
				String[] values = text.split("\t", -1);
				if (header == null)
				{
					header = values;
					continue;
				}
				Map<String, String> cells = new HashMap<>();
				for (int i = 0; i < header.length && i < values.length; i++)
				{
					cells.put(header[i], values[i].trim());
				}
				lines.add(new Line(number, Collections.unmodifiableMap(cells)));
			}
		}
		return lines;
	}

	@Value
	static class Line
	{
		int number;
		Map<String, String> cells;

		String get(String column)
		{
			return cells.getOrDefault(column, "");
		}
	}
}

package com.cluehelper.transport;

import lombok.Value;

@Value
public class VarCheck
{
	public enum Kind
	{
		VARBIT, VARP
	}

	public enum Op
	{
		EQUAL("="), GREATER(">"), SMALLER("<"), BIT_SET("&"),
		/** The var holds the epoch minute a cooldown started; it passes once more than {@code value} minutes have gone by. */
		COOLDOWN_MINUTES("@");

		private final String code;

		Op(String code)
		{
			this.code = code;
		}

		static Op of(char code)
		{
			for (Op op : values())
			{
				if (op.code.charAt(0) == code)
				{
					return op;
				}
			}
			throw new IllegalArgumentException("no var operator " + code);
		}
	}

	Kind kind;
	int id;
	Op op;
	int value;

	public boolean test(int current, long nowMinutes)
	{
		switch (op)
		{
			case EQUAL:
				return current == value;
			case GREATER:
				return current > value;
			case SMALLER:
				return current < value;
			case BIT_SET:
				return (current & value) != 0;
			case COOLDOWN_MINUTES:
				return nowMinutes - current > value;
			default:
				throw new IllegalArgumentException("unhandled op " + op);
		}
	}

	/** The first epoch minute a failing cooldown passes; {@link Long#MAX_VALUE} for every other clause. */
	public long passesFrom(int current)
	{
		return op == Op.COOLDOWN_MINUTES ? (long) current + value + 1 : Long.MAX_VALUE;
	}

	String whyNot(int current, long nowMinutes)
	{
		if (op == Op.COOLDOWN_MINUTES)
		{
			return "on cooldown, " + (passesFrom(current) - nowMinutes) + " min left";
		}
		return describe() + " (is " + current + ")";
	}

	public String describe()
	{
		return (kind == Kind.VARBIT ? "varbit " : "varp ") + id + " " + op.code + " " + value;
	}
}

package com.cluehelper.ui;

public enum BoxState
{
	DORMANT("Off on this world",
		"Clue Helper stays off on seasonal, Deadman, beta and other special worlds."),
	CORE_OFF("Turn the Clue Scroll plugin back on",
		"Clue Helper works alongside RuneLite's Clue Scroll plugin. Turn it back on to continue."),
	READ_CLUE("Read the clue to start", null),
	NO_CLUE(null, null),
	WORKING("Working…",
		"Ranking routes from what you have."),
	ROUTES(null, null);

	private final String title;
	private final String detail;

	BoxState(String title, String detail)
	{
		this.title = title;
		this.detail = detail;
	}

	public String getTitle()
	{
		return title;
	}

	public String getDetail()
	{
		return detail;
	}

	public boolean showsRoutes()
	{
		return this == WORKING || this == ROUTES;
	}

	/** The box is always in view, so core off and dormant would nag a player who isn't doing a clue. */
	public boolean shownWhen(boolean carryingClue)
	{
		switch (this)
		{
			case NO_CLUE:
				return false;
			case CORE_OFF:
			case DORMANT:
				return carryingClue;
			default:
				return true;
		}
	}

	public static BoxState of(boolean dormant, boolean coreActive, boolean clueNeedsRead, boolean hasStep, boolean planning)
	{
		if (dormant)
		{
			return DORMANT;
		}
		if (!coreActive)
		{
			return CORE_OFF;
		}
		if (clueNeedsRead)
		{
			return READ_CLUE;
		}
		if (!hasStep)
		{
			return NO_CLUE;
		}
		return planning ? WORKING : ROUTES;
	}
}

