package com.cluehelper.ui;

import com.cluehelper.guide.SubStep;
import com.cluehelper.hotcold.HotColdView;
import com.cluehelper.player.Book;
import com.cluehelper.route.Plan;
import com.cluehelper.route.Route;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Builder;
import lombok.Value;

/** Built on the client thread and handed to the overlay as one immutable value. */
@Value
@Builder(toBuilder = true)
public class GuideBox
{
	public static final GuideBox EMPTY = GuideBox.builder().state(BoxState.NO_CLUE).build();
	private static final String NO_ROUTE = "No route from what you have";
	private static final String NO_PLAN_YET = "Waiting for the first plan";
	private static final Set<String> ROUTE_NOTES = Set.of(NO_ROUTE, NO_PLAN_YET, "Walk too long", "No target tile for this step yet");

	BoxState state;
	boolean carryingClue;
	/** Replaces the state's own detail line. */
	String statusDetail;
	String now;
	@Builder.Default
	List<String> nowItems = List.of();
	String nowDetail;
	String next;
	@Builder.Default
	List<String> notes = List.of();
	/** Null outside a hot/cold step, or with the probe planner off. */
	HotColdView hotCold;

	/** What the player is asked to do once, so that what they own counts. */
	@Value
	public static class Prompts
	{
		boolean openBank;
		/** The house is known only from the nexus varbits. */
		boolean visitHouse;
	}

	public boolean isShown()
	{
		return state.shownWhen(carryingClue);
	}

	/** "Working…" only while there is nothing else to show: a re-plan keeps the last guidance on screen. */
	public String title()
	{
		return state == BoxState.WORKING && hasGuidance() ? null : state.getTitle();
	}

	public String detail()
	{
		return title() == null ? null : statusDetail != null ? statusDetail : state.getDetail();
	}

	private boolean hasGuidance()
	{
		return now != null || hotCold != null || !notes.isEmpty();
	}

	/** At the step itself nothing is travelled: no notes about routes. */
	public GuideBox atTheStep()
	{
		List<String> kept = notes.stream().filter(note -> !ROUTE_NOTES.contains(note)).collect(Collectors.toList());
		return toBuilder().notes(List.copyOf(kept)).build();
	}

	/**
	 * @param committed the route the guide follows, which the highlights show
	 * @param next null unless the next sub-step is wanted
	 * @param f2pBook the book a member is stuck on while on an F2P world, or null
	 */
	public static GuideBox of(BoxState state, String dormantReason, Plan plan, Route committed, SubStep now, SubStep next,
		Book f2pBook, Prompts prompts)
	{
		GuideBoxBuilder box = GuideBox.builder().state(state);
		if (state == BoxState.DORMANT)
		{
			return box.statusDetail("Clue Helper stays off on this " + dormantReason + ".").build();
		}
		if (!state.showsRoutes() || plan == null)
		{
			return box.build();
		}
		if (now != null)
		{
			box.now(now.getText()).nowItems(now.getItems()).nowDetail(now.getDetail()).next(next == null ? null : next.getText());
		}
		List<String> notes = new ArrayList<>();
		if (plan.getNote() != null && !plan.getNote().equals(Plan.NONE.getNote()))
		{
			notes.add(capitalise(plan.getNote()));
		}
		if (f2pBook != null)
		{
			notes.add("You're on " + bookName(f2pBook) + "; F2P worlds can't change book");
		}
		notes.addAll(plan.getRequirementNotes());
		if (prompts.isOpenBank())
		{
			notes.add("Open your bank once so banked teleports count");
		}
		if (prompts.isVisitHouse())
		{
			notes.add("Visit your house once so its furniture counts");
		}
		boolean noRoute = committed == null && plan.getBest() == null;
		if (noRoute && notes.isEmpty() && !(plan == Plan.NONE && state == BoxState.WORKING))
		{
			notes.add(plan == Plan.NONE ? NO_PLAN_YET : NO_ROUTE);
		}
		return box.notes(notes).build();
	}

	static String bookName(Book book)
	{
		String name = book.name().toLowerCase(Locale.ROOT);
		return Character.toUpperCase(name.charAt(0)) + name.substring(1);
	}

	private static String capitalise(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}
}

package com.cluehelper.ui;

import com.cluehelper.ClueHelperConfig;
import com.cluehelper.guide.StepGuide;
import com.cluehelper.hotcold.HotColdPlan;
import com.cluehelper.hotcold.HotColdService;
import com.cluehelper.hotcold.HotColdView;
import com.cluehelper.link.ClueLink;
import com.cluehelper.memory.BankMemory;
import com.cluehelper.player.Book;
import com.cluehelper.player.HouseState;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.poh.PohService;
import com.cluehelper.route.PlannerRunner;
import com.cluehelper.route.RoutePlanner;
import com.cluehelper.step.ClueTypes;
import com.cluehelper.step.HotColdTier;
import com.cluehelper.step.Step;
import com.cluehelper.transport.AvailabilityService;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Client thread only. Reads the guide, the routes and the hot/cold planner into one box and hands it to the overlay. */
@Singleton
public class GuideBoxPresenter
{
	private final ClueLink clueLink;
	private final PlayerModel playerModel;
	private final PlannerRunner planner;
	private final RoutePlanner routes;
	private final StepGuide guide;
	private final HotColdService hotCold;
	private final BankMemory bankMemory;
	private final PohService poh;
	private final AvailabilityService availability;
	private final ClueHelperConfig config;
	private final GuideOverlay overlay;

	@Inject
	GuideBoxPresenter(ClueLink clueLink, PlayerModel playerModel, PlannerRunner planner, RoutePlanner routes, StepGuide guide,
		HotColdService hotCold, BankMemory bankMemory, PohService poh, AvailabilityService availability, ClueHelperConfig config,
		GuideOverlay overlay)
	{
		this.clueLink = clueLink;
		this.playerModel = playerModel;
		this.planner = planner;
		this.routes = routes;
		this.guide = guide;
		this.hotCold = hotCold;
		this.bankMemory = bankMemory;
		this.poh = poh;
		this.availability = availability;
		this.config = config;
		this.overlay = overlay;
	}

	public void refresh()
	{
		GuideBox box = GuideBox.of(boxState(), dormantReason(), routes.getPlan(), guide.getRoute(), guide.getCurrent(),
			config.showNextStep() ? guide.getNext() : null, stuckBookOnF2p(), prompts());
		GuideBox atStep = guide.isAtStep() ? box.atTheStep() : box;
		GuideBox.GuideBoxBuilder shown = atStep.toBuilder().carryingClue(clueLink.carriesClue());
		if (atStep.getState().showsRoutes())
		{
			shown.hotCold(hotColdView());
		}
		overlay.show(shown.build());
	}

	public BoxState boxState()
	{
		return BoxState.of(dormantReason() != null, clueLink.isActive(), clueLink.needsRead(), clueLink.hasStep(), planner.isWorking());
	}

	private String dormantReason()
	{
		PlayerSnapshot snapshot = playerModel.getSnapshot();
		return snapshot == null ? null : snapshot.getDormantReason();
	}

	private HotColdView hotColdView()
	{
		Step step = clueLink.getCurrentStep();
		if (step == null || !ClueTypes.HOT_COLD.equals(step.getType()) || !config.hotColdPlanner())
		{
			return null;
		}
		HotColdPlan plan = hotCold.getPlan();
		if (plan == null || !plan.getStepKey().equals(step.getKey()))
		{
			return null;
		}
		HotColdTier tier = HotColdTier.of(step.getTier());
		return HotColdView.of(new HotColdView.Inputs(plan, hotCold.getCoreSpots(), hotCold.isCoreReset(),
			hotCold.spotsOf(tier), tier, hotCold.hitpoints()));
	}

	private GuideBox.Prompts prompts()
	{
		PlayerSnapshot snapshot = playerModel.getSnapshot();
		boolean bankCounts = snapshot != null && availability.bankCounts(snapshot);
		HouseState house = poh.getHouse();
		boolean houseKnown = !house.getNexusKeys().isEmpty() || !house.getFurniture().isEmpty();
		boolean onlyNexusVarbitsKnown = houseKnown && house.getSource() == HouseState.Source.VARBITS;
		return new GuideBox.Prompts(bankMemory.getBank() == null && bankCounts, onlyNexusVarbitsKnown);
	}

	/** Members keep their book on an F2P world, where no book can be changed and only Standard has teleports. */
	private Book stuckBookOnF2p()
	{
		PlayerSnapshot snapshot = playerModel.getSnapshot();
		if (snapshot == null || snapshot.isMembersWorld() || snapshot.getSpellbook() == null)
		{
			return null;
		}
		Book book = snapshot.getSpellbook().getBook();
		return book == null || book == Book.STANDARD ? null : book;
	}
}

package com.cluehelper.ui;

import com.cluehelper.ClueHelperConfig;
import com.cluehelper.ClueHelperPlugin;
import com.cluehelper.hotcold.HotColdView;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/** The guidance text, under the Clue Scroll plugin's own box and as wide. Renders only the value it was handed. */
@Singleton
public class GuideOverlay extends OverlayPanel
{
	/** Core's box has the lowest named priority; the lower one stacks under it. */
	private static final float BELOW_CORE_CLUE_BOX = PRIORITY_LOW - 0.01f;
	private static final String TITLE = "Clue Helper";
	private static final Color TEXT = Color.WHITE;
	private static final Color MUTED = new Color(190, 190, 190);
	private static final Color WARNING = new Color(255, 170, 60);
	/** Dimmer than the item lines, so the step after this one reads as not yet. */
	private static final Color UPCOMING = new Color(135, 135, 135);
	private static final char NO_BREAK = ' ';

	private final ClueHelperConfig config;
	private volatile GuideBox box = GuideBox.EMPTY;
	private FontMetrics metrics;

	@Inject
	GuideOverlay(ClueHelperPlugin plugin, ClueHelperConfig config)
	{
		super(plugin);
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(BELOW_CORE_CLUE_BOX);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, "Clue Helper overlay");
	}

	/** Any thread. */
	public void show(GuideBox box)
	{
		this.box = box;
	}

	/** Readable from any thread. */
	public GuideBox getShown()
	{
		return box;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GuideBox shown = box;
		if (!shown.isShown() || !config.showBox())
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(ComponentConstants.STANDARD_WIDTH, 0));
		metrics = graphics.getFontMetrics();
		panelComponent.getChildren().add(TitleComponent.builder().text(TITLE).color(TEXT).build());
		line(shown.title(), TEXT);
		line(shown.detail(), MUTED);
		line(shown.getNow(), TEXT);
		shown.getNowItems().forEach(item -> line("- " + item, MUTED));
		line(shown.getNowDetail(), MUTED);
		if (shown.getHotCold() != null)
		{
			gap();
			hotCold(shown.getHotCold());
		}
		if (!shown.getNotes().isEmpty())
		{
			gap();
			shown.getNotes().forEach(note -> line(note, WARNING));
		}
		if (shown.getNext() != null)
		{
			gap();
			panelComponent.getChildren().add(LineComponent.builder().left(closeColours(shown.getNext(), UPCOMING)).leftColor(UPCOMING)
				.leftFont(FontManager.getRunescapeSmallFont()).build());
		}
		return super.render(graphics);
	}

	private void hotCold(HotColdView view)
	{
		line(view.getTitle(), TEXT);
		List<String> lines = view.getLines();
		for (int i = 0; i < lines.size(); i++)
		{
			line(lines.get(i), i == 0 ? MUTED : TEXT);
		}
		view.getWarnings().forEach(warning -> line(warning, WARNING));
	}

	private void gap()
	{
		panelComponent.getChildren().add(LineComponent.builder().left("").build());
	}

	private void line(String text, Color colour)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		for (String part : text.contains("<col") ? wrapTagged(text) : List.of(text))
		{
			panelComponent.getChildren().add(LineComponent.builder().left(closeColours(part, colour)).leftColor(colour).build());
		}
	}

	/**
	 * LineComponent measures a word with its colour tags when it wraps, so a coloured hotkey wraps a line early. Such a
	 * line is wrapped here on its visible text, each piece held together by non-breaking spaces.
	 */
	private List<String> wrapTagged(String text)
	{
		int width = ComponentConstants.STANDARD_WIDTH - 2 * ComponentConstants.STANDARD_BORDER;
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String joined = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(Text.removeTags(joined)) > width)
			{
				lines.add(line.toString().replace(' ', NO_BREAK));
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(joined);
			}
		}
		lines.add(line.toString().replace(' ', NO_BREAK));
		return lines;
	}

	/** The box's text knows no closing colour tag: a coloured hotkey switches back to the line's own colour. */
	private static String closeColours(String text, Color colour)
	{
		return text.replace("</col>", ColorUtil.colorTag(colour));
	}
}

package com.cluehelper.ui;

import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.ImageUtil;

/**
 * How every Clue Helper highlight looks, so an overlay only decides what to highlight. Whatever is clicked is outlined
 * in cyan, and filled as well when a plain left click does what the step needs. Menu text is recoloured instead (see
 * MenuLines); only a line or widget without text gets a box. Objects and NPCs on another floor are not drawn: the
 * player can't see them yet.
 */
@Singleton
@Slf4j
public class Highlighter
{
	/** Wide enough to show on the nexus, which is cyan itself. */
	private static final int OUTLINE_WIDTH = 4;
	private static final int FEATHER = 4;
	private static final int ARC = 6;
	private static final float STROKE = 2f;

	private final Client client;
	private final ModelOutlineRenderer outlines;
	private final ItemManager itemManager;
	private final Set<Integer> unmodelled = new HashSet<>();

	private final ModelSilhouette silhouette;

	@Inject
	Highlighter(Client client, ModelOutlineRenderer outlines, ItemManager itemManager, ModelSilhouette silhouette)
	{
		this.client = client;
		this.silhouette = silhouette;
		this.outlines = outlines;
		this.itemManager = itemManager;
	}

	/**
	 * The client's own getModel throws a NullPointerException for some dynamic objects (seen at Trollheim and after
	 * teleports), in our fill and in RuneLite's outline renderer alike; such an object goes unhighlighted that frame.
	 */
	public void object(Graphics2D graphics, TileObject object, boolean leftClick)
	{
		if (!onPlayersFloor(object.getPlane()))
		{
			return;
		}
		try
		{
			if (leftClick)
			{
				graphics.setColor(Markers.ONE_CLICK_FILL);
				graphics.fill(silhouette.of(object));
			}
			outlines.drawOutline(object, OUTLINE_WIDTH, Markers.COLOUR, FEATHER);
		}
		catch (NullPointerException e)
		{
			if (unmodelled.add(object.getId()))
			{
				log.warn("No model to highlight object {} at {}", object.getId(), object.getWorldLocation(), e);
			}
		}
	}

	public void npc(Graphics2D graphics, NPC npc, boolean leftClick)
	{
		// An NPC that despawned since the last search has no model, which the outline renderer doesn't check.
		if (npc.getModel() != null && onPlayersFloor(npc.getWorldLocation().getPlane()))
		{
			if (leftClick)
			{
				graphics.setColor(Markers.ONE_CLICK_FILL);
				graphics.fill(silhouette.of(npc));
			}
			outlines.drawOutline(npc, OUTLINE_WIDTH, Markers.COLOUR, FEATHER);
		}
	}

	private boolean onPlayersFloor(int plane)
	{
		WorldView view = client.getTopLevelWorldView();
		return view != null && plane == view.getPlane();
	}

	public void item(Graphics2D graphics, int itemId, int quantity, Rectangle bounds, boolean leftClick)
	{
		if (leftClick)
		{
			BufferedImage image = itemManager.getImage(itemId, quantity, false);
			graphics.drawImage(ImageUtil.fillImage(image, Markers.ONE_CLICK_FILL), bounds.x, bounds.y, null);
		}
		graphics.drawImage(itemManager.getItemOutline(itemId, quantity, Markers.COLOUR), bounds.x, bounds.y, null);
	}

	/** An item's outline scaled into {@code bounds}, for a picture larger than the inventory icon (a scroll book entry). */
	public void itemScaled(Graphics2D graphics, int itemId, Rectangle bounds)
	{
		BufferedImage outline = itemManager.getItemOutline(itemId, 1, Markers.COLOUR);
		double scale = Math.min(bounds.getWidth() / outline.getWidth(), bounds.getHeight() / outline.getHeight());
		int width = (int) Math.round(outline.getWidth() * scale);
		int height = (int) Math.round(outline.getHeight() * scale);
		graphics.drawImage(outline, bounds.x + (bounds.width - width) / 2, bounds.y + (bounds.height - height) / 2, width, height, null);
	}

	public void box(Graphics2D graphics, Rectangle bounds)
	{
		box(graphics, new RoundRectangle2D.Double(bounds.x, bounds.y, bounds.width, bounds.height, ARC, ARC));
	}

	/** A spell, a tab stone, a fairy ring dial: things without text or a model. */
	public void box(Graphics2D graphics, Shape shape)
	{
		graphics.setColor(Markers.FILL);
		graphics.fill(shape);
		graphics.setColor(Markers.COLOUR);
		graphics.setStroke(new BasicStroke(STROKE));
		graphics.draw(shape);
	}

	/** A spot to walk to with nothing on it to outline. */
	public void tile(Graphics2D graphics, Polygon tile)
	{
		OverlayUtil.renderPolygon(graphics, tile, Markers.COLOUR);
