package com.cluehelper.ui;

import java.awt.Shape;
import java.awt.geom.Path2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Renderable;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * The object's or NPC's visible faces as one shape. Its clickbox won't do: a model that uses its bounding box as the clickbox
 * (Xeric's talisman, fairy rings, spirit trees) would fill as a box. Positions follow core's ModelOutlineRenderer, so
 * the fill sits inside the outline.
 */
@Singleton
final class ModelSilhouette
{
	private static final int OFF_SCREEN = Integer.MIN_VALUE;
	private static final int HIDDEN_FACE = -2;
	private static final int SEE_THROUGH = 254;
	private static final int NO_ROTATION = 0;

	private final Client client;

	@Inject
	ModelSilhouette(Client client)
	{
		this.client = client;
	}

	Shape of(TileObject object)
	{
		Path2D.Float shape = new Path2D.Float(Path2D.WIND_NON_ZERO);
		if (object instanceof GameObject)
		{
			GameObject game = (GameObject) object;
			addFaces(shape, object, game.getRenderable(), 0, 0, game.getModelOrientation());
		}
		else if (object instanceof DecorativeObject)
		{
			DecorativeObject decoration = (DecorativeObject) object;
			addFaces(shape, object, decoration.getRenderable(), decoration.getXOffset(), decoration.getYOffset(), NO_ROTATION);
			addFaces(shape, object, decoration.getRenderable2(), decoration.getXOffset2(), decoration.getYOffset2(), NO_ROTATION);
		}
		else if (object instanceof WallObject)
		{
			WallObject wall = (WallObject) object;
			addFaces(shape, object, wall.getRenderable1(), 0, 0, NO_ROTATION);
			addFaces(shape, object, wall.getRenderable2(), 0, 0, NO_ROTATION);
		}
		else if (object instanceof GroundObject)
		{
			addFaces(shape, object, ((GroundObject) object).getRenderable(), 0, 0, NO_ROTATION);
		}
		return shape;
	}

	Shape of(NPC npc)
	{
		Path2D.Float shape = new Path2D.Float(Path2D.WIND_NON_ZERO);
		LocalPoint at = npc.getLocalLocation();
		WorldView view = npc.getWorldView();
		if (at != null && view != null)
		{
			int z = Perspective.getTileHeight(client, at, view.getPlane()) - npc.getAnimationHeightOffset();
			addFaces(shape, view, npc, at.getX(), at.getY(), z, npc.getCurrentOrientation());
		}
		return shape;
	}

	private void addFaces(Path2D shape, TileObject object, Renderable renderable, int xOffset, int yOffset,
		int orientation)
	{
		if (renderable != null)
		{
			addFaces(shape, object.getWorldView(), renderable, object.getX() + xOffset, object.getY() + yOffset,
				object.getZ() - renderable.getAnimationHeightOffset(), orientation);
		}
	}

	/** Back faces are left out, so every face added winds the same way and overlaps fill once. */
	private void addFaces(Path2D shape, WorldView view, Renderable renderable, int localX, int localY, int z,
		int orientation)
	{
		Model model = renderable instanceof Model ? (Model) renderable : renderable.getModel();
		if (model == null)
		{
			return;
		}
		int count = model.getVerticesCount();
		int[] x = new int[count];
		int[] y = new int[count];
		Perspective.modelToCanvas(client, view, count, localX, localY, z, orientation, model.getVerticesX(), model.getVerticesZ(),
			model.getVerticesY(), x, y);
		int[] first = model.getFaceIndices1();
		int[] second = model.getFaceIndices2();
		int[] third = model.getFaceIndices3();
		for (int face = 0; face < model.getFaceCount(); face++)
		{
			int a = first[face];
			int b = second[face];
			int c = third[face];
			boolean onScreen = y[a] != OFF_SCREEN && y[b] != OFF_SCREEN && y[c] != OFF_SCREEN;
			if (onScreen && isDrawn(model, face) && facesCamera(x[a], y[a], x[b], y[b], x[c], y[c]))
			{
				shape.moveTo(x[a], y[a]);
				shape.lineTo(x[b], y[b]);
				shape.lineTo(x[c], y[c]);
				shape.closePath();
			}
		}
	}

	private static boolean isDrawn(Model model, int face)
	{
		byte[] transparencies = model.getFaceTransparencies();
		boolean seeThrough = transparencies != null && (transparencies[face] & 0xFF) >= SEE_THROUGH;
		return !seeThrough && model.getFaceColors3()[face] != HIDDEN_FACE;
	}

	private static boolean facesCamera(int x1, int y1, int x2, int y2, int x3, int y3)
	{
		return (y2 - y1) * (x3 - x2) - (x2 - x1) * (y3 - y2) > 0;
	}
}

package com.cluehelper.ui;

import com.cluehelper.route.Exit;
import com.cluehelper.route.SceneDoors;
import com.cluehelper.route.WalkTable;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/** The objects a path line leads through: each walk row it takes (a ladder, stairs, a shortcut) and each closed door. */
@Singleton
final class PathObjects
{
	/** A large staircase stands a few tiles from the row's origin tile. */
	private static final int ROW_OBJECT_TILES = 3;
	/** Row objects that open only after another is used each time, by id: Meiyerditch's barricade after its rocky surface. */
	private static final Map<Integer, Prerequisite> FIRST = Map.of(18054, new Prerequisite(18056, "Search"));

	static boolean isUsedFirst(int objectId)
	{
		return FIRST.values().stream().anyMatch(first -> first.getObjectId() == objectId);
	}

	@Value
	private static class Prerequisite
	{
		int objectId;
		String option;
	}
	private static final int WEST = 1;
	private static final int NORTH = 2;
	private static final int EAST = 4;
	private static final int SOUTH = 8;

	private final Client client;
	private final SceneDoors doors;

	@Inject
	PathObjects(Client client, SceneDoors doors)
	{
		this.client = client;
		this.doors = doors;
	}

	/** Client thread only. Each object with the menu option that takes the path through it. */
	Map<TileObject, String> along(WorldView view, WalkTable table, List<WorldPoint> path)
	{
		Map<TileObject, String> objects = new LinkedHashMap<>();
		for (int i = 0; i + 1 < path.size(); i++)
		{
			WorldPoint from = path.get(i);
			WorldPoint to = path.get(i + 1);
			if (isJump(from, to))
			{
				addRowObject(objects, view, table == null ? null : table.rowObject(from, to), from);
			}
			else
			{
				addClosedDoor(objects, view, from, to);
				addRowObject(objects, view, table == null ? null : table.rowObject(from, to), from);
				addWalkedOverRow(objects, view, table, path, i);
			}
		}
		return objects;
	}

	/**
	 * A row across tiles the collision map leaves open (the Isafdar sticks, a trap stepped on otherwise): the line walks
	 * it tile by tile.
	 */
	private void addWalkedOverRow(Map<TileObject, String> objects, WorldView view, WalkTable table,
		List<WorldPoint> path, int origin)
	{
		for (int j = origin + 2; table != null && j < Math.min(path.size(), origin + 1 + ROW_OBJECT_TILES + 2); j++)
		{
			addRowObject(objects, view, table.rowObject(path.get(origin), path.get(j)), path.get(origin));
		}
	}

	/** Two tiles of a walk that aren't neighbours on one floor: a row (stairs, a shortcut) joins them. */
	static boolean isJump(WorldPoint from, WorldPoint to)
	{
		return from.getPlane() != to.getPlane() || Math.max(Math.abs(from.getX() - to.getX()), Math.abs(from.getY() - to.getY())) > 1;
	}

	private void addRowObject(Map<TileObject, String> objects, WorldView view, Exit row, WorldPoint origin)
	{
		if (row == null || row.getObjectId() < 0)
		{
			return;
		}
		Prerequisite first = FIRST.get(row.getObjectId());
		TileObject before = first == null ? null : objectNear(view, first.getObjectId(), origin);
		if (before != null)
		{
			objects.putIfAbsent(before, first.getOption());
		}
		TileObject object = objectNear(view, row.getObjectId(), origin);
		if (object != null)
		{
			objects.putIfAbsent(object, row.getOption());
		}
	}

	/**
	 * Client thread only. The objects named as {@code crossed} is on the tiles {@code around} a jump: every stepping stone
	 * of a crossing, both ends of a pipe, where the walk data names only one.
	 */
	List<TileObject> sameNamed(WorldView view, TileObject crossed, Rectangle around)
	{
		String name = nameOf(crossed);
		List<TileObject> found = new ArrayList<>();
		for (int x = around.x; x < around.x + around.width; x++)
		{
			for (int y = around.y; y < around.y + around.height; y++)
			{
				Tile tile = tile(view, new WorldPoint(x, y, crossed.getPlane()));
				if (tile != null)
				{
					objectsOn(tile).stream().filter(object -> name != null && name.equals(nameOf(object))).forEach(found::add);
				}
			}
		}
		return found;
	}

	private List<TileObject> objectsOn(Tile tile)
	{
		List<TileObject> objects = new ArrayList<>();
		for (GameObject object : tile.getGameObjects())
		{
			if (object != null)
			{
				objects.add(object);
			}
		}
		for (TileObject object : new TileObject[]{tile.getWallObject(), tile.getGroundObject(), tile.getDecorativeObject()})
		{
			if (object != null)
			{
				objects.add(object);
			}
		}
		return objects;
	}

	private String nameOf(TileObject object)
	{
		ObjectComposition placed = client.getObjectDefinition(object.getId());
		ObjectComposition shown = placed.getImpostorIds() != null ? placed.getImpostor() : placed;
		return shown == null ? null : shown.getName();
	}

	/** The one nearest the row's origin: a pipe's two ends share an id, and the one clicked is the near end. */
	private TileObject objectNear(WorldView view, int id, WorldPoint origin)
	{
		TileObject nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (int dx = -ROW_OBJECT_TILES; dx <= ROW_OBJECT_TILES; dx++)
		{
			for (int dy = -ROW_OBJECT_TILES; dy <= ROW_OBJECT_TILES; dy++)
			{
				TileObject object = objectOn(tile(view, origin.dx(dx).dy(dy)), id);
				int distance = dx * dx + dy * dy;
				if (object != null && distance < nearestDistance)
				{
					nearest = object;
					nearestDistance = distance;
				}
			}
		}
		return nearest;
	}

	private TileObject objectOn(Tile tile, int id)
	{
		return tile == null ? null : objectsOn(tile).stream().filter(object -> isObject(object, id)).findFirst().orElse(null);
	}

	/** Shortest Path names a multiloc by the form it shows (the Kharazi broken cart: 28931, placed as 2216). */
	private boolean isObject(TileObject object, int id)
	{
		if (object.getId() == id)
		{
			return true;
		}
		ObjectComposition placed = client.getObjectDefinition(object.getId());
		ObjectComposition shown = placed.getImpostorIds() != null ? placed.getImpostor() : null;
		return shown != null && shown.getId() == id;
	}

	private void addClosedDoor(Map<TileObject, String> objects, WorldView view, WorldPoint from, WorldPoint to)
	{
		int dx = Integer.signum(to.getX() - from.getX());
		int dy = Integer.signum(to.getY() - from.getY());
		int fromSides = (dx > 0 ? EAST : dx < 0 ? WEST : 0) | (dy > 0 ? NORTH : dy < 0 ? SOUTH : 0);
		int toSides = (dx > 0 ? WEST : dx < 0 ? EAST : 0) | (dy > 0 ? SOUTH : dy < 0 ? NORTH : 0);
		for (TileObject door : new TileObject[]{closedDoorFacing(view, from, fromSides),
			closedDoorFacing(view, to, toSides), doors.diagonalDoor(tile(view, to))})
		{
			if (door != null)
			{
				objects.putIfAbsent(door, doors.openOption(door.getId()));
			}
		}
	}

	private WallObject closedDoorFacing(WorldView view, WorldPoint at, int sides)
	{
		Tile tile = tile(view, at);
		WallObject wall = tile == null ? null : tile.getWallObject();
		return wall != null && (wall.getOrientationA() & sides) != 0 && doors.opensOnClick(wall) ? wall : null;
	}

	private static Tile tile(WorldView view, WorldPoint at)
	{
		int x = at.getX() - view.getBaseX();
		int y = at.getY() - view.getBaseY();
		Tile[][][] tiles = view.getScene().getTiles();
		if (at.getPlane() < 0 || at.getPlane() >= tiles.length || x < 0 || y < 0 || x >= tiles[at.getPlane()].length
			|| y >= tiles[at.getPlane()][x].length)
		{
			return null;
		}
		return tiles[at.getPlane()][x][y];
	}
}

package com.cluehelper.ui;

import com.cluehelper.route.Ground;
import com.cluehelper.route.LoadedScene;
import com.cluehelper.route.PlannerRunner;
import com.cluehelper.route.RoutePlanner;
import com.cluehelper.route.WalkCosts;
import com.cluehelper.route.WalkData;
import com.cluehelper.route.WalkGoal;
import com.cluehelper.route.WorldWalk;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/**
 * The walk the path line draws, searched off the client thread, on its own runner so it never supersedes a route plan:
 * once per goal, and again once the player leaves it. Client thread.
 */
final class WalkLine
{
	/** A player this far from every tile of the walk still ahead took another way, or went back over an obstacle. */
	private static final int OFF_WALK_TILES = 2;

	private final Client client;
	private final RoutePlanner routes;
	private final WorldWalk walker;
	private final PlannerRunner runner;

	private WalkGoal goal;
	private WalkCosts here;
	private List<WorldPoint> walk = List.of();
	/** The index of the walk's tile the player last stood nearest. */
	private int passed;
	private boolean stale;

	@Inject
	WalkLine(Client client, RoutePlanner routes, WorldWalk walker, ScheduledExecutorService executor, ClientThread clientThread)
	{
		this.client = client;
		this.routes = routes;
		this.walker = walker;
		this.runner = new PlannerRunner(executor, clientThread);
	}

	/** Searches the walk to {@code goal} again when it is new, left, or stale; the walk found last stays until then. */
	void follow(WorldView view, WalkCosts here, WalkGoal goal)
	{
		boolean newGoal = !goal.equals(this.goal);
		boolean again = stale || isLeft() || walk.isEmpty() && here != this.here;
		if (newGoal || again && !runner.isWorking())
		{
			search(view, here, goal);
		}
	}

	/** The walk found last, from where the player stood then; it stands while the next search runs (a wandering NPC). */
	List<WorldPoint> getWalk()
	{
		return walk;
	}

	/**
	 * Moves on along the walk to its tile nearest the player, never back. Of tiles as near, the later one wins (past a
	 * door, the tile before it can be as near through the wall, and the door would count as ahead again), unless the
	 * player can't step to it yet.
	 */
	void advance()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		WorldPoint at = local.getWorldLocation();
		int nearestDistance = Integer.MAX_VALUE;
		for (int i = passed; i < walk.size(); i++)
		{
			WorldPoint tile = walk.get(i);
			int distance = tile.getPlane() == at.getPlane() ? tile.distanceTo2D(at) : Integer.MAX_VALUE;
			if (distance < nearestDistance || distance == nearestDistance && !isClosedOff(at, tile))
			{
				passed = i;
				nearestDistance = distance;
			}
		}
	}

	/**
	 * A neighbour the game won't step to now. The line is laid with doors open, so it can cross a doorway diagonally and
	 * miss the tile in front of the door: standing there, the tile behind a door not yet opened is as near as the one
	 * before it, but not passed.
	 */
	private boolean isClosedOff(WorldPoint at, WorldPoint tile)
	{
		if (tile.getPlane() != at.getPlane() || tile.distanceTo2D(at) != 1)
		{
			return false;
		}
		LoadedScene live = LoadedScene.capture(client.getTopLevelWorldView());
		return live != null && live.contains(at) && live.contains(tile) && !live.canStep(at, tile);
	}

	/** The walk from the player on: from the tile {@link #advance} reached. */
	List<WorldPoint> getAhead()
	{
		return walk.subList(Math.min(passed, walk.size()), walk.size());
	}

	/** After a gate, cart or shortcut the player may have gone back the way they came. */
	void forget()
	{
		stale = true;
	}

	/**
	 * A goal searched again from a tile no walk leaves (a stepping stone mid-shortcut) finds nothing: the walk found
	 * before stands. A new goal out of reach still clears it, never leading the wrong way.
	 */
	private void search(WorldView view, WalkCosts here, WalkGoal goal)
	{
		boolean sameGoal = goal.equals(this.goal);
		this.goal = goal;
		this.here = here;
		stale = false;
		Player local = client.getLocalPlayer();
		WalkData.Loaded data = routes.getWalk();
		if (local == null || data == null)
		{
			return;
		}
		Ground ground = view.isInstance() ? Ground.sceneOnly(here.getScene())
			: Ground.world(data.getMap(), here.getScene(), data.getTable(), routes.openRows());
		WorldPoint from = local.getWorldLocation();
		runner.submit(() -> walker.path(ground, from, goal), found ->
		{
			if (found.isEmpty() && sameGoal)
			{
				return;
			}
			walk = found;
			passed = 0;
		});
	}

	private boolean isLeft()
	{
		Player local = client.getLocalPlayer();
		if (local == null || walk.isEmpty())
		{
			return false;
		}
		WorldPoint at = local.getWorldLocation();
		return getAhead().stream().noneMatch(tile -> tile.getPlane() == at.getPlane() && tile.distanceTo2D(at) <= OFF_WALK_TILES);
	}
}

package com.cluehelper.ui;

import com.cluehelper.ClueHelperConfig;
import com.cluehelper.guide.StepGuide;
import com.cluehelper.guide.SubStep;
import com.cluehelper.link.ClueLink;
