		this.lines = lines;
		this.dials = dials;
		this.saveFrame = saveFrame;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!event.getCommand().equalsIgnoreCase("ch-ring"))
		{
			return;
		}
		code = event.getArguments().length == 0 ? null : event.getArguments()[0].toUpperCase();
		log.info("{} t{} forced code {}", TAG, client.getTickCount(), code);
	}

	/** Runs after the plugin's own pass, which resets the colour of lines its (empty) target doesn't want. */
	@Subscribe(priority = -3)
	public void onClientTick(ClientTick tick)
	{
		if (code != null)
		{
			lines.colourLines(target(), ScrollBook.NO_WIDGET, true);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == GROUP)
		{
			dumpPending = true;
		}
	}

	@Subscribe(priority = -3)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getParam1() >>> 16 == GROUP)
		{
			log.info("{} t{} click {} on {} dials {}", TAG, client.getTickCount(), event.getMenuOption(), name(event.getParam1()), dials());
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		for (int dial = 0; dial < DIAL_VARBITS.length; dial++)
		{
			if (event.getVarbitId() == DIAL_VARBITS[dial])
			{
				log.info("{} t{} dial {} -> {} dials {}", TAG, client.getTickCount(), dial + 1, event.getValue(), dials());
				framePending = true;
			}
		}
	}

	@Subscribe(priority = -3)
	public void onGameTick(GameTick tick)
	{
		if (dumpPending)
		{
			dumpPending = false;
			dumpWidgets();
			framePending = true;
		}
		if (framePending && client.getWidget(InterfaceID.Fairyrings.CONFIRM) != null)
		{
			framePending = false;
			saveFrame.accept(new File(PohTrace.FRAMES, String.format("dial-%03d-t%d-%s.png", ++frameCount, client.getTickCount(), dials())));
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (code == null)
		{
			return null;
		}
		graphics.setStroke(new BasicStroke(2f));
		for (Rectangle line : lines.lines(target()))
		{
			draw(graphics, line);
		}
		dials.shapes(code).forEach(shape -> draw(graphics, shape));
		return null;
	}

	private static void draw(Graphics2D graphics, Shape shape)
	{
		graphics.setColor(FILL);
		graphics.fill(shape);
		graphics.setColor(COLOUR);
		graphics.draw(shape);
	}

	private MenuTarget target()
	{
		return MenuTarget.fairyCode(code);
	}

	private void dumpWidgets()
	{
		List<String> widgets = new ArrayList<>();
		for (int id = InterfaceID.Fairyrings.A; id <= InterfaceID.Fairyrings.ROOT_GRAPHIC27; id++)
		{
			Widget w = client.getWidget(id);
			if (w != null)
			{
				widgets.add(name(id) + " " + w.getBounds() + (w.isHidden() ? " hidden" : "") + " type " + w.getType() + " model " + w.getModelId()
					+ " sprite " + w.getSpriteId() + " text '" + w.getText() + "' ops " + (w.getActions() == null ? "[]" : String.join("/", nonNull(w.getActions()))));
			}
		}
		log.info("{} t{} opened, dials {}: {}", TAG, client.getTickCount(), dials(), widgets);
	}

	private String dials()
	{
		return client.getVarbitValue(DIAL_VARBITS[0]) + "" + client.getVarbitValue(DIAL_VARBITS[1]) + client.getVarbitValue(DIAL_VARBITS[2]);
	}

	private static String name(int id)
	{
		return (id >>> 16) + ":" + (id & 0xFFFF);
	}

	private static List<String> nonNull(String[] actions)
	{
		List<String> out = new ArrayList<>();
		for (String a : actions)
		{
			if (a != null && !a.isEmpty())
			{
				out.add(a);
			}
		}
		return out;
	}
}

package com.cluehelper;

import com.cluehelper.hotcold.HotColdPlan;
import com.cluehelper.hotcold.HotColdService;
import com.cluehelper.hotcold.Probe;
import com.cluehelper.hotcold.ProbeJob;
import com.cluehelper.hotcold.Reading;
import com.cluehelper.step.HotColdTier;
import com.google.gson.Gson;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;

/**
 * {@code [CH-HOTCOLD]} lines, and each plan with what it was planned from in {@link #DECISIONS}, which
 * {@code HotColdDecisionReplayTest} replays. Nothing while the bank PIN keypad is open.
 */
@Slf4j
final class HotColdTrace
{
	static final String TAG = "[CH-HOTCOLD]";
	static final File FRAMES = new File("build/hotcold");
	static final File DECISIONS = new File(FRAMES, "decisions.jsonl");

	private final Client client;
	private final Gson gson = new Gson();
	private final Consumer<String> saveFrames;
	private final Runnable unregister;
	private int planCount;

	/** @param saveFrames saves the game and the panel under the given name stem */
	HotColdTrace(Client client, HotColdService hotCold, Consumer<String> saveFrames)
	{
		this.client = client;
		this.saveFrames = saveFrames;
		FRAMES.mkdirs();
		Runnable untrace = hotCold.addTraceListener(this::line);
		Runnable unplan = hotCold.addPlanListener(this::record);
		unregister = () ->
		{
			untrace.run();
			unplan.run();
		};
	}

	void stop()
	{
		unregister.run();
	}

	private void line(String text)
	{
		if (!pinOpen())
		{
			log.info("{} t{} {}", TAG, client.getTickCount(), text);
		}
	}

	private void record(HotColdService.Planned planned)
	{
		if (pinOpen())
		{
			return;
		}
		ProbeJob job = planned.getJob();
		HotColdPlan plan = planned.getPlan();
		Decision decision = new Decision(job.getStepKey(), job.getTier() == HotColdTier.BEGINNER, job.getReadings(), plan.getConsidered(),
			job.getCosts().getWildernessPenaltyTicks(), plan.getAction().name(),
			plan.getTile() == null ? null : new int[]{plan.getTile().getX(), plan.getTile().getY(), plan.getTile().getPlane()});
		try (Writer out = new FileWriter(DECISIONS, StandardCharsets.UTF_8, true))
		{
			out.write(gson.toJson(decision) + "\n");
		}
		catch (IOException e)
		{
			log.warn("{} could not record a decision", TAG, e);
		}
		saveFrames.accept(String.format("%03d-%s", ++planCount, plan.getAction().name().toLowerCase()));
	}

	private boolean pinOpen()
	{
		return client.getWidget(InterfaceID.BANKPIN_KEYPAD, 0) != null;
	}

	/** One line of {@link #DECISIONS}. */
	static final class Decision
	{
		final String stepKey;
		final boolean beginner;
		final List<Reading> readings;
		final List<Probe> probes;
		final int wildernessPenaltyTicks;
		final String action;
		final int[] tile;

		Decision(String stepKey, boolean beginner, List<Reading> readings, List<Probe> probes, int wildernessPenaltyTicks, String action, int[] tile)
		{
			this.stepKey = stepKey;
			this.beginner = beginner;
			this.readings = readings;
			this.probes = probes;
			this.wildernessPenaltyTicks = wildernessPenaltyTicks;
			this.action = action;
			this.tile = tile;
		}
	}
}

package com.cluehelper;

import com.cluehelper.step.ClueTypes;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepResolver;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;

/**
 * Hands the Clue Scroll plugin a clue as if read: one at random, filtered by tier and type, or a list of step IDs walked
 * with next and previous. Core's own lists are the source, so a mocked clue is the object a real read gives.
 */
@Slf4j
final class MockClues
{
	static final String COMMAND = "ch-mock";
	static final String ANY = "any";
	static final List<String> TIERS = List.of(ANY, "beginner", "easy", "medium", "hard", "elite", "master");
	static final List<String> TYPES = List.of(ANY, ClueTypes.ANAGRAM, ClueTypes.CIPHER, ClueTypes.COORDINATE, ClueTypes.CRYPTIC,
		ClueTypes.EMOTE, ClueTypes.FAIRY_RING, ClueTypes.FALO, ClueTypes.MAP, ClueTypes.MUSIC, ClueTypes.SKILL);
	static final int RANDOM_LIST_LENGTH = 6;

	private static final String CLUES_PACKAGE = "net.runelite.client.plugins.cluescrolls.clues.";
	private static final List<String> LIST_TYPES = List.of("CrypticClue", "AnagramClue", "CipherClue", "CoordinateClue",
		"EmoteClue", "MapClue", "BeginnerMapClue", "FairyRingClue", "MusicClue", "FaloTheBardClue", "SkillChallengeClue");

	/** One core clue with what Clue Helper reads from it. */
	static final class Mock
	{
		final ClueScroll clue;
		final String key;
		final String type;
		final String tier;
		final String text;
		/** Null for a step without a tile. */
		final WorldPoint target;

		Mock(ClueScroll clue, Step step)
		{
			this.clue = clue;
			this.key = step.getKey();
			this.type = step.getType();
			this.tier = step.getTier();
			this.text = step.getText() == null ? step.getKey() : step.getText();
			this.target = step.getTargets().isEmpty() ? null : step.getTargets().get(0);
		}

		String describe()
		{
			return (tier == null ? "?" : tier) + " " + type + "\n" + key + "\n" + text;
		}
	}

	private final Client client;
	private final Supplier<ClueScrollPlugin> core;
	private final StepResolver resolver;
	private final Consumer<String> shown;
	private final Random random = new Random();
	private List<Mock> catalog;
	private List<String> listIds = List.of();
	private List<Mock> list = List.of();
	private int position = -1;

	private final Consumer<List<String>> listFilled;

	/**
	 * @param shown gets each mocked clue's description, or null once cleared
	 * @param listFilled gets the step IDs of a random list, for the list field
	 */
	MockClues(Client client, Supplier<ClueScrollPlugin> core, StepResolver resolver, Consumer<String> shown,
		Consumer<List<String>> listFilled)
	{
		this.client = client;
		this.core = core;
		this.resolver = resolver;
		this.shown = shown;
		this.listFilled = listFilled;
	}

	/** Client thread, from ::ch-mock [random [tier] [type] | next | prev | off | step ID]. */
	void run(String[] arguments)
	{
		String argument = arguments.length == 0 ? "" : arguments[0].toLowerCase(Locale.ROOT);
		switch (argument)
		{
			case "":
				say("::" + COMMAND + " random [tier] [type], next, prev, off, or a step ID");
				return;
			case "random":
				random(arguments.length > 1 ? arguments[1] : ANY, arguments.length > 2 ? arguments[2] : ANY);
				return;
			case "next":
				walk(listIds, 1);
				return;
			case "prev":
				walk(listIds, -1);
				return;
			case "off":
				clear();
				return;
			default:
				walk(List.of(String.join(" ", arguments)), 1);
		}
	}

	/** Client thread. A single clue; the list keeps its place. */
	void random(String tier, String type)
	{
		List<Mock> pool = pool(tier, type);
		if (pool.isEmpty())
		{
			say("No " + tier + " " + type + " clue to mock");
			return;
		}
		show(pool.get(random.nextInt(pool.size())), "");
	}

	/** Client thread. Fills the list with random step IDs and starts it. */
	void randomList(String tier, String type)
	{
		List<Mock> pool = new ArrayList<>(pool(tier, type));
		if (pool.isEmpty())
		{
			say("No " + tier + " " + type + " clue to mock");
			return;
		}
		Collections.shuffle(pool, random);
		List<String> ids = pool.subList(0, Math.min(RANDOM_LIST_LENGTH, pool.size())).stream().map(mock -> mock.key)
			.collect(Collectors.toList());
		listFilled.accept(ids);
		walk(ids, 1);
	}

	/**
	 * Client thread. Steps through {@code ids}, one step ID per entry: from its first (or last, going back) when it differs
	 * from the list walked so far. An ID that matches no step whole is looked for as a piece of a step ID or text.
	 */
	void walk(List<String> ids, int by)
	{
		List<String> wanted = ids.stream().map(String::trim).filter(id -> !id.isEmpty()).collect(Collectors.toList());
		if (wanted.isEmpty())
		{
			say("No step IDs in the list");
			return;
		}
		if (!wanted.equals(listIds))
		{
			listIds = List.copyOf(wanted);
			list = resolve(wanted);
			position = by > 0 ? -1 : list.size();
		}
		if (list.isEmpty())
		{
			return;
		}
		position = Math.floorMod(position + by, list.size());
		show(list.get(position), (position + 1) + " / " + list.size());
	}

	/** Client thread. Every clue core's lists hold. */
	List<Mock> all()
	{
		return catalog();
	}

	/** Client thread. One clue, outside the list. */
	void mock(Mock mock, String where)
	{
		show(mock, where);
	}

	/** Client thread. */
	void clear()
	{
		invoke("resetClue", boolean.class, true);
		position = listIds.isEmpty() ? -1 : position;
		shown.accept(null);
		say("Mock clue cleared");
	}

	private List<Mock> resolve(List<String> ids)
	{
		List<Mock> found = new ArrayList<>();
		for (String id : ids)
		{
			Mock mock = find(id);
			if (mock == null)
			{
				say("No step matches " + id);
			}
			else
			{
				found.add(mock);
			}
		}
		return List.copyOf(found);
	}

	private void show(Mock mock, String where)
	{
		invoke("updateClue", ClueScroll.class, mock.clue);
		say("Mock clue " + (where.isEmpty() ? "" : where + " ") + mock.key);
		log.info("[CH-MOCK] {} {} {}", mock.key, mock.tier, where);
		shown.accept((where.isEmpty() ? "" : where + "  ") + mock.describe());
	}

	private List<Mock> pool(String tier, String type)
	{
		return catalog().stream()
			.filter(mock -> ANY.equalsIgnoreCase(tier) || tier.equalsIgnoreCase(mock.tier))
			.filter(mock -> ANY.equalsIgnoreCase(type) || type.equalsIgnoreCase(mock.type))
			.collect(Collectors.toList());
	}

	private Mock find(String id)
	{
		String lower = id.toLowerCase(Locale.ROOT);
		Mock whole = catalog().stream().filter(mock -> mock.key.equalsIgnoreCase(id)).findFirst().orElse(null);
		return whole != null ? whole : catalog().stream()
			.filter(mock -> mock.key.toLowerCase(Locale.ROOT).contains(lower) || mock.text.toLowerCase(Locale.ROOT).contains(lower))
			.findFirst().orElse(null);
	}

	/** Built on first use: resolving reads core's providers, which need the client thread. */
	private List<Mock> catalog()
	{
		if (catalog == null)
		{
			List<Mock> mocks = new ArrayList<>();
			for (String type : LIST_TYPES)
			{
				for (Object entry : coreList(type))
				{
					Step step = resolver.resolve((ClueScroll) entry, core.get());
					if (step != null && step.getKey() != null && !step.getKey().startsWith("unreadable"))
					{
						mocks.add(new Mock((ClueScroll) entry, step));
					}
				}
			}
			catalog = List.copyOf(mocks);
			log.info("[CH-MOCK] {} clues to mock", catalog.size());
		}
		return catalog;
	}

	private static Collection<?> coreList(String type)
	{
		try
		{
			Field field = Class.forName(CLUES_PACKAGE + type).getDeclaredField("CLUES");
			field.setAccessible(true);
			Object clues = field.get(null);
			return clues instanceof Map ? ((Map<?, ?>) clues).values() : (Collection<?>) clues;
		}
		catch (ReflectiveOperationException e)
		{
			log.warn("[CH-MOCK] can't read core's {} list", type, e);
			return List.of();
		}
	}

	private void invoke(String method, Class<?> parameter, Object argument)
	{
		try
		{
			Method m = ClueScrollPlugin.class.getDeclaredMethod(method, parameter);
			m.setAccessible(true);
			m.invoke(core.get(), argument);
		}
		catch (ReflectiveOperationException e)
		{
			log.warn("[CH-MOCK] core's {} failed", method, e);
		}
	}

	private void say(String text)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", text, null);
	}
}

package com.cluehelper;

import com.cluehelper.memory.FairyRingMemory;
import com.cluehelper.memory.SpiritTreeMemory;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
final class NetworkTrace
{
	static final String TREE_TAG = "[CH-TREE]";
	static final String RING_TAG = "[CH-RING]";
	static final String TIME_TAG = "[CH-TIME]";
	static final String QUETZAL_TAG = "[CH-QUETZAL]";
	static final String BOAT_TAG = "[CH-BOAT]";
	private static final int[][] BOAT_SLOTS = {
		{VarbitID.SAILING_BOAT_1_OWNED, VarbitID.SAILING_BOAT_1_PORT, VarbitID.SAILING_BOAT_1_TELEPORT_FOCUS},
		{VarbitID.SAILING_BOAT_2_OWNED, VarbitID.SAILING_BOAT_2_PORT, VarbitID.SAILING_BOAT_2_TELEPORT_FOCUS},
		{VarbitID.SAILING_BOAT_3_OWNED, VarbitID.SAILING_BOAT_3_PORT, VarbitID.SAILING_BOAT_3_TELEPORT_FOCUS},
		{VarbitID.SAILING_BOAT_4_OWNED, VarbitID.SAILING_BOAT_4_PORT, VarbitID.SAILING_BOAT_4_TELEPORT_FOCUS},
		{VarbitID.SAILING_BOAT_5_OWNED, VarbitID.SAILING_BOAT_5_PORT, VarbitID.SAILING_BOAT_5_TELEPORT_FOCUS}};
	private static final int WATCH_TICKS = 30;
	private static final int QUETZAL_MENU = InterfaceID.QuetzalMenu.ICONS >>> 16;
	private static final int WHISTLE_MENU = InterfaceID.QuetzalwhistleMenu.ICONS >>> 16;

	private final Client client;
	private final Consumer<File> saveFrame;
	private final Runnable unregister;
	private int watching;
	private WorldPoint lastTile;
	private int lastAnimation = -2;
	private int pendingQuetzal = -1;
	private String lastBoats;

	NetworkTrace(Client client, SpiritTreeMemory trees, FairyRingMemory rings, Consumer<File> saveFrame)
	{
		this.client = client;
		this.saveFrame = saveFrame;
		Runnable untrees = trees.addListener(line -> log.info("{} t{} {}", TREE_TAG, client.getTickCount(), line));
		Runnable unrings = rings.addListener(line -> log.info("{} t{} {}", RING_TAG, client.getTickCount(), line));
		unregister = () ->
		{
			untrees.run();
			unrings.run();
		};
	}

	void stop()
	{
		unregister.run();
	}

	@Subscribe(priority = -3)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (keypadOpen())
		{
			return;
		}
		log.info("{} t{} click {}|{}|{}|{} at {}", TIME_TAG, client.getTickCount(), event.getMenuOption(), event.getMenuTarget(),
			event.getMenuAction(), event.getId(), text(tile()));
		watching = WATCH_TICKS;
	}

	@Subscribe(priority = -3)
	public void onGameTick(GameTick tick)
	{
		if (pendingQuetzal >= 0)
		{
			dumpQuetzalIcons(pendingQuetzal);
			pendingQuetzal = -1;
		}
		if (!keypadOpen())
		{
			logBoats();
		}
		if (watching <= 0 || keypadOpen())
		{
			return;
		}
		watching--;
		WorldPoint tile = tile();
		Player local = client.getLocalPlayer();
		int animation = local == null ? -1 : local.getAnimation();
		if (tile != null && !tile.equals(lastTile) || animation != lastAnimation)
		{
			log.info("{} t{} at {} anim {}", TIME_TAG, client.getTickCount(), text(tile), animation);
		}
		lastTile = tile;
		lastAnimation = animation;
	}

	@Subscribe(priority = -3)
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == QUETZAL_MENU || event.getGroupId() == WHISTLE_MENU)
		{
			pendingQuetzal = event.getGroupId();
		}
	}

	/** Each boat slot's owned, port (SailingDock id) and teleport focus varbits, whenever one changes. */
	private void logBoats()
	{
		List<String> slots = new ArrayList<>();
		for (int i = 0; i < BOAT_SLOTS.length; i++)
		{
			int[] vars = BOAT_SLOTS[i];
			slots.add((i + 1) + ": owned " + client.getVarbitValue(vars[0]) + " port " + client.getVarbitValue(vars[1])
				+ " focus " + client.getVarbitValue(vars[2]));
		}
		String boats = String.join("; ", slots);
		if (!boats.equals(lastBoats) && client.getLocalPlayer() != null)
		{
			log.info("{} t{} {}", BOAT_TAG, client.getTickCount(), boats);
			lastBoats = boats;
		}
	}

	private void dumpQuetzalIcons(int group)
	{
		Widget icons = client.getWidget(group == QUETZAL_MENU ? InterfaceID.QuetzalMenu.ICONS : InterfaceID.QuetzalwhistleMenu.ICONS);
		List<String> children = new ArrayList<>();
		Widget[] dynamic = icons == null ? null : icons.getDynamicChildren();
		for (int i = 0; dynamic != null && i < dynamic.length; i++)
		{
			Widget c = dynamic[i];
			children.add(i + ":" + c.getOriginalX() + "," + c.getOriginalY() + " " + c.getWidth() + "x" + c.getHeight()
				+ (c.isHidden() ? " hidden" : "") + " sprite " + c.getSpriteId() + " model " + c.getModelId() + " name '" + c.getName()
				+ "' ops " + (c.getActions() == null ? "[]" : String.join("/", nonNull(c.getActions()))));
		}
		log.info("{} t{} interface {} icons {} children {}", QUETZAL_TAG, client.getTickCount(), group,
			icons == null ? "none" : icons.getBounds(), children);
		List<String> sites = new ArrayList<>();
		for (int row : client.getDBTableRows(DBTableID.Quetzal.ID))
		{
			sites.add(client.getDBTableField(row, DBTableID.Quetzal.COL_ID, 0)[0] + " " + client.getDBTableField(row, DBTableID.Quetzal.COL_NAME, 0)[0]
				+ " @" + client.getDBTableField(row, DBTableID.Quetzal.COL_IF_X_POS, 0)[0] + "," + client.getDBTableField(row, DBTableID.Quetzal.COL_IF_Y_POS, 0)[0]);
		}
		log.info("{} t{} cache sites {}", QUETZAL_TAG, client.getTickCount(), sites);
		saveFrame.accept(new File(PohTrace.FRAMES, "quetzal-" + group + "-t" + client.getTickCount() + ".png"));
	}

	private static List<String> nonNull(String[] actions)
	{
		List<String> out = new ArrayList<>();
		for (String a : actions)
		{
			if (a != null && !a.isEmpty())
			{
				out.add(a);
			}
		}
		return out;
	}

	private WorldPoint tile()
	{
		Player local = client.getLocalPlayer();
		return local == null ? null : WorldPoint.fromLocalInstance(client, local.getLocalLocation());
	}

	private boolean keypadOpen()
	{
		return client.getWidget(InterfaceID.BANKPIN_KEYPAD, 0) != null;
	}

	private static String text(WorldPoint tile)
	{
		return tile == null ? "?" : tile.getX() + " " + tile.getY() + " " + tile.getPlane();
	}
}

