import com.google.gson.Gson;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/**
 * Plans each {@link PlanTrace} recording again, warm and as the live planner does, and prints its time and labels beside
 * the live ones:
 * {@code gradlew planReplay [-Pplans=<folder>]}.
 */
public final class PlanReplay
{
	private static final int WARM_UP = 2;
	private static final int TIMED = 3;
	private static final long NANOS_PER_MILLI = 1_000_000;

	private PlanReplay()
	{
	}

	public static void main(String[] args) throws IOException
	{
		File folder = new File(args.length > 0 ? args[0] : PlanTrace.PLANS.getPath());
		File[] files = folder.listFiles((dir, name) -> name.endsWith(".json"));
		if (files == null || files.length == 0)
		{
			System.out.println("No recordings in " + folder);
			return;
		}
		Arrays.sort(files);
		WalkTable table = WalkTable.load();
		WorldMap map = WorldMap.load();
		Catalog catalog = CatalogLoader.load();
		NoTeleportAreas noTeleport = NoTeleportAreas.load();
		Map<String, Step> steps = DriftSteps.read();
		AvailabilityEngine engine = new AvailabilityEngine(Loadouts.runeModel(), id -> "item " + id);
		Gson gson = new Gson();
		for (File file : files)
		{
			PlanTrace.Recording recording;
			try (Reader in = new FileReader(file, StandardCharsets.UTF_8))
			{
				recording = gson.fromJson(in, PlanTrace.Recording.class);
			}
			PlanInput input = PlanInput.builder()
				.step(steps.getOrDefault(recording.stepKey, stepOf(recording)))
				.player(recording.player)
				.banked(recording.banked)
				.pinPending(recording.pinPending)
				.atOpenBank(recording.atOpenBank)
				.required(required(recording))
				.engine(engine)
				.nowMinutes(recording.nowMinutes)
				.catalog(catalog)
				.table(table)
				.noTeleport(noTeleport)
				.start(start(recording, folder, table, map, engine))
				.settings(recording.settings)
				.revertTicksLeft(recording.revertTicksLeft)
				.refusedChanges(recording.refusedChanges)
				.foreignHouseStart(recording.foreignHouseStart)
				.followedFirstTransport(recording.followedFirstTransport)
				.build();
			report(file.getName(), recording, input);
		}
	}

	private static void report(String name, PlanTrace.Recording recording, PlanInput input)
	{
		Plan plan = null;
		for (int i = 0; i < WARM_UP; i++)
		{
			plan = Planner.withoutAlternatives(input);
		}
		long best = Long.MAX_VALUE;
		for (int i = 0; i < TIMED; i++)
		{
			long started = System.nanoTime();
			plan = Planner.withoutAlternatives(input);
			best = Math.min(best, System.nanoTime() - started);
		}
		System.out.printf("%s: live %d ms %d labels | replay %d ms %d labels, %d searches | %s%n", name, recording.liveMillis,
			recording.liveLabels, best / NANOS_PER_MILLI, plan.getLabels(), plan.getSearches(),
			plan.getBest() == null ? "no route" : plan.getBest().describe());
	}

	/** A three-step or other key the step data lacks: its targets are enough to plan. */
	private static Step stepOf(PlanTrace.Recording recording)
	{
		List<WorldPoint> targets = recording.targets.stream().map(PlanReplay::point).collect(Collectors.toList());
		List<Stage> stages = recording.stages == null ? List.of() : recording.stages.stream().map(PlanReplay::stage).collect(Collectors.toList());
		return Step.builder().key(recording.stepKey).type(recording.stepType).tier(recording.tier).kind(TargetKind.valueOf(recording.kind))
			.targets(targets).stages(stages).regions(List.of()).build();
	}

	private static Stage stage(PlanTrace.RecordedStage recorded)
	{
		return Stage.builder().kind(Stage.Kind.valueOf(recorded.kind)).act(recorded.act)
			.tiles(recorded.tiles.stream().map(PlanReplay::point).collect(Collectors.toList())).worn(recorded.worn).build();
	}

	private static RequiredItems required(PlanTrace.Recording recording)
	{
		List<RequiredItems.Need> needs = recording.needs.stream()
			.map(need -> new RequiredItems.Need(need.name, requirement(need), need.stepItem, need.inCoreTag, need.blocksRoute))
			.collect(Collectors.toList());
		return RequiredItems.builder().needs(needs).stash(StashMemory.State.valueOf(recording.stash)).build();
	}

	private static ItemRequirement requirement(PlanTrace.RecordedNeed need)
	{
		if (need.gearPieces == null)
		{
			return new AnyOf(Set.copyOf(need.ids));
		}
		Map<Integer, GearPicker.Piece> pieces = need.gearPieces.stream().collect(Collectors.toMap(GearPicker.Piece::getItemId, piece -> piece));
		return new GearRequirement(need.name, need.gearAtLeast, pieces);
	}

	private static PlanStart start(PlanTrace.Recording recording, File folder, WalkTable table, WorldMap map, AvailabilityEngine engine)
		throws IOException
	{
		WorldPoint tile = point(recording.startTile);
		boolean[] rowOpen = new WalkGates(table, recording.player, engine, recording.nowMinutes).rowOpen();
		LoadedScene scene = recording.sceneFile == null ? null : scene(new File(folder, recording.sceneFile));
		WalkCosts walk = WalkCosts.from(Ground.world(map, scene, table, row -> rowOpen[row]), tile);
		switch (PlanStart.Kind.valueOf(recording.startKind))
		{
			case SCENE:
				return PlanStart.scene(tile, walk);
			case AT_NODE:
				return PlanStart.atNode(table, table.node(tile));
			default:
				return PlanStart.teleportOnly(tile, walk);
		}
	}

	private static LoadedScene scene(File file) throws IOException
	{
		try (InputStream in = new FileInputStream(file))
		{
			return SceneFiles.read(in).getScene();
		}
	}

	private static WorldPoint point(int[] xyz)
	{
		return new WorldPoint(xyz[0], xyz[1], xyz[2]);
	}

	/** A recorded need: any one of the owned items that counted for it. */
	private static final class AnyOf implements ItemRequirement
	{
		private final Set<Integer> ids;

		AnyOf(Set<Integer> ids)
		{
			this.ids = ids;
		}

		@Override
		public boolean fulfilledBy(int itemId)
		{
			return ids.contains(itemId);
		}

		@Override
		public boolean fulfilledBy(Item[] items)
		{
			return Arrays.stream(items).anyMatch(item -> ids.contains(item.getId()));
		}

		@Override
		public String getCollectiveName(Client client)
		{
			return "recorded need";
		}
	}
}

package com.cluehelper;

import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.GearPicker;
import com.cluehelper.route.GearRequirement;
import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanInput;
import com.cluehelper.route.PlanStart;
import com.cluehelper.route.PlannerSettings;
import com.cluehelper.route.RequiredItems;
import com.cluehelper.route.RoutePlanner;
import com.cluehelper.route.SceneFiles;
import com.cluehelper.route.WalkCosts;
import com.cluehelper.step.Stage;
import com.cluehelper.step.Step;
import com.google.gson.Gson;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;

/**
 * Each plan slower than {@link #SLOW_MILLIS}, with what it was planned from, as a {@link Recording} in {@link #PLANS}
 * (its scene beside it), which {@code PlanReplay} plans again offline. Nothing while the bank PIN keypad is open.
 */
@Slf4j
final class PlanTrace
{
	static final String TAG = "[CH-PLANREC]";
	static final File PLANS = new File("build/plans");
	private static final long SLOW_MILLIS = 300;
	private static final long NANOS_PER_MILLI = 1_000_000;
	private static final int MOST_RECORDINGS = 40;

	private final Client client;
	private final Gson gson = new Gson();
	private final Runnable unregister;
	private int recorded;

	PlanTrace(Client client, RoutePlanner routes)
	{
		this.client = client;
		PLANS.mkdirs();
		unregister = routes.addInputListener(this::record);
	}

	void stop()
	{
		unregister.run();
	}

	private void record(Plan plan, PlanInput input)
	{
		long millis = plan.getSearchNanos() / NANOS_PER_MILLI;
		if (millis < SLOW_MILLIS || recorded >= MOST_RECORDINGS || pinOpen() || input.getStep() == null)
		{
			return;
		}
		String name = String.format("%03d-%s", ++recorded, slug(input.getStep().getKey()));
		Recording recording = recording(plan, input, millis);
		WalkCosts walk = input.getStart().getWalk();
		if (walk != null && walk.getScene() != null)
		{
			recording.sceneFile = name + ".scene.gz";
			SceneFiles.write(new File(PLANS, recording.sceneFile), walk.getScene(), input.getStart().getTile());
		}
		try (Writer out = new FileWriter(new File(PLANS, name + ".json"), StandardCharsets.UTF_8))
		{
			out.write(gson.toJson(recording));
			log.info("{} {} took {} ms, {} labels: recorded", TAG, name, millis, plan.getLabels());
		}
		catch (IOException e)
		{
			log.warn("{} could not record {}", TAG, name, e);
		}
	}

	private static Recording recording(Plan plan, PlanInput input, long millis)
	{
		Step step = input.getStep();
		Recording r = new Recording();
		r.stepKey = step.getKey();
		r.stepType = step.getType();
		r.tier = step.getTier();
		r.kind = step.getKind().name();
		r.targets = step.getTargets().stream().map(PlanTrace::xyz).collect(Collectors.toList());
		r.stages = step.getStages().stream().map(PlanTrace::stage).collect(Collectors.toList());
		r.player = input.getPlayer();
		r.banked = input.getBanked();
		r.pinPending = input.isPinPending();
		r.atOpenBank = input.isAtOpenBank();
		r.nowMinutes = input.getNowMinutes();
		r.startKind = input.getStart().getKind().name();
		r.startTile = xyz(input.getStart().getTile());
		r.settings = input.getSettings();
		r.revertTicksLeft = input.getRevertTicksLeft();
		r.refusedChanges = input.getRefusedChanges();
		r.foreignHouseStart = input.isForeignHouseStart();
		r.followedFirstTransport = input.getFollowedFirstTransport();
		r.stash = input.getRequired().getStash().name();
		r.needs = needs(input);
		r.liveMillis = millis;
		r.liveLabels = plan.getLabels();
		return r;
	}

	/** A need as the owned items that count for it: its "all of" sets are kept as "any of". */
	private static List<RecordedNeed> needs(PlanInput input)
	{
		Set<Integer> owned = new HashSet<>(input.getPlayer().getInventory().keySet());
		owned.addAll(input.getPlayer().getWorn().keySet());
		PlayerSnapshot banked = input.getBanked();
		if (banked != null)
		{
			owned.addAll(banked.getBank().keySet());
			owned.addAll(banked.getGroupStorage().keySet());
		}
		List<RecordedNeed> needs = new ArrayList<>();
		for (RequiredItems.Need need : input.getRequired().getNeeds())
		{
			RecordedNeed recorded = new RecordedNeed();
			recorded.name = need.getName();
			recorded.stepItem = need.isStepItem();
			recorded.inCoreTag = need.isInCoreTag();
			recorded.blocksRoute = need.isBlocksRoute();
			recorded.ids = owned.stream().filter(need.getRequirement()::fulfilledBy).sorted().collect(Collectors.toList());
			if (need.getRequirement() instanceof GearRequirement)
			{
				GearRequirement gear = (GearRequirement) need.getRequirement();
				recorded.gearAtLeast = gear.getAtLeast();
				recorded.gearPieces = List.copyOf(gear.getPieces().values());
			}
			needs.add(recorded);
		}
		return needs;
	}

	private static RecordedStage stage(Stage stage)
	{
		RecordedStage recorded = new RecordedStage();
		recorded.kind = stage.getKind().name();
		recorded.act = stage.getAct();
		recorded.tiles = stage.getTiles().stream().map(PlanTrace::xyz).collect(Collectors.toList());
		recorded.worn = stage.getWorn();
		return recorded;
	}

	private static int[] xyz(WorldPoint tile)
	{
		return tile == null ? null : new int[]{tile.getX(), tile.getY(), tile.getPlane()};
	}

	private static String slug(String key)
	{
		String slug = key.toLowerCase().replaceAll("[^a-z0-9]+", "-");
		return slug.substring(0, Math.min(40, slug.length()));
	}

	private boolean pinOpen()
	{
		return client.getWidget(InterfaceID.BANKPIN_KEYPAD, 0) != null;
	}

	/** One recorded plan; {@code PlanReplay} reads it back. */
	static final class Recording
	{
		String stepKey;
		String stepType;
		String tier;
		String kind;
		List<int[]> targets;
		List<RecordedStage> stages;
		PlayerSnapshot player;
		PlayerSnapshot banked;
		boolean pinPending;
		boolean atOpenBank;
		long nowMinutes;
		String startKind;
		int[] startTile;
		String sceneFile;
		PlannerSettings settings;
		int revertTicksLeft;
		Set<String> refusedChanges;
		boolean foreignHouseStart;
		String followedFirstTransport;
		String stash;
		List<RecordedNeed> needs;
		long liveMillis;
		int liveLabels;
	}

	static final class RecordedStage
	{
		String kind;
		String act;
		List<int[]> tiles;
		List<String> worn;
	}

	static final class RecordedNeed
	{
		String name;
		boolean stepItem;
		boolean inCoreTag;
		boolean blocksRoute;
		List<Integer> ids;
		/** Gear needs only: the bonus total and each owned piece. */
		int gearAtLeast;
		List<GearPicker.Piece> gearPieces;
	}
}

package com.cluehelper;

import com.cluehelper.guide.MenuLines;
import com.cluehelper.guide.MenuTarget;
import com.cluehelper.guide.StepGuide;
import com.cluehelper.guide.SubStep;
import com.cluehelper.poh.PohService;
import java.awt.Rectangle;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
final class PohTrace
{
	static final String POH_TAG = "[CH-POH]";
	static final String MENU_TAG = "[CH-MENU]";
	static final File FRAMES = new File("build/poh-menus");
	private static final Set<Integer> TELEPORT_INTERFACES = Set.of(17, 187, 219, 590, InterfaceID.Fairyrings.ROOT_RECT0 >>> 16,
		InterfaceID.FairyringsLog.UNIVERSE >>> 16, InterfaceID.QuetzalMenu.ICONS >>> 16, InterfaceID.QuetzalwhistleMenu.ICONS >>> 16);
	private static final int MOST_FRAMES = 200;
	private static final int NEXUS_GROUP = 17;
	/** Interfaces the client reloads with every new scene: not a teleport's chooser. */
	private static final Set<Integer> RELOADED_ON_LANDING = Set.of(71, 109, 116, 182, 203, 216, 218, 239, 320, 387, 429, 541, 629, 712);

	private final Client client;
	private final StepGuide guide;
	private final MenuLines lines;
	private final Consumer<File> saveFrame;
	private final Runnable unregister;
	private int pendingInterface = -1;
	private static final int TREE_CHILDREN = 80;
	private int frames;
	private String lastTarget;

	PohTrace(Client client, PohService poh, StepGuide guide, MenuLines lines, Consumer<File> saveFrame)
	{
		this.client = client;
		this.guide = guide;
		this.lines = lines;
		this.saveFrame = saveFrame;
		FRAMES.mkdirs();
		unregister = poh.addListener(line ->
		{
			log.info("{} t{} {}", POH_TAG, client.getTickCount(), line);
			if (line.startsWith("scan") || line.startsWith("entered"))
			{
				frame("house");
			}
		});
	}

	void stop()
	{
		unregister.run();
	}

	@Subscribe(priority = -3)
	public void onGameTick(GameTick tick)
	{
		MenuTarget target = guide.getMenuTarget();
		String now = target == null || target.isEmpty() ? null : describe(target);
		if (now != null && !now.equals(lastTarget))
		{
			log.info("{} t{} target {}", MENU_TAG, client.getTickCount(), now);
		}
		lastTarget = now;
		if (pendingInterface >= 0)
		{
			log.info("{} t{} interface {} lines {}", MENU_TAG, client.getTickCount(), pendingInterface,
				rects(lines.lines(target)));
			if (pendingInterface == InterfaceID.MINIGAMES)
			{
				logMinigameCards();
			}
			if (pendingInterface == InterfaceID.BOOKOFSCROLLS && guide.getHighlightMenuWidget() >= 0)
			{
				logScrollEntry(guide.getHighlightMenuWidget());
			}
			if (pendingInterface == NEXUS_GROUP)
			{
				logLayer("rows", InterfaceID.TelenexusTeleport.ROWS1);
				logLayer("text", InterfaceID.TelenexusTeleport.TEXT1);
			}
			if (pendingInterface == InterfaceID.SAILING_MENU || pendingInterface == InterfaceID.CHARTERING_MENU_SIDE)
			{
				logTree(InterfaceID.SAILING_MENU);
				logTree(InterfaceID.CHARTERING_MENU_SIDE);
			}
			frame("interface-" + pendingInterface);
			pendingInterface = -1;
		}
	}

	/** Runs before the plugin (priority 2) and better-teleport-menu (1), so the arguments are logged as they arrive. */
	@Subscribe(priority = 3)
	public void onScriptPreFired(ScriptPreFired event)
	{
		int id = event.getScriptId();
		if (id != 218 && id != 219 && id != 9142 && id != 9143 && id != 217)
		{
			return;
		}
		int ints = client.getIntStackSize();
		List<Integer> tail = new ArrayList<>();
		for (int i = Math.max(0, ints - 8); i < ints; i++)
		{
			tail.add(client.getIntStack()[i]);
		}
		int objects = client.getObjectStackSize();
		List<String> strings = new ArrayList<>();
		for (int i = Math.max(0, objects - 3); i < objects; i++)
		{
			strings.add(String.valueOf(client.getObjectStack()[i]));
		}
		log.info("{} t{} script {} ints {} objects {}", MENU_TAG, client.getTickCount(), id, tail, strings);
	}

	@Subscribe(priority = -3)
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (TELEPORT_INTERFACES.contains(event.getGroupId()) && !guide.getMenuTarget().isEmpty() && !keypadOpen())
		{
			pendingInterface = event.getGroupId();
		}
		else if (guide.getCurrent() != null && guide.getCurrent().isTravel() && !RELOADED_ON_LANDING.contains(event.getGroupId()) && !keypadOpen())
		{
			log.info("{} t{} interface {} loaded during '{}'", MENU_TAG, client.getTickCount(), event.getGroupId(), guide.getCurrent().getText());
			pendingInterface = event.getGroupId();
		}
	}

	@Subscribe(priority = -3)
	public void onMenuOpened(MenuOpened event)
	{
		MenuTarget target = guide.getMenuTarget();
		if (target.isEmpty() || keypadOpen())
		{
			return;
		}
		List<String> entries = new ArrayList<>();
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			Menu sub = entry.getSubMenu();
			StringBuilder text = new StringBuilder(entry.getOption()).append('|').append(entry.getTarget()).append('|')
				.append(entry.getType()).append('|').append(entry.getIdentifier()).append('|').append(entry.getItemId());
			if (sub != null)
			{
				text.append(" sub[");
				for (MenuEntry option : sub.getMenuEntries())
				{
					text.append(option.getOption()).append(';');
				}
				text.append(']');
			}
			entries.add(text.toString());
		}
		Menu menu = client.getMenu();
		log.info("{} t{} menu at {},{} {}x{} entries {}", MENU_TAG, client.getTickCount(), menu.getMenuX(), menu.getMenuY(),
			menu.getMenuWidth(), menu.getMenuHeight(), entries);
		frame("menu");
	}

	@Subscribe(priority = -3)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		SubStep current = guide.getCurrent();
		if (current == null || keypadOpen() || guide.getMenuTarget().isEmpty())
		{
			return;
		}
		int widget = event.getParam1();
		log.info("{} t{} click {}|{}|{}|{} widget {}:{}[{}] during {} '{}'", MENU_TAG, client.getTickCount(), event.getMenuOption(),
			event.getMenuTarget(), event.getMenuAction(), event.getId(), widget >>> 16, widget & 0xFFFF, event.getParam0(),
			current.getKind(), current.getText());
	}

	private void logScrollEntry(int entry)
	{
		List<String> parts = new ArrayList<>();
		for (int id = entry; id <= entry + 3; id++)
		{
			Widget w = client.getWidget(id);
			parts.add((id & 0xFFFF) + (w == null ? " null" : " type " + w.getType() + " item " + w.getItemId() + " sprite " + w.getSpriteId()
				+ " model " + w.getModelId() + " text '" + w.getText() + "' " + w.getBounds()));
		}
		log.info("{} t{} scroll entry {}", MENU_TAG, client.getTickCount(), parts);
	}

	private void logMinigameCards()
	{
		List<String> cards = new ArrayList<>();
		for (int card = InterfaceID.Minigames.MINIGAME_21; card <= InterfaceID.Minigames.MINIGAME_1; card++)
		{
			Widget widget = client.getWidget(card);
			List<String> texts = new ArrayList<>();
			collectTexts(widget, texts);
			cards.add((card & 0xFFFF) + (widget == null ? " null" : widget.isHidden() ? " hidden" : "") + " " + texts);
		}
		log.info("{} t{} minigame cards {}", MENU_TAG, client.getTickCount(), cards);
	}

	private static void collectTexts(Widget widget, List<String> out)
	{
		if (widget == null)
		{
			return;
		}
		if (widget.getText() != null && !widget.getText().isBlank())
		{
			out.add(widget.getText());
		}
		for (Widget[] children : new Widget[][]{widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			for (int i = 0; children != null && i < children.length; i++)
			{
				collectTexts(children[i], out);
			}
		}
	}

	private void logLayer(String name, int component)
	{
		Widget layer = client.getWidget(component);
		Widget[] children = layer == null ? null : layer.getDynamicChildren();
		List<String> lines = new ArrayList<>();
		for (int i = 0; children != null && i < Math.min(4, children.length); i++)
		{
			Widget c = children[i];
			lines.add(i + ": y " + c.getRelativeY() + " h " + c.getHeight() + " text '" + c.getText() + "' colour " + Integer.toHexString(c.getTextColor()));
		}
		log.info("{} t{} nexus {} layer: {} children {}", MENU_TAG, client.getTickCount(), name, children == null ? 0 : children.length, lines);
	}

	/** Every widget of an interface we don't read yet, to learn where its lines and map markers are. */
	private void logTree(int group)
	{
		for (int child = 0; child < TREE_CHILDREN; child++)
		{
			Widget widget = client.getWidget(group, child);
			if (widget != null)
			{
				logWidget(group + ":" + child, widget);
			}
		}
	}

	private void logWidget(String path, Widget widget)
	{
		log.info("{} tree {} type {} hidden {} text '{}' name '{}' actions {} sprite {} item {} bounds {}", MENU_TAG, path,
			widget.getType(), widget.isHidden(), widget.getText(), widget.getName(),
			widget.getActions() == null ? "[]" : java.util.Arrays.toString(widget.getActions()), widget.getSpriteId(),
			widget.getItemId(), widget.getBounds());
		Widget[] dynamic = widget.getDynamicChildren();
		for (int i = 0; dynamic != null && i < Math.min(dynamic.length, TREE_CHILDREN); i++)
		{
			if (dynamic[i] != null)
			{
				logWidget(path + "[" + i + "]", dynamic[i]);
			}
		}
	}

	private String describe(MenuTarget target)
	{
		return target.getLine() + " id=" + target.getLineId() + " key=" + target.getLineKey() + " name=" + target.getLineName()
			+ " path=" + target.getPath() + " items=" + target.getItemIds() + " objects=" + target.getObjectIds()
			+ " found=" + guide.getHighlightObjects().size() + " filled=" + guide.getFillItems() + "/" + guide.getFillObjects().size();
	}

	private boolean keypadOpen()
	{
		return client.getWidget(InterfaceID.BANKPIN_KEYPAD, 0) != null;
	}

	private void frame(String what)
	{
		if (frames < MOST_FRAMES && !keypadOpen())
		{
			saveFrame.accept(new File(FRAMES, String.format("%03d-t%d-%s.png", ++frames, client.getTickCount(), what)));
		}
	}

	private static String rects(List<Rectangle> rects)
	{
		List<String> out = new ArrayList<>();
		rects.forEach(r -> out.add(r.x + "," + r.y + " " + r.width + "x" + r.height));
		return out.toString();
	}
}

package com.cluehelper;

import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.DriftSteps;
import com.cluehelper.route.Ground;
import com.cluehelper.route.LoadedScene;
import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanInput;
import com.cluehelper.route.PlanStart;
import com.cluehelper.route.Planner;
import com.cluehelper.route.PlannerSettings;
import com.cluehelper.route.Route;
import com.cluehelper.route.WalkCosts;
import com.cluehelper.route.WalkData;
import com.cluehelper.route.WalkGates;
import com.cluehelper.step.Step;
import com.cluehelper.transport.AvailabilityEngine;
import com.cluehelper.transport.AvailabilityService;
import com.cluehelper.transport.Catalog;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

@Slf4j
final class RouteSampler
{
	static final String TAG = "[CH-SAMPLE]";
	private static final List<String> STEPS = List.of(
		"cryptic:search the crates in a bank in varrock.",
		"cryptic:you will need to under-cook to solve this one.",
		"map:w348",
		"emote:12021",
		"coordinate:2840,3423,0",
		"anagram:12566",
		"cipher:19762",
		"coordinate:2303,3328,0",
		"cryptic:anger those who adhere to saradomin's edicts to prevent travel.",
		"skill:CHARLIE:i need to give charlie a cooked pike.");
	private static final int BFS_RUNS = 20;

	private final Client client;
	private final ClueHelperPlugin clueHelper;
	private final Catalog catalog;
	private final WalkData.Loaded walk;
	private final Executor executor;

	RouteSampler(Client client, ClueHelperPlugin clueHelper, Catalog catalog, WalkData.Loaded walk, Executor executor)
	{
		this.client = client;
		this.clueHelper = clueHelper;
		this.catalog = catalog;
		this.walk = walk;
		this.executor = executor;
	}

	/** Client thread only: times the start walk here, then plans the steps on the executor. */
	void run()
	{
		PlayerModel model = clueHelper.getPlayerModel();
		PlayerSnapshot player = model.getSnapshot();
		PlanStart start = clueHelper.getRoutes().getStart();
		if (player == null || model.getRuneModel() == null || start == null || catalog == null || walk == null)
		{
			log.info("{} not ready: snapshot, start, catalog or walk data missing", TAG);
			return;
		}
		AvailabilityEngine engine = new AvailabilityEngine(model.getRuneModel(), id -> "item " + id);
		timeBfs(player, engine, start);
		executor.execute(() -> planAll(player, engine, start));
	}

	private void timeBfs(PlayerSnapshot player, AvailabilityEngine engine, PlanStart start)
	{
		boolean[] rowOpen = new WalkGates(walk.getTable(), player, engine, AvailabilityService.nowMinutes()).rowOpen();
		long[] capture = new long[BFS_RUNS];
		long[] bfs = new long[BFS_RUNS];
		int reached = 0;
		for (int i = 0; i < BFS_RUNS; i++)
		{
			long t0 = System.nanoTime();
			LoadedScene scene = LoadedScene.capture(client.getTopLevelWorldView());
			long t1 = System.nanoTime();
			WalkCosts result = WalkCosts.from(Ground.world(walk.getMap(), scene, walk.getTable(), row -> rowOpen[row]), start.getTile());
			bfs[i] = System.nanoTime() - t1;
			capture[i] = t1 - t0;
			reached = result.reachedTiles();
		}
		Arrays.sort(capture);
		Arrays.sort(bfs);
		log.info("{} scene at {}: capture median {} ms, start walk median {} ms (max {} ms), {} tiles reached", TAG, start.getTile(),
			ms(capture[BFS_RUNS / 2]), ms(bfs[BFS_RUNS / 2]), ms(bfs[BFS_RUNS - 1]), reached);
	}

	private void planAll(PlayerSnapshot player, AvailabilityEngine engine, PlanStart start)
	{
		Map<String, Step> steps;
		try
		{
			steps = DriftSteps.read();
		}
		catch (IOException e)
		{
			log.warn("{} drift steps unreadable", TAG, e);
			return;
		}
		for (String key : STEPS)
		{
			Step step = steps.get(key);
			Plan plan = Planner.plan(PlanInput.builder()
				.step(step)
				.player(player)
				.engine(engine)
				.nowMinutes(AvailabilityService.nowMinutes())
				.catalog(catalog)
				.table(walk.getTable())
				.noTeleport(walk.getNoTeleport())
				.start(start)
				.settings(PlannerSettings.builder().build())
				.build());
			log.info("{} {} {}: {} ms, {} labels, {} searches{}", TAG, key, step.getTargets(), ms(plan.getSearchNanos()), plan.getLabels(),
				plan.getSearches(), plan.getNote() == null ? "" : ", " + plan.getNote());
			line("best", plan.getBest());
			line("same book", plan.getSameBook());
			plan.getAlternatives().forEach(route -> line("alt", route));
		}
	}

	private static void line(String label, Route route)
	{
		if (route != null)
		{
			log.info("{}   {} {}t (rank {}): {} {}", TAG, label, route.getTicks(), (route.getRankHalfTicks() + 1) / 2, route.describe(),
				route.getSpent());
		}
	}

	private static String ms(long nanos)
	{
		return String.format("%.2f", nanos / 1e6);
	}
}

package com.cluehelper.campaign;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

/**
 * Takes the new tick counts of the steps the last golden test marked {@code ticks}, and nothing else: a step whose
 * route or guide changed is refused, it needs playing again. Run after reading changed.html: gradlew acceptTickChanges.
 */
public final class AcceptTickChanges
{
	private AcceptTickChanges()
	{
	}

	public static void main(String[] args) throws IOException
	{
		if (!Files.exists(CampaignFiles.CHANGED))
		{
			System.out.println("No " + CampaignFiles.CHANGED + ": run the tests first");
			return;
		}
		CampaignReplay replay = CampaignReplay.load();
		int accepted = 0;
		for (String line : Files.readAllLines(CampaignFiles.CHANGED, StandardCharsets.UTF_8))
		{
			String[] parts = line.split("\t");
			if (parts.length == 3 && parts[0].equals("ticks") && accept(replay, Paths.get(parts[2])))
			{
				accepted++;
			}
		}
		System.out.println(accepted + " tick changes accepted");
	}

	private static boolean accept(CampaignReplay replay, Path file) throws IOException
	{
		CampaignRecording recording = CampaignFiles.read(file);
		Outcome now = replay.replay(recording, file.getParent());
		Outcome.Change change = recording.expected.changeTo(now);
		if (change != Outcome.Change.TICKS)
		{
			System.out.println("refused " + recording.key + ": " + change + " now, play it again in the campaign");
			return false;
		}
		System.out.println(recording.key + "\n  was " + bestLine(recording.expected) + "\n  now " + bestLine(now));
		recording.expected = now;
		CampaignFiles.write(file, recording);
		return true;
	}

	private static String bestLine(Outcome outcome)
	{
		List<String> route = outcome.getRoute();
		return route.isEmpty() ? "" : route.get(0);
	}
}

package com.cluehelper.campaign;

import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanInput;
import com.cluehelper.route.SceneFiles;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/**
 * The step campaign: every clue step, one mocked clue at a time. Finish saves the step's first plan as a golden
 * recording once it replays offline to what was shown; Bug saves a report for Claude; Previous and Next move without a
 * verdict. Steps waiting for a retest come first, then untested ones in order; reported bugs wait for their fix. No clue is
 * mocked until Next is pressed: the first Next of a session opens the saved step. Stop clears the clue and leaves the
 * step as it was, so the next Next opens it again.
 * Buttons may be pressed on any thread; the campaign's state lives on the client thread, its files on a worker.
 */
@Slf4j
public final class Campaign
{
	private static final String TAG = "[CH-CAMPAIGN]";
	private static final List<String> TIERS = List.of("beginner", "easy", "medium", "hard", "elite", "master");
	/** The Grand Exchange, where the walk through each tier starts. */
	private static final WorldPoint TOUR_START = new WorldPoint(3164, 3486, 0);
	private static final Path STAGING = Paths.get("build/campaign/staging");
	private static final String NOTE_FILE = "note.txt";
	private static final String GUIDE_FILE = "guide-now.txt";
	private static final String CHECK_FILE = "replay-check.txt";
	private static final String SCREENSHOT_FILE = "screenshot.png";

	/** Hands the Clue Scroll plugin a step's clue, or takes it away; client thread. */
	public interface Clues
	{
		void mock(CampaignStep step);

		void clear();
	}

	/** A step the campaign can mock. */
	@Value
	public static class CampaignStep
	{
		String key;
		String tier;
		String type;
		String text;
		/** Its place in core's lists, as {@link com.cluehelper.step.CoreClues#entry} takes it. */
		String coreClue;
		/** Null for a step without a tile. */
		WorldPoint target;
	}

	private final ClientThread clientThread;
	private final CampaignRecorder recorder;
	private final Supplier<List<CampaignStep>> steps;
	private final Clues clues;
	private final Supplier<List<String>> guideNow;
	private final BiConsumer<Path, Runnable> screenshot;
	private final Consumer<String> show;
	private final ExecutorService files;

	private CampaignProgress progress;
	private boolean started;
	private Map<String, CampaignStep> byKey = Map.of();
	private String armed;
	private CampaignRecorder.Capture capture;
	private String message = "";
	private CampaignReplay replay;

	/**
	 * @param steps every step core can hand out; client thread
	 * @param guideNow the guide's sub-steps as shown now; client thread
	 * @param screenshot saves the next game frame to the path, then runs the callback, also when no frame could be taken
	 * @param show the panel's text; any thread
	 * @param files saves and replays recordings off the client thread
	 */
	public Campaign(ClientThread clientThread, CampaignRecorder recorder, Supplier<List<CampaignStep>> steps, Clues clues,
		Supplier<List<String>> guideNow, BiConsumer<Path, Runnable> screenshot, Consumer<String> show, ExecutorService files)
	{
		this.clientThread = clientThread;
		this.recorder = recorder;
		this.steps = steps;
		this.clues = clues;
		this.guideNow = guideNow;
		this.screenshot = screenshot;
		this.show = show;
		this.files = files;
	}

	/** Client thread, once logged in: shows the saved step, without mocking its clue yet. */
	public void resume()
	{
		try
		{
			progress = CampaignProgress.read(CampaignFiles.PROGRESS);
		}
		catch (IOException e)
		{
			log.warn("{} can't read {}", TAG, CampaignFiles.PROGRESS, e);
			say("Can't read " + CampaignFiles.PROGRESS + ": see the log");
			return;
		}
		byKey = steps.get().stream().collect(Collectors.toMap(CampaignStep::getKey, step -> step, (a, b) -> a, LinkedHashMap::new));
		updateOrder();
		markFinishedFromGoldens();
		markChangedForRetest();
		if (progress.current == null || !byKey.containsKey(progress.current))
		{
			progress.current = next(null);
		}
		saveProgress();
		log.info("{} {} steps, at {}", TAG, progress.order.size(), progress.current);
		say("Press Next to start");
	}

	/** Client thread. The step's first plan is the one Finish saves. */
	public void onPlan(Plan plan, PlanInput input)
	{
		if (armed == null || input.getStep() == null || !armed.equals(input.getStep().getKey()))
		{
			return;
		}
		armed = null;
		try
		{
			capture = recorder.capture(byKey.get(input.getStep().getKey()).getCoreClue(), plan, input);
			capture.getProblems().forEach(problem -> log.warn("{} {}: {}", TAG, input.getStep().getKey(), problem));
			say(capture.getProblems().isEmpty() ? "Route captured" : "Route captured with problems: see the log");
		}
		catch (ReflectiveOperationException | RuntimeException e)
		{
			log.warn("{} capture of {} failed", TAG, input.getStep().getKey(), e);
			say("Capture failed: see the log");
		}
	}

	public void finish()
	{
		clientThread.invokeLater(() ->
		{
			if (!startedOrSay())
			{
				return;
			}
			if (capture == null || !capture.getRecording().key.equals(progress.current))
			{
				say("No route captured for this step yet: wait for its first plan");
				return;
			}
			if (!capture.getProblems().isEmpty())
			{
				say("Not saved: " + capture.getProblems().get(0));
				return;
			}
			CampaignRecorder.Capture saving = capture;
			say("Checking the replay...");
			files.execute(() -> save(saving));
		});
	}

	public void bug(String note)
	{
		if (note == null || note.isBlank())
		{
			say("A bug needs a note");
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (!startedOrSay())
			{
				return;
			}
			String key = progress.current;
			CampaignRecorder.Capture reported = capture != null && capture.getRecording().key.equals(key) ? capture : null;
			List<String> guide = guideNow.get();
			Path folder = CampaignFiles.BUGS.resolve(CampaignFiles.slug(key));
			progress.statuses.put(key, CampaignProgress.Status.BUG);
			progress.notes.put(key, note.trim());
			files.execute(() -> report(folder, key, note.trim(), guide, reported));
			screenshot.accept(folder.resolve(SCREENSHOT_FILE), () -> clientThread.invokeLater(this::advance));
		});
	}

	/** The session's first Next opens the saved step; every later one moves on. */
	public void next()
	{
		clientThread.invokeLater(() ->
		{
			if (progress == null)
			{
				return;
			}
			if (started)
			{
				advance();
				return;
			}
			started = true;
			if (progress.current == null)
			{
				advance();
				return;
			}
			mockCurrent();
		});
	}

	/** Ends the session: the clue goes, nothing is recorded, and the step stays where it was. */
	public void stop()
	{
		clientThread.invokeLater(() ->
		{
			if (!startedOrSay())
			{
				return;
			}
			started = false;
			armed = null;
			capture = null;
			clues.clear();
			say("Stopped: Next starts again at this step");
		});
	}

	public void previous()
	{
		clientThread.invokeLater(() ->
		{
			if (!startedOrSay())
			{
				return;
			}
			if (progress.history.isEmpty())
			{
				say("No step before this one");
				return;
			}
			progress.current = progress.history.remove(progress.history.size() - 1);
			saveProgress();
			mockCurrent();
		});
	}

	private boolean startedOrSay()
	{
		if (!started)
		{
			say("Press Next to start");
		}
		return started;
	}

	private void advance()
	{
		String next = next(progress.current);
		if (next == null)
		{
			say("Every step is finished or waiting for a fix");
			saveProgress();
			showState();
			return;
		}
		if (progress.current != null)
		{
			progress.history.add(progress.current);
		}
		if (progress.status(next) == CampaignProgress.Status.UNTESTED)
		{
			progress.untestedFrom = next;
		}
		progress.current = next;
		saveProgress();
		mockCurrent();
	}

	/**
	 * Steps to retest first, then the next untested one after the untested step reached last (else after {@code from}),
	 * wrapping round; never {@code from} itself. A retest further down the order doesn't move where the untested go on.
	 */
	private String next(String from)
	{
		List<String> order = progress.order;
		for (String key : order)
		{
			if (!key.equals(from) && progress.status(key) == CampaignProgress.Status.RETEST)
			{
				return key;
			}
		}
		String resume = progress.untestedFrom != null ? progress.untestedFrom : from;
		int at = resume == null ? -1 : order.indexOf(resume);
		for (int i = 1; i <= order.size(); i++)
		{
			String key = order.get(Math.floorMod(at + i, order.size()));
			if (!key.equals(from) && progress.status(key) == CampaignProgress.Status.UNTESTED)
			{
				return key;
			}
		}
		return null;
	}

	private void mockCurrent()
	{
		capture = null;
		CampaignStep step = byKey.get(progress.current);
		if (step == null)
		{
			showState();
			return;
		}
		armed = step.getKey();
		message = "";
		clues.mock(step);
		showState();
	}

	private void save(CampaignRecorder.Capture saving)
	{
		CampaignRecording recording = saving.getRecording();
		try
		{
			Outcome replayed = write(STAGING, saving);
			Outcome.Change change = recording.expected.changeTo(replayed);
			if (change != Outcome.Change.NONE)
			{
				log.warn("{} {} not saved, the replay differs ({}):\n  shown    {}\n  replayed {}", TAG, recording.key, change,
					recording.expected, replayed);
				say("Not saved: the replay differs (" + change + "), see the log");
				return;
			}
			Path golden = CampaignFiles.goldenFile(recording.tier, recording.key);
			Files.createDirectories(golden.getParent());
			Files.move(STAGING.resolve(golden.getFileName()), golden, StandardCopyOption.REPLACE_EXISTING);
			if (recording.sceneFile != null)
			{
				Files.move(STAGING.resolve(recording.sceneFile), golden.resolveSibling(recording.sceneFile), StandardCopyOption.REPLACE_EXISTING);
			}
			log.info("{} {} finished: {}", TAG, recording.key, golden);
			clientThread.invokeLater(() ->
			{
				progress.statuses.put(recording.key, CampaignProgress.Status.FINISHED);
				progress.notes.remove(recording.key);
				advance();
				say("Saved " + golden.getFileName());
			});
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("{} saving {} failed", TAG, recording.key, e);
			say("Saving failed: see the log");
		}
	}

	/** Writes the recording and its scene to {@code folder}, then replays them from there. Files thread. */
	private Outcome write(Path folder, CampaignRecorder.Capture saving) throws IOException
	{
		CampaignRecording recording = saving.getRecording();
		String slug = CampaignFiles.slug(recording.key);
		Files.createDirectories(folder);
		if (saving.getScene() != null)
		{
			recording.sceneFile = slug + CampaignFiles.SCENE_SUFFIX;
			SceneFiles.write(folder.resolve(recording.sceneFile).toFile(), saving.getScene(), saving.getSceneTile());
		}
		CampaignFiles.write(folder.resolve(slug + CampaignFiles.RECORDING_SUFFIX), recording);
		if (replay == null)
		{
			replay = CampaignReplay.load();
		}
		return replay.replay(recording, folder);
	}

	private void report(Path folder, String key, String note, List<String> guide, CampaignRecorder.Capture reported)
	{
		try
		{
			Files.createDirectories(folder);
			Files.write(folder.resolve(NOTE_FILE), List.of(key, "", note), StandardCharsets.UTF_8);
			Files.write(folder.resolve(GUIDE_FILE), guide, StandardCharsets.UTF_8);
			List<String> check = new ArrayList<>();
			if (reported == null)
			{
				check.add("No route was captured for this step.");
			}
			else
			{
				Outcome replayed = write(folder, reported);
				check.add("change: " + reported.getRecording().expected.changeTo(replayed));
				check.add("shown:    " + reported.getRecording().expected);
				check.add("replayed: " + replayed);
				reported.getProblems().forEach(problem -> check.add("problem: " + problem));
			}
			Files.write(folder.resolve(CHECK_FILE), check, StandardCharsets.UTF_8);
			log.info("{} bug reported for {}: {}", TAG, key, folder);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("{} the bug report for {} failed", TAG, key, e);
			say("Writing the bug report failed: see the log");
		}
	}

	/** New core steps join at the end; steps core no longer has drop out. */
	private void updateOrder()
	{
		Set<String> known = new HashSet<>(progress.order);
		progress.order.removeIf(key -> !byKey.containsKey(key));
		List<CampaignStep> added = byKey.values().stream().filter(step -> !known.contains(step.getKey())).collect(Collectors.toList());
		progress.order.addAll(tour(added));
	}

	/** By tier, and within a tier from each step to the nearest one left, so steps in a row are close. */
	private static List<String> tour(List<CampaignStep> steps)
	{
		List<String> order = new ArrayList<>();
		Map<String, List<CampaignStep>> byTier = steps.stream().collect(Collectors.groupingBy(CampaignStep::getTier));
		List<String> tiers = new ArrayList<>(byTier.keySet());
		tiers.sort(Comparator.comparingInt(tier -> TIERS.contains(tier) ? TIERS.indexOf(tier) : TIERS.size()));
		for (String tier : tiers)
		{
			List<CampaignStep> left = byTier.get(tier).stream().filter(step -> step.getTarget() != null).collect(Collectors.toList());
			WorldPoint at = TOUR_START;
			while (!left.isEmpty())
			{
				WorldPoint from = at;
				CampaignStep nearest = left.stream().min(Comparator.comparingInt(step -> distance(from, step.getTarget()))).orElseThrow();
				left.remove(nearest);
				order.add(nearest.getKey());
				at = nearest.getTarget();
			}
			byTier.get(tier).stream().filter(step -> step.getTarget() == null).forEach(step -> order.add(step.getKey()));
		}
		return order;
	}

	private static int distance(WorldPoint a, WorldPoint b)
	{
		return Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY()));
	}

	/** A golden recording on disk means the step was finished, even when progress.json was lost. */
	private void markFinishedFromGoldens()
	{
		for (String key : progress.order)
		{
			CampaignStep step = byKey.get(key);
			if (progress.status(key) == CampaignProgress.Status.UNTESTED && Files.exists(CampaignFiles.goldenFile(step.getTier(), key)))
			{
				progress.statuses.put(key, CampaignProgress.Status.FINISHED);
			}
		}
	}

	/** A finished step whose outcome the last golden test found changed beyond ticks is played again. */
	private void markChangedForRetest()
	{
		try
		{
			if (!Files.exists(CampaignFiles.CHANGED) || Files.getLastModifiedTime(CampaignFiles.CHANGED).toMillis() <= progress.changedSeen)
			{
				return;
			}
			progress.changedSeen = Files.getLastModifiedTime(CampaignFiles.CHANGED).toMillis();
			for (String line : Files.readAllLines(CampaignFiles.CHANGED, StandardCharsets.UTF_8))
			{
				String[] parts = line.split("\t");
				if (parts.length == 3 && parts[0].equals("route") && progress.status(parts[1]) == CampaignProgress.Status.FINISHED)
				{
					progress.statuses.put(parts[1], CampaignProgress.Status.RETEST);
					log.info("{} {} changed: retest", TAG, parts[1]);
				}
			}
		}
		catch (IOException e)
		{
			log.warn("{} can't read {}", TAG, CampaignFiles.CHANGED, e);
		}
	}

	private void saveProgress()
	{
		try
		{
			progress.write(CampaignFiles.PROGRESS);
		}
		catch (IOException e)
		{
			log.warn("{} can't save {}", TAG, CampaignFiles.PROGRESS, e);
			say("Can't save progress: see the log");
		}
	}

	/** Any thread. */
	private void say(String text)
	{
		log.info("{} {}", TAG, text);
		clientThread.invokeLater(() ->
		{
			message = text;
			showState();
		});
	}

	private void showState()
	{
		if (progress == null)
		{
			show.accept("Starts once logged in\n" + message);
			return;
		}
		String key = progress.current;
		CampaignStep step = key == null ? null : byKey.get(key);
		Map<CampaignProgress.Status, Integer> counts = progress.counts();
		String tally = progress.order.size() + " steps: " + Arrays.stream(CampaignProgress.Status.values())
			.map(status -> counts.getOrDefault(status, 0) + " " + status.name().toLowerCase())
			.collect(Collectors.joining(", "));
		String where = step == null ? "No step" : (progress.order.indexOf(key) + 1) + " / " + progress.order.size() + "  " + step.getTier()
			+ " " + step.getType() + "  " + progress.status(key).name().toLowerCase();
		String note = key == null ? null : progress.notes.get(key);
		show.accept(where + "\n" + (step == null ? "" : step.getKey() + "\n" + step.getText() + "\n") + (note == null ? "" : "Bug: " + note + "\n")
			+ tally + "\n" + message);
	}
}

package com.cluehelper.campaign;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

/** Where the campaign keeps its files, and how a recording is written: gzipped JSON, its scene beside it. */
public final class CampaignFiles
{
	/** The golden recordings, one folder per tier. They ship in the public repo. */
	public static final Path GOLDENS = Paths.get("src/test/resources/campaign");
	/** Progress and bug reports stay local: tools/ is never committed. */
	public static final Path LOCAL = Paths.get("tools/campaign");
	public static final Path BUGS = LOCAL.resolve("bugs");
	public static final Path PROGRESS = LOCAL.resolve("progress.json");
	/** The golden test's report: each changed key with {@code route} or {@code ticks}, and the page that shows why. */
	public static final Path CHANGED = Paths.get("build/campaign/changed.txt");
	public static final Path CHANGED_PAGE = Paths.get("build/campaign/changed.html");
	static final String RECORDING_SUFFIX = ".json.gz";
	static final String SCENE_SUFFIX = ".scene.gz";
	private static final int SLUG_CHARS = 48;

	private static final Gson GSON = new Gson();

	private CampaignFiles()
	{
	}

	/** Short and unique per key: long cryptic texts share their first words. */
	public static String slug(String key)
	{
		String words = key.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "");
		return words.substring(0, Math.min(SLUG_CHARS, words.length())) + "-" + Integer.toHexString(key.hashCode());
	}

	static Path goldenFile(String tier, String key)
	{
		return GOLDENS.resolve(tier).resolve(slug(key) + RECORDING_SUFFIX);
	}

	static List<Path> goldenFiles() throws IOException
	{
		try (Stream<Path> files = Files.walk(GOLDENS))
		{
			return files.filter(file -> file.getFileName().toString().endsWith(RECORDING_SUFFIX)).sorted().collect(Collectors.toList());
		}
	}

	static CampaignRecording read(Path file) throws IOException
	{
		try (Reader in = new InputStreamReader(new GZIPInputStream(Files.newInputStream(file)), StandardCharsets.UTF_8))
		{
			return GSON.fromJson(in, CampaignRecording.class);
		}
	}

	static void write(Path file, CampaignRecording recording) throws IOException
	{
		Files.createDirectories(file.getParent());
		try (Writer out = new OutputStreamWriter(new GZIPOutputStream(Files.newOutputStream(file)), StandardCharsets.UTF_8))
		{
			GSON.toJson(recording, out);
		}
	}
}

package com.cluehelper.campaign;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

/**
 * Every campaign step Nathan finished must replay to the outcome he signed off. A changed step fails the build: a
 * route or guide change is played again in the campaign, a tick-only one is accepted with {@code acceptTickChanges}
 * after reading {@code build/campaign/changed.html}.
 */
public class CampaignGoldensTest
{
	@Test
	public void finishedStepsReplayTheirSignedOffOutcome() throws IOException
	{
		assertTrue(CampaignFiles.GOLDENS + " is missing: the campaign's recordings must be there, even before the first",
			Files.isDirectory(CampaignFiles.GOLDENS));
		List<Path> files = CampaignFiles.goldenFiles();
		List<ChangeReport.Changed> changed = new ArrayList<>();
		CampaignReplay replay = files.isEmpty() ? null : CampaignReplay.load();
		for (Path file : files)
		{
			CampaignRecording recording = CampaignFiles.read(file);
			Outcome now = replay.replay(recording, file.getParent());
			Outcome.Change change = recording.expected.changeTo(now);
			if (change != Outcome.Change.NONE)
			{
				changed.add(new ChangeReport.Changed(file, recording, now, change));
			}
		}
		ChangeReport.write(changed);
		System.out.println(files.size() + " campaign steps replayed, " + changed.size() + " changed");
		assertTrue(changed.size() + " of " + files.size() + " finished steps changed (see " + CampaignFiles.CHANGED_PAGE + "):\n"
			+ changed.stream().map(step -> step.getChange() + " " + step.getRecording().key).collect(Collectors.joining("\n")),
			changed.isEmpty());
	}
}

package com.cluehelper.campaign;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Where the campaign stands, kept in tools/campaign/progress.json so it survives restarts. Claude edits it after a fix. */
final class CampaignProgress
{
	enum Status
	{
		UNTESTED,
		FINISHED,
		/** Waiting for a fix: out of the queue until it is set to RETEST. */
		BUG,
		/** Fixed, or its finished outcome changed: comes before every untested step. */
		RETEST
	}

	private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();

	/** Every step key, by tier and then a walk from each to the nearest next. */
	List<String> order = new ArrayList<>();
	String current;
	/** The untested step the walk through the order reached last: after the retests, the untested go on from there. */
	String untestedFrom;
	/** Steps not in it are untested. */
	Map<String, Status> statuses = new HashMap<>();
	Map<String, String> notes = new HashMap<>();
	/** The steps shown before the current one, the last most recent: Previous goes back through them. */
	List<String> history = new ArrayList<>();
	/** The golden test report last read, by modification time, so each report marks its steps once. */
	long changedSeen;

	Status status(String key)
	{
		return statuses.getOrDefault(key, Status.UNTESTED);
	}

	static CampaignProgress read(Path file) throws IOException
	{
		if (!Files.exists(file))
		{
			return new CampaignProgress();
		}
		try (Reader in = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			return GSON.fromJson(in, CampaignProgress.class);
		}
	}

	void write(Path file) throws IOException
	{
		Files.createDirectories(file.getParent());
		try (Writer out = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
		{
			GSON.toJson(this, out);
		}
	}

	Map<Status, Integer> counts()
	{
		Map<Status, Integer> counts = new HashMap<>();
		order.forEach(key -> counts.merge(status(key), 1, Integer::sum));
		return counts;
	}
}

package com.cluehelper.campaign;

import com.cluehelper.guide.SubStep;
import com.cluehelper.guide.SubSteps;
import com.cluehelper.memory.BankMemory;
import com.cluehelper.memory.StashMemory;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.player.RuneModel;
import com.cluehelper.route.GearPicker;
import com.cluehelper.route.GearPieces;
import com.cluehelper.route.LoadedScene;
import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanInput;
import com.cluehelper.route.RequiredItems;
import com.cluehelper.route.StepNeeds;
import com.cluehelper.route.WalkCosts;
import com.cluehelper.step.CoreClues;
import com.cluehelper.step.Stage;
import com.cluehelper.step.StageTarget;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import com.cluehelper.step.StepResolver;
import com.cluehelper.transport.ItemClause;
import com.cluehelper.transport.Requirements;
import com.google.gson.Gson;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/**
 * Client thread. Turns a step's first live plan into a recording: the clue resolved, its needs judged and its guide
 * written again through a {@link ClientTape}, so every client read lands on the tape, and the snapshots cut down to the
 * items the planner could use. The outcome kept is the live plan's route with the guide those same inputs give.
 */
public final class CampaignRecorder
{
	private final Client client;
	private final StashMemory stash;
	private final GearPieces gearPieces;
	private final BankMemory bankMemory;
	private final Supplier<RuneModel> runes;
	private final StepIndex index = StepIndex.read(new Gson());

	/** @param runes the player model's, loaded from the client's cache after start */
	public CampaignRecorder(Client client, StashMemory stash, GearPieces gearPieces, BankMemory bankMemory, Supplier<RuneModel> runes)
	{
		this.client = client;
		this.stash = stash;
		this.gearPieces = gearPieces;
		this.bankMemory = bankMemory;
		this.runes = runes;
	}

	/** What Finish saves and Bug reports; {@link #problems} say why a replay can't give it back. */
	@Value
	static class Capture
	{
		CampaignRecording recording;
		LoadedScene scene;
		WorldPoint sceneTile;
		List<String> problems;
	}

	/** @param coreClue the mocked clue's place in core's lists */
	Capture capture(String coreClue, Plan plan, PlanInput input) throws ReflectiveOperationException
	{
		CampaignRecording recording = new CampaignRecording();
		ClientTape tape = ClientTape.recording(client);
		Step step = new StepResolver(() -> index).resolve(CoreClues.entry(coreClue), CoreClues.plugin(tape.client()));
		Step travel = StageTarget.travelStep(step, PlayerSnapshot.items(input.getPlayer().getInventory()));
		recording.stashStates = new TreeMap<>();
		recording.gearPieces = new TreeMap<>();
		recording.onlyInBankedKit = new TreeMap<>();
		StepNeeds needs = new StepNeeds(tape.client(), id -> recordStash(recording, id),
			(bonus, owned) -> recordGear(recording, bonus.name(), gearPieces.of(bonus, owned)),
			() -> StepNeeds.ownedItemIds(input.getPlayer(), input.getBanked()));
		RequiredItems required = needs.of(travel);
		SubSteps subSteps = new SubSteps(tape.client(), input::getPlayer, id -> recordKit(recording, id), needs, input::getStart,
			input.getSettings()::isScrollBookOutOfWilderness);
		List<SubStep> guide = plan.getBest() == null ? List.of() : subSteps.of(plan.getBest(), travel);

		Set<Integer> usable = usableItemIds(input, required, travel, recording);
		recording.key = step.getKey();
		recording.coreClue = coreClue;
		recording.tier = step.getTier();
		recording.type = step.getType();
		recording.text = step.getText();
		recording.recordedOn = LocalDate.now().toString();
		recording.player = cutDown(input.getPlayer(), usable);
		recording.banked = cutDown(input.getBanked(), usable);
		recording.pinPending = input.isPinPending();
		recording.atOpenBank = input.isAtOpenBank();
		recording.nowMinutes = input.getNowMinutes();
		recording.startKind = input.getStart().getKind().name();
		WorldPoint tile = input.getStart().getTile();
		recording.startTile = new int[]{tile.getX(), tile.getY(), tile.getPlane()};
		recording.settings = input.getSettings();
		recording.revertTicksLeft = input.getRevertTicksLeft();
		recording.refusedChanges = input.getRefusedChanges();
		recording.foreignHouseStart = input.isForeignHouseStart();
		recording.client = tape.answers();
		recording.expected = Outcome.of(plan, guide);
		WalkCosts walk = input.getStart().getWalk();
		return new Capture(recording, walk == null ? null : walk.getScene(), tile, problems(tape, travel, input.getStep()));
	}

	private static List<String> problems(ClientTape tape, Step travel, Step live)
	{
		List<String> problems = new ArrayList<>();
		tape.unreplayable().forEach(call -> problems.add("a client call a replay can't answer: " + call));
		if (!travel.getKey().equals(live.getKey()) || !travel.getTargets().equals(live.getTargets()))
		{
			problems.add("resolved again, the step differs from the live one: " + travel.getKey() + " " + travel.getTargets()
				+ " vs " + live.getKey() + " " + live.getTargets());
		}
		return List.copyOf(problems);
	}

	private StashMemory.State recordStash(CampaignRecording recording, int objectId)
	{
		StashMemory.State state = stash.state(objectId);
		recording.stashStates.put(objectId, state.name());
		return state;
	}

	private static Map<Integer, GearPicker.Piece> recordGear(CampaignRecording recording, String bonus, Map<Integer, GearPicker.Piece> pieces)
	{
		recording.gearPieces.computeIfAbsent(bonus, b -> new TreeMap<>()).putAll(pieces);
		return pieces;
	}

	private boolean recordKit(CampaignRecording recording, int itemId)
	{
		boolean only = bankMemory.onlyInBankedKit(itemId);
		recording.onlyInBankedKit.put(itemId, only);
		return only;
	}

	private static boolean meets(Stage stage, int itemId)
	{
		return stage.getItem() != null && stage.getItem().fulfilledBy(itemId);
	}

	/**
	 * Items a route could use: any a teleport, a spellbook change or a walk gate asks for, runes and what stands in for
	 * them, and stored items that meet one of the step's needs or stages.
	 */
	private Set<Integer> usableItemIds(PlanInput input, RequiredItems required, Step travel, CampaignRecording recording)
	{
		Set<Integer> usable = new HashSet<>(runes.get().sourceItemIds());
		input.getCatalog().getTeleports().forEach(row -> addItems(row.getRequirements(), usable));
		input.getCatalog().getSpellbookChanges().forEach(change -> addItems(change.getRequirements(), usable));
		input.getTable().getGates().forEach(gate -> addItems(gate, usable));
		usable.add(ItemID.HUNTSMANS_KIT);
		recording.gearPieces.values().forEach(pieces -> usable.addAll(pieces.keySet()));
		List<ItemRequirement> needed = new ArrayList<>();
		required.getNeeds().forEach(need -> needed.add(need.getRequirement()));
		Set<Integer> stored = new HashSet<>();
		if (input.getBanked() != null)
		{
			stored.addAll(input.getBanked().storedIds());
		}
		for (int id : stored)
		{
			if (needed.stream().anyMatch(need -> need.fulfilledBy(id)) || travel.getStages().stream().anyMatch(stage -> meets(stage, id)))
			{
				usable.add(id);
			}
		}
		return usable;
	}

	private static void addItems(Requirements requirements, Set<Integer> ids)
	{
		if (requirements == null)
		{
			return;
		}
		for (ItemClause clause : requirements.getItems())
		{
			clause.getBranches().forEach(branch -> ids.addAll(branch.getIds()));
		}
	}

	/** Carried and worn items stay whole; bank and group storage keep only usable items, charges only for kept ones. */
	private static PlayerSnapshot cutDown(PlayerSnapshot snapshot, Set<Integer> usable)
	{
		if (snapshot == null)
		{
			return null;
		}
		Map<Integer, Integer> bank = only(snapshot.getBank(), usable);
		Map<Integer, Integer> groupStorage = only(snapshot.getGroupStorage(), usable);
		Set<Integer> kept = new HashSet<>(snapshot.carriedIds());
		kept.addAll(snapshot.getPouch().keySet());
		kept.addAll(bank.keySet());
		kept.addAll(groupStorage.keySet());
		return snapshot.toBuilder()
			.bank(bank)
			.groupStorage(groupStorage)
			.charges(only(snapshot.getCharges(), kept))
			.build();
	}

	private static <V> Map<Integer, V> only(Map<Integer, V> items, Set<Integer> ids)
	{
		return items.entrySet().stream().filter(item -> ids.contains(item.getKey()))
			.collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, TreeMap::new));
	}
}

package com.cluehelper.campaign;

import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.route.GearPicker;
import com.cluehelper.route.PlannerSettings;
import java.util.Map;
import java.util.Set;

/**
 * One finished campaign step: what its first plan was planned from, cut down to what the planner reads, and the route
 * and guide lines Nathan signed off. The step itself is not in it: a replay resolves the core clue again with today's
 * step data, so a step-data change is caught like a planner change.
 */
final class CampaignRecording
{
	String key;
	/** Core's list and the clue's place in it ({@code CrypticClue#12}); the key finds it when the list moved. */
	String coreClue;
	String tier;
	String type;
	String text;
	String recordedOn;

	/** Bank and group storage hold only the items a teleport, a rune, a need or a stage could use. */
	PlayerSnapshot player;
	PlayerSnapshot banked;
	boolean pinPending;
	boolean atOpenBank;
	long nowMinutes;
	String startKind;
	int[] startTile;
	/** Beside the recording, in the same folder. */
	String sceneFile;
	PlannerSettings settings;
	int revertTicksLeft;
	Set<String> refusedChanges;
	boolean foreignHouseStart;

	/** STASH unit object id to its remembered state, for each unit the needs asked about. */
	Map<Integer, String> stashStates;
	/** Gear bonus to what each owned piece adds, for each bonus the needs asked about. */
	Map<String, Map<Integer, GearPicker.Piece>> gearPieces;
	/** Item id to whether its only banked copy sat in the huntsman's kit, for each item the guide asked about. */
	Map<Integer, Boolean> onlyInBankedKit;
	/** The client's answers while resolving the clue, judging its needs and writing its guide: see {@link ClientTape}. */
	Map<String, Object> client;

	Outcome expected;
}

package com.cluehelper.campaign;

import com.cluehelper.guide.SubStep;
import com.cluehelper.guide.SubSteps;
import com.cluehelper.memory.StashMemory;
import com.cluehelper.player.Loadouts;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.player.RuneModel;
import com.cluehelper.route.GearPicker;
import com.cluehelper.route.NoTeleportAreas;
import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanInput;
import com.cluehelper.route.PlanStart;
import com.cluehelper.route.Planner;
import com.cluehelper.route.Ground;
import com.cluehelper.route.LoadedScene;
import com.cluehelper.route.WalkCosts;
import com.cluehelper.route.WorldMap;
import com.cluehelper.route.SceneFiles;
import com.cluehelper.route.StepNeeds;
import com.cluehelper.route.WalkGates;
import com.cluehelper.route.WalkTable;
import com.cluehelper.step.CoreClues;
import com.cluehelper.step.StageTarget;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepIndex;
import com.cluehelper.step.StepResolver;
import com.cluehelper.transport.AvailabilityEngine;
import com.cluehelper.transport.Catalog;
import com.cluehelper.transport.CatalogLoader;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;

/**
 * Plans a recording again offline the way the plugin planned it live: the core clue resolved with today's step data,
 * the stages left, the needs, the plan and the guide's sub-steps, every client read answered from the recording's tape.
 */
public final class CampaignReplay
{
	private final WalkTable table;
	private final WorldMap map;
	private final Catalog catalog;
	private final NoTeleportAreas noTeleport;
	private final RuneModel runes;
	private final StepIndex index;
	private Map<String, String> sourcesByKey;

	private CampaignReplay(WalkTable table, WorldMap map, Catalog catalog, NoTeleportAreas noTeleport, RuneModel runes, StepIndex index)
	{
		this.table = table;
		this.map = map;
		this.catalog = catalog;
		this.noTeleport = noTeleport;
		this.runes = runes;
		this.index = index;
	}

	/** The bundled walk table and world map, catalog and step data, and the rune model slice the tests plan with. */
	public static CampaignReplay load() throws IOException
	{
		return new CampaignReplay(WalkTable.load(), WorldMap.load(), CatalogLoader.load(), NoTeleportAreas.load(), Loadouts.runeModel(),
			StepIndex.read(new Gson()));
	}

	/**
	 * A replay that throws (a read that isn't on the tape, core lost the clue) comes back as an outcome saying so: it
	 * differs from every signed-off one, so the step is played again.
	 *
	 * @param folder where the recording's scene file is
	 */
	Outcome replay(CampaignRecording recording, Path folder) throws IOException
	{
		try
		{
			return plan(recording, folder);
		}
		catch (RuntimeException e)
		{
			return new Outcome(List.of("replay failed: " + e), List.of());
		}
	}

	private Outcome plan(CampaignRecording recording, Path folder) throws IOException
	{
		ClientTape tape = ClientTape.replaying(recording.client);
		Client client = tape.client();
		PlayerSnapshot player = recording.player;
		Step travel = StageTarget.travelStep(resolve(recording, client), PlayerSnapshot.items(player.getInventory()));
		StepNeeds needs = new StepNeeds(client, id -> stashState(recording, id), (bonus, owned) -> gearPieces(recording, bonus.name(), owned),
			() -> StepNeeds.ownedItemIds(player, recording.banked));
		AvailabilityEngine engine = new AvailabilityEngine(runes, id -> "item " + id);
		PlanStart start = start(recording, folder, engine);
		PlanInput input = PlanInput.builder()
			.step(travel)
			.player(player)
			.banked(recording.banked)
			.pinPending(recording.pinPending)
			.atOpenBank(recording.atOpenBank)
			.required(needs.of(travel))
			.engine(engine)
			.nowMinutes(recording.nowMinutes)
			.catalog(catalog)
			.table(table)
			.noTeleport(noTeleport)
			.start(start)
			.settings(recording.settings)
			.revertTicksLeft(recording.revertTicksLeft)
			.refusedChanges(recording.refusedChanges)
			.foreignHouseStart(recording.foreignHouseStart)
			.build();
		Plan plan = Planner.withoutAlternatives(input);
		SubSteps subSteps = new SubSteps(client, () -> player, id -> onlyInBankedKit(recording, id), needs, () -> start,
			recording.settings::isScrollBookOutOfWilderness);
		List<SubStep> guide = plan.getBest() == null ? List.of() : subSteps.of(plan.getBest(), travel);
		return Outcome.of(plan, guide);
	}

	private Step resolve(CampaignRecording recording, Client client)
	{
		try
		{
			StepResolver resolver = new StepResolver(() -> index);
			Step step = resolver.resolve(CoreClues.entry(recording.coreClue), CoreClues.plugin(client));
			if (step.getKey().equals(recording.key))
			{
				return step;
			}
			String moved = sourceOf(recording.key);
			if (moved == null)
			{
				throw new IllegalStateException("core has no clue with key " + recording.key + " any more");
			}
			return resolver.resolve(CoreClues.entry(moved), CoreClues.plugin(client));
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException("can't read core's clue " + recording.coreClue + " for " + recording.key, e);
		}
	}

	/** Core's lists moved (a RuneLite update): each clue's place found again by its key, read with every var at 0. */
	private String sourceOf(String key) throws ReflectiveOperationException
	{
		if (sourcesByKey == null)
		{
			sourcesByKey = new HashMap<>();
			StepResolver resolver = new StepResolver(() -> index);
			for (Map.Entry<String, ClueScroll> clue : CoreClues.steps().entrySet())
			{
				sourcesByKey.putIfAbsent(resolver.resolve(clue.getValue(), CoreClues.plugin()).getKey(), clue.getKey());
			}
		}
		return sourcesByKey.get(key);
	}

	private PlanStart start(CampaignRecording recording, Path folder, AvailabilityEngine engine) throws IOException
	{
		WorldPoint tile = new WorldPoint(recording.startTile[0], recording.startTile[1], recording.startTile[2]);
		boolean[] rowOpen = new WalkGates(table, recording.player, engine, recording.nowMinutes).rowOpen();
		LoadedScene scene = recording.sceneFile == null ? null : scene(folder.resolve(recording.sceneFile));
		WalkCosts walk = WalkCosts.from(Ground.world(map, scene, table, row -> rowOpen[row]), tile);
		switch (PlanStart.Kind.valueOf(recording.startKind))
		{
			case SCENE:
				return PlanStart.scene(tile, walk);
			case AT_NODE:
				return PlanStart.atNode(table, table.node(tile));
			default:
				return PlanStart.teleportOnly(tile, walk);
		}
	}

	private static LoadedScene scene(Path file) throws IOException
	{
		try (InputStream in = Files.newInputStream(file))
		{
			return SceneFiles.read(in).getScene();
		}
	}

	private static StashMemory.State stashState(CampaignRecording recording, int objectId)
	{
		String state = recording.stashStates.get(objectId);
		if (state == null)
		{
			throw new IllegalStateException("STASH unit " + objectId + " was not recorded");
		}
		return StashMemory.State.valueOf(state);
	}

	private static Map<Integer, GearPicker.Piece> gearPieces(CampaignRecording recording, String bonus, Collection<Integer> owned)
	{
		Map<Integer, GearPicker.Piece> pieces = recording.gearPieces.get(bonus);
		if (pieces == null)
		{
			throw new IllegalStateException("gear bonus " + bonus + " was not recorded");
		}
		return pieces.entrySet().stream().filter(piece -> owned.contains(piece.getKey()))
			.collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
	}

	private static boolean onlyInBankedKit(CampaignRecording recording, int itemId)
	{
		Boolean only = recording.onlyInBankedKit.get(itemId);
		if (only == null)
		{
			throw new IllegalStateException("whether item " + itemId + " is only in the banked kit was not recorded");
		}
		return only;
	}
}

package com.cluehelper.campaign;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * The golden test's report on the steps whose outcome changed: {@code changed.txt}, which the campaign reads to put
 * route changes back in the queue and {@code acceptTickChanges} reads to take tick-only ones, and {@code changed.html},
 * the same steps side by side, grouped by what changed, the largest route group first.
 */
final class ChangeReport
{
	private static final String TICKS_ONLY = "Ticks only";
	private static final String GUIDE_ONLY = "Guide lines only";
	private static final String FIRST_LEG_END = " → ";

	@Value
	static class Changed
	{
		Path file;
		CampaignRecording recording;
		Outcome now;
		Outcome.Change change;
	}

	private ChangeReport()
	{
	}

	static void write(List<Changed> changed) throws IOException
	{
		Files.createDirectories(CampaignFiles.CHANGED.getParent());
		List<String> lines = changed.stream()
			.map(step -> (step.getChange() == Outcome.Change.TICKS ? "ticks" : "route") + "\t" + step.getRecording().key + "\t" + step.getFile())
			.collect(Collectors.toList());
		Files.write(CampaignFiles.CHANGED, lines, StandardCharsets.UTF_8);
		Files.write(CampaignFiles.CHANGED_PAGE, page(changed).getBytes(StandardCharsets.UTF_8));
	}

	private static String page(List<Changed> changed)
	{
		Map<String, List<Changed>> groups = new LinkedHashMap<>();
		changed.forEach(step -> groups.computeIfAbsent(group(step), g -> new ArrayList<>()).add(step));
		List<Map.Entry<String, List<Changed>>> ordered = new ArrayList<>(groups.entrySet());
		ordered.sort(Comparator.comparingInt((Map.Entry<String, List<Changed>> group) -> rank(group.getKey()))
			.thenComparing(group -> -group.getValue().size()));
		StringBuilder html = new StringBuilder("<!doctype html><meta charset='utf-8'><title>Campaign changes</title><style>"
			+ "body{font:13px sans-serif;margin:16px}table{border-collapse:collapse;width:100%;margin-bottom:24px}"
			+ "td{border:1px solid #ccc;padding:4px;vertical-align:top;font-family:monospace;white-space:pre-wrap}"
			+ ".diff{background:#ffd7d7}.key{font-weight:bold}</style>");
		html.append("<h1>").append(changed.size()).append(" changed steps</h1>");
		if (changed.isEmpty())
		{
			html.append("<p>Every finished step replays its signed-off outcome.</p>");
		}
		for (Map.Entry<String, List<Changed>> group : ordered)
		{
			html.append("<h2>").append(escape(group.getKey())).append(" (").append(group.getValue().size()).append(")</h2>");
			if (group.getKey().equals(TICKS_ONLY))
			{
				html.append("<p>Same route and guide. After reading them: <code>gradlew acceptTickChanges</code></p>");
			}
			html.append("<table><tr><th>Step</th><th>Signed off</th><th>Now</th></tr>");
			group.getValue().forEach(step -> html.append(row(step)));
			html.append("</table>");
		}
		return html.toString();
	}

	private static String group(Changed step)
	{
		if (step.getChange() == Outcome.Change.TICKS)
		{
			return TICKS_ONLY;
		}
		Outcome before = step.getRecording().expected;
		Outcome now = step.getNow();
		if (before.getRoute().equals(now.getRoute()))
		{
			return GUIDE_ONLY;
		}
		return "Route: " + firstLeg(before) + FIRST_LEG_END + firstLeg(now);
	}

	/** Route changes first, then guide-only changes, then tick-only ones. */
	private static int rank(String group)
	{
		return group.equals(TICKS_ONLY) ? 2 : group.equals(GUIDE_ONLY) ? 1 : 0;
	}

	private static String firstLeg(Outcome outcome)
	{
		String best = outcome.getRoute().isEmpty() ? "" : outcome.getRoute().get(0);
		int legs = best.indexOf(": ");
		String route = legs < 0 ? best : best.substring(legs + 2);
		int end = route.indexOf(FIRST_LEG_END);
		return "[" + (end < 0 ? route : route.substring(0, end)) + "]";
	}

	private static String row(Changed step)
	{
		Outcome before = step.getRecording().expected;
		Outcome now = step.getNow();
		return "<tr><td class='key'>" + escape(step.getRecording().tier + "\n" + step.getRecording().key) + "</td><td>"
			+ lines(before, now) + "</td><td>" + lines(now, before) + "</td></tr>";
	}

	private static String lines(Outcome shown, Outcome other)
	{
		StringBuilder cell = new StringBuilder();
		appendLines(cell, shown.getRoute(), other.getRoute());
		cell.append("\n");
		appendLines(cell, shown.getGuide(), other.getGuide());
		return cell.toString();
	}

	private static void appendLines(StringBuilder cell, List<String> shown, List<String> other)
	{
		for (int i = 0; i < shown.size(); i++)
		{
			boolean same = i < other.size() && other.get(i).equals(shown.get(i));
			cell.append(same ? "" : "<span class='diff'>").append(escape(shown.get(i))).append(same ? "" : "</span>").append("\n");
		}
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.cluehelper.campaign;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.stream.Collectors;
import net.runelite.api.Client;

/**
 * A client that answers from a tape. Recording, it passes every call on to the real client and keeps the answers a
 * replay can give back: numbers, texts, enums and their arrays, also when they come through a definition (an item's
 * name). Replaying, it gives those answers back and throws on any call that isn't on the tape, so a replay that needs
 * more than was recorded fails instead of guessing.
 */
public final class ClientTape
{
	private static final String NULL = "<null>";

	private final Client real;
	private final Map<String, Object> answers;
	private final Set<String> unreplayable = new TreeSet<>();
	private final Client client;

	private ClientTape(Client real, Map<String, Object> answers)
	{
		this.real = real;
		this.answers = answers;
		this.client = (Client) proxy(Client.class, real, "");
	}

	/** Client thread: the calls reach the real client. */
	public static ClientTape recording(Client real)
	{
		return new ClientTape(real, new TreeMap<>());
	}

	public static ClientTape replaying(Map<String, Object> answers)
	{
		return new ClientTape(null, new TreeMap<>(answers));
	}

	public Client client()
	{
		return client;
	}

	public Map<String, Object> answers()
	{
		return new TreeMap<>(answers);
	}

	/** Calls a replay can't answer: they returned something other than a value or a definition. */
	public Set<String> unreplayable()
	{
		return Set.copyOf(unreplayable);
	}

	private Object proxy(Class<?> type, Object target, String prefix)
	{
		return Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(proxy, method, args) -> answer(proxy, method, args, target, prefix));
	}

	private Object answer(Object proxy, Method method, Object[] args, Object target, String prefix) throws Throwable
	{
		switch (method.getName())
		{
			case "toString":
				return "ClientTape";
			case "hashCode":
				return System.identityHashCode(proxy);
			case "equals":
				return proxy == args[0];
		}
		String key = prefix + method.getName() + "(" + arguments(args) + ")";
		Class<?> type = method.getReturnType();
		if (isDefinition(type))
		{
			return definition(type, method, args, target, key);
		}
		if (!isValue(type))
		{
			return unanswerable(method, args, target, key);
		}
		if (real == null)
		{
			if (!answers.containsKey(key))
			{
				throw new IllegalStateException("not on the tape: " + key);
			}
			return fromTape(answers.get(key), type);
		}
		Object value = invoke(method, target, args);
		answers.put(key, toTape(value));
		return value;
	}

	private Object definition(Class<?> type, Method method, Object[] args, Object target, String key) throws Throwable
	{
		if (real == null)
		{
			return NULL.equals(answers.get(key)) ? null : proxy(type, null, key + ".");
		}
		Object definition = invoke(method, target, args);
		if (definition == null)
		{
			answers.put(key, NULL);
			return null;
		}
		return proxy(type, definition, key + ".");
	}

	private Object unanswerable(Method method, Object[] args, Object target, String key) throws Throwable
	{
		if (real == null)
		{
			if (method.getReturnType() == void.class)
			{
				return null;
			}
			throw new IllegalStateException("not on the tape: " + key);
		}
		unreplayable.add(key);
		return invoke(method, target, args);
	}

	private static Object invoke(Method method, Object target, Object[] args) throws Throwable
	{
		try
		{
			return method.invoke(target, args);
		}
		catch (InvocationTargetException e)
		{
			throw e.getCause();
		}
	}

	/** ItemComposition, NPCComposition, ObjectComposition: their answers go on the tape under the call that gave them. */
	private static boolean isDefinition(Class<?> type)
	{
		return type.isInterface() && type.getSimpleName().endsWith("Composition");
	}

	private static boolean isValue(Class<?> type)
	{
		return type.isPrimitive() && type != void.class || type == String.class || type.isEnum() || Number.class.isAssignableFrom(type)
			|| type == Boolean.class || type == int[].class || type == String[].class;
	}

	private static String arguments(Object[] args)
	{
		if (args == null)
		{
			return "";
		}
		return Arrays.stream(args).map(arg -> arg instanceof Enum ? ((Enum<?>) arg).name()
			: arg instanceof int[] ? Arrays.toString((int[]) arg) : String.valueOf(arg)).collect(Collectors.joining(","));
	}

	private static Object toTape(Object value)
	{
		if (value == null)
		{
			return NULL;
		}
		if (value instanceof Enum)
		{
			return ((Enum<?>) value).name();
		}
		if (value instanceof int[])
		{
			return Arrays.stream((int[]) value).boxed().collect(Collectors.toList());
		}
		if (value instanceof String[])
		{
			return Arrays.asList((String[]) value);
		}
		return value;
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	private static Object fromTape(Object value, Class<?> type)
	{
		if (NULL.equals(value) && type != String.class)
		{
			return null;
		}
		if (type == int.class || type == Integer.class)
		{
			return ((Number) value).intValue();
		}
		if (type == long.class || type == Long.class)
		{
			return ((Number) value).longValue();
		}
		if (type == double.class || type == Double.class)
		{
			return ((Number) value).doubleValue();
		}
		if (type == float.class || type == Float.class)
		{
			return ((Number) value).floatValue();
		}
		if (type == short.class || type == Short.class)
		{
			return ((Number) value).shortValue();
		}
		if (type == byte.class || type == Byte.class)
		{
			return ((Number) value).byteValue();
		}
		if (type.isEnum())
		{
			return Enum.valueOf((Class<Enum>) type, (String) value);
		}
		if (type == int[].class)
		{
			return ((List<Number>) value).stream().mapToInt(Number::intValue).toArray();
		}
		if (type == String[].class)
		{
			return ((List<String>) value).toArray(new String[0]);
		}
		return NULL.equals(value) ? null : value;
	}
}

package com.cluehelper.campaign;

import com.cluehelper.guide.SubStep;
import com.cluehelper.route.Plan;
import com.cluehelper.route.RouteText;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import lombok.Value;

/** What a step's first plan showed: the route as golden lines, and the guide's sub-steps. */
@Value
public class Outcome
{
	/** The tick counts in a route line: {@code 20t}, {@code (rank 21)}, {@code walk 14}, {@code walk south 3}. */
	private static final Pattern TICKS = Pattern.compile("\\b\\d+t\\b|(?<=\\(rank )\\d+(?=\\))|(?<=walk )\\d+|(?<=walk south )\\d+");

	List<String> route;
	List<String> guide;

	public enum Change
	{
		NONE,
		/** The same route and guide; only tick counts moved. */
		TICKS,
		ROUTE
	}

	static Outcome of(Plan plan, List<SubStep> guide)
	{
		List<String> route = new ArrayList<>();
		route.add("best " + RouteText.describe(plan.getBest()));
		if (plan.getNote() != null)
		{
			route.add("note " + plan.getNote());
		}
		plan.getRequirementNotes().forEach(note -> route.add("needs " + note));
		return new Outcome(List.copyOf(route), guideLines(guide));
	}

	public static List<String> guideLines(List<SubStep> guide)
	{
		return guide.stream().map(step -> step.getKind() + ": " + step.getText() + (step.getDetail() == null ? "" : " (" + step.getDetail() + ")"))
			.collect(Collectors.toList());
	}

	/** How {@code now} differs from this, the signed-off outcome. */
	Change changeTo(Outcome now)
	{
		if (equals(now))
		{
			return Change.NONE;
		}
		return guide.equals(now.guide) && withoutTicks(route).equals(withoutTicks(now.route)) ? Change.TICKS : Change.ROUTE;
	}

	private static List<String> withoutTicks(List<String> lines)
	{
		return lines.stream().map(line -> TICKS.matcher(line).replaceAll("#")).collect(Collectors.toList());
	}
}

package com.cluehelper.campaign;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

/** One recording replayed, beside what was recorded: a bug report's, or a golden's. gradlew campaignReplay -Pfile=<path>. */
public final class ReplayRecording
{
	private ReplayRecording()
	{
	}

	public static void main(String[] args) throws IOException
	{
		Path file = Paths.get(args[0]);
		CampaignRecording recording = CampaignFiles.read(file);
		Outcome now = CampaignReplay.load().replay(recording, file.getParent());
		System.out.println(recording.key + " (" + recording.coreClue + "), recorded " + recording.recordedOn);
		print("recorded", recording.expected);
		print("replayed", now);
		System.out.println("change: " + recording.expected.changeTo(now));
	}

	private static void print(String title, Outcome outcome)
	{
		System.out.println(title + ":");
		outcome.getRoute().forEach(line -> System.out.println("  " + line));
		outcome.getGuide().forEach(line -> System.out.println("  - " + line));
	}
}

package com.cluehelper.dev;

import com.cluehelper.ClueHelperConfig;
import com.cluehelper.link.ClueLink;
import com.cluehelper.memory.MemorySlot;
import com.cluehelper.memory.MemoryStore;
import com.cluehelper.player.PlayerModel;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.player.RuneModel;
import com.cluehelper.route.PlannerRunner;
import com.cluehelper.step.ClueFacts;
import com.cluehelper.step.CoreClueReader;
import com.cluehelper.step.Step;
import com.cluehelper.step.StepKey;
import com.cluehelper.ui.BoxState;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;
import net.runelite.client.plugins.PluginManager;

@Singleton
class BuiltInSelfTests
{
	private static final String ROUND_TRIP_KEY = "devSelfTest";
	/** Aether, the newest rune in enum 982. */
	private static final int LAST_POUCH_TYPE = 23;

	private final Client client;
	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;
	private final PluginManager pluginManager;
	private final ClueHelperConfig config;
	private final ClueLink core;
	private final MemoryStore memory;
	private final MemorySlot<String> roundTrip;
	private final PlayerModel player;

	@Inject
	BuiltInSelfTests(Client client, ClientThread clientThread, ScheduledExecutorService executor,
		PluginManager pluginManager, ClueHelperConfig config, ClueLink core, MemoryStore memory, PlayerModel player)
	{
		this.player = player;
		this.client = client;
		this.clientThread = clientThread;
		this.executor = executor;
		this.pluginManager = pluginManager;
		this.config = config;
		this.core = core;
		this.memory = memory;
		this.roundTrip = memory.slot(ROUND_TRIP_KEY, String.class, () -> null);
	}

	List<SelfTest> create(Supplier<BoxState> shownState, Supplier<BoxState> signalledState)
	{
		return Arrays.asList(
			SelfTest.of("config", this::checkConfig),
			SelfTest.of("core link", this::checkCoreLink),
			SelfTest.of("core link reads a clue", this::checkClueRead),
			SelfTest.of("box state", run ->
				run.check(shownState.get() == signalledState.get(), "box shows " + shownState.get() + ", signals say " + signalledState.get())),
			SelfTest.of("memory store", this::checkMemoryRoundTrip),
			SelfTest.of("player snapshot", this::checkPlayerSnapshot),
			new PlannerRunnerTest());
	}

	private void checkConfig(SelfTestRun run)
	{
		run.check(config.avoidWilderness() != null && config.spellbookChanges() != null,
			"enum keys read through the config proxy: " + config.avoidWilderness() + ", " + config.spellbookChanges());
	}

	private void checkCoreLink(SelfTestRun run)
	{
		Plugin corePlugin = core.getCore();
		run.check(corePlugin != null, "core Clue Scroll plugin found");
		if (corePlugin != null)
		{
			boolean active = pluginManager.isPluginActive(corePlugin);
			run.check(core.isActive() == active, "active flag " + core.isActive() + " agrees with isPluginActive " + active);
		}
	}

	private void checkClueRead(SelfTestRun run)
	{
		ClueScroll clue = core.coreClue();
		if (clue == null || core.getCore() == null)
		{
			run.skip("the Clue Scroll plugin has no clue: read one first");
			return;
		}
		ClueFacts facts = CoreClueReader.facts(clue, core.getCore());
		String key = StepKey.of(facts);
		Step step = core.getCurrentStep();
		run.check(step != null && key.equals(step.getKey()), "current step " + (step == null ? null : step.getKey())
			+ " is core's clue " + key);
		if (step != null)
		{
			run.check(step.isKnown(), "the step data has " + step.getKey());
			run.check(!step.getTargets().isEmpty() || !step.getNpcs().isEmpty(), step.getTargets().size()
				+ " targets, " + step.getNpcs().size() + " NPCs");
		}
	}

	private void checkMemoryRoundTrip(SelfTestRun run)
	{
		if (!memory.hasProfile())
		{
			run.skip("no RuneScape profile yet: log in first");
			return;
		}
		String value = "self-test " + System.nanoTime();
		roundTrip.set(value);
		memory.reload();
		run.check(value.equals(roundTrip.get()), "value read back from the profile after a reload (game state "
			+ client.getGameState() + ")");
		roundTrip.clear();
		memory.reload();
		run.check(roundTrip.get() == null, "value gone from the profile after clear");
	}

	private void checkPlayerSnapshot(SelfTestRun run)
	{
		PlayerSnapshot snapshot = player.getSnapshot();
		RuneModel runes = player.getRuneModel();
		if (snapshot == null || runes == null)
		{
			run.skip("no snapshot yet: log in first");
			return;
		}
		run.check(runes.getSpells().size() > 150, runes.getSpells().size() + " spells read from the cache");
		run.check(runes.pouchRune(LAST_POUCH_TYPE) > 0, "pouch type " + LAST_POUCH_TYPE + " is rune " + runes.pouchRune(LAST_POUCH_TYPE));
		run.check(snapshot.getSpellbook().getBook() != null, "book " + snapshot.getSpellbook().getBook());
		run.check(snapshot.isQuestsRead(), snapshot.getQuests().size() + " quest states read");
		run.check(snapshot.getPosition().getTile() != null, "position " + snapshot.getPosition());
		run.check(!snapshot.getBoostedLevels().isEmpty(), "levels read");
	}

	/** A runner of its own, so the test never supersedes a real planner job. */
	private final class PlannerRunnerTest implements SelfTest
	{
		@Override
		public String name()
		{
			return "planner runner";
		}

		@Override
		public void run(SelfTestRun run)
		{
			PlannerRunner runner = new PlannerRunner(executor, clientThread);
			AtomicBoolean supersededDelivered = new AtomicBoolean();
			runner.submit(() -> "superseded", result -> supersededDelivered.set(true));
			runner.submit(client::isClientThread, ranOnClientThread ->
			{
				run.check(!ranOnClientThread, "job ran off the client thread");
				run.check(client.isClientThread(), "result delivered on the client thread");
				run.check(!supersededDelivered.get(), "superseded job's result dropped");
				run.check(!runner.isWorking(), "runner idle after the latest result");
				run.done();
			});
		}
	}
}

package com.cluehelper.dev;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Consumer;

public class DevCommands
{
	private static final String PREFIX = "ch-";

	private final Map<String, Command> commands = new TreeMap<>();
	private final Consumer<String> reply;

	public DevCommands(Consumer<String> reply)
	{
		this.reply = reply;
		register("help", "list these commands", args -> help());
	}

	public synchronized void register(String nameWithoutPrefix, String usage, Consumer<String[]> action)
	{
		commands.put(nameWithoutPrefix.toLowerCase(Locale.ROOT), new Command(usage, action));
	}

	/** @param command as typed after "::" */
	public void dispatch(String command, String[] args)
	{
		String typed = command.toLowerCase(Locale.ROOT);
		if (!typed.startsWith(PREFIX))
		{
			return;
		}
		Command found;
		synchronized (this)
		{
			found = commands.get(typed.substring(PREFIX.length()));
		}
		if (found == null)
		{
			reply.accept("Unknown command ::" + typed + ", try ::ch-help");
		}
		else
		{
			found.action.accept(args);
		}
	}

	synchronized List<String> lines()
	{
		List<String> lines = new ArrayList<>();
		commands.forEach((name, c) -> lines.add("::" + PREFIX + name + " " + c.usage));
		return lines;
	}

	private void help()
	{
		for (String line : lines())
		{
			reply.accept(line);
		}
	}

	private static final class Command
	{
		private final String usage;
		final Consumer<String[]> action;

		Command(String usage, Consumer<String[]> action)
		{
			this.usage = usage;
			this.action = action;
		}
	}
}

package com.cluehelper.dev;

import com.cluehelper.guide.StepGuide;
import com.cluehelper.hotcold.HotColdService;
import com.cluehelper.guide.SubStep;
import com.cluehelper.link.ClueLink;
import com.cluehelper.link.StepChange;
import com.cluehelper.memory.StashMemory;
