import com.cluehelper.player.Position;
import com.cluehelper.player.RuneModel;
import com.cluehelper.player.Spell;
import com.cluehelper.player.SpellbookState;
import com.cluehelper.transport.AvailabilityService;
import com.cluehelper.transport.AvailabilitySet;
import com.cluehelper.transport.Category;
import com.cluehelper.transport.RowAvailability;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;

/** Client thread only. */
@Slf4j
final class PlayerDump
{
	static final String TAG = "[CH-PLAYER]";
	private static final int PARAM_SPELL_WIDGET = 596;
	private static final int PARAM_SPRITE_LIT = 597;
	private static final int PARAM_SPRITE_DIM = 598;
	private static final double NANOS_PER_MS = 1_000_000.0;

	private final Client client;
	private final PlayerModel model;
	private final AvailabilityService availability;
	private Set<String> lastAvailable = new TreeSet<>();

	PlayerDump(Client client, PlayerModel model, AvailabilityService availability)
	{
		this.client = client;
		this.model = model;
		this.availability = availability;
	}

	void describe(Consumer<String> chat, Consumer<String> logOnly)
	{
		PlayerSnapshot s = model.getSnapshot();
		if (s == null)
		{
			chat.accept("No snapshot: not logged in yet");
			return;
		}
		snapshotLines(s).forEach(chat);
		RuneModel runes = model.getRuneModel();
		if (runes != null)
		{
			spellLines(s, runes).forEach(chat);
		}
		AvailabilitySet carried = availability.getCarried();
		AvailabilitySet banked = availability.getBanked();
		PlayerSnapshot bankedSnapshot = availability.getBankedSnapshot();
		chat.accept(String.format("A_carried: %d of %d rows (v%d); A_banked: %s (both judged in %.2f ms)",
			carried.available().size(), carried.getRows().size(), carried.getSnapshotVersion(),
			bankedSnapshot == null ? "none (no bank seen, useBank off or UIM)"
				: banked.available().size() + " rows, bank " + bankedSnapshot.getBank().size() + " items, group storage "
				+ bankedSnapshot.getGroupStorage().size(),
			availability.getLastJudgeNanos() / NANOS_PER_MS));
		chat.accept("Available by category: " + availableByCategory(carried) + " (every row is in the log)");
		carried.getRows().forEach(row -> logOnly.accept(rowLine(row)));
		chat.accept("Rebuilds: " + model.getStats().summary());
	}

	private static String availableByCategory(AvailabilitySet carried)
	{
		Map<Category, Long> counts = carried.available().stream()
			.collect(Collectors.groupingBy(row -> row.getRow().getCategory(), () -> new EnumMap<>(Category.class), Collectors.counting()));
		return counts.entrySet().stream().map(e -> e.getKey() + " " + e.getValue()).collect(Collectors.joining(", "));
	}

	void onJudged(AvailabilitySet carried)
	{
		PlayerSnapshot s = model.getSnapshot();
		Set<String> available = carried.available().stream().map(r -> r.getRow().getName()).collect(Collectors.toCollection(TreeSet::new));
		Set<String> gained = new TreeSet<>(available);
		gained.removeAll(lastAvailable);
		Set<String> lost = new TreeSet<>(lastAvailable);
		lost.removeAll(available);
		lastAvailable = available;
		StringBuilder line = new StringBuilder(TAG).append(" t").append(client.getTickCount())
			.append(" snapshot v").append(s == null ? 0 : s.getVersion())
			.append(" A_carried ").append(available.size()).append('/').append(carried.getRows().size());
		if (s != null)
		{
			line.append(" pouch ").append(s.isPouchHeld() ? names(s.getPouch()) : "not held")
				.append(" charges ").append(charges(s));
		}
		if (!gained.isEmpty())
		{
			line.append(" +").append(gained);
		}
		if (!lost.isEmpty())
		{
			line.append(" -").append(lost);
		}
		log.info(line.toString());
	}

	private List<String> snapshotLines(PlayerSnapshot s)
	{
		List<String> lines = new ArrayList<>();
		Position p = s.getPosition();
		Position now = model.getPosition();
		lines.add(String.format("Snapshot v%d (t%d): %s %s, now %s, wild %d, %s world%s, account %s", s.getVersion(),
			s.getTick(), p.getKind(), tile(p.getTile()), tile(now.getTile()) + (now.getMapped() != null
				&& !now.getMapped().equals(now.getTile()) ? " (mapped " + tile(now.getMapped()) + ")" : ""),
			s.getWildernessLevel(), s.isMembersWorld() ? "members" : "F2P", s.isPvpWorld() ? ", PvP" : "",
			s.getAccountType()) + (s.getDormantReason() == null ? "" : ", dormant: " + s.getDormantReason()));
		SpellbookState b = s.getSpellbook();
		lines.add(String.format("Book %s%s, cape changes left %d, Arceuus %s, access ancient %s lunar %s swap %s",
			b.getBook(), b.isPendingRevert() ? " (pending revert)" : "", b.getCapeChangesLeft(), yes(b.isArceuusUnlocked()),
			yes(b.isAncientAccess()), yes(b.isLunarAccess()), yes(b.isSwapAccess())));
		lines.add("Inventory: " + names(s.getInventory()));
		lines.add("Worn: " + names(s.getWorn()));
		lines.add("Pouch: " + (s.isPouchHeld() ? names(s.getPouch()) : "not held"));
		lines.add("Charges: " + charges(s));
		long finished = s.getQuests().values().stream().filter(q -> q == QuestState.FINISHED).count();
		lines.add(String.format("Quests %s: %d/%d finished, %d QP; Magic %d, total %d, combat %d; vars %s / varps %s",
			s.isQuestsRead() ? "read" : "not read", finished, s.getQuests().size(), s.getQuestPoints(),
			s.getBoostedLevels().getOrDefault(Skill.MAGIC, 0), s.getTotalLevel(), s.getCombatLevel(),
			s.getVarbits().size(), s.getVarps().size()));
		return lines;
	}

	private List<String> spellLines(PlayerSnapshot s, RuneModel runes)
	{
		List<String> lines = new ArrayList<>();
		List<String> mismatches = new ArrayList<>();
		int checked = 0;
		for (Book book : Book.values())
		{
			List<String> castable = new ArrayList<>();
			for (Spell spell : runes.getSpells())
			{
				if (spell.getBook() != book)
				{
					continue;
				}
				boolean ours = runes.whyNotCastable(spell, s).isEmpty();
				if (ours && spell.getName().contains("Teleport"))
				{
					castable.add(spell.getName());
				}
				Boolean lit = book == s.getSpellbook().getBook() ? widgetLit(spell) : null;
				if (lit != null)
				{
					checked++;
					if (lit != ours)
					{
						mismatches.add(spell.getName() + " widget " + (lit ? "lit" : "dim") + ", ours " + (ours ? "castable" : runes.whyNotCastable(spell, s)));
					}
				}
			}
			lines.add(book + " teleports castable: " + castable.size() + " " + castable);
		}
		lines.add(checked == 0 ? "Spell widget check: open the magic tab and run ::ch-player again"
			: "Spell widget check: " + checked + " spells, " + mismatches.size() + " mismatches " + mismatches);
		return lines;
	}

	/** Null while the spell's widget is hidden, since a hidden widget's sprite is stale. */
	private Boolean widgetLit(Spell spell)
	{
		int widgetId = client.getItemDefinition(spell.getObj()).getIntValue(PARAM_SPELL_WIDGET);
		Widget widget = widgetId <= 0 ? null : client.getWidget(widgetId);
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		int sprite = widget.getSpriteId();
		if (sprite == client.getItemDefinition(spell.getObj()).getIntValue(PARAM_SPRITE_LIT))
		{
			return true;
		}
		return sprite == client.getItemDefinition(spell.getObj()).getIntValue(PARAM_SPRITE_DIM) ? false : null;
	}

	private String rowLine(RowAvailability row)
	{
		String head = (row.isAvailable() ? "+ " : "- ") + row.getRow().getName()
			+ (row.getRow().getRequirements().getBook() == null ? "" : " [" + row.getRow().getRequirements().getBook() + "]");
		if (row.isAvailable())
		{
			return head + (row.getConfidence() == RowAvailability.Confidence.SURE ? "" : " (" + row.getConfidence() + ")")
				+ " via " + row.getWitness().stream().map(this::use).collect(Collectors.joining(", "));
		}
		return head + ": " + String.join("; ", row.getWhyNot());
	}

	private String use(ItemUse use)
	{
		return use.getQuantity() + " " + name(use.getItemId()) + " (" + use.getContainer().name().toLowerCase() + ")";
	}

	private String charges(PlayerSnapshot s)
	{
		return s.getCharges().entrySet().stream()
			.map(e -> name(e.getKey()) + "=" + e.getValue().getCharges() + " " + source(e.getValue()))
			.collect(Collectors.joining(", ", "[", "]"));
	}

	private static String source(Charge charge)
	{
		return charge.getSource().name().toLowerCase().replace('_', ' ');
	}

	private String names(Map<Integer, Integer> items)
	{
		return items.entrySet().stream().map(e -> e.getValue() + " " + name(e.getKey())).collect(Collectors.joining(", ", "[", "]"));
	}

	private String name(int id)
	{
		return client.getItemDefinition(id).getName();
	}

	private static String tile(WorldPoint p)
	{
		return p == null ? "-" : p.getX() + "," + p.getY() + "," + p.getPlane();
	}

	private static String yes(boolean value)
	{
		return value ? "yes" : "no";
	}
}

package com.cluehelper.dev;

import com.cluehelper.route.Plan;
import com.cluehelper.route.PlanStart;
import com.cluehelper.route.Route;
import com.cluehelper.route.RoutePlanner;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.stream.Collectors;

final class RouteDump
{
	static final String TAG = "[CH-ROUTE]";
	private static final double NANOS_PER_MS = 1_000_000.0;

	private final RoutePlanner routes;

	RouteDump(RoutePlanner routes)
	{
		this.routes = routes;
	}

	void describe(Consumer<String> chat, Consumer<String> logOnly)
	{
		Plan plan = routes.getPlan();
		chat.accept(header(plan));
		summary(plan).forEach(chat);
		candidates(plan).forEach(logOnly);
	}

	String header(Plan plan)
	{
		PlanStart start = routes.getStart();
		return String.format("Plan %s: %d searches, %d labels, %.1f ms (judging %.1f ms); start %s, nearest node %d, start walk %.2f ms%s%s",
			plan.getStepKey(), plan.getSearches(), plan.getLabels(), plan.getSearchNanos() / NANOS_PER_MS,
			plan.getContextNanos() / NANOS_PER_MS, start == null ? "none" : start.getKind(), routes.getNearestNode(),
			routes.getLastWalkNanos() / NANOS_PER_MS, plan.getNote() == null ? "" : "; " + plan.getNote(),
			plan.getRequirementNotes().isEmpty() ? "" : "; needs: " + String.join("; ", plan.getRequirementNotes()));
	}

	List<String> summary(Plan plan)
	{
		List<String> lines = new ArrayList<>();
		line(lines, "Best", plan.getBest());
		line(lines, "Committed", routes.getCommitted() == plan.getBest() ? null : routes.getCommitted());
		line(lines, "Direct", plan.getDirect());
		line(lines, "Same book", plan.getSameBook());
		line(lines, "Faster, under the margin", plan.getFasterUnqualified());
		plan.getAlternatives().forEach(route -> line(lines, "Alt", route));
		return lines;
	}

	List<String> candidates(Plan plan)
	{
		List<String> lines = new ArrayList<>();
		plan.getCandidates().forEach(candidate -> line(lines, "candidate (" + candidate.getCategory() + ")", candidate.getRoute()));
		plan.getProbeTicks().forEach((tile, ticks) ->
			lines.add("probe " + tile.getX() + "," + tile.getY() + "," + tile.getPlane() + " " + ticks + "t"));
		return lines;
	}

	private static String withdraw(Route route)
	{
		if (!route.isBanked())
		{
			return "";
		}
		return " withdraw " + route.getWithdraw().stream().map(use -> String.valueOf(use.getItemId())).collect(Collectors.joining(",", "[", "]"))
			+ (route.getWithdrawInCoreTag().isEmpty() ? "" : " coreTag" + route.getWithdrawInCoreTag())
			+ (route.isDepositFirst() ? " depositFirst" : "") + (route.isPinIncluded() ? " +PIN" : "");
	}

	private static void line(List<String> lines, String label, Route route)
	{
		if (route != null)
		{
			lines.add(label + " " + route.getTicks() + "t (rank " + (route.getRankHalfTicks() + 1) / 2 + ", " + route.getConfidence()
				+ "): " + (route.isOpenBankStart() ? "(open bank) " : "") + route.describe() + " " + route.getSpent()
				+ (route.getEndBook() != route.getStartBook() ? " leaves you on " + route.getEndBook() : "") + withdraw(route));
		}
	}
}

package com.cluehelper.dev;

import com.cluehelper.route.OriginClass;
import com.cluehelper.route.PlanStart;
import com.cluehelper.route.RoutePlanner;
import com.cluehelper.route.WalkCosts;
import com.cluehelper.route.WalkData;
import com.cluehelper.route.WalkTable;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

final class RouteOverlay extends Overlay
{
	private static final Map<Integer, Color> KIND_COLOURS = Map.of(
		WalkTable.KIND_TARGET, Color.MAGENTA,
		WalkTable.KIND_BANK, Color.YELLOW,
		WalkTable.KIND_ORIGIN, Color.CYAN,
		WalkTable.KIND_CHANGE, Color.ORANGE,
		WalkTable.KIND_LANDING, Color.GREEN);
	private static final int[] KIND_ORDER = {WalkTable.KIND_TARGET, WalkTable.KIND_BANK, WalkTable.KIND_ORIGIN,
		WalkTable.KIND_CHANGE, WalkTable.KIND_LANDING};
	private static final Point STATUS_AT = new Point(10, 40);

	private final Client client;
	private final RoutePlanner routes;
	private final WalkData walkData;

	RouteOverlay(Client client, RoutePlanner routes, WalkData walkData)
	{
		this.client = client;
		this.routes = routes;
		this.walkData = walkData;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WalkData.Loaded data = walkData.get().getNow(null);
		PlanStart start = routes.getStart();
		if (data == null || start == null || client.getLocalPlayer() == null)
		{
			return null;
		}
		WalkTable table = data.getTable();
		WalkCosts walk = start.getWalk();
		int plane = client.getTopLevelWorldView().getPlane();
		for (int node = 0; node < table.nodeCount(); node++)
		{
			WorldPoint tile = table.placed(node) != null ? table.placed(node) : table.tile(node);
			LocalPoint local = tile.getPlane() == plane ? LocalPoint.fromWorld(client.getTopLevelWorldView(), tile) : null;
			if (local != null)
			{
				drawNode(graphics, local, node + " " + walk(walk, tile), colour(table, node));
			}
		}
		String origin = start.getTile() == null ? "-" : OriginClass.of(start.getTile(), data.getNoTeleport()).name();
		OverlayUtil.renderTextLocation(graphics, STATUS_AT, "start " + start.getKind() + ", origin " + origin
			+ ", nearest node " + routes.getNearestNode(), Color.WHITE);
		return null;
	}

	private void drawNode(Graphics2D graphics, LocalPoint local, String text, Color colour)
	{
		Polygon poly = Perspective.getCanvasTilePoly(client, local);
		if (poly != null)
		{
			OverlayUtil.renderPolygon(graphics, poly, colour);
		}
		Point at = Perspective.getCanvasTextLocation(client, graphics, local, text, 0);
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, colour);
		}
	}

	private static String walk(WalkCosts walk, WorldPoint tile)
	{
		int cost = walk == null ? WalkCosts.UNREACHED : walk.cost(tile);
		return cost == WalkCosts.UNREACHED ? "-" : String.valueOf(cost);
	}

	private static Color colour(WalkTable table, int node)
	{
		for (int kind : KIND_ORDER)
		{
			if (table.is(node, kind))
			{
				return KIND_COLOURS.get(kind);
			}
		}
		return Color.GRAY;
	}
}

package com.cluehelper.dev;

import java.util.function.Consumer;

public interface SelfTest
{
	String name();

	/**
	 * Starts on the client thread. Must end with {@link SelfTestRun#done()}, from any thread and
	 * possibly later; a test that never calls it fails on the runner's timeout.
	 */
	void run(SelfTestRun run);

	/** Tests run in ascending order, ties in registration order. Tests that restart plugins go last. */
	default int order()
	{
		return 0;
	}

	/** A test whose checks all happen on the client thread, at once. */
	static SelfTest of(String name, Consumer<SelfTestRun> checks)
	{
		return new SelfTest()
		{
			@Override
			public String name()
			{
				return name;
			}

			@Override
			public void run(SelfTestRun run)
			{
				checks.accept(run);
				run.done();
			}
		};
	}
}

package com.cluehelper.dev;

import java.util.ArrayList;
import java.util.List;

public final class SelfTestReport
{
	private int passed;
	private int failed;
	private int skipped;
	private final List<String> failures = new ArrayList<>();

	synchronized void record(String test, boolean ok, String what)
	{
		if (ok)
		{
			passed++;
		}
		else
		{
			failed++;
			failures.add(test + ": " + what);
		}
	}

	synchronized void skip()
	{
		skipped++;
	}

	public synchronized int passed()
	{
		return passed;
	}

	public synchronized int failed()
	{
		return failed;
	}

	public synchronized int skipped()
	{
		return skipped;
	}

	public synchronized List<String> failures()
	{
		return new ArrayList<>(failures);
	}

	@Override
	public synchronized String toString()
	{
		return passed + " passed, " + failed + " failed, " + skipped + " skipped";
	}
}

package com.cluehelper.dev;

/** Safe to use from any thread. */
public interface SelfTestRun
{
	void check(boolean ok, String what);

	/** The test can't run in this state (e.g. logged out); counted apart from passes and failures. */
	void skip(String why);

	void done();
}

package com.cluehelper.dev;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executor;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;

/** A test that throws or never finishes fails, and the run carries on. */
@Slf4j
@Singleton
public class SelfTestRunner
{
	static final String TAG = "[CH-TEST]";
	private static final long TIMEOUT_MS = 15_000;

	private final Executor clientThread;
	private final ScheduledExecutorService scheduler;
	private final long timeoutMs;
	private final List<SelfTest> tests = new CopyOnWriteArrayList<>();
	private final AtomicBoolean running = new AtomicBoolean();

	@Inject
	SelfTestRunner(ClientThread clientThread, ScheduledExecutorService scheduler)
	{
		this(clientThread::invoke, scheduler, TIMEOUT_MS);
	}

	SelfTestRunner(Executor clientThread, ScheduledExecutorService scheduler, long timeoutMs)
	{
		this.clientThread = clientThread;
		this.scheduler = scheduler;
		this.timeoutMs = timeoutMs;
	}

	/** @return an action that unregisters the test again */
	public Runnable register(SelfTest test)
	{
		tests.add(test);
		return () -> tests.remove(test);
	}

	public List<String> testNames()
	{
		List<String> names = new ArrayList<>();
		for (SelfTest test : tests)
		{
			names.add(test.name());
		}
		return names;
	}

	/**
	 * @param onFinished called on the client thread with the totals
	 * @return false, doing nothing, while an earlier run is still going
	 */
	public boolean run(Consumer<SelfTestReport> onFinished)
	{
		if (!running.compareAndSet(false, true))
		{
			return false;
		}
		List<SelfTest> ordered = new ArrayList<>(tests);
		ordered.sort(Comparator.comparingInt(SelfTest::order));
		Deque<SelfTest> queue = new ArrayDeque<>(ordered);
		SelfTestReport report = new SelfTestReport();
		log.info("{} running {} tests", TAG, queue.size());
		clientThread.execute(() -> runNext(queue, report, onFinished));
		return true;
	}

	private void runNext(Deque<SelfTest> queue, SelfTestReport report, Consumer<SelfTestReport> onFinished)
	{
		SelfTest test = queue.poll();
		if (test == null)
		{
			log.info("{} RESULT: {}", TAG, report);
			running.set(false);
			onFinished.accept(report);
			return;
		}
		log.info("{} test: {}", TAG, test.name());
		Run run = new Run(test.name(), report, () -> clientThread.execute(() -> runNext(queue, report, onFinished)));
		run.timeout = scheduler.schedule(run::timeOut, timeoutMs, TimeUnit.MILLISECONDS);
		try
		{
			test.run(run);
		}
		catch (RuntimeException | AssertionError e)
		{
			log.warn("{} {} threw", TAG, test.name(), e);
			run.check(false, "threw " + e);
			run.done();
		}
	}

	private final class Run implements SelfTestRun
	{
		private final String test;
		private final SelfTestReport report;
		private final Runnable next;
		private final AtomicBoolean finished = new AtomicBoolean();
		private final AtomicInteger checks = new AtomicInteger();
		private volatile boolean skipped;
		private volatile ScheduledFuture<?> timeout;

		Run(String test, SelfTestReport report, Runnable next)
		{
			this.test = test;
			this.report = report;
			this.next = next;
		}

		@Override
		public void check(boolean ok, String what)
		{
			if (finished.get())
			{
				log.warn("{} {}: check after the test ended, ignored: {}", TAG, test, what);
				return;
			}
			checks.incrementAndGet();
			report.record(test, ok, what);
			log.info("{} {} {}: {}", TAG, ok ? "PASS" : "FAIL", test, what);
		}

		@Override
		public void skip(String why)
		{
			if (!skipped && !finished.get())
			{
				skipped = true;
				report.skip();
				log.info("{} SKIP {}: {}", TAG, test, why);
			}
		}

		@Override
		public void done()
		{
			if (!finished.compareAndSet(false, true))
			{
				return;
			}
			ScheduledFuture<?> t = timeout;
			if (t != null)
			{
				t.cancel(false);
			}
			if (checks.get() == 0 && !skipped)
			{
				report.record(test, false, "made no checks");
				log.info("{} FAIL {}: made no checks", TAG, test);
			}
			next.run();
		}

		void timeOut()
		{
			if (!finished.get())
			{
				check(false, "timed out after " + timeoutMs + " ms");
				done();
			}
		}
	}
}

package com.cluehelper.dev;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import org.junit.After;
import org.junit.Test;

public class SelfTestRunnerTest
{
	private static final long TIMEOUT_MS = 200;

	private final ScheduledExecutorService scheduler = new ScheduledThreadPoolExecutor(1);
	private final SelfTestRunner runner = new SelfTestRunner(Runnable::run, scheduler, TIMEOUT_MS);

	@After
	public void stopScheduler()
	{
		scheduler.shutdownNow();
	}

	@Test
	public void aFailingThrowingOrHangingTestIsReportedAndTheRunCarriesOn() throws InterruptedException
	{
		List<String> ran = new ArrayList<>();
		runner.register(test("passes", 0, ran, run -> run.check(true, "ok")));
		runner.register(test("fails", 0, ran, run -> run.check(false, "wrong")));
		runner.register(test("skips", 0, ran, run -> run.skip("logged out")));
		runner.register(test("throws", 0, ran, run ->
		{
			throw new IllegalStateException("boom");
		}));
		runner.register(test("hangs", 0, ran, null));
		runner.register(test("runs after the hang", 0, ran, run -> run.check(true, "ok")));

		SelfTestReport report = runToEnd();

		assertEquals(List.of("passes", "fails", "skips", "throws", "hangs", "runs after the hang"), ran);
		assertEquals(2, report.passed());
		assertEquals(1, report.skipped());
		assertEquals(3, report.failed());
		assertTrue(report.failures().get(1).startsWith("throws: threw java.lang.IllegalStateException"));
		assertEquals("hangs: timed out after " + TIMEOUT_MS + " ms", report.failures().get(2));
	}

	@Test
	public void runsInAscendingOrderThenRegistrationOrder() throws InterruptedException
	{
		List<String> ran = new ArrayList<>();
		runner.register(test("last", 1000, ran, run -> run.check(true, "ok")));
		runner.register(test("first", 0, ran, run -> run.check(true, "ok")));
		runner.register(test("second", 0, ran, run -> run.check(true, "ok")));
		runner.register(test("middle", 100, ran, run -> run.check(true, "ok")));

		runToEnd();

		assertEquals(List.of("first", "second", "middle", "last"), ran);
	}

	/** A null body never calls done(), so the runner's timeout has to end it. */
	private static SelfTest test(String name, int order, List<String> ran, Consumer<SelfTestRun> body)
	{
		return new SelfTest()
		{
			@Override
			public String name()
			{
				return name;
			}

			@Override
			public int order()
			{
				return order;
			}

			@Override
			public void run(SelfTestRun run)
			{
				ran.add(name);
				if (body != null)
				{
					body.accept(run);
					run.done();
				}
			}
		};
	}

	private SelfTestReport runToEnd() throws InterruptedException
	{
		AtomicReference<SelfTestReport> result = new AtomicReference<>();
		CountDownLatch finished = new CountDownLatch(1);
		assertTrue(runner.run(report ->
		{
			result.set(report);
			finished.countDown();
		}));
		assertTrue("run finished", finished.await(5, TimeUnit.SECONDS));
		return result.get();
	}
}

package com.cluehelper.dev;

