package com.cluehelper.dev;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * A click is logged with the tick count of the period it happened in, and a server effect (var,
 * animation) with the count of the period before its tick boundary, so "ticks from click to effect"
 * is {@code effectTick + 1 - clickTick}.
 */
final class SpellbookTimingParser
{
	private static final int MAGIC_SPELLBOOK_GROUP = 218;
	private static final int INVENTORY_GROUP = 149;
	private static final int EQUIPMENT_GROUP = 387;
	private static final int GIVE_UP_AFTER_TICKS = 40;
	private static final int ACCEPT_WITHIN_TICKS = 3;
	private static final int RECLICK_TICKS = 10;
	private static final Set<String> BOOK_OPTIONS = new HashSet<>(Arrays.asList("standard", "ancient", "lunar", "arceuus"));
	private static final Set<String> NOT_PART_OF_A_CHANGE = new HashSet<>(Arrays.asList("walk here", "inventory", "magic", "worn equipment", "cancel"));

	static final class Trial
	{
		String method;
		String firstClick;
		int firstClickTick;
		int commitClickTick;
		int clicks;
		int bookChangeTick = -1;
		String bookChange;
		String castClick;
		int castClickTick = -1;
		int acceptTick = -1;
		int castClicksBeforeAccept;
		String refusal;

		boolean changed()
		{
			return bookChangeTick >= 0;
		}

		/** The committing click is a sub-op, a dialogue choice or the op itself. */
		int commitToBook()
		{
			return bookChangeTick + 1 - commitClickTick;
		}

		/** Includes menus and walking. */
		int firstClickToBook()
		{
			return bookChangeTick + 1 - firstClickTick;
		}

		/** Human reaction time: an upper bound on any spell lock after the change. */
		int bookToCastClick()
		{
			return castClickTick < 0 ? -1 : castClickTick - bookChangeTick;
		}

		int castClickToAccept()
		{
			return acceptTick < 0 ? -1 : acceptTick + 1 - castClickTick;
		}

		@Override
		public String toString()
		{
			return method + " '" + firstClick + "' t" + firstClickTick + " commit t" + commitClickTick + " clicks=" + clicks
				+ (changed() ? " book t" + bookChangeTick + " (" + bookChange + ") commit->book=" + commitToBook()
				+ " first->book=" + firstClickToBook() : " NO CHANGE" + (refusal == null ? "" : " '" + refusal + "'"))
				+ (castClickTick < 0 ? "" : " cast '" + castClick + "' t" + castClickTick + " book->castClick=" + bookToCastClick()
				+ " castClick->accept=" + castClickToAccept() + " ignored=" + castClicksBeforeAccept);
		}
	}

	private SpellbookTimingParser()
	{
	}

	static List<Trial> parse(List<JsonObject> events)
	{
		List<Trial> trials = new ArrayList<>();
		Trial open = null;
		Trial awaitingCast = null;
		for (JsonObject e : events)
		{
			String kind = e.get("event").getAsString();
			int t = e.get("t").getAsInt();
			if (open != null && t - open.commitClickTick > GIVE_UP_AFTER_TICKS)
			{
				open = null;
			}
			if (awaitingCast != null && awaitingCast.acceptTick < 0 && awaitingCast.castClickTick >= 0
				&& t - awaitingCast.castClickTick > ACCEPT_WITHIN_TICKS)
			{
				awaitingCast.castClicksBeforeAccept++;
				awaitingCast.castClickTick = -1;
			}
			switch (kind)
			{
				case "click":
				{
					String option = e.get("option").getAsString();
					String method = method(e);
					boolean reclick = method != null && open != null && method.equals(open.method) && t - open.commitClickTick <= RECLICK_TICKS;
					if (method != null && !reclick)
					{
						open = new Trial();
						open.method = method;
						open.firstClick = option + " | " + e.get("target").getAsString();
						open.firstClickTick = t;
						open.commitClickTick = t;
						open.clicks = 1;
						trials.add(open);
						awaitingCast = null;
					}
					else if (open != null && !NOT_PART_OF_A_CHANGE.contains(option.toLowerCase()) && !isCast(e))
					{
						open.commitClickTick = t;
						open.clicks++;
					}
					else if (awaitingCast != null && isCast(e) && awaitingCast.acceptTick < 0)
					{
						if (awaitingCast.castClickTick < 0)
						{
							awaitingCast.castClick = option + " | " + e.get("target").getAsString();
							awaitingCast.castClickTick = t;
						}
					}
					break;
				}
				case "vars":
				{
					if (open != null && bookChanged(e))
					{
						open.bookChangeTick = t;
						open.bookChange = describeBookChange(e);
						awaitingCast = open;
						open = null;
					}
					break;
				}
				case "anim":
				{
					if (awaitingCast != null && awaitingCast.castClickTick >= 0 && awaitingCast.acceptTick < 0
						&& e.get("anim").getAsInt() != -1 && t >= awaitingCast.castClickTick)
					{
						awaitingCast.acceptTick = t;
					}
					break;
				}
				case "chat":
				{
					String message = e.get("message").getAsString();
					if (open != null && isRefusal(message))
					{
						open.refusal = message;
					}
					if (awaitingCast != null && awaitingCast.castClickTick >= 0 && awaitingCast.acceptTick < 0
						&& "GAMEMESSAGE".equals(e.get("type").getAsString()) && t >= awaitingCast.castClickTick)
					{
						awaitingCast.acceptTick = t;
					}
					break;
				}
				default:
					break;
			}
		}
		return trials;
	}

	static String method(JsonObject click)
	{
		String option = click.get("option").getAsString().toLowerCase();
		String target = click.get("target").getAsString().toLowerCase();
		int group = click.has("widgetGroup") ? click.get("widgetGroup").getAsInt() : -1;
		if (target.contains("spellbook swap"))
		{
			return "swap";
		}
		if (target.contains("mounted") && (option.equals("perks") || option.equals("spellbook")))
		{
			return "mountedCape";
		}
		if ((target.contains("magic cape") || target.contains("max cape")) && option.equals("spellbook"))
		{
			return "cape";
		}
		if ((group == INVENTORY_GROUP || group == EQUIPMENT_GROUP) && BOOK_OPTIONS.contains(option))
		{
			return "cape";
		}
		if (target.contains("altar of the occult"))
		{
			return option.equals("venerate") ? "occultVenerate" : BOOK_OPTIONS.contains(option) ? "occultOp" : null;
		}
		if (target.equals("altar") && option.equals("pray"))
		{
			return "astralAltar";
		}
		if (target.equals("altar") && option.equals("pray-at"))
		{
			return "pyramidAltar";
		}
		if (target.startsWith("tyss") && option.equals("spellbook"))
		{
			return "tyss";
		}
		if (target.endsWith("altar") && option.equals("venerate"))
		{
			return "singleAltar";
		}
		return null;
	}

	private static boolean isCast(JsonObject click)
	{
		return click.has("widgetGroup") && click.get("widgetGroup").getAsInt() == MAGIC_SPELLBOOK_GROUP
			&& !click.get("target").getAsString().toLowerCase().contains("spellbook swap");
	}

	private static boolean bookChanged(JsonObject vars)
	{
		JsonObject from = vars.getAsJsonObject("from");
		JsonObject to = vars.getAsJsonObject("to");
		if (!from.has("book4070"))
		{
			return false;
		}
		return !from.get("book4070").equals(to.get("book4070")) || !from.get("swap3617").equals(to.get("swap3617"));
	}

	private static String describeBookChange(JsonObject vars)
	{
		JsonObject from = vars.getAsJsonObject("from");
		JsonObject to = vars.getAsJsonObject("to");
		return "4070 " + from.get("book4070") + "->" + to.get("book4070") + ", 3617 " + from.get("swap3617") + "->" + to.get("swap3617");
	}

	private static boolean isRefusal(String message)
	{
		String m = message.toLowerCase();
		return m.contains("can't") || m.contains("cannot") || m.contains("unable") || m.contains("already") || m.contains("too deep")
			|| m.contains("not able") || m.contains("may only");
	}
}

package com.cluehelper.dev;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;

public class SpellbookTimingParserTest
{
	private static final String RUN1 = "/b04/run1-swap-and-occult.jsonl";
	private static final String RUN2 = "/b04/run2-cape-altars-tyss-wild.jsonl";
	private static final Gson GSON = new Gson();
	/** First-click ticks in run 2 made from a distance (house entry or approach), so walking is in their time. */
	private static final Set<Integer> CLICKED_WHILE_STILL_WALKING_TO_IT = Set.of(1602, 2009);

	@Test
	public void spellbookSwapChangesTheBookFourTicksAfterTheCommittingClick() throws IOException
	{
		List<SpellbookTimingParser.Trial> swaps = changed(RUN1, "swap");
		swaps.addAll(changed(RUN2, "swap"));
		assertEquals(8, swaps.size());
		long fours = swaps.stream().filter(s -> s.commitToBook() == 4).count();
		assertEquals(7, fours);
		assertTrue(swaps.stream().allMatch(s -> s.commitToBook() >= 4 && s.commitToBook() <= 5));
	}

	@Test
	public void oneClickChangesLandOnTheNextTickWhenAlreadyAdjacent() throws IOException
	{
		for (String method : new String[]{"occultOp", "cape", "tyss", "pyramidAltar", "astralAltar"})
		{
			List<SpellbookTimingParser.Trial> trials = changed(RUN2, method).stream()
				.filter(t -> t.clicks == 1 && !CLICKED_WHILE_STILL_WALKING_TO_IT.contains(t.firstClickTick))
				.collect(Collectors.toList());
			assertFalse(method, trials.isEmpty());
			for (SpellbookTimingParser.Trial trial : trials)
			{
				assertTrue(method + " " + trial, trial.commitToBook() >= 1 && trial.commitToBook() <= 3);
			}
			long nextTick = trials.stream().filter(t -> t.commitToBook() == 1).count();
			assertTrue(method + " mostly next tick", nextTick * 2 > trials.size());
		}
	}

	@Test
	public void theFirstSpellClickedAfterAChangeIsAccepted() throws IOException
	{
		List<SpellbookTimingParser.Trial> withCast = new ArrayList<>();
		for (String run : new String[]{RUN1, RUN2})
		{
			parse(run).stream().filter(t -> t.changed() && t.castClickTick >= 0).forEach(withCast::add);
		}
		assertTrue(withCast.size() >= 25);
		for (SpellbookTimingParser.Trial trial : withCast)
		{
			assertEquals(trial.toString(), 0, trial.castClicksBeforeAccept);
			assertTrue(trial.toString(), trial.castClickToAccept() >= 1 && trial.castClickToAccept() <= 3);
		}
	}

	@Test
	public void theSixthCapeChangeIsRefusedWithTheDailyLimitLine() throws IOException
	{
		List<SpellbookTimingParser.Trial> refused = parse(RUN2).stream()
			.filter(t -> t.method.equals("cape") && !t.changed())
			.collect(Collectors.toList());
		assertEquals(1, refused.size());
		assertEquals("You may only switch spellbooks five times per day. Try again tomorrow.", refused.get(0).refusal);
	}

	@Test
	public void capeUsesCountUpOneSharedCounterInVarbit4816() throws IOException
	{
		List<Integer> counts = new ArrayList<>();
		for (JsonObject e : events(RUN2))
		{
			if ("vars".equals(e.get("event").getAsString()) && e.getAsJsonObject("from").has("capeUses4816"))
			{
				int from = e.getAsJsonObject("from").get("capeUses4816").getAsInt();
				int to = e.getAsJsonObject("to").get("capeUses4816").getAsInt();
				if (from != to)
				{
					counts.add(to);
				}
			}
		}
		assertEquals(List.of(1, 2, 3, 4, 5), counts);
	}

	@Test
	public void aSwapRevertsExactly200TicksAfterVarbit3617TurnsOn() throws IOException
	{
		List<Integer> durations = new ArrayList<>();
		for (String run : new String[]{RUN1, RUN2})
		{
			int on = -1;
			for (JsonObject e : events(run))
			{
				if ("vars".equals(e.get("event").getAsString()) && e.getAsJsonObject("from").has("swap3617"))
				{
					int from = e.getAsJsonObject("from").get("swap3617").getAsInt();
					int to = e.getAsJsonObject("to").get("swap3617").getAsInt();
					if (from == 0 && to == 1)
					{
						on = e.get("t").getAsInt();
					}
					else if (from == 1 && to == 0 && on >= 0)
					{
						durations.add(e.get("t").getAsInt() - on);
						on = -1;
					}
				}
			}
		}
		assertTrue(durations.contains(200));
		assertEquals(2, durations.stream().filter(d -> d == 200).count());
	}

	@Test
	public void swapBookVarbit4823NeverMoved() throws IOException
	{
		for (String run : new String[]{RUN1, RUN2})
		{
			for (JsonObject e : events(run))
			{
				if ("vars".equals(e.get("event").getAsString()) && e.getAsJsonObject("to").has("swapBook4823"))
				{
					assertEquals(run + " t" + e.get("t"), 0, e.getAsJsonObject("to").get("swapBook4823").getAsInt());
				}
			}
		}
	}

	private static List<SpellbookTimingParser.Trial> changed(String run, String method) throws IOException
	{
		return parse(run).stream().filter(t -> t.method.equals(method) && t.changed()).collect(Collectors.toList());
	}

	private static List<SpellbookTimingParser.Trial> parse(String run) throws IOException
	{
		return SpellbookTimingParser.parse(events(run));
	}

	private static List<JsonObject> events(String resource) throws IOException
	{
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(
			SpellbookTimingParserTest.class.getResourceAsStream(resource), StandardCharsets.UTF_8)))
		{
			return reader.lines().map(line -> GSON.fromJson(line, JsonObject.class)).collect(Collectors.toList());
		}
	}
}

package com.cluehelper.dev;

import com.cluehelper.link.ClueLink;
import com.cluehelper.link.StepChange;
import com.cluehelper.step.CoreClueReader;
import com.cluehelper.step.Step;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;

/**
 * Fixture lines use the replay fixtures' format, so a clue type the fixtures lack can be cut from the
 * log into src/test/resources.
 */
final class StepDump
{
	static final String TAG = "[CH-STEP]";
	private static final int SHOWN_TARGETS = 6;
	private static final int SHOWN_TEXT = 140;

	private final ClueLink link;
	private final Gson gson;

	StepDump(ClueLink link, Gson gson)
	{
		this.link = link;
		this.gson = gson;
	}

	void describe(Consumer<String> reply)
	{
		Step step = link.getCurrentStep();
		if (step == null)
		{
			reply.accept("No step (core active " + link.isActive() + ", needs read " + link.needsRead() + ")");
			return;
		}
		lines(step).forEach(reply);
	}

	/** Client thread only. */
	String fixtureLine(int tick, StepChange change, Step step)
	{
		JsonObject event = new JsonObject();
		event.addProperty("t", tick);
		event.addProperty("event", "clue");
		event.addProperty("change", change.name());
		ClueScroll clue = link.coreClue();
		if (step != null && clue != null && link.getCore() != null)
		{
			event.addProperty("class", clue.getClass().getSimpleName());
			JsonObject fields = gson.toJsonTree(CoreClueReader.facts(clue, link.getCore())).getAsJsonObject();
			JsonArray targets = new JsonArray();
			for (WorldPoint point : step.getTargets())
			{
				targets.add(gson.toJsonTree(new int[]{point.getX(), point.getY(), point.getPlane()}));
			}
			fields.add("targets", targets);
			fields.add("npcs", gson.toJsonTree(step.getNpcs()));
			event.add("fields", fields);
			event.addProperty("key", step.getKey());
		}
		return TAG + " fixture " + gson.toJson(event);
	}

	static List<String> lines(Step step)
	{
		List<String> lines = new ArrayList<>();
		lines.add("Step " + step.getKey());
		lines.add(step.getType() + ", " + step.getTier() + ", " + step.getKind()
			+ (step.isKnown() ? ", rows " + step.getCacheRows() : ", no step data"));
		lines.add("Targets (" + step.getTargets().size() + "): " + tiles(step.getTargets()));
		if (!step.getNpcs().isEmpty())
		{
			lines.add("NPCs: " + String.join(", ", step.getNpcs()) + (step.getRegions().isEmpty() ? "" : " in regions " + step.getRegions()));
		}
		if (!step.getObjectIds().isEmpty() || !step.getObjectNames().isEmpty())
		{
			lines.add("Objects: " + step.getObjectIds() + " " + step.getObjectNames());
		}
		lines.add("Needs: " + step.getRequirements());
		String text = step.getText() == null ? "" : step.getText();
		lines.add("Text: " + (text.length() > SHOWN_TEXT ? text.substring(0, SHOWN_TEXT) + "…" : text));
		return lines;
	}

	private static String tiles(List<WorldPoint> points)
	{
		String shown = points.stream().limit(SHOWN_TARGETS)
			.map(p -> p.getX() + "," + p.getY() + "," + p.getPlane())
			.collect(Collectors.joining("; "));
		return points.size() > SHOWN_TARGETS ? shown + "; +" + (points.size() - SHOWN_TARGETS) + " more" : shown;
	}
}

package com.cluehelper.dev;

import java.util.ArrayList;
import java.util.List;

/** Oldest entry first. Stored as JSON in the profile, so field names are persisted keys. */
public final class StepLog
{
	private List<Entry> entries = new ArrayList<>();

	public List<Entry> entries()
	{
		if (entries == null)
		{
			entries = new ArrayList<>();
		}
		return entries;
	}

	/**
	 * ClueLink reports a re-read, a pick-up or a core re-enable as a new step, but for step
	 * frequencies it is the same step again.
	 */
	boolean endsWith(String key)
	{
		List<Entry> list = entries();
		return !list.isEmpty() && list.get(list.size() - 1).getKey().equals(key);
	}

	void append(Entry entry, int maxEntries)
	{
		List<Entry> list = entries();
		list.add(entry);
		if (list.size() > maxEntries)
		{
			list.subList(0, list.size() - maxEntries).clear();
		}
	}

	public static final class Entry
	{
		private final String tier;
		private final String type;
		private final String key;
		private final long epochSecond;

		Entry(String tier, String type, String key, long epochSecond)
		{
			this.tier = tier;
			this.type = type;
			this.key = key;
			this.epochSecond = epochSecond;
		}

		public String getTier()
		{
			return tier;
		}

		public String getType()
		{
			return type;
		}

		public String getKey()
		{
			return key;
		}

		public long getEpochSecond()
		{
			return epochSecond;
		}

		@Override
		public String toString()
		{
			return tier + " " + type + " " + key;
		}
	}
}

package com.cluehelper.dev;

import com.cluehelper.memory.MemorySlot;
import com.cluehelper.memory.MemoryStore;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Collects step frequencies to weight loadouts later. Records only while enabled, which is developer mode. */
@Singleton
public class StepLogger
{
	static final String KEY = "devStepLog";
	/** Over 150 steps per tier many times over, while keeping the profile's config small. */
	private static final int MAX_ENTRIES = 5000;

	private final MemorySlot<StepLog> slot;
	private volatile boolean enabled;

	@Inject
	StepLogger(MemoryStore memory)
	{
		this.slot = memory.slot(KEY, StepLog.class, StepLog::new);
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	public synchronized void record(String tier, String type, String key)
	{
		if (!enabled)
		{
			return;
		}
		StepLog log = slot.get();
		if (log.endsWith(key))
		{
			return;
		}
		log.append(new StepLog.Entry(tier, type, key, Instant.now().getEpochSecond()), MAX_ENTRIES);
		slot.set(log);
	}

	public synchronized List<StepLog.Entry> entries()
	{
		return new ArrayList<>(slot.get().entries());
	}

	public synchronized void clear()
	{
		slot.clear();
	}
}

package com.cluehelper.dev;

import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(name = "UI Watchdog", description = "Dev only: logs UI-thread freezes with a stack trace")
public class UiWatchdogPlugin extends Plugin
{
	/** Longer than this is a visible freeze. */
	private static final long STALL_MS = 250;

	private volatile boolean watching;

	@Override
	protected void startUp()
	{
		watching = true;
		Thread t = new Thread(this::watch, "ui-watchdog");
		t.setDaemon(true);
		t.start();
	}

	@Override
	protected void shutDown()
	{
		watching = false;
	}

	private void watch()
	{
		while (watching)
		{
			AtomicBoolean done = new AtomicBoolean();
			long sent = System.nanoTime();
			SwingUtilities.invokeLater(() -> done.set(true));
			boolean reported = false;
			while (!done.get() && watching)
			{
				sleep(20);
				if (!reported && (System.nanoTime() - sent) / 1_000_000 > STALL_MS)
				{
					reported = true;
					log.warn("[CH-WATCHDOG] UI thread stalled >{}ms; it is in:{}", STALL_MS, swingStack());
				}
			}
			if (reported)
			{
				log.warn("[CH-WATCHDOG] UI thread stall ended after {} ms", (System.nanoTime() - sent) / 1_000_000);
			}
			sleep(100);
		}
	}

	private static String swingStack()
	{
		StringBuilder trace = new StringBuilder();
		for (Map.Entry<Thread, StackTraceElement[]> e : Thread.getAllStackTraces().entrySet())
		{
			if (e.getKey().getName().startsWith("AWT-EventQueue"))
			{
				for (int i = 0; i < Math.min(30, e.getValue().length); i++)
				{
					trace.append(System.lineSeparator()).append("\t    at ").append(e.getValue()[i]);
				}
			}
		}
		return trace.toString();
	}

	private static void sleep(long ms)
	{
		try
		{
			Thread.sleep(ms);
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
		}
	}
}

