package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.cluehelper.step.StepIndex;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.GZIPInputStream;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * The live run's plans (recorded by the dev client's HotColdTrace with every probe they weighed) planned again: the
 * same readings and probes must give the same action and tile.
 */
public class HotColdDecisionReplayTest
{
	@Test
	public void liveDecisionsReplay() throws IOException
	{
		Gson gson = new Gson();
		StepIndex index = StepIndex.read(gson);
		List<String> differences = new ArrayList<>();
		int decisions = 0;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(new GZIPInputStream(
			HotColdDecisionReplayTest.class.getResourceAsStream("/b19/decisions.jsonl.gz")), StandardCharsets.UTF_8)))
		{
			for (String line = in.readLine(); line != null; line = in.readLine())
			{
				JsonObject recorded = gson.fromJson(line, JsonObject.class);
				HotColdTier tier = recorded.get("beginner").getAsBoolean() ? HotColdTier.BEGINNER : HotColdTier.MASTER;
				List<Reading> readings = Arrays.asList(gson.fromJson(recorded.get("readings"), Reading[].class));
				ProbePlanner.Costs costs = ProbePlanner.Costs.builder()
					.wildernessPenaltyTicks(recorded.get("wildernessPenaltyTicks").getAsInt()).build();
				HotColdPlan plan = ProbeJob.decide(recorded.get("stepKey").getAsString(), Spots.of(index, tier), tier, readings,
					probes(recorded.getAsJsonArray("probes")), costs);
				String expected = recorded.get("action").getAsString() + " " + tile(recorded.getAsJsonArray("tile"));
				String replayed = plan.getAction() + " " + plan.getTile();
				if (!expected.equals(replayed))
				{
					differences.add(readings.size() + " readings: live " + expected + ", replay " + replayed);
				}
				decisions++;
			}
		}
		assertTrue("a live run's decisions are recorded", decisions > 0);
		assertEquals(List.of(), differences);
	}

	private static List<Probe> probes(JsonArray recorded)
	{
		List<Probe> probes = new ArrayList<>();
		for (int i = 0; i < recorded.size(); i++)
		{
			JsonObject probe = recorded.get(i).getAsJsonObject();
			probes.add(new Probe(tile(probe.getAsJsonObject("tile")), Probe.Kind.valueOf(probe.get("kind").getAsString()),
				probe.get("ticks").getAsInt(), probe.get("rankTicks").getAsInt(), probe.get("wilderness").getAsBoolean()));
		}
		return probes;
	}

	private static WorldPoint tile(JsonObject tile)
	{
		return new WorldPoint(tile.get("x").getAsInt(), tile.get("y").getAsInt(), tile.get("plane").getAsInt());
	}

	private static WorldPoint tile(JsonArray tile)
	{
		return tile == null ? null : new WorldPoint(tile.get(0).getAsInt(), tile.get(1).getAsInt(), tile.get(2).getAsInt());
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.cluehelper.step.StepIndex;
import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdLocation;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdSolver;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdTemperature;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdTemperatureChange;
import org.junit.Test;

/**
 * A recorded run, both tiers: a reading's tile from 3544, the logs across logins (each one a round trip through
 * the stored JSON) and a new step, a run and a walk across an edge. The true spot must stay in every grid, exactly.
 * Core's solver runs alongside on the same tiles, to count where our grid keeps a spot core has dropped.
 */
public class HotColdReplayTest
{
	private static final Map<String, String> TRUE_SPOT = Map.of("beginner", "NORTHEAST_OF_AL_KHARID_MINE", "master", "WILDERNESS_49");
	private static final Map<String, String> STEP_KEY = Map.of("beginner", "hotcold:beginner:reldo", "master", "hotcold:master:jorral");

	@Test
	public void recordedRunKeepsTheTrueSpotInEveryGrid() throws IOException
	{
		Gson gson = new Gson();
		StepIndex index = StepIndex.read(gson);
		FeelLogs logs = new FeelLogs();
		int readings = 0;
		int otherLines = 0;
		int coreDropped = 0;
		HotColdSolver core = null;
		List<String> firstReadings = new ArrayList<>();
		for (String[] row : rows())
		{
			String tier = row[2];
			if (row[1].equals("login"))
			{
				logs = gson.fromJson(gson.toJson(logs), FeelLogs.class);
				continue;
			}
			if (!row[1].equals("feel"))
			{
				continue;
			}
			DeviceLine line = DeviceLine.parse(row[6]);
			assertNotNull("every device line parses: " + row[6], line);
			if (line.getKind() != DeviceLine.Kind.READING)
			{
				otherLines++;
				continue;
			}
			readings++;
			int coord = Integer.parseInt(row[3]);
			String key = STEP_KEY.get(tier);
			logs = logs.with(key, new Reading(coord >> 14 & 0x3FFF, coord & 0x3FFF, coord >> 28 & 3, line.getBand(), line.getComparison()));
			List<Reading> log = logs.get(key);
			if (log.size() == 1)
			{
				firstReadings.add(row[0]);
				core = coreSolver(tier.equals("beginner"));
			}
			Reading last = log.get(log.size() - 1);
			core.signal(new WorldPoint(last.getX(), last.getY(), last.getPlane()), HotColdTemperature.getFromTemperatureSet(
				tier.equals("beginner") ? HotColdTemperature.BEGINNER_HOT_COLD_TEMPERATURES : HotColdTemperature.MASTER_HOT_COLD_TEMPERATURES,
				row[6]), HotColdTemperatureChange.of(row[6]));
			Hypotheses grid = Hypotheses.filter(Spots.of(index, HotColdTier.of(tier)), HotColdTier.of(tier), log);
			assertTrue("tick " + row[0] + ": every reading fits the true spot", grid.isExact());
			assertTrue("tick " + row[0] + ": the true spot is kept", grid.spotShares().containsKey(TRUE_SPOT.get(tier)));
			Set<String> coreSpots = new HashSet<>();
			core.getPossibleLocations().forEach(location -> coreSpots.add(location.name()));
			if (!coreSpots.containsAll(grid.spotShares().keySet()))
			{
				coreDropped++;
			}
		}
		assertEquals(104, readings);
		assertEquals(17, otherLines);
		assertEquals("a log starts at the session's first beginner reading and at the master's first", List.of("19", "3259"), firstReadings);
		System.out.println("Replay: " + readings + " readings; our grid kept a spot core had dropped after " + coreDropped);
	}

	/** Core's own solver, fed the exact tile; it never resets on a re-read here. */
	private static HotColdSolver coreSolver(boolean beginner)
	{
		Set<HotColdLocation> spots = new HashSet<>();
		for (HotColdLocation location : HotColdLocation.values())
		{
			if (location.isBeginnerClue() == beginner)
			{
				spots.add(location);
			}
		}
		return new HotColdSolver(spots);
	}

	private static List<String[]> rows() throws IOException
	{
		List<String[]> rows = new ArrayList<>();
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			HotColdReplayTest.class.getResourceAsStream("/b18/feels.tsv"), StandardCharsets.UTF_8)))
		{
			for (String line = in.readLine(); line != null; line = in.readLine())
			{
				if (!line.startsWith("#"))
				{
					rows.add(Arrays.copyOf(line.split("\t", -1), 7));
				}
			}
		}
		return rows;
	}
}

package com.cluehelper.hotcold;

import com.cluehelper.step.HotColdTier;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.cluehelper.route.WalkTable;
import com.cluehelper.step.StepIndex;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdLocation;
import org.junit.Test;

/**
 * A simulation on the live planner's own rules: every spot solved from the tier's NPC, the truth on core's centre
 * (the disputed spots then sit k tiles off the cache's), with crude costs: any walk-table node 10 ticks away,
 * scene tiles at a run's pace. Counts feels until a dig and ticks until the dig tile; a dig on the wrong spot or no
 * decision is a failure.
 */
public class HotColdSimulationTest
{
	private static final WorldPoint RELDO = new WorldPoint(3211, 3494, 0);
	private static final WorldPoint JORRAL = new WorldPoint(2436, 3347, 0);
	private static final int LANDING_TICKS = 10;
	private static final int LOCAL_TILES = 32;
	private static final int LOCAL_STRIDE = 4;
	private static final int MOST_FEELS = 12;
	/** Regression bounds, a little above this planner's numbers on 2026-10-21: beginner 1.80, master 4.15. */
	private static final double BEGINNER_MEAN_FEELS = 2.0;
	private static final double MASTER_MEAN_FEELS = 4.3;
	private static final Path OUT = Paths.get("build/hotcold/simulation.tsv");

	@Test
	public void everySpotIsSolvedWithFewFeels() throws IOException
	{
		StepIndex index = StepIndex.read(new Gson());
		List<WorldPoint> landings = landings();
		List<String> rows = new ArrayList<>();
		rows.add("tier\tspot\tfeels\tticks\tresult");
		double beginner = meanFeels(true, RELDO, index, landings, rows);
		double master = meanFeels(false, JORRAL, index, landings, rows);
		Files.createDirectories(OUT.getParent());
		Files.write(OUT, rows, StandardCharsets.UTF_8);
		System.out.printf(Locale.ROOT, "hot/cold simulation: beginner %.2f feels, master %.2f feels (%s)%n", beginner, master, OUT);
		assertTrue("beginner mean feels " + beginner, beginner <= BEGINNER_MEAN_FEELS);
		assertTrue("master mean feels " + master, master <= MASTER_MEAN_FEELS);
	}

	private static double meanFeels(boolean beginner, WorldPoint start, StepIndex index, List<WorldPoint> landings, List<String> rows)
	{
		HotColdTier tier = beginner ? HotColdTier.BEGINNER : HotColdTier.MASTER;
		List<Spot> spots = Spots.of(index, tier);
		ProbePlanner.Costs costs = ProbePlanner.Costs.builder()
			.wildernessPenaltyTicks(HotColdService.WILDERNESS_PENALTY_TICKS).build();
		int total = 0;
		List<String> failures = new ArrayList<>();
		for (HotColdLocation truth : HotColdLocation.values())
		{
			if (truth.isBeginnerClue() != beginner)
			{
				continue;
			}
			int[] result = solve(truth, tier, start, spots, landings, costs);
			total += result[0];
			String outcome = result[2] == 1 ? "dug" : "FAILED";
			rows.add((beginner ? "beginner" : "master") + "\t" + truth.name() + "\t" + result[0] + "\t" + result[1] + "\t" + outcome);
			if (result[2] != 1)
			{
				failures.add(truth.name());
			}
		}
		assertEquals("spots not solved", List.of(), failures);
		return (double) total / spots.size();
	}

	/** @return feels, ticks, 1 when the dig found the spot */
	private static int[] solve(HotColdLocation truth, HotColdTier tier, WorldPoint start, List<Spot> spots, List<WorldPoint> landings,
		ProbePlanner.Costs costs)
	{
		WorldPoint centre = truth.getWorldPoint();
		List<Reading> readings = new ArrayList<>();
		WorldPoint at = start;
		int ticks = 0;
		for (int feels = 0; feels <= MOST_FEELS; feels++)
		{
			HotColdPlan plan = ProbeJob.decide("sim", spots, tier, readings, probes(at, landings), costs);
			if (plan.isDig())
			{
				boolean found = plan.getTile().distanceTo2D(centre) <= Band.digRadius(tier);
				int digTrip = Math.min((at.distanceTo2D(plan.getTile()) + 1) / 2, LANDING_TICKS);
				return new int[]{feels, ticks + digTrip, found ? 1 : 0};
			}
			if (plan.getAction() != HotColdPlan.Action.FEEL || feels == MOST_FEELS)
			{
				return new int[]{feels, ticks, 0};
			}
			Probe probe = plan.getChoice().getProbe();
			ticks += probe.getTicks() + ProbePlanner.FEEL_TICKS;
			at = probe.getTile();
			readings.add(feel(at, centre, tier, readings));
		}
		return new int[]{MOST_FEELS, ticks, 0};
	}

	private static Reading feel(WorldPoint at, WorldPoint centre, HotColdTier tier, List<Reading> before)
	{
		int distance = at.distanceTo2D(centre);
		Band band = Band.of(distance, tier);
		Reading previous = before.isEmpty() ? null : before.get(before.size() - 1);
		Comparison comparison = previous == null || band == Band.SHAKING ? null
			: Comparison.of(distance, new WorldPoint(previous.getX(), previous.getY(), 0).distanceTo2D(centre));
		return new Reading(at.getX(), at.getY(), at.getPlane(), band, comparison);
	}

	private static List<Probe> probes(WorldPoint at, List<WorldPoint> landings)
	{
		List<Probe> probes = new ArrayList<>();
		probes.add(new Probe(at, Probe.Kind.HERE, 0, 0, false));
		for (int dx = -LOCAL_TILES; dx <= LOCAL_TILES; dx += LOCAL_STRIDE)
		{
			for (int dy = -LOCAL_TILES; dy <= LOCAL_TILES; dy += LOCAL_STRIDE)
			{
				int ticks = (Math.max(Math.abs(dx), Math.abs(dy)) + 1) / 2;
				if (ticks > 0)
				{
					probes.add(new Probe(new WorldPoint(at.getX() + dx, at.getY() + dy, 0), Probe.Kind.LOCAL, ticks, ticks, false));
				}
			}
		}
		for (WorldPoint landing : landings)
		{
			probes.add(new Probe(landing, Probe.Kind.LANDING, LANDING_TICKS, LANDING_TICKS, false));
		}
		return probes;
	}

	private static List<WorldPoint> landings() throws IOException
	{
		WalkTable table = WalkTable.load();
		List<WorldPoint> tiles = new ArrayList<>();
		for (int node = 0; node < table.nodeCount(); node++)
		{
			WorldPoint tile = table.tile(node);
			if (tile != null && tile.getPlane() == 0 && tile.getY() < 4500)
			{
				tiles.add(tile);
			}
		}
		return tiles;
	}
}

