	public void dialogueIdentifiedCluesChangeBetweenPriorityZeroAndMinusOne() throws IOException
	{
		List<JsonObject> changedBetween = events(RUN1, "chat").stream()
			.filter(e -> e.get("coreChangedBetween").getAsBoolean())
			.collect(Collectors.toList());
		assertEquals(2, changedBetween.size());
		for (JsonObject e : changedBetween)
		{
			assertEquals("DIALOG", e.get("type").getAsString());
			assertTrue(e.get("atPriority0").getAsString().startsWith("CrypticClue@"));
			assertTrue(e.get("atPriorityMinus1").getAsString().startsWith("SkillChallengeClue@"));
		}
	}

	private static final class Replay
	{
		final List<String> changes = new ArrayList<>();
		final List<String> activeMismatches = new ArrayList<>();
		final List<Integer> readPromptStarts = new ArrayList<>();
	}

	/**
	 * Each tick's recorded events first, then one tick read: the probe logged clue reads at GameTick -1, and only on a
	 * change.
	 */
	private static Replay replay(String resource) throws IOException
	{
		List<JsonObject> all = allEvents(resource);
		Replay replay = new Replay();
		LinkState state = new LinkState();
		boolean coreActive = false;
		String key = null;
		Object targets = null;
		boolean holdsClue = false;
		boolean neededRead = false;
		int lastTick = all.get(all.size() - 1).get("t").getAsInt();
		int next = 0;
		for (int tick = 0; tick <= lastTick; tick++)
		{
			for (; next < all.size() && all.get(next).get("t").getAsInt() == tick; next++)
			{
				JsonObject e = all.get(next);
				switch (e.get("event").getAsString())
				{
					case "start":
						coreActive = recordedActive(e.get("coreState").getAsString());
						state.start(coreActive);
						break;
					case "pluginChanged":
						if (e.get("plugin").getAsString().equals("ClueScrollPlugin"))
						{
							state.onPluginChanged(e.get("loaded").getAsBoolean());
						}
						break;
					case "coreState":
						coreActive = recordedActive(e.get("to").getAsString());
						break;
					case "inventory":
						holdsClue = !e.get("clueItems").getAsString().isEmpty();
						break;
					case "clue":
						key = e.has("key") ? e.get("key").getAsString() : null;
						targets = e.has("fields") ? e.getAsJsonObject("fields").get("targets") : null;
						break;
					default:
						break;
				}
				if (e.has("coreState") && state.isActive() != recordedActive(e.get("coreState").getAsString()))
				{
					replay.activeMismatches.add("t" + tick + " " + e.get("event").getAsString() + ": " + state.isActive());
				}
			}
			StepChange change = state.tick(coreActive, key, targets, holdsClue);
			if (change == StepChange.NEW)
			{
				replay.changes.add("NEW " + key);
			}
			else if (change != StepChange.UNCHANGED)
			{
				replay.changes.add(change.name());
			}
			if (state.needsRead() && !neededRead)
			{
				replay.readPromptStarts.add(tick);
			}
			neededRead = state.needsRead();
		}
		return replay;
	}

	private static boolean recordedActive(String coreState)
	{
		return coreState.startsWith("active=true");
	}

	private static int identityAt(List<JsonObject> clues, int tick)
	{
		return clues.stream().filter(e -> e.get("t").getAsInt() == tick).findFirst()
			.orElseThrow(() -> new AssertionError("no clue event at t" + tick))
			.get("identity").getAsInt();
	}

	private static List<JsonObject> events(String resource, String kind) throws IOException
	{
		return allEvents(resource).stream().filter(e -> e.get("event").getAsString().equals(kind)).collect(Collectors.toList());
	}

	private static List<JsonObject> allEvents(String resource) throws IOException
	{
		List<JsonObject> events = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(
			CoreLinkFixtureTest.class.getResourceAsStream(resource), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				events.add(GSON.fromJson(line, JsonObject.class));
			}
		}
		return events;
	}
}

package com.cluehelper.memory;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;

public final class FakeProfileConfig implements ProfileConfig
{
	private final Map<String, Map<String, String>> profiles = new HashMap<>();
	private String profileKey;

	public MemoryStore newStore()
	{
		return new MemoryStore(this, new Gson());
	}

	public void logIn(String profile)
	{
		profileKey = profile;
	}

	public void logOut()
	{
		profileKey = null;
	}

	public Map<String, String> values(String profile)
	{
		return profiles.computeIfAbsent(profile, p -> new HashMap<>());
	}

	@Override
	public String profileKey()
	{
		return profileKey;
	}

	@Override
	public String get(String key)
	{
		return profileKey == null ? null : values(profileKey).get(key);
	}

	@Override
	public void set(String key, String value)
	{
		if (profileKey == null)
		{
			throw new IllegalStateException("write without a profile: " + key);
		}
		values(profileKey).put(key, value);
	}

	@Override
	public void unset(String key)
	{
		if (profileKey != null)
		{
			values(profileKey).remove(key);
		}
	}
}

package com.cluehelper.memory;

import static org.junit.Assert.assertEquals;

import java.util.Map;
import org.junit.Test;

public class LateDepositsTest
{
	private static final int MAX_CAPE = 13280;
	private static final int COINS = 995;

	@Test
	public void depositWithoutBankUpdateCountsOnceAndOnlyAfterAClick()
	{
		assertEquals("walked off before the bank update", Map.of(MAX_CAPE, 1), run(true, false, false));
		assertEquals("bank update after the inventory's", Map.of(), run(true, true, false));
		assertEquals("bank update before the inventory's", Map.of(), run(true, false, true));
		assertEquals("no Deposit click: eaten, dropped or worn", Map.of(), run(false, false, false));
	}

	private static Map<Integer, Integer> run(boolean clicked, boolean bankAfter, boolean bankBefore)
	{
		LateDeposits deposits = new LateDeposits();
		deposits.onCarried(Map.of(MAX_CAPE, 1, COINS, 100), 10);
		if (clicked)
		{
			deposits.onDepositClicked(10);
		}
		if (bankBefore)
		{
			deposits.onBankSeen(11);
		}
		deposits.onCarried(Map.of(COINS, 100), 11);
		if (bankAfter)
		{
			deposits.onBankSeen(11);
		}
		Map<Integer, Integer> first = deposits.onTick();
		assertEquals("released twice", Map.of(), deposits.onTick());
		return first;
	}
}

package com.cluehelper.memory;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class MemoryStoreTest
{
	public static final class Bank
	{
		List<Integer> items = new ArrayList<>();
		long seenAt;
	}

	private final FakeProfileConfig profile = new FakeProfileConfig();
	private final MemoryStore store = profile.newStore();
	private final MemorySlot<Bank> bank = store.slot("bank", Bank.class, Bank::new);

	@Test
	public void roundTripsAValueThroughTheProfileConfig()
	{
		profile.logIn("main");
		Bank saved = new Bank();
		saved.items.add(995);
		saved.seenAt = 42;
		bank.set(saved);

		store.reload();
		Bank loaded = bank.get();

		assertEquals(List.of(995), loaded.items);
		assertEquals(42, loaded.seenAt);
		assertTrue(profile.values("main").get("bank").contains("995"));
	}

	@Test
	public void beforeLoginNothingIsReadOrWritten()
	{
		assertFalse(store.hasProfile());
		Bank early = bank.get();
		early.items.add(1);
		bank.set(early);
		assertTrue(profile.values("main").isEmpty());

		profile.logIn("main");
		assertTrue("the pre-login value isn't the profile's", bank.get().items.isEmpty());
	}

	@Test
	public void eachProfileKeepsItsOwnValue()
	{
		profile.logIn("main");
		Bank main = new Bank();
		main.seenAt = 1;
		bank.set(main);

		profile.logIn("ironman");
		store.reload();
		assertEquals(0, bank.get().seenAt);

		profile.logIn("main");
		assertEquals("a profile switch without the event still reloads", 1, bank.get().seenAt);
	}

	@Test
	public void unreadableJsonStartsFresh()
	{
		profile.logIn("main");
		profile.values("main").put("bank", "{not json");
		assertTrue(bank.get().items.isEmpty());
	}

	@Test
	public void clearRemovesTheStoredValue()
	{
		profile.logIn("main");
		MemorySlot<String> note = store.slot("note", String.class, () -> null);
		note.set("x");
		note.clear();
		store.reload();
		assertNull(note.get());
		assertFalse(profile.values("main").containsKey("note"));
	}
}

