	/** Families whose item id encodes the charges; the rest stay unknown. */
	private static final Map<String, Integer> CHARGES = Map.of("Amulet of glory", 4, "Burning amulet", 5, "Combat bracelet", 6,
		"Digsite pendant", 5, "Games necklace", 8, "Necklace of passage", 5, "Ring of dueling", 8, "Ring of wealth", 5,
		"Skills necklace", 6, "Slayer ring", 8);
	private static final int RUNE_STACK = 1000;
	private static final List<Integer> RUNES = List.of(ItemID.AIRRUNE, ItemID.WATERRUNE, ItemID.EARTHRUNE, ItemID.FIRERUNE,
		ItemID.MINDRUNE, ItemID.BODYRUNE, ItemID.COSMICRUNE, ItemID.CHAOSRUNE, ItemID.NATURERUNE, ItemID.LAWRUNE,
		ItemID.DEATHRUNE, ItemID.ASTRALRUNE, ItemID.BLOODRUNE, ItemID.SOULRUNE, ItemID.WRATHRUNE);
	private static final Map<String, AccountType> ACCOUNT_TYPES = Map.of("mid-ironman", AccountType.IRONMAN, "uim", AccountType.ULTIMATE_IRONMAN,
		"hcim", AccountType.HARDCORE_IRONMAN, "gim", AccountType.GROUP_IRONMAN);
	private static final int MAX_QUEST_POINTS = 300;
	/** Runes are taken to sit in a rune pouch, so only the carried items fill slots. */
	private static final int INVENTORY_SLOTS = 28;
	private static final int BANKED_TABLETS = 5;
	private static final int NEXUS_SLOTS = 41;

	private Loadouts()
	{
	}

	@Value
	public static class Loadout
	{
		String name;
		PlayerSnapshot carried;
		List<Integer> banked;
		PlayerSnapshot bankedSnapshot;
		JsonObject fixture;
	}

	public static Loadout load(String name)
	{
		JsonObject f = read(name);
		Map<Integer, Integer> inventory = new HashMap<>();
		Map<Integer, Charge> charges = new HashMap<>();
		for (JsonElement item : array(f, "carried"))
		{
			int id = itemId(item.getAsString());
			inventory.merge(id, 1, Integer::sum);
			Integer known = CHARGES.get(item.getAsString());
			if (known != null)
			{
				charges.put(id, new Charge(known, Charge.Source.ITEM_ID));
			}
		}
		if (f.get("runes").getAsBoolean())
		{
			RUNES.forEach(rune -> inventory.put(rune, RUNE_STACK));
		}
		List<String> bankedFamilies = new ArrayList<>();
		array(f, "banked").forEach(item -> bankedFamilies.add(item.getAsString()));
		if (f.get("banked").isJsonPrimitive() && "*".equals(f.get("banked").getAsString()))
		{
			ITEMS.keySet().stream().filter(family -> !inventory.containsKey(ITEMS.get(family))).sorted().forEach(bankedFamilies::add);
		}
		List<Integer> banked = new ArrayList<>();
		bankedFamilies.forEach(family -> banked.add(itemId(family)));
		int carriedItems = f.getAsJsonArray("carried").size();

		Map<Skill, Integer> levels = levels(f.getAsJsonObject("skills"));
		Map<Quest, QuestState> quests = quests(f.get("quests"));
		JsonObject vars = f.getAsJsonObject("vars");
		Map<Integer, Integer> values = new HashMap<>();
		vars.getAsJsonObject("values").entrySet().forEach(e -> values.put(Integer.parseInt(e.getKey()), e.getValue().getAsInt()));
		boolean varsPass = vars.get("default").getAsString().equals("pass");
		boolean allQuests = f.get("quests").isJsonPrimitive();
		PlayerSnapshot snapshot = PlayerSnapshot.builder()
			.version(1)
			.membersWorld(f.get("members").getAsBoolean())
			.accountType(ACCOUNT_TYPES.getOrDefault(name, AccountType.NORMAL))
			.inventory(inventory)
			.freeInventorySlots(Math.max(0, INVENTORY_SLOTS - carriedItems))
			.weapon(-1)
			.boostedLevels(levels)
			.realLevels(levels)
			.totalLevel(f.get("maxTotal").getAsBoolean() ? 99 * Skill.values().length
				: levels.values().stream().mapToInt(Integer::intValue).sum())
			.combatLevel(combatLevel(levels))
			.questPoints(allQuests ? MAX_QUEST_POINTS : 0)
			.questsRead(true)
			.quests(quests)
			.varbits(values)
			.varps(values)
			.unknownVars(varsPass ? PlayerSnapshot.UnknownVars.PASS : PlayerSnapshot.UnknownVars.FAIL)
			.charges(charges)
			.house("full".equals(f.get("poh").getAsString()) ? fullyBuiltHouse() : HouseState.NONE)
			.plantedTrees(strings(f, "plantedTrees"))
			.spellbook(new SpellbookState(Book.valueOf(f.get("book").getAsString().toUpperCase()), false,
				SpellbookState.CAPE_CHANGES_PER_DAY, varsPass || values.getOrDefault(VarbitID.ARCEUUS_SPELLBOOK_UNLOCKED, 0) == 1,
				quests.get(Quest.DESERT_TREASURE_I) == QuestState.FINISHED, quests.get(Quest.LUNAR_DIPLOMACY) == QuestState.FINISHED,
				quests.get(Quest.DREAM_MENTOR) == QuestState.FINISHED))
			.build();
		return new Loadout(name, snapshot, List.copyOf(banked), bankedSnapshot(snapshot, bankedFamilies), f);
	}

	private static PlayerSnapshot bankedSnapshot(PlayerSnapshot carried, List<String> families)
	{
		if (families.isEmpty())
		{
			return null;
		}
		Map<Integer, Integer> stored = new HashMap<>();
		Map<Integer, Charge> charges = new HashMap<>(carried.getCharges());
		for (String family : families)
		{
			int id = itemId(family);
			stored.merge(id, family.endsWith("tablet") ? BANKED_TABLETS : 1, Integer::sum);
			Integer known = CHARGES.get(family);
			if (known != null)
			{
				charges.put(id, new Charge(known, Charge.Source.ITEM_ID));
			}
		}
		boolean group = carried.getAccountType().isGroup();
		return carried.toBuilder().bank(group ? Map.of() : stored).groupStorage(group ? stored : Map.of()).charges(charges).build();
	}

	/** Walks stay at the unlearned 4 ticks. */
	public static HouseState fullyBuiltHouse()
	{
		Set<Integer> keys = new HashSet<>();
		for (int key = 1; key <= NEXUS_SLOTS; key++)
		{
			keys.add(key);
		}
		return HouseState.builder()
			.nexusKeys(keys)
			.furniture(Set.of(ObjectID.POH_NEXUS_PORTAL_3, ObjectID.POH_JEWELLERY_BOX_3, ObjectID.POH_TROPHY_AMULETOFGLORY_4,
				ObjectID.POH_AMULET_XERIC_INFERNO, ObjectID.POH_AMULET_DIG_FOSSIL, ObjectID.POH_ALTAR_OCCULT,
				ObjectID.POH_MOUNTED_MAX_CAPE, ObjectID.POH_WILDERNESS_OBELISK, ObjectID.POH_SPIRIT_RING))
			.xericLeftClick(3)
			.digsiteLeftClick(2)
			.boxLeftClick(20)
			.source(HouseState.Source.SCAN)
			.scannedAt(1)
			.build();
	}

	public static RuneModel runeModel()
	{
		return RuneModel.load(new RuneModelTest.SliceCacheView("/b08/cache-runes.json"));
	}

	public static int itemId(String family)
	{
		Integer id = ITEMS.get(family);
		if (id == null)
		{
			throw new IllegalArgumentException("no item id for fixture item '" + family + "'");
		}
		return id;
	}

	private static Map<Skill, Integer> levels(JsonObject skills)
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			JsonElement own = skills.get(skill.getName());
			levels.put(skill, (own != null ? own : skills.get("default")).getAsInt());
		}
		return levels;
	}

	private static Map<Quest, QuestState> quests(JsonElement spec)
	{
		Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		for (Quest quest : Quest.values())
		{
			quests.put(quest, spec.isJsonPrimitive() ? QuestState.FINISHED : QuestState.NOT_STARTED);
		}
		if (spec.isJsonArray())
		{
			Map<String, Quest> byName = new HashMap<>();
			for (Quest quest : Quest.values())
			{
				byName.put(quest.getName(), quest);
			}
			for (JsonElement name : spec.getAsJsonArray())
			{
				Quest quest = byName.get(name.getAsString());
				if (quest == null)
				{
					throw new IllegalArgumentException("no quest named '" + name.getAsString() + "'");
				}
				quests.put(quest, QuestState.FINISHED);
			}
		}
		return quests;
	}

	/** The game's formula. */
	private static int combatLevel(Map<Skill, Integer> l)
	{
		double base = 0.25 * (l.get(Skill.DEFENCE) + l.get(Skill.HITPOINTS) + Math.floor(l.get(Skill.PRAYER) / 2.0));
		double melee = 0.325 * (l.get(Skill.ATTACK) + l.get(Skill.STRENGTH));
		double range = 0.325 * Math.floor(3 * l.get(Skill.RANGED) / 2.0);
		double mage = 0.325 * Math.floor(3 * l.get(Skill.MAGIC) / 2.0);
		return (int) Math.floor(base + Math.max(melee, Math.max(range, mage)));
	}

	private static Set<String> strings(JsonObject f, String key)
	{
		Set<String> out = new HashSet<>();
		array(f, key).forEach(value -> out.add(value.getAsString()));
		return out;
	}

	private static Iterable<JsonElement> array(JsonObject f, String key)
	{
		JsonElement value = f.get(key);
		return value != null && value.isJsonArray() ? value.getAsJsonArray() : List.of();
	}

	private static JsonObject read(String name)
	{
