	}
}

package com.cluehelper.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.Executor;
import org.junit.Test;

public class PlannerRunnerTest
{
	private static final class ManualExecutor implements Executor
	{
		final Deque<Runnable> queue = new ArrayDeque<>();

		@Override
		public void execute(Runnable task)
		{
			queue.add(task);
		}

		void runAll()
		{
			while (!queue.isEmpty())
			{
				queue.poll().run();
			}
		}
	}

	private final ManualExecutor background = new ManualExecutor();
	private final ManualExecutor clientThread = new ManualExecutor();
	private final PlannerRunner runner = new PlannerRunner(background, clientThread);
	private final List<String> delivered = new ArrayList<>();
	private final List<String> ran = new ArrayList<>();

	@Test
	public void aJobSupersededBeforeItStartsNeverRuns()
	{
		runner.submit(() -> job("first"), delivered::add);
		runner.submit(() -> job("second"), delivered::add);
		background.runAll();
		clientThread.runAll();

		assertEquals(List.of("second"), ran);
		assertEquals(List.of("second"), delivered);
	}

	@Test
	public void aJobSupersededWhileItRunsHasItsResultDropped()
	{
		runner.submit(() ->
		{
			runner.submit(() -> job("second"), delivered::add);
			return job("first");
		}, delivered::add);
		background.runAll();
		clientThread.runAll();

		assertEquals(List.of("first", "second"), ran);
		assertEquals(List.of("second"), delivered);
	}

	@Test
	public void aResultWaitingForTheClientThreadIsDroppedWhenSuperseded()
	{
		runner.submit(() -> job("first"), delivered::add);
		background.runAll();
		runner.submit(() -> job("second"), delivered::add);
		clientThread.runAll();
		assertTrue(delivered.isEmpty());

		background.runAll();
		clientThread.runAll();
		assertEquals(List.of("second"), delivered);
	}

	@Test
	public void workingUntilTheLatestResultIsDelivered()
	{
		assertFalse(runner.isWorking());
		runner.submit(() -> job("only"), delivered::add);
		assertTrue(runner.isWorking());
		background.runAll();
		assertTrue(runner.isWorking());
		clientThread.runAll();
		assertFalse(runner.isWorking());
	}

	@Test
	public void cancelAllDropsPendingResults()
	{
		runner.submit(() -> job("only"), delivered::add);
		runner.cancelAll();
		assertFalse(runner.isWorking());
		background.runAll();
		clientThread.runAll();
		assertTrue(delivered.isEmpty());
	}

	@Test
	public void aFailingJobLeavesTheRunnerIdle()
	{
		runner.<String>submit(() ->
		{
			throw new IllegalStateException("boom");
		}, delivered::add);
		background.runAll();
		clientThread.runAll();
		assertFalse(runner.isWorking());
		assertTrue(delivered.isEmpty());
	}

	private String job(String name)
	{
		ran.add(name);
		return name;
	}
}

package com.cluehelper.route;

import com.cluehelper.player.Container;
import java.util.stream.Collectors;

/** A route as one line of a golden file: its ticks, its legs, what it spends and withdraws, and the book it ends on. */
public final class RouteText
{
	private RouteText()
	{
	}

	public static String describe(Route route)
	{
		if (route == null)
		{
			return "none";
		}
		String extras = route.getRankHalfTicks() != route.getHalfTicks() ? " (rank " + (route.getRankHalfTicks() + 1) / 2 + ")" : "";
		String spent = route.getSpent().isEmpty() ? "" : " " + route.getSpent();
		String ends = route.getEndBook() != route.getStartBook() ? " leaves you on " + route.getEndBook() : "";
		return route.getTicks() + "t" + extras + ": " + (route.isOpenBankStart() ? "(at the open bank) " : "") + route.describe() + spent
			+ ends + withdraw(route);
	}

	private static String withdraw(Route route)
	{
		if (!route.isBanked())
		{
			return "";
		}
		String items = route.getWithdraw().stream().map(use -> use.getItemId() + (use.getContainer() == Container.GROUP_STORAGE ? " (group)" : ""))
			.collect(Collectors.joining(", "));
		return " withdraw [" + items + "]" + (route.isDepositFirst() ? " deposit first" : "") + (route.isPinIncluded() ? " +PIN" : "");
	}
}

package com.cluehelper.route;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

public final class SceneFiles
{
	/** Older files end after the flags; newer ones go on with the closed doors a walk may open. */
	private static final String DOORS = "doors";

	@Value
	public static class Recorded
	{
		LoadedScene scene;
		WorldPoint player;
	}

	private SceneFiles()
	{
	}

	public static void write(File file, LoadedScene scene, WorldPoint player)
	{
		try (PrintWriter out = new PrintWriter(new OutputStreamWriter(new GZIPOutputStream(new FileOutputStream(file)), StandardCharsets.UTF_8)))
		{
			int[][][] flags = scene.getFlags();
			out.println(scene.getBaseX() + " " + scene.getBaseY() + " " + scene.getSizeX() + " " + scene.getSizeY() + " " + flags.length
				+ " " + player.getX() + " " + player.getY() + " " + player.getPlane());
			writePlanes(out, flags);
			if (scene.getDoorSides() != null)
			{
				out.println(DOORS);
				writePlanes(out, scene.getDoorSides());
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("scene " + file, e);
		}
	}

	private static void writePlanes(PrintWriter out, int[][][] planes)
	{
		for (int[][] plane : planes)
		{
			if (plane == null)
			{
				out.println("-");
				continue;
			}
			for (int[] column : plane)
			{
				StringBuilder line = new StringBuilder();
				for (int value : column)
				{
					line.append(line.length() == 0 ? "" : " ").append(value);
				}
				out.println(line);
			}
		}
	}

	/** A scene recorded into the test resources' scenes folder, by its file name without ".scene.gz". */
	public static Recorded resource(String name) throws IOException
	{
		try (InputStream in = SceneFiles.class.getResourceAsStream("/scenes/" + name + ".scene.gz"))
		{
			return read(in);
		}
	}

	public static Recorded read(InputStream in) throws IOException
	{
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8)))
		{
			String[] h = reader.readLine().split(" ");
			int sizeX = Integer.parseInt(h[2]);
			int planes = Integer.parseInt(h[4]);
			int[][][] flags = readPlanes(reader, planes, sizeX);
			int[][][] doorSides = DOORS.equals(reader.readLine()) ? readPlanes(reader, planes, sizeX) : null;
			LoadedScene scene = new LoadedScene(Integer.parseInt(h[0]), Integer.parseInt(h[1]), sizeX, Integer.parseInt(h[3]), flags, doorSides);
			return new Recorded(scene, new WorldPoint(Integer.parseInt(h[5]), Integer.parseInt(h[6]), Integer.parseInt(h[7])));
		}
	}

	private static int[][][] readPlanes(BufferedReader reader, int planes, int sizeX) throws IOException
	{
		int[][][] values = new int[planes][][];
		for (int p = 0; p < planes; p++)
		{
			String first = reader.readLine();
			if (first.equals("-"))
			{
				continue;
			}
			values[p] = new int[sizeX][];
			for (int x = 0; x < sizeX; x++)
			{
				String[] cells = (x == 0 ? first : reader.readLine()).split(" ");
				values[p][x] = new int[cells.length];
				for (int y = 0; y < cells.length; y++)
				{
					values[p][x][y] = Integer.parseInt(cells[y]);
				}
			}
		}
		return values;
	}
}

package com.cluehelper.route;

import static org.junit.Assert.assertTrue;

import com.cluehelper.player.Charge;
import com.cluehelper.player.Container;
import com.cluehelper.player.ItemUse;
import com.cluehelper.player.PlayerSnapshot;
import com.cluehelper.transport.CatalogRow;
import com.cluehelper.transport.RowAvailability;
import com.cluehelper.transport.Spend;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Tallied from the route's legs rather than the search's labels, so it checks the search independently. */
final class SpendCheck
{
	private SpendCheck()
	{
	}

	static void assertWithinMeans(PlanInput input, Route route)
	{
		Map<String, Integer> used = new HashMap<>();
		PlayerSnapshot at = input.getPlayer();
		for (Leg leg : route.getLegs())
		{
			if (leg.getKind() == Leg.Kind.BANK)
			{
				at = input.getBanked();
				continue;
			}
			if (leg.getRow() != null)
			{
				tally(input, leg.getRow(), leg.getRow().getSpends(), at, used);
			}
			if (leg.getChange() != null)
			{
				CatalogRow asRow = CatalogRow.builder().name(leg.getChange().getName()).requirements(leg.getChange().getRequirements()).build();
				tally(input, asRow, leg.getChange().getSpends(), at, used);
			}
		}
		PlayerSnapshot end = at;
		used.forEach((key, units) -> assertTrue(input.getStep().getKey() + ": " + route.describe() + " uses " + units + " of " + key
			+ ", has " + available(key, end), units <= available(key, end)));
	}

	private static void tally(PlanInput input, CatalogRow row, List<Spend> spends, PlayerSnapshot player, Map<String, Integer> used)
	{
		RowAvailability judged = input.getEngine().judge(row, player.toBuilder().wildernessLevel(0).build(), input.getNowMinutes());
		for (Spend spend : spends)
		{
			switch (spend.getKind())
			{
				case RUNES:
				case ITEM:
					for (ItemUse use : judged.getWitness())
					{
						if (use.getContainer() != Container.WORN)
						{
							used.merge("item:" + use.getItemId(), use.getQuantity(), Integer::sum);
						}
					}
					break;
				case CHARGE:
					judged.getWitness().forEach(use -> used.merge("charge:" + use.getItemId(), 1, Integer::sum));
					break;
				case COOLDOWN:
				case DAILY:
					used.merge("once:" + spend.getVar(), 1, Integer::sum);
					break;
				default:
					used.merge("cape", 1, Integer::sum);
			}
		}
	}

	private static int stored(PlayerSnapshot player, int id)
	{
		return player.count(Container.INVENTORY, id) + player.count(Container.WORN, id) + player.count(Container.BANK, id)
			+ player.count(Container.GROUP_STORAGE, id);
	}

	private static int available(String key, PlayerSnapshot player)
	{
		String[] parts = key.split(":");
		switch (parts[0])
		{
			case "item":
				int id = Integer.parseInt(parts[1]);
				return stored(player, id) + player.count(Container.RUNE_POUCH, id);
			case "charge":
				int item = Integer.parseInt(parts[1]);
				Charge charge = player.getCharges().get(item);
				int held = stored(player, item);
				return Math.max(1, held) * (charge == null ? 1 : charge.getCharges());
			case "once":
				return 1;
			default:
				return player.getSpellbook().getCapeChangesLeft();
		}
	}
}

package com.cluehelper.route;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * The walk search and the bundled walk table walk Shortest Path's map by the same rules, so a search from a node costs
 * each of its table walks exactly; a drifted map or a changed rule shows here.
 */
public class WalkCostsTest
{
	/** Every so many nodes, to keep the test quick. */
	private static final int NODE_STRIDE = 25;
	/** The walk generator's search limit. */
	private static final int WALK_LIMIT = 200;

	@Test
	public void startWalksMatchTheTable() throws IOException
	{
		WalkTable table = WalkTable.load();
		Ground ground = Ground.world(WorldMap.load(), null, table, row -> true);
		List<String> mismatches = new ArrayList<>();
		int compared = 0;
		int capped = 0;
		for (int from = 0; from < table.nodeCount(); from += NODE_STRIDE)
		{
			if (table.placed(from) == null)
			{
				continue;
			}
			WalkSearch walk = new WalkSearch(ground, WALK_LIMIT, false);
			walk.run(WalkTable.pack(table.placed(from)), (tile, cost) -> WalkSearch.UNREACHED);
			for (int e = table.entriesFrom(from); e < table.entriesEnd(from); e++)
			{
				WorldPoint to = table.placed(table.entryTo(e));
				if (to == null)
				{
					continue;
				}
				int walked = walk.cost(WalkTable.pack(to));
				if (walked == WalkSearch.UNREACHED && walk.reachedTiles() >= ground.tileLimit())
				{
					capped++;
					continue;
				}
				compared++;
				if (walked != table.entryFull(e))
				{
					mismatches.add("node " + from + " " + table.placed(from) + " -> " + to + ": table " + table.entryFull(e)
						+ ", walk " + (walked == WalkSearch.UNREACHED ? "unreached" : walked));
				}
			}
		}
		System.out.printf("walks against the table: %d pairs, %d differ, %d past the search's tile limit%n", compared,
			mismatches.size(), capped);
		assertTrue(compared > 0);
		assertTrue(String.join("\n", mismatches.subList(0, Math.min(20, mismatches.size()))), mismatches.isEmpty());
	}
}

package com.cluehelper.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.util.List;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class WorldWalkTest
{
	/**
	 * A wall along x = 15 with a closed door at y = 16 and a gap at y = 19: one tile further round beats opening the
	 * door. The client blocks the scene's edge rows, so the wall stands well inside.
	 */
	@Test
	public void aShortDetourBeatsOpeningADoor()
	{
		int size = 32;
		int wallX = 15;
		int doorY = 16;
		int gapY = 19;
		int[][] flags = new int[size][size];
		int[][] doorSides = new int[size][size];
		for (int y = 0; y < gapY; y++)
		{
			int[][] sides = y == doorY ? doorSides : flags;
			sides[wallX][y] |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;
			sides[wallX - 1][y] |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		}
		LoadedScene scene = new LoadedScene(0, 0, size, size, new int[][][] {flags}, new int[][][] {doorSides});
		WorldPoint start = new WorldPoint(wallX - 3, doorY, 0);
		List<WorldPoint> line = new WorldWalk().path(Ground.sceneOnly(scene), start, WalkGoal.tile(new WorldPoint(wallX + 3, doorY, 0)));

		assertEquals(start, line.get(0));
		assertFalse("through the door: " + line, line.contains(new WorldPoint(wallX, doorY, 0)));
	}

	/** Walking to a chest ends where it is used, on a straight side with no wall between: never against its walled side. */
	@Test
	public void anObjectIsWalkedToWhereItIsUsed()
	{
		int size = 32;
		WorldPoint chest = new WorldPoint(15, 15, 0);
		int[][] flags = new int[size][size];
		flags[chest.getX()][chest.getY()] |= CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		flags[chest.getX()][chest.getY()] |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		flags[chest.getX() - 1][chest.getY()] |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		LoadedScene scene = new LoadedScene(0, 0, size, size, new int[][][] {flags});
		List<WorldPoint> line = new WorldWalk().path(Ground.sceneOnly(scene), new WorldPoint(10, 15, 0), WalkGoal.object(chest, 1, 1));

		WorldPoint end = line.get(line.size() - 1);
		assertEquals("ends beside the chest: " + line, 1, Math.abs(end.getX() - chest.getX()) + Math.abs(end.getY() - chest.getY()));
		assertFalse("against the wall: " + line, end.equals(chest.dx(-1)));
	}

	/**
	 * A goal in a house's corner, walked to from outside that corner: the line goes round through the doorway on the far
	 * side, never ends against the wall beside the goal.
	 */
	@Test
	public void aGoalInsideAHouseIsReachedThroughItsDoorway()
	{
		int size = 32;
		int low = 11;
		int high = 19;
		int doorwayX = 15;
		int[][] flags = new int[size][size];
		for (int i = low; i <= high; i++)
		{
			wall(flags, low, i, CollisionDataFlag.BLOCK_MOVEMENT_WEST, -1, 0, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
			wall(flags, high, i, CollisionDataFlag.BLOCK_MOVEMENT_EAST, 1, 0, CollisionDataFlag.BLOCK_MOVEMENT_WEST);
			wall(flags, i, low, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH, 0, -1, CollisionDataFlag.BLOCK_MOVEMENT_NORTH);
			if (i != doorwayX)
			{
				wall(flags, i, high, CollisionDataFlag.BLOCK_MOVEMENT_NORTH, 0, 1, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH);
			}
		}
		LoadedScene scene = new LoadedScene(0, 0, size, size, new int[][][] {flags});
		WorldPoint corner = new WorldPoint(low, low, 0);
		List<WorldPoint> line = new WorldWalk().path(Ground.sceneOnly(scene), new WorldPoint(low - 2, low + 1, 0), WalkGoal.tile(corner));

		assertEquals("ends in the corner: " + line, corner, line.get(line.size() - 1));
	}

	private static void wall(int[][] flags, int x, int y, int side, int dx, int dy, int facingSide)
	{
		flags[x][y] |= side;
		flags[x + dx][y + dy] |= facingSide;
	}

	/**
	 * Past the loaded scene's edge, up stairs, the walk still reaches the goal, every step one the game walks: Daer
	 * Krand in the Sisterhood Sanctuary, from the corridor north of the medallion's landing, and a long walk across
	 * Lumbridge to Draynor's bank with no scene at all.
	 */
	@Test
	public void walksPastTheSceneTileByTile() throws IOException
	{
		WalkTable table = WalkTable.load();
		WorldMap map = WorldMap.load();
		LoadedScene sanctuary = SceneFiles.resource("3760_9648_1").getScene();
		WorldWalk walk = new WorldWalk();
		WorldPoint daerKrand = new WorldPoint(3821, 9780, 2);
		for (WorldPoint at : List.of(new WorldPoint(3814, 9731, 1), new WorldPoint(3826, 9733, 1)))
		{
			assertWalks(walk, Ground.world(map, sanctuary, table, row -> true), at, daerKrand);
		}
		assertWalks(walk, Ground.world(map, null, table, row -> true), new WorldPoint(3222, 3218, 0), new WorldPoint(3092, 3245, 0));
	}

	private static void assertWalks(WorldWalk walk, Ground ground, WorldPoint from, WorldPoint to)
	{
		long started = System.nanoTime();
		List<WorldPoint> line = walk.path(ground, from, WalkGoal.tile(to));
		System.out.printf("%s -> %s: %d tiles in %.1f ms%n", from, to, line.size(), (System.nanoTime() - started) / 1e6);
		assertEquals(from, line.get(0));
		WorldPoint end = line.get(line.size() - 1);
		assertTrue("ends at " + end, end.getPlane() == to.getPlane() && end.distanceTo2D(to) <= 2);
		for (int i = 0; i + 1 < line.size(); i++)
		{
			WorldPoint a = line.get(i);
			WorldPoint b = line.get(i + 1);
			boolean onFoot = a.getPlane() == b.getPlane() && a.distanceTo2D(b) == 1;
			assertTrue("step " + a + " -> " + b, !onFoot || canStep(ground, a, b));
		}
	}

	/** A walk, or a straight step onto a blocked tile a row starts from. */
	private static boolean canStep(Ground ground, WorldPoint a, WorldPoint b)
	{
		for (int d = 0; d < Directions.COUNT; d++)
		{
			if (a.getX() + Directions.DX[d] == b.getX() && a.getY() + Directions.DY[d] == b.getY())
			{
				return ground.canMove(a.getX(), a.getY(), a.getPlane(), d)
					|| d < Directions.STRAIGHT && ground.openRowsFrom(WalkTable.pack(b)).length > 0;
			}
		}
		return false;
	}
}

package com.cluehelper.step;

import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.io.Writer;
import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;

/**
 * Writes core's clue data to JSON for tools/cache/c1_match.py and tools/steps/generate.py. Provider lambdas run
 * under every var state in {@link CoreClues#VAR_STATES}, so varbit- or quest-dependent entries list all
 * their branches. Run: gradlew coreClues.
 */
public class CoreClueExport
{
	private static final String CLUES_PACKAGE = CoreClues.CLUES_PACKAGE;

	private static ClueScrollPlugin fakePlugin;

	public static void main(String[] args) throws Exception
	{
		Path out = Paths.get(args.length > 0 ? args[0] : "tools/cache/out/core-clues.json");
		fakePlugin = CoreClues.plugin();

		JsonObject root = new JsonObject();
		for (String type : CoreClues.LIST_TYPES)
		{
			JsonArray array = new JsonArray();
			for (Object clue : CoreClues.entries(type))
			{
				array.add(withStepKey(describe(clue, 0).getAsJsonObject(), (ClueScroll) clue));
			}
			root.add(type, array);
			System.out.println(type + ": " + array.size());
		}
		root.add("HotColdLocation", enumValues(CLUES_PACKAGE + "hotcold.HotColdLocation"));
		root.add("STASHUnit", enumValues(CLUES_PACKAGE + "emote.STASHUnit"));
		root.add("HotColdClue", hotColdClues());

		Files.createDirectories(out.getParent());
		try (Writer writer = Files.newBufferedWriter(out, StandardCharsets.UTF_8))
		{
			new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().serializeNulls().create().toJson(root, writer);
		}
		System.out.println("wrote " + out.toAbsolutePath());
	}

	private static JsonArray enumValues(String className) throws Exception
	{
		JsonArray array = new JsonArray();
		for (Object constant : Class.forName(className).getEnumConstants())
		{
			JsonObject described = describe(constant, 0).getAsJsonObject();
			described.addProperty("name", ((Enum<?>) constant).name());
			array.add(described);
		}
		return array;
	}

	private static JsonArray hotColdClues() throws Exception
	{
		JsonArray array = new JsonArray();
		for (String name : CoreClues.HOT_COLD_CLUES)
		{
			Object clue = CoreClues.staticField(CLUES_PACKAGE + "HotColdClue", name);
			JsonObject described = withStepKey(describe(clue, 0).getAsJsonObject(), (ClueScroll) clue);
			described.addProperty("name", name);
			array.add(described);
		}
		return array;
	}

	/** The step index generator joins on this key, taken under var state 0. */
	private static JsonObject withStepKey(JsonObject described, ClueScroll clue)
	{
		described.addProperty("stepKey", StepKey.of(CoreClueReader.facts(clue, fakePlugin)));
		return described;
	}

	private static JsonElement describe(Object value, int depth)
	{
		if (value == null)
		{
			return JsonNull.INSTANCE;
		}
		if (value instanceof Number)
		{
			return new JsonPrimitive((Number) value);
		}
		if (value instanceof Boolean)
		{
			return new JsonPrimitive((Boolean) value);
		}
		if (value instanceof CharSequence || value instanceof Character)
		{
			return new JsonPrimitive(value.toString());
		}
		if (value instanceof WorldPoint)
		{
			WorldPoint point = (WorldPoint) value;
			JsonArray xyz = new JsonArray();
			xyz.add(point.getX());
			xyz.add(point.getY());
			xyz.add(point.getPlane());
			return xyz;
		}
		if (value instanceof Enum && depth > 0)
		{
			return new JsonPrimitive(((Enum<?>) value).name());
		}
		if (value instanceof Function)
		{
			return evaluateProvider((Function<?, ?>) value, depth);
		}
		if (value instanceof Map)
		{
			JsonArray pairs = new JsonArray();
			for (Map.Entry<?, ?> entry : ((Map<?, ?>) value).entrySet())
			{
				JsonArray pair = new JsonArray();
				pair.add(describe(entry.getKey(), depth + 1));
				pair.add(describe(entry.getValue(), depth + 1));
				pairs.add(pair);
			}
			return pairs;
		}
		if (value instanceof Collection)
		{
			JsonArray array = new JsonArray();
			for (Object element : (Collection<?>) value)
			{
				array.add(describe(element, depth + 1));
			}
			return array;
		}
		if (value.getClass().isArray())
		{
			JsonArray array = new JsonArray();
			for (int i = 0; i < Array.getLength(value); i++)
			{
				array.add(describe(Array.get(value, i), depth + 1));
			}
			return array;
		}
		if (isCoreClueType(value.getClass()) && depth < 6)
		{
			return describeFields(value, depth);
		}
		return new JsonPrimitive(value.toString());
	}

	private static boolean isCoreClueType(Class<?> type)
	{
		return type.getName().startsWith("net.runelite.client.plugins.cluescrolls");
	}

	private static JsonObject describeFields(Object value, int depth)
	{
		JsonObject object = new JsonObject();
		object.addProperty("class", value.getClass().getSimpleName());
		for (Class<?> type = value.getClass(); type != null && type != Object.class && type != Enum.class; type = type.getSuperclass())
		{
			for (Field field : type.getDeclaredFields())
			{
				if (Modifier.isStatic(field.getModifiers()) || object.has(field.getName()))
				{
					continue;
				}
				try
				{
					field.setAccessible(true);
					object.add(field.getName(), describe(field.get(value), depth + 1));
				}
				catch (ReflectiveOperationException | RuntimeException e)
				{
					object.addProperty(field.getName(), "<unreadable: " + e + ">");
				}
			}
		}
		return object;
	}

	@SuppressWarnings("unchecked")
	private static JsonElement evaluateProvider(Function<?, ?> provider, int depth)
	{
		Set<String> seen = new LinkedHashSet<>();
		List<JsonElement> branches = new ArrayList<>();
		for (int state : CoreClues.VAR_STATES)
		{
			CoreClues.setVarState(state);
			JsonElement result;
			try
			{
				result = describe(((Function<Object, Object>) provider).apply(fakePlugin), depth + 1);
			}
			catch (RuntimeException e)
			{
				result = new JsonPrimitive("<threw " + e.getClass().getSimpleName() + ">");
			}
			if (seen.add(result.toString()))
			{
				branches.add(result);
			}
		}
		CoreClues.setVarState(0);
		JsonObject object = new JsonObject();
		JsonArray array = new JsonArray();
		branches.forEach(array::add);
		object.add("branches", array);
		return object;
	}
}

package com.cluehelper.step;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.HotColdClue;

/** The fake client answers every varbit and varp with one settable value, so each provider branch can be evaluated. */
public final class CoreClues
{
	static final String CLUES_PACKAGE = "net.runelite.client.plugins.cluescrolls.clues.";
	static final int[] VAR_STATES = {0, 1, 2, 3, 4, 5, 10, 100};
	static final String[] LIST_TYPES = {
		"CrypticClue", "AnagramClue", "CipherClue", "CoordinateClue", "EmoteClue", "MapClue",
		"BeginnerMapClue", "FairyRingClue", "MusicClue", "FaloTheBardClue", "SkillChallengeClue",
	};
	static final String[] HOT_COLD_CLUES = {"BEGINNER_CLUE", "MASTER_CLUE", "LEAGUE_TUTOR_BEGINNER_CLUE", "LEAGUE_TUTOR_MASTER_CLUE"};

	private static int varState;
	private static ClueScrollPlugin plugin;

	private CoreClues()
	{
	}

	public static synchronized ClueScrollPlugin plugin() throws ReflectiveOperationException
	{
		if (plugin == null)
		{
			plugin = pluginWithFakeClient();
		}
		return plugin;
	}

	/** A Clue Scroll plugin that reads {@code client}, for resolving a clue offline. */
	public static ClueScrollPlugin plugin(Client client) throws ReflectiveOperationException
	{
		ClueScrollPlugin plugin = new ClueScrollPlugin();
		Field clientField = ClueScrollPlugin.class.getDeclaredField("client");
		clientField.setAccessible(true);
		clientField.set(plugin, client);
		return plugin;
	}

	/** Core's clue at {@code source}, its list and place in it: {@code CrypticClue#12}. */
	public static ClueScroll entry(String source) throws ReflectiveOperationException
	{
		String[] parts = source.split("#");
		return (ClueScroll) entries(parts[0]).get(Integer.parseInt(parts[1]));
	}

	/** Where {@code clue} is in core's lists, as {@link #entry} takes it; null for a clue in none of them. */
	public static String source(ClueScroll clue) throws ReflectiveOperationException
	{
		for (String type : LIST_TYPES)
		{
			List<Object> entries = entries(type);
			for (int i = 0; i < entries.size(); i++)
			{
				if (entries.get(i) == clue)
				{
					return type + "#" + i;
				}
			}
		}
		return null;
	}

	static void setVarState(int state)
	{
		varState = state;
	}

	static List<Object> entries(String type) throws ReflectiveOperationException
	{
		Object clues = staticField(CLUES_PACKAGE + type, "CLUES");
		Collection<?> values = clues instanceof Map ? ((Map<?, ?>) clues).values() : (Collection<?>) clues;
		return new ArrayList<>(values);
	}

	/** Hot/cold clues are reset first, as core does when it hands one out, so they have a solver. */
	public static Map<String, ClueScroll> steps() throws ReflectiveOperationException
	{
		Map<String, ClueScroll> steps = new LinkedHashMap<>();
		for (String type : LIST_TYPES)
		{
			List<Object> entries = entries(type);
			for (int i = 0; i < entries.size(); i++)
			{
				steps.put(type + "#" + i, (ClueScroll) entries.get(i));
			}
		}
		for (String name : HOT_COLD_CLUES)
		{
			HotColdClue clue = (HotColdClue) staticField(CLUES_PACKAGE + "HotColdClue", name);
			clue.reset();
			steps.put("HotColdClue#" + name, clue);
		}
		return steps;
	}

	static Object staticField(String className, String fieldName) throws ReflectiveOperationException
	{
		Field field = Class.forName(className).getDeclaredField(fieldName);
		field.setAccessible(true);
		return field.get(null);
	}

	/** Cipher clues name their NPC through the client's NPC definitions. */
	private static NPCComposition npcNamed(String name)
	{
		return (NPCComposition) Proxy.newProxyInstance(NPCComposition.class.getClassLoader(), new Class<?>[]{NPCComposition.class},
			(proxy, method, methodArgs) -> method.getName().equals("getName") ? name : null);
	}

	private static ClueScrollPlugin pluginWithFakeClient() throws ReflectiveOperationException
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, methodArgs) ->
			{
				switch (method.getName())
				{
					case "getVarbitValue":
					case "getVarpValue":
						return varState;
					case "getIntStack":
						return new int[]{varState, varState, varState};
					case "getNpcDefinition":
						return npcNamed("npc " + methodArgs[0]);
					case "toString":
						return "FakeClient";
					case "hashCode":
						return 0;
					case "equals":
						return proxy == methodArgs[0];
				}
				Class<?> type = method.getReturnType();
				if (type == boolean.class)
				{
					return false;
				}
				if (type.isPrimitive() && type != void.class)
				{
					return type == long.class ? 0L : type == float.class ? 0f : type == double.class ? 0d : 0;
				}
				return null;
			});
		return plugin(client);
	}
}

