/**
 * On a snapshot difference this writes build/drift/core-steps.tsv: review the diff, then copy it over
 * src/test/resources/drift/core-steps.tsv. A cache-side change shows up only once
 * tools/steps/generate.py regenerates the step files from a newer dump.
 */
public class CoreDriftTest
{
	private static final String GOLDEN = "/drift/core-steps.tsv";
	private static final Path ACTUAL = Paths.get("build/drift/core-steps.tsv");
	private static final Path VIEW_ROWS = Paths.get("build/drift/steps.json");
	private static final String SPOT_PREFIX = "spot:";
	private static final int MOST_DIFF_LINES = 40;

	private static final Set<String> EXPECTED_WITHOUT_ROW = new TreeSet<>(List.of(
		"cryptic:search a crate in the haymaker's arms.",
		"hotcold:beginner:leagues tutor",
		"hotcold:master:leagues tutor",
		SPOT_PREFIX + "SAIL_ISLE_OF_SERPENTS"));

	private static StepIndex index;
	private static Map<String, ClueScroll> steps;
	private static final Map<String, List<String>> SOURCES_BY_KEY = new TreeMap<>();
	/** Step key → snapshot columns → the var states that resolve to them. */
	private static final Map<String, Map<String, List<Integer>>> SNAPSHOT = new TreeMap<>();
	private static final List<String> UNSTABLE_KEYS = new ArrayList<>();
	private static final Map<String, Step> FIRST_BRANCH = new TreeMap<>();

	@BeforeClass
	public static void resolveEverything() throws ReflectiveOperationException
	{
		index = StepIndex.read(new Gson());
		steps = CoreClues.steps();
		ClueScrollPlugin plugin = CoreClues.plugin();
		StepResolver resolver = new StepResolver(() -> index);
		for (Map.Entry<String, ClueScroll> source : steps.entrySet())
		{
			String keyAtZero = null;
			for (int state : CoreClues.VAR_STATES)
			{
				CoreClues.setVarState(state);
				Step step = resolver.resolve(source.getValue(), plugin);
				if (keyAtZero == null)
				{
					keyAtZero = step.getKey();
					SOURCES_BY_KEY.computeIfAbsent(keyAtZero, k -> new ArrayList<>()).add(source.getKey());
					FIRST_BRANCH.putIfAbsent(keyAtZero, step);
				}
				else if (!keyAtZero.equals(step.getKey()))
				{
					UNSTABLE_KEYS.add(source.getKey() + ": " + keyAtZero + " / " + step.getKey() + " at var state " + state);
				}
				SNAPSHOT.computeIfAbsent(keyAtZero, k -> new LinkedHashMap<>())
					.computeIfAbsent(snapshotColumns(step), k -> new ArrayList<>()).add(state);
			}
		}
		CoreClues.setVarState(0);
	}

	@Test
	public void everyStepHasOneKeyOfItsOwnUnderEveryBranch()
	{
		assertEquals("keys that change with a varbit:\n" + String.join("\n", UNSTABLE_KEYS), List.of(), UNSTABLE_KEYS);
		List<String> shared = SOURCES_BY_KEY.entrySet().stream()
			.filter(e -> e.getValue().size() > 1)
			.map(e -> e.getKey() + " <- " + e.getValue())
			.collect(Collectors.toList());
		assertEquals("keys shared by two core entries:\n" + String.join("\n", shared), List.of(), shared);
		assertEquals(steps.size(), SOURCES_BY_KEY.size());
	}

	@Test
	public void everyKeyMapsToItsCacheRows()
	{
		Set<String> coreKeys = SOURCES_BY_KEY.keySet();
		Set<String> dataKeys = index.getSteps().keySet();
		assertEquals("core keys missing from the step files (regenerate them, tools/steps/generate.py)",
			Set.of(), difference(coreKeys, dataKeys));
		assertEquals("step file keys core no longer has", Set.of(), difference(dataKeys, coreKeys));

		Set<String> spotNames = new TreeSet<>();
		for (HotColdLocation spot : HotColdLocation.values())
		{
			spotNames.add(spot.name());
		}
		assertEquals("hot/cold spots core no longer has", Set.of(), difference(index.getHotColdSpots().keySet(), spotNames));

		Set<String> withoutRow = new TreeSet<>();
		index.getSteps().forEach((key, entry) ->
		{
			if (entry.getRows().isEmpty())
			{
				withoutRow.add(key);
			}
		});
		for (String name : spotNames)
		{
			if (!index.getHotColdSpots().containsKey(name))
			{
				withoutRow.add(SPOT_PREFIX + name);
			}
		}
		assertEquals(EXPECTED_WITHOUT_ROW, withoutRow);

		StepIndex.Entry nieveOrSteve = index.entry("anagram:12059");
		assertEquals("I EVEN / VESTE owns one row per branch of varbit 5037", List.of(true, false),
			nieveOrSteve.getRows().stream().map(row -> row.getWhen().holdsFor(0)).collect(Collectors.toList()));
	}

	/** The step files' contract with the guide: a broken row would only show as a step with no route or no stage. */
	@Test
	public void stepFilesHoldWhatTheGuideNeeds()
	{
		List<String> broken = new ArrayList<>();
		index.getSteps().forEach((key, entry) ->
		{
			boolean coreOnly = entry.getRows().isEmpty();
			if (entry.getTier() == null && !coreOnly)
			{
				broken.add(key + ": no tier");
			}
			for (StepIndex.Target target : entry.getTargets())
			{
				if (target.getKind() == StepIndex.Target.Kind.KEY && (target.getKey() < 0 || target.getKeyTile() == null || target.getTile() == null))
				{
					broken.add(key + ": key target without key, kill tile or chest tile");
				}
				if (target.getKind() == StepIndex.Target.Kind.KILL && entry.getArea() == null && entry.getReach() == null)
				{
					broken.add(key + ": kill target without an area or a reach note");
				}
			}
			StepIndex.WayIn way = entry.getEntry();
			if (way != null && (way.getTile() == null || way.getTo() == null || !way.isInside(way.getTo()) || way.isInside(way.getTile())))
			{
				broken.add(key + ": way in must start outside its box and land inside it");
			}
			boolean placed = !entry.getTiles().isEmpty() || entry.getArea() != null || entry.getStand() != null;
			if (!placed && entry.getReach() == null && !entry.isHidden() && !key.startsWith("hotcold:") && !coreOnly)
			{
				broken.add(key + ": no tile, area, standing tile or reach note");
			}
		});
		assertEquals(List.of(), broken);
	}

	@Test
	public void resolvedStepsMatchTheGoldenSnapshot() throws IOException
	{
		List<String> actual = snapshotLines();
		Files.createDirectories(ACTUAL.getParent());
		Files.write(ACTUAL, actual, StandardCharsets.UTF_8);
		writeViewRows();

		List<String> golden = golden();
		if (!golden.equals(actual))
		{
			fail("core's resolved steps differ from " + GOLDEN + " (actual in " + ACTUAL + "):\n" + diff(golden, actual));
		}
	}

	@Test
	public void threeStepTakesItsPartsRowsAndShrinksAsPartsAreSolved() throws ReflectiveOperationException
	{
		CoreClues.setVarState(0);
		List<Map.Entry<CrypticClue, Boolean>> parts = new ArrayList<>();
		for (String start : List.of("the doorman of the warriors' guild", "she's small but can build", "my life was spared"))
		{
			CrypticClue part = (CrypticClue) CoreClues.entries("CrypticClue").stream()
				.filter(c -> ClueFacts.normalise(((CrypticClue) c).getText()).startsWith(start))
				.findFirst().orElseThrow(() -> new AssertionError("no cryptic starting " + start));
			parts.add(new AbstractMap.SimpleEntry<>(part, false));
		}
		ThreeStepCrypticClue clue = new ThreeStepCrypticClue(parts, "three parts");
		StepResolver resolver = new StepResolver(() -> index);

		Step whole = resolver.resolve(clue, CoreClues.plugin());
		assertEquals("master", whole.getTier());
		assertTrue(whole.isKnown());
		assertEquals(TargetKind.SEQUENCE, whole.getKind());
		assertEquals(3, whole.getCacheRows().size());
		assertEquals(3, whole.getTargets().size());

		parts.get(0).setValue(true);
		Step oneSolved = resolver.resolve(clue, CoreClues.plugin());
		assertEquals("the key stays, so ClueLink calls it an updated step", whole.getKey(), oneSolved.getKey());
		assertEquals(whole.getTargets().subList(1, 3), oneSolved.getTargets());
	}

	@Test
	public void unknownStepsStillGetCoresTargets() throws ReflectiveOperationException
	{
		CoreClues.setVarState(0);
		ClueScrollPlugin plugin = CoreClues.plugin();
		StepResolver withoutData = new StepResolver(StepIndex::empty);
		List<String> lost = new ArrayList<>();
		for (Map.Entry<String, ClueScroll> source : steps.entrySet())
		{
			Step unknown = withoutData.resolve(source.getValue(), plugin);
			assertFalse(unknown.isKnown());
			if (!unknown.getTargets().equals(CoreClueReader.locations(source.getValue(), plugin)))
			{
				lost.add(source.getKey() + " " + unknown.getKey() + " " + unknown.getTargets());
			}
		}
		assertEquals("unknown steps whose targets aren't core's", List.of(), lost);
	}

	private static String snapshotColumns(Step step)
	{
		return String.join("\t",
			step.getType(),
			step.getTier(),
			step.getKind().name(),
			tiles(step.getTargets()),
			String.join("|", step.getNpcs()),
			step.getRegions().stream().map(String::valueOf).collect(Collectors.joining("|")),
			step.getObjectIds().stream().map(String::valueOf).collect(Collectors.joining("|")),
			String.join("|", step.getObjectNames()),
			step.getRequirements().toString(),
			step.getCacheRows().stream().map(row -> String.valueOf(row.getId())).collect(Collectors.joining("|")),
			oneLine(step.getText()));
	}

	private static List<String> snapshotLines()
	{
		List<String> lines = new ArrayList<>();
		lines.add("key\tbranch\ttype\ttier\tkind\ttargets\tnpcs\tregions\tobjects\tobject names\tneeds\trows\ttext");
		SNAPSHOT.forEach((key, branches) -> branches.forEach((columns, states) ->
			lines.add(key + "\t" + (branches.size() == 1 ? "*" : states.stream().map(String::valueOf).collect(Collectors.joining(","))) + "\t" + columns)));
		for (HotColdLocation spot : HotColdLocation.values())
		{
			StepIndex.Spot row = index.getHotColdSpots().get(spot.name());
			lines.add(SPOT_PREFIX + spot.name() + "\t*\thotcold spot\t" + spot.getType().name().toLowerCase() + "\t\t"
				+ tiles(List.of(spot.getWorldPoint())) + "\t\t\t\t\t\t" + (row == null ? "" : row.getRow()) + "\t" + oneLine(spot.getArea()));
		}
		return lines;
	}

	private static void writeViewRows() throws IOException
	{
		List<Map<String, Object>> rows = new ArrayList<>();
		FIRST_BRANCH.forEach((key, step) ->
		{
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("key", key);
			row.put("type", step.getType());
			row.put("tier", step.getTier());
			row.put("kind", step.getKind().name());
			row.put("targets", tiles(step.getTargets()));
			row.put("targetCount", step.getTargets().size());
			row.put("npcs", String.join(", ", step.getNpcs()));
			row.put("objects", step.getObjectIds() + " " + step.getObjectNames());
			row.put("needs", step.getRequirements().toString());
			row.put("rows", step.getCacheRows().stream().map(CacheRow::getName).collect(Collectors.joining(", ")));
			row.put("branches", SNAPSHOT.get(key).size());
			row.put("text", oneLine(step.getText()));
			rows.add(row);
		});
		Files.write(VIEW_ROWS, new GsonBuilder().disableHtmlEscaping().create().toJson(rows).getBytes(StandardCharsets.UTF_8));
	}

	private static List<String> golden() throws IOException
	{
		try (InputStream in = CoreDriftTest.class.getResourceAsStream(GOLDEN))
		{
			if (in == null)
			{
				return List.of();
			}
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				return reader.lines().collect(Collectors.toList());
			}
		}
	}

	private static String diff(List<String> golden, List<String> actual)
	{
		Set<String> goldenSet = new TreeSet<>(golden);
		Set<String> actualSet = new TreeSet<>(actual);
		List<String> out = new ArrayList<>();
		for (String line : difference(goldenSet, actualSet))
		{
			out.add("- " + line);
		}
		for (String line : difference(actualSet, goldenSet))
		{
			out.add("+ " + line);
		}
		out.sort((a, b) -> a.substring(2).compareTo(b.substring(2)));
		int shown = Math.min(out.size(), MOST_DIFF_LINES);
		return String.join("\n", out.subList(0, shown)) + (out.size() > shown ? "\n… " + (out.size() - shown) + " more" : "");
	}

	private static String tiles(List<WorldPoint> points)
	{
		return points.stream().map(p -> p.getX() + "," + p.getY() + "," + p.getPlane()).collect(Collectors.joining("|"));
	}

	private static String oneLine(String text)
	{
		return text == null ? "" : text.replaceAll("\\s+", " ").trim();
	}

	private static Set<String> difference(Set<String> a, Set<String> b)
	{
		Set<String> d = new TreeSet<>(a);
		d.removeAll(b);
		return d;
	}
}

package com.cluehelper.step;

import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Hand-written click targets and walk row objects against the cache's names and options. Copied ids went wrong
 * silently three times (an ivy that was a corpse, a ladder top that was its bottom). Needs the local cache dump, which
 * isn't committed: without it the test is skipped.
 */
public class StepDataCacheTest
{
	private static final Path DUMP = Path.of("tools/cache/dump/2026-10-18");
	private static final Path SKILL_STEPS = Path.of("src/main/resources/com/cluehelper/step/steps/skill.json");
	private static final Path ROW_OBJECTS = Path.of("src/main/resources/com/cluehelper/route/walk/row-objects.tsv");
	private static final String SHERLOCK = "skill:SHERLOCK:";
	/** An item used on the object ("Use Rope -> Rock") is no option of the object's own. */
	private static final String USE_ITEM_ON = "Use";

	private static Map<Integer, JsonObject> objects;
	private static Map<Integer, JsonObject> npcs;

	@BeforeClass
	public static void loadDump() throws IOException
	{
		assumeTrue("no cache dump at " + DUMP.toAbsolutePath(), Files.isDirectory(DUMP));
		objects = byId(DUMP.resolve("objects.json"));
		npcs = byId(DUMP.resolve("npcs.json"));
	}

	@Test
	public void sherlockPlacesNameTheirClickTargetsAsTheCacheDoes() throws IOException
	{
		List<String> failures = new ArrayList<>();
		JsonObject steps = read(SKILL_STEPS).getAsJsonObject().getAsJsonObject("steps");
		for (Map.Entry<String, JsonElement> step : steps.entrySet())
		{
			if (!step.getKey().startsWith(SHERLOCK))
			{
				continue;
			}
			JsonObject data = step.getValue().getAsJsonObject();
			if (!data.has("places"))
			{
				failures.add(step.getKey() + ": no places, and not marked anywhere (places [])");
				continue;
			}
			for (JsonElement place : data.getAsJsonArray("places"))
			{
				checkPlace(step.getKey(), place.getAsJsonObject(), failures);
			}
		}
		assertTrue(String.join("\n", failures), failures.isEmpty());
	}

	@Test
	public void walkRowObjectsAreTheCachesObjects() throws IOException
	{
		List<String> failures = new ArrayList<>();
		List<String> lines = Files.readAllLines(ROW_OBJECTS, StandardCharsets.UTF_8);
		for (String line : lines.subList(1, lines.size()))
		{
			String[] cells = line.split("\t");
			String option = cells[2];
			String name = cells[3];
			int id = Integer.parseInt(cells[4]);
			boolean found = family(objects, id, "configChangeDest").stream().anyMatch(o -> named(o, name, option))
				|| family(npcs, id, "configs").stream().anyMatch(n -> named(n, name, option))
				|| USE_ITEM_ON.equals(option) && family(objects, id, "configChangeDest").stream().anyMatch(o -> name.equals(name(o)));
			if (!found)
			{
				failures.add(cells[0] + ": " + option + " " + name + " " + id);
			}
		}
		assertTrue(failures.size() + " row objects:\n" + String.join("\n", failures), failures.isEmpty());
	}

	private static void checkPlace(String key, JsonObject place, List<String> failures)
	{
		JsonArray objectIds = place.has("objects") ? place.getAsJsonArray("objects") : new JsonArray();
		JsonArray npcIds = place.has("npcs") ? place.getAsJsonArray("npcs") : new JsonArray();
		if (objectIds.size() + npcIds.size() == 0)
		{
			return;
		}
		String at = key + " at " + place.get("tile");
		if (!place.has("click"))
		{
			failures.add(at + ": click targets without click [option, name]");
			return;
		}
		JsonArray click = place.getAsJsonArray("click");
		String option = click.size() < 2 ? null : click.get(0).getAsString();
		String name = click.get(click.size() - 1).getAsString();
		objectIds.forEach(id -> checkId(at, "object", family(objects, id.getAsInt(), "configChangeDest"), id, option, name, failures));
		npcIds.forEach(id -> checkId(at, "npc", family(npcs, id.getAsInt(), "configs"), id, option, name, failures));
	}

	private static void checkId(String at, String kind, List<JsonObject> family, JsonElement id, String option, String name,
		List<String> failures)
	{
		if (family.stream().noneMatch(entry -> named(entry, name, option)))
		{
			failures.add(at + ": " + kind + " " + id + " is " + family.stream().map(StepDataCacheTest::name).collect(Collectors.toList())
				+ ", not " + name + " with " + option);
		}
	}

	private static boolean named(JsonObject entry, String name, String option)
	{
		return name.equals(name(entry)) && (option == null || ops(entry).contains(option));
	}

	private static String name(JsonObject entry)
	{
		return entry.get("name").isJsonNull() ? null : entry.get("name").getAsString();
	}

	private static List<String> ops(JsonObject entry)
	{
		List<String> ops = new ArrayList<>();
		if (entry.has("ops") && entry.get("ops").isJsonArray())
		{
			for (JsonElement op : entry.getAsJsonArray("ops"))
			{
				if (op.isJsonObject() && op.getAsJsonObject().has("text") && !op.getAsJsonObject().get("text").isJsonNull())
				{
					ops.add(op.getAsJsonObject().get("text").getAsString());
				}
			}
		}
		return ops;
	}

	/** The entry and its multiloc children: which one shows depends on a var. */
	private static List<JsonObject> family(Map<Integer, JsonObject> table, int id, String children)
	{
		List<JsonObject> family = new ArrayList<>();
		JsonObject parent = table.get(id);
		if (parent == null)
		{
			return family;
		}
		family.add(parent);
		if (parent.has(children) && parent.get(children).isJsonArray())
		{
			for (JsonElement child : parent.getAsJsonArray(children))
			{
				if (!child.isJsonNull() && table.containsKey(child.getAsInt()))
				{
					family.add(table.get(child.getAsInt()));
				}
			}
		}
		return family;
	}

	private static Map<Integer, JsonObject> byId(Path file) throws IOException
	{
		Map<Integer, JsonObject> byId = new HashMap<>();
		for (JsonElement entry : read(file).getAsJsonArray())
		{
			byId.put(entry.getAsJsonObject().get("id").getAsInt(), entry.getAsJsonObject());
		}
		return byId;
	}

	private static JsonElement read(Path file) throws IOException
	{
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			return new JsonParser().parse(reader);
		}
	}
}

package com.cluehelper.transport;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CatalogSchemaTest
{
	private static final Map<String, Class<?>> GAMEVAL = Map.of("item", ItemID.class, "object", ObjectID.class,
		"varbit", VarbitID.class, "varp", VarPlayerID.class, "npc", NpcID.class);
	private static final Pattern NAMED_ID = Pattern.compile("(\\w+):(\\d+)=(\\w+)");
	private static final Pattern ITEM_ID = Pattern.compile("(?<![A-Z_])(\\d+)=\\d+");
	private static final Pattern VAR_ID = Pattern.compile("(\\d+)\\s*[=<>&@]");
	private static final Pattern SPELLBOOK_CLAUSE = Pattern.compile("(^|;)\\s*4070\\s*=");
	private static final Pattern WHERE_ID = Pattern.compile("(object|npc):(\\d+)");
	private static final Set<String> BOOKS = Set.of("Standard", "Ancient", "Lunar", "Arceuus");
	private static final int MAX_COORD = (1 << 14) - 1;
	private static final int MIN_TELEPORT_ROWS = 700;

	@Test
	public void everyRowPassesTheSchema()
	{
		List<String> failures = new ArrayList<>();
		for (String file : CatalogLoader.TELEPORT_FILES)
		{
			for (TsvTable.Line line : CatalogLoader.read(file))
			{
				teleportRules(line, failures::add, file + ":" + line.getNumber() + " " + line.get(CatalogLoader.NAME) + ": ");
			}
		}
		for (TsvTable.Line line : CatalogLoader.read(CatalogLoader.SPELLBOOK_FILE))
		{
			sharedRules(line, failures::add, CatalogLoader.SPELLBOOK_FILE + ":" + line.getNumber() + " " + line.get(CatalogLoader.NAME) + ": ");
		}

		Catalog catalog = CatalogLoader.load();
		catalog.getTeleports().forEach(row -> row.getRequirements().getErrors().forEach(e -> failures.add(row.getName() + ": " + e)));
		catalog.getSpellbookChanges().forEach(row -> row.getRequirements().getErrors().forEach(e -> failures.add(row.getName() + ": " + e)));

		assertEquals("", String.join("\n", failures));
		assertTrue(catalog.getTeleports().size() > MIN_TELEPORT_ROWS);
	}

	private static void teleportRules(TsvTable.Line line, Failures fail, String at)
	{
		sharedRules(line, fail, at);
		Category category = Category.of(line.get(CatalogLoader.CATEGORY));
		if (SPELLBOOK_CLAUSE.matcher(line.get(RequirementParser.VARBITS)).find())
		{
			fail.add(at + "4070 left in Varbits");
		}
		if (line.get(RequirementParser.CONSUMABLE).equals("T") && line.get(CatalogLoader.SPENDS).equals("none"))
		{
			fail.add(at + "consumable without Spends");
		}
		if (category != Category.FAIRY_RING && line.get(RequirementParser.WILDERNESS).isEmpty())
		{
			fail.add(at + "teleport without a Wilderness level");
		}
		boolean bookRow = category == Category.SPELL || category == Category.HOME;
		String book = line.get(RequirementParser.BOOK);
		if (bookRow ? !BOOKS.contains(book) : !book.equals("any"))
		{
			fail.add(at + "Book '" + book + "' for a " + category + " row");
		}
		validTile(line.get(CatalogLoader.ORIGIN), fail, at);
		validTile(line.get(CatalogLoader.DESTINATION), fail, at);
		if (line.get(CatalogLoader.ORIGIN).isEmpty() && line.get(CatalogLoader.DESTINATION).isEmpty())
		{
			fail.add(at + "neither origin nor destination");
		}
	}

	private static void sharedRules(TsvTable.Line line, Failures fail, String at)
	{
		Map<String, Integer> named = new HashMap<>();
		Matcher m = NAMED_ID.matcher(line.get("Gameval"));
		while (m.find())
		{
			int id = Integer.parseInt(m.group(2));
			named.put(m.group(1) + ":" + id, id);
			Integer actual = gameval(m.group(1), m.group(3));
			if (actual == null || actual != id)
			{
				fail.add(at + m.group(0) + " but the gameval constant is " + actual);
			}
		}
		for (String ref : referencedIds(line))
		{
			if (!named.containsKey(ref))
			{
				fail.add(at + ref + " has no gameval name beside it");
			}
			if (ref.startsWith("item:") && CatalogRules.UNCHARGED.contains(Integer.parseInt(ref.substring(5))))
			{
				fail.add(at + "uncharged " + ref);
			}
		}
		String members = line.get(RequirementParser.MEMBERS);
		if (!members.equals("Y") && !members.equals("N"))
		{
			fail.add(at + "Members '" + members + "'");
		}
		if (line.get(CatalogLoader.SPENDS).isEmpty() || line.get(CatalogLoader.DURATION).isEmpty()
			|| line.get(CatalogLoader.MENU_TICKS).isEmpty())
		{
			fail.add(at + "Spends, Duration or Menu ticks empty");
		}
	}

	private static List<String> referencedIds(TsvTable.Line line)
	{
		List<String> refs = new ArrayList<>();
		collect(ITEM_ID, line.get(RequirementParser.ITEMS), "item:", refs);
		collect(VAR_ID, line.get(RequirementParser.VARBITS), "varbit:", refs);
		collect(VAR_ID, line.get(RequirementParser.VARPS), "varp:", refs);
		String menu = line.get("menuOption menuTarget objectID");
		if (!menu.isEmpty())
		{
			String kind = line.get(CatalogLoader.MENU).startsWith("npc ") ? "npc:" : "object:";
			refs.add(kind + menu.substring(menu.lastIndexOf(' ') + 1));
		}
		String house = line.get(RequirementParser.HOUSE);
		if (house.startsWith("object:"))
		{
			for (String id : house.substring("object:".length()).split("\\|"))
			{
				refs.add("object:" + id);
			}
		}
		Matcher where = WHERE_ID.matcher(line.get(CatalogLoader.WHERE));
		while (where.find())
		{
			refs.add(where.group(1) + ":" + where.group(2));
		}
		return refs;
	}

	private static void collect(Pattern pattern, String cell, String prefix, List<String> refs)
	{
		Matcher m = pattern.matcher(cell);
		while (m.find())
		{
			refs.add(prefix + m.group(1));
		}
	}

	private static Integer gameval(String kind, String name)
	{
		Class<?> constants = GAMEVAL.get(kind);
		try
		{
			Field field = constants.getField(name);
			field.setAccessible(true);
			return field.getInt(null);
		}
		catch (ReflectiveOperationException | NullPointerException e)
		{
			return null;
		}
	}

	private static void validTile(String cell, Failures fail, String at)
	{
		if (cell.isEmpty())
		{
			return;
		}
		try
		{
			WorldPoint tile = CatalogLoader.tile(cell);
			boolean valid = tile.getX() > 0 && tile.getX() <= MAX_COORD && tile.getY() > 0 && tile.getY() <= MAX_COORD
				&& tile.getPlane() >= 0 && tile.getPlane() <= 3;
			if (!valid)
			{
				fail.add(at + "tile out of range: " + cell);
			}
		}
		catch (RuntimeException e)
		{
			fail.add(at + e.getMessage());
		}
	}

	private interface Failures
	{
		void add(String failure);
	}
}

package com.cluehelper.transport;

import static org.junit.Assert.assertEquals;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Test;

public class RequirementParserTest
{
	private static final String[][] CASES = {
		{"Items", "AIR_RUNE=3&&FIRE_RUNE=1&&LAW_RUNE=1", "items 556x3 & 554x1 & 563x1"},
		{"Items", "1706=1||1708=1||1710=1", "items 1706x1|1708x1|1710x1"},
		{"Items", "13393=1&UNLOCK_XERICS_HONOUR=1", "items 13393x1 & unlock XERICS_HONOUR"},
		{"Items", "aether_rune=2 & sunfire_rune=1", "items 30843x2 & 28929x1"},
		{"Items", "SPADE=1", "error Items: unknown item 'SPADE'"},
		{"Items", "AIR_RUNE", "error Items: can't read 'AIR_RUNE'"},
		{"Items", "AIR_RUNE=0", "error Items: 'AIR_RUNE=0' needs a positive quantity"},
		{"Skills", "25 Magic;50 Agility", "levels 25 Magic; 50 Agility"},
		{"Skills", "Max Total", "levels 2376 total level"},
		{"Skills", "Max Construction;100 Combat;32 Quest", "levels 99 Construction; combat level 100; 32 quest points"},
		{"Skills", "70 Agilty", "error Skills: can't read '70 Agilty'"},
		{"Skills", "high Magic", "error Skills: can't read 'high Magic'"},
		{"Quests", "Lunar Diplomacy;Fairytale II - Cure a Queen", "quests Fairytale II - Cure a Queen; Lunar Diplomacy"},
		{"Quests", "Dragon Slayer", "error Quests: unknown quest 'Dragon Slayer'"},
		{"Varbits", "4070=2", "book LUNAR"},
		{"Varbits", "4070=0;4480=1", "book STANDARD; vars varbit 4480 = 1"},
		{"Varbits", "4070>1", "vars varbit 4070 > 1"},
		{"Varbits", "4560&1;3264=11", "vars varbit 4560 & 1; varbit 3264 = 11"},
		{"Varbits", "6104<-1", "vars varbit 6104 < -1"},
		{"Varbits", "1234~5", "error Varbits: can't read '1234~5'"},
		{"VarPlayers", "4560=0;892@30", "vars varp 4560 = 0; varp 892 @ 30"},
		{"Wilderness level", "20", "wild 20"},
		{"Wilderness level", "-1", ""},
		{"Wilderness level", "deep", "error Wilderness level: can't read 'deep'"},
		{"Book", "Arceuus", "book ARCEUUS"},
		{"Members", "T", "members"},
		{"Consumable", "T", "spends charges"},
	};

	private final RequirementParser parser = new RequirementParser();

	@Test
	public void parsesEveryCaseOfTheShortestPathSyntax()
	{
		List<String> failures = new ArrayList<>();
		for (String[] c : CASES)
		{
			String column = c[0];
			String cell = c[1];
			String expected = c[2];
			String actual = describe(parser.parse(Map.of(column, cell)));
			if (!actual.equals(expected))
			{
				failures.add(column + " '" + cell + "': expected '" + expected + "', got '" + actual + "'");
			}
		}
		assertEquals("", String.join("\n", failures));
	}

	@Test
	public void aBookColumnThatDisagreesWithVarbit4070IsAnError()
	{
		Requirements r = parser.parse(Map.of("Book", "Lunar", "Varbits", "4070=0"));
		assertEquals(List.of("Book LUNAR disagrees with varbit 4070 = 0"), r.getErrors());
	}

	@Test
	public void varChecksPassAtTheirBoundaries()
	{
		VarCheck cooldown = new VarCheck(VarCheck.Kind.VARP, 892, VarCheck.Op.COOLDOWN_MINUTES, 30);
		assertEquals(false, cooldown.test(1000, 1030));
		assertEquals(true, cooldown.test(1000, 1031));
		assertEquals(1031, cooldown.passesFrom(1000));
		assertEquals(Long.MAX_VALUE, new VarCheck(VarCheck.Kind.VARBIT, 1, VarCheck.Op.EQUAL, 1).passesFrom(0));

		assertEquals(true, new VarCheck(VarCheck.Kind.VARBIT, 1, VarCheck.Op.GREATER, 39).test(40, 0));
		assertEquals(false, new VarCheck(VarCheck.Kind.VARBIT, 1, VarCheck.Op.GREATER, 39).test(39, 0));
		assertEquals(true, new VarCheck(VarCheck.Kind.VARBIT, 1, VarCheck.Op.SMALLER, 5).test(4, 0));
		assertEquals(false, new VarCheck(VarCheck.Kind.VARBIT, 1, VarCheck.Op.SMALLER, 5).test(5, 0));
		assertEquals(true, new VarCheck(VarCheck.Kind.VARP, 4182, VarCheck.Op.BIT_SET, 4).test(6, 0));
		assertEquals(false, new VarCheck(VarCheck.Kind.VARP, 4182, VarCheck.Op.BIT_SET, 4).test(3, 0));
	}

	private static String describe(Requirements r)
	{
		List<String> parts = new ArrayList<>();
		if (!r.getItems().isEmpty())
		{
			parts.add("items " + r.getItems().stream().map(RequirementParserTest::clause).collect(Collectors.joining(" & ")));
		}
		if (!r.getLevels().isEmpty())
		{
			parts.add("levels " + r.getLevels().stream().map(LevelNeed::describe).collect(Collectors.joining("; ")));
		}
		if (!r.getQuests().isEmpty())
		{
			parts.add("quests " + r.getQuests().stream().map(q -> q.getName()).sorted().collect(Collectors.joining("; ")));
		}
		if (r.getBook() != null)
		{
			parts.add("book " + r.getBook());
		}
		if (!r.getVars().isEmpty())
		{
			parts.add("vars " + r.getVars().stream().map(VarCheck::describe).collect(Collectors.joining("; ")));
		}
		if (r.getMaxWildernessLevel() != Requirements.NO_WILDERNESS_LIMIT)
		{
			parts.add("wild " + r.getMaxWildernessLevel());
		}
		if (r.isMembers())
		{
			parts.add("members");
		}
		if (r.isSpendsCharges())
		{
			parts.add("spends charges");
		}
		r.getErrors().forEach(error -> parts.add("error " + error));
		return String.join("; ", parts);
	}

	private static String clause(ItemClause clause)
	{
		return clause.getBranches().stream()
			.map(b -> b.isUnlock() ? "unlock " + b.getUnlock() : b.getIds().stream().map(String::valueOf)
				.collect(Collectors.joining("/")) + "x" + b.getQuantity())
			.collect(Collectors.joining("|"));
	}
}
